COLLDATA("adabbayhaqi","ur",[[1,"سیدنا عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’میں نے رسول اللہ صلی اللہ علیہ وسلم سے سوال کیاکہ اللہ تعالی کے ہاں سب سے زیادہ پسندیدہ عمل کونسا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: نماز کو بروقت ادا کرنا۔ میں نے پوچھا:پھر کونسا؟ آپ صلی اللہ علیہ وسلم نے فرمایا:والدین کے ساتھ حسنِ سلوک۔ میں نے کہا:پھر کونسا؟ آپ صلی اللہ علیہ وسلم نے فرمایا:اللہ کی راہ میں جہاد کرنا۔ راوی کہتے ہیں کہ آپ صلی اللہ علیہ وسلم نے مجھے یہی باتیں بتلائیں، البتہ اگر میں مزید پوچھتا تو آپ صلی اللہ علیہ وسلم اور بھی بتلاتے۔‘‘","صحیح",{"k":"صحیح بخاری (527)، صحیح مسلم (85)۔","f":"آداب واخلاقيات میں سب سے اوّليں امر يہی ہے، اسى ليے اسلام نے اس كے اہتمام پر بہت زور ديا ہے۔ قرآن وسنت میں بہ كثرت ايسى نصوص وارد ہوئى ہیں کہ جن سے اس معاملے كى اہمیت واضح ہوتی ہے۔ والدين كے ساتھ اچھا برتاؤ اور حسنِ مصاحبت ہربا شعور مسلمان كاامتيازى وصف ہے۔ قرآنِ كريم میں متعدد مقامات پر اللہ تعالىٰ نے اپنى بندگى كے حكم كے متصل بعد والدين كے ساتھ نيك سلوك كرنے كاحكم فرمايا ہے، گويا اللہ تعالىٰ نے اپنى عبادت كے بعدجس امر كوديگر تمام امور سے اہم سمجھا وہ یہی ہے، جيساكہ فرمانِ بارى تعالىٰ ہے: ﴿وَقَضٰى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا إِمَّا يَبْلُغَنَّ عِنْدَكَ الْكِبَرَ أَحَدُهُمَا أَوْ كِلَاهُمَا فَلَا تَقُلْ لَهُمَا أُفٍّ وَلَا تَنْهَرْهُمَا وَقُلْ لَهُمَا قَوْلًا كَرِيمًا﴾ [الاسراء: ۲۳] ’’اور تمہارا پروردگار صاف صاف حکم دے چکا ہے کہ تم اس کے سوا کسی اور کی عبادت نہ کرنا اور ماں باپ کے ساتھ احسان کرنا۔ اگر تیری موجودگی میں ان میں سے ایک یاد ونوں بڑھاپے کو پہنچ جائیں تو ان کے آگے ’’اُف‘‘ تک نہ کہنا اور نہ ہی انہیں ڈانٹ ڈپٹ کرنا، بلکہ ان کے ساتھ ادب واحترام سے بات چیت کرنا۔‘‘\nمذکورہ حدیثِ مبارکہ میں نبی صلی اللہ علیہ وسلم نے بھی پہلا افضل عمل باری تعالیٰ کی بندگی یعنی نمازذِکر فرمایا اور اس کے بعد ديگر تمام اعمال پر فضیلت کا حامل جو عمل بتلایا وہ والدین کے ساتھ حسنِ سلوک ہے۔ گویا قرآن وسنّت کے طرزِبیان سے ہی اس عمل کی فضیلت واہمیت اور اس کی بجاآوری کے تقاضے کی شدّت کا احساس ہوتاہے۔"}],[2,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ ایک آدمی نے عرض کیا:\n’’اے اللہ کے رسول صلی اللہ علیہ وسلم !میرے اچھے سلوک کاسب سے زیادہ حقدار کون ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:تمہاری ماں۔ اس نے عرض کیا:پھر کون حق رکھتا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:پھر تمہاری ماں۔ اس نے کہا:پھرکس کاحق ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:پھر تمہارے باپ كا۔‘‘","صحیح",{"k":"صحیح بخاری (5971)، صحیح مسلم (2548)۔"}],[3,"ایک روایت میں یوں ہے کہ اس صحابی نے کہا:\n’’اے اللہ کے نبیؐ!میں کس کے ساتھ نیک سلوک کروں؟ آپ صلی اللہ علیہ وسلم نے فرمایا:اپنی ماں کے ساتھ۔ اس نے کہا: پھرکس سے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:پھر اپنی ماں سے۔ اس نے پوچھا:پھرکس سے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:پھر بھی اپنی ماں سے۔ اس نے پھر عرض کیاکہ پھرکس سے نیک سلوک کروں؟ آپ صلی اللہ علیہ وسلم نے فرمایا:پھر اپنے باپ سے۔‘‘","صحیح",{"k":"صحیح مسلم (2548)، سنن ابن ماجه (3658)۔","f":"یعنی ماں حسنِ سلوک کا تین چوتھائی حق رکھتی ہے اور باپ ایک چوتھائی، اس کی وجہ واضح ہے کہ ماں کو بچے کی پیدائش کے اوّل تاآخر کئی تکلیف دہ مراحل سے گزرنا پڑتا ہے اور پھر اس کی پرورش ونگہداشت کی ذِمہ داری بھی ماں ہی کے سرہوتی ہے، علاوہ ازیں اس کی ابتدائی تعلیم وتر بیت میں بھی باپ کی بہ نسبت ماں کا زیادہ کر دار ہوتا ہے، ان تمام امور کی بنا پر ماں کو باپ پر فضیلت وفوقیت دی گئی ہے۔"}],[4,"عبداللہ بن دینار عبداللہ بن عمر رضی اللہ عنہما کے بارے میں روایت کرتے ہیں کہ:\n’’ایک بدوی شخص انہیں مکہ کے کسی راستے میں ملا، تو عبداللہؓ نے اسے سلام کہا اور اسے اس سواری پر بٹھا لیاجس پہ خود سواری کیا کرتے تھے اور اپنے سرسے پگڑی اتار کر اسے دے دی۔ ابنِ دینار کہتے ہیں کہ ہم نے کہا:اللہ تعالیٰ آپ میں نیکی کا(مزید)جذبہ پیدا فرمائے، یہ بدوی لوگ تو تھوڑے بہت پر ہی خوش ہوجاتے ہیں(آپ نے اتنا کیوں کیا؟)، تو عبداللہ رضی اللہ عنہ نے فرمایا:اس شخص کا والد(میرے والد)عمربن خطاب رضی اللہ عنہ کا دوست تھا، اور میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے کہ سب سے بڑا نیک سلوک یہ ہے کہ آدمی اپنے باپ کے دوستوں سے میل جول رکھے۔‘‘","صحیح",{"k":"صحیح مسلم (2552)، سنن أبوداؤد (5143)، سنن ترمذی (1903)۔","f":"یعنی صرف باپ پر ہی حسنِ سلوک کا سلسلہ ختم نہیں کر دینا چاہیے بلکہ باپ کی وفات کے بعد ان کے دوستوں سے میل جول اور اچھا برتاؤ رکھنا بھی باعثِ اجروثواب ہے۔"}],[5,"ابوایوب انصاری رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’کسی سفر میں ایک بدوی نبی صلی اللہ علیہ وسلم کے پاس آیا اور اس نے (آپ صلی اللہ علیہ وسلم کی)اونٹنی کی لگام یالگام کا کڑا پکڑ لیا اور کہا:اے اللہ کے رسول!، یا(کہا)اے محمد!مجھے کوئی ایسا عمل بتلائیے جو مجھے جنّت کے قریب کردے اور جہنّم سے دُورکر دے۔ تو آپ صلی اللہ علیہ وسلم نے فرمایا:اللہ تعالیٰ کی عبادت کیا کر اور اس کے ساتھ کسی کو شریک مت ٹھہرا، نماز قائم کر، زکاۃ دے اور صلہ رحمی کر۔‘‘","صحیح",{"k":"صحیح بخاری (1396)، صحیح مسلم (13)۔","f":"رَحِمْ سے مراد قرابت داری ہے اور صلہ رحمی کا مطلب ہے کہ رشتے داروں سے میل جول اور تعلق وناتہ جوڑے رکھنا۔ صلہ رحمی کرنے والے کے بارے میں اللہ تعالیٰ فرماتا ہے: ﴿وَالَّذِينَ يَصِلُونَ مَا أَمَرَ اللهُ بِهِ أَن يُوصَلَ وَيَخْشَوْنَ رَبَّهُمْ وَيَخَافُونَ سُوءَ الحِسَابِ﴾ [الرعد: ۲] ’’اور(جنّتی)لوگ وہ ہیں جوان رشتوں کو ملاتے ہیں جنہیں ملانے کا انہیں حکم دیا گیا ہے اور وہ برے حساب سے ڈرتے ہیں۔‘‘\nاور قطع رحمی کرنے والے کے بارے میں فرمایا: ﴿فَهَلْ عَسَيْتُمْ إِن تَوَلَّيْتُمْ أَن تُفْسِدُوا فِي الْأَرْضِ وَتُقَطِّعُوا أَرْحَامَكُمْ أُوْلَئِكَ الَّذِينَ لَعَنَهُمُ اللّٰهُ فَأَصَمَّهُمْ وَأَعْمٰى أَبْصَارَهُمْ﴾ [محمد: ۲۲،۲۳] ’’اور تم سے یہ بھی بعید نہیں ہے کہ اگر تم کو حکومت مل جائے تو تم زمین میں فساد برپا کر ڈالو اور رشتے ناتے توڑ ڈالو۔یہ وہی لوگ ہیں جن پر اللہ کی پھٹکار ہے اورجن کی سماعت اور آنکھوں کی روشنی چھین لی گئی ہے۔‘‘\nيعنى اللہ تعالىٰ نے اس آيت میں فسادفى الارض كے ساتھ قطع رحمى كوبھي موجبِ لعنت قرار ديا ہے۔\nمذکورہ حدیث میں رسولِ مکرم صلی اللہ علیہ وسلم نے صلہ رحمی یعنی عزیز واقارب کے ساتھ میل جول رکھنے، تعلق وناتہ جوڑنے اور اچھا سلوک کرنے کے عمل کوجنّت کے قریب اور جہنّم سے دُورکر دینے والا عمل بتلایا ہے۔"}],[6,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب اللہ تعالیٰ مخلوق کو پیدا کرنے سے فارغ ہوا تو رشتے داری نے کہا:قطع رحمی سے پناہ مانگنے والے کا یہ مقام ہے؟ تو اللہ تعالیٰ نے فرمایا:ہاں، کیا تو اس بات سے راضی نہیں ہے کہ میں اسے ملاؤں جو تجھے ملائے اور میں اس سے تعلق توڑوں جو تجھ سے تعلق توڑے؟ رشتے داری نے کہا:اے پروردگار!کیوں نہیں، تو اللہ تعالیٰ نے فرمایا:تیرے لیے یہی ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:اللہ تعالیٰ کا یہ فرمان پڑھ لو: ﴿فَهَلْ عَسَيْتُمْ إِنْ تَوَلَّيْتُمْ أَنْ تُفْسِدُوا فِي الْأَرْضِ وَتُقَطِّعُوا أَرْحَامَكُمْ، أُولٰئِكَ الَّذِينَ لَعَنَهُمُ اللّٰهُ فَأَصَمَّهُمْ وَأَعْمٰى أَبْصَارَهُمْ﴾ [محمد: ۲۲،۲۳] ’’اور تم سے یہ بھی بعید نہیں ہے کہ اگر تم کو حکومت مل جائے تو تم زمین میں فساد برپا کر ڈالو اور رشتے ناتے توڑ ڈالو۔یہ وہی لوگ ہیں جن پر اللہ کی پھٹکار ہے اورجن کی سماعت اور آنکھوں کی روشنی چھین لی گئی ہے۔‘‘","صحیح",{"k":"صحیح بخاری (5987)، صحیح مسلم (2554)۔"}],[7,"جبیربن مطعم رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ نے فرمایا:\n’’قطع رحمی کرنے والا جنت میں نہیں جائے گا۔‘‘","صحیح",{"k":"صحیح بخاری (5984)، صحیح مسلم (2556)۔","f":"مذکورہ دونوں حدیثوں سے یہ بات احاطۂ علم میں آتی ہے کہ جس طرح صلہ رحمی موجبِ اجروثواب ہے اسی طرح قطع رحمی باعثِ غضب وعذاب ہے۔ غضب اس طرح کہ جو شخص رشتے داری کو توڑتا ہے وہ اللہ کا غضب مول لیتا ہے کیونکہ اللہ تعالیٰ اس سے تعلق توڑ لیتا ہے اور باعثِ عذاب یوں کہ ایسا شخص جنّت میں داخل نہیں ہوگا۔"}],[8,"عبداللہ بن عمرو رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’صِلہ رحمی کرنے والا وہ نہیں ہوتا جو بدلے میں صِلہ رحمی کرے، بلکہ صِلہ رحمی کرنے والا وہ ہے کہ جس سے رشتہ داری توڑی جائے اور وہ (پھر بھى)اسے ملائے۔‘‘","صحیح",{"k":"صحیح بخاری (5991)، سنن أبوداؤد (1697)، سنن ترمذی (1908)، مسند أحمد (2؍163)۔","f":"اس حدیث میں صلہ رحمی کا مفہوم بتلایا گیا ہے کہ صلہ رحمی کا یہ مطلب نہیں ہے کہ دوسرا رشتے دار میل جول رکھے تو تبھی اس سے رشتہ داری رکھی جائے بلکہ اس کا مطلب یہ ہے کہ وہ آپ سے میل جول رکھے یانہ رکھے، اچھا سلوک کرے یانہ کرے آپ کو کسی صورت اس سے رشتہ ناتہ نہیں توڑنا چاہیے، بلکہ صلہ رحمی کہتے ہی اسی کو ہیں کہ دوسرا ناتے کو توڑے اور آپ اس سے جوڑیں، کیونکہ بدلے میں صلہ رحمی کرنا تو بدلے کی نیکی ہوئى، لیکن اس عظیم عمل کا اظہار اسی صورت میں ہے کہ فریقِ ثانی خواہ کیسا بھی سلوک کرے مگر آپ اس سے صلہ رحمی کا ہی معاملہ کریں۔"}],[9,"اُمِ کلثوم بنت عقبہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’سب سے زیادہ فضیلت کا حامل صدقہ وہ ہے جو بہت زیادہ دشمنی رکھنے والے رشتہ دار پر کیا جائے۔‘‘","صحیح",{"k":"مستدرک حاکم (1؍406)، المعجم الکبیر للطبرانی (18؍258)، صحیح الإرواء (892)۔","f":"گویا کوئی عزیزو رشتے دار اگر دشمنی کی طرح کا سلوک کرتا ہو تو اس پر صدقہ کر ناسب سے زیادہ فضیلت کا حامل ہے، اور یہ صدقہ صرف مالی مراد نہیں ہے بلکہ کسی بھی طرح سے اس کے کام آنا، اس کی مدد کر نایا اس کادُکھ بانٹناسب امورِصدقہ میں شامل ہیں کیونکہ نبی مکرم صلی اللہ علیہ وسلم کا یہ ارشادِگرامی ہے کہ ہرنيك کام صدقہ ہے۔"}],[10,"ابوبکرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’سرکشی اور قطع رحمی سے بڑھ کر کوئی بھی گناہ ایسا نہیں ہے کہ جس کا عذاب آخرت میں برقرار رکھنے کے ساتھ ساتھ اللہ تعالیٰ اس گناہ کے مرتکب کو دنیا میں بھی سزا سے دو چار کرے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4902)، سنن ترمذی (2511)، سنن ابن ماجه (4211)، مسند أحمد (5؍36)، سلسلہ الأحادیث الصحیحہ (918)۔","f":"گویا رشتے ناتے توڑنا ایسا قبیح گناہ ہے کہ اللہ تعالیٰ اس کی سزا ہردو جہاں میں دیتا ہے، دنیا میں بھی اسے سزا سے دو چار کرتا ہے اور آخرت میں بھی جنّت سے محروم رکھے گا۔"}],[11,"عبدالرحمان بن عوف رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’اللہ تعالیٰ فرتا ہے:میں اللہ ہوں اور میں رحمان ہوں، میں نے ہی رحم(یعنی رِشتہ داری)کو پیدا کیا اور اس کا نام اپنے نام کو پھاڑ کر اس سے رکھا ہے، سوجو کوئی اسے ملائے گاا سے میں ملاؤں گااور جو اسے توڑے گامیں اسے توڑوں گا۔ یایہ فرمایاکہ میں اسے کاٹ کے رکھ دوں گا۔‘‘","صحیح",{"k":"سنن أبوداؤد (1694)، سنن ترمذی (1907)، الأدب المفرد للبخاری (53)، سلسلہ الأحادیث الصحیحہ (520)۔"}],[12,"اسماء بنت ابی بکر رضی اللہ عنہما بیان کرتی ہیں کہ:\n’’میری والدہ عہدِرسالت میں بھی مشرکہ ہی تھیں، وہ (ایک مرتبہ)میرے پاس آئیں تو میں نے رسول اللہ صلی اللہ علیہ وسلم سے یہ فتویٰ طلب کیاکہ میرے پاس میری والدہ آئی ہیں اور انہوں نے ابھی اسلام قبول نہیں کیا، تو کیا میں اس سے صلہ رحمی کروں؟ آپ صلی اللہ علیہ وسلم نے فرمایا:ہاں۔ سفیانؒ کہتے ہیں کہ اسی بارے میں یہ آیت نازل ہوئی: ﴿لَا يَنْهَاكُمُ اللّٰهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ﴾ الْآيَةَ ’’جو لوگ تم سے دین کے معاملے میں لڑتے بھِڑتے نہیں ہیں ان سے (اچھا سلوک کرنے سے)اللہ تعالیٰ تمہیں منع نہیں کرتا۔‘‘","صحیح",{"k":"صحیح بخاری (2620)، صحیح مسلم (1003)۔","f":"یعنی والدین اگر مشرک ہوں تب بھی ان کے ساتھ حسنِ سلوک کا معاملہ کرنا چاہیے، بشرطیکہ وہ اللہ کی نافرمانی کا کام کرنے کونہ کہیں، لیکن اگر وہ کوئی ایسا کام کرنے کو کہیں کہ جس سے اللہ کی نافرمانی ہوتی ہو تو ایسی صورت میں ان کی اطاعت لازم نہیں ہے۔"}],[13,"جیسا کہ سعد رضی اللہ عنہ بیان کرتے ہیں کہ:\nاُمِ سعد(یعنی ان کی والدہ)نے (ان سے)کہا:کیا اللہ تعالٰی نے والدین کے ساتھ نیک سلوک کرنے کاحکم نہیں فرمایا؟ اللہ کی قسم!میں تب تک کچھ نہ کھاؤں پیوں گی جب تک تُوکافر نہیں ہو جاتا یامر نہیں جاتا۔ سوجب وہ انہیں کچھ کھلا نایا پلانا چاہتے تو چھڑی کے ساتھ ان کا منہ کھولتے پھر کھانایا پانی ان کے حلق میں اتارتے، تو(اس موقع پر)یہ آیت نازل ہوئی: «وَوَصَّيْنَا الْإِنْسَانَ بِوَالِدَيْهِ حُسْنًا وَإِنْ جَاهَدَاكَ لِتُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا» ’’اور ہم نے انسان کو اپنے والدین کے ساتھ حُسنِ سلوک کی وصیت کی، لیکن اگر وہ تجھے اس بات پر مجبور کریں کہ تُومیرے ساتھ شرک کرے جس کا تجھے علم نہیں ہے، تو ان کی بات مت مان۔‘‘","صحیح",{"k":"صحیح مسلم (1748)، مسند أحمد (3؍176)۔"}],[14,"جیسا کہ ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے حسن بن علی رضی اللہ عنہما کا بوسہ لیا تو اقرع بن حابس پاس بیٹھے ہوئے تھے، انہوں نے کہا:اے اللہ کے رسول صلی اللہ علیہ وسلم !میرے دس بچے ہیں لیکن میں نے تو ان میں سے کسی کا بھی کبھی بوسہ نہیں لیا۔ رسول اللہ صلی اللہ علیہ وسلم نے اس کی طرف نظر اٹھائی اور فرمایا:جو(کسی پر)رحم نہیں کرتا اس پر بھی رحم نہیں کیا جاتا۔‘‘","صحیح",{"k":"صحیح بخاری (5997)، صحیح مسلم (2318)۔","f":"اولاد سے محبت وشفقت اللہ کے رحم وکرم کا موجب عمل ہے اور جو اس سے قاصر ہوتا ہے وہ اللہ کے رحم سے محروم ہوتاہے۔"}],[15,"اور سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ:\n’’ایک دیہاتی نبی صلی اللہ علیہ وسلم کے پاس آیا اور کہنے لگا:کیا آپ صلی اللہ علیہ وسلم بچوں کو چومتے ہیں؟ ہم تو انہیں نہیں چومتے، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:اگر اللہ نے ہی تمہارے دِل سے شفقت چھین لی ہو تو پھر میں تمہارا کیا کر سکتا ہوں۔‘‘","صحیح",{"k":"صحیح بخاری (5998)، صحیح مسلم (2317)۔","f":"گویا اپنے بچوں کو پیار نہ کرنا اللہ کی طرف سے رحمت وشفقت چھِن جانے کی دلیل ہے اور رحمتِ الہٰی کے حقدار ٹھہر نے کے لیے ضروری ہے کہ اپنی اولاد کے ساتھ محبت کا اظہار کیا جائے، ان پر شفقت كي جائے اور ان كے ساتھ نرم رويہ ركھا جائے، تاکہ اولاد والدین کی شفقت سے اور والدین اللہ کی رحمت سے محروم نہ ہو پائیں۔"}],[16,"اسامہ بن زید رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم مجھے پکڑ کر اپنی (بائیں)ران پر اور حسنؓ کو دائیں ران پر بٹھا لیا کرتے تھے، پھر ہمیں (محبت سے)بھِینچ لیتے(یعنی زور سے سِینے سے لگا لیتے)اور فرماتے:اے اللہ!ان دونوں پر رحم فرما!کیونکہ میں بھی ان پر شفقت کرتا ہوں۔‘‘","صحیح",{"k":"صحیح بخاری (6003)، مسند أحمد (5؍205)۔","f":"یہ كمالِ شفقت كے اظہار كاانداز ہے، اس حديث سے يہ بات بھي احاطہ علم ميں آتى کہ اپنی اولاد کے لیے رب تعالیٰ کے حضور دست بہ دعا بھی رہنا چاہیے۔"}],[17,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ:\n’’میرے پاس ایک عورت آئی، اس نے اپنی دو بیٹیوں کو اٹھا رکھا تھا، وہ مجھ سے(کھانے کے لیے کچھ)مانگنے لگی تو میرے پاس سوائے ایک کھجور کے اور کچھ نہ تھا، میں نے وہی کھجور اسے دے دی۔ اس نے وہ کھجور پکڑی اور اس کے دو ٹکڑے کرکے اپنی بیٹیوں کو کھلا دی لیکن خود اس سے ذرہ بھی نہ کھائی، پھر وہ اُٹھی اور اپنی بیٹیوں کو لے کر چلی گئی۔ جب نبی صلی اللہ علیہ وسلم میرے پاس تشریف لائے تو میں نے یہ واقعہ آپ صلی اللہ علیہ وسلم سے بیان کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا:جس شخص کو بیٹیوں کے ساتھ آزمایا گیا اور اس نے اچھے طریقے سے ان کی پرورش کی، تو وہ اس کے لیے (جہنم کی)آگ سے آڑبن جائیں گی۔‘‘","صحیح",{"k":"صحیح بخاری (1418)، صحیح مسلم (2629)۔"}],[18,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ:\n’’ایک مسکین عورت اپنی دو بیٹیوں کو اٹھائے ہوئے آئی، میں نے اسے تین کھجوریں دِیں تو اس نے اپنی دونوں بیٹیوں کو ایک ایک کھجور دے دی اور باقی ایک کھجور کو(خود کھا نے کے لیے)اپنے منہ کی طرف بڑھایا ہی تھا کہ اس کی بیٹیوں نے وہ بھی مانگ لی، تو اس عورت نے وہ کھجور جسے وہ خود کھانا چاہتی تھی دو ٹکڑے کرکے ان دونوں کو دے دی۔ مجھے اس کی یہ بات بہت پیاری لگی، میں نے رسول اللہ صلی اللہ علیہ وسلم کے پاس یہ بیان کی تو آپ صلی اللہ علیہ وسلم نے فرمایا:یقیناًاللہ تعالیٰ نے اس کے بدلے میں اس عورت کے لیے جنّت کو واجب کر دیا اور اسے جہنّم سے آزاد کر دیا۔‘‘","صحیح",{"k":"صحیح مسلم (2630)، مسند أحمد (5؍252)۔","f":"ماں کا معاملہ ہی اللہ تعالیٰ نے سب سے جُدار کھا ہے، یہ ایسی ہستی ہے کہ جو اپنی اولاد کی خوشی کے لیے اپنی ادنیٰ سی خوشی سے لے کر اپنی زندگی بھر کے آرام وسکون کو قربان كردینے میں دو رائے نہیں رکھتی، انسان ماں کی محبت کو لفظوں میں قید کرنے سے قاصر ہے، محبتِ حقیقی کا یہ واحد ایسا جذبہ ہے کہ جس کا اندازہ اس ہستی کے سوا کوئی بشر نہیں لگا سکتا۔"}],[19,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’اونٹ پر سواری کرنے والی عورتوں میں سے بہترین عورت قریش کی نیک عورت ہوتی ہے، جو اپنے بچے کے بچپن میں اس سے بہت زیادہ شفقت کرتی ہے اور اپنے خاوند کے مال واسباب میں اس کی نگہبان ہوتی ہے۔‘‘","صحیح",{"k":"صحیح بخاری (5082)، صحیح مسلم (2527)۔","f":"حدیث میں مذکور أَحْنَا کا لفظ حَنْيٌسے ہے، اورحَنْيٌ کا مطلب ہے انتہا درجے کی شفقت ومہربانی کرنا، جب اس لفظ کا استعمال عورت کے ساتھ ہوتاہے تو پھر مطلب ہوتاہے کہ ایک بیوہ عورت کا اپنے بچوں پر اس درجے تک شفیق ومہربان ہونا کہ ان کی وجہ سے وہ دوسری شادی نہ کرے تاکہ پوری توجہ سے ان کی دیکھ بھال کر سکے۔ اس حديث میں ایسى عورت كونبى صلی اللہ علیہ وسلم نے بہترين عورت قرار ديا ہے۔"}],[20,"سہل بن سعد الساعدی رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’میں اور یتیم کی کفالت کرنے والاجنّت میں ان دو(انگلیوں)کی طرح(ایک ساتھ اکٹھے) ہوں گے۔ راوی کہتے ہیں کہ آپ صلی اللہ علیہ وسلم نے اپنی انگشتِ شہادت اور درمیانی انگلی کے ساتھ(اشارہ کرکے)فرمایا۔‘‘","صحیح",{"k":"صحیح بخاری (6005)، سنن أبوداؤد (5150)، سنن ترمذی (1918)۔","f":"یعنی جس طرح انگشتِ شہادت اور درمیان والی انگلی باہم ملی ہوئی ہیں اور ان میں کوئی فاصلہ نہیں ہے اسی طرح یتیم کی کفالت کرنے والا شخص رسولِ مکرم صلی اللہ علیہ وسلم کے بالکل ساتھ ہوگا۔"}],[21,"اُمِ سعید رضی اللہ عنہا اپنے باپ سے روایت کرتی ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’میں اور اپنے یاکسی غیر کے یتیم کی کفالت کرنے والاجنّت میں ان دو(انگلیوں)کی طرح ہوں گے۔ سفیانؒ نے یہ حدیث بیان کرتے ہوئے اپنی دو انگلیوں کے ساتھ اشارہ کیا۔‘‘","صحیح",{"k":"السنن الکبری للبیهقی (6؍283)، الأدب المفرد للبخاری (133)، سلسلہ الأحادیث الصحیحہ (800)۔","f":"یعنی کفالتِ یتیم کا یہ اجروثواب اپنے کسی عزیز بچے کی کفالت کے ساتھ ہی خاص نہیں ہے بلکہ وہ یتیم اگر کسی اور کا بھی ہو تو اس کی کفالت میں بھی اسی قدر اجر ملے گا۔"}],[22,"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جس شخص نے اپنی دو بچیوں کی ان کے جوان ہونے تک کفالت کی، وہ روزِقیامت یوں آئے گاکہ وہ اور میں ان دو(انگلیوں)کی طرح ہوں گے۔ آپ صلی اللہ علیہ وسلم نے یہ فرماتے ہوئے اپنی دو انگلیوں کو ملایا۔‘‘","صحیح",{"k":"صحیح مسلم (2631)، سنن ترمذی (1914)۔"}],[23,"عقبہ بن عامر رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’جس کی تین بیٹیاں ہوں اور وہ ان پہ صبر کرے اوجو کچھ میسر ہو اس میں سے انہیں کھلائے پِلائے اور(لباس) پہنائے، تو وہ (روزِقیامت)اس کے لیے (عذاب سے) آڑبن جائیں گی۔‘‘","صحیح",{"k":"سنن ابن ماجه (3669)، الأدب المفرد للبخاری (76)، سلسلہ الأحادیث الصحیحہ (294)۔","f":"جس شخص کی دویا تین بچیاں ہوں وہ ان کی اچھی طرح کفالت کرے، ان کی تعلیم وتر بیت کا اہتمام کرے اور دیگر حقوق بھى بہ خوبی ادا کرے تو وہ بھی نبی صلی اللہ علیہ وسلم کا ساتھ پائے گااور وہ بچیاں اس کے لیے جہنّم سے آڑبن جائیں گی یعنی اس عمل کے بہ دولت اللہ تعالیٰ اسے جہنّم سے بچا لیں گے۔"}],[24,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’اللہ تعالیٰ نے رحمت کے سوحصے بنائے ہیں، ننانوے حصوں کو اپنے پاس رکھا ہے اور ایک حصے کو زمین پہ اتارا ہے، چنانچہ مخلوقِ خدا کا باہم رحم وکرم سے پیش آنا(بلکہ)یہاں تک کہ گھوڑا جو اس ڈرسے اپنے بچے سے اپنی ٹانگ کو اٹھائے ركھتا ہے کہ کہِیں اس کی ٹانگ اس کے بچے کونہ کچل دے، یہ سب رحمت کے اسی ایک حصے سے ہے۔‘‘","صحیح",{"k":"صحیح بخاری (6000)، صحیح مسلم (2752)۔","f":"مذکورہ حدیث میں اللہ کی رحمت کا بیان ہے کہ اللہ تعالیٰ کی رحمت کے سوحصوں میں سے اس نے صرف ایک حصہ زمین پر اتارا ہے اور تمام مخلوقِ خدا،خواہ وہ جِن وانس ہوں یاچرندو پرند، وہ سب آپس میں جو رحم وکرم سے پیش آتے ہیں وہ صرف اس ایک حصے کے بدولت ہے، حتىٰ كہ ايك گھوڑا اگر كھڑا ہو اور نيچے اس كابچہ بيٹھا ہو اور گھوڑے كى وہ ٹانگ جو اس كے بچے كى طرف ہوتی ہے وہ اسے صرف اس خدشے كے باعث اوپر اٹھائے ركھتا ہے کہ اگر وہ زمين پر ركھے گاتوكہِيں اس كابچہ نيچے آكركچلاہى نہ جائے۔ تو فرما ياكہ گھوڑے كي يہ محبت بھى رحمتِ الہٰى كے اسى ايك حصے میں سے ہوتی ہے۔ چنانچہ اندازہ کیجیے کہ باقی ننانوے حصے اللہ تعالیٰ نے اپنے پاس رکھے ہیں تو اس كى رحمت كاكيا عالم ہوگا اور وہ کس درجہ مہربان ہوگا؟"}],[25,"جریربن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’اللہ تعالیٰ ایسے شخص پر رحم نہیں فرماتا جو لوگوں پر رحم نہ کرتا ہو۔‘‘","صحیح",{"k":"صحیح بخاری (7376)، صحیح مسلم (2316)۔"}],[26,"جریربن عبداللہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’جو شخص لوگوں پر رحم نہیں کرتا اللہ تعالیٰ بھی اس پر رحم نہیں فرماتا۔‘‘","صحیح",{"k":"صحیح بخاری (7376)، صحیح مسلم (2316)۔"}],[27,"عبداللہ بن عمروبن عاص رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’رحم کرنے والوں پر رحمان (عزوجل)رحم فرماتا ہے، سوتم زمین والوں پر رحم کیا کرو تم پر آسمان والا رحم فرمائے گا۔‘‘","صحیح",{"k":"سنن أبوداؤد (4941)، سنن ترمذی (1924)، صحیح الجامع للألبانی (7467)۔","f":"مذکورہ احادیث سے معلوم ہوا کہ رحمتِ الہٰی کا مستحق بننے کے لیے مخلوقِ خدا پر رحم کرنا ضروری ہے اور جو اس کا اہتمام نہیں کرتا وہ اللہ تعالیٰ کے رحم كاحقدار نہیں ٹھہرتا۔"}],[28,"عیاض بن حمار رضی اللہ عنہ سے مروی ہے کہ پیغمبرِخدا صلی اللہ علیہ وسلم نے فرمایا:\n’’جنّتی لوگ تین طرح کے ہوں گے:(پہلا)ایسا صاحبِ سلطنت شخص کہ جو میانہ روہو، صدقہ وخیرات کرنے والا ہو اور(بھلائی)کی توفیق سے نوازا گیا ہو، (دوسرا)وہ مہربان شخص جوہر قرابت دار اور ہرمسلمان کے لیے نرم دِل ہواور(تیسرا)وہ غریب شخص جو(لوگوں سے مانگنے)سے بچتا ہوا اور(حتی الوسعت)صدقہ وخیرات کرتا ہو۔‘‘","صحیح",{"k":"صحیح مسلم (2865)۔","f":"گويا وہ شخص بھى جنت كاحقدار ہے جو لوگوں كے ليے اپنے دِل ميں نرم گوشہ ركھتا ہے اور پھر اس كايہ رویّہ بلا تفريق ہوتاہے، يعنى خواہ اس کا کوئی قرابت دار ہویا غیر ہو، سب كے ساتھ اس كاسلوك رحم وكرم كاہوتا ہے۔"}],[29,"نعمان بن بشیر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’مسلمانوں کا آپس میں رحم وکرم، محبت ومودّت اور میل جول کا معاملہ ایک جسم کے مانند ہے، جب اس کے جسم کا ایک عضو تکلیف میں مبتلا ہوتا ہے تو سارا جسم بخار اوربے خوابی کے ساتھ اس کی تکلیف میں شریک ہو جاتا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (6011)، صحیح مسلم (2586)۔","f":"یعنی جس طرح جسم کے ایک عضو میں تکلیف ہونے سے سارا جسم بے آرام وبے سکون ہو جاتا ہے اسی طرح ایک مسلمان کے دُکھ، تکلیف اور کسی بھی قسم کی پریشانی میں مبتلا ہو جا نے سے تمام مسلمانوں کوبے چین ہو جانا چاہیے اور اپنی اپنی استطاعت کے مطابق اس کے دُکھ، درد اور پریشانی کا مداوا کرنا چاہیے۔"}],[30,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے صادق ومصدوق ابوالقاسم صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’رحمت وشفقت سوائے بدبخت کے کسی سے نہیں چھِینی جاتی۔‘‘","حسن",{"k":"سنن أبوداؤد (4942)، سنن ترمذی (1923)، مسند أحمد (2؍301)۔","f":"یعنی جو کسی پر رحم اور شفقت نہیں کرتا وہ بدبخت شخص ہے، اور اس بدبختی کودُورکرنے اور سعادتمندی سے بہرہ مند ہو نے کے لیے دِل کو مہربان کرنا ضروری ہے۔"}],[31,"انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’میں نماز شروع کرتا ہوں تو لمبی نماز پڑھنے کا ارادہ کرتا ہوں، ليكن جب کسی بچے کے رونے کی آواز ميرے كان ميں پڑتى ہے تو میں اس بچے کی ماں کو اس کے باعث ہونے والی سخت بے چینی کو جان کر اس کی وجہ سے نماز مختصر کر دیتا ہوں۔‘‘","صحیح",{"k":"صحیح بخاری (709)، صحیح مسلم (470)۔","f":"یعنی آپ صلی اللہ علیہ وسلم کے دِل میں رحم اور شفقت اس قدر تھی کہ ایک ماں کا اپنے بچے کی وجہ سے بے چین ہو جانا بھی آپ صلی اللہ علیہ وسلم پر گراں گزرتا تھا اور اس کی خاطر آپ صلی اللہ علیہ وسلم نماز کو مختصر فرما دیتے تھے جوکہ بندگیٔ الہٰی کا عالی ترین مظہر ہے۔"}],[32,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’ایک آدمی راستے میں چلا جا رہا تھا کہ اسے پیاس لگ گئی، وہ (پانی پینے کے لیے)کنویں کے پاس آیا اور اتر کر پانی پیا، پھر نکلنے لگا تو اس نے دیکھا کہ ایک کُتاپیاس کے مارے مٹّی چاٹ رہا ہے، وہ دوبارہ کنویں کے پاس آیا اور اپنے موزے کو پانی سے بھر کرکتّے کے منہ سے لگا دیا، کتّے نے پانی پی لیا، تو اللہ تعالیٰ نے اس کے اس عمل کی قدر کی اور اسے بخش دیا۔ صحابہؓ نے عرض کیا:اے اللہ کے رسول!کیا ہمارے لیے چوپایوں میں بھی اجر ہے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ہرتازہ جِگر(جان کی خدمت)میں اجر ملتا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (2363)، صحیح مسلم (2244)۔","f":"ہرجاندار پر رحم کرنے میں اللہ تعالیٰ نے اجر رکھا ہے، حتیٰ کہ ہماری نظر میں جو حقیر ترین جا نورکُتاہے اس کو پانی پلانے سے ایک شخص کی مغفرت ہوگئی، تو گویا نیکی کے کسی معاملے کو بھی حقیر نہیں جاننا چاہیے خواہ وہ کسی جانور کی خدمت ہی کیوں نہ ہو۔"}],[33,"قُرہ روایت کرتے ہیں کہ ایک آدمی نے کہا:\n’’اے اللہ کے رسول!میں جب بکری ذبح کرنے لگتا ہوں تو اس پر رحم کرتا ہوں، آپ صلی اللہ علیہ وسلم نے فرمایا:اگر تو بکری پر بھی رحم کرے گاتو اللہ تعالیٰ تجھ پر رحم فرمائے گا۔‘‘","صحیح",{"k":"مسند أحمد (3؍436)، الأدب المفرد للبخاری (373)، سلسلہ الأحادیث الصحیحہ (26)۔","f":"بکری کو ذبح کرتے ہوئے رحم کرنے سے مراد یہ ہے کہ اسے اچھی طرح پکڑایا باندھا جائے تاکہ وہ قابو میں رہے اور درمیانِ ذبح چھُوٹ کر تڑپنے نہ لگے، اور ذبح کرنے کا آلہ تیز دھار ہونا چاہیے تاکہ وہ ایک ہی دفعہ اسے ذبح کر ڈالے، ایسا نہ ہوکہ وہ کُندہو اور تیز نہ چلنے کی وجہ سے بکری کو تڑپا نے کا باعث بنے، اسی طرح ذبح کرنے سے پہلے آلۂ ذبح جانور کے سامنے تیز کرنے سے بھی احتراز کرنا چاہیے تاکہ وہ جانور ذبح ہونے سے پہلے ہی موت کے خوف میں مبتلا نہ ہوجائے۔"}],[34,"عبداللہ بن عمرو رضی اللہ عنہما نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’جو شخص ہمارے چھوٹوں پر شفقت نہیں کرتا اور ہمارے بڑوں کے حق کو نہیں پہچانتا وہ ہم میں سے نہیں ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4943)، مسند أحمد (1؍257)، صحیح الجامع للألبانی (6540)۔","f":"شارحینِ حدیث نے لَيْسَ مِنَّاکے متعدد معانی کیے ہیں، ان سب کا خلاصہ یہ ہے:\nوہ ہماری سُنّت کی پیروی کرنے والا، ہمارے بتائے ہوئے راستے پر چلنے والا، ہماری ہدایت کو قبول کرنے والا، ہمارے علم وعمل کی اقتداء کرنے والا اور ہمارے بتائے ہوئے حکم پر عمل پیرا ہو نے والا نہیں ہے۔ (فتح الباری بشرح صحيح البخاری:۹/۷۰-شرح صحيح البخاری لابن بطال:۲/۲۸۱-شرح مسلم للنووی:۱/۱۰۹-شرح مسلم للسيوطی:۱/۸۳)"}],[35,"ابوموسیٰ اشعری رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’بلاشبہ بوڑھے مسلمان، غُلوو تقصیر سے بچنے والے صاحبِ قرآن اور منصف حکمران کی عزت کرنا اللہ تعالیٰ کی تعظیم کرنے میں سے ہیں۔‘‘","صحیح",{"k":"سنن أبوداؤد (4843)، صحیح الجامع للألبانی (2199)۔","f":"يعنى بزرگ شخص كى عزت واحترام اللہ تعالىٰ كى تعظيم كرنے كے مترادف ہے۔"}],[36,"جابربن عبداللہ رضی اللہ عنہ عرفات میں دیے گئے نبی کریم صلی اللہ علیہ وسلم کے خطبہ حجۃ الوداع کے بارے میں روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’عورتوں کے معاملے میں اللہ تعالیٰ سے ڈرتے رہا کرو، کیونکہ تم انہیں اللہ تعالیٰ کی امانت سے حاصل کرتے ہو اور اللہ کے کلمے سے ان کے ساتھ ہمبستری کو جائز کرتے ہو، یقیناًان کے ذمے بھی تمہارے کچھ حقوق ہیں(وہ یہ کہ)وہ تمہارے بستروں پر ایسے کسی شخص کونہ آنے دیں جسے تم ناپسند کرو، اور اگر وہ ایسا کریں تو انہیں مارو، لیکن ایسی مار نہ مارو کہ جو انہیں زخمی کردے، اور تمہارے ذِمے ان کے کھانے پینے اور لباس وغیرہ کی معروف انداز میں ذِمہ داری ادا کرنا ہے۔‘‘","صحیح",{"k":"صحیح مسلم (1218)، سنن أبوداؤد (1905)، سنن ابن ماجه (3074)۔"}],[37,"معاویہ رضی اللہ عنہ روایت کرتے ہیں کہ ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم سے سوال کیا:\n’’عورت کا اپنے خاوند پر کیاحق ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:یہ کہ جب وہ خود کھائے تو اسے بھی کھلائے، جب وہ خود(نيا لباس)پہنے تو اسے بھی پہنائے، اور صرف گھر ہی میں اسے تنہا چھوڑے، نہ اس کے چہرے پہ مارے اور نہ ہی اسے بُرابھلا کہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (2142)، سنن ابن ماجه (1850)، إرواء الغلیل للألبانی (2033)۔","f":"ان دونوں حدیثوں میں زوجین کے حقوق وفرائض بیان کیے گئے ہیں، خوشحال ازدواجی زندگی کے لیے آپ صلی اللہ علیہ وسلم کے بتلائے ہوئے ان زرِّیں اصولوں کو اپنانا ناگزیر ہے۔"}],[38,"ابو مسعود انصاری رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’مسلمان جب اپنی کمائی کو نیکی کی نیّت سے اپنے گھر والوں پر خرچ کرتاہے تو وہ اس کے لیے صدقہ لکھ دی جاتی ہے۔‘‘","صحیح",{"k":"صحیح مسلم (1002)، مسند أحمد (4؍120)۔","f":"یعنی اگر کوئی شخص اس نیّت سے اپنے اہلِ خانہ پر خرچ کرتاہے کہ میں اللہ کے حکم کی بجاآوری میں اپنے بیوی بچوں پر خرچ کر رہا ہوں تو اس کے لیے وہ بھی صدقہ بن جاتا ہے۔"}],[39,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’ایک دینار وہ جوتُونے راہِ خدا میں دے دیا، ایک دینار وہ جوتُونے کسی مسکین کو دے دیا اور ایک دینار وہ جوتُونے اپنے گھر والوں پر خرچ کیا، فرمایاکہ ان تینوں دیناروں میں سے اجروثواب کے لحاظ سے سب سے عظيم دینار وہ ہے جوتُونے اپنے گھر والوں پر خرچ کیا۔‘‘","صحیح",{"k":"صحیح مسلم (995)، مسند أحمد (2؍473)۔","f":"اس حدیث سے معلوم ہوا کہ اپنے بیوی بچوں پر خرچ کرنا راہِ خدا میں اور مساکین پر خرچ کرنے سے بھی زیادہ فضیلت رکھتا ہے، لیکن اگر اہلِ خانہ کے حقوق بہت عمدہ انداز میں ادا ہو رہے ہوں اور مالی وسعت بھی ہو تو پھر حسبِ حال اللہ تعالیٰ کی راہ میں اور محتاج ومساکین پر خرچ کرنا بھی اہم ہو جاتا ہے۔"}],[40,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’تم میں سے بہتر وہ ہے جو اپنے گھر والوں کے حق میں بہتر ہو، اور میں تم میں سے اپنے گھر والوں کے لیے بہتر ہوں، اورجب تمہارا کوئی ساتھی فوت ہوجائے تو تم اس کے لیے دعا کیا کرو اور اس کی برائیاں مت بیان کیا کرو۔‘‘","صحیح",{"k":"سنن ترمذی (3895)، سلسلہ الأحادیث الصحیحہ (285)۔"}],[41,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’بِلاشک عورت ٹیڑھی پسلی کے مانند ہے، اگرتُواسے سیدھا کرنے لگے گاتو توڑ بیٹھے گااور اگر تو اس سے فائدہ اٹھانا چاہتا ہے تو اس کے ٹیڑھے پَن کے باوجود ہی فائدہ اٹھا سکتا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (5184)، صحیح مسلم (1468)۔","f":"نبی صلی اللہ علیہ وسلم کے فرمان کے مطابق عورت کی پیدائش ٹیڑھی پسلی سے ہوئی ہے، اس بناء پر اس کے ساتھ اس ٹیڑھے پن کے ہوتے ہوئے ہی گزارا کیا جا سکتا ہے، اسے سیدھا کرنا یاسدھارنا سعی لاحاصل ہے کیونکہ فطری امور کو تبدیل نہیں کیا جا سکتا۔"}],[42,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’اگر میں کسی کو کسی کو سجدہ کرنے كاحكم ديتا تو عورت کو دیتا کہ وہ اپنے خاوند کو سجدہ کرے، اس تعظیم کی وجہ سے جو اللہ تعالیٰ نے خاوند کے حق سے عورت پر لازم کی ہے۔‘‘","صحیح",{"k":"سنن ترمذی (1159)، إرواء الغلیل للألبانی (1998)۔","f":"سجدہ سوائے مسجودِخلائق کے کسی کے لیے ہرگز جائز نہیں ہے بلکہ ایسا کرنے والا دائرۂ اسلام سے خارج ہے، لیکن آپ صلی اللہ علیہ وسلم نے فرمایاکہ اگر اللہ کے سوا کسی اور کو سجدہ جائز ہوتا تو میں عورت کو اپنے خاوند کے آگے سجدہ ریز ہو نے کاحکم فرماتا۔ اس فرمان سے خاوند کے مقام کابہ خوبی اندازہ ہو جاتا ہے کہ عورت کوکس درجے تک اس كے حقوق كى ادا ئيگى کا پاس ولحاظ رکھنا چاہیے۔"}],[43,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب کوئی آدمی اپنی بیوی کو اپنے بستر پر بلائے اور وہ(آنے سے)انکار کر دے اور(وہ آدمی)اس سے ناراضگی کی حالت میں رات بسر کرے، تو صبح ہونے تک فرشتے اس عورت پر لعنت بھیجتے رہتے ہیں۔‘‘","صحیح",{"k":"صحیح بخاری (5193)، صحیح مسلم (1436)۔"}],[44,"حصین بن محصن انصاری بیان کرتے ہیں کہ:\n’’ان کی (یعنی حصین کی)پھوپھی نے انہیں بتلایا کہ وہ کسی کام کی غرض سے رسول اللہ صلی اللہ علیہ وسلم کے پاس آئیں، جب وہ فارغ ہوگئیں تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا:کیا تمہارا خاوند ہے؟ انہوں نے جواب دیا:جی ہاں، آپ صلی اللہ علیہ وسلم نے فرمایا:تم کیسی ہو(یعنی اپنے خاوند کے ساتھ تمہارا رویہ کیسا ہے؟) انہوں نے کہا:میں اس کی اپنی عجز کی انتہاتک پرواہ نہیں کرتی، آپ صلی اللہ علیہ وسلم نے فرمایا:اس سے اپنے مقام کو پہچانو(یعنی اس کے حقوق کا خیال رکھو)، کیونکہ وہ تیری جنّت اور تیری جہنم ہے۔‘‘","صحیح",{"k":"مسند أحمد (4؍341)، مستدرک حاکم (2؍189)، سلسلہ الأحادیث الصحیحہ (2612)۔","f":"عجز کی انتہاء سے مراد یہ ہے کہ میں اس کا بہت زیادہ خیال نہیں رکھتی بلکہ مناسب سی دیکھ بھال کرتی ہوں، توآپ صلی اللہ علیہ وسلم نے اسے ناکافی سمجھتے ہوئے فرمایاکہ وہ تیری جنت اور جہنم ہے، یعنی اگرتُواس کے حقوق کو احسن انداز سے ادا کرے گی تو جنت کی حقدار ٹھہرے گی اور اگر اس کے حقوق کا خیال نہیں رکھے گی تو جہنم میں بھی جاسکتی ہے۔"}],[45,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’عورت کا خاوندجب(گھر میں)موجود ہو تو وہ اس کی اجازت کے بغیر روزہ نہیں رکھ سکتی، نہ ہی وہ اس کے گھر میں موجود ہوتے ہوئے اس کی اجازت کے بغیر(کسی کو گھر آنے کی)اجازت دے سکتی ہے، اور عورت اپنے خاوند کی کمائی سے اس کی اجازت کے بغیر جو بھی(راہِ خدا میں)خرچ کرے اس کا آدھا ثواب خاوند کو بھی ملے گا۔‘‘","صحیح",{"k":"صحیح بخاری (5195)، صحیح مسلم (1026)۔","f":"اس سے مراد نفلی روزہ ہے فرضی نہیں، کیونکہ فرائض کی ادائیگی میں کسی کی اجازت کی ضرورت نہیں ہوتی، اور مال خرچ کرنے کے بارے میں بعض اہلِ علم کا قول ہے کہ عورت اپنے خاوند کی اجازت کے بغیر صرف اس مال سے خرچ کر سکتی ہے جو خاوند نے اسے اس کے خرچے وغیرہ کے لیے دیا ہو۔"}],[46,"سیدنا علی المرتضیٰ رضی اللہ عنہ فرماتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم کی آخری کلام یہ تھی: نماز، نماز، (اور)اپنے زیرِملکیت لوگوں (یعنی غلاموں اور لونڈیوں)کے بارے میں اللہ تعالیٰ سے ڈرتے رہنا۔‘‘","صحیح",{"k":"سنن أبوداؤد (5156)، سنن ابن ماجه (2698)، مسند أحمد (1؍78)، إرواء الغلیل للألبانی (7؍238)۔","f":"فرمانِ باری تعالیٰ ہے: ﴿وَبِالْوَالِدَيْنِ إِحْسَانًا﴾ إِلٰى قَوْلِهِ: ﴿وَمَا مَلَكَتْ أَيْمَانُكُمْ﴾ [النساء:۳۶] ’’والدین کے ساتھ حسنِ سلوک سے پیش آؤ۔۔۔اور۔۔۔اپنے زیرِملکیت لوگوں کے ساتھ اچھا برتاؤ کرو۔‘‘"}],[47,"اُمِ سلمہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مرض الموت میں فرمایا:\n’’اللہ، اللہ، نماز کا اہتمام کرنا اور اپنے زیرِملکیت لوگوں کا خیال رکھنا، آپ صلی اللہ علیہ وسلم مسلسل یہی فرماتے رہے یہاں تک کہ آپ صلی اللہ علیہ وسلم کی زبان مبارک رُک گئی۔‘‘","صحیح",{"k":"سنن ابن ماجه (1625)، مسند أحمد (6؍290)۔","f":"گویا آپ صلی اللہ علیہ وسلم نے بہ وقتِ رحلت بھی جن اہم امور کے اہتمام کی بہ طورِخاص وصیّت فرمائی ان میں سے ایک امر غلاموں کے ساتھ اچھا سلوک کرنا ہے۔"}],[48,"معروربن سوید بیان کرتے ہیں کہ:\n’’میں نے ابوذرغفاری رضی اللہ عنہ کو دیکھا کہ وہ ایک عمدہ پوشاک پہنے ہوئے ہیں اور ان کے غلام نے بھی ایک عمدہ پوشاک پہنی ہوئی ہے، تو میں نے ان سے اس بارے میں پوچھا تو انہوں نے جواب دیا:ایک مرتبہ ایک شخص سے میری گالم گلوچ ہوگئی، اس نے رسول اللہ صلی اللہ علیہ وسلم کو میری شکایت کردی، تو رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا:کیا تم نے اسے اس کی ماں کی عاردِلائی ہے؟ میں نے کہا:جی ہاں، پھر آپ صلی اللہ علیہ وسلم نے فرمایا:یقیناًتمہارے غلام بھی تمہارے بھائی ہیں، اگرچہ انہیں اللہ تعالیٰ نے تمہاری ماتحتی میں دے رکھا ہے، سوجس شخص کا بھی بھائی اس کے ماتحت ہوا سے اس کو بھی وہی کچھ کھلانا چاہیے جو وہ خود کھائے اور اسے بھی وہی پہنائے جو وہ خود پہنے، اور ان کی طاقت سے زیادہ تم انہیں تکلیف مت دو اور اگر ان کی طاقت سے زیادہ ان پر بوجھ لادو بھی تو اس کام میں ان کی مدد کرو۔‘‘","صحیح",{"k":"صحیح بخاری (30)، صحیح مسلم (1661)۔","f":"جس شخص کے ساتھ حضرت ابوذرؓکا یہ واقعہ پیش آیا تھا وہ حضرت بلالؓ تھے، اور گالی گلوچ سے مراد لڑائی جھگڑے میں اُونچ نِیچ ہو جانا یابُرابھلا کہنا مراد ہے۔ بلالؓ چونکہ غلام تھے اس لیے نبی صلی اللہ علیہ وسلم نے اس کا ذمہ دار حضرت ابوذرؓکو ٹھہرایا اور تمام مسلمانوں کے لیے یہ حکم جاری فرمایاکہ غلاموں کے ساتھ امتیازی سلوک کی بجائے انہیں مساویانہ حقوق دِیے جائیں اور انہیں بھی ان سب سہو لیات سے نوازا جائے جو اپنے لیے ہوں۔"}],[49,"ابوذر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’تمہارے غلاموں اور لونڈیوں میں سے جو تمہارے موافق ہوں انہیں بھى تم وہی کھلاؤ جو تم کھاتے ہو اور وہی پہناؤ جو تم پہنتے ہو، اور جو ان میں سے تمہارے موافق نہ ہوں تو انہیں بیچ دو، اور اللہ کی مخلوق کو عذاب مت دو۔‘‘","صحیح",{"k":"سنن أبوداؤد (5161)، مسند أحمد (5؍158)۔","f":"موافق ہونے سے مراد یہ ہے کہ وہ تمہاری خدمت کرتے ہوں، اپنے فرائض کی ادائیگی میں کوتاہی نہ کرتے ہوں اور تابعفر مانی بجالاتے ہوں، اگر وہ یہ سب کرتے ہوں تو پھر انہیں اپنے جیسا کھلاؤپلاؤاور لباس پہناؤ۔ اور ساتھ ہی فرما دیا کہ اگر وہ یہ سب نہ کرتے ہوں تو پھر انہیں سزائیں نہ دویا ان کے حقوق سلب نہ کرو بلکہ ان کاحل یہ ہے کہ انہیں کسی اور کو بیچ دو مگر ان پر ظلم ہرگز نہ کرو۔"}],[50,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’غلام کو اچھے طریقے سے کھانا اور لباس مہیا کیا جائے اور اسے اس کی طاقت سے بڑھ کر کسی کام کی تکلیف نہ دی جائے۔‘‘","صحیح",{"k":"صحیح مسلم (1662)۔"}],[51,"ابوہریرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب تم میں سے کسی شخص کا خادم اس کے لیے کھانا تیار کر کے اسے پیش کرے اور(چونکہ)اس نے (تیار کرتے وقت)اس کی گرمی اور دھواں برداشت کیا ہوتا ہے(اس لیے)اسے (يعنى اس كے مالك كو)چاہیے کہ وہ اسے بھی اپنے ساتھ بٹھا کر کھلائے، لیکن اگر کھا ناکم ہو اور کھا نے والے زیادہ ہوں تو پھر بھی ایک یادو لقمے اس کے ہاتھ پہ رکھ دینے چاہییں۔‘‘","صحیح",{"k":"صحیح مسلم (1663)، سنن أبوداؤد (3846)۔","f":"افضل تو یہ ہے کہ اپنے غلام یاخادم کو اپنے ساتھ بٹھا کر کھانا کھلایا جائے لیکن اگر کسی وجہ سے اسے ساتھ بٹھا ناممکن نہ ہو تو پھر کھا نے میں سے کچھ نہ کچھ، خواہ ایک یادو لقمے ہی ہوں، اس کو تھما دینے چاہییں تاکہ اس نے جو کھانا پکاتے ہوئے آگ کی تپش برداشت کی ہے اس کا تھوڑا ساصِلہ مل جائے۔"}],[52,"ابو مسعود انصاری رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’میں اپنے غلام کو مار رہا تھا کہ میں نے ایک آواز سنی:اے ابومسعود!یاد رکھ، ابومسعود!یاد رکھ، ابومسعود!یاد رکھ کہ تیری اس پر قدرت سے کہِيں زیادہ اللہ تعالیٰ تجھ پر قادر ہے۔ میں نے پيچھے مُڑكرديكھا تو وہ نبی صلی اللہ علیہ وسلم تھے۔ میں نے (اسی وقت)کہا:اے اللہ کے رسول!یہ رضائے الٰہی کے لیے آزاد ہے۔ تو آپ صلی اللہ علیہ وسلم نے فرمایا:سنو!اگر تم یہ نہ کرتے توآگ تمہیں اپنی لپیٹ میں لے لیتی۔‘‘","صحیح",{"k":"صحیح مسلم (1659)، سنن أبوداؤد (5159)، سنن ترمذی (1948)۔"}],[53,"ابنِ عمر رضی اللہ عنہما نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’جس نے اپنے غلام یالونڈی کو تھپڑ لگایا یاا سے مارا، تو اس کا کفارہ یہی ہے کہ وہ اسے آزاد کر دے۔‘‘","صحیح",{"k":"صحیح مسلم (1657)۔","f":"گویا غلام کو مارنا اس قدر بڑا جرم ہے کہ اس کا کفارہ اس غلام کی آزادی ہے، یعنی اسے آزاد کر کے ہی وہ اس گناہ سے بری ہو سکتا ہے۔"}],[54,"ابوہریرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’جس نے اپنے غلام یالونڈی پر زنا کی تہمت لگائی تو اس پر روزِقیامت(تہمت کی)حَدلگائی جائے گی، سوائے اس کے کہ وہ اسی طرح ہو جیسے اس نے کہا۔‘‘","صحیح",{"k":"صحیح بخاری (6858)، صحیح مسلم (1660)۔","f":"یعنی اگر اس کا غلام یالونڈی حقيقتاًویسا ہی ہو جیسا اس نے کہا ہو تو اس صورت میں معافی ہو سکتی ہے وگرنہ روزِقیامت اسے اس تہمت کی سزا میں حَدلگائی جائے گی۔"}],[55,"ابنِ عمر رضی اللہ عنہما نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم سے پوچھا گیا:\n’’آپ صلی اللہ علیہ وسلم خادم سے کتنی مرتبہ درگزر کرتے ہیں؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:میں اس سے ہرروزستّرمرتبہ درگزر کرتا ہوں۔‘‘","صحیح",{"k":"سنن أبوداؤد (5164)، سنن ترمذی (1949)۔","f":"اگر خادم یانو کر ایک دِن میں ستّرمرتبہ بھی غلطی کرتاہے تو نبی صلی اللہ علیہ وسلم کے عمل کے مطابق اسے ستّربا رہی معاف کر دیا جائے، گویا اس کے بار بار غلطی کرنے پر اسے شائستگی اور نرمی سے سمجھایا تو جا سکتا ہے مگر زدو کوب نہیں کیا جا سکتا۔"}],[56,"ابوموسیٰ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’وہ غلام جو اچھے طریقے سے اپنے رب کی عبادت کرتاہے اور اس پر اس کے مالک کے جو خیرخواہی اور فرمانبرداری کے حقوق ہیں انہیں بھی بہ طریقِ احسن ادا كرتا ہے تو اس کے لیے دو گنا اجر ہے، ایک اجر اپنے رب کی اچھے طریقے سے عبادت کرنے کا اور دوسرا اجر اپنے اوپر عائد ہو نے والے اپنے آقا کے حقوق کی ادائیگی کا۔‘‘","صحیح",{"k":"صحیح بخاری (2551)۔","f":"لیکن اگر وہ اللہ تعالیٰ اور اپنے مالک یاان دونوں میں سے کسی ایک کے حقوق کی ادائیگی ميں كوتا ہی کرتاہے تو پھر وہ اس فضیلت کا حقدار نہیں بلکہ اس کے برعکس گناہ کا سزاوار ٹھہرے گا۔"}],[57,"ابوبردہ اپنے باپ سے روایت کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’تین لوگ ایسے ہیں جنہیں دو ہرے اجر سے نوازا جائے گا: (ایک)وہ بندہ جو پہلی کتاب پر بھی ایمان لایا اور اس پر بھی جو محمد( صلی اللہ علیہ وسلم )پر نازل کی گئی، (دوسرا) وہ شخص جس کی ملکیت میں لونڈی تھی، اس نے اس کی اچھے انداز میں تربیت کی پھر اسے آزاد کر کے اس سے شادی کرلی، اور(تیسرا)وہ غلام جو اللہ تعالیٰ کاحق بھی ادا کرتا ہے اور اپنے مالکوں کاحق بھی ادا کرتا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (97)، صحیح مسلم (154)۔"}],[58,"عبداللہ بن عمر رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’سنو!تم میں سے ہرایک نگران ہے اور ہرایک سے اس کے زیرِنگیں لوگوں کے بارے میں پوچھا جائے گا، امیر(حکمران)لوگوں پر نگران ہے اور اس سے اپنی رعایا کے بارے میں پوچھا جائے گا، آدمی اپنے گھر والوں پر نگران ہے اور اس سے اپنے زیرِنگیں لوگوں کے بابت سوال ہوگا، آدمی کی بیوی اپنے خاوند کے گھر اور اس کے بچوں کی نگران ہے اور اس سے ان کے بابت پوچھا جائے گااور آدمی کا غلام اپنے آقا کے مال پر نگران ہے اور اس سے اس کے متعلق سوال کیا جائے گا، سنو!تم میں سے ہرایک نگران ہے اور ہرایک اپنے زیرِنگِیں کے بارے میں مسؤل ہے۔‘‘","صحیح",{"k":"صحیح بخاری (7137)، صحیح مسلم (1829)۔","f":"دنیا میں آنے والا ہرشخص کسی نہ کسی فردیا افراد کا نگران ہے اور اس سے اس کے زیرِنگیں لوگوں کے بارے میں سوال کیا جائے گاکہ تمہارى نگرانى ميں فلاں فلاں لوگ تھے، تم پر ان کی ذِمہ داری عائد تھی تو تم نے وہ کسقدر نبھائی ہے؟ وہ الله ورسول كے فلاں فلاں حكم سے سرتابى كيا كرتے تھے تو تم نے انہیں کیوں نہیں سمجھايا؟ ان كى خبر كيوں نہیں لی؟ جاننے كے باوجود بھى ان سے الله ورسول كى نافرمانى ترك كرواكر ان كے احكام كي بجا آورى كاا نہیں پابند كيوں نہیں بنایا؟ چنانچہ وہ رب کے حضور اپنے علاوہ اپنے زیرِنگرانی لوگوں کے بابت بھی جوا بدہ ہوگا۔ اس لیے ہرشخص کو اس ذِمہ داری کا احساس کرتے ہوئے اپنے فرائض کی ادائیگی میں کوئی دقیقہ فروگذاشت نہیں چھوڑنا چاہیے تاکہ کل روزِقیامت رب تعالیٰ کے حضور جواب دہی کے معاملے کو آسان بنایا جا سکے۔"}],[59,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جس نے کسی نو کر کو اس کے مالک کے خلاف بھڑکایا وہ ہم میں سے نہیں، اورجس نے کسی عورت کا اس کے خاوند کے خلاف ذہن بگاڑا وہ بھی ہم میں سے نہیں۔‘‘","صحیح",{"k":"السنن الکبری للبیهقی (8؍13)، مسند أحمد (2؍397)، سلسلہ الأحادیث الصحیحہ (324)۔","f":"نو کر کو مالک کے خلاف اور بیوی کو اس کے خاوند کے خلاف بھڑکانا بہت بڑے فساد کا باعث بنتا ہے، اس کی قباحت کی وجہ سے آپ صلی اللہ علیہ وسلم نے ایسے عملِ بدکے مرتکب کے ساتھ لاتعلقی کا اظہار فرمایا ہے کہ ایسا شخص ہمارے طریقے اور راستے پر نہیں ہے۔"}],[60,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جبرائیل علیہ السلام مجھے ہمسائے کے ساتھ (حسنِ سلوک کی)مسلسل وصیّت کرتے رہے، یہاں تک کہ مجھے گمان ہونے لگا کہ وہ اسے وراثت میں شریک کردیں گے۔‘‘","صحیح",{"k":"صحیح بخاری (6014)، صحیح مسلم (2624)۔","f":"اللہ تعالیٰ فرماتا ہے: ﴿وَبِالْوَالِدَيْنِ إِحْسَانًا وَبِذِي الْقُرْبٰى وَالْيَتَامٰى وَالْمَسَاكِينِ وَالْجَارِ ذِي الْقُرْبٰى وَالْجَارِ الْجُنُبِ وَالصَّاحِبِ بِالْجَنْبِ وَابْنِ السَّبِيلِ﴾ [النساء: ۳۶] ’’والدین کے ساتھ، قریبی رشتے داروں، یتیموں، مسکینوں، قرابت دار ہمسائے، اجنبی ہمسائے، پہلُوکے ساتھی اور راہ چلتے مسافر کے ساتھ حسنِ سلوک سے پیش آؤ۔‘‘\nجبرائيل عليہ السلام نبى كريم صلی اللہ علیہ وسلم كوہمسائے کے ساتھ حسنِ سلوک کی اسقدر شدید اور مسلسل تاکید فرماتے رہے کہ آپ صلی اللہ علیہ وسلم كویہ گمان گزرنے لگا کہ شاید اسے وراثت میں ہی شامل کر دیا جائے گا، یعنی جس طرح وارث اپنے مورّث کے مال کا حقدار ہوتا ہے اسی طرح ہمسائے کے بھی اس حق کا اہل ہونے کا گمان ہونے لگا۔"}],[61,"ابوشریح خزاعی رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جو شخص اللہ تعالیٰ پر ایمان اور آخرت(کے واقع ہونے)پر یقین رکھتا ہوا سے اپنے مہمان کی عزّت کرنی چاہیے، اور جو شخص اللہ اور یومِ آخرت پر ایمان رکھتا ہوا سے اپنے ہمسائے کے ساتھ حسنِ سلوک سے پیش آنا چاہیے اور جو اللہ وروزِآخرت پر ایمان رکھتا ہوا سے یاتو اچھی بات کرنی چاہیے یاپھر خاموش ہی رہنا چاہیے۔ اور ابو سلمہؓ اپنے ہمسائے کو تکلیف نہ دے۔سے مروی ایک روایت میں یہ اضافہ ہے کہ (نبی صلی اللہ علیہ وسلم نے فرمایا:)وہ اپنے ہمسائے کو تکلیف نہ دے۔‘‘","صحیح",{"k":"صحیح بخاری (6135)، صحیح مسلم (48)۔","f":"گویا ایمان کا یہ تقاضا ہے کہ ہمسائے کے ساتھ اچھا سلوک کیا جائے جس سے پتہ چلتا ہے کے ہمسائے کے ساتھ بُراسلوک کرنے والا کامل طور پر مومن نہیں ہے۔"}],[62,"ابوشریح کعبی رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’اللہ کی قسم!وہ مومن نہیں ہے، اللہ کی قسم!وہ مومن نہیں ہے، آپ صلی اللہ علیہ وسلم نے یہ تین مرتبہ فرمایا۔ صحابہؓ نے عرض کیا:اے اللہ کے رسول!ایسا کون ہے؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:جس کا ہمسایہ اس کی تکلیفوں سے محفوظ نہ ہو۔ صحابہؓ نے پوچھا:اس کی تکلیفوں سے کیا مراد ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:اس کاشر۔‘‘","صحیح",{"k":"صحیح بخاری (6016)۔","f":"اس امر کی شدّت کا اندازہ اس سے لگا ئیے کہ نبی مکرم صلی اللہ علیہ وسلم نے اللہ کی قسم اُٹھا کر ایک بار نہیں بلکہ تین بار فرمایا کہ وہ شخص ایمان سے متصف نہیں ہے جس کی شرانگیزیوں اور فتنہ پردازیوں سے اس کا ہمسایہ محفوظ نہ ہو۔"}],[63,"سیدہ عائشہ رضی اللہ عنہا سے مروی ہے کہ انہوں نے عرض کیا:\n’’اے اللہ کے رسول!میرے دو ہمسائے ہیں، میں ان میں سے کسے تحفہ بھیجوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا:ان دونوں میں دروازے کے لحاظ سے جو تمہارے زیادہ قریب ہو۔‘‘","صحیح",{"k":"صحیح بخاری (2259)، مسند أحمد (6؍239)۔","f":"ایک گھر کے بہت سے ہمسائے ہوتے ہیں، اگر تو اتنی استطاعت ہوکہ سبھی کو تحفہ دیا جا سکتا ہو تو ایسا کرنا انتہائی فضیلت کا حامل عمل ہوگا، لیکن اگر اتنی استطاعت نہیں ہے بلکہ کسی ایک کو ہی دینے كى گنجائش ہو تو پھر اس ہمسائے کو تحفہ دینا چاہیے جس کا دروازہ آپ کے گھر کے قریب پڑتا ہو، کیونکہ وہی اس کا زیادہ حق رکھتا ہے۔"}],[64,"ابوذر رضی اللہ عنہ فرماتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم نے مجھے (امیر کی)سمع واطاعت کی وصیت فرمائی، اگرچہ وہ ناک کان کٹا غلام ہی ہو، اور(یہ بھی وصیت فرمائی کہ)جب میں سالن تیار کروں تو اس میں پانی زیادہ ڈال لیا کروں، پھر میں دیکھوں کہ کونسا گھر میرے گھر کے قریب ہے تو انہیں بھی مناسب سادے دوں۔‘‘","صحیح",{"k":"صحیح مسلم (1837)، الأدب المفرد للبخاری (113)۔"}],[65,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’اے مسلمان عورتو!کوئی بھی عورت اپنی ہمسائی (کو تحفہ دینے)کے لیے(کسی بھی چیز کو)ہرگز حقیر نہ سمجھے، اگرچہ وہ بکری کاکھُرہی ہو۔‘‘","صحیح",{"k":"صحیح بخاری (2566)، صحیح مسلم (1030)۔","f":"حقِ ہمسائیگی ادا کرنے کے لیے کسی بھی چیز کو کمتر نہیں سمجھنا چاہیے بلکہ جس قدر استطاعت ہو حسنِ سلوک کا معاملہ کرنا چاہیے، خواہ وہ ہنڈیا میں پانی زیادہ ڈال کے شوربا بناكر اپنے سالن سے ہمسائے كوبھى حصہ دینے سے ہویا بکری کا ایک کھُرہی میسر آنے پر اسے اپنے ہمسائے كوبہ طورِتحفہ پیش کردینے سے ہو، کسى بھي طرح سے حُسنِ سلوك كاجسقدربھى مظاہرہ کیا جا سکتا ہے کرنا چاہیے۔"}],[66,"مجاہدؒبیان کرتے ہیں کہ:\n’’ہم عبداللہ بن عمروبن عاص رضی اللہ عنہ کے پاس بیٹھے ہوئے تھے کہ ان کے غلام نے ایک بکری ذبح کی تو انہوں نے اپنے غلام سے فرمایا:اے غلام!جب تُوفارغ ہوجائے تو پہلے ہمارے یہودی ہمسائے کو(گوشت)دینا، آپؓ نے یہ تین مرتبہ فرمایا، لوگوں میں سے ایک آدمی بولا: اللہ تعالیٰ آپ کی اصلاح فرمائے آپ یہودی کی بات کررہے ہیں۔ تو انہوں نے فرمایاکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو ہمسائے کے ساتھ حسنِ سلوک کی اسقدر وصیت فرماتے سنا کہ ہمیں گمان ہونے لگ گیا تھا کہ آپ صلی اللہ علیہ وسلم اسے وراثت میں بھی حصے دار بنا دیں گے۔‘‘","صحیح",{"k":"سنن أبوداؤد (5152)، سنن ترمذی (1943)۔","f":"معلوم ہوا کہ اگر ہمسایہ غیر مسلم ہے تو اس کے ساتھ بھی اچھا سلوک کرنا چاہیے، یہ حكم صرف مسلمان ہمسایوں کے بارے میں خاص نہیں ہے۔"}],[67,"ابنِ عباس رضی اللہ عنہما نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’وہ شخص مومن نہیں ہے جو(خود تو)سیر شكم ہو، جبکہ اس کے پہلُومیں اس کا ہمسایہ بھُوکا ہو۔‘‘","صحیح",{"k":"الأدب المفرد للبخاری (112)، مستدرک حاکم (4؍167)، سلسلہ الأحادیث الصحیحہ (149)۔","f":"آپ صلی اللہ علیہ وسلم نے ایسے شخص کو مومنین کی صف سے خارج فرمایا ہے جو خود تو پيٹ بھر كركھاناكھائے ليكن اس كے پہلُوميں اس ہمسايہ بھُوكا ہو۔"}],[68,"ابوشریح کعبی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جو شخص بھی اللہ تعالیٰ اور روزِآخرت پر ایمان رکھتا ہے اسے اچھی بات ہی کہنی چاہیے، یاپھر خاموش رہے۔ اور جو شخص اللہ تعالیٰ اور قیامت کے دِن پر ایمان رکھتا ہے اسے اپنے ہمسائے کی عزت کرنی چاہیے اور جو اللہ تعالیٰ اور یومِ آخرت پر ایمان رکھتا ہے اسے اپنے مہمان کی عزت كرنی چاہیے، ایک دِن اور ایک رات پر تكلف مہمان نوازی کرنی چاہیے اور تین دِن تک پُرتكلّف اور تين دِن تك مناسب مہمان نوازی كرنی چاہیے اور جو اس کے بعد ہو وہ صدقہ ہے، اور مہمان کے لیے بھی جائز نہیں ہے کہ وہ اس کے پاس ہی بیٹھ رہے کہ اسے پریشانی میں ہی ڈال دے۔‘‘","صحیح",{"k":"صحیح بخاری (6135)، صحیح مسلم (48)۔","f":"مہمان کی ضیافت ہرمسلمان کا اخلاقی فرض ہے، رسولِ مکرم صلی اللہ علیہ وسلم نے ہرمومن شخص کو حکماًاس کی تاکید فرمائی ہے۔ مہمان کی میزبانی کی کم ازکم مدت جو لازم ہے وہ ایک دِن ہے جبکہ تین دِن تک وہ اس کاحق رکھتا ہے، یعنی ایک دِن اس کی پُرتکلف خدمت کی جائے اور باقی دودِن جو میسر ہو، اور اگر تین دِن کے بعد بھی میزبان اس کی خاطر تواضع کرتاہے تو یہ اس کے لیے صدقہ ہوگا، يعنى ميزبان كواس مہمان نوازى كے بدلے ميں صدقے كااجرو ثواب ملے گا۔ البتہ مہمان کے لیے بھی نبی کریم صلی اللہ علیہ وسلم نے یہ حکم فرمایا ہے کہ اسے اپنے میزبان کے ہاں بیٹھ نہیں رہنا چاہیے کہ اسے مشقت میں ہی ڈال دے بلکہ وہ کوشش کرے کہ جتنا جلدی ممکن ہو اپنے گھر کو روانہ ہوجائے۔"}],[69,"اشہب بیان کرتے ہیں کہ:\n’’امام مالکؒ سے نبی صلی اللہ علیہ وسلم کے فرمان: ’’مہمان کی ایک دِن اور ایک رات تک مہمان کی اچھی طرح ضیافت کی جائے۔‘‘ کے بارے میں سوال کیا گیا تو انہوں نے فرمایا:میزبان اپنے مہمان کی عزت کرے، اسے تحفہ دے، اسے خصوصی اہمیت دے اور پورا ایک دِن اور ایک رات اس کی حفاظت کرے، اور مہمان نوازی تین دِن تک ہوتی ہے۔ سلیمان خطابی فرماتے ہیں کہ اس کا مطلب یہ ہے کہ جب مہمان اس کے ہاں آئے تو ایک دِن اور ایک رات اس کی پُرتکلّف خدمت کرے اور اسے تحفہ دے، اور اور دیگر ایام میں اس کے ساتھ اچھا سلوک کرے، اور دوسرے دودِنوں میں جو کچھ باقی ہوا سے پیش کردے اورجب تین دِن گزر جائیں تو اس نے اپنا(مہمان نوازی کا)حق ادا کر دیا، لیکن اگر وہ اس سے بھی زیادہ کرے گاتو اس کے لیے صدقے کا اجروثواب لازم ہوجائے گا۔‘‘","صحیح",{"k":"سنن أبوداؤد (3748)۔","f":"مہمان نوازی صرف قیام وطعام کی نہیں ہوتی بلکہ مہمان کی ہرلحاظ سے خدمت، حفاظت، اکرام وتعظیم کرنا اور اپنی استطاعت کے مطابق اسے تحفہ دینا بھی مہمان نوازی میں شامل ہے۔ ابوعبیدہ الھروی اس حدیث کے مفہوم کو یوں بیان کرتے ہیں کہ تین دِن تک مہمان نوازی کرے، پھر اسے اتنا دے دیا جائے کہ جو ایک دِن اور ایک رات کی مسافت میں کفایت کر سکے۔ يَحُوزُاصل میں حِيْزَةسے ہے، اس کا مطلب یہ ہے کہ کھانے اور پینے کی وہ مقدار جو مسافر ایک منزل سے دوسری منزل تک كے سفر کے دوران استعمال کرتاہے۔"}],[70,"شقیق بیان کرتے ہیں کہ:\n’’میں اور میرا ایک ساتھی سلمان کے پاس حاضر ہوئے تو انہوں نے ہمیں روٹی اور نمک پیش کیا اور فرمایا:اگر نبی صلی اللہ علیہ وسلم نے ہمیں تکلّف سے منع نہ کیا ہوتا تو ہم تمہارے لیے پُرتکلّف کھانا تیار کرتے۔ تو میرے ساتھی نے کہا:کاش!اگر اس نمک میں پہاڑی پودینہ ڈال دیا جائے(تو بہتر ہو جائے)، تو سلمان نے اپنا لوٹا سبزی فروش کو ديا اور اسے گروی رکھ کر اس کے عوض میں پہاڑی پودینہ لے آئے اور اس میں ڈال دیا۔ جب ہم کھانا کھا چکے تو میرے ساتھی نے کہا: «اَلْحَمْدُ لِلّٰهِ الَّذِي قَنَّعَنَا بِمَا رَزَقَنَا» ’’تمام تعریفیں اس اللہ کے لیے ہیں جس نے ہمیں اس رزق پر قناعت کی توفیق دی جو اس نے ہمیں عطا کیا۔‘‘ تو سلمان فرمانے لگے کہ اگر تم نے اللہ کے دِیے ہوئے رزق پر کفایت کی ہوتی تو میرا لوٹا گروی نہ پڑا ہوتا۔‘‘","صحیح",{"k":"مستدرک حاکم (4؍123)، المعجم الکبیر للطبرانی (6؍288)، سلسلہ الأحادیث الصحیحہ (2392)۔","f":"اس سے مرا دبے جا تکلف ہے کہ آدمی اپنی استطاعت سے بڑھ کر اور ضرورت سے زائد ضیافت کا اہتمام کرے، لیکن اگر ایسا نہ ہو تو مناسب تکلف میں حرج نہیں ہے، وگرنہ جو میسر ہو وہی پیش کر دینا چاہیے اور مہمان کو بھی اسی پر قناعت کرنی چاہیے۔"}],[71,"عبداللہ بن سلام رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم جس وقت(مدینہ)تشریف لائے تو لوگ جوق درجوق آپ صلی اللہ علیہ وسلم کے پاس حاضر ہو نے لگے، اور(سب کو)بتایا جا نے لگا کہ رسول اللہ صلی اللہ علیہ وسلم تشریف لے آئے ہیں۔ راوی کہتے ہیں کہ میں بھی لوگوں کے ساتھ ہو لیا تاکہ میں بھی آپ صلی اللہ علیہ وسلم کو دیکھ کر آؤں، جب میں نے خوب اچھی طرح سے آپ صلی اللہ علیہ وسلم کے چہرۂ اقدس کا دیدار کیا تو میں ایک ہی بات سمجھا کہ آپ صلی اللہ علیہ وسلم کا چہرہ کسی جھوٹے شخص کا چہرہ نہیں ہوسکتا۔ چنانچہ سب سے پہلی بات جو آپ صلی اللہ علیہ وسلم کو فرماتے ہوئے میں نے سُنی(وہ یہ تھی:)اے لوگو!سلام کو پھیلاؤ، (ضرورت مندوں کو)کھانا کھلاؤ، رشتے داری کو ملاؤ، رات کو نماز پڑھوجب لوگ سور ہے ہوں، (ان تمام اعمال کے صلے میں)تم جنّت میں سلامتی سے داخل ہو جاؤگے۔‘‘","صحیح",{"k":"سنن ترمذی (2485)، سنن ابن ماجه (3251)، سلسلہ الأحادیث الصحیحہ (569)۔","f":"اللہ تعالیٰ کا فرمان ہے: ﴿وَيُطْعِمُونَ الطَّعَامَ عَلٰى حُبِّهِ مِسْكِينًا وَيَتِيمًا وَأَسِيرًا﴾ [الدهر: ۸] ’’اور(نیک لوگ)اللہ تعالیٰ کی محبت میں مسکین، یتیم اور قیدی لوگوں کو کھانا کھلاتے ہیں۔‘‘"}],[72,"ابوموسیٰ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’بھُوکے کو کھلاؤ، مریض کی عیادت کرو اور قیدی کو آزاد کراؤ۔‘‘","صحیح",{"k":"صحیح بخاری (3046)، سنن أبوداؤد (3105)۔"}],[73,"براء رضی اللہ عنہ بیان کرتے ہیں کہ ایک بدوی رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور اس نے کہا:\n’’اے اللہ کے رسول!مجھے کوئی ایسا عمل بتائیں جو مجھے جنّت میں لے جائے، تو آپ صلی اللہ علیہ وسلم نے فرمایا:اگرتُوخطبے کو مختصر کرے گاتو مانگنے سے بچ سکتا ہے، رُوح کو آزاد کر اور گردن کو بھی آزادی دلا۔ اس نے کہا:یہ دونوں(یعنی رُوح اور گردن کو آزاد کرنا)ایک ہی نہیں ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا:نہیں، رُوح کو آزاد کرنا یہ ہے کہ تُواکیلا ہی کسی کو آزاد کرائے اور گردن کو آزاد کرا نے کا مطلب یہ ہے کہ تُواس کی قیمت(کی ادائیگی)میں تعاون کرے، زیادہ دودھ دینے والی بکری کا عطیہ کر، ظالم رشتے دار سے ملتا جلتارہ، لیکن اگرتُواس کی طاقت نہیں رکھتا توبھُوکے کو کھانا کھلا اور پیا سے کو پانی پلا، نیکی کرنے کا کہہ اور برائی سے روک، اور اگر اس کی بھی تجھ میں طاقت نہیں ہے تو اپنی زبان سے سوائے اچھی بات کے اور کچھ مت بول۔‘‘","صحیح",{"k":"مسند أحمد (4؍299)، السنن الکبری للبیهقی (10؍273)، مسند الطیالسی (739)، صحیح الترغیب والترهیب (1898)۔"}],[74,"سراقہ بن مالک بن جعشم رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’میں نے رسول اللہ صلی اللہ علیہ وسلم سے گمشدہ اونٹ کے بابت پوچھا کہ اگر وہ میرے حوض پر آجائے جو میں نے اپنے اونٹوں کو پانی پلانے کے لیے بنایا ہے، تو کیا اسے پانی پلانے پر مجھے ثواب ملے گا؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:ہاں!حرارت والی ہرذی رُوح چیز(کی خدمت کرنے)میں ثواب ملتا ہے۔‘‘","صحیح",{"k":"سنن ابن ماجه (3686)، سلسلہ الأحادیث الصحیحہ (2152)۔"}],[75,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ لوگوں نے پوچھا:\n’’اے اللہ کے رسول!کیا ہمیں جانوروں(کو کھلا نے پلانے)میں بھی اجر ملتا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:ہرتازہ جِگر(جان کی خدمت)میں اجر ملتا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (2363)، صحیح مسلم (2244)۔","f":"مذکورہ بالا تمام احادیث کھانا کھلا نے اور پانی پلانے کے حکم اور اس کے اجروثواب سے متعلق ہیں، یہ حکم صرف محتاج ومسکین کو کھانا کھلا نے کے ساتھ خاص نہیں ہے بلکہ ان کے علاوہ ديگر لوگوں کی بھی دعوت وغیرہ کرنے سے یہی اجروثواب ملتا ہے، بشرطیکہ نیّت فقط رضائے الہٰی کا حصول ہو۔ نیز اس میں تمام جاندار شامل ہیں خواہ وہ انسان ہوں یاحیو ان، ہرایک سے نیکی کا یہ معاملہ کرنا باعثِ خیر ہے۔"}],[76,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’اگر مجھے بازو(کا گوشت)تحفے میں دیا جائے تو بھی میں قبول کر لوں گااور اگر مجھے پائے(کے گوشت)کی دعوت دی جائے تو میں اسے بھی قبول کر لوں گا۔‘‘","صحیح",{"k":"صحیح بخاری (2568)، مسند أحمد (2؍424)۔"}],[77,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’اے مسلمان عورتو!کوئی بھی عورت اپنی ہمسائی (کو تحفہ دینے)کے لیے(کسی بھی چیز کو)ہرگز حقیر نہ سمجھے، اگرچہ وہ بکری کاکھُرہی ہو۔‘‘","صحیح",{"k":"صحیح بخاری (2566)، صحیح مسلم (1030)۔"}],[78,"ابوہریرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’آپس میں تحائف دِیالیِاکرو، اس سے باہم محبت بڑھتی ہے۔‘‘","حسن",{"k":"السنن الکبری للبیهقی (6؍169)، الأدب المفرد للبخاری (594)، إرواء الغلیل للألبانی (1601)۔","f":"باہم تحائف کے تبادلے سے محبت بڑھتی ہے، تحفے میں گراں قیمت چیز دینا ہرگز ضروری نہیں ہے اوربے جا تکلفات واسراف سے تو الله ورسول صلی اللہ علیہ وسلم نے ويسے ہی منع فرمایا ہے، اس لیے ان کو اپنے آپ پر لازم کرکے اس عظیم نیکی سے محروم نہیں ہونا چاہیے بلکہ آپ صلی اللہ علیہ وسلم کے فرمان کے مطابق اگر بکری کا ایک کھُربھی بہ طورِتحفہ دینا کمتر نہیں ہے تو پھر چھوٹى سے چھوٹى كسى بھى چيزكو تحفے ميں كرنے ميں عار نہیں سمجھنى چاہیے۔"}],[79,"عبداللہ بن مسعود رضی اللہ عنہما فرماتے ہیں:\n’’جہاں خرچ کرنے کی ضرورت نہ ہو، وہاں خرچ کرنا فضول خرچی ہے۔‘‘","حسن",{"k":"السنن الکبری للبیهقی (6؍63)۔"}],[80,"ورّاد بیان کرتے ہیں کہ سیدنا مغیرہ بن شعبہ رضی اللہ عنہ نے سیدنا معاویہ رضی اللہ عنہ کو لکھا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’یقیناًاللہ تعالیٰ نے تین کاموں کو حرام کیا ہے:ماؤں کی نافرمانی، لڑکیوں کو زندہ درگور کرنا اور ناحق مطالبہ کرنا اور تین کاموں سے منع فرمایا ہے:قِیل وقال، مال ضائع کرنے اورلِپٹ کر مانگنے سے۔‘‘","صحیح",{"k":"صحیح بخاری (5975)، صحیح مسلم (1715)۔","f":"مال ضائع کرنے سے مراد یہ ہے کہ اسراف وتبذیر سے کام نہ لیا جائے، اسراف سے مراد یہ ہے کہ کسی کام میں ضرورت سے زیادہ خرچ کیا جائے اور تبذیر اسے کہتے ہیں کہ ایسے کام میں خرچ کیا جائے جہاں خرچ کرنے کی سرے سے ضرورت ہی نہ ہو۔"}],[81,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’کوئی دِن ایسا نہیں ہوتا کہ جب بندے صبح کواُٹھتے ہیں تو(آسمان سے)دو فرشتے اترتے ہیں، ان میں سے ایک کہتا ہے:اے اللہ!خرچ کرنے والے کو اس کا اچھا بدلہ دے۔ اور دوسرا کہتا ہے:اے اللہ!مال کو(خرچ کرنے سے)روک رکھنے والے کا مال تلف کردے۔‘‘","صحیح",{"k":"صحیح بخاری (1442)، صحیح مسلم (1010)۔","f":"اللہ تعالیٰ خرچ کرنے والوں کی تعریف میں فرماتا ہے: ﴿وَسَارِعُوا إِلٰى مَغْفِرَةٍ مِنْ رَبِّكُمْ وَجَنَّةٍ عَرْضُهَا السَّمَوَاتُ وَالْأَرْضُ أُعِدَّتْ لِلْمُتَّقِينَ، الَّذِينَ يُنْفِقُونَ فِي السَّرَّاءِ وَالضَّرَّاءِ﴾ [آل عمران: ۱۳۳] ’’اپنے رب کی مغفرت اورجنّت کی طرف جلدی کرو(وہ جنّت)کہ جس کی چوڑائی آسمانوں اور زمین کے برابر ہے، وہ ان متّقین کے لیے تیار کی گئی ہے جو خوشحالی وتنگی میں خرچ کرتے ہیں۔‘‘\nایک مقام پہ اللہ تعالیٰ بخیل لوگوں کی مذمت میں فرماتا ہے: ﴿وَاللّٰهُ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُورٍ، الَّذِينَ يَبْخَلُونَ وَيَأْمُرُونَ النَّاسَ بِالْبُخْلِ﴾ [الحديد: ۲۴] ’’اور اللہ تعالیٰ اِترا نے والے شیخی خوروں کو پسند نہیں فرماتا، جو خود بھی بخل کرتے ہیں اور لوگوں کو بھی بخیلی سے کام لینے کا کہتے ہیں۔‘‘"}],[82,"ابوہریرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’خرچ کرنے والے اور کنجوسی کرنے والے کی مثال ان دو آدمیوں کی طرح ہے جو لو ہے کے دوکُرتے زیب تن کیے ہوئے ہوں، جو چھاتی سے لے کر ہنسلی تک ہوں۔ جب خرچ کرنے والا خرچ کرنا چاہتا ہے تو وہ کُرتا کشادہ ہو جاتا ہے، یہاں تک کہ اس کے سارے جسم کوچھُپالیتا ہے اور اس کے نشانات کو مٹاتا جاتا ہے، اورجب کنجوس خرچ کرنے کا ارادہ کرتاہے تو وہ کُرتاسُکڑجاتا ہے اور اس کا ہرحلقہ اپنی جگہ سے چِمٹ جاتا ہے، یہاں تک کہ وہ اس کی گردن کو یااس کی ہنسلی کو پکڑ لیتا ہے، بخیل اسے کشادہ کرنے کی کوشش کرتاہے لیکن وہ کشادہ نہیں ہو پاتا۔‘‘","صحیح",{"k":"صحیح بخاری (1443)، صحیح مسلم (1021)۔","f":"مطلب یہ ہے کہ سخی شخص خرچ کرنے سے فرحت محسوس کرتاہے اور اس کادِل فراخ وکشادہ ہو جاتا ہے جبکہ بخیل پہلے ہی مرحلے میں تنگ زِرہ کی طرح اپنے ہاتھوں کو اپنے جسم سے چِمٹا لیتا ہے اور انہیں اپنی جیب تک جانے ہی نہیں دیتا کہِیں وہ اپنا مال کم نہ کر بیٹھے، اس طرح اسے خرچ کرنے کی توفیق ہی نہیں مل پاتی اوریُوں وہ فرحت وکشادگی سے محروم رہتا ہے۔"}],[83,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’بے حیائی سے بچو کیونکہ اللہ تعالٰی بے حیائی کا مظاہرہ کرنے والے اور گالیاں بکنے والے کو پسند نہیں فرماتا، ظلم کرنے سے بھی خود کو بچائے رکھو کیونکہ ظلم روزِقیامت اللہ تعالٰی کے ہاں اندھیرے کا باعث ہوگا اور انتہائی کنجوسی اور بخیلی سے بچو کیونکہ تم سے پہلے لوگوں کو اسی نے اپنے رشتے داروں سے قطع تعلقی پر مجبور کیا اور انہوں نے رشتے ناتے توڑ ڈالے، اسی نے انہیں حرام امور کو حلال کرنے پر اکسایا اور اسی نے انہیں اپنے خون بہانے پر بھڑکایا اور انہوں نے خون بہائے۔‘‘","صحیح",{"k":"مسند أحمد (302)، صحیح ابن حبان (1561)، سلسلہ الأحادیث الصحیحہ (2؍357)۔"}],[84,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’آدمی میں جوبُری خصلتیں ہو سکتی ہیں(وہ یہ ہیں)کہ (ایک تو وہ)کچے دِل والا انتہائی کنجوس ہواور(دوسرا)دِل چھوڑ دینے والا انتہائی بُزدِل ہو۔‘‘","صحیح",{"k":"سنن أبوداؤد (2511)، سلسلہ الأحادیث الصحیحہ (560)۔"}],[85,"ابوہریرہ رضی اللہ عنہ سے ہی مرفوعاًمروی ہے کہ:\n’’ایک بندے کے دِل میں کنجوسی اور ایمان اکٹھے نہیں ہو سکتے۔‘‘","صحیح",{"k":"السنن الکبری للبیهقی (9؍161)، مستدرک حاکم (2؍72)، السنن الکبری للنسائی (4319)، صحیح الجامع للألبانی (7616)۔","f":"گویا کنجوسی ایمان کے منافی امور میں سے ہے، جس دِل میں ایمان ہوگا اس میں کنجوسی نہیں ہو سکتی اورجس میں کنجوسی ہوگی وہ ایمان سے قاصر ہوگا۔"}],[86,"ابوموسیٰ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’ایک مومن دوسرے مومن کے لیے عمارت کے مانند ہے، جس کا ایک حصہ دوسرے حصے کو مضبوط کرتاہے۔ آپ صلی اللہ علیہ وسلم نے یہ فرماتے ہوئے اپنی انگلیوں کے درمیان تشبیک دی۔‘‘","صحیح",{"k":"صحیح بخاری (6026)، صحیح مسلم (2585)۔","f":"فرمانِ باری تعالیٰ ہے: ﴿وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوٰى وَلَا تَعَاوَنُوا عَلَى الْإِثْمِ وَالْعُدْوَانِ﴾ [المائدة: ۲] ’’اور تم نیکی اور پرہیزگاری کے معاملے میں ایک دوسرے سے تعاون کیا کرو، برائی اور زیادتی کے سلسلے میں تعاون مت کیا کرو۔‘‘\nآپ صلی اللہ علیہ وسلم نے تشبیک دے کر یعنی ایک ہاتھ کی انگلیوں کو دوسرے ہاتھ کی انگلیوں میں ڈال کے دونوں ہاتھوں کو آپس میں مضبوطی سے ملا کر فرمایا کہ ایسے ہی ایک مومن دوسرے مومن کے لیے مضبوطی کا باعث ہوتاہے۔"}],[87,"نعمان بن بشیر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’تمام مسلمان(آپس میں) ایک ہی آدمی کے مانند ہیں، جب اس کی آنکھوں کو تکلیف ہوتی ہے تو سارا جسم ہی تکلیف میں مبتلا ہو جاتا ہے اور(اسی طرح)جب اس کا سردرد ہوتا ہے تو سارا جسم ہی درد ہو نے لگتا ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2586)۔"}],[88,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’مومن، مومن کا آئینہ ہے، مومن، مومن کا بھائی ہے، جہاں کہیں بھى وہ اسے ملتا ہے اس کو نقصان سے بچاتا ہے اور اس کی عدم موجودگی میں اس کی عزت کی حفاظت کرتاہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4918)، الأدب المفرد للبخاری (239)، سلسلہ الأحادیث الصحیحہ (926)۔","f":"اس کی عدم موجودگی میں اس کی حفاظت کرنے کا ایک مطلب تو یہ ہے کہ اس کی عدم موجودگی میں اس کی بُرائی بیان نہ کرے، اس کی غیبت اورچُغلی نہ کرے، اس پر تہمت والزام نہ لگائے اور اس کے عیوب بیان نہ کرے، دوسرا مطلب یہ کہ اگر وہ گھر میں موجود نہ ہو تو اس کے گھر والوں کی اور اس کے مال کی حفاظت کرے، اس کی عزت کا محافظ بنے اور اسے رسوا نہ کرے۔"}],[89,"سالم بن عبداللہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’مسلمان مسلمان کا بھائی ہے، وہ نہ تو اس پر ظلم کرتاہے اور نہ ہی اسے تنہا چھوڑتا ہے، اور جو شخص اپنے (مسلمان) بھائی کی ضرورت پوری کرنے میں لگتا ہے اللہ تعالیٰ اس کی ضرورت پوری کرنے میں لگ جاتا ہے، اور جو کسی مسلمان کادُکھ دُورکرتا ہے اللہ تعالیٰ روزِقیامت اس کادُکھ دُورکرےگا اورجس نے کسی مسلمان کے عیب پر پردہ ڈالا اللہ تعالیٰ روزِقیامت اس کے گناہوں پر پردہ ڈالے گا۔‘‘","صحیح",{"k":"صحیح بخاری (2442)، صحیح مسلم (2580)۔"}],[90,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جس نے اپنے(مسلمان)بھائی سے دنیا کی پریشانیوں میں سے کوئی پریشانی دُورکی تو اللہ تعالیٰ اس سے قیامت کے دِن کی پریشانیوں میں سے ایک پریشانی دُورکر دے گا، جس نے کسی مسلمان(کے عیوب)کی پردہ پوشی کی اللہ تعالیٰ دنیا وآخرت میں اس (کے عیوب)پر پردہ ڈالے گا، جس نے کسی مسلمان کے لیے آسانی پیدا کی اللہ تعالیٰ اس کے لیے دنیا وآخرت میں آسانیاں پیدا کر دے گا، اللہ تعالیٰ تب تک بندے کی مدد میں رہتا ہے جب تک بندہ اپنے(مسلمان)بھائی کی مدد میں رہتا ہے، جو شخص حصولِ علم کی نیّت سے گھر سے نکلے اللہ تعالیٰ اس کی (اس نیکی)وجہ سے جنّت کا راستہ اس کے لیے آسان کر دیتا ہے، جو لوگ اللہ تعالیٰ کی مساجد میں سے کسی بھی مسجد میں فقط کتاب اللہ کی تلاوت اور اسے مل کر پڑھنے اور سمجھنے کے لیے بیٹھتے ہیں فرشتے انہیں گھیر لیتے ہیں، رحمت ان پہ سایہ فگن ہوجاتی ہے اور اللہ تعالیٰ ان لوگوں کا ذکر اپنے پاس موجود افراد کے پاس کرتاہے اور جسے اس کے عمل نے پیچھے چھوڑ دیا اسے اس کا نسب آگے نہیں بڑھا سکتا۔‘‘","صحیح",{"k":"صحیح مسلم (2699)۔","f":"حدیث میں بیان آخری بات کا مطلب یہ ہے کہ آخرت میں صرف اور صرف نیک اعمال ہی کام آئیں گے۔ اگر کسی کے پاس اعمال نہ ہوئے تو وہ حسب ونسب کے لحاظ سے خواہ کتنا ہی عظیم کیوں نہ ہو، اس کی نجات کا ذریعہ نہیں بن پائے گا۔ وہاں صرف نیک اعمال یااللہ کی رحمت ہی بچا پائے گی۔ اگر نسب کی وجہ سے رعایت ہوتی تو نبی صلی اللہ علیہ وسلم اپنی پیاری صاحبزادی سیدہ فاطمہؓ سے یہ نہ فرماتے کہ نیک اعمال کرلو، کیونکہ روزِقیامت میں تمہارے کسی کام نہیں آسکوں گا۔"}],[91,"ابو مسعود انصاری رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم کے پاس ایک آدمی آیا اور اس نے عرض کیا:اے پیغمبرِخدا!میری سواری ہلاک ہوگئی ہے مجھے کوئی سواری عنایت کر دیجیے۔ تو آپ صلی اللہ علیہ وسلم نے فرمایا:میرے پاس تو کوئی سواری نہیں ہے جو میں تجھے دوں، لیکن فلاں شخص کے پاس جا(وہ تجھے دیدے گا۔) چنانچہ وہ آدمی اس کے پاس گیا تو اس نے اسے سواری دے دی، وہ(دوبارہ)رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور آپ صلی اللہ علیہ وسلم کو اس کا بتلایا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:جس نے بھلائی کے کام پر کسی کی راہنمائی کی تو اسے بھى بھلائی کرنے والے کے اجروثواب جتنا اجر ملے گا۔‘‘","صحیح",{"k":"صحیح مسلم (1893)، سنن أبوداؤد (5129)، سنن ترمذی (2671)۔","f":"یعنی نیکی اور بھلائی کا کام کرنے والے کو تو اجروثواب ملنا ہی ہے، لیکن جو شخص اسے نیکی کی راہ دکھاتا ہے اسے بھی نیکی کرنے والے کے مثل اجروثواب ملتا ہے۔ گویا نیک کام کی راہنمائی کرنا خود نیکی کرنے کے مترادف ہے۔"}],[92,"ابوموسیٰ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’ہرمسلمان پر صدقہ کرنا لازم ہے۔ صحابہؓ نے عرض کیا:اگر اس کے پاس کچھ نہ ہوتو؟ آپ صلی اللہ علیہ وسلم نے فرمایا:پھر وہ اپنے ہاتھ سے کچھ کما کر خود بھی فائدہ اٹھائے اور صدقہ بھی کردے۔ صحابہؓ نے پوچھا:اگر وہ اس کی بھی استطاعت نہ رکھے، یاوہ ایسا نہ کرے تو؟ آپ صلی اللہ علیہ وسلم نے فرمایا:پھر وہ(لوگوں کو)بھلائی اور نیکی کی ترغیب دے۔ صحابہؓ نے کہا:اگر وہ یہ بھی نہ کرے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:پھر وہ (لوگوں کو)برائی سے روکے، یقیناًیہ بھی اس کے لیے صدقہ ہے۔‘‘","صحیح",{"k":"صحیح بخاری (1445)، صحیح مسلم (1008)۔","f":"معلوم ہوا کہ ہرمسلمان صدقہ کرنے کا اہل ہوتاہے، لازمی نہیں کہ وہ مالی صدقہ ہی کرے بلکہ اس حدیث کے مطابق لوگوں کو نیکی کے کاموں کی ترغیب دینا اور برائی کے کاموں سے منع کرنا بھی صدقہ ہی ہے۔"}],[93,"حذیفہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’ہرنيك کام صدقہ ہے۔‘‘","صحیح",{"k":"صحیح مسلم (4947)۔","f":"یعنی خير وبھلائى اور نيكى كاہر وہ کام جو اللہ کی رضا اور لوگوں کے فائدے کا باعث بنے وہ صدقہ ہے، اس میں تعبدی امور کے علاوہ اخلاقیات اور معاشرت کے تمام امور شامل ہیں۔"}],[94,"ابو سلام بیان کرتے ہیں کہ ابوذر رضی اللہ عنہ نے فرمایا:\n’’ہربندے پر روزانہ صدقہ کرنا لازم ہے، ابوذرؓکہتے ہیں کہ میں نے عرض کیا:اے اللہ کے رسول!ہمارے پاس تو مال ودولت ہی نہیں ہے ہم کہاں سے صدقہ کریں؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:یہ امور بھی صدقے کی قبیل سے ہی ہیں(کہ تُویہ پڑھے:)سبحان الله، الحمد لله، لاالٰه الا الله، الله أکبر اور، نیکی کرنے کا حكم دے اور برائی سے منع کرے، لوگوں کی گزر گاہ سے کانٹے، ہڈی اور پتھر کو ہٹا دے، نابینے کو راستہ دکھائے اور گونگے بہرے کو بات سمجھائے، کسی کام میں راہنمائى کے طلبگار کی اچھی طرح سے راہنمائی کرے(کہ کسی اور سے پوچھنے کی اس کو ضرورت نہ رہے)، اپنی کاوشوں کو مہمان کے لیے خاص کرے اور داد رسی کے لیے فریاد کرنے والے سے تعاون کرے، یہ تمام امور تیری جان پر صدقے کے ہی قبیل سے ہیں، (یہاں تک کہ)اپنی بیوی سے ہمبستری کرنے میں بھی تجھے ثواب ملے گا۔ ابوذرؓنے عرض کیا:اپنی شہوت کی تکمیل کرنے میں ہمیں کیسے ثواب مل سکتا ہے؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:تمہارا کیا خیال ہے کہ اگر تمہارا بچہ ہو، وہ تجھے مل جائے اورتُواس سے ثواب کی امید بھی رکھتا ہو، پھر وہ فوت ہوجائے تو کیاتُواس سے اجر کی امید رکھے گا؟ انہوں نے جواب دیا:جی ہاں، تو آپ صلی اللہ علیہ وسلم نے فرمایا:کیاتُونے اسے پیدا کیا تھا؟ ابوذرؓکہتے ہیں کہ میں نے کہا:(نہیں)بلکہ اللہ تعالٰی نے اسے پیدا فرمایا تھا، آپ صلی اللہ علیہ وسلم نے پوچھا:کیاتُونے اسے ہدایت دی تھی؟ انہوں نے جواب دیا:(نہیں)بلکہ اللہ تعالٰی نے ہی اسے ہدایت دی تھی، آپ صلی اللہ علیہ وسلم نے فرمایا:کیا اسے رزق تُودیا کرتا تھا؟ انہوں نے عرض کیا:(نہیں)بلکہ اللہ تعالٰی ہی اسے رزق دیا کرتا تھا، تو آپ صلی اللہ علیہ وسلم نے فرمایا:اسی طرح وہ اس بچے کو اس کے حلال مقام پہ رکھتا ہے اور اسے حرام سے بچاتا ہے، سواگر اللہ تعالٰی چاہے تو اسے زندہ رکھے اور اگر چاہے تو اسے موت دیدے، لیکن تمہیں اس کا اجر ملے گا۔‘‘","صحیح",{"k":"مسند أحمد (5؍168)، سلسلہ الأحادیث الصحیحہ (575)۔"}],[95,"انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’اپنے(مسلمان)بھائی کی مدد کر، خواہ وہ ظالم ہویا مظلوم۔ صحابہؓ نے عرض کیا:اے اللہ کے رسول!بندہ کسی مظلوم کی مدد تو کر سکتا ہے، لیکن وہ ظالم کی مدد کیسے کرے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:(اس کی مدد یہ ہے کہ)تُواسے ظلم کرنے سے روکے۔‘‘","صحیح",{"k":"صحیح بخاری (2444)، سنن ترمذی (2255)۔","f":"يعنى اگر اسے ظلم كرنے سے روكے تويہ برائى سے منع كرنے كى وجہ سے نیکی کے کام میں تعاون ہوگا۔"}],[96,"انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’اگر اہلِ مدینہ میں سے ایک لونڈی بھی رسول اللہ صلی اللہ علیہ وسلم کا ہاتھ پکڑ لیا کرتی تو آپ صلی اللہ علیہ وسلم اس کی ضرورت پوری کرنے کے لیے اس کے ساتھ بھی چل دیا کرتے تھے۔‘‘","صحیح",{"k":"صحیح (6072)، سنن ابن ماجه (4177)۔","f":"نبی صلی اللہ علیہ وسلم اس معاملے میں چنداں عار نہیں سمجھتے تھے کہ وہ ایک لونڈی کا کہا کیوں مانیں یااس کی ضرورت پوری کرنے کے لیے زحمت کیوں کریں، بلکہ آپ صلی اللہ علیہ وسلم تو یکسانیت کے درس کا عملی نمونہ پیش کرتے تھے، یہی وجہ ہے کہ آپ صلی اللہ علیہ وسلم آزا دو غلام ميں كوئى فرق نہ كرتے تھے اورسب كوايك ہی درجہ دیتے اور ایک ہی نظر سے ديكھتے تھے، یہاں تک کہ اگر ایک لونڈی بھی آپ صلی اللہ علیہ وسلم سے اپنی کوئی حاجت بیان کر دیتی تو آپ صلی اللہ علیہ وسلم اس کی ضرورت پوری کرنے کے لیے بھی اس کے ساتھ چل پڑتے تھے۔"}],[97,"عبداللہ بن ابی اوفیٰ رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کی اس خصلتِ مدیحہ کا ذکر فرماتے ہیں کہ:\n’’آپ صلی اللہ علیہ وسلم بیواؤں اور مساکین کے ساتھ جا کر ان کی ضرورت پوری کرنے کو ناپسند نہیں فرماتے تھے۔‘‘","صحیح",{"k":"سنن نسائی، کتاب الجمعہ، باب مایستحب من تقصیرالخطبہ، ح:-1414مستدرک حاکم (2؍614)، صحیح الجامع للألبانی (5005)۔"}],[98,"ابوموسیٰ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم کے پاس جب کوئی مانگنے والا آتا تو آپ صلی اللہ علیہ وسلم فرماتے: سفارش کر دیا کرو، تاکہ تمہیں اجر سے نوازا جائے، اور اللہ تعالیٰ اپنے نبی کی زبان پر وہی فیصلہ کرتے ہیں جو وہ چاہتا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (1432)، صحیح مسلم (2627)۔","f":"اللہ تعالیٰ فرماتا ہے: ﴿مَنْ يَشْفَعْ شَفَاعَةً حَسَنَةً يَكُنْ لَهُ نَصِيبٌ مِنْهَا﴾ [النساء: ۸۵] ’’جو شخص کسی نیکی یابھلے کام کی سفارش کرے، تو اسے بھی اس کا حصہ ملے گا۔‘‘\nیعنی ہونا تو وہی ہے جو اللہ تعالیٰ کا فیصلہ ہوتاہے مگر سفارش کردینے سے سفارش کرنے والا اجروثواب کا حقداربن جاتا ہے۔"}],[99,"ابوہریرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’ہراس دِن میں کہ جس میں سورج طلوع ہوتاہے(یعنی روزانہ)انسان کے ہرجوڑ پر صدقہ لازم ہے، پھر اگر وہ دو لوگوں کے درمیان انصاف کردے تو یہ بھی صدقہ ہے، کسی کی سواری کے معاملے میں مدد کر دے، وہ اس طرح کہ اسے اس پر سوار کرا دے یااس کا سامان اٹھا کر اس پہ رکھ دے تو یہ بھی صدقہ ہے، اچھی بات کہنا بھی صدقہ ہے، ہروہ قدم جو نماز کے لیے اٹھتا ہے صدقہ ہے اور راستے سے جو وہ تکلیف دہ چیز ہٹا دیتا ہے تو یہ بھی صدقہ ہے۔‘‘","صحیح",{"k":"صحیح بخاری (2989)، صحیح مسلم (1009)۔","f":"اللہ تعالیٰ فرماتا ہے: ﴿لَا خَيْرَ فِي كَثِيرٍ مِنْ نَجْوَاهُمْ إِلَّا مَنْ أَمَرَ بِصَدَقَةٍ أَوْ مَعْرُوفٍ أَوْ إِصْلَاحٍ بَيْنَ النَّاسِ﴾ [النساء: ۱۱۴] ’’ان کی اکثر خفیہ سرگوشیوں میں کوئی خیر نہیں ہوتی، ہاں!بھلائی اس کے مشورے میں ہے جو خیرات کی، یانیک کام کی، یالو گوں میں صلح کرانے کی بات کرے۔‘‘ اسی طرح فرمایا: ﴿إِنَّمَا الْمُؤْمِنُونَ إِخْوَةٌ فَأَصْلِحُوا بَيْنَ أَخَوَيْكُمْ﴾ [الحجرات: ۱۰] ’’یقیناًتمام اہلِ ایمان آپس میں بھائی بھائی ہیں، سوتم(ناراضگی کی صورت میں)اپنے بھائیوں میں صلح کرا دیا کرو۔‘‘\nاس حدیث میں بھی صدقے کی مختلف صورتیں بیان ہوئی ہیں، ان میں سے ایک صورت دو لوگوں کے درمیان انصاف کرنا ہے، یہاں انصاف سے مراد یہ ہے کہ اگر دو مسلمان بھائی آپس میں ناراض اور قطع تعلق ہوں دونوں کے پاس الگ الگ جا کر دوسرے کی تعریف کی جائے اور اس کے محاسن بیان کیے جائیں، اور اس کے متعلق اس دوسرے بھائی کی محبت اور چاہت بیان کی جائے، تاکہ اس کادِل نرم پڑجائے اور وہ صلح کے لیے تیار ہو جائے۔ انصاف کرے، یعنی اچھائیاں ہی بیان کرے، ایسا نہ ہوکہ دوسرے کی کوئی ایسی برائی ذکر کر دے جس سے ان کی رنجش ختم ہونے کی بہ جائے اور بھی بڑھ جائے۔ علاوہ ازیں انصاف یہاں اپنے حقیقی معنی میں بھی مراد لیا جا سکتا ہے کہ اگر دو مسلمان بھائیوں کا کسی معاملے میں تنازعہ ہو گیا ہے تو ان دونوں میں انصاف کرتے ہوئے جس کی زیادتی ہوا سے سمجھانا بجھانا چاہیے اور صاحبِ حق کو اس کاحق دِلاکر ان دونوں میں صلح کرا دینی چاہیے۔ اس کے علاوہ اس روایت میں صدقے کی اور بھی صورتیں بیان كى گئی ہیں، گویا یہ حدیث اس گزشتہ حدیث کی ہی تشریح ہے جس میں نبی مکرم صلی اللہ علیہ وسلم کا یہ ارشادِگرامی مذکور ہے کہ ہرنيك کام صدقہ ہے۔"}],[100,"ابوالدرداء رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’کیا میں تمہیں نماز، روزے اور صدقے سے بھی افضل درجے کا عمل نہ بتلاؤں؟ صحابہؓ نے عرض کیا:کیوں نہیں(ضرور بتلائیے)، تو آپ صلی اللہ علیہ وسلم نے فرمایا:آپس میں صلح صفائی رکھنا(ان تمام سے افضل ہے۔) کیونکہ آپس کی بدسلوکی تودِین کومُونڈ کر رکھ دینے والی بات ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4919)، سنن ترمذی (2509)، مسند أحمد (6؍444)۔","f":"یعنی بدسلوکی دِین کا نام ونشان ہی ختم کر دیتی ہے، اس کی وجہ یہ ہے کہ اس کے باعث انسان بہت سی دیگر اخلاقی گرا وٹوں کا شکار ہو جاتا ہے، مثال کے طور پرجب وہ اپنے مسلمان بھائی سے صلح رکھنے کی بجائے اس سے بدسلوکی رکھے گاتو اس سے بول چال بھی ختم کردے گا، اس کے متعلق دِل میں حسد، بغض، کینہ اور نفرت پیدا کر لے گا، اس کے بارے میں اتہام والزام کا مرتکب ہوگا، اس کی غیبت اورچُغلی کرنے لگے گا، غرضیکہ ہروہ کام کرنے پراُترآئے گاجس سے دوسرے مسلمان بھائی کی تذلیل ہو سکے۔ تو گویا بدسلوکی بہت سی برائیوں کا باعث بنتى ہے اسی لیے اسے دِین کومُونڈ کر رکھ دینے والابُراعمل قرار دیا گیا ہے۔"}],[101,"اُمِ کلثوم بنت عقبہ رضی اللہ عنہا بیان کرتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’وہ شخص جھوٹا نہیں ہے جو لوگوں میں صلح کرائے(اور اس غرض سے)وہ اچھی بات کہہ بھی دیتا ہے اور کوئی اچھی بات چھپا بھی لیتا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (2692)، صحیح مسلم (2605)۔"}],[102,"اُمِ کلثوم بنت عقبہ رضی اللہ عنہا بیان کرتی ہیں کہ:\n’’میں نے رسول اللہ صلی اللہ علیہ وسلم کو تین خلافِ حقیقت باتوں کے سوا کسی بات کو بیان کرنے میں رُخصت دیتے نہیں سنا، آپ صلی اللہ علیہ وسلم فرمایا کرتے تھے کہ میں اس شخص کو جھوٹا شمار نہیں کرتا جو لوگوں کے مابین صلح کرواتا ہے اور وہ کوئی(جھُوٹی)بات کہہ دیتا ہے جس سے اس کا ارادہ فقط اصلاح كاہوتا ہے، اور(دوسرا)وہ آدمی جو دور انِ جنگ کوئی (جھوٹی)بات کہتا ہے اور(تیسرا)وہ شخص جو اپنی بیوی سے کوئی(خلافِ حقیقت)بات بیان کرے اور بیوی اپنے خاوند سے ایسی کوئی بات بیان کرے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4921)۔","f":"اس حدیث میں تین امور میں جھوٹ بولنے کی رخصت دی گئی ہے بلکہ نبی صلی اللہ علیہ وسلم کے فرمان کے مطابق درحقیقت یہ جھوٹ نہیں ہیں:(۱)وہ شخص جو دو ناراض مسلمان بھائیوں میں صلح کراتا ہے اور ان کی ناراضگی دُورکرنے کے لیے ایک کے پاس دوسرے بھائی کے اس بارے ميں اچھے خیالات اور تعریفی کلمات اپنی طرف سے ہی بنا کر بیان کر دیتا ہے كہ وہ تو تمہیں بہت اچھا سمجھتا ہے، تمہاری بہت تعریف کرتاہے، تمہارے بارے ميں اس كے خيالات لڑائى كے باوجود بھى بہت اچھے ہیں، اس نے تمہاری یہ تعریف کی، وہ تعریف کی، وغیرہ وغیرہ۔ تاکہ وہ اپنے بارے میں دوسرے بھائی کے اچھے تأثرات دیکھ کر اپنی ناراضگی ختم کردے۔ (۲)دورانِ جنگ دشمن کو شکست دینے کے لیے کوئی جھوٹی بات کہہ کر یاغلط افواہ اُڑا کر اسے دھوکہ دینا۔ (۳)خاوند اور بیوی ایک دوسرے کو خوش کرنے کے لیے اگر کچھ خلافِ حقیقت بات کہہ دیں تو وہ بھی جھوٹ میں شمار نہیں ہوگا۔"}],[103,"جابربن عبداللہ رضی اللہ عنہ سے مروی ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’جب انسان کوئی بات کر رہا ہو اورجس شخص کے پاس وہ بات کر رہا ہو وہ اسے اِدھراُدھر دیکھتا پائے تو وہ بات امانت ہوتی ہے۔‘‘","حسن",{"k":"سنن أبوداؤد (4868)، سنن ترمذی (3896)، مسند أحمد (3؍352)، سلسلہ الأحادیث الصحیحہ (1090)۔","f":"یعنی جب ایک شخص دوسرے سے کوئی بات کرتے ہوئے اپنے اِردگردديكھتا رہتا ہے كہ کہیں كوئى سُن ہی نہ لے، تو دوسرے شخص کو سمجھ جانا چاہیے یہ اس کی راز کی بات ہے جو وہ اس کے پاس بہ طورِامانت بیان کر رہا ہے، لہٰذا اسے چاہیے کہ وہ بات کرنے والے کی وضاحت کے بغیر ہی اس بات کو امانت سمجھے اور کسی کے پاس بیان نہ کرے۔"}],[104,"ہمام بیان کرتے ہیں کہ:\n’’میں حذیفہ رضی اللہ عنہ کے پاس بیٹھا ہوا تھا کہ ایک آدمی گزرا، لوگوں نے کہاکہ یہ آدمی بادشاہ کو باتیں پہنچاتا ہے۔ تو حذیفہ رضی اللہ عنہ کہنے لگے کہ رسول اللہ صلی اللہ علیہ وسلم کا فرمان ہے:چُغل خورجنّت میں نہیں جائے گا۔‘‘","صحیح",{"k":"صحیح بخاری (6056)، صحیح مسلم (105)۔"}],[105,"ابنِ عباس رضی اللہ عنہما نبی صلی اللہ علیہ وسلم سے ان دو لوگوں کے بابت روایت کرتے ہیں جنہیں ان کی قبروں میں عذاب دیا جا رہا تھا، کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’ان میں سے ایک چُغلی کیا کرتا تھا۔‘‘","صحیح",{"k":"صحیح بخاری (216)، سنن أبوداؤد (20)، سنن ترمذی (70)، سنن نسائی (31)۔"}],[106,"عبادہ بن صامت رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے بيعت كاذكركرتے ہوئے بيان کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’اور ہم میں سے کوئی بھی کسی دوسرے پر قبیح الزام نہیں تھو نپے گا۔‘‘","صحیح",{"k":"صحیح مسلم (1709)، مسند أحمد (5؍313)۔"}],[107,"ابنِ مسعود رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’کیا میں تمہیں بتلاؤں نہ کہ قبیح الزام کیا ہے؟ وہ چُغل خوری ہے، جو لوگوں میں دشمنی ڈال دیتی ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2606)، مسند أحمد (1؍437)۔"}],[108,"سیدنا انس رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے چُغل خوری کی تفسیر کے بابت روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’لوگوں میں سے ایک کی بات سُن کر دوسرے کو بتلانا، تاکہ ان میں بدسلوکی پیدا ہو جائے۔‘‘","صحیح",{"k":"صحیح مسلم (2606)، مسند أحمد (1؍437)۔"}],[109,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’روزِقیامت تُولو گوں میں سے بُراشخص اسے پائے گاجو دورُخا(يعنى دو غلا)ہوگا، جواِن کے پاس آکر کچھ اور بات کرتا تھا اوراُن کے پاس جا کر کچھ اور کہتا تھا۔‘‘","صحیح",{"k":"صحیح بخاری (6058)، صحیح مسلم (2526)۔","f":"مذکورہ بالا تمام تراحادیث چُغل خوری کی مذمت میں بیان ہوئی ہیں، چُغل خوری کی تعریف خود نبی کریم صلی اللہ علیہ وسلم نے فرما دی ہے کہ صرف فتنہ وفساد ڈالنے کی غرض سے ایک شخص کی بات سُن کر دوسرے کو جا كربتلاناچُغل خوری کہلاتا ہے اور اس قبیح خصلت کے حاملین کا انجام آپ پڑھ چکے ہیں۔"}],[110,"انس رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’تم میں سے کوئی بھی تب تک مومن نہیں ہو سکتاجب تک وہ اپنے(مسلمان)بھائی کے لیے وہی کچھ پسند نہ کرنے لگے جو وہ اپنے لیے پسند کرتا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (13)، صحیح مسلم (45)۔","f":"کمالِ ایمان سے متصف ہونے کے لیے ضروری ہے کہ اپنے مسلمان بھائی کے لیے بھی وہی کچھ پسند کیا جائے جو بندہ اپنے لیے کرتاہے، اس کے بارے میں بہت سی احادیث وارد ہوئی ہیں جن میں سے چند ایک یہ ہیں:"}],[111,"عبداللہ بن عمرو رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جو شخص یہ پسند کرے کہ اسے جہنم سے بچا لیا جائے اورجنّت کا داخلہ نصیب کر دیا جائے تو اسے اس حالت میں موت آنی چاہیے کہ وہ اللہ تعالیٰ اور روزِقیامت پر ایمان رکھتا ہو، اور وہ لوگوں کو بھی وہی کچھ دینا پسند کرتا ہو جو وہ اپنے لیے دیا جا ناپسند کرتا ہے۔‘‘","صحیح",{"k":"صحیح مسلم (1844)، مسند أحمد (2؍192)۔"}],[112,"شعبہ بیان کرتے ہیں کہ:\n’’میں ایک آدمی کے پاس پہنچا جو لوگوں کو حدیثیں بیان کر رہا تھا، میں (بھی وہاں)بیٹھ گیا، اس نے کہا:میں منٰی میں تھا اور عرفات کو جا نے کا ارادہ کر رہا تھا، تو میں (آپ صلی اللہ علیہ وسلم کے)قریب ہو گیا اور(آپ صلی اللہ علیہ وسلم کی سواری کی)لگام پکڑ لی اور عرض کیا:اے اللہ کے رسول!مجھے کوئی ایسا عمل بیان کیجیے جو مجھے جنّت کے قریب کردے اور جہنّم سے دُورکر دے، آپ صلی اللہ علیہ وسلم نے فرمایا:نماز قائم کیا کر، زکاۃ کی ادائیگی کیا کر، بیت اللہ کاحج کر، ماہِ رمضان کے روزے رکھا کر، لوگوں کے لیے وہی کچھ پسند کر جو اپنے لیے پسند کرتا ہے اور وہی کچھ ان کے لیے ناپسند کر جو اپنے لیے ناپسند کرتا ہے، چلواب سواری کے سامنے سے ہٹ جاؤ۔‘‘","صحیح",{"k":"مسند أحمد (5؍372)، سلسلہ الأحادیث الصحیحہ (1477)۔"}],[113,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’یقیناًلوگوں میں سے بدترین شخص وہ ہے جو دورُخا(یعنی دو غلا)ہے، وہ اِن کے پاس ایک رُخ لے کے آتا ہے اوراُن کے پاس اپنا دو سرارُخ دِکھاتا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (6058)، صحیح مسلم (2526)۔","f":"بغیر تصدیق وتحقیق کے کسی کے بارے میں اپنی طرف سے ہی یاسُن سنا کر کوئی منفی رائے قائم کر لینا بدگمانی اور لوگوں سے چھُپ کر یاان کی لاعلمی میں ان کی ایسی باتیں سننا کہ جن کا کسی اور کو پتہ چل جانا انہیں پسند نہ ہو، جاسوسی کہلاتا ہے۔\nاللہ تعالیٰ فرماتا ہے: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا اجْتَنِبُوا كَثِيرًا مِنَ الظَّنِّ إِنَّ بَعْضَ الظَّنِّ إِثْمٌ وَلَا تَجَسَّسُوا﴾ [الحجرات: ۱۲] ’’اے ایمان والو!بہت زیادہ گمان کرنے سے بچو، کیونکہ بعض گمان گناہ ہوتے ہیں، اور تم جاسوسی بھی مت کیا کرو۔‘‘"}],[114,"اور رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’گمان کرنے سے بچو، کیونکہ گمان سب سے جھوٹی بات ہے، اور جاسوسی مت کرو، ٹوہ مت لگاؤ، ایک دوسرے کو نیچا دکھا نے کی کوشش مت کرو، ایک دوسرے سے حسدمت کرو، باہم بُغض مت رکھو اور اے اللہ کے بندو!آپس میں بھائی بھائی بن جاؤ۔‘‘","صحیح",{"k":"صحیح بخاری (6066)، صحیح مسلم (2563)۔"}],[115,"اور نبی صلی اللہ علیہ وسلم کا فرمان ہے:\n’’ایک دوسرے سے حسدمت کرو۔‘‘","صحیح",{"k":"صحیح بخاری (6064)، صحیح مسلم (2558)، سنن أبوداؤد (4910)، سنن ترمذی (1935)، سنن ابن ماجه (3849)۔","f":"کسی شخص کی کوئی خوبی، اچھائی، کامیابی، خوشحالی، مال ودولت یاعلم ومنصب میں برتری دیکھ کر کسی دوسرے شخص کے نفس میں ایسی جلن(Jealousy)پیدا ہوتی ہے جس سے وہ یہ خواہش کرنے لگتا ہے کہ وہ نعمت اس سے زائل ہو کر اسے مل جائے، اسے حسد سے تعبیر کیا جاتا ہے۔\nاللہ جلّ شانہ کا فرمان ہے: ﴿وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ﴾ [الفلق: ۵] ’’(اے پیغمبر!آپ صلی اللہ علیہ وسلم کہہ دیجیے)میں حاسد کے شرسے(پناہ مانگتا ہوں)جب وہ حسد کرے۔"}],[116,"زبیربن عوام رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’تم میں پہلی اُمتوں کی بیماری یعنی حسد اور بغض سرایت کر جائيں گے، یہ (دونوں)مُونڈ کے رکھ دینے والے ہیں، میری مراد یہ نہیں کہ یہ بال مُونڈ دیتے ہیں بلکہ یہ دِین کومُونڈ کے رکھ دیتے ہیں۔ اس ذات کی قسم جس کے ہاتھ میں میری جان ہے!تم تب تک جنّت میں نہیں جا سکتے جب تک کہ ایمان والے نہ بن جاؤ، اورتب تک ایمان والے نہیں بن سکتے جب تک کہ آپس میں محبت نہ کرنے لگو، کیا میں تمہیں ایسا عمل نہ بتلاؤں جو تمہیں محبت میں پُختہ کردے؟ آپس میں سلام پھیلاؤ۔‘‘","حسن",{"k":"سنن ترمذی (2510)، مسند أحمد (1؍156)، الإرواء (3؍238)۔","f":"يعنى ايك دوسرے كوكثرت سے سلام كہنا محبت كى پختگى كاسبب ہے اور حسدو بغض كى بيمارى سے سلامت رہنے کا بہترین ذريعہ ہے۔"}],[117,"ابوبرزہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’اے وہ لوگو کہ جو اپنی زبان سے تو ایمان قبول کر چکے ہو مگردِلوں میں ابھی جاگزیں نہیں ہوا!تم مسلمان بھائیوں کی غیبت مت کرو اور نہ ہی ان کے مخفی عیوب ٹٹولنے لگو، کیونکہ جو اپنے بھائی کے عیب ٹٹولنے لگے گاا للہ تعالیٰ اس کے عیب ٹٹولنے لگ جائے گا، اور اللہ جس کے عیوب ٹٹولنے لگ پڑے تو اسے گھر کے اندر بھی رُسوا کر کے چھوڑتا ہے۔‘‘","حسن",{"k":"سنن أبوداؤد (4880)۔","f":"االلہ عزّوجلّ فرماتا ہے: ﴿وَلَا يَغْتَبْ بَعْضُكُمْ بَعْضًا أَيُحِبُّ أَحَدُكُمْ أَنْ يَأْكُلَ لَحْمَ أَخِيهِ مَيْتًا فَكَرِهْتُمُوهُ﴾ [الحجرات: ۱۲] ’’تم میں سے کوئی کسی کی غیبت نہ کرے، کیا تم میں سے کوئی بھی اپنے مُردہ بھائی کا گوشت کھانا پسند کرتا ہے؟ اسے تو تم ناپسند کرتے ہو۔‘‘"}],[118,"انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب میرارب مجھے معراج پر لے گیا تو میرا گزر ایسے لوگوں کے پاس سے ہو اجن کے ناخن تانبے کے تھے اور وہ ان سے اپنے چہروں اورسِینوں کو نوچ رہے تھے، میں نے پوچھا:اے جبرائیل!یہ کون لوگ ہیں؟ تو انہوں نے جواب دیا:یہ وہ لوگ ہیں جو لوگوں کا گوشت کھاتے تھے اور ان کی عزتیں اچھالتے تھے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4878)، مسند أحمد (3؍224)۔"}],[119,"غیبت کہتے کس کو ہیں؟ اس کی وضاحت خود نبی کریم صلی اللہ علیہ وسلم نے فرمائی ہے، جیسا کہ ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’کیا تم جانتے ہوکہ غیبت کیا ہے؟ صحابہؓ نے عرض کیا:اللہ اور اس کا رسول ہی بہتر جانتے ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا:تم اپنے (مسلمان)بھائی کے متعلق ایسی بات بیان کرو کہ جسے وہ ناپسند کرتا ہو۔ پوچھا گیا کہ اگر وہ بات جو میں کہہ رہا ہوں اس میں پائی جاتی ہو تو اس کے بارے میں آپ صلی اللہ علیہ وسلم کا کیا خیال ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:اگر وہ بات جو تم کہتے ہو وہ اس میں پائی جاتی ہو تو تم نے اس کی غیبت کی ہے، اور اگر تمہاری کہی ہوئی بات اس میں میں موجود نہ ہو تو تم نے اس پر بہتان باندھا ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2589)، سنن أبوداؤد (4874)، سنن ترمذی (1934)۔","f":"یعنی غیبت کہتے ہی اس عیب کے بیان کرنے کو ہیں جو اس شخص میں پایا جاتا ہوجس کی غیبت کی جا رہی ہے، اور اگر وہ عیب اس میں پایا ہی نہ جاتا ہو تو پھر یہ بہتان ہوگا، جو غیبت سے بھی بڑا گناہ ہے۔"}],[120,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’ایک دوسرے سے حسدمت کرو، باہم بُغض مت رکھو، ایک دوسرے پر بڑھا چڑھا کر بولی مت لگاؤ، ایک دوسرے سے منہ نہ موڑو اور تم میں سے کوئی بھی کسی دوسرے کے سودے پر اپنا سودا نہ کرے، اے اللہ کے بندو!بھائی بھائی بن جاؤ(کیونکہ)مسلمان مسلمان کا بھائی ہوتاہے، نہ اس پر ظلم کرتاہے، نہ اسے رُسوا کرتا ہے اور نہ اسے نِیچادِکھاتا ہے۔ تقوٰی یہاں ہے(آپ صلی اللہ علیہ وسلم نے یہ)اپنے سینے کی طرف تین مرتبہ اشارہ کرتے ہوئے(فرمایا)۔ آدمی کے بُراہو نے کے لیے یہی کافی ہے کہ وہ اپنے مسلمان بھائی کو حقیر جا نے، ہرمسلمان پر دوسرے مسلمان کا خون، مال اورعزّت حرام ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2564)۔"}],[121,"اسامہ بن شریک رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’میں بھی اس وقت بدوی لوگوں کے پاس موجود تھاجب وہ نبی صلی اللہ علیہ وسلم سے سوال کررہے تھے کہ کیا فلاں کام کرنے میں ہم پر گناہ ہے؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:اے اللہ کے بندو!گناہ کواُٹھا لیا گیا ہے سوائے اس شخص کے جس نے اپنے مسلمان بھائی کی عزت سے ایک حصہ کاٹ لیا تو یہ وہ شخص ہے جس نے گناہ کا ارتکاب کیا۔ پھر انہوں نے پوچھا:اے اللہ کے رسول!بندے کو جو(اللہ کی طرف سے)بہترین چیز عطا کی گئی ہے، وہ کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:اچھا اخلاق۔‘‘","صحیح",{"k":"سنن ابن ماجه (3436)، مسند أحمد (4؍278)، سلسلہ الأحادیث الصحیحہ (433)۔","f":"عزت اچھالنے یاعزت کا ایک حصہ کاٹ لینے سے مراد یہ ہے کہ دوسرے مسلمان کے بارے میں کوئی ایسی بات کرنا یاکسی ایسے عمل کا مظاہرہ کرناجس سے اس کی عزت پر آنچ آتى ہو، خواہ اس کا کوئی جسمانی عیب بیان کیا جائے، اخلاقی خصلت ذکر کی جائے یااس کے گھر کی عزت کو داغدار کرنے کی مذموم کوشش کی جائے، غرضیکہ قولی وفعلی کسی طور پر بھی اسے تضحیک کا نشانہ بنانا اس کی عزت اچھا لنا ہے اور ایک مومن کے لائقِ مقام نہیں ہے کہ وہ ایسی گھناؤنی حرکت کرے۔"}],[122,"عبداللہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’مسلمان کو گالی دینا گناہ اور اس سے لڑائی کرنا کفر ہے۔‘‘","صحیح",{"k":"صحیح بخاری (48)، صحیح مسلم (64)۔"}],[123,"ابوذر رضی اللہ عنہ روایت کرتے ہیں کہ انہوں نے نبی صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’کوئی شخص کسی دوسرے شخص پر فاسق یاکافر ہو نے کا الزام نہ لگائے، کیونکہ اگر اس کا ساتھی(جسے اس نے یہ کہا ہو)ایسا نہ ہوا تو اس الزام کا مورَدوہ خود ہی ٹھہرے گا۔‘‘","صحیح",{"k":"صحیح بخاری (6045)، مسند أحمد (5؍181)۔","f":"یعنی اگر اس کے الزام کے مطابق وہ شخص کسی ایسے گناہ کا مرتکب ہوکہ جس سے کفر یافسق لازم آتا ہوتب تو اس کی یعنی الزام لگانے والے کی معافی کی گنجائش ہے لیکن اگر اس میں ایسی کوئی برائی نہ پائی جاتی ہو تو پھر اپنے اس الزام کا مورَدوہ خود ہی ٹھہرے گا۔"}],[124,"جابربن سلیم رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’میں نے ایک آدمی کو دیکھا کہ لوگ اس کی باتوں کوسن رہے تھے، وہ جو بھی حکم جاری کرتا لوگ اسے مان لیتے تھے، میں نے پوچھا:یہ کون ہے؟ تو لوگوں نے بتایا کہ یہ اللہ کے رسول صلی اللہ علیہ وسلم ہیں۔ میں نے کہا: «عَلَيْكَ السَّلَامُ يَارَسُولَ اللّٰهِ» میں نے یہ دو مرتبہ کہا۔ آپ صلی اللہ علیہ وسلم نے جواب میں فرمایا: «عَلَيْكَ السَّلَامُ» نہ کہو، کیونکہ یہ میّت کا سلام ہے، «اَلسَّلَامُ عَلَيْكَ» کہو۔ جابرؓکہتے ہیں کہ میں نے پوچھا:آپ اللہ کے رسول ہیں؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:(ہاں)میں اللہ کا رسول ہوں، (وہ اللہ)کہ جب تجھے کوئی دُکھ تکلیف پہنچتی ہے اورتُواسے پکارے تو وہ (تيرى تكليف)دُورکر دیتا ہے، اگر تجھ پہ قحط چھا جاتا ہے اورتُواسے پکارتا ہے تو وہ تیری فصل کو اگاتا ہے اورجب تُوکسی بنجر زمین یاصحراء میں ہوا ورتُواپنی سواری کھو بیٹھے پھرتُواسے پکارے تو وہ تجھے تیری سواری لوٹا دیتا ہے۔ جابرؓکہتے ہیں کہ میں نے کہا:مجھے کوئی وصیّت فرما دیجیے۔ آپ صلی اللہ علیہ وسلم نے فرمایا:کسی کو گالی بالکل نہ دے۔ جابرؓکہتے ہیں کہ میں نے اس کے بعد آزاد، غلام، اونٹ اور بکری کسی کو بھی کبھی گالی نہیں دی۔ آپ صلی اللہ علیہ وسلم نے (مزيد)فرمایا:کسی نیکی کو ہرگز کمترمت سمجھ، اپنے بھائی سے بات کرتے ہوئے ہنستے اورکھِلتے چہرے سے بات کر، کیونکہ یہ بھی نیکی ہے، اپنے تہہ بند کو نصف پنڈلی تک اُٹھا کر رکھ، اگر اتنا نہیں کر سکتا تو ٹخنوں تک کر، البتہ ٹخنوں سے نیچے تہہ بند لٹکا نے سے بچ، کیونکہ یہ تکبّرکی علامت ہے اور بلاشبہ اللہ تعالیٰ تکبّرکو پسند نہیں فرماتا اور اگر کوئی شخص تجھے گالی دے یاتجھ میں پائی جانے والی کسی ایسی بات پر تمہیں عاردِلائے جسے وہ جانتا ہو توتُواس کی کسی ایسی بات پر عار نہ دِلاجوتُوجانتا ہو، کیونکہ اس کا وبال اسی پر ہوگا۔‘‘","صحیح",{"k":"سنن أبوداؤد (4084)، سنن ترمذی (2722)، سلسلہ الأحادیث الصحیحہ (1403)۔"}],[125,"سعیدبن زید رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’سب سے بڑاسُود(زیادتی)کسی مسلمان کی عزّت پر ناحق دست درازی کرنا ہے۔ اوررَحِمْ (رشتے داری)رحمان کی شاخ ہے، سوجس نے اسے کاٹا اس پر اللہ تعالیٰ جنّت حرام کردے گا۔‘‘","صحیح",{"k":"سنن أبوداؤد (4876)، مسند أحمد (1؍190)۔"}],[126,"ابوبکرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’سرکشی اور قطع رحمی سے بڑھ کر کوئی بھی گناہ ایسا نہیں ہے کہ جس کے مرتکب کو اللہ تعالیٰ جلد ہی اس دنیا میں بھی سزا سے دو چار کرنے کے ساتھ ساتھ آخرت میں بھی اس کے لیے سزا باقی رکھے گا۔‘‘","صحیح",{"k":"سنن أبوداؤد (4902)، سنن ترمذی (2511)، سنن ابن ماجه (4211)، مسند أحمد (5؍36)، سلسلہ الأحادیث الصحیحہ (918)۔"}],[127,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’ایک آدمی ابوبکر رضی اللہ عنہ کوبُرابھلا کہے جا رہا تھا، حالانکہ رسول اللہ صلی اللہ علیہ وسلم بھی تشریف فرما تھے، آپ صلی اللہ علیہ وسلم کو اس کی یہ حرکت بہت عجیب لگی اور آپ صلی اللہ علیہ وسلم مسکرا نے لگے۔ لیکن جب وہ بہت زیادہ ہی بولنے لگ گیا تو ابوبکر رضی اللہ عنہ نے بھی اس کی کسی بات کا جواب دے دیا، تو رسول اللہ صلی اللہ علیہ وسلم غصے میں آگئے اوراُٹھ کر چلے گئے۔ ابوبکرؓپیچھے گئے اور عرض کیا:اے اللہ کے رسول!جب تک وہ مجھے بُرابھلا کہتا رہا تو آپ صلی اللہ علیہ وسلم بیٹھے رہے اورجب میں نے اس کی ایک بات کا جواب دے دیا تو آپ صلی اللہ علیہ وسلم نے غصہ کر لیا اوراُٹھ کر آگئے۔ آپ صلی اللہ علیہ وسلم نے فرمایا:اس لیے کہ (اللہ کی طرف سے)تیرے ساتھ(ایک فرشتہ) مقرر تھا جو تیری طرف سے اسے جواب دے رہاتھا، لیکن جب تم نے اس کا جواب دیا تو شیطان (وہاں آکر)بیٹھ گیا، اور میں شیطان کے ساتھ نہیں بیٹھ سکتا تھا۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:اے ابوبکر!جس بندے پر بھی ظلم کیا جائے اور وہ اللہ کی خاطر خاموش رہے تو اللہ تعالٰی اپنی مدد کے ساتھ اسے عزت وغلبہ عطا فرما دیتا ہے۔‘‘","حسن",{"k":"مسند أحمد (2؍436)، سلسلہ الأحادیث الصحیحہ (2231)۔","f":"گوکہ ظالم سے بدلہ لینے کی قدرت نہ ہونے کے باوجود بھی اسے معاف کر دینا نیکی ہے کیونکہ اس سے ظلم کرنے والے کاعِندا للہ مواخذہ نہیں ہوتا، لیکن بدلے اور انتقام کی قدرت کے باوجود ظالم کو معاف کرنا بہت بڑی نیکی ہے، کیونکہ اس صورت میں معاف کردینے کی وجہ خالصتاًرضائے الہٰی کا حصول ہوتاہے۔"}],[128,"سعیدبن مسیّب بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم اپنے صحابہؓ کے ساتھ تشریف فرما تھے کہ اسی دوران ایک آدمی ابوبکر رضی اللہ عنہ(کوبُرابھلا کہہ کر)تکلیف دینے لگا، ابوبکر رضی اللہ عنہ خاموش رہے اور اسے کوئی جواب نہ دیا، اس نے دوری باراذِیّت دی، ابوبکرؓپھر بھی خاموش رہے، اس نے تیسری مرتبہ ایذاء رسانی کی تو ابوبکرؓنے بھی جواب دے کر اس سے بدلہ لے لیا۔ جب ابوبکرؓنے بدلہ لیا تو رسول اللہ صلی اللہ علیہ وسلم اُٹھ کر چلے گئے۔ ابوبکر رضی اللہ عنہ نے عرض کیا:اے اللہ کے رسول!کیا آپ صلی اللہ علیہ وسلم مجھ سے ناراض ہوگئے ہیں؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:آسمان سے ایک فرشتہ اترا تھا جو اس آدمی کی ان باتوں کی تکذیب کر رہا تھا جو وہ کہہ رہاتھا، لیکن جب تُونے بدلہ لیا تو شیطان آگیا، اورجب شیطان آگیا تو میں وہاں نہیں بیٹھ سکتا تھا۔‘‘","صحیح",{"k":"سنن أبوداؤد (4896)۔"}],[129,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’صدقہ مال کوکم نہیں کرتا اور نہ کسی کو معاف کردینے سے (عزت میں کمی ہوجاتی ہے، بلکہ(اللہ تعالیٰ عزّت میں اضافہ ہی فرماتا ہے، اور جو شخص بھی اللہ کے لیے جھُک جاتا ہے اللہ تعالیٰ اسے بلند کر دیتا ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2588)، سنن ترمذی (2029)۔","f":"معاشرتی جاہلی رویّوں میں مخالف سے انتقام نہ لینا بزدلی اورذِلّت کی علامت سمجھا جاتا ہے جوکہ فساد پھیلا نے کا سراسر شیطانی ہتھکنڈہ ہے، حالانکہ درحقیقت معاف کرنا ہی عزت سے ہمکنار ہو نے کا موجب عمل ہے۔"}],[130,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’مدِّمقابل کو پچھاڑ دینے والا سخت جان نہیں ہوتا۔ صحابہؓ نے عرض کیا:اے اللہ کے رسول!تو پھر سخت جان کون ہوتاہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:وہ شخص جو غصے کے وقت اپنے آپ پر قابو رکھے۔‘‘","صحیح",{"k":"صحیح بخاری (6114)، صحیح مسلم (2609)۔","f":"اللہ تعالیٰ فرماتا ہے: ﴿وَالْكَاظِمِينَ الْغَيْظَ وَالْعَافِينَ عَنِ النَّاسِ وَاللّٰهُ يُحِبُّ الْمُحْسِنِينَ﴾ [آلعمر ان: ۱۳۴] ’’غصے کوپی جانے والے اور لوگوں سے درگزر کرنے والے، اور اللہ تعالیٰ نیکی کرنے والے )ایسے(لوگوں کو پسند فرماتا ہے۔‘‘\nیعنی آپ صلی اللہ علیہ وسلم نے فرمایاکہ بہادر اور سخت جان وہ نہیں ہوتا کہ جس کی کسی سے لڑائی ہو تو وہ مدِمقابل کوچِت کردے، بلکہ حقیقی بہادر وہ شخص ہوتاہے جو غصے کے وقت اپنے آپ پر قابو رکھے، جس پر غصہ ہوا سے اللہ کی رضا کی خاطر معاف کردے اور جذبات میں آکر کوئی ایسا کام نہ کر بیٹھے جس سے بعد میں ندامت اور پچھتاوا ہو۔"}],[131,"ابوہریرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’مدِّمقابل کو پچھاڑ دینے والا سخت جان نہیں ہوتا بلکہ(درحقیقت)غصے کے وقت خود پر قابو رکھنے والا سخت جان ہوتاہے۔‘‘","صحیح",{"k":"صحیح بخاری (6114)، صحیح مسلم (2609)۔"}],[132,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’ایک آدمی رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوا اور اس نے عرض کیا:مجھے (کسی عمل کا)حکم فرمائیے، لیکن بہت زیادہ احکام مت دیجیے، تاکہ میں اسے سمجھ سکوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا:غصہ مت کیا کر۔ آپ صلی اللہ علیہ وسلم نے اسی بات کو بار بار دوہرایا اور فرمایا:غصہ مت کیا کر۔ ایک روایت میں یوں ہے کہ اس آدمی نے کہا:(اے اللہ کے رسول!)مجھے کوئی ایسا عمل بتلائیے کہ جس پر عمل پیرا ہو کر میں جنّت میں جا سکوں۔ اس کے بعد وہی ساری حدیث آخرتک۔‘‘","صحیح",{"k":"صحیح بخاری (6116)، سنن ترمذی (2020)، مسند أحمد (2؍362)۔","f":"اس سائل نے نبی صلی اللہ علیہ وسلم سے موجبِ جنت عمل کے بارے میں سوال کیا اور ساتھ ہی یہ کہہ دیا کہ میں بہت زیادہ احکام یاد نہیں رکھ سکتا بلکہ صرف ایک ہی جامع ساحکم بتلا دیجیے، توآپ صلی اللہ علیہ وسلم نے اسے فرمایاکہ غصہ مت کیا کر۔ تو گویا غصہ نہ کرنا بقیہ تمام احکام سے اہم ہے، کیونکہ آپ صلی اللہ علیہ وسلم نے یقیناًاسے وہی حکم فرمایا ہوگا جوآپؐ کی نظر میں سب سے زیادہ اہمیت کا حامل اور جامع ہوگا۔ البتہ یہ یاد رہے کہ جن دیگر امور پر اس عمل کو فضیلت دی گئی ہے وہ نفلی امور ہیں، ان میں فرائض شامل نہیں ہیں، فرائض وواجبات کاحکم اپنی جگہ برقرار رہے گاکیونکہ ان کی کسی بھی شخص کے لیے معافی نہیں ہے۔"}],[133,"ابوذر رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب تم میں سے کسی شخص کو غصہ آئے اور وہ کھڑا ہو تو اسے بیٹھ جانا چاہیے، سواگر اس سے غصہ چلا جائے تو(ٹھیک ہے)اور اگر پھر بھی ختم نہ ہو تو لیٹ جائے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4782)، مسند أحمد (5/152-)۔","f":"یہاں نبی صلی اللہ علیہ وسلم نے غصہ دُورکرنے کا ایک شاندار نسخہ بتلایا ہے۔ ماہرینِ نفسیات کے مطابق بھی اگر غصے کے دوران انسان کی حالت (Position) تبدیل کردی جائے تو غصے کے باعث اس کے خون کی گردش میں جو تیزی آئی ہوتی ہے اس میں کمی واقع ہوجاتی ہے اور یوں جذبات قابو میں آجاتے ہیں اور غصہ ختم ہو جاتا ہے۔ اس لیے جب بھی انسان کو غصہ آئے اگر وہ کھڑا ہو تو اسے فوراًبیٹھ جانا چاہیے اور اگر بیٹھا ہو تو لیٹ جانا چاہیے تاکہ وہ ان جذبات سے مغلوب ہونے کی بہ جائے انہیں ختم کر سکے۔"}],[134,"سلیمان بن صرد رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے سخت غصے والے شخص کے بابت روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’میں ایک ایسا کلمہ جانتا ہوں کہ اگر وہ اسے(غصے کے وقت)پڑھ لے گاتو اس کا غصہ جاتا رہے گا، (وہ کلمہ یہ ہے:) «أَعُوذُ بِاللّٰهِ مِنَ الشَّيْطَانِ الرَّجِيمِ» ’’میں شیطان مردود سے اللہ کی پناہ میں آتا ہوں۔‘‘","صحیح",{"k":"صحیح بخاری (3282)، صحیح مسلم (2610)۔","f":"یہ بھی غصہ ختم کرنے کا نہایت مؤثرعلاج ہے، کیونکہ غصہ شیطان کی طرف سے ہوتاہے اور أعوذ باللہ پڑھنے سے شیطان بھاگ جاتا ہے تو غصہ بھی جاتا رہتا ہے۔"}],[135,"ابنِ عمر رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’کوئی بھی گھُونٹ بندہ ایسا نہیں پِیتا کہ جو اللہ تعالیٰ کے ہاں رضائے الٰہی کی خاطر غصے کاگھُونٹ پینے سے بڑھ کر اجروثواب کا حامل ہو۔‘‘","صحیح",{"k":"سنن ابن ماجه (4189)۔","f":"مراد یہ ہے کہ رضائے الہٰی کی خاطر غصہ پی جانا اور کسی پر اس کا نفاذ نہ کرنا اجروثواب کے لحاظ سے سب سے عظیم عمل ہے۔"}],[136,"ابوہریرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’جو کسی مسلمان کا سودا واپس کرلے، اللہ تعالیٰ روزِقیامت اس کے گناہ معاف فرما دے گا۔‘‘","صحیح",{"k":"سنن أبوداؤد (2199)۔"}],[137,"سیدہ عائشہ رضی اللہ عنہا نبی صلی اللہ علیہ وسلم سے روایت کرتی ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’عزّت دار لوگوں کی لغزشیں معاف کر دیا کرو، جب تک کہ وہ کسی قابلِ حَدجرم تک نہ پہنچیں۔‘‘","صحیح",{"k":"سنن أبوداؤد (4375)، مسند أحمد (6؍181)، سلسلہ الأحادیث الصحیحہ (638)۔","f":"یعنی اگر کسی معزز شخص سے کوئی خطاو لغزش ہوجائے تو اس سے درگزر کر دینا اور انتقام نہ لینا ہی افضل ہے، کیونکہ حقیقت میں وہ ایسا نہیں ہوتا کہ کسی کو نقصان پہنچائے یاکسی کی دِل آزاری کا باعث بنے بلکہ غیر ارادی طور پر شیطان کے بہکاوے میں آکر ایسا کر بیٹھتا ہے۔"}],[138,"ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے اشج بن عبدالقیس سے فرمایا:\n’’تم میں دو خصلتیں ایسی ہیں کہ جنہیں اللہ تعالیٰ اور اس كار سول پسند فرماتے ہیں:بردباری اور وقار۔‘‘","صحیح",{"k":"صحیح مسلم (18)۔"}],[139,"سعد رضی اللہ عنہ اس حدیث کو مرفوعاًبیان کرتے ہیں کہ:\n’’آخرت کے کام کے سوا کسی بھی کام میں جلدبازی نہیں کرنی چاہیے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4810)، سلسلہ الأحادیث الصحیحہ (1794)۔"}],[140,"سیدنا انس رضی اللہ عنہ فرماتے ہیں کہ:\n’’میں نے دس سال رسولِ مکرم صلی اللہ علیہ وسلم کی خدمت کی، قسم بخدا!آپ صلی اللہ علیہ وسلم نے مجھے کبھی بھی اُف تک نہیں کہا، اور نہ تو کسی ایسے کام پہ کہ جو میں نے کیا ہو یہ کہاکہ تم نے یہ کیوں کیا؟ اور نہ ہی کسی ایسے کام پہ کہ جو میں نہ کر سکا ہوا یہ کہاکہ تم نے یہ کام کیوں نہیں کیا؟‘‘","صحیح",{"k":"صحیح بخاری (6038)، صحیح مسلم (2309)۔","f":"اگر کسی سے کوئی غلطی سرزد ہو جائے تو اس کا مواخذہ کرنے کی بہ جائے اسے معاف کر دینا چاہیے۔ معافی بھی کُلّی طور پر دی جائے، یعنی سرزنش کی کسی ادنیٰ سی صورت کا بھی اظہار نہ کیا جائے، جیسا کہ نبی کریم صلی اللہ علیہ وسلم اپنے خادم کو ’’اُف‘‘ تک نہیں کہا کرتے تھے۔"}],[141,"سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں کہ:\n’’میں نے رسول اللہ صلی اللہ علیہ وسلم کو کبھی کسی خادم کو اور اپنی کسی بیوی مارتے نہیں دیکھا، اور نہ ہی آپ صلی اللہ علیہ وسلم نے اپنے ہاتھ سے کسی کو مارا سوائے راہِ خدا میں جہاد کرتے ہوئے، اگر آپ صلی اللہ علیہ وسلم کو کوئی نقصان پہنچایا گیا تو آپ صلی اللہ علیہ وسلم نے اس کا انتقام نہیں لیا، سوائے اس صورت کے کہ اللہ تعالٰی کا کوئی معاملہ ہو، اللہ تعالٰی کے معاملات میں آپ صلی اللہ علیہ وسلم انتقام لیا کرتے تھے اور اگر دو کام آپ صلی اللہ علیہ وسلم کے سامنے آتے تو آپ صلی اللہ علیہ وسلم ان دونوں میں سے آسان ترین کو اختیار فرماتے بشرطیکہ وہ گناہ نہ ہو، کیونکہ اگر وہ گناہ ہوتا تو آپ صلی اللہ علیہ وسلم تو گناہ سے تمام لوگوں سے زیارہ دُوررہتے تھے۔‘‘","صحیح",{"k":"صحیح مسلم (7232)۔"}],[142,"زوجۂ پیغمبر سیدہ عائشہ رضی اللہ عنہا سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’اے عائشہ!یقیناًاللہ تعالیٰ نرم ہے اور نرمی کو پسند فرماتا ہے، وہ نرمی پر وہ کچھ عطا کر دیتا ہے جو وہ سختی اور اس کے علاوہ کسی بھی اور چیز پر عطا نہیں کرتا۔‘‘","صحیح",{"k":"صحیح مسلم (2593)۔"}],[143,"سیدہ عائشہ رضی اللہ عنہا روایت کرتی ہیں کہ وہ ایک اونٹ پر سوار تھیں اور اسے مارنے لگیں، نبی صلی اللہ علیہ وسلم نے(یہ دیکھا تو)فرمایا:\n’’اے عائشہ!نرمی اپناؤ، کیونکہ جس بھی چیز میں نرمی آجاتی ہے اسے خوبصورت بنا دیتی ہے اورجس چیز سے نرمی چھین لی جاتی ہے اسے بدصورت بنا دیتی ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2594)، سنن أبوداؤد (4808)۔"}],[144,"جریربن عبداللہ رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’جو نرمی سے محروم کر دیا گیا، وہ بھلائی سے محروم کر دیا گیا۔‘‘","صحیح",{"k":"صحیح مسلم (2592)، سنن أبوداؤد، کتاب الأدب، باب فی الرفق، ح (-4809)۔"}],[145,"عبداللہ بن عباس رضی اللہ عنہما سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’نیک چال چلن، پاکیزہ کر دار اور میانہ روی نبوّت کے پچیس اجزاء میں سے ایک جزو ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4776)، مسند أحمد (1؍296)۔","f":"کسی بھی مسلمان کے شایانِ شان نہیں ہے کہ وہ غیر سنجیدہ، بدچلن اور بدکردار ہو، کیونکہ یہ خصائلِ رذیلہ اسلام کے ماننے والے کی ناموس وعزت اور اس کے دِین کے منافی امور میں سے ہیں۔ حقیقی مسلمان تو نیک چلن اور پاکیزہ کر دار کا حامل ہوتاہے، اسی طرح نہ وہ حق بات کرنے کے وقت خاموش رہتا ہے اور نہ ہی بے فائدہ اور غیر ضروری باتوں اور کاموں میں اُلجھا رہتا ہے بلکہ بامقصد اور میانہ روہو تاہے۔"}],[146,"شرم وحياء بنده مسلم كاامتيازى وصف ہے۔ جس شخص ميں حياء نہ ہو وہ حقيقى مسلمان نہیں ہوتا، كيونكہ حياء كے وجود سے ہی ايمان كاوجود ہے اور اس كے فقد ان سے نہ صرف ايمان جاتا رہتا ہے بلکہ تمام اخلاقى گرا وٹيں پيدا ہو جاتی ہیں۔ حياء جتنا بھي ہوکم ہی ہوتاہے، جیسا کہ ابنِ عمر رضی اللہ عنہما روایت کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم ایک آدمی کے پاس سے گزرے تو وہ اپنے بھائی کو حیاء کے بارے میں نصیحت کر رہا تھا، تو آپ صلی اللہ علیہ وسلم نے فرمایا:اسے چھوڑ دے، کیونکہ حیاء ایمان کا حصہ ہے۔‘‘","صحیح",{"k":"صحیح بخاری (24)، صحیح مسلم (36)۔","f":"صحيح بخارى میں یہ حديث ذرا تفصيل كے ساتھ موجود ہے، اس میں ذكر ہے کہ وہ آدمى اپنے جس بھائى كوسمجھا رہا تھاوه بہت شرميلا تھا، یہ اسے اتنا شرما نے كے بارے ميں سرزنش كررہاتھااوركہہ رہا تھاكہ تم اسقدر شرماتے ہوکہ بسااوقات اس كى وجہ سے تمہارا نقصان بھى ہو جاتا ہے، اس ليے اتنا شرمانا اچھا نہیں۔ پاس سے نبى صلی اللہ علیہ وسلم گزر رہے تھے تو آپ صلی اللہ علیہ وسلم نے يہ سُن ليا تو اسے فرمايا:ايسامت كہو، کیونکہ حياء تو ايمان كاحصہ ہے، اس ليے اسے حياء كوكم كرنے كى نصيحت مت كرو۔"}],[147,"ابوہریرہ، ابوبکرہ اور عمر ان بن حصین رضی اللہ عنہم نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’حیاء ایمان کا حصہ ہے اور ایمان جنّت میں (لے جانے والا)ہے، بدزبانی بداخلاقی کا حصہ ہے اور بداخلاقی جہنّم میں (لے جانے والی)ہے۔‘‘","صحیح",{"k":"سنن ترمذی (2009)، سنن ابن ماجه (4184)، المعجم الکبیر للطبرانی (18؍178)، سلسلہ الأحادیث الصحیحہ (495)۔","f":"گویا حیاء موجبِ جنّت اور بدزبانی موجبِ جہنّم ہے۔"}],[148,"عمران بن حصین رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’حیاء سراسر بھلائی ہی ہے، اور حیاء بھلائی ہی لے کر آتا ہے۔‘‘","صحیح",{"k":"صحیح مسلم (37)۔","f":"یعنی حیاء کا نتیجہ سوائے خیروبھلائی کے اور کچھ ہو ہی نہیں سکتا، یہ سراسر خیر کا ہی پیش خیمہ ہوتاہے۔"}],[149,"ابو مسعود رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’پہلے انبیاء کی کلام سے جو بات لوگوں نے یاد رکھی ہے وہ یہ ہے کہ جب تجھے حیاء محسوس نہ ہو تو جو تیر اجی چاہے کر۔‘‘","صحیح",{"k":"صحیح بخاری (3483)، سنن أبوداؤد (4797)۔","f":"جب انسان میں حیاء کا فقد ان ہوجائے تو اس پر وعظ ونصیحت کچھ اثر نہیں کرتا اور نہ ہی وہ کسی کا کچھ پاس ولحاظ رکھتا ہے، بلکہ اس کا نفس اسقدر شیطنت میں غرق ہو جاتا ہے کہ وہ جو بھی کرتا رہے اسے کچھ پرواہ نہیں ہوتی، نہ اسے رب تعالیٰ کا خوف رہتا ہے اور نہ ہی لوگوں میں بدنامی کاڈر، گویا وہ ان لوگوں میں شمار ہو جاتا ہے کہ جن کی نظر میں ہو ائے نفسانیہ کے سوا کسی اور چیز کی اہمیت نہیں رہتی۔"}],[150,"ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم پردہ نشین کنواری لڑکی سے بھی زیادہ شرم وحیاء والے تھے، اورجب آپ صلی اللہ علیہ وسلم کسی بات یاکسی چیز کو ناپسند فرماتے تو ہم اسے آپ صلی اللہ علیہ وسلم کے چہرے سے ہی پہچان لیا کرتے تھے۔‘‘","صحیح",{"k":"صحیح بخاری (6102)، صحیح مسلم (2320)۔"}],[151,"ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’تم میں سے جو شخص برائی دیکھے، اگر تو وہ اسے اپنے ہاتھ سے ختم کرنے کی استطاعت رکھتا ہو تو اسے ایسا کرنا چاہیے، لیکن اگر اس کے پاس اس کی استطاعت نہ ہو تو اپنی زبان سے منع کرے اور اگر وہ اس کی بھی طاقت نہ رکھتا ہو تو اپنے دِل سے ہی بُراجا نے، اور یہ ایمان کا کمزور ترین درجہ ہے۔‘‘","صحیح",{"k":"صحیح مسلم (49)، سنن أبوداؤد (1140)، سنن ترمذی (2172)، سنن ابن ماجه (1275)۔","f":"اس حدیثِ مبارکہ میں برائی کو ختم کرنے کے تین مراتب بیان ہوئے ہیں: (۱)سب سے افضل مرتبہ یہ ہے کہ برائی کو ہاتھ سے روکا جائے۔ (۲)اس سے کم فضیلت والا مرتبہ یہ ہے کہ برائی کرنے والے کو زبان سے منع کیا جائے۔ (۳)تیسرا مرتبہ ان دونوں سے کم فضیلت والا ہے، وہ یہ کہ برائی کودِل میں ہی بُراجانا جائے۔ یاد رہے کہ دوسرا مرتبہ تبھی اختیار کیا جا سکتا ہے جب پہلے پر عمل کی طاقت نہ ہو اور تیسرا بھی اسی صورت میں اختیار کیا جائے گاجب دوسرے کی بھی استطاعت نہ ہو، لیکن اگر افضل درجے کی استطاعت موجود ہو تو ادنیٰ درجے کو اختیار کرنا درست نہیں ہے بلکہ اسی پر عمل کرنا ضروری ہے جس کا وہ اہل ہے۔ پھر یہ فریضہ صرف علماء کے ساتھ ہی خاص نہیں ہے بلکہ ہرصاحبِ ایمان شخص پر اس کی حیثیت واستطاعت کے مطابق واجب ہے۔"}],[152,"عبداللہ بن عمرو رضی اللہ عنہما فرماتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم بدزبان اور لڑنے جھگڑنے والے نہیں تھے، آپ صلی اللہ علیہ وسلم فرمایا کرتے تھے:یقیناًتم میں سب سے بہتر وہ شخص ہے جو اخلاق کے لحاظ سے تم سب سے اچھا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (6035)، صحیح مسلم (2321)۔"}],[153,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’مومنوں میں سے کامل ترین ایمان والا وہ شخص ہے جوان میں بہ اعتبارِاخلاق سب سے اچھا ہے۔ اور رسول اللہ صلی اللہ علیہ وسلم کا فرمان ہے:مجھے اچھے اخلاق کی تکمیل کے لیے ہی بھیجا گیا ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4682)، مسند أحمد (2؍250)، سلسلہ الأحادیث الصحیحہ (284)۔","f":"گویا جو شخص اخلاقی اوصاف سے کامل طور پر متصف نہ ہو وہ کامل مومن بھی نہیں ہوتا اور خود کو کامل مومن بنانے کے لیے اخلاقِ حسنہ کا اہتمام ضروری ہے۔"}],[154,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’بلا شائبہ بندۂ مومن اپنے اچھے اخلاق کی وجہ سے رات کو قیام کرنے اوردِن کو روزہ رکھنے والے شخص کا درجہ پالیتا ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4798)۔","f":"یعنی خود کو اچھے اخلاق سے متصف کر لینے سے آدمی اتنے اجروثواب کا حقداربن جاتا ہے جتنا ثواب وہ شخص کماتا ہے جودِن کو روزہ رکھتا ہو اور رات اللہ کے حضور کھڑے ہو کر نماز میں بسر کرتا ہو۔"}],[155,"ابودرداء رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’جسے نرمی سے کچھ حصہ عطا کر دیا گیا اسے بھلائی کے کچھ حصے سے نواز دیا گیا اور جو نرمی کے کچھ بھی حصے سے محروم رہا اسے خیروبھلائی کے حصے سے ہی محروم کر دیا گیا۔ اور آپ صلی اللہ علیہ وسلم کا فرمان ہے:میزانِ عمل میں سب سے بھاری چیز اچھا اخلاق ہے، بلاشبہ اللہ تعالٰی بے حیاء اور بدزبان شخص سے نفرت کرتاہے۔‘‘","صحیح",{"k":"سنن ترمذی (2002)، سلسلہ الأحادیث الصحیحہ (519)۔"}],[156,"سہل بن سعد رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’یقیناًاللہ تعالیٰ بہت صاحبِ کرم ہے، وہ عالی ظرف اور بلند اخلاق کو پسند فرماتا ہے اور کمینہ خصلت کو ناپسند فرماتا ہے۔‘‘","صحیح",{"k":"سلسلہ الأحادیث الصحیحہ (1378)۔"}],[157,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’مومن سادہ لوح اور کشادہ ظرف ہوتاہے، جبکہ فاجر چالاک فریبی اور تنگ ظرف ہوتاہے۔‘‘","حسن",{"k":"سنن أبوداؤد (4790)، سنن ترمذی (1964)، سلسلہ الأحادیث الصحیحہ (935)۔","f":"یعنی چالاکی، فریبی، دغابازی، کم ظرفی اور گھٹیاپن جیسے تمام خصائلِ رزیلہ ایک حقیقی مومن کی شان کے لائق نہیں ہیں بلکہ یہ فاجرو فاسق وفاجر شخص کی خصلتیں ہیں۔ مومن کا تو ان سے دُورکا بھی واسطہ نہیں ہونا چاہیے۔"}],[158,"سہل بن سعد رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’مومن اُلفت ومحبت رکھنے والا ہوتا ہے، اور ایسے شخص میں کوئی بھلائی نہیں ہوتی جو نہ تو خود کسی سے اُلفت رکھتا ہو اور نہ ہی اس سے کوئی رکھے۔‘‘","صحیح",{"k":"مسند أحمد (5؍35)، سلسلہ الأحادیث الصحیحہ (426)۔","f":"اگر کوئی شخص اپنے مسلمان بھائیوں سے خود الفت ومحبت رکھے گاتو ہی وہ ان کی محبت پائے گا، لیکن اگر وہ کسی کو اس لائق ہی نہ گردانے کہ اس پہ اپنی محبت نچھاور کرے تو اسے بھی کوئی قابلِ التفات نہیں سمجھے گااور ایسا شخص بہ فرمانِ نبویؐ خیروبھلائی سے قاصر ہوتا ہے۔ لہٰذا لوگوں کے دِلوں میں اپنی محبت پیدا کرنے کے لیے ضروری ہے کہ انہیں بھی محبت کا مقام دیا جائے۔"}],[159,"عبداللہ بن مسعود رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جو شخص باوقار وسنجیدہ، نرم مزاج، (لوگوں کے لیے)آسانی پیدا کرنے والا اور قربت رکھنے والا ہو تو اللہ تعالیٰ اسے جہنم کی آگ پر حرام کردیتا ہے۔‘‘","صحیح",{"k":"سنن ترمذی (2488)، مسند أحمد (1؍415)، سلسلہ الأحادیث الصحیحہ (938)۔"}],[160,"مکحول رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’باوقار اور سنجیدہ مومنین نکیل والے اس اونٹ کے مانند ہیں کہ جسے باندھ دیا جائے تو وہ بندھ جائے اور اگر اسے بیٹھنے کو کہا جائے تو وہ چٹان پر بھی بیٹھ جائے۔‘‘","حسن",{"k":"سلسلہ الأحادیث الصحیحہ (936)۔","f":"یعنی حقیقی مومن کی یہ صفت ہوتی ہے کہ اس میں اکڑ اور انا نہیں ہوتی، بلکہ نہایت عاجز، منکسر مزاج اور فرمانبردار شخص ہوتاہے۔"}],[161,"جابربن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’اللہ تعالیٰ اس بندے پر رحم فرمائے جو(سودا)بیچتے وقت نرمی کرتاہے، خریدتے وقت بھی اورجب تقاضا کرتا ہے تب بھی نرمی سے کام لیتا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (2076)۔","f":"نبی کریم صلی اللہ علیہ وسلم نے ایسے شخص کے یے رحم کی دعا فرمائی ہے جو ہر معاملے میں نرمی اپناتا ہے، کسی بھی کام میں سختی و درشتی کا قائل نہیں ہوتا۔ وہ ہستی کہ خدا تعالیٰ کے بعد اسی کا درجہ ہے اور وہ تمام جہانوں سے افضل و اعلیٰ ہے،اس ہستی کی دعا کا حقدار بننے کے لیے اپنے آپ میں نرمی پیدا کر لینا کوئی بڑا عمل نہیں ہے۔"}],[162,"انس بن مالک رضی اللہ عنہ فرماتے ہیں کہ:\n’’میں نے کبھی کسی شخص کو نہیں دیکھا کہ اس نے نبی صلی اللہ علیہ وسلم کے کان میں کوئی بات کہی ہو تو آپ صلی اللہ علیہ وسلم نے اپنا سردُورکر لیا ہو، یہاں تک کہ وہ آدمی خود ہی اپنا سردُورکر لیتا تھا، اور نہ ہی میں نے ایسا کبھی دیکھا کہ کسی نے آپ صلی اللہ علیہ وسلم کا ہاتھ پکڑا ہو تو آپ صلی اللہ علیہ وسلم نے اس کا ہاتھ چھوڑ دیا ہو، یہاں تک کہ وہ آدمی خود ہی آپ صلی اللہ علیہ وسلم کا ہاتھ چھوڑ دیتا تھا۔‘‘","حسن",{"k":"سنن أبوداؤد (4794)۔","f":"یعنی آپ صلی اللہ علیہ وسلم اخلاقیات سے متعلقہ چھوٹی سے چھوٹی بات کا بھی خیال رکھتے تھے کہ مبادا کسی شخص کے دل میں کوئی بات نہ آ جائے۔"}],[163,"سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں کہ:\n’’نبی کریم صلی اللہ علیہ وسلم کوجب کسی آدمی کے بارے میں کسی بات کا پتہ چلتا تو آپؐ(اس کا نام لے کر)نہیں کہتے تھے کہ فلاں شخص کو کیا ہو گیا ہے؟ بلکہ آپ صلی اللہ علیہ وسلم یوں فرماتے کہ لوگوں کو کیا ہو گیا ہے کہ وہ اس طرح اس طرح کہتے پھرتے ہیں۔‘‘","صحیح",{"k":"سنن أبوداؤد (4788)۔","f":"چونکہ تمام لوگوں کے بیچ اگر کسی کو مخاطب کر کے یا اس کا نام لے کر اسکی غلطی کی نشاندہی کی جائے تو اس سے اس شخص کی بے عزتی ہوتی ہے اور تمام لوگوں کی نظروں کا نشانہ بننے کی وجہ سے اسے نہایت شرمندگی اٹھانا پڑتی ہے، اس لیے آپ صلی اللہ علیہ وسلم کسی کا نام نہیں لیتے تھے بلکہ عمومی انداز میں سب کو مخا طب کر کے فرما دیا کرتے تھے کہ لوگوں کو کیا ہو گیا ہے کہ وہ ایسے ایسے کہتے یا کرتے ہیں؟ اس عمدہ انداز سے وہ شخص جسکی اصلاح مقصود ہوتی تھی، از خود سمجھ جاتا تھا کہ یہ میرے بارے میں کہا جا رہا ہے، یوں اس کی عزت پر بھی حرف نہیں آتا تھا اور اس کی اصلاح بھی ہو جاتی تھی۔"}],[164,"سیدہ عائشہ رضی اللہ عنہا ہی بیان کرتی ہیں کہ:\n’’ایک آدمی نے نبی صلی اللہ علیہ وسلم سے (اندر آنے کی)اجازت مانگی تو آپ صلی اللہ علیہ وسلم نے فرمایا:اسے اجازت دے دو(یہ اپنے)خاندان کا بہت برا آدمی ہے۔ جب وہ اندر آیا تو آپ صلی اللہ علیہ وسلم نے اس سے نرم لہجے میں بات چیت کی، پھرجب وہ باہر نکل گیا تو میں نے کہا:اے اللہ کے رسول!آپ صلی اللہ علیہ وسلم نے تو اسے خاندان کابُراآدمی کہا تھا، پھرجب وہ اندر آیا تو آپ صلی اللہ علیہ وسلم نے بہت نرم لہجے میں اس سے بات چیت کی ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:اے عائشہ!بلا شائبہ روزِقیامت اللہ تعالیٰ کے ہاں مقام ومرتبے کے لحاظ سے تمام لوگوں میں سے بدترین شخص وہ ہو گاجس کی بدزبانی کی وجہ سے لوگوں نے اسے چھوڑ دیا ہو۔‘‘","صحیح",{"k":"صحیح بخاری (6054)، صحیح مسلم (2591)۔","f":"یعنی آپ صلی اللہ علیہ وسلم نے اسکے شر سے محفوظ رہنے کے لیے اس کو اندر آنے سے منع نہیں کیا اور ساتھ ہی یہ بھی بتلا دیا کہ ایسا شخص بدترین ہوتا ہے کہ جس کی بدزبانی سے ڈرتے ہوئے لوگ اسے چھوڑ دیں۔"}],[165,"ابنِ عمر رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’وہ مومن جو لوگوں کے ساتھ رہ کر زندگی گزارتا ہے اور ان کی تکلیفوں پر صبر کرتا ہے، یہ اس مومن سے افضل ہے جو نہ تو لوگوں کے ساتھ رہ کر زندگی گزارتا ہے اور نہ ہی ان کی تکلیفوں پر صبر کرتا ہے۔‘‘","صحیح",{"k":"سنن ترمذی (2507)، سنن ابن ماجه (4032)، مسند أحمد (2؍43)، سلسلہ الأحادیث الصحیحہ (939)۔"}],[166,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’سات قسم کے لوگوں کو اللہ تعالیٰ اس دِن اپنے سائے میں جگہ دے گا کہ جس دِن اس کے سائے کے علاوہ کوئی اور سایہ ہی نہیں ہوگا۔ پھر آپ صلی اللہ علیہ وسلم نے ان سات لوگوں کا ذکر کیا اور ان میں ان دو آدمیوں کا بھی ذکر کیا جو فقط اللہ تعالیٰ کی خاطر ایک دوسرے سے محبت رکھتے ہیں، اسی بنیاد پر اکٹھے اور جدا ہوتے ہیں۔‘‘","صحیح",{"k":"صحیح بخاری (660)، صحیح مسلم (1031)۔"}],[167,"ابوہریرہ رضی اللہ عنہ سے ہی مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’یقیناًاللہ تعالیٰ روزِقیامت فرمائے گا:میرے جلال وعظمت کی خاطر باہم محبت کرنے والے کہاں ہیں؟ آج کہ جس دِن میرے سائے کے علاوہ کوئی سایہ نہیں ہے، میں انہیں اپنے سائے میں جگہ دیتا ہوں۔‘‘","صحیح",{"k":"صحیح مسلم (2566)، مسند أحمد (2؍237)۔"}],[168,"ابوادریس علوی بیان کرتے ہیں کہ میں عبادہ بن صامت رضی اللہ عنہ کے پاس حاضر ہوا تو انہوں نے فرمایا:\n’’میں آج تمہیں صرف وہی بات سناؤں گاجو میں نے محمد صلی اللہ علیہ وسلم کی زبان سے سنی ہے:(وہ یہ ہے کہ)اللہ تعالی فرماتا ہے:میری خاطر باہم محبت کرنے والوں کے لیے میری محبت ثابت ہو چکی ہے، میری وجہ سے ایک دوسرے سے جُڑنے والوں کے لیے میری محبت مستحکم ہوگئی ہے،اور میری رضا کے لیے آپس میں خاص تعلق رکھنے والوں کے لیے میری محبت مضبوط ہو چکی ہے۔‘‘","صحیح",{"k":"مسند أحمد (5؍229)، مستدرک حاکم (4؍170)، صحیح الجامع للألبانی (4321)۔"}],[169,"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جو بھی دو شخص آپس میں رضائے الٰہی کی خاطر محبت رکھتے ہیں، ان میں سے افضل وہ ہے جو اپنے ساتھی سے اس کی نسبت زیادہ محبت کرتاہے۔‘‘","صحیح",{"k":"مستدرک حاکم (4؍170)، صحیح ابن حبان (2509)، سلسلہ الأحادیث الصحیحہ (540)۔"}],[170,"انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’تم میں سے کوئی بھی شخص تب تک ایمان کی مٹھاس نہیں پاسکتاجب تک کہ وہ(ان امور کو نہ اپنا لے کہ) وہ جس آدمی سے محبت کرتا ہو اس سے صرف اللہ کی رضا کی خاطر محبت رکھے، اور اسے (کفر اور جہنّم)سے بچا لینے کے بعد اسے کافر ہو جانا اسی طرح ناپسند ہوجس طرح کہ اسے آگ میں ڈال دیا جانا ناپسند ہو اور اسے اللہ ورسول کے ساتھ ان کے علاوہ تمام لوگوں اور تمام چیزوں سے بڑھ کر محبت ہو۔‘‘","صحیح",{"k":"صحیح بخاری (6041)، صحیح مسلم (43)۔"}],[171,"عبداللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’اے عبداللہ!اسلام کا کونسا کڑا زیادہ مضبوط ہے؟ راوی کہتے ہیں کہ میں نے کہا:اللہ اور اس کے رسول ہی بہتر جانتے ہیں تو آپ صلی اللہ علیہ وسلم نے فرمایا:اللہ تعالیٰ کی خاطر دوستی، اللہ کی خاطر محبّت اور اسی کی خاطربُغض رکھنا۔‘‘","صحیح",{"k":"السنن الکبری للبیهقی (10؍223)، المعجم الکبیر للطبرانی (10؍212)، سلسلہ الأحادیث الصحیحہ (1728)۔"}],[172,"انس بن مالک رضی اللہ عنہ روایت کرتے ہیں کہ ایک شخص نے نبی صلی اللہ علیہ وسلم سے کہا:\n’’میں فلاں شخص سے فقط رضائے الٰہی کی خاطر محبت رکھتا ہوں۔ تو نبی صلی اللہ علیہ وسلم نے فرمایا:کیا تم نے اسے بتلایا ہے؟ اس نے کہا:نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا:اسے بتاؤ(کہ تم اس سے محبت کرتے ہو)۔ راوی کہتے ہیں کہ بعد میں وہ آدمی اس سے ملا اور اسے کہاکہ اللہ کی قسم!میں تم سے اللہ تعالیٰ کی خاطر محبت کرتا ہوں۔ تو اس نے جواب میں کہا:تجھ سے وہ محبت کرے جس کی خاطر تم مجھ سے محبت کرتے ہو۔‘‘","صحیح",{"k":"سنن أبوداؤد (5125)۔","f":"چنانچہ آدمی کو جس سے اللہ کی رضا کی خاطر محبت ہو اسے بتلا دینا چاہیے تا کہ اس نیکی میں وہ بھی شریک ہو جائے۔ دوسرا یہ کہ جسے بتلایا جائے اسے جو اباً دعا دینی چاہیے اور محبت کا جواب محبت سے دینا چاہیے۔"}],[173,"ابوموسیٰ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے عرض کیا:\n’’اے اللہ کے رسول!ایک آدمی کسی قوم سے محبت رکھتا ہے لیکن ان سے مل نہیں سکا؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:آدمی اسی کے ساتھ ہو گاجس سے وہ محبت کرتاہے۔‘‘","صحیح",{"k":"صحیح بخاری (6170)، صحیح مسلم (2640)۔","f":"لہٰذا اس معاملے میں انسان کو احتیاط کرنی چاہیے کہ وہ کس سے محبت رکھتا ہے؟ کیونکہ ایسا نہ ہوکہ اس کی محبت کسی ایسے شخص سے ہو جو فاسق وفاجر اور اللہ کا پیارا نہ ہو تو وہ روزِقیامت اسی کے ساتھ ہو، بلکہ اس چیز کا اہتمام کرنا چاہیے کہ اس کی محبوب شخصیت اللہ تعالیٰ کی محبوب شخصیت ہی ہو یعنی نیکوکار اور برگزیدہ لوگوں سے وہ محبت رکھے تاکہ کل قیامت کے دِن ان کے ساتھ ہی جنّت کا داخلہ پاسکے۔"}],[174,"ابوہریرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’ایک آدمی کسی دوسری بستی میں اپنے کسی مسلمان بھائی سے ملنے جا رہا تھا تو اللہ تعالٰی نے اس کے راستے میں ایک فرشتہ بٹھا دیا، جب وہ اس فرشتے کے پاس پہنچا تو اس نے پوچھا:کہاں جانے کا ارادہ ہے؟ اس آدمی نے جواب دیا:میں اس بستی میں اپنے ایک بھائی کو ملنے کے ارادے سے جا رہا ہوں، فرشتے نے کہا:کیا تیرے ذمے اس کی کوئی چیز ہے جسے تُولوٹا نے جا رہا ہے؟ اس نے جواب دیا:نہیں، میں تو صرف اس سے اللہ کی رضا کی خاطر محبت کرتا ہوں(اور اسی وجہ سے ملنے جا رہا ہوں)، تو اس فرشتے نے کہا:میں تیری طرف اللہ تعالٰی کا بھیجا ہوا ہوں (تاکہ تجھے بتلاؤں)کہ اللہ عزوجل بھی تجھ سے اسی طرح محبت رکھتا ہے جیسے تُواس کی رضا کی خاطر اپنے مسلمان بھائی سے محبت رکھتا ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2567)، مسند أحمد (2؍292)۔"}],[175,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب کوئی آدمی فقط رضائے الٰہی کی خاطر اپنے(مسلمان)بھائی کی عیادت یااس کی زیارت کرتاہے، تو اللہ تعالیٰ فرماتا ہے:تُوبہت اچھا ہے، (اس نیک کام کے لیے)تیرا چلنا بھی اچھا ہے اورتُونے جنّت میں اپنا گھر تیار کر لیا ہے۔‘‘","حسن",{"k":"سنن ترمذی (2008)، سنن ابن ماجه (1443)۔"}],[176,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’ایک مسلمان کے دوسرے مسلمان پر چھے حقوق ہیں:پوچھا گیا:اے اللہ کے رسول!وہ کونسے حقوق ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا:جب تُواسے مِلے تو اسے سلام کہہ، جب وہ تیری دعوت کرے تو قبول کر، جب وہ تجھ سے خیرخواہی کا طلبگار ہو تو اس سے خیرخواہی کر، جب وہ چھینک مارے )اور الحمد لله کہے)تو)يرحمك اللهکہہ کر(اس کا جواب دے، جب وہ بیمار ہو جائے تو اس کی تیمارداری کر اورجب وہ فوت ہوجائے تو اس کے جنازے میں شریک ہو۔‘‘","صحیح",{"k":"صحیح بخاری (1240)، صحیح مسلم (2162)۔","f":"خیر خواہی کے طلب گار سے خیر خواہی کرنے کا مطلب ہے کہ جب اسے کسی معاملے میں مشورہ درکار ہو تو اسے اچھا اور مفید مشورہ دینا، یا اسے کسی مشکل وقت میں اس کی ضرورت ہو تو اس کے کام آنا، یا اس میں کوئی تعبدی امور کی کوتاہی یا اخلاقی برائی پائی جاتی ہو تو اس کی اصلاح کے لیے اسے سمجھانا اور نصیحت کرنا، غرضیکہ وہ تمام امور خیر خواہی میں شامل ہیں جن سے دوسرے مسلمان کا بھلا ہوتا ہے۔"}],[177,"براء بن عازب رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے ہمیں سات کام کرنے کاحکم فرمایا:مریض کی عیادت، جنازے میں شرکت، چھینک کا جواب، سلام کا جواب، دعوت قبول کرنے، قسم پوری کرنے اور مظلوم کی مدد کرنے کا، اور سات کاموں سے منع فرمایا:سونے کی انگوٹھی، ریشم، استبرق، دیباج، سُرخ چوغہ اور قسی پہننے اور چاندی کے برتن استعمال کرنے سے۔‘‘","صحیح",{"k":"صحیح بخاری (1239)، صحیح مسلم (2066)۔","f":"’حریر‘ عام ریشم کو کہتے ہیں اور یہ کُلی طور پرہر ریشمی کپڑے پر بھی بولا جاتا ہے، باقی سب بھی ریشم کی ہی قسمیں ہیں، فرق صرف یہ ہے کہ ’استبرق‘ بہت نفیس اور موٹا ریشم ہوتاہے اور’دیباج‘ خالص ریشمی کپڑے کو کہتے ہیں یعنی جس کا تانا بانا ہی ریشم کا ہوتا ہے اور ’قسی‘ شام ومصر میں تیار ہو کر آنے والے ریشمی ملبوسات پر بولا جاتا تھا۔"}],[178,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’اس ذات کی قسم جس کے ہاتھ میں میری جان ہے!تم جنّت میں تب تک نہیں جا سکتے جب تک کہ ایمان نہ لے آؤ اورتب تک تم ایمان والے نہیں بن سکتے جب تک کہ ایک دوسرے سے محبت نہ کرنے لگو، کیا میں تمہیں ایسا عمل نہ بتلاؤں کہ جسے کرنے سے تم باہم محبت کرنے لگوگے؟ آپس میں سلام کو پھیلاؤ۔‘‘","صحیح",{"k":"صحیح مسلم (54)، سنن أبوداؤد (5193)، سنن ترمذی (5193)، سنن ابن ماجه (68)۔","f":"گویا سلام کو عام کرنا دخولِ جنّت کا باعث ہے۔"}],[179,"ابوموسیٰ اشعری رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’بھُوکے کو کھانا کھلاؤ، بیمار کی تیمارداری کرو اور قیدی کو آزاد کراؤ۔‘‘","صحیح",{"k":"صحیح بخاری (3046)، سنن أبوداؤد (3105)۔"}],[180,"ابو سعید خدری رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’راستوں پر بیٹھنے سے اجتناب کرو۔ لوگوں نے عرض کیا:اے اللہ کے رسول!بعض مجلسیں )راستے میں(لگانا ہمارے لیے ضروری ہو جاتا ہے جن میں (آپس میں) باتیں کرتے ہیں۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:جب تم مجلس لگانے پہ مُصِرہی ہو تو پھر راستے کو اس کاحق دیا کرو۔ لوگوں نے پوچھا:راستے کا کیاحق ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:نظریں جھُکائے رکھنا، تکلیف دہ چیز ہٹانا، سلام کا جواب دینا، نیکی کاحکم دینا اور برائی سے منع کرنا۔‘‘","صحیح",{"k":"صحیح بخاری (6229)، صحیح مسلم (2121)۔"}],[181,"سیدنا تمیم داری رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’یقیناًدِین خیرخواہی کا نام ہے، بلاشبہ دِین خیرخواہی ہے، بے شک دِین سراسر خیرخواہی ہے۔ صحابہؓ نے عرض کیا:اے اللہ کے رسول!کس کے لیے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:اللہ تعالیٰ کے لیے، اس کی کتاب کے لیے، اس کے رسول کے لیے اور اس مسلمانوں کے ائمہ کے لیے۔ یافرمایا:مسلمانوں کے ائمہ اور ان کے عام لوگوں کے لیے۔‘‘","صحیح",{"k":"صحیح مسلم (55)، سنن أبوداؤد (4944)۔","f":"اللہ تعالیٰ کے لیے خیر خواہی یہ ہے کہ بندہ اس کی وحدانیت کا اقرار کرتے ہوئے اس کی بندگی کو بجا لائے، رسول اللہ صلی اللہ علیہ وسلم کے لیے خیرخواہی کا مطلب یہ ہے کہ آپؐ کی نبوت پر کامل ایمان و یقین رکھنے کے ساتھ ساتھ آپؐ کے احکام و فرامین کو بلا تاویل و توجیہہ کے قبول کیا جائے، کتاب اللہ کے لیے خیر خواہی سے مراد اس کی تلاوت اور اس میں مزکور احکاماتِ الٰہیہ کو پہلے اپنی نجی زندگی اور پھر پورے معاشرے پر نافذ کرنا، مسلمانوں کے ائمہ یعنی امراء و سلاطین کے لیے خیر خواہی یہ ہے کہ بھلائی اور اچھائی کے کاموں میں ان کی معاونت کرے اور برائی کے کاموں میں ان کی اصلاح کرے اور عام لوگوں کی خیر خواہی یہ ہے کہ ہر ایک کے ساتھ اچھا برتائو کرے، ہر مسلمان کے حقوق کی ادائیگی کرے، کسی کی عزت کو داغدار نہ کرے، ہر شخص کو اس کے مقام و مرتبہ کے مطابق اسی قدر زیادہ عزت د ے، حسبِ استطاعت اپنے ضرورت مند بھائی کی مدد کرے، جتنا ہو سکے دوسروں کو فائدہ پہنچانے کی کوشش کرے، غرضیکہ اپنے تمام مسلمان بھائیوں کے بارے میں اخلاقیات کے تمام تر اوصافِ حمیدہ کو ملحوظ رکھے۔"}],[182,"زیادبن علاقہ روایت کرتے ہیں کہ انہوں نے جریربن عبداللہ رضی اللہ عنہ کو فرماتے سنا کہ:\n’’میں نے نبی صلی اللہ علیہ وسلم سے ہرمسلمان کی خیرخواہی پر بیعت کی۔‘‘","صحیح",{"k":"صحیح بخاری (57)، صحیح مسلم (56)۔"}],[183,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جس سے مشورہ مانگا جائے وہ امانت دار ہوتا ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (5128)، سنن ترمذی (2822)، سنن ابن ماجه (3745)، سلسلہ الأحادیث الصحیحہ (1641)۔","f":"جس طرح ایک امین شخص لوگوں کی امانتوں کی حفاظت کرتاہے اسی طرح وہ شخص کہ جس سے مشورہ لیا جائے امین کے حکم میں ہوتاہے یعنی مشورہ لینے والے کی بات اس کے پاس امانت ہوتی ہے اور اس پر اس امانت کی حفاظت واجب ہے، مشورے کی حفاظت سے مراد کسی اور کو اس بات کی خبر نہ ہونے دینا ہے۔"}],[184,"ابوبرزہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے عرض کیا:\n’’اے اللہ کے رسول!مجھے ایسی بات سکھلا دیجیے جس سے میں فائدہ اُٹھاؤں؟ آپ صلی اللہ علیہ وسلم نے فرمایا:مسلمانوں کے (گزرنے کے)راستے سے تکلیف دہ چیز کو ہٹا دیا کر۔‘‘","صحیح",{"k":"صحیح مسلم (2618)، سنن ابن ماجه (3681)۔","f":"فائدہ اٹھانے سے مراد یہ ہے کہ دنیا میں لوگوں کی محبت کے حصول کی صورت میں فائدہ مل سکے اور آخرت میں اللہ تعالیٰ کی رضا مندی کے حصول کی صورت میں۔"}],[185,"ابوہریرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’میں نے جنّت میں ایک آدمی کو ٹہلتے گھُومتے دیکھا(جس نے عمل یہ کیا تھا کہ)سرِراہ لگے ہوئے ایک ایسے درخت کو کاٹا تھا جو لوگوں کو تکلیف دیتا تھا۔ اور ابو صالح کی روایت میں یہ الفاظ ہیں کہ اس نے راست میں ایک کانٹے دار ٹہنی پڑی دیکھی تو اسے اُٹھا دیا، اللہ تعالیٰ نے اس (کے اس عمل)کی قدر کی اور اسے معاف فرمادیا۔‘‘","صحیح",{"k":"صحیح مسلم (1914)۔","f":"یعنی راستے میں ایک ایسا درخت لگا ہوا تھا(اور ایک روایت کے مطابق کانٹے دار ٹہنی پڑی ہوئی تھی) جس سے گزرنے والے تنگ ہوتے تھے، اس شخص نے وہ درخت اکھاڑ پھینکا (یا وہ ٹہنی اٹھا کر راستے سے ہٹا دی) تا کہ لوگوں کو تکلیف کا سامنا نہ کرنا پڑے۔تو اللہ تعالیٰ نے اس کے اس عمل کے بدلے میں اسے جنت عطا فرما دی۔"}],[186,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جو شخص لوگوں کا شکر یہ ادا نہیں کرتا؛ وہ اللہ تعالی کا بحی شکرگزار نہیں ہوتا۔‘‘","صحیح",{"k":"سنن أبوداؤد (4811)، مسند أحمد (2؍203)، سلسلہ الأحادیث الصحیحہ (416)۔","f":"چونکہ لوگوں کا شکریہ ادا کر نابا لو اسطہ اللہ تعالیٰ ہی کی شکر گزاری ہوتی ہے، کیونکہ جس احسان پر کسی محسن کا شکریہ ادا کیا جاتا ہے اسے وہ احسان کرنے کی توفیق اللہ تعالیٰ نے ہی دی ہوتی ہے، اس لیے محسن کا شکریہ درحقیقت اللہ تعالیٰ کی شکر گزاری ہے، اس لیے یہ فرمایا کہ جو لوگوں کا شکریہ ادا نہیں کرتا حقیقت میں وہ اللہ کا شکر گزار نہیں ہوتا۔"}],[187,"انس رضی اللہ عنہ سے مروی ہے کہ:\n’’مہاجر صحابہؓ نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کیاکہ سارا ثواب تو انصار لے گئے ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا:نہیں، (تب تک تم بھی ثواب پاتے رہوگے)جب تک تم ان کے لیے اللہ تعالیٰ سے دعا کرتے اور ان کی نیکی کو سرا ہتے رہوگے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4812)، سنن ترمذی (2483)۔","f":"مہاجرین کی مدینہ آمد پر انصار نے ان پر بہت سے احسانات کیے اور مواخاۃ قائم ہونے پر اپنے حقیقی بھائیوں سے بھی بڑھ کر ان کے ساتھ بھائی چارے کا اظہار کیا۔ ان کی انہی بڑی بڑی نیکیوں کی وجہ سے مہاجر صحابہؓ نے کہا کہ سارا اجروثواب تو انصار صحابہؓ نے اپنے اعمال ناموں میں لکھوا لیا ہے، تو نبی صلی اللہ علیہ وسلم نے فرمایا: نہیں، جب تک تم ان کے احسانات کے بدلے میں ان کا شکریہ ادا کرنے کے طور پر ان کے لیے دعائیں کرتے رہو گے تب تک تم بھی ثواب کماتے رہو گے۔"}],[188,"جابربن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جسے کوئی چیز دی جائے اور وہ استطاعت رکھتا ہو تو اسے بھی بدلے میں )کوئی چیز(دینی چاہیے، لیکن اگر وہ استطاعت نہیں رکھتا تو اس کی )یعنی وہ چیز دینے وزلے کی(تعریف کر دینی چاہیے، سواگر اس نے اس کی تعریف کردی تو اس نے اس کا شکر یہ ادا کر دیا، لیکن اگر اس نے اسے چھپایا(یعنی تعریف بھی نہ کی)تو اس نے اس کی ناشکری کی، اورجس نے نہ ملنے والی چیز پر شکم سیری کا اظہار کیا وہ جھُوٹ کے دو کپڑے پہننے والے کے مانند ہے۔‘‘","حسن",{"k":"سنن أبوداؤد (4813)، سنن ترمذی (2034)۔"}],[189,"ابنِ عمر رضی اللہ عنہما نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’جو تم سے اللہ کے نام پر(کوئی چیز)مانگے اس کو دو، جو تم سے پناہ مانگے اسے پناہ دو اور جو تمہارے ساتھ نیکی کرے اسے اس کا بدلہ دو، اگر تم(بدلے میں دینے کے لیے کوئی چیز)نہ پاؤ تو اس کے لیے دعا کر دیا کرو، یہاں تک کہ تمہیں یقین ہوجائے کہ تم نے اس کا بدلہ دے دیا ہے اور جو تم سے اور اللہ کے نام پر(دشمن وغیرہ سے)بچنے کے لیے پناہ چاہے تم اسے پناہ دو۔‘‘","صحیح",{"k":"سنن أبوداؤد (5109)، مسند أحمد (2/68-)۔"}],[190,"یحییٰ بن عبداللہ بن صیفی نبی صلی اللہ علیہ وسلم سے مرسل روایت کرتے ہیں کہ:\n’’جس شخص کو کسی نعمت سے نوازا جائے تو اسے اس نعمت کا شکر ادا کرنا چاہیے۔‘‘","",{}],[191,"ابنِ عباس رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’میں نے جہنّم کو دیکھا توآج جیسا منظر میں نے کبھی نہیں دیکھا، اور میں نے جہنّم میں زیادہ ترعورتوں کو دیکھا۔ صحابہؓ نے عرض کیا:ایسا کیوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا:ان کے کفر کی وجہ سے۔ صحابہؓ نے پوچھا:کیا وہ اللہ کے ساتھ کفر کرتی ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا:(نہیں، بلکہ)وہ خاوندوں کی ناشکری کرتی ہیں اور(ان کے)احسان کو نہیں مانتی ہیں، اگرتُوان میں سے کسی پر زندگی بھر احسان کرتا رہے پھر وہ تجھ سے ذرہ سی بھی کوئی کمی محسوس کرے تو کہے گی کہ میں نے تو تجھ سے کبھی بھلائی دیکھی ہی نہیں۔‘‘","صحیح",{"k":"صحیح مسلم (907)۔","f":"آنحضرت صلی اللہ علیہ وسلم نے عورتوں کی فطری خصلت کا تذکرہ فرمایا ہے کہ عورت کبھی بھی اپنے خاوند سے خوش نہیں ہوتی بلکہ اس کے ہزارہا احسانات کے باوصف بھی اگر کبھی کوئی ذرہ سی تنگی آن پڑی تو پچھلے سارے احسانات بھول کر ناشکری کی زبان چلانے لگے گی کہ مجھے تو تم سے کبھی سکون ملا ہی نہیں ہے، ان کی اسی ناشکری، ناقدری اور احسان فراموشی کی وجہ سے آپ صلی اللہ علیہ وسلم نے جہنم میں انہی کی اکثریت دیکھی ہے۔"}],[192,"ابوذر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’تِین لوگ ایسے ہیں کہ جن سے اللہ تعالیٰ روزِقیامت نہ تو بات کرے گا، نہ ان کی طرف دیکھے گا اور نہ ہی انہیں پاک کرے گا، بلکہ ان کے لیے دردناک عذاب ہوگا:کسی کو کچھ دے کر احسان جتلا نے والا، اپنے تہہ بند کو ٹخنوں سے نیچے لٹکانے والا اورجھُوٹی قسم اُٹھا کر اپنے سامان کو بیچنے والا۔‘‘","صحیح",{"k":"صحیح مسلم (106)، سنن أبوداؤد (4087)، سنن ترمذی (1211)، سنن ابن ماجه (2208)۔","f":"اللہ تعالیٰ فرماتا ہے: ﴿لَا تُبْطِلُوا صَدَقَاتِكُمْ بِالْمَنِّ وَالْأَذَى﴾ [البقرة: ۲۶۴] ’’تم اپنے صدقات وخیرات کو احسان جتلا کر اور تکلیف دے کر ضائع مت کرو۔‘‘\nکسی مفلس وحاجتمند پر احسان فقط اللہ کی رضا کے لیے کرنا چاہیے نہ کہ اس سے کسی صلے اور بدلے کی طمع رکھتے ہوئے احسان کا معاملہ کرنا چاہیے، اورجب کوئی احسان کر دیا جائے تو پھر اسے بھول جانا چاہیے اور اس کی جزا کی امید فقط اللہ تعالیٰ سے رکھنی چاہیے اور اپنے ممنون کو اپنے قول وفعل کسی بھی طرح سے اپنی احسان مندی باور نہیں کر انی چاہیے تاکہ اس کی عزتِ نفس مجروح نہ ہو، اور نہ ہی اس کے کسی ناپسندیدہ رویے کے ردِّعمل میں اسے اپنے احسانات یاددِلاکر طعن وملامت کرنے جیسی غلیظ حرکت سے بھی اجتناب کرنا چاہیے کیونکہ احسان جتلا نے سے نہ صرف اس کا اجروثواب ضائع ہو جاتا ہے بلکہ اللہ تعالیٰ کی کلام، اس کی نظرِرحمت اور تزکیے سے بھی محرومی ہوجاتی ہے۔"}],[193,"عیاض بن حمار رضی اللہ عنہ روایت کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے اپنے خطبے میں فرمایا:\n’’یقیناًاللہ تعالیٰ نے مجھے یہ حکم فرمایا ہے کہ تم اسقدر عاجزی اختیا کرو کہ کوئی کسی پر فخر نہ کرے اور کوئی کسی پر زیادتی نہ کرے۔‘‘","صحیح",{"k":"صحیح مسلم (2865)، سنن أبوداؤد (4895)، سنن ابن ماجه (4179)۔"}],[194,"ابوامامہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’سادگی ایمان کا حصہ ہے، سادگی ایمان کا حصہ ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4161)، سنن ابن ماجه (4118)، سلسلہ الأحادیث الصحیحہ (1646)۔"}],[195,"محمدبن اسحاق بیان کرتے ہیں کہ:\n’’ایک دِن اصحابِ رسول رضی اللہ عنہم نے نبی صلی اللہ علیہ وسلم کے پاس دنیا کاذِکر کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا:کیا تم سنتے نہیں ہو؟ کہ سادگی ایمان کا حصہ ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4161)، سنن ابن ماجه (4118)، سلسلہ الأحادیث الصحیحہ (1646)۔"}],[196,"ابنِ عمر رضی اللہ عنہما بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’اللہ تعالٰی فرماتا ہے:جو میرے لیے اس طرح جھک جاتا ہے-آپ صلی اللہ علیہ وسلم نے اپنی دائیں ہتھیلی کو پھیلایا اور اس کے پیٹ(یعنی درمیانی حصے)سے زمین کی طرف اشارہ کیا- اسے اللہ تعالٰی اس طرح بلند فرما دیتا ہے -اور آپ صلی اللہ علیہ وسلم نے اپنی دائیں ہتھیلی کو پھیلایا اور اس کے پیٹ سے آسمان کی طرف اشارہ کیا۔‘‘","صحیح",{"k":"مسند أحمد (1؍44)، صحیح الترغیب والترهیب (2894)۔","f":"نبی صلی اللہ علیہ وسلم نے تواضع کی ترغیب دیتے ہوئے عملی طرز کی مثال سے سمجھایا اور جھکنے کے الفاظ بولتے ہوئے اپنی ہتھیلی سے زمین کی طرف اشارہ کیاکہ یوں جھک جانا جیسے زمین کی طرح سب سے نیچے ہوجائے، اور اس کا انعام یعنی اللہ تعالٰی کی طرف سے بلندی کے حصول کے بابت بتلاتے ہوئے آسمان کی طرف اشارہ فرمایاکہ اس کے صلے میں اللہ تمہیں یوں بلندیاں عطا فرمائے گاجیسے یہ آسمان بلند ہے۔"}],[197,"حارثہ بن وہب خزاعی رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’کیا میں تمہیں جنّتی لوگوں کا نہ بتلاؤں؟ ہرکمزور اور توضع اختیار کرنے والا شخص(جنّتی ہے)اگر وہ اللہ پر قسم بھی ڈال دے تو اللہ اس کی قسم کو پوری کر دیتا ہے، کیا میں تمہیں جہنّمی لوگوں کا نہ بتلاؤں؟ ہراَکھڑ مزاج، اکڑ اکڑ کر چلنے والا اور تکبر کرنے والا(جہنّمی ہے)۔‘‘","صحیح",{"k":"صحیح بخاری (6071)، صحیح مسلم (2853)۔"}],[198,"عبداللہ بن عمرو رضی اللہ عنہما بیان کرتے ہیں کہ:\n’’ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم سے سوال کیا:اسلام کا کونسا کام بہتر ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:(يہ کام کہ)تُوکھاناکھِلائے اورہر واقف ونا واقف شخص کو سلام کہے۔‘‘","صحیح",{"k":"صحیح بخاری (28)، صحیح مسلم (39)۔"}],[199,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’چھوٹا بڑے کو سلام کہے گا، گزرنے والا بیٹھنے والے کو اور تھوڑے لوگ زیادہ لوگوں کو۔‘‘","صحیح",{"k":"صحیح بخاری (6234)۔"}],[200,"ابوہریرہ رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’سوار پیدل کو سلام کہے، چلنے والا بیٹھے ہوئے کو اور تھوڑے لوگ زیادہ لوگوں کو۔‘‘","صحیح",{"k":"صحیح بخاری (6233)، صحیح مسلم (2160)۔"}],[201,"جابر رضی اللہ عنہ فرماتے ہیں:\n’’دو چلنے والے جب اکٹھے ہوتے ہیں تو ان دونوں میں جو سلام میں پہل کرے وہی افضل ہے۔‘‘","صحیح",{"k":"الأدب المفرد للبخاری (143)، صحیح ابن حبان (1935)، سلسلہ الأحادیث الصحیحہ (1146)۔"}],[202,"ابوامامہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’یقیناًلوگوں میں سے اللہ تعالیٰ کے زیادہ قریب وہ شخص ہے جو انہیں پہلے سلام کہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (5197)، صحیح الجامع للألبانی (2011)۔","f":"مندرجہ بالا احادیث میں اس بات کی وضاحت کی گئی ہے کہ پہلے سلام کر ناکس کا فرض ہے؟ تو مختلف نوعیتوں کے حوالے سے مختلف لوگوں کا ذکر فرمایا، یعنی چھوٹا بڑے کو سلام کرے، راہ چلتا شخص بیٹھے ہوئے کو سلام کرے، تھوڑے لوگ زیادہ لوگوں کو سلام کریں اور سوار پیدل چلنے والے کو سلام کرے۔"}],[203,"عبداللہ بن بسر رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم جب کسی کے دروازے پر تشریف لاتے تو سیدھا دروازے کی طرف رُخ کرکے کھڑے نہیں ہوتے تھے بلکہ دروازے کے دائیں یابا ئیں کونے میں کھڑے ہوجاتے اور السلام علیکم کہتے، اور یہ ان دنوں کی بات ہے جب گھروں(کے درو ازاں)پر پر دے نہیں ہوتے تھے۔‘‘","صحیح",{"k":"سنن أبوداؤد (5186)، الأدب المفرد للبخاری (1085)۔","f":"گھر کے دروازے کے بالکل سامنے کھڑے ہو نانا مناسب امر ہے، خاص طور پرجب گھر کے دروازے پہ پردہ نہ ہو، کیونکہ اس طرح گھر کے اندر نگاہ پڑنے کا خدشہ ہوتاہے اور گھر میں مستورات کے علاوہ بھی بہت سے امور ایسے ہوتے ہیں جو سوائے اہلِ خانہ کے کسی اور کے دیکحنے کے لائق نہیں ہوتے، اس لیے نبی کریم صلی اللہ علیہ وسلم دروازے کی دائیں یابا ئیں جانب کھڑے ہوتے تھے۔"}],[204,"ابنِ عباس رضی اللہ عنہما بیان کرتے ہیں کہ:\n’’عمر رضی اللہ عنہ نبی صلی اللہ علیہ وسلم کے پاس تشریف لائے، جبکہ آپ صلی اللہ علیہ وسلم اپنے حجرے میں تشریف فرما تھے، تو حضرت عمرؓنے کہا: «اَلسَّلَامُ عَلَيْكَ يَا رَسُولَ اللّٰهِ! اَلسَّلَامُ عَلَيْكُمْ» کیا عمر اندر آسکتا ہے؟‘‘","صحیح",{"k":"سنن أبوداؤد (5201)، الأدب المفرد للبخاری (4108)۔"}],[205,"ربعی بن حراش بیان کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم گھر تشریف فرما تھے کہ بنو عامر کا ایک شخص آیا اور آپ صلی اللہ علیہ وسلم سے اجازت لیتے ہوئے بولا:کیا میں اندر آسکتا ہوں؟ تو رسول اللہ صلی اللہ علیہ وسلم نے اپنے خادم سے فرمایاکہ اس کے پاس باہر جا کر اسے اجازت لینے کا طریقہ بتاؤ، چنانچہ اس نے اسے جا کر کہا کہ یوں کہو:السلام علیکم، کیا میں اندر آسکتا ہوں؟ )اس نے جب ایسے کہا(تو نبی صلی اللہ علیہ وسلم نے اسے اجازت دے دی اور وہ اندر آگیا۔‘‘","صحیح",{"k":"سنن أبوداؤد (5177)۔"}],[206,"ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’ہم اُبَی بن کعبؓ کی مجلس میں شریک تھے کہ ابو موسٰی اشعری رضی اللہ عنہ غصے کی حالت میں آئے اور(ہمارے پاس آکر)کھڑے ہوگئے اور بولے:میں تمہیں اللہ کا واسطہ دے کر پوچھتا ہوں کیا تم میں سے کسی نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے کہ تین مرتبہ اجازت لی جائے اور اگر اجازت مل جائے تو ٹھیک ہے وگرنہ واپس چلا جائے؟ اُبَیؓ نے پوچھا:ہوا کیا ہے؟ انہوں نے جواب دیا کہ میں نے کل عمربن خطاب رضی اللہ عنہ سے(ان کے پاس حاضر ہو نے کی) تین مرتبہ اجازت مانگی لیکن انہوں نے مجھے اجازت نہیں دی، سومیں واپس چلا آیا۔ پھرآج میں ان کے پاس گیا اور انہیں بتلایا کہ میں کل بھی آیا تھا اور تین مرتبہ سلام کہا(یعنی اندر آنے کی اجازت مانگی، لیکن اجازت نہیں ملی)تو میں واپس چلا گیا، تو انہوں نے جواب دیا کہ ہم نے تمہارا سلام سنا تو تھا لیکن ہم اس وقت کسی کام میں مشغول تھے، تو تم تب تک اجازت کیوں نہ مانگتے رہے جب تک کہ تمہیں اجازت دے نہ دی جاتی؟ میں نے کہا:میں نے تو اسی طریقے کے مطابق اجازت مانگی تھی جو میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا تھا۔ انہوں نے کہا:قسم بخدا!یاتوتُواپنی اس بات پر کوئی گواہ لے کرآ، یاپھر میں تیری پُشت اور پیٹ کو ضرور تکلیف سے دو چار کروں گا(یعنی تمہیں سزا دوں گا)، اُبَی بن کعبؓ نے(یہ سُن کر)فرمایا:اللہ کی قسم!تیرے ساتھ (گواہی کے لیے)ہم میں سب سے کم عمر کھڑا ہوگا، اے ابوسعید!اُٹھو۔ چنانچہ میں اُٹھا اور عمر رضی اللہ عنہ کے پاس جا کر کہا کہ:میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے سنا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (6245)، صحیح مسلم (2153)۔"}],[207,"جابر رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’میں اپنے باپ پر قرض کے مسئلے میں رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوا، میں نے دروازہ کھٹکھٹایا تو آپ صلی اللہ علیہ وسلم نے فرمایا:کون ہے؟ تو میں نے کہا:میں، آپ صلی اللہ علیہ وسلم نے فرمایا:میں، میں۔ گویا کہ آپ صلی اللہ علیہ وسلم نے اس انداز کو ناپسند فرمایا۔‘‘","صحیح",{"k":"صحیح بخاری (6250)، صحیح مسلم (2155)۔","f":"یعنی اگر صاحبِ خانہ آنے والے سے اس کا نام پوچھے تو اسے اپنا نام ہی بتانا چاہیے نہ کہ یوں کہنا چاہیے کہ ’’میں ہوں‘‘ نبی صلی اللہ علیہ وسلم نے ایسا کہنے کو ناپسند فرمایا ہے۔"}],[208,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب تم میں سے کوئی مجلس میں آئے تو اسے سلام کہنا چاہیے، سوا گروہ کھڑا ہو اور لوگ بیٹھے ہوں تو اسے ہی سلام کہنا چاہیے، کیونکہ پہلا دوسرے کی نسبت زیادہ حق نہیں رکھتا۔‘‘","حسن",{"k":"سنن أبوداؤد (5208)، سنن ترمذی (2706)، مسند أحمد (2؍287)۔"}],[209,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ انہوں نے آپ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’جو اپنے (مسلمان)بھائی کو ملے تو اسے سلام کہنا چاہیے، اگر ان دونوں کے درمیان درخت، دیوار یاپتھر حائل ہوجائے اورجب وہ اس سے ملے تو اسے پھر سلام کہنا چاہیے۔‘‘","صحیح",{"k":"سنن أبوداؤد (5200)۔"}],[210,"عمران بن حصین رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’ہم نبی صلی اللہ علیہ وسلم کے پاس بیٹھے ہوئے تھے کہ ایک آدمی آیا اور اس نے «اَلسَّلَامُ عَلَيْكُمْ» کہا، تو رسول اللہ صلی اللہ علیہ وسلم نے اس کا جواب دیا اور فرمایا:)اس نے(دس نیکیاں)حاصل کیں(۔ پھر دوسرا آیا اور اس نے «اَلسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللّٰهِ» کہا تو نبی صلی اللہ علیہ وسلم نے اس کا جواب دیا اور فرمایا:)اس نے(بِیس نیکیاں)حاصل کیں(۔ پھر ایک اور شخص آیا اور اس نے «اَلسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللّٰهِ وَبَرَكَاتُهُ» کہا، تو آپ صلی اللہ علیہ وسلم نے اس کا بھی جواب دیا اور فرمایا:)اس نے(تِیس نیکیاں)حاصل کیں(۔‘‘","صحیح",{"k":"سنن أبوداؤد (5195)، سنن ترمذی (2689)، عمل الیوم والیلہ للنسائی (118)۔"}],[211,"سیدنا علی بن ابی طالب رضی اللہ عنہ مرفوعاًروایت کرتے ہیں کہ:\n’’جب کوئی جماعت گزرے اور ان میں سے ایک بندہ بھی سلام کردے تو اس جماعت کفایت کر جائے گا، اور(اسی طرح)مجلس میں سے ایک بھی شخص سلام کا جواب دے دے تو ان سب کو کفایت کر جائے گا۔‘‘","صحیح",{"k":"سنن أبوداؤد (5210)، سلسلہ الأحادیث الصحیحہ (1148)۔","f":"یعنی اگر زیادہ لوگ ہوں اور انہوں نے کسی کو سلام کہنا ہو یاپحر انہیں کوءی شخص سلام کہہ دے تو پوری جماعت کا سلام کہنا یاسب کا جواب دینا ضروری نہیں ہے بلکہ ان میں سے ایک شخص بھی سلام کہہ دے یاسلام کرنے والے کا جواب دے دے تو تمام کی طرف سے کفایت کر جاتا ہے۔"}],[212,"انس بن مالک رضی اللہ عنہ روایت کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم بچوں کے پاس سے گزرے تو انہیں سلام کہا۔‘‘","صحیح",{"k":"صحیح بخاری (6247)، صحیح مسلم (2168)۔"}],[213,"اسماء بنت یزید رضی اللہ عنہا بیان کرتی ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم ہم عورتوں کے پاس سے گزرے تو آپ صلی اللہ علیہ وسلم نے ہمیں سلام کہا۔‘‘","صحیح",{"k":"سنن أبوداؤد (5204)، سنن ترمذی (2697)۔","f":"امام بیہقیؒ فرماتے ہیں کہ اس پر وہی شخص عمل کر سکتا ہے جسے عورتوں کے فتنے سے محفوظ رہنے میں اپنے آپ پر اعتماد ہو، یاپھر ان عورتوں کو سلام کہا جا سکتا ہے جن کی شادی کی عمر گزر چکی ہو، لیکن اگر کسی کو عورتوں کے فتنے سے محفوظ رہنا ممکن نظر نہ آتا ہویا جسے وہ سلام کرنا چاہے وہ نوجوان عورت ہو تو ایسی صورت میں سلام نہیں کرنا چاہیے۔"}],[214,"سہیل بن ابی صالح بیان کرتے ہیں کہ:\n’’میں اپنے باپ کے ساتھ شام کی طرف گیا تو لوگ عیسائیوں کی عبادت گاہوں کے پاس سے گزرتے ہوئے انہیں سلام کہتے تھے، تو میرے والد نے کہا:تم انہیں سلام کرنے میں پہل نہ کرو، کیونکہ ہمیں ابوہریرہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے یہ حدیث روایت کرتے ہوئے بیان کی ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا:تم انہیں سلام میں پہل مت کرو اورجب راستے میں تمہارا ان سے سامنا ہو جائے تو انہیں تنگ ترین راستے کی طرف مجبور کر دو۔‘‘","صحیح",{"k":"صحیح مسلم (2167)، سنن أبوداؤد (5205)، سنن ترمذی (2700)۔","f":"اس روایت میں دو چیزیں بیان ہوئی ہیں: ایک یہ کہ غیر مسلم لوگوں کو سلام کرنے میں پہل نہیں کرنی چاہیے اور دوسری یہ کہ اگر راستے میں کہیں ان کا سامنا ہو جائے تو ان کے گزرنے کے لیے راستہ تنگ کر دیا جائے۔ یہ حکم اس لیے ہے تا کہ انہیں اپنی کمتری اور مسلمانوں کے غلبے کا احساس ہو سکے۔"}],[215,"ابنِ عمر رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’یقیناًجب یہودی تمہیں سلام کرتے ہیں تو وہ «اَلسَّامُ عَلَيْكُمْ» (یعنی تم پر موت آئے)کہتے ہیں، سوتم انہیں «وَعَلَيْكُمْ» (اور تم پر بھی)کہہ کر جواب دے دیا کرو۔‘‘","صحیح",{"k":"صحیح بخاری (6257)، صحیح مسلم (2164)۔","f":"وَعَلَيْکُمْ کہنے میں حکمت یہ ہے کہ جیسا اس نے کہا ہو گا ویسا ہی اسے جواب مل جائے گا۔ یعنی اگر تو اس نے واقعی سلامتی کی دعا دی ہو گی تو جو اباً اسے بھی سلامتی کی دعا مل جائے گی اور اگر اس نے سلام کے دھوکے میں سام یعنی موت کی بدعا دی ہو گی تو جو اباً اسے بھی ویسے ہی بددعا مل جائے گی۔"}],[216,"ام المومنین سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ:\n’’چند یہودی رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور انہوں نے «اَلسَّامُ عَلَيْكَ» (یعنی تم پر موت آئے)کہا، تو ہم سمجھ گئے۔ چنانچہ میں نے جو «اباً عَلَيْكُمُ السَّامُ وَاللَّعْنَةُ» (یعنی تم پر موت آئے اور لعنت ہو)کہہ دیا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:عائشہ!چھوڑو(ایسے نہ کہو)، کیونکہ اللہ تعالیٰ ہرمعا ملے میں نرمی کو پسند فرماتا ہے۔ میں نے عرض کیا:اے اللہ کے رسول!کیا آپ صلی اللہ علیہ وسلم نے نہیں سنا جو انہوں نے کہا ہے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:میں نے «وَعَلَيْكُمْ» کہہ کر جواب دے دیا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (6256)، صحیح مسلم (2165)۔","f":"غیرمسلموں کے سلام کے جواب میں وَعَلَيكُمکہنے کی حکمت یہ ہے کہ اگر تو انہوں نے سلام ہی کہا ہوگا تو انہیں ان کے سلام کا جواب مل جائے گالیکن اگر انہوں نے سلامتی کی دعا کے بجائے موت کی بددعا دی ہو تو انہیں بھی وہی جواب مل جائے گا۔"}],[217,"ابنِ عباس رضی اللہ عنہما روایت کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے شاہِ رُوم ہرقل کے نام یہ پیغام لکھا کہ ہراس شخص پر سلامتی ہو جو بھی ہدایت کی پیروی کرے۔‘‘","صحیح",{"k":"صحیح بخاری (7)۔","f":"شاہِ رُوم جوکہ نصرانی تھا، نبی صلی اللہ علیہ وسلم نے اسے بھی سلام نہیں لکھا بلکہ «سَلَامٌ عَلٰى مَنِ اتَّبَعَ» الْهُدٰىلکھا، مراد یہ تھا کہ اگر تم ہدایت کی پروی کروگے تو تم پر سلامتی ہوگی۔"}],[218,"ابوذر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’اے ابوذر!تُوکسی بھی نیکی کو ہرگز حقیرمت سمجھ، خواہ وہ نیکی یہی ہوکہ تُواپنے (مسلمان)بھائی کو خندہ پیشانی سے ملے، اور اگرچہ (وہ نیکی یہ ہوکہ)تُوپانی مانگنے والے کے برتن میں اپنے ڈول سے پانی ڈال دے، اورجب تُوہا نڈی پکائے تو اس کا شوربہ زیادہ بنا لیا کر اور اس سے اپنے پڑوسی کو بھی دے دیا کر۔‘‘","صحیح",{"k":"صحیح مسلم (2625)، سنن ترمذی (1833)۔"}],[219,"قتادہ بیان کرتے ہیں کہ:\n’’میں نے انس رضی اللہ عنہ نے پوچھا:کیا نبی صلی اللہ علیہ وسلم کے صحابہ مصافحہ کیا کرتے تھے؟ تو انہوں نے جواب دیا:جی ہاں۔‘‘","صحیح",{"k":"صحیح بخاری (6263)۔"}],[220,"زراع رضی اللہ عنہ، جو عبدالقیس کے وفد میں شامل تھے، بیان کرتے ہیں کہ:\n’’ہم اپنی سواریوں سے جلدی جلدی اُترکر رسول اللہ صلی اللہ علیہ وسلم کے ہاتھ اور پاؤں کو بوسے دینے لگے۔‘‘\n’’جب وہ شام تشریف لائے تو ابوعبیدہ بن جراح رضی اللہ عنہ نے ان کا استقبال کیا اور ان کے ہاتھ کو بوسہ دیا۔‘‘","حسن",{"k":"سنن أبوداؤد (5225)۔","f":"سیدنا عمربن خطاب رضی اللہ عنہ بیان کرتے ہیں کہ:أَنَّهُ «لَمَّا قَدِمَ الشَّامَ اسْتَقْبَلَهُ أَبُو عُبَيْدَةَ بْنُ الْجَرَّاحِ فَقَبَّلَ يَدَهُ»."}],[221,"سیدہ عائشہ رضی اللہ عنہا واقعہ اِفک کے بابت روایت کرتی ہیں کہ:\n’’میرے ماں باپ نے مجھ سے کہا:اُٹھوا اور رسول اللہ صلی اللہ علیہ وسلم کے سَرکو بوسہ دو۔‘‘","صحیح",{"k":"سنن أبوداؤد (5219)۔"}],[222,"اسیدبن حضیر رضی اللہ عنہ روایت کرتے ہیں کہ:\n’’جس وقت نبی صلی اللہ علیہ وسلم نے ان کی کوکھ میں لکڑی چبھوئی تو انہوں نے قصاص مانگ لیا، تو نبی صلی اللہ علیہ وسلم نے اپنا قمیض اُٹھا دیا اوراُسید آپ صلی اللہ علیہ وسلم کے پیٹ سے چمٹ گئے اور آپ صلی اللہ علیہ وسلم کے پہلُوکو چومنے لگے۔‘‘","صحیح",{"k":"سنن أبوداؤد (5224)۔","f":"كَشْحٌسے مراد کوکھ اور پسلیوں کے درمیان کی جگہ ہے۔ اس روایت سے صحابہ کرام رضی اللہ عنہم کی نبی کریم صلی اللہ علیہ وسلم سے محبت اور وار فتگی کا اندازہ ہوتاہے کہ وہ کس درجے تک رسول اللہ صلی اللہ علیہ وسلم سے پیار کرتے تھے، علاوہ ازیں اس سے یہ بات بھی احاطۂ علم میں آتی ہے کہ آدمی کا اپنی محبوب شخصیت کے جسم کو بوسہ دینا جائز ہے۔"}],[223,"انس بن مالک رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’ایک دوسرے سے بُغض مت رکھو، باہم حسدمت کرو اور ایک دوسرے سے منہ نہ موڑو اور اللہ کے بندو!بھائی بھائی بن جاؤ، کسی مسلمان کے لیے جائز نہیں ہے کہ وہ اپنے(مسلمان)بھائی سے تین دِن سے زیادہ بول چال چھوڑے رکھے اورجب وہ آپس میں ملیں تو یہ اس سے منہ پھیر لے اور وہ اس سے منہ پھیر لے، ان دونوں میں سے بہتر وہ ہوگا جو سلام میں پہل کرے۔‘‘","صحیح",{"k":"صحیح بخاری (6065)، صحیح مسلم (2559)۔"}],[224,"ہشام بن عامر انصاری رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’کسی مسلمان کے لیے جائز نہیں ہے کہ وہ اپنے مسلمان بھائی سے تین دِن سے زیادہ قطع تعلقی کرے، وہ جب تک آپس میں قطع تعلق رہتے ہیں تب تک حق سے ہٹے رہتے ہیں، اور ان میں سے جو پہلے اپنے غصے کو ختم کرتاہے تو اس کا غصہ ختم کرنے میں پہل کرنا اس کے لیے کفارہ بن جائے گا، پھر اگر وہ دوسرے کو سلام کہتا ہے اور وہ اس کے سلام کو قبول نہیں کرتا اور نہ ہی اسے جواب دیتا ہے تو اس کے سلام کا جواب فرشتے دیتے ہیں جبکہ دوسرے کو شیطان جواب دیتا ہے، لیکن اگر(ان میں سے کوئی بھی ناراضگی ختم نہ کرے اور)وہ قطع تعلقی میں ہی انہیں موت آجائے تو وہ دونوں جنت میں نہیں جا سکیں گے۔ یافرمایا کہ وہ دونوں جنت میں ایک ساتھ نہیں رہ سکیں گے۔‘‘","صحیح",{"k":"مسند الطیالسی (1223)، الأدب المفرد للبخاری (402)۔"}],[225,"ابو خراش سُلمی رضی اللہ عنہ روایت کرتے ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\nجس نے اپنے (مسلمان)بھائی سے ایک سال تک بول چال چھوڑے رکھی، تو وہ(بہ اعتبارِگناہ)اس کا خون بہانے کے مثل ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4915)، مسند أحمد (4؍320)، سلسلہ الأحادیث الصحیحہ (928)۔"}],[226,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’سوموار اور جمعرات کے دِن جنّت کے دروازے کھولے جاتے ہیں اور ہراس بندۂ مومن کو بخش دیا جاتا ہے جو اللہ کے ساتھ کسی کو بھی شریک نہ ٹھہراتا ہو، سوائے اس شخص کے جس کی اپنے بھائی کے ساتھ عداوت ہو، تو(ان کے بارے میں یہ)کہا جاتا ہے کہ انہیں تب تک چھوڑے رکھوجب تک کہ یہ صلح نہیں کرلیتے۔‘‘","صحیح",{"k":"صحیح مسلم (2565)، سنن أبوداؤد (4916)، سنن ترمذی (2023)۔","f":"یعنی باہم ناراض دو مسلمان بھائیوں کو تب تک بخشش سے محروم رکھا جاتا ہے جب تک وہ صلح نہیں کرلیتے۔"}],[227,"انس رضی اللہ عنہ روایت کرتے ہیں کہ نبی صلی اللہ علیہ وسلم اپنی کسی بیوی کے ساتھ(جارہے)تھے کہ ایک آدمی گزر ارو آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’اے فلاں!یہ میری فلاں بیوی ہے۔ اس نے عرض کیا:اے اللہ کے رسول!میں کون ہوتا ہوں کہ ایسا گمان کروں؟ اور نہ ہی آپ کے بارے میں کوئى گمان کیا ہے۔، تو آپ صلی اللہ علیہ وسلم نے فرمایا:یقیناًشیطان ابنِ آدم کے جسم میں خون کے چلنے کی جگہ پر دوڑتا ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2174)، سنن أبوداؤد (4719)۔","f":"شیطان انسان کے جسم میں خون کی طرح گردش کرتا ہے اور اس میں اپنے وساوس اور خیالات ڈالنے کی کوشش کرتا ہے، اسی لیے نبی صلی اللہ علیہ وسلم نے اس صحابیؓ سے وضاحت فرما دی تا کہ شیطان اس کے دل میں کوئی برا خیال نہ ڈال دے۔"}],[228,"ابوموسیٰ رضی اللہ عنہ بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’نیک ہم نشین کی مثال اور برے ہم نشین کی مثال کستوری اٹھانے والے اور بھٹی دھونکنے والے کے مِثل ہے۔ سوجو کستوری اٹھانے والا ہے وہ یاتو تجھے دے دے گا، یاتُواس سے اس سے خرید لے گااور یاتُواس سے اچھی خوشبو ہی پالے گا۔ اور جو بھٹی دھونکنے والا ہے وہ یاتو تیرے کپڑے جلا دے گا، یاپھرتُواس سے بدبُوہی پائے گا۔‘‘","صحیح",{"k":"صحیح بخاری (2101)، صحیح مسلم (2628)۔","f":"اسی طرح اچھے شخص کی صحبت سے اس سے کچھ نہ کچھ فائدہ ہی حاصل ہوگا، یاتو وہ خود کوئی فائدے کی بات بتا دے گا، اگر وہ خود نہیں بتاتا تو تم اس سے پوچھ سکتے ہو، اور اگر یہ دونوں ہی نہ ہوں توکم ازکم اس کی صحبت کے اثر سے ہی تم اچھی عادات وخصائل اپنا لوگے، اور اس کے برعکس بُراصحبت نشین ہے، وہ جب بھی کوئی بات بتائے گاتوبے فائدہ اور نقصان کی بات ہی بتائے گااور اگر وہ کچھ نہ بھی بتائے تو اس سے کسی طور بھی چنداں کوئی فائدہ نہیں ہو سکتا بلکہ اس کی صحبت کے اثر سے تم بھی بری عادات وخصائل کے حامل ہو جاؤگے۔"}],[229,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’آدمی اپنے دوست کے دِین پر ہی ہوتاہے، سوتم میں سے (ہر)شخص کو یہ دیکھنا چاہیے کہ وہ کسے دوست بناتا ہے۔‘‘","حسن",{"k":"سنن أبوداؤد (4833)، سنن ترمذی (2378)، مسند أحمد (2؍334)، سلسلہ الأحادیث الصحیحہ (927)۔","f":"آدمی کے دوستوں کو دیکھ کر ہی اس کا اندازہ ہو جاتا ہے کہ یہ کیسے کر دارو سیرت کا حامل ہے، کیونکہ انسان اپنے دوستوں کے دِین یعنی طور وطرز اور انہی کے طریق ونہج پر ہوتا ہے، اس لیے کسی کو اپنانا دوست بنانے سے پہلے اس کے جمیع امور وخصائل کوبہ خوبی ملاحظہ کرنا چاہیے تاکہ اُس کے درست نہ ہونے پراِس کا شمار بھی اسی کے ساتھ نہ کیا جا نے لگے۔"}],[230,"ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’تُوصرف مومن شخص کو ہی اپنا ساتھی بنا اور تیرا کھانا صرف متّقی شخص ہی کھائے۔‘‘","حسن",{"k":"سنن أبوداؤد (4832)، سنن ترمذی (2395)، صحیح الجامع للألبانی (7341)۔"}],[231,"سیدہ عائشہ رضی اللہ عنہا رسول اللہ صلی اللہ علیہ وسلم سے روایت کرتی ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’رُوحوں کے لشکر کے لشکر الگ الگ ہیں، سوجو(عالمِ ارواح میں)ایک دوسرے سے متعارف تھیں(دنیا میں آکر)ان میں محبت ہوگئی، اور جو وہاں ایک دوسرے سے ناواقف تھیں، ان(کا دنیا)میں بھی اختلاف ہی رہا۔‘‘","صحیح",{"k":"صحیح بخاری (3336)، صحیح مسلم (2638)۔","f":"یہ محبت اور اختلاف روحانی مناسبت سے ہے، اس حدیث میں یہ بیان ہے کہ جب عالمِ ارواح میں رُوحوں کے لشکر کے لشکر موجود تھے تو جورُوحیں دنیا میں آنے سے پہلے وہاں ایک دوسرے سے متعارف ہوگئیں تھیں، دنیا میں آکر ان کی باہم محبت ہوگئی، لیکن جن کا وہاں آپس میں مزاج نہ مل سکا وہ دنیا میں آکر بھی ایک دوسرے کے مخالف ہی رہِیں۔ مثال کے طور پر نیک شخص کا مزاج نیک سے ہی ملتا ہے اور اسی کو اپنا صحبت نشیں اور مجلس نشیں بنائے گا، اسی طرح بُرے شخص کی عادات بُرے سے ہی میل کھاتی ہیں اور وہ اسی سے ہی میل جول رکھے گا، اور ان دونوں طرح کے یعنی نیک اوربُرے لوگوں کا آپس میں چنداں مزاج نہیں ملتا اور نہ ہی ان کی عادات وخصائل میں کچھ مماثلت ہے، اس لیے یہ عالمِ ارواح میں بھی ایک دوسرے سے مانوس نہ ہو سکیں اور دنیا میں آکر بھی ان کا آپس میں اختلاف ہی رہا۔"}],[232,"ابو سعید خدری رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’لوگوں میں سے زیادہ فضیلت کا حامل کون شخص ہے؟ صحابہؓ نے عرض کیا:اللہ اور اس کے رسول ہی بہتر جانتے ہیں۔ آپ صلی اللہ علیہ وسلم نے تین مرتبہ بار بار یہی فرمایا تو صحابہؓ نے کہا:جو راہِ خدا میں اپنے مال اور اپنی جان کے ساتھ جہاد کرے۔ آپ صلی اللہ علیہ وسلم نے فرمایا:پھر کون؟ صحابہؓ عرض گزار ہوئے کہ اللہ اور اس کے رسول ہی بہتر جانتے ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا:جو کسی گھاٹی میں علٰیحدگی اختیار کر لے، اپنے رب سے ڈرتا ہو اور لوگوں کو اپنی برائی(سے بچانے کے لیے)چھوڑ دے۔‘‘","صحیح",{"k":"صحیح بخاری (2786)، صحیح مسلم (1888)۔","f":"رہبانیت اور گوشہ نشینی ویسے تو اسلام کی نظر میں ناجائز ہے لیکن اگر لوگوں کے ساتھ رہنے سے دِین کو نقصان پہنچتا ہو اور وہ تعبدی امور کو بجا نہ لاسکتا ہویا پھر اس کی وجہ سے لوگوں کو ضرر پہنچتا ہو تو پھر گوشہ نشینی اختیار کرنا افضل ہے، لیکن اگر اس کا لوگوں کے ساتھ مل جل کر رہنا لوگوں کے حق میں مفید ہو، ان کی اصلاح وتر بیت کا باعث ہو اور وہ لوگوں کے مصائب پر صبر بھی کر سکتا ہو تو ایسی صورت میں لوگوں کے ساتھ مل جل کر رہنا ہی افضل ہے اس صورت میں گوشہ نشینی اختیار کرنا جائز نہیں ہے۔"}],[233,"ابنِ عمر رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’لوگ ایسے ہوجائیں گے جیسے سواونٹوں میں سواری کے قابل ایک اونٹ بھی نہیں ہوتا۔‘‘","صحیح",{"k":"صحیح مسلم (2547)، مسند أحمد (2؍109)۔","f":"امام بیہقیؒ فرماتے ہیں کہ اس کا معنٰی یوں کیا گیا ہے کہ لوگ احکامِ دین میں برابر ہو جائیں گے، کسی صاحبِ حیثیت کو عام شخص پر چنداں فضیلت نہیں ہوگی۔ ’’سواونٹوں کی طرح ہوجائیں گے جن میں کوئی سواری کا اونٹ نہیں ہوگا‘‘ اس میں مذکور لفظ رَاحِلَةٌ اس چیز پر دلالت کرتاہے جوکُوچ کر جاتی ہے، اور اس کا مطلب یہ ہوا کہ اکثر لوگ ردّی ہوں گے، لہذاتُوان کی صحبت میں زیادہ مت رہ، اور لوگوں میں سے اہلِ فضل(نیکوکار لوگ)ہی انجام کا قصد کریں گے لیکن ان کی تعداد بہت تھوڑی ہوگی (ایسے ہی )جیسے بوجھ اٹھانے والے اونٹوں میں (تھوڑے سے)سواری کے قابل اونٹ ہوتے تھے۔"}],[234,"مرد اس اسلمی رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’نیک لوگ ایک ایک کرکے (دنیا سے)چلے جائیں گے اور ان کے بعدجَویا کھجور کے بھوسے کے مثل لوگ باقی رہ جائیں گے، اللہ تعالٰی کو ان کی چنداں پرواہ نہیں ہوگی۔‘‘","صحیح",{"k":"صحیح بخاری (6434)، مسند أحمد (4؍193)۔","f":"«حُفَالَةٌ» کا مطلب ہے کسی بھی چیز کا باقی بچ جانے والا ناکارہ اور خراب حصہ، جسے ہم بھوسہ یاتلچھٹ کہتے ہیں۔ تو گویا دنیا کے بہترین لوگ اللہ تعالٰی کے نیکوکار بندے ہیں اور ان کے دنیا سے گزر جا نے کے بعد باقی سب ناکارہ لوگ ہی رہ جائیں گے، جن کا ہو نایا نہ ہونا اللہ تعالٰی کی نظر میں برابر ہے۔"}],[235,"سیدنا عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب تم تین لوگ ہو تو دو آدمی اپنے(تیسرے)ساتھی کو چھوڑ کر آپس میں سرگوشی نہ کریں، کیونکہ یہ بات اس (تیسرے)شخص کو پریشان کرے گی۔ اور ایک روایت میں یہ اضافہ ہے کہ(وہ دونوں تب تک سرگوشی نہ کریں)جب تک کہ وہ لوگوں میں گھُل مِل نہیں جاتے۔‘‘","صحیح",{"k":"صحیح بخاری (6290)، صحیح مسلم (2184)۔","f":"اس حدیثِ مبارکہ میں یہ بیان ہوا ہے کہ اگر ایک جگہ پر تین لوگ موجود ہوں تو ان میں سے دو لوگوں کو آپس میں سرگوشی نہیں کرنی چاہیے۔ اس ممانعت کی وجہ یہ خدشہ ہے کہ اس تیسرے شخص کے دل میں یہ خیال پیدا ہو سکتا ہے کہ شاید انہوں نے میرے بارے میں کوئی بات کی ہو جو مجھ سے چھپائی ہے۔ یہ خیال اسے پریشان کر سکتا ہے اور کسی مسلمان کو پریشان کرنا بہ جائے خود ایک گناہ ہے۔"}],[236,"کعب بن مالک رضی اللہ عنہ کی توبہ والی حدیث میں ہے کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے تو کہا:\n’’لوگ مجھے فوج درفوج ملے اور وہ معافی کی مبارکباد دے رہے تھے، جب میں مسجد میں داخل ہوا تو طلحہ بن عبیداللہؓ لپک کر آئے اور مجھ سے مصافحہ کیا اور مبارکباد دی، مہاجرین میں سے ان کے علاوہ کوئی شخص اُٹھ کر میری طرف نہیں آیا، اور میں طلحہؓ کی اس بات کو کبھی نہیں بھول سکوں گا۔‘‘","صحیح",{"k":"صحیح بخاری (4418)، صحیح مسلم (2769)۔"}],[237,"ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’جب(یہودیوں کے قبیلہ)بنوقریظہ نے سعد رضی اللہ عنہ کے حکم پر ہتھیار ڈال دیے تو رسول اللہ صلی اللہ علیہ وسلم نے ان کی طرف(آدمی)بھیجا، وہ گدھے پر سوار ہو کر آئے، جب پاس آگئے تو نبی صلی اللہ علیہ وسلم نے فرمایا:اپنے سردار کے استقبال کے لیے کھڑے ہوجاؤ۔‘‘","صحیح",{"k":"صحیح بخاری (3804)، صحیح مسلم (1768)۔"}],[238,"شعبہ بیان کرتے ہیں کہ:\n’’جب وہ مسجد کے قریب آگئے تو رسول اللہ صلی اللہ علیہ وسلم نے انصار سے فرمایا:اپنے سردار، یا(فرمایا:)اپنے بہترین شخص کے استقبال کے لیے کھڑے ہوجاؤ۔‘‘","",{}],[239,"سیدہ فاطمہ رضی اللہ عنہا بیان کرتی ہیں کہ:\n’’جب وہ نبی صلی اللہ علیہ وسلم کے پاس آتیں تو آپ صلی اللہ علیہ وسلم ان کے استقبال میں کھڑے ہوجاتے، ان کا ہاتھ پکڑ کر اسے چومتے اور انہیں اپنی نشست پر بٹھاتے اورجب آپ صلی اللہ علیہ وسلم ان کے پاس تشریف لاتے تو وہ آپ صلی اللہ علیہ وسلم کے استقبال میں کھڑی ہو جاتیں، آپ صلی اللہ علیہ وسلم کا ہاتھ پکڑ کر چومتیں اور آپ صلی اللہ علیہ وسلم کو اپنی نشست پر بٹھاتیں۔‘‘","صحیح",{"k":"سنن أبوداؤد (5217)۔"}],[240,"طارق بن عبدالرحمان احمسی بیان کرتے ہیں کہ:\n’’ہم شعبیؒ کے دروازے پر بیٹھے ہوئے تھے کہ جریربن یزیدبن جریربن عبداللہ تشریف لائے، شعبیؒ نے ان کے لیے تکیہ منگوایا، ہم نے ان سے عرض کیا:اے ابوعمرو!آپ کے اردگرد بزرگ لوگ بیٹھے ہوئے ہیں مگر جو نہی یہ لڑکا آیا ہے آپ نے اس کے لیے تکیہ منگوا لیا؟ انہوں نے کہا:جی ہاں، یقیناًرسول اللہ صلی اللہ علیہ وسلم نے اپنے جدِّامجد کے لیے تکیہ رکھا تھا اور فرمایا کہ جب تمہارے پاس قوم کا معزّزشخص آئے تو اسکی عزت کیا کرو۔‘‘","حسن",{"k":"سلسلہ الأحادیث الصحیحہ (1205)۔","f":"کسی معزز شخص کے استقبال میں کھڑے ہونے کی مذکورہ تمام احادیث ایسی صورت کے بارے میں ہیں کہ وہ شخص خود یہ پسند نہ کرتا ہو کہ جب وہ آئے تو لوگ اس کے لیے کھڑے ہوں، اور اگر کوئی شخص اپنے لیے ایسا اکرام خود پسند کرتا ہو، جیسا کہ ہمارے حکام یا انکساری سے عاری امراء طبقہ، تو ایسے شخص کے بارے میں شدید وعید وارد ہوئی ہے جو آئندہ حدیث میں مذکور ہے۔"}],[241,"سیدنا معاویہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’جو شخص یہ پسند کرے کہ لوگ اس کے لیے کھڑے رہیں تو اسے اپنا ٹھکانہ (جہنم کی)آگ میں بنا لینا چاہیے۔‘‘","صحیح",{"k":"سنن أبوداؤد (5229)، سنن ترمذی (2755)، مسند أحمد (4؍91)، سلسلہ الأحادیث الصحیحہ (357)۔","f":"امام بیہقیؒ فرماتے ہیں کہ یہ وعید اس صورت میں ہے کہ جس کے لیے کھڑا ہوا جائے وہ خود اس بات کاحکم دے کہ لوگ اس کی آمد پر اس کے استقبال میں کھڑے ہوں اور تکبرو بڑائی کی بناء پر ان پر اس بات کو لازمی کردے اور پھرجب وہ بیٹھ جائے تو لوگ اس کے سامنے سیدھے کھڑے رہیں، یعنی وہ انہیں بیٹھنے کونہ کہے بلکہ ان کا کھڑے رہنا اسے اچھا لگتا ہو۔"}],[242,"ابنِ عمر رضی اللہ عنہما بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے اس بات سے منع فرمایا ہے کہ کسی آدمی کو اس کی جگہ سے اُٹھا کر کوئی دوسرا شخص اس کی جگہ پر بیٹھ جائے، لیکن تم کشادہ اور وسیع ہو جایا کرو۔‘‘","صحیح",{"k":"صحیح بخاری (6270)، صحیح مسلم (2177)۔","f":"کیونکہ جو شخص پہلے آ کر بیٹھا ہے وہی اس جگہ پر بیٹھنے کا حقدار ہے، بعد میں آنے والے کا اسے اٹھا کر خود وہاں بیٹھ جانا اس شخص کی حق تلفی ہے، اس لیے اس سے منع فرمایا گیا۔ البتہ اس کا حل بتلا دیا گیا کہ بہ جائے کسی کو اٹھانے کے مجلس کشادہ کر لی جائے اور تھوڑا کھلے کھلے ہو لیا جائے تا کہ نیا آنے والا بھی باآسانی بیٹھ سکے۔"}],[243,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب تم میں سے کوئی اپنی جگہ سے جہاں وہ بیٹھا ہواُٹھ کر جائے، پھر وہ واپس آئے تو اپنی اس جگہ پر بیٹھنے کا وہی زیادہ حق رکھتا ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2179)، سنن ابن ماجه (3717)۔","f":"یعنی اگر کوئی شخص کسی ضرورت کے باعث مجلس سے اٹھ کر جاتا ہے تو کسی اور کو اس کی جگہ پر نہیں بیٹھ جانا چاہیے، بلکہ اس کی جگہ خالی ہی رکھی جائے یا اگر کوئی بیٹھ بھی جائے تو اس کی واپسی پر اس کی جگہ چھوڑ دی جائے تا کہ وہ اپنی جگہ پر بیٹھ سکے لیکن اگر اس کے واپس نہ آنے کا یقین ہو تو پھر اس کی جگہ پر بیٹھا جا سکتا ہے۔"}],[244,"عمروبن شعیب اپنے باپ کے حوالے سے اپنے دادا سے روایت کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے اس بات سے منع فرمایا ہے کہ کوئی شخص دو آدمیوں کے درمیان بیٹھے، ہاں اگر ان کی اجازت ہو تو پھر کوئی حرج نہیں ہے۔‘‘","حسن",{"k":"سنن أبوداؤد (4844)، سنن ترمذی (2752)۔"}],[245,"جابر رضی اللہ عنہ فرماتے ہیں کہ:\n’’جب ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوتے تھے تو جہاں ہم آخر میں ہوتے وہیں بیٹھ جاتے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4825)، سنن ترمذی (2725)۔","f":"یعنی آخر میں آ کر آگے بیٹھنے کے لیے لوگوں کے کندھے پھلانگ پھلانگ کر آگے جانے کی کوشش نہیں کرنی چاہیے بلکہ مجلس کے آخر میں جہاں جگہ ملے وہیں بیٹھ جانا چاہیے تا کہ لوگوں کو بھی تکلیف نہ ہو اور آدابِ مجلس بھی پامال نہ ہوں۔"}],[246,"ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’بہترین مجلس وہ ہے جو بہت کشادہ اور کھلی ہو۔‘‘","صحیح",{"k":"سنن أبوداؤد (4820)، مسند أحمد (3؍69)، سلسلہ الأحادیث الصحیحہ (832)۔","f":"کیونکہ اگر جگہ کی تنگی ہو تو سبھی لوگ تنگ ہوتے رہتے ہیں اور ہر نئے شخص کی آمد پر ساری مجلس کو اِدھر اُدھر ہونا پڑتا ہے، اس لیے پہلے ہی کسی وسیع و کشادہ جگہ کا انتخاب کیا جائے تا کہ بعد میں کسی پریشانی کا سامنا نہ ہو اور مقصودِ مجلس تمام تر توجہ و انہماک سے حاصل کیا جائے۔"}],[247,"ابو واقدلیثی رضی اللہ عنہ روایت کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم مسجد میں تشریف فرما تھے اور لوگ آپ صلی اللہ علیہ وسلم کے ساتھ بیٹھے ہوئے تھے کہ تین آدمی آئے، دو تو رسول اللہ صلی اللہ علیہ وسلم کے پاس آگئے اور ایک چلا گیا۔ راوی کہتے ہیں کہ وہ دونوں رسول اللہ صلی اللہ علیہ وسلم کے پاس کھڑے ہوگئے، ان میں سے ایک نے تو مجلس میں کچھ گنجائش دیکھی تو وہ وہاں بیٹھ گیا، اور دوسرا ان کے پیچھے بیٹھ گیا، جبکہ تیسرا واپس چلا گیا۔ جب رسول اللہ صلی اللہ علیہ وسلم فارغ ہوئے تو آپ صلی اللہ علیہ وسلم نے فرمایا:کیا میں تمہیں تین لوگوں کی بات نہ بتلاؤں؟ ان میں سے ایک اللہ تعالیٰ کی طرف جگہ چاہی تو اللہ نے اسے جگہ دے دی، دوسرے نے شرم محسوس کی تو اللہ تعالٰی نے بھی اس سے شرم محسوس کی اور تیسرے نے منہ پھیر لیا تو اللہ تعالٰی نے بھی اس سے منہ پھیر لیا۔‘‘","صحیح",{"k":"صحیح بخاری (66)، صحیح مسلم (2176)۔","f":"اللہ تعالیٰ نے شرم محسوس کی کا مطلب یہ ہے کہ اللہ تعالیٰ نے اسے بیٹھنے کے لیے جگہ نہ دی اور منہ پھیر لینے سے مراد یہ ہے کہ اللہ تعالیٰ نے تیسرے شخص کو رسول اللہ صلی اللہ علیہ وسلم کی مجلس میں بیٹھنے کی توفیق ہی نہ دی۔"}],[248,"جابربن سمرہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’ہم الگ الگ حلقے لگائے بیٹھے ہوئے تھے کہ رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے تو آپ صلی اللہ علیہ وسلم نے فرمایا:میں کیا دیکھ رہا ہوں کہ تم فرقوں میں بٹے بیٹھے ہو۔ محمدبن فضیل کہتے ہیں کہ آپ صلی اللہ علیہ وسلم نے ایسے فرمایاکہ جیسے آپ صلی اللہ علیہ وسلم جماعت )یعنی ایک جگہ مل کر بیٹھنے(کو پسند فرماتے ہیں۔‘‘","صحیح",{"k":"صحیح مسلم (430)، سنن أبوداؤد (4823)۔","f":"لیکن اگر کسی فائدے اور مقصد کے باعث حلقوں میں بیٹھنا ناگزیر ہو تو اس صورت میں ایسا کرنا جائز ہوگا۔"}],[249,"جابربن سمرہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم جب فجر کی نماز پڑھ لیتے تھے تو سورج خوب طلوع ہوجانے تک اپنی جگہ پر ہی چارزانو ہو کر بیٹھے رہا کرتے تھے۔‘‘","صحیح",{"k":"صحیح مسلم (670)، سنن أبوداؤد (4850)، سنن ترمذی (585)۔"}],[250,"ابنِ عمر رضی اللہ عنہما بیان کرتے ہیں کہ:\n’’میں نے رسول اللہ صلی اللہ علیہ وسلم کو کعبے کے صحن میں دونوں رانیں پیٹ سے لگائے، دونوں ہاتھوں سے پنڈلی پکڑے سُرین پر بیٹھے دیکھا۔‘‘","صحیح",{"k":"صحیح بخاری (6272)۔"}],[251,"قیلہ بنت مخرمہ رضی اللہ عنہا روایت کرتی ہیں کہ:\n’’انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ صلی اللہ علیہ وسلم دونوں رانوں کو پیٹ سے ملا کر اور دونوں ہاتھوں سے پنڈلیوں پر حلقہ بنا کر سرین کے بَل بیٹھے ہوئے تھے، جب میں نے آپ صلی اللہ علیہ وسلم کو بیٹھنے کی خشوع والی اس حالت میں دیکھا تو میں خوف کے مارے لرز گئی۔‘‘","حسن",{"k":"سنن أبوداؤد (4847)۔","f":"یعنی جب انہوں نے دیکھا کہ دو عالم کے تاجدار اور تمام انبیاء کے سردار ہوتے ہوئے بھی اتنی عاجزی اور خشوع کے ساتھ بیٹھے ہیں تو فرماتی ہیں کہ میں اس قدر ورطۂ حیرت میں ڈوب گئی اور آپ صلی اللہ علیہ وسلم کے اس انداز میں بھی ایسی جلالت اور ہیبت نظر آئی کہ میں خوف کے مارے لرز اٹھی۔"}],[252,"شریدبن سوید رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم (میرے پاس سے)گزرے اور میں اپنے بائیں ہاتھ کو اپنی پُشت کے پیچھے کرکے اپنے ہاتھ کے انگوٹھے کی جڑاور اس کے نچلے حصے پر ٹیک لگا کر بیٹھا ہوا تھا، تو آپ صلی اللہ علیہ وسلم نے فرمایا:کیا تم ان لوگوں کی طرح بیٹھے ہوئے ہوجن پر غضب کیا گیا ہے؟‘‘","صحیح",{"k":"سنن أبوداؤد (4848)۔","f":"ہمارے معاشرے میں لوگ اس انداز میں عموماًبیٹھتے ہیں، یعنی ہاتھ کو کمر کے پیچھے زمین پر رکھ کر اس پہ ٹیک لگا کر بیٹھنا، جبکہ مذکورہ حدیث میں اس انداز کو غضبِ الٰہی کا نشانہ بننے والے لوگوں کا انداز کہا گیا ہے، لہٰذا اس سے احتراز کرنا چاہیے۔"}],[253,"ابوہریرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب تم میں سے کوئی شخص سائے میں بیٹھا ہو، پھر اس سے سایہ ہٹ جائے اور وہ کچھ حصہ دھوپ میں ہوجائے اور کچھ سائے میں تو اسے(وہاں سے) کھڑے ہو جانا چاہیے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4821)، سلسلہ الأحادیث الصحیحہ (737)۔"}],[254,"ابوحازم روایت کرتے ہیں کہ:\n’’وہ (مسجد میں آئے)آئے اور نبی صلی اللہ علیہ وسلم خطبہ ارشاد فرما رہے تھے تو وہ دھوپ میں کھڑے ہوگئے، تو آپ صلی اللہ علیہ وسلم نے انہیں حکم فرمایا تو وہ سائے میں آگئے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4822)۔","f":"آدھا دھوپ میں اور آدھا سائے میں بیٹھنا یاکھڑے ہونا طبی طور پر انسانی صحت کے لیے ضرر رساں ہے، اسی لیے اس سے منع فرمایا گیا۔"}],[255,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جو بھی لوگ کسی ایسی مجلس سے اُٹھتے ہیں جس میں وہ اللہ کا ذکر نہ کرتے ہوں تو وہ کسی مردار گدھے پر سے اُٹھنے کے مثل ہیں، اور وہ مجلس (روزِقیامت)ان کے لیے حسرت بن جائے گی۔‘‘","صحیح",{"k":"سنن أبوداؤد (4855)، سلسلہ الأحادیث الصحیحہ (77)۔","f":"یعنی روزِقیامت وہ مجلس ان کے لیے اس طرھ وبال بن جاءے گی کہ وہ یہ حسرت اور تمنا کریں گے کہ کاش ہم نے اس مجلس میں اللہ کا ذکر کیا ہوتا۔"}],[256,"ابوبرزہ اسلمی رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم جب کسی مجلس میں تشریف فرما ہوتے اور پھراُٹھنے کا ارادہ فرماتے تو یہ دعا پڑھتے: «سُبْحَانَكَ اللّٰهُمَّ وَبِحَمْدِكَ أَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا أَنْتَ أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ» ’’اے اللہ!تو اپنی تعریف کے ساتھ بہت پاک ہے، میں اس بات کی گواہی دیتا ہوں کہ تیرے سوا کوئی معبود نہیں ہے، میں تیری بخشش کا طلبگار ہوں اور تیری طرف رجوع کرتا ہوں۔‘‘ صحابہؓ نے عرض کیا:اے اللہ کے رسول!آپ صلی اللہ علیہ وسلم یہ جو کلمات کہتے ہیں انہیں آپ صلی اللہ علیہ وسلم تنہائی میں نہیں پڑھتے(اس کی کیا وجہ ہے؟( تو آپ صلی اللہ علیہ وسلم نے فرمایا:یہ(دعا) مجلس میں ہونے والی باتوں کا کفارہ ہے۔‘‘","حسن",{"k":"سنن أبوداؤد (4859)۔","f":"یعنی مجلس میں بیٹھنے کے دوران سبقتِ لسانی سے جو باتیں ہوجاتی ہیں مجلس ختم کرنے کے بعد یہ دعا پڑھنے سے ان خطاؤں کا کفارہ ادا ہو جاتا ہے۔"}],[257,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’یقیناًاللہ تعالٰی چھینک کو پسند فرماتا ہے اور جمائی کو ناپسند فرماتا ہے۔ سوتم میں سے جب کسی کو چھینک آئے تو اسے «اَلْحَمْدُ» لِلّٰهِکہنا چاہیے، یاوہ «اَلْحَمْدُ» لِلّٰهِکہے تو سننے والے کا یہ حق ہے کہ وہ «يَرْحَمُكَ» اللّٰهُ(یعنی اللہ تم پر رحم فرمائے)کہے۔ اورجب وہ جمائی لیتا ہے تو شیطان ہنستا ہے، اس لیے جس قدر ہو سکے اسے روکنا چاہیے۔‘‘","صحیح",{"k":"صحیح بخاری (6223)، سنن ترمذی (2747)۔"}],[258,"ابوہریرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب تم میں سے کسی کو چھینک آئے تو اسے «اَلْحَمْدُ لِلَّهِ عَلٰى كُلِّ» حَالٍ(یعنی ہرحال میں تمام ترتعریفات اللہ تعالٰی کے لیے ہیں)اور اس کے (مسلمان)بھائی، یا(فرمایا:)اس کے ساتھی کويَرْحَمُكَ اللّٰهُکہنا چاہیے، اور پھر اس کے جواب میں وہ(یعنی چھینکنے والا)يَهْدِيكُمُ «اللّٰهُ وَيُصْلِحُ» بَالَكُمْکہے(یعنی اللہ تمہیں ہدایت سے نوازے اور تمہارا معاملہ درست فرمائے)۔‘‘","صحیح",{"k":"سنن أبوداؤد (5033)، صحیح بخاری (4622)۔"}],[259,"ابوہریرہ رضی اللہ عنہ سے مرفوعاًاور موقوفاًدونوں طرح سے مروی ہے کہ:\n’’اپنے بھائی کی چھینک کا تین بار جواب دو، اور جو اس سے زیادہ بار چھینکے تو وہ زکام ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (5034)۔","f":"یعنی اگر زکام کی وجہ سے کوئی بار بار چھینک رہا ہو تو اس صورت میں يَرْحَمُکَ اللهُ سے جواب نہ بھی دیا جائے تو کوئی حرج نہیں ہے، کیونکہ جن چھینکوں کے جواب کا حکم ہے وہ صرف پہلی تین چھینکیں ہیں، اس کے بعد والی زکام کے باعث ہوتی ہیں اس لیے ان کا جواب دینا ضروری نہیں ہے۔"}],[260,"سلمہ بن اکوع رضی اللہ عنہ روایت کرتے ہیں کہ:\n’’ایک آدمی نے نبی صلی اللہ علیہ وسلم کے پاس چھینک ماری تو آپ صلی اللہ علیہ وسلم نے فرمایا «يَرْحَمُكَ اللّٰهُ»، پھر اس نے دوسری مرتبہ ماری تو نبی صلی اللہ علیہ وسلم نے فرمایا: «مَزْكُومٌ» (یعنی اسے زکام لگا ہوا ہے)۔ ایک روایت میں ہے کہ اس کے تیسری مرتبہ چھینکنے پر آپ صلی اللہ علیہ وسلم نے یہ فرمایا تھا۔‘‘","صحیح",{"k":"صحیح مسلم (2993)، سنن أبوداؤد (5037)، سنن ترمذی (2743)۔","f":"اس روایت میں دوسری یا تیسری مرتبہ کے چھینکنے کو بھی زکام کہا گیا ہے، البتہ تین چھینکوں تک جواب دینا بہتر عمل ہے۔"}],[261,"انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم کے پاس دو آدمیوں نے چھینک ماری، تو آپ صلی اللہ علیہ وسلم نے ان میں سے ایک کا جواب(يَرْحَمُكَ اللّٰهُ کہہ کر)دے دیا جبکہ دوسرے کا نہ دیا۔ میں نے عرض کیا:اے پیغمبرِخدا!دو آدمیوں نے چھینک ماری اور آپ صلی اللہ علیہ وسلم نے ایک کا جواب دیا اور دوسرے کا نہیں دیا۔ تو آپ صلی اللہ علیہ وسلم نے فرمایا:اس نے «اَلْحَمْدُ لِلّٰهِ» کہا تھا اور اس نے «اَلْحَمْدُ» لِلّٰهِنہیں کہا۔‘‘","صحیح",{"k":"صحیح بخاری (6221)، صحیح مسلم (2991)۔","f":"یعنی جس شخص نے الحمد للہ کہا تھا آپ صلی اللہ علیہ وسلم نے اس کا جواب دے دیا اور جس نے نہیں کہا تھا اسے جواب نہیں دیا۔ اس لیے رحمتِ خداوندی کی دعا لینے کے لیے ضروری ہے کہ «اَلْحَمْدُ لِلَّهِ» کہا جائے۔"}],[262,"ابو موسٰی اشعری رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’جب تم میں سے کوئی چھینک مارے اور وہ «اَلْحَمْدُ لِلّٰهِ» کہے تو(يَرْحَمُكَ اللّٰهُ کہہ کر)اس کا جواب دو، اور اگر وہ «اَلْحَمْدُ» لِلّٰهِنہ کہے تو اس کا جواب مت دو۔‘‘","صحیح",{"k":"صحیح مسلم (2992)، الأدب المفرد للبخاری (941)۔","f":"اس حدیث میں بحی اسی بات کا ذکر ہے کہ چھینک کے جواب میں رحمت کی دعا لینے کا وہی حقدار ہے جو پہلے الحمدللہ کہے، اور جو چھینکنے پر الحمدللہ نہیں کہتا اسے جواب میں ’یرحمک اللہ‘بھی نہیں کہا جائے گا۔"}],[263,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم جب چھینک مارتے تھے تو اپنی آواز کو پست رکھتے اور آپ صلی اللہ علیہ وسلم کا چہرۂ مبارک سُرخ ہوجاتا۔‘‘","حسن",{"k":"سنن أبوداؤد (5029)، سنن ترمذی (2745)، مسند أحمد (2؍439)۔","f":"معلوم ہوا کہ چھینتے وقت آواز کو پست رکھناسُنّتِ رسول ہے۔"}],[264,"ابنِ عمر رضی اللہ عنہما سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب تم میں سے کوئی اپنے بھائی کو شادی کی یااس جیسی کوئی اور دعوت دے تو اسے قبول کرنے چاہیے۔‘‘","صحیح",{"k":"صحیح مسلم (1429)، سنن أبوداؤد (3738)۔"}],[265,"ابوہریرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب تم میں سے کسی کو کھا نے کی دعوت دی جائے تو اسے قبول کرنی چاہیے، سواگر تو اس نے روزہ نہ رکھا ہو تو اسے کھا لینا چاہیے لیکن اگر روزے سے ہو تو اسے دعا کر دینی چاہیے۔‘‘","صحیح",{"k":"صحیح مسلم (1431)، سنن أبوداؤد (2460)، سنن ترمذی (780)۔","f":"یعنی وہاں حاضر ضرور ہونا چاہیے، البتہ انہیں بتا دیا جائے کہ میں نے روزہ رکھا ہوا ہے اس لیے کھا نہیں سکتا اور ان کے لیے برکت کی دعا کر دینی چاہیے۔"}],[266,"جابر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب تم میں سے کسی کو دعوت دی جائے تو اسے قبول کرنی چاہیے، پھر اگر وہ چاہے تو کھا لے اور اگر چاہے تو چھوڑ دے۔‘‘","صحیح",{"k":"صحیح مسلم (1430)، سنن أبوداؤد (3740)، سنن ابن ماجه (1751)۔","f":"یعنی دعوت ٹھکرانی نہیں چاہیے بلکہ قبول ضرور کر لینی چاہیے، وہاں جا کرا گردِل چاہے تو کھا لے ورنہ رہنے دے، اس میں کوئی حرج نہیں ہے، البتہ دعوت کو قبول ہی نہ کرنا خلافِ سُنّت بات ہے۔"}],[267,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’اگر مجھے پائے(کے گوشت)کی دعوت دی جائے تو بھی میں قبول کر لوں گااور اگر مجھے بازو(کا گوشت)تحفے میں دیا جائے تو اسے بھی میں قبول کر لوں گا۔‘‘","صحیح",{"k":"صحیح بخاری (2568)، مسندأحمد (2؍424)۔","f":"گویا اگر کسی بھائی کی طرف سے کھانے پر مدعو کیا جائے تو یہ نہیں دیکھنا چاہیے کہ ان کے ہاں کھانے کا اہتمام کیسا ہے، کہ اگر اچھا ہو تو چلا جائے اور اگر پر تکلف نہ ہو تو پھر شرکت نہ کرے۔ ایسا کرنا «شرعاً و اخلاقاً» ہر دو لحاظ سے برا عمل ہے۔ سنت کی اتباع اور اخلاقیات کا تقاضا یہ ہے کہ خواہ کیسے ہی کھانے پر مدعو کیا جائے دعوت کو قبول کرنا چاہیے۔"}],[268,"ابوہریرہ رضی اللہ عنہ فرمایا کرتے تھے:\n’’بدترین کھانا ولیمے کا وہ کھانا ہے جس میں مالداروں کو دعوت دی گئی ہو اور غریبوں کونہ بلایا گیا ہو، یہ حق ہے، سوجس نے اسے چھوڑا اس نے اللہ اور اس کے رسول کی نافرمانی کی۔‘‘","صحیح",{"k":"صحیح بخاری (5177)، صحیح مسلم (1432)۔","f":"حق سے مراد یہ ہے کہ ایک مسلمان کے دوسرے مسلمان پر جو حقوق ہیں ان میں سے ایک حق یہ بھی ہے کہ جب وہ اسے دعوت دے تو اسے قبول کرنی چاہیے، اور چھوڑ نے سے مراد دعوت قبول نہ کرنا ہے، یعنی جو دعوت قبول کرنے سے انکار کر دے اس نے اللہ تعالٰی اور اس کے رسول کی نافرنی کی۔ علاوہ ازیں اس روایت میں یہ بھی فرمایا گیا ہے کہ جس دعوتِ ولیمہ میں صرف امراء، صاحبِ حیثیت اور بااثر افراد کو ہی مدعو کیا گیا ہو اور فقراء وغرباء کو دعوت نہ دی گءی ہو، ایسی دعوت بدترین دعوت ہے۔"}],[269,"انس رضی اللہ عنہ روایت کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے سعدبن عبادہؓ سے السلام علیکم ورحمۃ اللہ کہہ کر(ان کے گھر میں داخلے کی)اجازت لی، پھر انسؓ نے طویل حدیث بیان کی جس میں آپ صلی اللہ علیہ وسلم کا ان کے گھر تشریف لے جانے اور ان کے ہاں کھانا تناول فرمانے کا ذکر تھا، پھرجب آپ صلی اللہ علیہ وسلم فارغ ہوئے تو یہ دعا پڑھی: «أَكَلَ طَعَامَكُمُ الْأَبْرَارُ وَصَلَّتْ عَلَيْكُمُ الْمَلَائِكَةُ وَأَفْطَرَ عِنْدَكُمُ الصَّائِمُونَ» ’’نیک لوگ تمہارا کھانا کھائیں، فرشتے تمہیں دعائیں دیں اور روزے دار لوگ تمہارے ہاں افطاری کریں۔‘‘","صحیح",{"k":"سنن أبوداؤد (3854)، سنن ابن ماجه (1747)۔"}],[270,"ابو سعید خدری رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’اپنے بیمار لوگوں کی عیادت کیا کرو اور جنازوں میں شرکت کیا کرو، یہ تمہیں آخرت کی یاد دلاتے ہیں۔‘‘","صحیح",{"k":"مسند أحمد (3؍23)، الأدب المفرد للبخاری (518)، سلسلہ الأحادیث الصحیحہ (1981)۔","f":"بیماروں کی عیادت اور جنازوں میں شرکت سے دل میں خوف اور نرمی پیدا ہوتی ہے اور بندے کو اپنی موت اور آخرت کا معاملہ یاد رہتا ہے، جس سے وہ اپنا تزکیہ اور محاسبہ کرتا رہتا ہے اور اپنی آخرت کو بہتر بنانے والے عمل کرتا رہتا ہے۔"}],[271,"ثوبان رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جس نے کسی بیمار کی عیادت کی وہ ہمیشہ جنّت کے میووں میں رہتا ہے۔ پوچھا گیا:اے اللہ کے رسول!جنّت کے میوے کیا ہیں؟ فرمایا:اس کے چنے ہوئے پھل۔‘‘","صحیح",{"k":"صحیح مسلم (2568)۔"}],[272,"سیدنا علی رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’جب کوئی شخص اپنے(مسلمان)بھائی کی عیادت کرنے آتا ہے تو وہ (مریض کے پاس آکر)بیٹھ جانے تک جنّت کے چنیدہ پھلوں میں چلتا آتا ہے، اورجب وہ بیٹھ جاتا ہے تو رحمت اس پر سایہ فگن ہوجاتی ہے، پھر اگر وہ صبح کو(عیادت کے لیے)آیا ہو تو شام تک ستّرہزار فرشتے اس کے حق میں دعائیں کرتے رہتے ہیں اور اگر وہ شام کو آیا ہو تو صبح تک ستّرہزار فرشتے اس کے لیے دعائیں کرتے رہتے ہیں۔‘‘","صحیح",{"k":"سنن أبوداؤد (3100)، سنن ابن ماجه (1442)، سلسلہ الأحادیث الصحیحہ (1367)۔"}],[273,"جابربن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم میری عیادت کرنے کے لیے تشریف لائے، آپ صلی اللہ علیہ وسلم نہ کسی خچر پر سوار تھے اور نہ ہی کسی گھوڑے پر۔‘‘","صحیح",{"k":"صحیح بخاری (5664)، سنن أبوداؤد (3096)، سنن ترمذی (3851)۔","f":"یعنی آپ صلی اللہ علیہ وسلم مسلمان کے اس حق کی ادائیگی کے لیے پیدل ہی تشریف لے گئے، لہٰذاجس طرح سے بھی اپنے مریض مسلمان بھائی کی عیادت کے لیے جانا ممکن ہو اسی طرح چلے جانا چاہیے اور تکلّفات میں پڑنے سے بچنے کی خاطر اس سے گریز نہیں کرنا چاہیے، جیسا کہ ہمارے معاشرے میں عموماًہوتاہے کہ جب کسی مریض کی عیادت کے لیے جانا ہو تو اس کے لیے بے شمار تکلّفات اُٹھائے جاتے ہیں، خواہ وہ مریض کی خدمت داری کے لیے ہوں یاا پنی ٹھاٹھ باٹھ کے لیے، اور بسااوقات ایسا بھی ہوتاہے کہ وسائل کی عدمِ دستیابی پر یہ بے جا تکلّفات ترک کرنا گوارہ نہیں کیا جاتا بلکہ مسلمان کا ایک عظیم حق یعنی تیمارداری چھوڑ دینا گوارہ کر لیا جاتا ہے، جبکہ اس نیکی پر عمل کے لیے درحقیقت کوئی چیز بھی مانع نہیں ہے۔"}],[274,"زیدبن ارقم رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’میری آنکھ میں تکلیف تھی تو رسول اللہ صلی اللہ علیہ وسلم نے میری عیادت فرمائی۔‘‘","صحیح",{"k":"سنن أبوداؤد (3102)۔","f":"یعنی ضروری نہیں ہے کہ عیادت صرف اسی کی کی جائے جو بہت زیادہ بیمار ہو یاکسی بڑی تکلیف میں مبتلا ہو، بلکہ چھوٹی موٹی بیماری یاتھوڑی بہت طبیعت خراب والے شخص کی بھی عیادت کرنی چاہیے تاکہ اس مسلمان بھائی کاحق ادا ہو جائے اور اپنے نامہ اعمال میں اجروثواب لکھوایا جا سکے، جیسا کہ نبی کریم صلی اللہ علیہ وسلم نے زیدبن ارقمؓ کو آنکھ کی تکلیف ہونے پر ان کی عیادت فرمائی۔"}],[275,"سیدنا سعد رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’میں مکہ میں بیمار پڑگیا، تو رسول اللہ صلی اللہ علیہ وسلم میری عیادت کرنے کے لیے تشریف لائے، آپ صلی اللہ علیہ وسلم نے اپنا دستِ مبارک میری پیشانی پر رکھا اور پھر اسے میرے سینے اور پیٹ پر پھیرا، پھر فرمایا:اے اللہ!سعد کو شفا دے اور اس کی ہجرت کو پورا فرما۔‘‘","صحیح",{"k":"صحیح بخاری (5659)۔","f":"ہجرت کو پورا فرمانے سے مراد یہ تھا کہ اسے صحت دے اور ہجرت تک زندگی عطا فرما، تا کہ یہ مدینہ طیبہ پہنچ جائے۔"}],[276,"سیدہ عائشہ رضی اللہ عنہا روایت کرتی ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم جب کسی بیمار کی عیادت فرماتے تو اس کے چہرے اور سینے پر ہاتھ پھیرتے، اور یہ دعا پڑھتے: «أَذْهِبِ الْبَأْسَ رَبَّ النَّاسِ، وَاشْفِ أَنْتَ الشَّافِي لَا شِفَاءَ إِلَّا شِفَاؤُكَ، شِفَاءً لَا يُغَادِرُ» سَقَمًا’’اے لوگوں کے پالنہار!(اس کی)تکلیف کودُورکر دے اور شفا عطا فرما، تُوہی شفا دینے والا ہے اور تیری شفا کے علاوہ کوئی شفا نہیں ہے، ایسی شفا عطا فرما جو کسی بھی بیماری کو باقی نہ رہنے دے۔‘‘ سیدہ عائشہؓ فرماتی ہیں کہ جب آپ صلی اللہ علیہ وسلم مرض الموت میں مبتلا تھے تو میں آپ صلی اللہ علیہ وسلم کا ہاتھ پکڑنے لگی تاکہ اسے آپ صلی اللہ علیہ وسلم کے سینے پر رکھ کر یہ دعا پڑھوں، تو آپ صلی اللہ علیہ وسلم نے مجھ سے اپنا ہاتھ کھینچ لیا اور فرمایا:اے اللہ!مجھے اعلٰی رفیق میں شامل کردے۔‘‘","صحیح",{"k":"صحیح مسلم (2191)، مسند أحمد (6؍126)۔"}],[277,"ابنِ عباس رضی اللہ عنہما بیان کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم ایک بدوی صحابی کی عیادت کے لیے تشریف لے گئے، اور فرمایا: «لَا بَأْسَ عَلَيْكَ طَهُورٌ إِنْ شَاءَ اللّٰهُ» ’’فکر کی کوئی بات نہیں ہے، اگر اللہ نے چاہا تو یہ بیماری گناہوں سے پاکیزگی کا ذریعہ بن جائے گی۔‘‘","صحیح",{"k":"صحیح بخاری (5662)۔"}],[278,"ابومجلز فرماتے ہیں کہ:\n’’مریض کے پاس وہی باتیں کرنی چاہییں جو اسے اچھی لگتی ہوں۔‘‘","",{"k":"شعب الإیمان للبیهقی (11؍426)۔","f":"لیکن اس کا یہ مفہوم ہرگز نہیں لیا جا سکتا کہ مریض کوجس طرح کی بھی باتیں اچھی لگتی ہوں اس کے پاس وہی کی جائیں، اگر اس کادِل کسی ایسے موضوع پر بات کرنے کو چاہے کہ جو خلافِ شرع ہو یاکسی ممنوعہ امور کا ارتکاب کرے مثلاًچغلی، غیبت یاا لزام تراشی وغیرہ، تو ایسے امور میں ہرگز مریض کا ساتھ نہیں دینا چاہیے بلکہ اسے منع کرنا چاہیے، ہاں ان امور کے علاوہ کوئی ایسی بات کہ جس میں شرعاًکوئی قباحت نہ ہو اور مریض کی اس بات سے طبیعت بہلتی ہو تو اس کا ساتھ دینا چاہیے تاکہ اس کے لیے خوش طبعی کا ساماں ہو سکے۔"}],[279,"طاؤس فرماتے ہیں کہ:\n’’سب سے زیادہ فضیلت والی وہ عیادت ہے جو خفیف ترین ہو۔‘‘","",{"k":"شعب الإیمان للبیهقی (11؍433)۔","f":"خفیف ترین ہونے سے مراد یہ ہے کہ مریض کے پاس کم سے کم وقت بیٹھا جائے اور اس کی عیادت اور مناسب گفتگو کے بعداُٹھ جانا چاہیے۔"}],[280,"ابو سعید رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’اپنے قریب المرگ لوگوں کو «لَا إِلٰهَ إِلَّا اللّٰهُ» کی تلقین کیا کرو۔‘‘","صحیح",{"k":"صحیح مسلم (916)، سنن أبوداؤد (3117)، سنن ترمذی (976)، سنن نسائی (1826)، سنن ابن ماجه (1445)۔","f":"قریب المرگ مریض کے پاس بیٹھے شخص کے لیے یہ عمل کرنا مستحب ہے۔ بہرحال اس کا اہتمام لازمی کرنا چاہیے شاید کہ دوسرے شخص کے منہ سے کلمہ سُن کر وہ بھی کلمہ پڑھ لے اور یوں اس کی مغفرت کا سامان ہوجائے، کیونکہ نبی مکرم صلی اللہ علیہ وسلم کا ارشادِگرامی ہے کہ «مَنْ كَانَ آخِرُ كَلَامِهِ لَا إِلَهَ إِلَّا اللَّهُ دَخَلَ» الْجَنَّةَ’جس شخص کا آخری کلام «لَا إِلٰهَ إِلَّا اللّٰهُ» ہوا وہ جنّت میں جائے گا۔‘‘ (سنن أبوداؤد، كتاب الجنائز، باب في التلقين، ح:۳۱۱۶-سنن ترمذی، أبواب الجنائز، باب ما جاء في تلقين المريض عند الموت، ح:۹۷۷)"}],[281,"سہل بن حنیف رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم کمزور(غریب)مسلمانوں سے ملنے آیا کرتے، ان کے بیمار لوگوں کی عیادت فرماتے اور ان کے جنازوں میں شریک ہوا کرتے تھے۔‘‘","صحیح",{"k":"مستدرک حاکم (2؍466)، سلسلہ الأحادیث الصحیحہ (2112)۔","f":"بدقسمتی سے ہمارے معاشرے کی یہ رِیت پڑ چکی ہے کہ صرف اسی شخص کی تیمارداری کے لیے زحمت کی جاتی ہے جس سے کچھ نہ کچھ فائدہ حاصل ہونے کی امید ہو، یا پھر اس کی عیادت سے نام و نمود کی نمائش مقصود ہو یا فقط حاضری ہی ملحوظِ نظر ہو کہ بیمار شخص کے علم میں آ جائے کہ فلاں بھی تیمارداری کے لیے آیا تھا، اور اس کے برعکس اگر کوئی بے نام، غریب اور مِٹا ہوا شخص خواہ بسترِمرگ پر تڑپ تڑپ مر جائے اس کی مالی مدد تو درکنار اس کے احوال پوچھنے کے لیے بھی اس کی کٹیا میں جانا اپنی شان کے شایاں نہیں سمجھا جاتا۔ حالانکہ نبی صلی اللہ علیہ وسلم کی بعثت کے مقاصد میں سے ایک مقصد طبقاتی تقسیم ختم کرنا بھی تھا اور اسی وجہ سے آپؐ نے تمام بنی نوعِ انسانیت کی یکسانیت کے بارے میں نہ صرف بے شمار ارشادات فرمائے بلکہ عملی طور پر بھی اس کی مثالیں مہیا فرمائیں، جیسا کہ مذکورہ حدیث میں بھی ذکر ہے۔ اس لیے ہمیں آپؐ کی اتباع کرتے ہوئے اس قبیح تقسیم کو ختم کرنا چاہیے۔"}],[282,"ابورافع رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جس نے کسی میّت کو غسل دیا اور اس کے عیوب کی پردہ پوشی کی تو اللہ تعالٰی اسے چالیس مرتبہ معاف فرماتا ہے، جس نے کسی میّت کو کفن پہنایا اللہ تعالٰی اسے نرم وبا ریک اور موٹے ریشم کا جنتی لباس پہنائے گااو رجس نے میت کے لیے قبر کھودی اور اسے اس میں دفنایا تو اسے ایسا اجر دیا جائے گاکہ جیسے اس نے اس(میت)کو قیامت تک کے لیے رہائش فراہم کردی ہو۔‘‘","صحیح",{"k":"السنن الکبری للبیهقی (3؍395)، مستدرک حاکم (1؍354)۔"}],[283,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’جو شخص میّت کے گھر سے جنازے کے ساتھ روانہ ہو، پھر وہ اس کی نمازِجنازہ ادا کرے، پھر اسے دفنادِیے جانے تک اس کے پیچھے(یعنی ساتھ)رہے تو اسے دو قیراط اجروثواب ملتا ہے، اور جو نمازِجنازہ پڑھ کر واپس آجائے تو اسے اُحدپہاڑ کے مِثل ایک قیراط اجروثواب ملتا ہے۔‘‘","صحیح",{"k":"صحیح مسلم (945)، سنن أبوداؤد (3169)۔","f":"قیراط سے مراد وزن کی پیمائش ہے جو مختلف زمانوں میں بدلتی رہتی ہے، یہ مقدار میں بہت کم وزن اور ماپ پر بولا جاتا ہے لیکن یہاں اسے اُحدپہاڑ کی مماثلت سے بیان کیا گیا ہے، جس کی احتما لی وجہ یہ ہو سکتی ہے کہ نبی صلی اللہ علیہ وسلم نے اس حدیث میں مذکور عمل کے اجروثواب کواُحدپہاڑ کے ساتھ تشبیہ دے کر بتلایا ہے کہ بظاہر اس چھوٹے سے عمل کا بھی اہتمام کیا جائے تو اس کا اجر بہت بڑا ہو سکتا ہے۔"}],[284,"ابوہریرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’قبروں کی زیارت کیا کرو، کیونکہ یہ تمہیں موت کی یاددلاتی ہیں۔‘‘","صحیح",{"k":"صحیح مسلم (976)، سنن أبوداؤد (3234)، سنن نسائی (2034)، سنن ابن ماجه (1572)۔"}],[285,"بریدہ رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’(پہلے)میں تمہیں قبروں کی زیارت سے منع کیا کرتا تھا، لیکن (اب)تم ان کی زیارت کیا کرو، کیونکہ ان کی زیارت میں (موت کی)یاد ہے۔‘‘","صحیح",{"k":"صحیح مسلم (977)، سنن أبوداؤد (3235)، سنن ترمذی (1054)۔"}],[286,"انس رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’(پہلے)میں تمہیں قبروں کی زیارت سے منع کیا کرتا تھا، پھر(یہ بات)مجھ پر واضح ہوگئی، چنانچہ تم ان کی زیارت کیا کرو، کیونکہ یہ دِل کو نرم کرتی ہیں، آنکھوں کو بہاتی ہیں اور آخرت کی یاددِلاتی ہیں، سوتم زیارت کیا کرو اور بیہودہ گوئی نہ کیا کرو۔‘‘","",{"f":"چونکہ قبرستان جانے سے انسان کو یہ احساس ہوتا ہے کہ جس طرح آج یہ لوگ یہاں مدفون ہیں اسی طرح کل میں بھی یہاں منوں مٹی تلے پڑا ہوں گا۔ اس احساس سے اس کا دل نرم پڑ جاتا ہے اور اپنی موت کو یاد کر کے اشک بہانے لگتا ہے۔ اور یوں قبروں کی زیارت اس کی آخرت کے بہتر ہو جانے کا ذریعہ بن جاتی ہے۔"}],[287,"محمدبن قیس بن مخرمہ بن عبدالمطلب بیان کرتے ہیں کہ سیدہ عائشہ رضی اللہ عنہا نے فرمایا:\n’’کیا میں تمہیں اپنی ایک بات اور رسول اللہ صلی اللہ علیہ وسلم کی حدیث بیان نہ کروں؟ میں نے عرض کیا:کیوں نہیں، تو انہوں نے بقیع(قبرستان)کی طرف جانے کا واقعہ بیان کیا، اور انہوں نے (رسول اللہ صلی اللہ علیہ وسلم سے)کہا:اے اللہ کے رسول!(میں قبرستان میں داخل ہوتے ہوئے)کیا کہوں؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:تُوکہہ «اَلسَّلَامُ عَلٰى أَهْلِ الدِّيَارِ مِنَ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ، وَيَرْحَمُ اللّٰهُ الْمُسْتَقْدِمِينَ مِنَّا وَالْمُسْتَأْخِرِينَ، وَإِنَّا إِنْ شَاءَ اللّٰهُ بِكُمْ لَاحِقُونَ» ’’مومنوں اور مسلمانوں کے گھروں والوں پر سلامتی ہو اور اللہ تعالیٰ ہم سے پہلے چلے جانے والوں پر اور ہم سے بعد میں آنے والوں پر رحم فرمائے، اور بلاشبہ اگر اللہ تعالیٰ نے چاہا تو ہم بھی تم سے آملنے والے ہیں۔‘‘ اور ایک روایت میں یہ اضافہ ہے کہ: «أَنْتُمْ لَنَا فَرَطٌ وَنَحْنُ لَكُمْ تَبَعٌ نَسْأَلُ اللّٰهَ لَنَا وَلَكُمُ الْعَافِيَةَ» ’’تم ہم سے پہلے پہنچ چکے ہو اور ہم تمہارے پیچھے آنے والے ہیں، ہم اللہ تعالیٰ سے اپنے اور تمہارے لیے عافیت کا سوال کرتے ہیں۔‘‘","صحیح",{"k":"صحیح مسلم (974)، سنن نسائی (2037)۔"}],[288,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’فوت شدگان کو برامت کہو، کیونکہ انہوں نے جیسے اعمال کیے تھے ان کا بدلہ پالیا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (1393)، سنن نسائی (1936)۔"}],[289,"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم کے پاس سے ایک جنازہ لے جایا گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا:اس کی تعریف کرو)یعنی مجھے بتا=کہ یہ کیسا شخص تھا؟( تو صحابہؓ نے کہا:ہم تو یہی جانتے ہیں کہ یہ اللہ اور اس کے رسول سے محبت رکھتا تھا، اور صحابہؓ نے اس کی تعریف کی، تو آپ صلی اللہ علیہ وسلم نے فرمایا:(اس پرجنّت)واجب ہوگئی۔ راوی کہتے ہیں کہ پھر ایک جنازہ لے جایا گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا:اس کی تعریف کرو۔ تو صحابہؓ نے کہا:اللہ کے دِین میں یہ بہت برا آدمی تھا، تو آپ صلی اللہ علیہ وسلم نے فرمایا:(اس پر جہنم)واجب ہوگئی، تم زمین میں اللہ تعالیٰ کے گواہ ہو۔‘‘","صحیح",{"k":"صحیح مسلم (949)، شرح السنہ للبغوی (5؍386)۔","f":"اس روایت کے معنیٰ میں یہ احتمال ہے کہ آپ صلی اللہ علیہ وسلم نے انہی لوگوں کے بابت ایسا پوچھا ہوجن کی نیکی یابرائی تمام لوگوں پر واضح تھی اورسب کو ان کے اچھے برے اعمال کا پتہ تھا، اور آپ صلی اللہ علیہ وسلم نے بری تعریف والے شخص کے بابت اس لیے پوچھا تاکہ ان جیسے دیگر لوگ اس کا انجام سن کر برائی کرنے سے باز آجائیں۔"}],[290,"ابوہریرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’مسلمان، مسلمان کا بھائی ہے، وہ نہ تو اس پر ظلم کرتاہے، نہ اسے رُسوا کرتا ہے اور نہ ہی اسے حقیر سمجھتا ہے، آدمی کے بُراہو نے کے لیے یہی کافی ہے کہ وہ اپنے مسلمان بھائی کو حقیر سمجھے۔‘‘","",{"k":"صحیح مسلم (2564)، سنن ترمذی (1927)۔"}],[291,"عبداللہ بن مسعود رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’تکبر یہ ہے کہ جوحق کو ٹھکرائے اور لوگوں کو حقیر جا نے۔‘‘","",{"k":"صحیح مسلم (91)۔"}],[292,"جندب رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے بیان فرمایا:\n’’ایک آدمی نے کہاکہ اللہ فلاں شخص کو معاف نہیں فرمائے گا، تو اللہ تعالیٰ نے فرمایا:جو شخص اس بات پر قسم اُٹھائے کہ میں فلاں شخص کو معاف نہیں کروں گاتو یقیناًمیں فلاں کو تو معاف کردوں گالیکن تیرے عمل ضائع کردوں گا۔‘‘","صحیح",{"k":"صحیح مسلم (2621)، سنن أبوداؤد (4983)۔"}],[293,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب تم کسی آدمی کو یہ کہتا سنو کہ لوگ ہلاک ہوگئے تو وہ ان سب سے زیادہ ہلاک ہونے والا ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2623)، سنن أبوداؤد (4983)۔","f":"گویا نبی صلی اللہ علیہ وسلم نے ایسے شخص کے لیے بددعا کی صورت میں سرزنش فرمائی ہے جو خود پسندی کا شکار ہو اور ہر دم خود ستائی میں ہی لگا رہے، اور دوسرے لوگوں کو حقیر اور نکما سمجھے۔"}],[294,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’عنقریب لوگوں پر ایسا زمانہ آئے گاکہ آدمی کو عاجزی اور فخر وتکبر(میں سے ایک کو اپنا نے) میں اختیار دیا جائے گا، سوجو اس زمانے میں موجود ہوا سے فخر وتکبر کی بجائے عاجزی کو اختیار کرنا چاہیے۔‘‘","صحیح",{"k":"مستدرک الحاکم (8353)، شعب الإیمان للبیهقی (7979)۔"}],[295,"عبداللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’سچ بولنا اپنے اوپر لازم کرلو، کیونکہ سچ نیکی کی طرف لے کر جاتا ہے اور نیکی جنّت میں لے کر جائے گی، اور یقیناًآدمی اتناسچ بولتا ہے کہ اسے اللہ کے ہاں سچّالکھ دیا جاتا ہے۔ اور جھوٹ سے بچنا بھی اپنے اوپر لازم کرلو، کیونکہ جھوٹ گناہ کی طرف کے کر جاتا ہے اور گناہ جہنّم میں لے جائے گا، اور یقیناًآدمی اس قدرجھُوٹ بولتا ہے کہ اسے اللہ کے ہاں بھی جھُوٹا ہی لکھ دیا جاتا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (6094)، صحیح مسلم (2607)۔","f":"اللہ تعالٰی فرماتا ہے: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللّٰهَ وَكُونُوا مَعَ الصَّادِقِينَ﴾ [التوبة: ۱۱۹] ’’اے ایمان والو!اللہ سے ڈرتے رہو اورسچ بولنے والوں کے ساتھ مل جاؤ۔‘‘"}],[296,"عبداللہ رضی اللہ عنہ اس حدیث کو مرفوع بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’یقیناًجھوٹ حقیقت یامذاق کسی صورت میں بھی جائز نہیں ہے اور نہ کوئی آدمی اپنے بیٹے سے ایسا وعدہ کرے کہ جسے وہ پورا نہ کر سکے۔‘‘","صحیح",{"k":"مستدرک حاکم (1؍127)۔"}],[297,"ابوشریح خزاعی رضی اللہ عنہ کی روایت پیچھے بیان ہو چکی ہے، جس میں وہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’جو شخص اللہ تعالٰی اور اس کے رسول پر ایمان رکھتا ہوا سے اچھی بات ہی کہنی چاہیے، یاپھر خاموش رہنا چاہیے۔‘‘","صحیح",{"k":"صحیح بخاری (6018)، صحیح مسلم (47)، سنن أبو داؤد (5154)، سنن ترمذی (2500)۔"}],[298,"سہل بن سعدان رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جو شخص مجھے اپنے دو جبڑوں کے درمیان والے عضو(یعنی زبان)اور اپنی دو ٹانگوں کے درمیان والے عضو(یعنی شرمگاہ کے جائز استعمال) کی ضمانت دے دے، میں اسے جنّت کی ضمانت دیتا ہوں۔‘‘","صحیح",{"k":"صحیح بخاری (6474)، سنن ترمذی (2408)۔"}],[299,"سفیان بن عبداللہ ثقفی رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’میں نے کہا:اے اللہ کے رسول!مجھے کسی ایسے کام کاحکم فرمائیے جسے میں اسلام میں مضبوطی سے تھامے رکھوں۔ آپ صلی اللہ علیہ وسلم نے فرمایاکہ کہو:میں اللہ پر ایمان لایا اور پھر اس پرڈٹ جا، کہتے ہیں کہ میں نے عرض کیا:میں کس چیز سے ڈرتا رہوں جس میں میرے مبتلا ہو جا نے سے آپ صلی اللہ علیہ وسلم خوف کھاتے ہیں؟ تو آپ صلی اللہ علیہ وسلم نے اپنی زبان کا ایک کنارہ پکڑ کر فرمایا:اس سے۔‘‘","صحیح",{"k":"صحیح مسلم (38)، سنن ترمذی (2410)، سنن ابن ماجه (3972)۔"}],[300,"ابووائل روایت کرتے ہیں کہ عبداللہ رضی اللہ عنہ نے صفا پہاڑی پر تلبیہ کہا، پھر فرمایا:\n’’اے زبان!اچھی بات کہہ، غنیمت میں رہے گی اور خاموش رہ، شرمندگی اٹھانے سے پہلے ہی سلامتی میں رہے گی۔ لوگوں نے پوچھا:اے ابو عبدالرحمان!یہ جو بات آپ نے کہی ہے یہ آپ کا قول ہے یاآپ نے کسی سے سنی ہے؟ تو انہوں نے جواب دیا کہ نہیں(میرا قول نہیں ہے)بلکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے کہ بلاشبہ انسان کی سب سے بڑی غلطی اس کی زبان سے سرزد ہوتی ہے۔‘‘","حسن",{"k":"الفقیه والمتفقه للخطیب (2؍148)۔"}],[301,"ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’)انسانی جسم کے تمام)اعضاء زبان سے دست بستہ کہتے ہیں کہ ہمارے معاملے میں اللہ سے ڈرتی رہنا، کیونکہ اگر تو سیدھی رہی تو ہم بھی سیدھے رہیں گے اور اگر تو ٹیڑھی ہوگئی تو ہم بھی ٹیڑھے ہوجائیں گے۔‘‘","حسن",{"k":"سنن ترمذی (2407)، مسند أحمد (3؍96)، صحیح الجامع للألبانی (351)۔","f":"مراد یہ ہے کہ زبان کے ہی صحیح بول سے جسم کے سب اعضاء تکلیف میں مبتلا ہو نے سے محفوظ رہتے ہیں اور اسی کے غلط بولنے سے نوبت لڑائی جھگڑے تک پہنچ جاتی ہے اور مارپِیٹ کی صورت میں جسم کے تمام اعضاء کو زبان کا کیا دھرا بھگتنا پڑتا ہے۔"}],[302,"معاذبن جبل رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے اسلام، نماز اور جہاد کا ذکر کیا، پھر فرمایا:\n’’کیا میں تجھے تمام اعمال کا خلاصہ نہ بتلا دوں؟ میں نے عرض کیا:کیوں نہیں(ضرور بتلائیے)، تو آپ صلی اللہ علیہ وسلم نے اپنی زبان کو پکڑا اور فرمایا:اس (کے جائز استعمال)پر توجہ دینا اپنے آپ پر لازم کرلے، میں نے پوچھا:اے اللہ کے رسول!کیا ہم جو اس سے باتیں کرتے ہیں اس پر بھی ہمارا مواخذہ ہوگا؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:اے معاذ!تمہاری ماں تجھ سے محروم ہوجائے، لوگوں کو جہنم کی آگ میں ان کے چہروں کے بَل –یافرمایا:-ان کے نتھنوں کے بل جہنم کی آگ میں سوائے ان کی زبانوں کی کاٹی ہوئی فصل کے اور کونسی چیز ڈالے گی؟‘‘","حسن",{"k":"سنن ترمذی (2616)، سنن ابن ماجه (3973)، إرواء الغلیل للألبانی (413)۔"}],[303,"عقبہ بن عامر رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’ایک روز میں رسول اللہ صلی اللہ علیہ وسلم سے ملا تو میں نے پوچھا:کس عمل میں نجات ہے؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:اے عقبہ!اپنی زبان کو اپنے قابو میں رکھ، تمہارا گھر تمہیں کھلی جگہ دے اور اپنے گناہوں پر رویا کر۔‘‘","صحیح",{"k":"سنن ترمذی (2406)، سلسلہ الأحادیث الصحیحہ (890)۔","f":"گھر کے جگہ دینے سے مراد یہ ہے کہ خانہ نشین ہوکررہ جا، اپنے معمولات کے علاوہ جو اضافی وقت ہے وہ اپنے گھر میں ہی گزار، زبان کا درست استعمال کرنا اور اسے غلط استعمال ہونے سے بچائے رکھنا اور اپنے گناہوں پہ اشکبار رہنا، انہی امور میں نجات پنہاں ہے۔"}],[304,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’آدمی کے گناہ گار ہو نے کے لیے یہی کافی ہے کہ وہ ہرسُنی سنائی بات آگے بیان کردے۔‘‘","صحیح",{"k":"صحیح مسلم (5)، سنن أبوداؤد (4992)۔","f":"یہ عادتِ بد بہت سے لوگوں میں پائی جاتی ہے کہ جس کسی سے بھی جیسی تیسی بات سنی اس کی تحقیق کیے بغیر فوری آگے بیان کر دی۔ نامعلوم کہ وہ بات سچ ہے یا جھوٹ۔ اگر جھوٹ ہو تو یہ اک جھوٹی بات کی تشہیر کرنے کی وجہ سے بہت قبیح گناہ ہے اور اگر سچ بھی ہو تو پھر بھی یہ کسی طور پر درست نہیں ہے کیونکہ جس کی بات اڑائی جا رہی ہوتی ہے درحقیقت اس کی تذلیل کی جا رہی ہوتی ہے جو کہ بہ جائے خود کبیرہ گناہ ہے۔ اس لیے اس عادتِ بد کو اپنا کر بہ فرمانِ نبویؐ گناہ گاروں میں شامل نہیں ہونا چاہیے۔"}],[305,"عبداللہ بن عمروبن عاص رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’مسلمان وہ ہے جس کی زبان اور اس کے ہاتھ سے دوسرے مسلمان محفوظ ہوں، اور مہاجر وہ ہے جو اللہ تعالٰی کے منع کردہ کاموں کو چھوڑ دے۔‘‘","صحیح",{"k":"صحیح بخاری (10)، سنن أبوداؤد (2481)۔","f":"گویا مسلمان کی علامت ہی یہ بتلائی ہے کہ جس شخص کی زبان اور ہاتھ سے دیگر مسلمان محفوظ ہوں وہی مسلمان ہے اورجس کی زبان دراز یوں اور دست دراز یوں سے دوسرے مسلمان محفوظ نہ ہوں وہ کامل مسلمان ہے۔"}],[306,"جابربن عبداللہ رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے کعب بن عجرہؓ سے فرمایا:\n’’اے کعب بن عجرہ!اللہ تعالٰی تجھے بیوقوف لوگوں کی امارت(حکمرانی)سے بچا کر رکھے، انہوں نے عرض کیاکہ بیوقوف لوگوں کی امارت سے کیا مراد ہے؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:میرے بعد ایسے امراء(حکمران)آئیں گے جو میری (دی ہوئی)راہنمائی کے مطابق ہدایات نہیں کریں گے اور نہ ہی وہ میری سُنّت کی پیروی کریں گے، سوجس شخص نے ان کے جھوٹا ہو نے کے باوجود انہیں سچا کہا اور ظلم پر ان کی معاونت کی تو یہی وہ لوگ ہیں جن کا مجھ سے کوئی تعلق نہیں اور نہ ہی میرا ان سے کوئی تعلق ہے اور نہ ہی یہ میرے حوض (یعنی حوضِ کوثر)پہ آسکیں گے، لیکن جس نے ان کے جھوٹ کوسچ نہ کہا اور نہ ہی ظلم پر ان کی مدد کی تو انہی لوگوں کا مجھ سے تعلق ہے اور میرا ان سے تعلق ہے اور یہ میرے حوض پر بھی آسکیں گے۔ اے کعب!روزہ (گناہوں سے بچاؤ کے لیے)ڈھال ہے، صدقہ گناہوں کو مٹا دیتا ہے اور نماز(اللہ تعالٰی کے)بہت ہی قریب کرنے والی ہے، یافرمایا کہ نماز قطعی دلیل ہے۔ اے کعب بن عجرہ!حرام سے پرورش پانے والا گوشت(یعنی جسم)جنّت میں نہیں جائے گا، بلکہ وہ آگ کے زیادہ لائق ہے۔ اے کعب بن عجرہ!صبح سویرے دو آدمی (اپنے معمولاتِ زندگی کا)قصد کرتے ہیں، (ان میں سے ایک)اپنے نفس کو خرید کر آزاد کر دیتا ہے اور(دوسرا)اپنے نفس کو بیچ کر ہلاک کر دیتا ہے۔‘‘","صحیح",{"k":"مسند أحمد (3؍321)، مستدرک حاکم (4؍422)، صحیح ابن حبان (1569)، صحیح الترغیب والترهیب (2242)۔"}],[307,"ابوہریرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’یقیناًبندہ اللہ تعالٰی کی رضامندی والی کبھی ایسی بات کرتاہے جسے وہ (اپنی نظر میں)کوئی اہمیت نہیں دیتا، لیکن اللہ تعالٰی اسی بات کی وجہ سے اس کے درجات بلند فرما دیتا ہے، اور بسااوقات بندہ اللہ کی ناراضگی والی کوئی ایسی بات کہہ دیتا ہے جسے وہ کوئی اہمیت نہیں دے رہا ہوتا، لیکن وہ اسی بات کی وجہ سے جہنّم میں جا گرتا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (6478)، مسند أحمد (2؍334)۔","f":"اس لیے زبان سے کوئی بھی بات نکالتے وقت نہایت احتیاط کو ملحوظ رکھنا چاہیے اور عمدہ ومناسب گفتگو کرنی چاہیے، تاکہ زبان سے اللہ تعالیٰ کی ناراضگی کو مول لینے والا کوئی بھی بول نکلنے نہ پائے۔"}],[308,"بہزبن حکیم اپنے باپ کے حوالے سے اپنے دادا سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’اس آدمی کے لیے ہلاکت ہے جو لوگوں کو ہنسا نے کے لیے جھوٹی باتیں کرتاہے، اس کے لیے ہلاکت ہے، اس کے لیے ہلاکت ہے۔‘‘","حسن",{"k":"سنن أبوداؤد (4990)، سنن ابن ماجه (2315)، صحیح الجامع للألبانی (7136)۔","f":"ہمارے معاشرے میں یہ برائی بہت عام ہے اور بدقسمتی سے اس کے مرتکب کوبہ طورِاعزاز فنکار اور ادا کار کا نام دیا جاتا ہے، جبکہ شریعت نے ایسے شخص کے لیے ہلاکت کی سخت وعید فرمائی ہے۔ ہمارے معاشرے کی اجتماعی زبوں حالی کا یہ عالم ہے کہ اس بیہودہ گوئی کا مظاہرہ کرنے اور اس سے لطف اندوز ہو نے کے لیے تھیٹرز میں باقاعدہ محافل لگائی جاتی ہیں اور شیطان کے بہکاوے میں آکر بہت سے لوگ زرِکثیر خرچ کر کیبڑے شوق سے اس وعید کے مستوجب ٹھہرتے ہیں۔ (العیاذباللہ)"}],[309,"عماربن یاسر رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’جو دنیا میں دورُخا)یعنی دو غلا(ہو، قیامت کے دِن اسے آگ کی دو زبانیں لگائی جائیں گی۔‘‘","صحیح",{"k":"سنن أبوداؤد (4873)، سلسلہ الأحادیث الصحیحہ (892)۔"}],[310,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’دو غلے شخص کے یہ لائق ہی نہیں ہے کہ وہ امانت دار ہو۔‘‘","صحیح",{"k":"السنن الکبری للبیهقی (10؍246)، الأدب المفرد للبخاری (313)۔","f":"یعنی وہ کسی کی بات کو بطورِامانت اپنے پاس محفوط نہیں رکھ سکتا، اس لیے وہ اس بات کے لائق ہی نہیں ہے کہ اسے امین کہایا سمجھا جائے۔"}],[311,"عبداللہ بن عمرو رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’چار خصلتیں ایسی ہیں کہ وہ جس میں بھی پائی جائیں گی وہ پکّامنافق ہوگا، اورجس میں ان میں سے کوئی ایک خصلت پائی جائے گی تو اس میں نفاق کی ایک خصلت ہوگی، جب تک کہ وہ اسے چھوڑ نہیں دیتا، (وہ یہ ہیں:)جب بات کرے تو جھوٹ بولے، جب معاہدہ کرے تو دھو کہ دے، جب وعدہ کرے تو خلاف ورزی کرے اورجب جھگڑا کرے تو بدزبانی کرے۔‘‘","صحیح",{"k":"صحیح بخاری (34)، صحیح مسلم (58)۔"}],[312,"ابوبکرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم کے پاس ایک آدمی نے کسی شخص کی تعریف کردی، تو نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’تجھ پر افسوس ہے تُونے اپنے (مسلمان)بھائی کی گردن کاٹ دی، آپ صلی اللہ علیہ وسلم نے یہ کئی مرتبہ فرمایا۔ اگر وہ شخص(جس کی تُونے تعریف کی ہے)اسے سُن لیتا تو وہ اس کے بعد کبھی کامیابی نہ پاتا، اس لیے اگر تم میں سے کسی کو اپنے مسلمان بھائی کی ضرور ہی تعریف کرنی ہو اور وہ اس کی خوبی کو جانتا ہو تو اسے یوں کہنا چاہیے کہ میں فلاں شخص کو ایسا ایسا سمجھتا ہوں، باقی اللہ تعالٰی اسے بہتر جانتا ہے، میں اللہ تعالٰی کے سامنے کسی کوبے عیب نہیں کہہ سکتا۔‘‘","صحیح",{"k":"صحیح بخاری (2662)، صحیح مسلم (3000)۔","f":"یعنی کسی مسلمان بھائی کی تعریف کرنا بھی ہو تو اس کی خوبی یاا چھائی کے بارے میں اپنی رائے تو دی جاسکتی ہے لیکن حتمی نہ قرار دیا جائے بلکہ یوں کہہ دینا چاہیے کہ میری رائے میں تو وہ فلاں فلاں خوبی کا حامل ہے، باقی حقیقتِ حال سے اللہ ہی واقف ہے۔"}],[313,"ہمام بن حارث بیان کرتے ہیں کہ:\n’’ایک آدمی عثمان رضی اللہ عنہ کی تعریف کرنے لگا تو مقدامؓ کھڑے ہوئے اور اس پر مٹی ڈال دی اور کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں حکم فرمایاکہ ہم تعریف کرنے والوں کے مونہوں میں مٹی ڈال دیں۔‘‘","صحیح",{"k":"صحیح مسلم (3002)۔"}],[314,"عبداللہ بن شخیر رضی اللہ عنہ روایت کرتے ہیں کہ وہ بنو عامر کے ایک وفد کے ہمراہ نبی صلی اللہ علیہ وسلم کے پاس آئے، کہتے ہیں کہ:\n’’ہم آپ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور ہم نے سلام کیا، پھر ہم نے کہا:آپ صلی اللہ علیہ وسلم ہمارے باپ (بہ جا)ہیں، آپ صلی اللہ علیہ وسلم ہمارے سردار ہیں، آپ صلی اللہ علیہ وسلم ہم سب سے زیادہ ہم پر سخاوت کرنے والے ہیں اور آپ صلی اللہ علیہ وسلم بہت ہی فیاض ومہربان ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا:تم اپنی بات کہہ لو، لیکن شیاطین تمہیں اپنے پیچھے نہ لگا لیں، یایوں فرمایاکہ شیاطین تمہیں اپنے جال میں نہ پھنسا لیں، میں(فقط)محمد، اللہ کا بندہ اور اس کا رسول ہوں، مجھے یہ بالکل پسند نہیں ہے کہ تم مجھے اللہ تعالٰی کے عطا کردہ مقام ومرتبے سے بڑھا چڑھا کر کوئی مقام دو۔‘‘","صحیح",{"k":"سنن أبوداؤد (4806)، مسند أحمد (3؍241)۔"}],[315,"سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم تمہاری طرح تیز تیز باتیں نہیں کیا کرتے تھے بلکہ آپ صلی اللہ علیہ وسلم ٹھہر ٹھہر کر بات کرتے، جسے ہرسننے والا یاد کر لیتا۔‘‘","حسن",{"k":"سنن ترمذی (3639)، الشمائل المحمدیہ للترمذی (112)۔"}],[316,"جابربن عبداللہ رضی اللہ عنہ فرماتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم کی کلام میں انتہائی ٹھہراؤ ہوتا تھا۔‘‘","صحیح",{"k":"سنن أبوداؤد (4838)۔"}],[317,"ابووائل بیان کرتے ہیں کہ:\n’’عمار رضی اللہ عنہ نے ہمیں انتہائی بلیغ اور بہت مختصر خطبہ دیا، جب وہ (منبر سے)اُترے تو ہم نے کہا:اے ابویقظان!آپ نے انتہائی بلیغ اور بہت مختصر خطبہ دیا ہے اگر آپ تھوڑا لمبا کر دیتے تو اچھا ہوتا، تو عمارؓنے جواب دیا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:آدمی کا نماز لمبی ادا کرنا اور خطبہ مختصر دینا اس کے سمجھدار ہو نے کی نشانی ہے، سوتم نماز لمبی پڑھا کرو اور خطبہ مختصر دیا کرو، اور بلاشبہ کوئی بیان جا دو اثر ہوتا ہے۔‘‘","صحیح",{"k":"صحیح مسلم (869)، مسند أحمد (4؍264)۔"}],[318,"عمروبن عاص رضی اللہ عنہ سے مروی ہے کہ:\n’’ایک آدمی کھڑا ہوا اور اس نے بہت ساری باتیں کیں، تو عمروؓنے کہا:اگر یہ اپنی بات میں میانہ روی اپناتا تو اس کے لیے بہتر ہوتا، کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:میرا خیال ہے، یا(فرمایاکہ)مجھے حکم دیا گیا ہے کہ میں اپنی بات میں میانہ روی اپناؤں، کیونکہ بلاشبہ میانہ روی خیروبھلائی ہی ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (5008)۔"}],[319,"ابووائل بیان کرتے ہیں کہ:\n’’عبداللہ رضی اللہ عنہ ہرجمعرات کو ہمیں وعظ ونصیحت کیا کرتے تھے، ان سے کسی نے کہا:ہم چاہتے ہیں کہ آپ ہمیں روزانہ وعظ فرمایا کریں۔ تو انہوں نے جواب دیا کہ میں تمہیں مقررہ دِنوں میں ہی وعظ کیا کروں گا، کیونکہ رسول اللہ صلی اللہ علیہ وسلم بھی ہمارے اُکتا جا نے کو ناپسند کرنے کی وجہ سے ہمیں مقررہ دِنوں میں ہی وعظ فرمایا کرتے تھے۔‘‘","صحیح",{"k":"صحیح بخاری (6411)، صحیح مسلم (2821)۔","f":"سیدنا عمربن خطاب، عبداللہ بن مسعود، عبداللہ بن عباس اور سیدہ عائشہ رضی اللہ عنہم سے بھی لمبے وعظ کی ناپسندیدگی روایت کی گئی ہے۔ سیدہ عائشہ رضی اللہ عنہا نے عبیدبن عمر سے فرمایا:لوگوں کواُکتاہٹ میں ڈالنے اور مایوس کرنے سے بچو۔ عبداللہ بن مسعود رضی اللہ عنہ فرماتے تھے:لوگوں کوتب تک وعظ ونصیحت کر وجب تک ان کے دِل تمہاری طرف متوجہ رہیں، لیکن جب ان کے دِل تم سے مُڑجا ئیں تو پھر ان سے بات نہ کرو۔ پوچھا گیا کہ اس کی کیا علامت ہے کہ ان کے دِل متوجہ ہیں یانہیں؟ تو انہوں نے فرمایا:جب وہ اپنی نظریں تم پہ گاڑے تمہاری باتیں کررہے یاسُن رہے ہوں تب تک ان سے مخاطب رہو اورجب وہ ایک دوسرے پر ٹیک لگانے اور جمائیاں لینے لگیں تو اپنی بات ختم کردو۔"}],[320,"ابوہریرہ رضی اللہ عنہ اس حدیث کو مرفوعاًبیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’کیا میں تمہیں اس اُمت کے بدترین لوگوں کا نہ بتلاؤں؟ وہ بہت زیادہ باتیں کرنے والے، باچھیں ہلا ہلا کر بولنے والے اور بڑھا چڑھا کر بات کرنے والے ہیں۔ کیا میں تمہیں ان کے اچھے لوگوں کا نہ بتلاؤں؟ یہ وہ ہیں جوان میں سب سے اچھے اخلاق والے ہیں۔‘‘","صحیح",{"k":"السنن الکبری للبیهقی (10؍194)۔","f":"«اَلثِّرْثَارُ» کا معنٰی ہے بہت زیادہ بولنے والا اور فضول وبے مقصد باتیں کرنے والا، جسے ہم باتونی کہتے ہیں، «الْمُتَشَدِّقُ» کا مطلب ہے لوگوں کو متاثر کرنے اور انہیں اپنی عمدہ کلامی باور کروا کر ان کے دِل موہ لینے کے لیے باچھیں ہلا ہلا کر اور جبڑے موڑ کر(یعنی منہ کے مختلف انداز بنا کر)تکلّف سے بولنے والا اور اَلْمُتَفَيْهِقُسے مراد وہ ہے جو کلام میں وسعت پیدا کرتا جائے، یعنی الفاظ وکلمات کو مختلف انداز سے دوہرا دوہرا کر اپنی بات کو لمبا کرنے والا۔ بعض مقررین متذکرہ بالا امور کو اپنے تئیں ادیبا نہ اور خطیبا نہ خصلت سمجھتے ہیں اور عمداًوتکلّفاًایسے انداز اپناتے ہیں، حالانکہ ایسا کرنے والوں کو نبی مکرم صلی اللہ علیہ وسلم نے اس اُمت کے بدترین لوگ کہا ہے۔ممانعت میں اس قدرشدّت کی وجوہ یہ ہیں کہ ان امور سے اولاًتو خلوص کی بہ جائے بناوٹ اور دکھاوا ہوتا ہے جوکہ کسی بھی عمل کے عدمِ قبولیت کااوّلیں سبب ہے، دوسرا اس طرح عجز وانکساری بھی نہیں رہتی بلکہ بڑائی کا اظہار ہوتا ہے اور آدمی مخاطبین پر اپنا علمی وادبی رعب بٹھا نے کی کوشش کرتاہے جوکہ شرعاًقطعی ناجائز بلکہ حرام ہے اور دوسری قباحت یہ ہے کہ اس طرح کے تکلفات سے گفتگو اس قدر مشکل اور پیچیدہ ہوجاتی ہے کہ بہت سے سامعین کے فہم سے بالاتر رہتی ہے اور یوں مقرر اور سامع دونوں اپنے مقاصد کے حصول میں ناکام رہتے ہیں، لہٰذا ان ممنوعہ امور سے بالکل احتراز کرنا چاہیے اور سادہ وعام فہم انداز وکلمات اپنانے چاہییں، کیونکہ بات جس قدر سادہ ہوگی اتنی ہی جلدی سمجھ میں آئے گی اور اللہ تعالٰی بھی دل سے نکلی ہوئی بات میں، خواہ وہ سادہ سے انداز میں ہی کہی گئی ہو، ایسی تاثیر پیدا کر دیتا ہے کہ وہ دِلوں میں اثر کر جاتی ہے اور سامعین بھی اس سے بہ خوبی حظ اٹھاتے ہیں۔"}],[321,"عبداللہ بن عمرو رضی اللہ عنہما نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’یقیناًاللہ تعالٰی لوگوں میں سے ایسے بلاغت والے شخص سے بغض ونفرت کرتا ہے جو اپنی زبان کو ایسے چلائے جیسے گائے اپنی زبان کو چلاتی ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (5005)، سنن ترمذی (2853)، سلسلہ الأحادیث الصحیحہ (880)۔","f":"یہ تشبیہ ایسے شخص کے ساتھ دی گئی ہے جو گفتگو کرتے ہوئے تکلّفاًبناوٹ اور تصنع کاسا انداز اپناتا ہے اور طرح طرح سے منہ کے مختلف انداز بناتا ہے۔"}],[322,"اسماء بنت ابی بکر رضی اللہ عنہا بیان کرتی ہیں کہ:\n’’ایک عورت نبی صلی اللہ علیہ وسلم کے پاس آئی اور اس نے پوچھا:اے اللہ کے رسول!)میری ایک سوکن ہے، تو)کیا یہ میرے لیے درست ہے کہ میں(اسے جلانے کے لیے یہ)کہوں کہ میرے خاوند نے مجھے(فلاں چیز)دی ہے حالانکہ اس نے دی نہ ہو، تو کیا اس کا مجھ پر کوئی گناہ ہے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس نے کسی ایسی چیز پر شکم سیری کا اظہار کیا جو اسے ملی ہی نہ ہو تو وہ جھُوٹ کے دو کپڑے پہننے والے کے مانند ہے۔‘‘","صحیح",{"k":"صحیح بخاری (5219)، صحیح مسلم (2130)۔","f":"اس حدیث میں اس عورت یااس شخص کاحکم بیان کیا گیا ہے جسے کسی نے کوئی چیز نہ دی ہو لیکن وہ لوگوں کو کہتا پھرے کہ مجھے فلاں نے یہ چیز دی ہے، اورجھُوٹ کے دو کپڑوں کا ذکر اس لیے فرمایا کہ اس کو دو طرح کا نقصان ہوا، ایک تو وہ اس چیز سے بھی محروم رہا، یعنی وہ چیز اسے سرے سے ملی بھی نہیں لیکن اس نے یوں ہی کہہ دیا، اور دوسرا نقصان یہ کہ اس نے جھُوٹ بول کر گناہ کما لیا۔ ویسے یہ حکم عام ہے، لیکن اس حکم کے صدور کی جو وجہ حدیث میں مذکور ہے اور سوال کرنے والی عورت نے جس بنیاد پر یہ مسئلہ پوچھا تھا درحقیقت وہ بہ جائے خود ایک بُراعمل ہے، یعنی اپنی سوکن کو جلا نے کے لیے جھوٹ بولنا۔ لہٰذا اس ایک برے عمل سے کتنی اور بھی برائیاں متعلق ہیں جس وجہ سے اس کی قباحت میں اضافہ ہو جاتا ہے۔"}],[323,"سہل بن حنیف رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’تم میں سے کوئی بھی یوں ہرگز نہ کہے کہ میرا نفس پلیدو ناپاک ہو گیا ہے، بلکہ اسے یوں کہنا چاہیے کہ میرا نفس سُست پڑگیا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (6180)، صحیح مسلم (2251)۔","f":"اصل میں یہ عرب کے محاورے تھے، وہ جب طبیعت میں تنگی محسوس کرتے تو ایسا بولا کرتے تھے۔پہلے محاورے میں نفس کے ناپاک ہونے کا ذکر ہے اس لیے اسے بولنے سے منع کیاگیا، کیونکہ مومن کا نفس ناپاک نہیں ہوتا بلکہ کافر کا نفس ناپاک ہوتاہے۔"}],[324,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’تم انگور کو کرم ہرگز نہ کہا کرو، کیونکہ کرم تو صرف مسلمان شخص ہوتاہے۔‘‘","صحیح",{"k":"صحیح بخاری (6183)، صحیح مسلم (2247)۔","f":"یعنی یہ بھی بولنے میں بے احتیاطی ہے کہ مسلمان کی ایک خصلتِ مدیحہ کو کسی پھل کے نام کے طور پر بولا جائے، چنانچہ آپ صلی اللہ علیہ وسلم نے شدتِ احتیاط کے پیشِ نظر اس سے بھی منع فرمادیا۔"}],[325,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’تم میں سے کوئی بھی (اپنے غلام اور لونڈی کو)’میرے بندے‘اور’میری بندی‘ ہرگز نہ کہے، اور کوئی غلام اور لونڈی بھی (اپنے مالک کو)’اے میرے رب‘ ہرگز نہ کہے، بلکہ مالک کو چاہیے کہ وہ یوں کہے:اے جوان لڑکے، اے جوان لڑکی۔ اور غلام ولو نڈی کو یوں کہنا چاہیے:اے میرے سردار، کیونکہ تم سبھی غلام ہو اوررب صرف اللہ تعالٰی ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4975)۔"}],[326,"اور نبی صلی اللہ علیہ وسلم کا فرمان ہے کہ:\n’’تم ایسے مت کہو کہ جو اللہ تعالٰی اور فلاں چاہے، بلکہ یوں کہو کہ جو اللہ تعالٰی چاہے، پھر فلاں چاہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4980)۔"}],[327,"ایک روایت میں ہے کہ:\n’’ایک خطیب نے نبی صلی اللہ علیہ وسلم کے پاس )ان الفاظ میں(خطبہ دیا: «مَنْ يُطِعِ اللّٰهَ وَرَسُولَهُ فَقَدْ رَشَدَ وَمَنْ يَعْصِهِمَا فَقَدْ» غَوٰى’’جو اللہ تعالٰی اور اس کے رسول کی اطاعت کرے گاوہ ہدایت پائے گااور جو ان دونوں کی نافرمانی کرے گاوہ گمراہ ہوگا۔‘‘ تو نبی صلی اللہ علیہ وسلم نے فرمایا:تُوبُراخطیب ہے، (ایسے نہیں بلکہ یوں)کہہ: «مَنْ يَعْصِ اللّٰهَ وَرَسُولَهُ فَقَدْ غَوٰى» ’’جو اللہ تعالٰی اور اس کے رسول کی نافرمانی کرے گاوہ گمراہ ہوگا۔‘‘","صحیح",{"k":"صحیح مسلم (870)، سنن أبوداؤد (1099)۔","f":"نبی صلی اللہ علیہ وسلم نے ادبِ خداوندی کا پاس کرتے ہوئے خطبہ دینے والے اس شخص کو اللہ تعالیٰ اور اس کے رسول کا ایک ہی ضمیر(Pronoun)کے ساتھ اکٹھاذِکر کرنے سے منع فرما دیا اور ان دونوں ناموں کو الگ الگ بیان کرنے کاحکم فرمایا، یہ بھی بولنے میں شدید احتیاط اور ادبِ الہٰی کی درخشندہ مثال ہے۔"}],[328,"اور ایک روایت میں ہے کہ:\n’’نبی صلی اللہ علیہ وسلم نے قِیل وقال، کثرتِ سوال اور مال ضائع کرنے سے منع فرمایا۔‘‘","صحیح",{"k":"صحیح بخاری (5975)، صحیح مسلم (1715)۔","f":"قیل وقال سے مراد سنی سنائی باتیں آگے بیان کر دینا، کثرتِ سوال سے مراد ضرورت سے زیادہ اوربے معنیٰ وبے مقصد سوالات کرنا ہے اور مال ضائع کرنے کا مطلب مال کو ان امور میں سرف کرنا کہ جن میں خرچ کرنا فضول خرچی کے زمرے میں آتا ہو۔"}],[329,"نبی صلی اللہ علیہ وسلم نے لفظ زَعَمُوا(لوگوں کا خیال ہے)بولنے کے بارے میں فرمایا:\n’’لفظ زَعَمُواآدمی کے سوار ہو نے کا بہت برا جانور ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4972)۔","f":"اس روایت میں اس عادت کے ناپسندیدہ ہونے کی طرف اشارہ ہے، کہ بندہ بے اصل وبے بنیاد باتوں کو محض سُن سنا کر یاا پنے ہی گمان اور خیال کی بنیاد پر کسی بات کو آگے بیان کردے اور اسے لوگوں سے منسوب کردے کہ لوگوں کا یہ خیال ہے یالوگ یوں کہتے ہیں۔"}],[330,"بریدہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’تم کسی منافق کو سردارمت کہو۔‘‘","صحیح",{"k":"سنن أبوداؤد (4977)، مسند أحمد (5؍436)، سلسلہ الأحادیث الصحیحہ (370)۔","f":"سردار کہنے سے مراد یہ ہے کہ اس کے لیے عزت کا کوئی بھی ایسا لفظ نہ بولا جائے جس کا وہ لائق نہ ہو۔"}],[331,"اور نبی صلی اللہ علیہ وسلم کا فرمان ہے کہ:\n’’تُویہ مت کہہ کہ شیطان ہلاک ہو، بلکہ بسم اللہ کہہ، کیونکہ جب تو بسم اللہ کہے گاتو وہ (یعنی شیطان) اسقدر چھوٹا ہو جاتا ہے کہ مکھی کی طرح بن کررہ جاتا ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4982)، مسند أحمد (5؍59)، صحیح الجامع للألبانی (7401)۔"}],[332,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب آدمی کہے کہ لوگ ہلاک ہوگئے تو وہ خود ان سب سے زیادہ ہلاک ہونے والا ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2623)، سنن أبوداؤد (4983)۔","f":"کیونکہ لوگوں کی ہلاکت وبربادی کا فیصلہ کرنے کا اس شخص کو قطعی حق حاصل نہیں ہے، یہ اللہ تعالیٰ کا معاملہ ہے، تو ایسا کہنے کی وجہ زبان کا ناجائز استعمال ہے، اسی لیے آپ صلی اللہ علیہ وسلم نے اسے سب سے زیادہ ہلاکت کا مارا قرار دیا۔"}],[333,"ابوامامہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’میں اس شخص کے لیے جنّت کے ایک گوشے میں بنے گھر کا ضامن ہوں جوحق پر ہو نے کے باوجود جھگڑا چھوڑ دے، اور درمیانِ جنّت(میں قائم گھر)کی اس کے لیے ضمانت دیتا ہوں جو مزاح میں بھی جھوٹ بولنا چھوڑ دے اورجنّت کے اعلٰی درجے میں تعمیر گھر کا اس کے لیے ضامن ہوں جس کا اخلاق اچھا ہو۔‘‘","حسن",{"k":"سنن أبوداؤد (4800)، سلسلہ الأحادیث الصحیحہ (273)۔"}],[334,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’پرہیز گاربن جا؛ تمام لوگوں سے زیادہ عبادت گزاربن جائے گا، قناعت پسند ہو جا؛ تمام لوگوں سے بڑھ کر شکر گزاربن جائے گا، لوگوں کے لیے وہی کچھ پسند کرنے لگ جا جوتُواپنے لیے پسند کرتا ہے؛ حقیقی مومن بن جائے گا، اپنے ہمسائے کے ساتھ اچھی ہمسائیگی کا ثبوت دے؛ حقیقی مسلمان بن جائے گااور ہنسناکم کردے؛ کیونکہ زیادہ ہنسنادِل کومُردہ کر دیتا ہے۔‘‘","صحیح",{"k":"سنن ابن ماجه (4217)، سلسلہ الأحادیث الصحیحہ (506)۔"}],[335,"انس بن مالک رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’اگر تمہیں اس کا پتہ چل جائے جسے میں جانتا ہوں تو تم تھوڑا ہنسو اور زیادہ روؤ۔‘‘","",{}],[336,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’(رسول اللہ صلی اللہ علیہ وسلم سے)کہا گیا:اے اللہ کے رسول!آپ صلی اللہ علیہ وسلم تو ہمارے ساتھ ہنسی مذاق بھی کرلیتے ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا:لیکن میں سوائے حق بات کے اور کچھ نہیں بولتا۔‘‘","صحیح",{"k":"سنن ترمذی (1990)، مسند أحمد (2؍340)۔","f":"مزاح اور خوش طبعی کو اسلام نے ناجائز ونا پسندیدہ قرار نہیں دیا بلکہ فرحتِ نفس کے لیے جھوٹ اور لغو باتوں سے پاک جائز مزاح کرنا مباح ہے اور اس کی متعدد مثالیں نبی کریم صلی اللہ علیہ وسلم کی حیاتِ طیبہ سے بھی ملتی ہیں، جن میں سے چند ایک زینتِ قرطاس ہیں۔"}],[337,"انس رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’اُمِ سُلیم کا ایک بیٹا تھا جسے ابو عمیر کے نام سے پکارا جاتا تھا، وہ جب نبی صلی اللہ علیہ وسلم کے پاس آتا تو آپ صلی اللہ علیہ وسلم اس سے مزاح کیا کرتے تھے، ایک روز وہ آیا اور آپ صلی اللہ علیہ وسلم اس سے مزاح کرنے لگے تو آپ صلی اللہ علیہ وسلم نے اسے غمگین پایا، آپ صلی اللہ علیہ وسلم نے پوچھا:کیا بات ہے میں ابو عمیر کو پریشان دیکھ رہا ہوں؟ تو گھر والوں نے بتایا کہ اس کا چڑیا کا بچہ مرگیا ہے جس سے یہ کھیلا کرتا تھا۔ تو آپ صلی اللہ علیہ وسلم اسے یوں آواز دینے لگے:اے ابو عمیر!تیرے چڑیا کے بچے نے کیا کر دیا؟‘‘","صحیح",{"k":"صحیح بخاری (6129)، صحیح مسلم (2150)۔"}],[338,"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم سے سواری کا مطالبہ کیا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:میں تمہیں اونٹنی کا بچہ دیتا ہوں، اس نے کہا:اونٹنی کے بچے کا میں کیا کروں گا؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:کیا اونٹ کو اونٹنی ہی جنم نہیں دیتی؟‘‘","صحیح",{"k":"سنن أبوداؤد (4998)، سنن ترمذی (1991)۔"}],[339,"انس رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم مجھے يَاذَا الْأُذُنَيْنِ(اے دو کانوں والے!)کہا۔‘‘","صحیح",{"k":"سنن أبوداؤد (5002)، سنن ترمذی (1992)، مسند أحمد (3؍242)۔"}],[340,"سیدنا انس رضی اللہ عنہ روایت کرتے ہیں کہ:\n’’زاہربن حرام نامی ایک دیہاتی شخص تھا، وہ خوبصورت نہیں تھا لیکن نبی صلی اللہ علیہ وسلم اسے پسند فرماتے تھے، ایک روز نبی صلی اللہ علیہ وسلم اس کے پاس تشریف لائے اور وہ اپنا سامان بیچ رہاتھا، آپ صلی اللہ علیہ وسلم نے اسے پیچھے سے اپنی بانہوں میں لے لیا اور آپ صلی اللہ علیہ وسلم اسے نظر نہیں آرہے تھے، اس نے کہا:چھوڑو مجھے، کون ہو؟ جب اس نے توجہ کی تو اس نے نبی صلی اللہ علیہ وسلم کو پہچان لیا، تو وہ اپنی پُشت کو نبی صلی اللہ علیہ وسلم کے سِینۂ مبارک کے ساتھ لگانے لگا، اور نبی صلی اللہ علیہ وسلم فرمانے لگے:یہ بندہ مجھ سے کون خریدے گا؟ اس نے عرض کیا:اے اللہ کے رسول!اللہ کی قسم!آپ صلی اللہ علیہ وسلم مجھے ردّی پائیں گے(یعنی میری بالکل قیمت نہیں ہے)، تو نبی صلی اللہ علیہ وسلم نے فرمایا:لیکن اللہ کے ہاں تُوردّی نہیں ہے، یایوں فرمایاکہ اللہ تعالٰی کے ہاں تُوقیمتی ہے۔‘‘","صحیح",{"k":"مسند أحمد (3؍161)، الشمائل المحمدیہ للترمذی (121)۔"}],[341,"عبدالرحمان بن ابی لیلٰی بیان کرتے ہیں کہ:\n’’ہمیں اصحابِ محمد رضی اللہ عنہم نے بیان کیاکہ وہ نبی صلی اللہ علیہ وسلم کے ساتھ محوِسفر تھے کہ ان میں سے ایک آدمی سوگیا، ایک اور آدمی اس سے رسّی لینے گیا جو اس کے پاس تھی، اس نے وہ رسّی پکڑی تو وہ(سویا ہوا شخص)گھبرا گیا، تو نبی صلی اللہ علیہ وسلم نے فرمایا:مسلمان کے لیے جائز نہیں ہے کہ وہ کسی مسلمان کو گھبراہٹ میں ڈالے۔‘‘","صحیح",{"k":"سنن أبوداؤد (5004)، مسند أحمد (5؍362)، صحیح الجامع للألبانی (7658)۔"}],[342,"عبداللہ بن سائب بن یزید اپنے باپ کے واسطے سے اپنے دادا سے روایت کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’تم میں سے کوئی بھی اپنے ساتھی کا سامان مذاق اور حقیقت )کسی صورت(میں )بھی(ہرگز نہ اٹھائے۔ ایک اور روایت میں ہے کہ نہ تو مذاق میں اور نہ ہی حقیقت میں، اورجس نے اپنے ساتھی کی لاٹھی اُٹھا لی ہوا سے وہ بھی واپس کر دینی چاہیے۔‘‘","حسن",{"k":"سنن أبوداؤد (5003)، مسند أحمد (4؍221)۔"}],[343,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’کسی سچے شخص کے یہ بالکل لائق نہیں ہے کہ وہ بہت زیادہ لعنت کرنے والا ہو۔‘‘","صحیح",{"k":"صحیح مسلم (2597)۔","f":"[صحيح] السنن الكبرى للبيهقى:۸/۲۳-شعب الا يمان للبيهقى:۳۸۵۴-اس حدیث کی اصل صحیحین میں ہے: صحيح بخارى، كتاب الأدب، باب من كفر أخاه بغير تأويل فهو كما قال، ح:۶۱۰۵-صحيح مسلم، كتاب الإيمان، باب غلظ تحريم قتل الإنسان نفسه، ح:۱۱۰\nیعنی جو لعن طعن کرنے والا ہے وہ مرتبۂ صداقت پر فائز نہیں ہو سکتا اور جو صدیق ہے اسے ایسی بے ہودہ حرکت زیب نہیں دیتی اور اس کی شان کے ہی شایاں نہیں ہے۔"}],[344,"زیدبن اسلم بیان کرتے ہیں کہ:\n’’عبدالملک بن مروان اُمِ درداءؓ کی طرف بھیجا کرتے تھے اور ہم ان کی بیویوں کے ہاں رات بسر کرتے تھے اور ان سے کسی چیز کے بارے میں باہم سوال کرتے تھے، ایک رات وہ اُٹھے اور اپنی خادمہ کو بلایا، اس نے آنے میں تھوڑی سستی کی تو انہوں نے اسے لعنت کردی، اُمِ درداء رضی اللہ عنہا نے کہا:لعنت مت کرو، کیونکہ ابودرداء رضی اللہ عنہ نے مجھ سے بیان کیاکہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:بلاشبہ لعنت کرنے والے روزِقیامت نہ تو سفارش کرنے والے بن سکیں گے اور نہ ہی گواہی دینے والے۔‘‘","صحیح",{"k":"صحیح مسلم (2598)، سنن أبوداؤد (4907)۔","f":"یعنی لعنت وملامت کرنے والا اللہ تعالیٰ کے ان برگزیدہ بندوں میں شامل ہونے سے قاصر رہے گاجنہیں روزِقیامت گواہی دینے اور سفارش کرنے کے اعزاز سے نوازا جائے گا۔"}],[345,"ثابت بن ضحاک رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’جو چیز انسان کی ملکیت میں نہ ہو اس میں وہ نذر نہیں مان سکتا، مومن پر لعنت کرنا اسے قتل کردینے کے مترادف ہے، جس نے اپنے آپ کو کسی چیز سے قتل کر ڈالا وہ روزِقیامت اسی کے ذریعے عذاب سے دو چار کیا جائے گا، جس نے اسلام کے علاوہ کسی اوردِین کی قسم اٹھائی تو وہ اسی طرح ہوگا جیسے اس نے کہا اورجس نے کسی مومن کو کافر کہا تو وہ بھی اس کے قتل کہ طرح(گناہ کا مرتکب)ہوا۔‘‘","",{}],[346,"انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم گالم گلوچ، فحش گوئی اور لعن وطعن کرنے والے نہیں تھے، غصے کے وقت بھی کسی کو صرف اتنا ہی فرمایا کرتے تھے: «مَالَهُ تَرِبَتْ» جَبِينُهُ’’اس کی پیشانی خاک آلود ہو، اسے کیا ہو گیا ہے؟‘‘","صحیح",{"k":"صحیح بخاری (6031)، مسند أحمد (3؍129)۔","f":"«تَرِبَتْ جَبِينُهُعرب» کے ہاں بہ طورِمحاورہ بولا جاتا تھاجب کسی پر ناراضگی کا اظہار کرنا مقصود ہوتا تھا توتب اسے ایسا کہتے تھے، لیکن اس سے حقیقت مراد نہیں ہوتی تھی۔"}],[347,"ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’عیدالفطر یاعیدالاضحٰی کے دِن رسول اللہ صلی اللہ علیہ وسلم عیدگاہ میں تشریف لائے، آپ صلی اللہ علیہ وسلم نے نماز پڑھا کر لوگوں کو وعظ ونصیحت کی، پھر عورتوں کی طرف آئے اور فرمایا:اے عورتوں کی جماعت!صدقہ کیا کرو، کیونکہ میں نے جہنمیوں میں اکثر عورتیں دیکھی ہیں۔ عورتوں نے پوچھا:اے اللہ کے رسول!ایسا کیوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا:تم لعن طعن بہت زیادہ کرتی ہو اور خاوند کی ناشکری کرتی ہو۔ اے عورتوں کی جماعت!میں نے عقل ودِین میں ناقص تم سے بڑھ کر ایسی کوئی مخلوق نہیں دیکھی کہ جو اچھے بھلے آدمی کی عقل کو بھی ختم کر دیتی ہو۔ عورتوں نے پوچھا:ہماری عقل اوردِین کا نقص کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:کیا ایک عورت کی گواہی آدمی کی آدھی گواہی کے برابر نہیں ہے؟ انہوں نے جواب دیا:کیوں نہیں، تو آپ صلی اللہ علیہ وسلم نے فرمایا:یہ تمہاری عقل کی کمی کی وجہ سے ہی تو ہے۔ کیا ایسا نہیں ہے کہ جب عورت حائضہ ہوجاتی ہے تو نہ نماز پڑھ سکتی ہے اور نہ روزہ رکھ پاتی ہے؟ انہوں نے جواب دیا:جی ہاں، آپ صلی اللہ علیہ وسلم نے فرمایا:یہی اس میں دِین کی کمی کی وجہ ہے۔ پھر آپ صلی اللہ علیہ وسلم واپس آگئے، جب اپنے گھر پہنچے تو عبداللہ بن مسعود رضی اللہ عنہ کی بیوی زینب رضی اللہ عنہا آئیں اور وہ حاضری کی اجازت مانگنے لگیں۔ آپ صلی اللہ علیہ وسلم کو بتلایا گیا کہ اے اللہ کے رسول!زینب آئی ہیں اور آپ صلی اللہ علیہ وسلم سے ملاقات کے لیے اجازت مانگ رہی ہیں۔ آپ صلی اللہ علیہ وسلم نے پوچھا:کون زینب؟ بتلایا گیا کہ عبداللہ بن مسعودؓکی بیوی۔ آپ صلی اللہ علیہ وسلم نے فرمایا:ہاں، اسے اجازت دے دو، چنانچہ انہیں اجازت دے دی گئی۔ تو انہوں نے کہا:اے اللہ کے پیغمبر!آپ صلی اللہ علیہ وسلم نے ہمیں آج صدقہ وخیرات کاحکم فرمایا ہے، اور میرے پاس کچھ زیورات ہیں جنہیں میں صدقہ کرنا چاہتی ہوں، جبکہ(میرے خاوند)ابنِ مسعودؓکا خیال ہے کہ وہ اور ان کا بچہ ان لوگوں سے زیادہ حق رکھتے ہیں جن پر میں نے یہ صدقہ کرنا ہے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:ابنِ مسعود نے سچ کہا ہے، تمہارا خاوند اور تمہارا بچہ ان لوگوں سے زیادہ حق رکھتے ہیں جن پر تم صدقہ کروگی۔‘‘","صحیح",{"k":"صحیح بخاری (1462)۔"}],[348,"ابوبرزہ روایت کرتے ہیں کہ:\n’’ایک لونڈی اونٹ یاکسی سواری پر دو پہاڑوں کے درمیان(سفر کرتی جا رہی)تھی اور اس پر لوگوں کا کچھ سامان بھی لادا ہوا تھا، پہاڑ نے اسے مشکل میں ڈال دیا(یعنی پہاڑی راستہ کافی دشوار گزار تھا)تو رسول اللہ صلی اللہ علیہ وسلم کی اس کے پاس آمد ہوئی، اس نے جب آپ صلی اللہ علیہ وسلم کو دیکھا تو کہنے لگی:اے اللہ!اس سواری پر لعنت فرما، تو رسول اللہ صلی اللہ علیہ وسلم نے استفسار فرمایا:یہ کس کی لونڈی ہے؟ کوئی سواری یاا ونٹ جس پر اللہ کی لعنت کی جائے ہمارے ساتھ نہیں چل سکتا۔‘‘","صحیح",{"k":"صحیح مسلم (2596)، مسند أحمد (4؍420)۔"}],[349,"اور نبی صلی اللہ علیہ وسلم سے روایت کیا گیا ہے کہ:\n’’آپ صلی اللہ علیہ وسلم نے مُرغ کو گالی دینے سے منع کیا اور فرمایا:یہ نماز کے لیے بیدار کرتا ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (5101)، صحیح الجامع للألبانی (7314)۔"}],[350,"سیدنا ابنِ عباس رضی اللہ عنہما بیان کرتے ہیں کہ:\n’’عہدِرسالت میں ایک شخص سے ہو اچا دراُڑاکر لے گئی تو اس نے ہوا پر لعنت کردی، تو نبی صلی اللہ علیہ وسلم نے فرمایا:اس پر لعنت نہ کر، کیونکہ وہ تو(اللہ کے)حکم کی پابند ہے، اور یقیناًجس شخص نے کسی ایسی چیز(یاشخص)پر لعنت بھیجی جس کا وہ اہل نہیں تھا، تو وہ لعنت اسی پر لوٹ آتی ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4908)، سنن ترمذی (1978)، سلسلہ الأحادیث الصحیحہ (527)۔"}],[351,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’یقیناًاللہ تعالٰی نے تم سے عہدِجاہلیت کی بری عادتیں اور آباء واجداد کی وجہ سے فخر کرنا ختم کر دیا ہے، متقی مومن اور بدبخت فاجر، تمام انسان آدم علیہ السلام کی اولاد ہیں اور آدمؑ کی پیدائش مٹی سے ہوئی ہے۔ تمام قومیں عہدِجاہلیت میں اپنے آباء واجداد پر فخر کرنے کی عادت سے لازماًباز آجائیں، ورنہ وہ اللہ تعالٰی کے ہاں اس کالے کیڑے سے بھی کمتر ہو جائیں گے جو اپنی ناک سے گندگی دھکیلتا ہے۔‘‘","حسن",{"k":"سنن أبوداؤد (5116)، سنن ترمذی (3956)، صحیح الجامع للألبانی (1787)۔","f":"اس حدیث کے ابتدائی الفاظ میں اس بات کی طرف اشارہ ہے کہ آدمی دو ہی قسم کے ہو سکتے ہیں:ایک تو متقی وپر ہیز گار مومن اور دوسرا شقی وبدبخت فاجر۔ اس روحانی تقسیم کے علاوہ انسانیت کی کوئی تقسیم نہیں کی جاسکتی، بلکہ تمام بنی نوعِ انسان ایک ہی باپ یعنی آدم علیہ السلام کی اولاد ہو نے کے ناطے سے برابر ہیں، کسی کو کسی پر چنداں کوئی فضیلت حاصل نہیں ہے۔ اپنے حسب ونسب اور آباء واجداد کی دنیوی شان شوکت پر فخر کرنا اوراِترانا جاہلی امور میں سے ہے، کیونکہ اسلام اس کی قطعاًاجازت نہیں دیتا بلکہ اسلام نے آکر ہی اس مذموم سوچ کی بیخ کنی کی ہے۔"}],[352,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’لوگ قومی فخر بالکل چھوڑ دیں، بلاشبہ یہ تو جہنم کا کوئلہ ہے۔‘‘","حسن",{"k":"سنن أبوداؤد (5116)، سنن ترمذی (3956)، صحیح الجامع للألبانی (1787)۔"}],[353,"عبیداللہ بن ابی یزید روایت کرتے ہیں کہ انہوں نے ابنِ عباس رضی اللہ عنہما کو فرماتے سنا:\n’’عہدِجاہلیت کی عادات میں سے (تین)عادتیں(یہ ہیں:)نسب میں طعن کرنا، میت پر نوحہ کرنا اور تیسری وہ بھول گئے۔ سفیان کہتے ہیں کہ تیسری عادت وہ یہ فرماتے تھے کہ ستاروں کے ذریعے بارش مانگنا۔‘‘","صحیح",{"k":"صحیح بخاری (3850)۔"}],[354,"ابو مالک اشعری رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’میری اُمت میں چار کام دورِجاہلیت کے ہوں گے، جنہیں لوگ چھوڑیں گے نہیں: حسب پر فخر کرنا، نسب پر طعن کرنا، ستاروں کے ذریعے بارش طلب کرنا اور میت پر نوحہ کرنا، اور نوحہ کرنے والی عورت نے اگر مرنے سے پہلے توبہ نہ کی تو وہ(روزِقیامت اس حالت میں)کھڑی ہوگی کہ اسے تارکول کا کُرتا پہنایا جائے گا اور اس پر پھرآگ کے شعلوں کا چوغہ پہنا دیا جائے گا۔‘‘","صحیح",{"k":"مستدرک حاکم (1؍383)۔"}],[355,"سیدنا عبیداللہ سے مروی ہے کہ سیدنا عبداللہ بن عباس رضی اللہ عنہما نے فرمایا:\n’’اے مسلمانوں کی جماعت!تم اہلِ کتاب سے کیونکر سوال کرتے ہو؟ حالانکہ تمہاری کتاب جو اللہ تعالٰی نے اپنے رسول صلی اللہ علیہ وسلم پر نازل فرمائی ہے وہ اللہ تعالٰی کی باتوں کے متعلق أحدث(یعنی جدید ترین)کتاب ہے(مراد یہ ہے کہ سب سے آخر میں نازل ہونے والی یہی کتاب ہے)تم جانتے ہوکہ اس میں گڑبڑ نہیں ہو سکتی، جبکہ اللہ تعالٰی نے تمہیں بتا رکھا ہے کہ اہلِ کتاب نے اللہ تعالٰی کی کتابوں میں تغیّروتبدّل کر دیا ہے اور انہوں نے اپنے ہاتھوں سے لکھ کر کہہ دیا کہ «هٰذَا مِنْ عِنْدِ اللّٰهِ لِيَشْتَرُوا بِهِ ثَمَنًا قَلِيلًا» ’’یہ اللہ کی بھیجی ہوئی ہے، (اور انہوں نے یہ اس لیے کیا)تاکہ وہ اس کے عوض تھوڑی سی قیمت وصول کرلیں۔‘‘ کیا تمہیں جو(اللہ کی کتاب)سے علم ملا ہے وہ تمہیں ان سے سوال کرنے سے منع نہیں کرتا؟ قسم بخدا!ہم نے تو کبھی ان کا کوئی آدمی نہیں دیکھا جو تم سے تمہارے اوپر نازل کردہ امور کے بارے میں سوال کرتا ہو۔‘‘","صحیح",{"k":"السنن الکبری للبیهقی (10؍162)۔","f":"ان سوالات سے مراد کسی مسئلہ میں ان سے شرعی راہنمائی لینا ہے۔ یہ قطعاًممنوع ہے، کیونکہ ان کی شریعت مسخ ہو چکی ہے اور اسلام کے ہوتے ہوئے کسی اوردِین کے احکام پر عمل کرنا ارتداد کے مترادف ہے۔ البتہ عام سوالات جن کا شرعی راہنمائی لینے سے تعلق نہیں ہوتا وہ پوچھنے میں کوئی حرج نہیں ہے، مثال کے طور پر اپنی تحقیق یاعلم کے لیے ان کی کتب کا مطالعہ یاان سے سوالات کرنا اس ممانعت میں داخل نہیں ہے۔"}],[356,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’نہ تم اہلِ کتاب کو سچا کہو اور نہ ہی انہیں جھوٹا کہو، بس یہ کہو کہ: «آمَنَّا بِالَّذِي أُنْزِلَ إِلَيْنَا وَأُنْزِلَ إِلَيْكُمْ، وَإِلٰهُنَا وَإِلٰهُكُمْ وَاحِدٌ وَنَحْنُ لَهُ مُسْلِمُونَ» ’’ہم اس پر ایمان لائے جو ہم پر اور تمہاری طرف نازل کی گئی، اور ہمارا اور تمہارا معبود ایک ہی ہے، اور ہم اسی کے تابعفر مان ہیں۔‘‘","صحیح",{"k":"صحیح بخاری (4485)۔","f":"تصدیق اس لیے نہیں کرنی چاہیے کیونکہ انہوں نے اپنی کتاب میں بہت سی تحریفات کردی ہیں جس کی وجہ سے صحیح وغیر صحیح خلط ملط ہوگئے ہیں اور ان کی پہچان مشکل ہے اور تکذیب اس لیے نہیں کرنی چاہیے کیونکہ باوجود تغیر وتبدل کے کسی نہ کسی بات کے درست ہونے کا بھی امکان ہے۔"}],[357,"ابنِ عباس رضی اللہ عنہما سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جس نے علمِ نجوم کا کچھ حصہ حاصل کر لیا اس نے جا دو کی ایک شاخ حاصل کردی، وہ اسے جتنا بڑھاتا جائے وہ بڑھتا جائے گا۔‘‘","حسن",{"k":"سنن أبوداؤد (3905)، سنن ابن ماجه (3726)، سلسلہ الأحادیث الصحیحہ (793)۔"}],[358,"ابنِ عباس رضی اللہ عنہما نے علمِ نجوم سیکھنے سکھانے اور اس کے ذریعے کام کرنے کروانے والوں کے بارے میں فرمایا:\n’’میرا نہیں خیال کہ جو یہ کرتا ہو اس کے لیے اللہ کے ہاں کوئی حصہ ہوگا۔‘‘","صحیح",{"k":"السنن الکبری للبیهقی (8؍139)۔"}],[359,"معاویہ بن حکم سلمی روایت کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم کے صحابہ رضی اللہ عنہم نے پوچھا:اے اللہ کے رسول!ہم میں سے بعض لوگ فال نکالتے ہیں(ان کا کیا حکم ہے؟) آپ صلی اللہ علیہ وسلم نے فرمایا:یہ ایسی چیز ہے جسے تم اپنے دِلوں میں محسوس کرتے ہو، لیکن یہ تمہیں (کسی بھی کام سے)ہرگز نہ روکے۔ انہوں نے کہا:اور ہم میں سے بعض لوگ نجومیوں کے پاس بھی جاتے ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا:تم کاہن کے پاس مت جاؤ۔‘‘","صحیح",{"k":"صحیح مسلم (537)، سنن أبوداؤد (930)۔"}],[360,"سیدہ صفیہ رضی اللہ عنہا نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’جو کسی نجومی کے پاس آیا اور اس سے کسی چیز کے بابت پوچھا، اس کی چالیس دِن تک نماز قبول نہیں ہوتی۔‘‘","صحیح",{"k":"صحیح مسلم (2230)، مسند أحمد (5؍38)۔"}],[361,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’بدشگونی کی کوئی حیثیت نہیں ہے، اور اس میں بہترین بات فال ہے۔ پوچھا گیا:اے اللہ کے رسول!فال کیا چیز ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:وہ نیک بات جو تم میں سے کوئی سنتا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (5755)، صحیح مسلم (2223)۔"}],[362,"بریدہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم کسی چیز سے بدشگونی نہیں لیا کرتے تھے، اور آپ صلی اللہ علیہ وسلم اچھے نام کو پسند فرمایا کرتے تھے۔‘‘","صحیح",{"k":"سنن أبوداؤد (3920)، سلسلہ الأحادیث الصحیحہ (762)۔","f":"بعض روایات میں یہ بھی مذکور ہے کہ آپ صلی اللہ علیہ وسلم برے نام کو ناپسند فرمایا کرتے تھے، بلکہ بعض صحابہ وصحابیات کے ایسے ہی ناموں کو بدل کر آپ صلی اللہ علیہ وسلم نے اچھے نام رکھے ہیں۔ لہٰذا گوکہ یہ بات بدشگونی نہیں ہے لیکن آپ صلی اللہ علیہ وسلم کے عمل کی پیروی کرتے ہوئے نام رکھنے میں احتیاط کرنی چاہیے، مبادا ایسا نام نہ رکھ لیا جائے جو معیوب ہو۔"}],[363,"عبداللہ بن عم رضی اللہ عنہما سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’اگر کسی چیز میں بدشگونی ہوتی تو گھوڑے، گھر اور عورت میں ہوتی۔‘‘","صحیح",{"k":"صحیح بخاری (5093)، صحیح مسلم (2225)۔","f":"یہ بات واضح رہے کہ اسلام میں بدشگونی کا تصور ہی نہیں ہے، اور اس حدیث میں یہ بیان کیا گیا ہے کہ اگر بدشگونی ہوتی بھی تو ان تین چیزوں میں ہونی تھی، لہٰذا اس بات سے بدشگونی کا وجود مراد نہیں لیا جا سکتا کیونکہ اس سے یہ ثابت نہیں ہوتا، بلکہ یہ بتلانا مقصود ہے کہ اسلام میں اس کا تصور سرے سے نہیں ہے لیکن فرض کریں کہ اگر ہوتا تو تو صرف ان تین چیزوں کے بابت ہونا تھا۔ ان تین چیزوں کوبہ طورِ خاص ذکر کرنے کی وجہ یہ ہے کہ بعض گھوڑے بہت سرکش ہوتے ہیں اور گھوڑے یعنی سواری کا اچھا نہ ہونا انتہائی تکلیف دہ امر ہوتا ہے اور بہت پریشانی کا باعث بنتا ہے، اسی طرح کئی گھر یعنی مکانات بھی اتنے خستہ حال ہوتے ہیں کہ ہربھی وقت ان سے بڑے نقصان کا خدشہ رہتا ہے، اور اسی طرح عورت اگر بدخلق ہو تو بہت سے فسادات، لڑائی جھگڑوں اور گھر میں بے سکونی وبے اطمینانی کا موجب بنتی ہے۔"}],[364,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم فرمایا کرتے تھے:\n’’عہدِجاہلیت کے لوگ کہا کرتے تھے کہ عورت، جانور(یعنی سواری)اور گھر میں براشگون ہوتاہے، پھر آپ صلی اللہ علیہ وسلم نے یہ آیت پڑھی: ﴿مَا أَصَابَ مِنْ مُصِيبَةٍ فِي الْأَرْضِ وَلَا فِي أَنْفُسِكُمْ إِلَّا فِي كِتَابٍ مِنْ قَبْلِ أَنْ نَبْرَأَهَا إِنَّ ذَلِكَ عَلَى اللّٰهِ يَسِيرٌ﴾ ’’نہ دنیا میں کوئی مصیبت آتی ہے اور نہ ہی خاص تمہاری جانوں میں، مگر اس سے پہلے کہ ہم اسے پیدا کریں، وہ ایک خاص کتاب میں لکھی ہوئی ہے، یقیناًیہ کام اللہ تعالٰی پر بہت آسان ہے۔‘‘","صحیح",{"k":"السنن الکبری للبیهقی (8؍140)، مستدرک حاکم (2؍479)، سلسلہ الأحادیث الصحیحہ (7993)۔"}],[365,"امام مالک بن انس رحمہ اللہ سے اسی بارے میں سوال کیا گیا تو انہوں نے جواب دیا:\n’’بہت سے گھر ایسے بھی ہیں کہ جن میں بسنے والے لوگ اس دنیا سے چلے گئے، پھر دوسرے لوگ اس میں آبسے اور پھر انہیں بھی موت نے آلیا۔ ہماری رائے میں تو اس کی تفسیر یہی ہے، باقی اللہ تعالٰی بہتر جانتا ہے۔‘‘","صحیح",{"k":"السنن الکبری للبیهقی (8؍140)۔"}],[366,"اور ایسے گھر کو تبدیل کرنے سے متعلق جو حدیث مروی ہے جس گھر کے عیال اور اموال کم پڑجائیں تو اس کے بارے میں رسول اللہ صلی اللہ علیہ وسلم کا فرمان ہے کہ:\n’’ایسے برے گھر کو چھوڑ دو۔‘‘","حسن",{"k":"سنن أبوداؤد (3924)۔","f":"امام خطابیؒ فرماتے ہیں کہ اس گھر کو چھوڑ دینے کاحکم ممکن ہے کہ اس وجہ سے ہوکہ اس گھر کے افراد کے دِلوں میں پیدا ہو جا نے والے وسوسے کی جڑہی کاٹ دی جائے، کیونکہ جب وہ گھر تبدیل کرلیں گے تو ان کا وہم بھی سرے سے ختم ہوجائے گا۔ واللہ أعلم"}],[367,"ابنِ عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’نہ تو کوئی بیماری متعدی ہوتی ہے اور نہ ہی بدشگونی ہوتی ہے۔‘‘","صحیح",{"k":"صحیح بخاری (5772)، صحیح مسلم (2225)۔","f":"ایک شخص سے دوسرے شخص کو یاایک جانور سے دوسرے جانور کولگ جانے والی بیماری کو متعدی بیماری کہتے ہیں، انگریزی میں اسے Infectious Deseasکہتے ہیں۔"}],[368,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ:\n’’جب رسول اللہ صلی اللہ علیہ وسلم نے فرمایاکہ کوئی بیماری متعدی نہیں ہے، صفر اوراُلُّوکی نحوست بھی کوئی چیز نہیں ہے۔ تو ایک بدوی نے کہا:اے اللہ کے رسول(اگر کوئی بیماری متعدی نہیں ہے)تو پھر اس اونٹوں کو کیا مسئلہ ہوتاہے جو ریگستان میں ہرن کی طرح صاف چمکدار ہوتے ہیں اور ایک خارش زدہ اونٹ آکرجب ان میں شامل ہو جاتا ہے تو وہ انہیں بھی خارش لگا دیتا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:تو پہلے اونٹ کوکس نے خارش لگائی تھی؟‘‘","صحیح",{"k":"صحیح بخاری (5770)، صحیح مسلم (2221)۔","f":"امام بیہقی فرماتے ہیں کہ اعتقادی طور پر وہ یہ سمجھتے تھے کہ ایک اونٹ کو بیماری لگنے کا سبب دوسرا بیمار اونٹ ہے، تو نبی صلی اللہ علیہ وسلم نے ان کے اس وہم کا ازالہ اس سوال سے فرمایاکہ پہلے اونٹ کو بیماری کس نے لگائی؟ یعنی جس نے پہلے اونٹ کو بیماری لگائی ہے وہی اس سبب کو پیدا کرنے والا ہے کہ پہلا اونٹ جب دیگر اونٹوں کے ساتھ ملے گاتو انہیں بھی خارش پڑجائے گی، تو گویا دونوں کو اللہ ہی کے حکم سے بیماری لگی ہے اورجب ایک خارش زدہ اونٹ کا دیگر اونٹوں میں گھُل مل جانا انہیں بھی خارش زدہ کرنے کا سبب بن جاتا ہے تو یہ سبب بھی اللہ تعالیٰ کی مشیئت، چاہت، اس کے فیصلے اور حکم سے ہی بنتا ہے، اسی لیے بہ طورِاحتیاط نبی کریم صلی اللہ علیہ وسلم نے یہ ارشاد فرمایا ہے کہ اپنے صحت مند اونٹ کو بیمار اونٹوں میں شامل نہ کرو۔"}],[369,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’کوئی شخص اپنے بیمار اونٹوں کو کسی کے تندرست اونٹوں میں شامل نہ کرے۔ ایک اور روایت میں ہے کہ نبی صلی اللہ علیہ وسلم سے پوچھا گیا:اے اللہ کے رسول!ایسا کیوں ہے؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:اس لیے کہ یہ باعثِ کوفت ہے۔‘‘","صحیح",{"k":"صحیح بخاری (5771)، صحیح مسلم (2221)۔","f":"امام بیہقیؒ کی ذکر کردہ کلام کا خلاصہ یہ ہے کہ نبی کریم صلی اللہ علیہ وسلم کا اس سے منع کرنا فقط اس لیے ہے تاکہ قلب وذہن میں یہ بداعتقادی کا خیال جنم نہ لے سکے کہ دوسرے اونٹوں کو بھی اس بیمار اونٹ کی وجہ سے بیماری لگی ہے، حالانکہ ایسا ہرگز نہیں ہے کیونکہ جس ذات نے پہلے اونٹ کو بیماری لگائی تھی اس نے اسی اونٹ کے دیگر اونٹوں میں شامل ہوجانے کو ان اونٹوں کے بیمار ہو جا نے کا سبب بنا دیا، تو گویا دونوں جگہ بیماری اللہ تعالیٰ ہی کے حکم اور فیصلے سے لگی ہے، اس ایک بیمار اونٹ کا اس میں قطعی کوئی عمل دخل نہیں ہے۔"}],[370,"سعدبن مالک، خزیمہ بن ثابت اور اسامہ بن زید رضی اللہ عنہم بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’طاعون اس عذاب کا باقی ماندہ حصہ اور گندگی ہوتی ہے جس عذاب سے کسی قوم کو دو چار کیا جاتا ہے، سوجب یہ (وباء)کسی ایسے علاقے میں پھُوٹ پڑے جہاں تم موجود ہو تو وہاں سے نکلومت، لیکن اگر یہ ایسے علاقے میں پھوٹے جہاں تم موجود نہ ہو تو اس علاقے میں مت جاؤ۔‘‘","صحیح",{"k":"صحیح بخاری (5728)، صحیح مسلم (2218)۔"}],[371,"عبداللہ بن عباس رضی اللہ عنہما بیان کرتے ہیں کہ:\n’’وہ عمربن خطاب رضی اللہ عنہ کے ساتھ تھے جب آپؓ شام کی طرف روانہ ہوئے، اورجب آپؓ لوگوں کو سرغ مقام سے لے کر واپس ہوئے تو آپؓ فوجی دستوں کے امراء سے ملے، ابوعبیدہ بن جراح رضی اللہ عنہ نے اپنے ساتھیوں سمیت آپ سے ملاقات کی(اور بتلایا کہ)شام میں طاعون کی وبا پھوٹ پڑی ہے۔ تو عمر رضی اللہ عنہ نے فرمایا:پہلے مہاجرین کو میرے پاس جمع کرو۔ میں نے انہیں آپ کے پاس اکٹھا کیا اور آپ نے ان سے مشاورت کی تو انہوں نے مختلف آراء دِیں۔ بعض نے کہاکہ لوگوں کو واپس بھیج دیجیے اور انہیں وبا میں نہ دھکیلیں، جبکہ کچھ نے کہاکہ یہ تو اللہ تعالٰی کی (لکھی ہوئی)تقدیر ہے، آپ جس کام کے لیے نکلے ہیں اسے چھوڑ کر واپس مت جائیے۔ حضرت عمرؓنے انہیں جانے کاحکم فرمایا، چنانچہ وہ آپ کے پاس سے اُٹھ کر چلے گئے۔ پھر آپؓ نے فرمایاکہ انصار کو میرے پاس بلا کر لاؤ، میں انہیں بلا لایا تو آپ نے ان سے بھی مشاورت کی، وہ بھی مہاجرین کی راہ پر ہی چلے اور انہی کی طرح اختلاف کیا۔ آپ نے انہیں بھی چلے جانے کاحکم فرمایا، وہ بھی چلے گئے۔ پھر آپ نے فرمایا:فتح مکہ کے وقت اسلام قبول کر کے آنے والے جو بزرگ یہاں موجود ہیں انہیں بلاؤ، میں انہیں بلا لایا، آپ نے ان سے بھی اس بارے میں مشورہ لیا تو وہ سب ایک ہی رائے پر متفق تھے کہ واپس چلے جانا چاہیے۔ چنانچہ عمر رضی اللہ عنہ نے لوگوں میں یہ اعلان کرا دیا کہ میں سوار ہو(کر واپس جا)نے والا ہوں سوتم بھی واپسی کا بندوبست کرو، کیونکہ میں اپنی رائے کے مطابق فیصلہ نافذ کروں گا، سوتم اس پر نظر رکھوجس کا میں تمہیں حکم دینے والا ہوں، سوا نہوں نے اسی پر عمل کیا اور عمر رضی اللہ عنہ سواری پر سوار ہو گئے۔ راوی کہتے ہیں کہ عمر رضی اللہ عنہ سوار ہوئے، پھر لوگوں سے فرمایا:میں واپس جا رہا ہوں۔ تو ابوعبیدہ بن جراحؓ، جو آپ کی مخالفت کرنا ناپسند کیا کرتے تھے، بولے:کیا اللہ تعالٰی کی تقدیر سے فرار ہو رہے ہیں؟ عمر رضی اللہ عنہ (یہ سن کر)غصے میں آگئے اور فرمایا:اے ابوعبیدہ! کاش یہ بات تمہارے علاوہ کسی اور نے کہی ہوتی، ہاں!میں اللہ کی ایک تقدیر سے فرار ہو کر دوسری تقدیر کی طرف جا رہا ہوں، تمہاری کیا رائے ہے کہ اگر ایک آدمی کسی ایسی وادی میں جائے جس کے دو کنارے ہوں، ایک خشک اور دوسرا سرسبز ہو، کیا ایسا نہیں ہے کہ اگر وہ اپنے جانوروں کو خشک کنارے پر چرائے گاتو وہ بھی اللہ کی (لکھی ہوئی)تقدیر سے ہوگا اور اگر سرسبز کنارے پر چرائے گاتو وہ بھی اللہ کی تقدیر ہی سے ہوگا؟ پھر عمرؓابوعبیدہ کو لے کر تنہائی میں گئے اور کچھ ہی دیر میں دونوں واپس آگئے، اور(اتنے میں)عبدالرحمان بن عوفؓ بھی تشریف لے آئے جو کسی ضروری کام کی وجہ سے وہاں حاضر نہیں تھے، وہ آئے اور اختلاف کررہے تھے تو انہوں نے کہا:یقیناًمیرے پاس ایک علم ہے؟ عمرؓ نے پوچھا:وہ کیا؟ انہوں نے جواب دیا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:جب تم کسی علاقے میں وبا پھوٹنے کا سنو تو وہاں مت جاؤ، اور اگر وبا وہاں پھوٹ پڑے جہاں تم موجود ہو تو پھر تم اس سے فرار اختیار کرتے ہوئے وہاں سے مت نکلو۔ سوعمر رضی اللہ عنہ نے (یہ سن)کر اللہ تعالٰی کا شکر ادا کیا اور لوگوں کو حکم فرمایاکہ وہ واپس چلے جائیں۔‘‘","صحیح",{"k":"صحیح بخاری (5729)، صحیح مسلم (2219)۔"}],[372,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’اللہ تعالٰی فرماتا ہے:ابنِ آدم زمانے کوبُرابھلا کہتا ہے، حالانکہ میں ہی زمانہ ہوں، میرے ہاتھ میں ہی شب وروز ہیں۔اور ایک روایت میں ہے کہ وہ زمانے کو گالی دیتا ہے، جبکہ زمانہ میں ہی ہوں، (گردشِ زمانہ کا)سارا معاملہ میرے ہاتھ میں ہی ہے، میں ہی شب وروز کو بدلتا ہوں۔‘‘","صحیح",{"k":"صحیح بخاری (6181)، صحیح مسلم (2246)۔","f":"یعنی کوئی بھی مصیبت آن پڑنے پر زمانے کوبُرابحلا کہنا اور یہ عقیدہ رکھنا کہ جو اس پر مصیبت ٹُوٹی ہے یہ زمانے کا ہی کیا دھرا ہے، مذموم عمل ہے، کیونکہ اللہ تعالٰی ہی بندے پر اچھے اوربُرے حالات لاتا ہے اور وہی تنگی وخوشحالی کے دِن دکھاتا ہے، کیونکہ گردشِ زمانہ کا سارا معاملہ اسی کے کنٹرول میں ہے اور وہ جیسے چاہتا ہے شب وروز کو بدلتا رہتا ہے۔ اسی لیے فرمایاکہ جب بندہ زمانے کوبُرابھلا کہتا ہے تو درحقیقت اللہ تعالٰی ہی کوبُرابھلا کہہ رہا ہوتا ہے، کیونکہ زمانہ تو حکمِ الٰہی کا پابند ہے۔ ہمارے معاشرے میں بھی اکثر یہ بات زبان زدِعام ہے کہ جب بھی کسی برائی، غلط چیزیا حالات کی تنگی کا مشاہدہ کرنا پڑتا ہے تو یہی کہا جاتا ہے کہ’’زمانہ ہی ایسا آگیا ہے‘‘ حالانکہ ایسا کہنے والا اسی حدیث کا مصداق بنتا ہے، اس لیے حالات خواہ کیسے بھی آجائیں اسے کبھی زمانے کو قصوروار نہیں ٹھہرانا چاہیے۔"}],[373,"ابوہریرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’مومن ایک ہی سوراخ سے دو بار نہیں ڈسا جاتا۔‘‘","صحیح",{"k":"صحیح بخاری (6133)، صحیح مسلم (2998)۔","f":"یعنی مومن ایک جگہ سے دھوکہ کھانے کے بعد دوبارہ اسی جگہ سے فریب نہیں کھاتا بلکہ محتاط وہو شیا رہو جاتا ہے اور آئندہ اس غلطی کے اعا دے سے خود کو بچائے رکھتا ہے۔"}],[374,"عبداللہ بن عمر رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جس وقت تم سونے لگو تو اپنے گھروں میں آگ جلتی ہوئی نہ چھوڑا کرو۔‘‘","صحیح",{"k":"صحیح بخاری (6293)، صحیح مسلم (2015)۔"}],[375,"ابنِ عباس رضی اللہ عنہما بیان کرتے ہیں کہ:\n’’ایک چوہیا آئی اور چراغ کی بتّی پکڑ کر اسے گھسیٹنے لگی، ایک بچی اسے بھگا نے لگ گئی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:اسے چھوڑ دو، پھر اس(چوہیا)نے وہ بتّی لاکر اس چٹائی پر پھینک دی جس پر آپ صلی اللہ علیہ وسلم بیٹھے ہوئے تھے، اس بتّی نے ایک درہم کی جگہ کے بہ قدر چٹائی جلا دی، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:جب تم سونے لگو تو اپنے چراغوں کو بجھا دیا کرو، کیونکہ شیطان اس جیسے جانوروں کی ایسے کاموں میں راہنمائی کرتاہے اور تمہارے گھروں کو جلا دیتا ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (5247)۔","f":"گویا ایسے جانوروں کو اس طرح کے نقصان دہ اور ضرر رساں امور شیطان سُجھا تاہے اور ان کی راہنمائی کرتاہے، تاکہ وہ مسلمانوں کے گھر کو نقصان پہنچا سکے، اس لیے نبی صلی اللہ علیہ وسلم نے یہ تنبیہ فرمائی کہ سونے سے پہلے گھر کے چراغ بجھا دیا کرو۔ تو ہروہ چیز جوآگ سے متعلقہ ہوا سے بند کر کے یابجھا کر سونا چاہیے مثلاًچولہا، ہِیٹر، انگیٹھی، لالٹین، موم بتی، گیزر اور گیس کا لیمپ وغیرہ۔"}],[376,"جابربن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب رات چھا جائے یاشام ہوجائے تو تم اپنے بچوں کو(گھروں میں)روک لیا کرو، کیونکہ اس وقت شیاطین پھیل جاتے ہیں، لیکن جب رات کا کچھ وقت گزر جائے تو انہیں چھوڑ دیا کرو، اللہ کا نام لے کر دروازے بند کر دیا کرو کیونکہ شیطان بند دروازہ نہیں کھولتا، بسم اللہ پڑھ کر مشکیزوں کا منہ باندھ دیا کرو، اللہ کے نام سے اپنے برتن بھی ڈھانپ دیا کرو خواہ ان پر کوئی چوڑائی میں ہی کوئی چیز رکھ دیا کرو اور اپنے چراغوں کو بجھا دیا کرو۔‘‘","صحیح",{"k":"صحیح بخاری (5613)، صحیح مسلم (2012)۔"}],[377,"جابر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب سورج غروب ہوجائے توتب تک تم اپنے چوپایوں اور اپنے بچوں کومت چھوڑ وجب تک کہ رات کا اندھیرا اچھی طرح نہ چھا جائے، کیونکہ غروبِ آفتاب کے وقت شیطان بھیجا جاتا ہے اور وہ تب تک رہتا ہے جب تک کہ اچھی طرح رات نہیں چھا جاتی۔‘‘","صحیح",{"k":"صحیح مسلم (2013)، سنن أبوداؤد (2604)۔"}],[378,"جابربن عبداللہ انصاری رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’برتنوں کو ڈھانپ دو اور مشکیزوں کا منہ باندھ دو، کیونکہ سال میں ایک رات ایسی ہوتی ہے جس میں ایک وباء اترتی ہے، جو کسی بھی ایسے برتن کے پاس سے گزر جائے جس کو ڈھانپا نہ گیا ہو اور کسی بھی مشکیزے کے پاس سے گزر جائے جس کا منہ نہ باندھا گیا ہو تو وہ وباء اس میں پڑجاتی ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2014)۔"}],[379,"سالم اپنے باپ(عبداللہ بن عمرؓ) سے روایت کرتے ہیں کہ انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’سانپوں کو مار دیا کرو، (خاص طور پر)انہیں جن کے سرپر دو نقطے ہوتے ہیں اور چھوٹی دُم والے موذی سانپ کو بھی، کیونکہ یہ دونوں سانپ بینائی چھین لیتے ہیں اور حمل گرا دیتے ہیں۔ ابنِ عمر رضی اللہ عنہما ہرسانپ کو مار دیا کرتے تھے، ایک مرتبہ وہ کسی سانپ پر حملہ آور ہو رہے تھے کہ ابولبابہ یازیدبن خطاب نے آپ کو دیکھ لیا اور بتلایا کہ گھر میں رہنے والے سانپوں کو مار نے سے منع کر دیا گیا تھا۔‘‘","صحیح",{"k":"صحیح بخاری (3297)، صحیح مسلم (2233)۔","f":"آنکھوں کی بینائی زائل کر دینایا عورت کا حمل گرا دینا ان کے شدید زہریلے ہونے کی وجہ سے ہے، یعنی سانپ کی ان دو قسموں میں اس قدر زہر ہے کہ یہ بغیر ڈسے بھی انسانی جان پر اثر انداز ہو جاتا ہے اور گھروں میں رہنے والے سانپوں کو مار نے سے منع کرنے کی وجہ ایک اور حدیث میں بیان ہوئی ہے کہ ایسے سانپ اکثرجِن ہوتے ہیں جو سانپوں کے رُوپ میں گھروں میں رہتے ہیں، اس لیے انہیں نہیں مارنا چاہیے۔"}],[380,"ابو سائب روایت کرتے ہیں کہ:\n’’میں ابو سعید خدری رضی اللہ عنہ کی عیادت کرنے ان کے پاس گیا تو میں نے دیکھا کہ وہ نماز پڑھ رہے ہیں، کہتے ہیں کہ میں بیٹھ گیا تو مجھے گھر کے کونے میں پڑی لکڑیوں سے کچھ حرکت سنائی دی، میں نے دیکھا تو وہ سانپ تھا، میں اسے مارنے کے لیے اُٹھا تو تو ابو سعیدؓنے مجھے اشارہ کر دیا کہ نہ مارو۔ جب وہ نماز سے فارغ ہوئے تو انہوں نے (ایک کوٹھڑی کی طرف اشارہ کرتے ہوئے)کہا:تُویہ گھر دیکھ رہا ہے؟ اس میں ہمارا چچازاد رہتا تھا، اس کی نئی نئی شادی ہوئی تھی، وہ خندق کے دِنوں میں نصف النہار کے وقت رسول اللہ صلی اللہ علیہ وسلم سے اجازت لے کر گھر آیا کرتا تھا اور رسول اللہ صلی اللہ علیہ وسلم اسے اجازت دے دیتے تھے، ایک روز اس نے اجازت لی تو آپ صلی اللہ علیہ وسلم نے اجازت دے دی اور فرمایا:اپنا ہتھیار لے جا کیونکہ مجھے تیرے بارے میں بنوقریظہ سے خطرہ ہے(بنوقریظہ دغابازی کرکے دشمن کے ساتھ جا ملے تھے)، چنانچہ وہ آیا تو اس کی بیوی دروازے میں کھڑی تھی، اس نے اپنی بیوی کو)اس وجہ سے(مارنے کے لیے نیزہ اُٹھایا)کہ وہ باہر دراز ازے میں کیوں کھڑی ہے(تو اس نے کہا:اپنا نیزہ سنبھال اور اندر جا کر دیکھ (کہ میں باہر کیوں کھڑی ہوں؟)وہ اندر گیا تو اس نے دیکھا کہ بستر پر سانپ بیٹھا ہوا ہے، اس نے اسے نیزے میں ہی پرو لیا، پھر وہ باہر نکلا اور نیزہ کوٹھڑی میں گاڑ دیا اور سانپ نیزے کے پھل پر تڑپ رہاتھا، اتنے میں وہ نوجوان بھی تڑپنے لگا، پھر پتہ نہیں پہلے کس کی موت آئی، نوجوان کی یاسانپ کی)یعنی دونوں ہی مرگئے(۔ ابوسعید رضی اللہ عنہ کہنے لگے کہ پھر ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور آپ صلی اللہ علیہ وسلم کو یہ واقعہ بتلایا اور ہم نے عرض کیا:اللہ تعالیٰ سے دعا فرمائیے کہ وہ ہمارے ساتھی کو زندہ کردے، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:اپنے ساتھی کے لیے مغفرت کی دعا کرو، مدینہ میں کچھ جِن رہتے ہیں جو مسلمان ہوگئے ہیں، سواگر ان میں سے (سانپ وغیرہ کی شکل میں)کوئی چیز تمہیں نظر آئے تو تین دِن تک اسے خبر دار کرو)یعنی اسے وہاں سے جانے کے لیے کہتے رہو(، لیکن اگر تین دِن کے بعد بھی وہ تمہیں نظر آئے تو اسے مار دو، کیونکہ وہ شیطان ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2236)، سنن أبوداؤد (5257)۔"}],[381,"ابو سعید رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’یقیناًان گھروں میں کچھ عمر رسیدہ سانپ ہوتے ہیں، سوجب تم ان میں سے کوئی دیکھو تو تین دِن تک اسے تنگ کرو، لیکن اگر اس کے بعد بھی وہ تمہیں نظر آئے تو بلاشبہ وہ کافر ہے، اسے قتل کردو۔‘‘","صحیح",{"k":"صحیح مسلم (2236)، سنن أبوداؤد (5258)۔","f":"تنگ کرنے سے مراد یہ ہے کہ اسے اس طرح کی آوازیں دی جائیں کہ تم یہاں سے چلے جاؤ ورنہ ہم تمہیں مار دیں گے وغیرہ وغیرہ۔"}],[382,"سعدبن ابی وقاص رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم نے چھپکلی کو مار نے کاحکم فرمایا اور اسے ’’فویسقہ‘‘کا نام دیا۔‘‘","صحیح",{"k":"صحیح مسلم (2238)، سنن أبوداؤد (5262)۔","f":"فویسقہ کا مطلب ہے نقصان پہنچانے والا چھوٹا جانور۔ اس کو مار نے کی ایک وجہ تو یہ ہے کہ یہ بہت زہریلی ہوتی ہے اور دوسری وجہ یہ ہے کہ جب حضرت ابراہیم علیہ السلام کوآگ میں پھینکا گیا تو اس نے پھونکیں مار کرآگ بھڑ کا نے میں حصہ ڈالا تھا۔ (صحيح بخارى، كتاب أحاديث الأنبياء، باب قول الله تعالى: واتخذ الله إبراهيم خليلا، ح:۳۳۵۹-صحيح مسلم، كتاب السلام، باب استحباب قتل الوزغ، ح:۲۲۳۷) اور بعض روایت میں نبی صلی اللہ علیہ وسلم کا یہ فرمان مذکور ہے کہ جو شخص چھپکلی کو پہلی ہی چوٹ میں مار دے اسے سونیکیاں ملیں گی۔ (صحيح مسلم، كتاب السلام، باب استحباب قتل الوزغ، ح:۴۰۲۲)"}],[383,"ابنِ عباس رضی اللہ عنہما بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے چیونٹی، شہد کی مکھی، ہُدہُداور لٹورا کو مار نے سے منع فرمایا۔‘‘","صحیح",{"k":"سنن أبوداؤد (5267)، سنن ابن ماجه (3224)، إرواء الغلیل للألبانی (2490)۔","f":"لٹورا ایک پرندہ ہے جو چڑیوں کا شکار کرتا ہے اور کیڑے مکوڑے کھاتا ہے۔"}],[384,"عبدالرحمان بن عثمان بیان کرتے ہیں کہ:\n’’ایک طبیب نے نبی صلی اللہ علیہ وسلم سے مینڈک کے بارے میں پوچھا کہ وہ اسے(مار کر)دوا میں ڈال سکتا ہے؟ تو آپ صلی اللہ علیہ وسلم نے اسے مینڈک کو مار نے سے منع فرمادیا۔‘‘","صحیح",{"k":"سنن أبوداؤد (5269)۔"}],[385,"ابوہریرہ رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’ایک نبی کو کسی چیونٹی نے کاٹ لیا، تو انہوں نے چیونٹی کی بستی کو ہی جلانے کاحکم دے دیا، چنانچہ وہ جلا دی گئی، تو اللہ تعالیٰ نے ان کی طرف وحی کی کہ اگر ایک چیونٹی نے تمہیں کاٹ لیا ہے تو تم نے اللہ تعالیٰ کی تسبیح کرنے والی اُمتوں میں سے ایک اُمت کو ہی جلا ڈالا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (3019)، صحیح مسلم (2241)۔","f":"اس حدیث سے چیونٹی کو مار نے کی ممانعت کے علاوہ یہ بات بھی احاطۂ علم میں آتی ہے کہ صرف انسان وجِن اور فرشتے ہی نہیں بلکہ جانور، پرندے اور کیڑے مکوڑے بھی اللہ تعالیٰ کی تسبیح کرتے ہیں۔"}],[386,"ابنِ عمر رضی اللہ عنہما سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’ایک عورت کوبِلّی کی وجہ سے عذاب دیا گیا، کیونکہ اس عورت نے اسے باندھے رکھا، یہاں تک کہ وہ بھوک سے مرگئی، اور وہ عورت (اسی کی وجہ سے) جہنّم میں چلی گئی۔ فرمایاکہ جب اس عورت نے اسے باندھا تو اسے نہ تو کچھ کھانے کے لیے دیا اور نہ پینے کے لیے، اور نہ ہی اسے چھوڑا کہ وہ زمین کے کیڑے مکوڑے ہی کھا لیتی۔‘‘","صحیح",{"k":"صحیح بخاری (3318)، صحیح مسلم (2242)۔"}],[387,"عبداللہ بن بریدہ سے مروی ہے کہ:\n’’عبداللہ بن مغفل رضی اللہ عنہ نے ایک آدمی کو درمیان والی دو انگلیوں سے کنکری پھینکتے دیکھا تو کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے انگلیوں سے کنکری پھینکنے سے منع فرمایا ہے اور آپ صلی اللہ علیہ وسلم نے فرمایا:یہ نہ تو کوئی شکار مار سکتی ہے اور نہ ہی دشمن کو کوئی نقصان پہنچا سکتی ہے، البتہ کسی کا دانت توڑ دے گی یاکسی کی آنکھ پھوڑ دے گی۔ راوی کہتے ہیں کہ عبداللہ بن مغفلؓ نے اس کے بعد پھر اسے انگلیوں سے کنکری پھینکتے دیکھا تو فرمایا:میں نے تجھے رسول اللہ صلی اللہ علیہ وسلم کی حدیث بیان کی ہے اورتُوپھر بھی کنکری پھینک رہا ہے، اللہ کی قسم!میں آج کے بعد تم سے بات ہی نہیں کروں گا، اور اس کے علاوہ بھی کافی کچھ کہا۔‘‘","صحیح",{"k":"صحیح بخاری (6220)، صحیح مسلم (1954)۔"}],[388,"ابوموسیٰ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’جس نے ہم پر ہتھیاراُٹھا یاوہ ہم میں سے نہیں۔‘‘","صحیح",{"k":"صحیح بخاری (7071)، صحیح مسلم (101)۔","f":"ہتھیار اٹھا نے سے مراد ہے کہ کسی ہتھیار سے اپنے کسی مسلمان بھائی کی جان لے لینا یااس پر تاننا؛خواہ اس کی جان نہ بھی لی جائے۔ کیونکہ ایک روایت میں اپنے مسلمان بھائی کی طرف ہتھیار کارُخ کرنے کی بھی ممانعت وارد ہوئی ہے اور اس کی وجہ آپ صلی اللہ علیہ وسلم نے یہ بتلائی ہے کہ شیطان کسی بھی لمحے اس کے ہاتھ سے وہ ہتھیار چلا سکتا ہے۔ (صحيح بخاری، کتاب الفتن، باب قول النبیؐ:من حمل علينا السلاح فليس منا، ح:۷۰۷۲-صحيح مسلم، کتاب البر والصلة، باب النهي عن الا شارة بالسلاح الیٰ مسلم، ح:۲۶۱۷)"}],[389,"اور اسی اسناد سے ہی مروی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’تم میں سے جو کوئی شخص ہماری مسجد یابازار میں سے تِیرلے کر گزرے تو وہ اس کاپھَل تھامے رکھے، تاکہ وہ کسی مسلمان کو نقصان نہ پہنچا سکے۔‘‘","صحیح",{"k":"صحیح بخاری (452)، صحیح مسلم (2615)۔"}],[390,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب تم میں سے کوئی اپنے بھائی کی طرف کسی لوہے سے اشارہ کرتاہے تو فرشتے اس پر لعنت کرتے ہیں، اگرچہ وہ اس کا سگا بھائی ہی ہو۔‘‘","صحیح",{"k":"السنن الکبری للبیهقی (8؍23)، مسند أحمد (2؍256)، صحیح ابن حبان (1856)۔"}],[391,"ابوذر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’میری اُمت کے نیک اور برے اعمال مجھے دکھائے گئے، تو میں نے ان کے نیک اعمال میں یہ عمل بھی دیکھا کہ جو راستے سے تکلیف دہ چیز ہٹا دی جاتی ہے، اوربُرے اعمال میں میں نے یہ عمل بھی پایا کہ جو مسجد میں ناک کی ریزش پھینکی ہو اور پھر اسے دفن نہ کیا ہو۔‘‘","صحیح",{"k":"صحیح مسلم (553)، مسند أحمد (5؍180)۔","f":"اوّلاًتو مسجد کے آداب میں سے یہی ہے کہ وہاں تھُوک، بلغم، رِینٹ اور ناک کی ریزش وغیرہ پھینکی ہی نہ جائے، کیونکہ مسجد اللہ تعالیٰ کا گھر ہے اور وہ ہمارے گھروں سے زیادہ اس بات کاحق رکھتا ہے کہ اسے پاک وصاف رکھا جائے۔ لیکن اگر ایسی کوتاہی ہو بھی جاتی ہے تو پھر ایسا کرنے والے پر لازم ہے کہ اس پر کوئی مٹی وغیرہ ڈال کر یاتو دفن کردے یاپانی گرا کر اسے دھو ڈالے، اور اگر وہ یہ بھی نہیں کرتا تو یہ برائی شمار ہوگی اور مذکورہ حدیث کے مطابق نامۂ اعمال میں اس کا گناہ لکھا جائے گا۔"}],[392,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے قبلہ کی جانب ریزش پھینکی ہوئی دیکھی تو ایک کنکری لے کر اسے صاف کردیا، پھر فرمایا:\n’’تم میں سے کوئی بھی قبلے کی جانب نہ تھوکے اور نہ ہی اپنی دائیں جانب تھوکے، بلکہ اسے اپنے بائیں جانب یاا پنے بائیں پاؤں کے نیچے تھُوکنا چاہیے۔ ایک روایت میں ان الفاظ کا اضافہ ہے کہ اگر ایسا بھی ممکن نہ ہو تو اسے اپنے کپڑے میں تھوک کر اسے رگڑ لینا چاہیے۔‘‘","صحیح",{"k":"صحیح بخاری (408)، صحیح مسلم (550)۔","f":"اپنی بائیں جانب یاپاؤں کے نیچے تھوکنے کی ناممکنہ صورت یہی ہو سکتی ہے کہ آدمی مسجد وغیرہ میں ہو، تو ایسی صورت کے لیے یہ حکم فرما دیا کہ اسے اپنے رومال یاکسی بھی کپڑے میں وہ تھوک کر لینی چاہیے اور پھر اسے رگڑ لے، یوں اس کی حاجت بھی رفع ہوجائے گی اور مسجد کا احترام بھی باقی رہے گا۔"}],[393,"ابو موسٰی رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’میرا ایک بچہ پیدا ہوا تو میں اسے نبی صلی اللہ علیہ وسلم کے پاس لے کر آیا، آپ صلی اللہ علیہ وسلم نے اس کا نام ابراہیم رکھا اور کھجور کے ساتھ اسے گھُٹّی دی۔‘‘","صحیح",{"k":"صحیح بخاری (6198)، صحیح مسلم (2145)۔"}],[394,"ابنِ عمر رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’یقیناًاللہ تعالیٰ کے ہاں تمہارے سب ناموں سے زیادہ پسندیدہ نام عبداللہ اور عبدالرحمان ہیں۔‘‘","صحیح",{"k":"صحیح مسلم (2132)، سنن ترمذی (2834)۔"}],[395,"سمرہ بن جندب رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’اللہ تعالٰی کی نظر میں سب سے زیادہ پسندیدہ کلام «لَا إِلٰهَ إِلَّا» اللّٰهُہے، اَللّٰهُ أَكْبَرُہے، «سُبْحَانَ اللّٰهِ اوراَلْحَمْدُ» لِلَّهِہے، تو ان میں سے جسے چاہے پہلے پڑھ لے کوئی مسئلہ نہیں ہے، اور اپنے غلام کا نام یسار، رباح، نجیح اور افلح مت رکھ، کیونکہ تُو(اس کا نام لے کر)کہے گا:کیا وہ ہے؟ وہ نہیں ہوگا تو جواب ملے گاکہ نہیں۔‘‘","صحیح",{"k":"صحیح مسلم (2137)، سنن ترمذی (2836)۔","f":"اس حدیث میں چار ناموں کا ذکر کیا گیا ہے، یسار کا معنیٰ ہے خوشحالی، رباح کا مطلب ہے فائدہ ومنافع، نجیح کا معنیٰ ہے صابر وثابت قدم اور افلح کا مطلب ہے بہت کامیاب شخص۔ آخر میں نبی صلی اللہ علیہ وسلم نے ان ناموں کی ممانعت کی وجہ بھی بیان فرما دی، مثال کے طور پر اگر کسی کا نام یسار ہو، جس کا مطلب ہے خوشحالی، اور کوئی اس کا پوچھے کہ کیا یسار ہے؟ تو اگر وہ نہ ہو تو اسے یہی جواب دیا جائے گاکہ یسار نہیں ہے، تو اس کا ایک مطلب یہ بھی نکلتا ہے کہ خوشحالی نہیں ہے، اس لیے ایسے نام رکھنا ممنوع قرار دیا گیا ہے۔"}],[396,"جابر رضی اللہ عنہ روایت کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم نے اس بات سے منع کرنا چاہا کہ (بچوں کے)یعلٰی، برکت، افلح، یسار، نافع اور اس جیسے نام رکھے جائیں، پھر میں نے دیکھا کہ آپ صلی اللہ علیہ وسلم نے ان سے خاموشی اختیار لی(یعنی منع نہیں فرمایا)پھر آپ صلی اللہ علیہ وسلم وفات پاگئے اور(تادمِ وفات)آپ صلی اللہ علیہ وسلم نے اس سے منع نہیں کیا۔‘‘","صحیح",{"k":"صحیح مسلم (2138)۔"}],[397,"ابوہریرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’روزِقیامت اللہ تعالٰی کے ہاں سب سے بدترین نام اس شخص کا ہوگا جسے شاہانِ شاہ کے نام سے پکارا جاتا ہوگا، اس لیے کہ اللہ کے سوا کوئی شہنشاہ نہیں ہے۔‘‘","صحیح",{"k":"صحیح بخاری (6206)، صحیح مسلم (2143)۔"}],[398,"ابنِ عمر رضی اللہ عنہما سے مروی ہے کہ:\n’’نبی صلی اللہ علیہ وسلم نے(ایک عورت کا)عاصیہ نام تبدیل کر دیا اور فرمایا کہ تُوجمیلہ ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2139)، سنن أبوداؤد (4952)، سنن ترمذی (2838)، سنن ابن ماجه (3733)۔","f":"عاصیہ کا مطلب نافرمان عورت ہے، اس لیے نبی صلی اللہ علیہ وسلم نے اسے بُراقرار دیا اور بدل کر اس عورت کا نام جمیلہ رکھ دیا۔"}],[399,"ابنِ مسیّب اپنے باپ کے حوالے سے اپنے دادا سے روایت کرتے ہیں کہ انہوں نے کہا:\n’’رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا:تمہارا نام کیا ہے؟ میں نے کہا:حَزن(یعنی تنگی)، آپ صلی اللہ علیہ وسلم نے فرمایا: (نہیں)بلکہ تم سہل(یعنی آسانی)ہو۔ انہوں نے جواب میں کہاکہ میں وہ نام نہیں بدلوں گاجو میرے باپ نے میرا رکھا ہے۔ ابنِ مسیّب کہتے ہیں کہ پھر اس کے بعد ہمیں تنگی ہی درپیش رہی۔‘‘","صحیح",{"k":"صحیح بخاری (6190)، سنن أبوداؤد (4956)۔"}],[400,"زینب بنت اُمِ سلمہ بیان کرتی ہیں کہ:\n’’میرا نام برّہ تھا، تو رسول اللہ صلی اللہ علیہ وسلم نے میرا نام زینب رکھ دیا، زینب بنت جحشؓ آئیں اور ان کا نام بھی برّہ تھا تو آپ صلی اللہ علیہ وسلم نے ان کا نام بھی زینب رکھ دیا۔‘‘","صحیح",{"k":"صحیح مسلم (2142)، سنن أبوداؤد (4953)۔"}],[401,"عبدالرحمان رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’میں اپنے باپ کے ساتھ نبی صلی اللہ علیہ وسلم کے پاس آیا، تو آپ صلی اللہ علیہ وسلم نے (میرے باپ سے)دریافت فرمایا:تمہارے اس بیٹے کا نام کیا ہے؟ انہوں نے جواب دیا:عزیز، آپ صلی اللہ علیہ وسلم نے فرمایا:اس کا نام عزیزمت رکھو، بلکہ اس کا نام عبدالرحمان رکھ دو، کیونکہ اللہ تعالیٰ کو جو نام سب سے زیادہ پسند ہیں وہ عبدالرحمان اور عبداللہ ہیں۔‘‘","صحیح",{"k":"مسند أحمد (4؍178)، مسند البزار (1993)، سلسلہ الأحادیث الصحیحہ (904)۔"}],[402,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’تم میرا نام رکھ لیا کرو، مگر میری کنیت مت رکھا کرو۔‘‘","صحیح",{"k":"صحیح بخاری (3539)، صحیح مسلم (2134)۔"}],[403,"انس رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’ایک آدمی نے بقیع الغرقد(جنت البقیع)سے آواز لگائی:اے ابوالقاسم!، رسول اللہ صلی اللہ علیہ وسلم نے مُڑکر اس کی طرف دیکھا تو اس نے کہا:اے اللہ کے رسول!میری مراد آپ نہیں ہیں، بلکہ میں نے فلاں کو آواز دی ہے۔ تو آپ صلی اللہ علیہ وسلم نے فرمایا:تم میرا نام رکھ لیا کرو اور میری کنیت مت رکھا کرو۔ امام شافعی رحمہ اللہ فرمایا کرتے تھے کہ کسی کے لیے بھی یہ جائز نہیں ہے کہ وہ اپنی کنیت ’ابوالقاسم‘ رکھے، خواہ اس کا نام ’محمد‘ہویا کچھ اور ہو۔‘‘","صحیح",{"k":"صحیح بخاری (3537)، صحیح مسلم (2131)۔"}],[404,"سیدنا علی رضی اللہ عنہ سے مروی ہے کہ:\n’’انہوں نے (یعنی علیؓ نے) عرض کیا:اے اللہ کے رسول!آپ صلی اللہ علیہ وسلم کی وفات کے بعد اگر میرا بیٹا پیدا ہو تو کیا میں آپ صلی اللہ علیہ وسلم کے نام پر اس کا نام اور آپ صلی اللہ علیہ وسلم کی کنیت پر اس کی کنیت رکھ سکتا ہوں؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:ہاں۔‘‘","صحیح",{"k":"سنن أبوداؤد (4967)، سنن ترمذی (2843)۔"}],[405,"سیدہ عائشہ رضی اللہ عنہا سے مروی ہے کہ:\n’’انہوں نے(یعنی عائشہؓ نے)عرض کیا:اے اللہ کے رسول!آپ صلی اللہ علیہ وسلم کی سب بیویوں کی کنیت ہے، کیا آپ صلی اللہ علیہ وسلم میری کنیت نہیں رکھیں گے؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:تم اپنے بیٹے عبداللہ کے نام سے اپنی کنیت رکھ لو، چنانچہ ان کی کنیت اُمِ عبداللہ رکھ دی گئی۔‘‘","صحیح",{"k":"سنن أبوداؤد (4970)، الأدب المفرد للبخاری (850)۔"}],[406,"ابوجبیرہ بن ضحاک بیان کرتے ہیں کہ:\n’’یہ آیت ﴿وَلَا تَنَابَزُوا بِالْأَلْقَابِ﴾ بنو سلمہ کے بارے میں اتری ہے، جب رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے تو ہم میں سے ہرآدمی کے دو نام تھے، رسول اللہ صلی اللہ علیہ وسلم جب(کسی کا نام لے کر)فرماتے کہ اے فلاں!، تو آپ صلی اللہ علیہ وسلم سے کہا جاتا کہ اے اللہ کے رسول!یہ نام مت لیجیے، وہ اس نام سے غصہ کرتاہے۔ تو یہ آیت نازل ہوگئی کہ:﴿وَلَا تَنَابَزُوا بِالْأَلْقَابِ﴾’’اور ایک دوسرے کو برے القاب مت دو۔‘‘","صحیح",{"k":"سنن أبوداؤد (4962)، سنن ترمذی (3268)، سنن ابن ماجه (3741)۔"}],[407,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’اے لوگو!یقیناًاللہ تعالٰی پاک ہے اور پاکیزہ مال کو ہی قبول فرماتا ہے، اور بلاشبہ اس نے مومنین کو بھی وہی حکم دیا جو اس نے رسولوں کو دیا، اللہ تعالٰی نے فرمایا: «يَا أَيُّهَا الرُّسُلُ كُلُوا مِنَ الطَّيِّبَاتِ وَاعْمَلُوا صَالِحًا إِنِّي بِمَا تَعْمَلُونَ عَلِيمٌ» ’’اے رسو لو!پاکیزہ چیزیں کھاؤ اور نیک عمل کرو، یقیناًمیں تمہارے اعمال کو بہت اچھی طرح جانتا ہوں۔‘‘ اور فرمایا: «يَا أَيُّهَا الَّذِينَ آمَنُوا كُلُوا مِنْ طَيِّبَاتِ مَا رَزَقْنَاكُمْ» ’’اے مومنو!جو ہم نے تمہیں پاکیزہ رزق عطا کیا ہے اس سے کھاؤ۔‘‘ پھر آپ صلی اللہ علیہ وسلم نے ایسے آدمی کا ذکر کیا جو لمبا سفر کرے، اس کے بال پراگندہ ہوں اور خود غبار سے اَٹاہو، وہ اپنے ہاتھوں کو پھیلا کر ’’اے میرے رب! اے میرے پروردگار!‘‘ کہنے لگے جبکہ اس کا کھانا حرام ہو، اس کا پینا حرام ہو، اس کا لباس حرام ہو اور اسے غذا بھی حرام ہی دی گئی ہو، تو اس کی دعا کیسے قبول کی جاسکتی ہے؟‘‘","صحیح",{"k":"صحیح مسلم (1015)، مسند أحمد (2؍328)۔","f":"اس حدیث میں مذکورہ صفات والے بندے کی مثال اس لیے دی گئی کہ ایسی حالت والا بندہ یعنی جو بہت لمبا سفر کرکے آرہا ہو، اس کے بال پراگندہ ہوں، اس کا جسم گردوغبار سے اَٹاپڑا ہو، ایسی حالت میں بندہ بہت قابلِ رحم لگتا ہے اور اس پر شفقت کرنے کوجی چاہتا ہے، لیکن اگر ایسے بندے کا کھانا، پینا، لباس حتٰی کہ اس نے پرورش ہی حرام مال سے پائی ہو تو اس کی ایسی قابلِ رحم حالت کی بھی اللہ تعالٰی رعایت نہیں کرتا اور اس کی دعا کو قبول نہیں فرماتا۔ قابلِ غور بات یہ ہے کہ جب ایسا شخص بھی التفاتِ الٰہی کا مستحق نہیں ٹھہرتا تو پھر عام شخص کیا حیثیت رکھتا ہے؟ اس کی دعائیں تو بالا ولٰی قبول نہیں کی جاتی ہوں گی۔ اس لیے اللہ تعالٰی کے ہاں اپنی دعاؤں کو شرفِ قبولیت بخشوانے کے لیے اپنے مال کو قطعی طور پر حرام کی پلیدگی سے بچانا چاہیے۔"}],[408,"نعمان بن بشیر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’حلال بھی واضح ہے اور حرام بھی واضح ہے، اور ان دونوں کے درمیان مشتبہات ہیں جن(کے حلال یاحرام ہونے)کا بہت سے لوگوں کو علم ہی نہیں ہے، سوجو ان مشتبہات سے بچ گیا اس نے اپنادِین اور اپنی عزت دونوں محفوظ کرلیں، اور جو ان مشتبہات میں پڑگیا وہ اس چرواہے کے مانند ہے، جو(اپنے جانوروں کو ممنوعہ)چراگاہ کے اِردگِردچراتا ہے، بعید نہیں ہے کہ وہ اس چراگاہ میں ہی گھُس جائے، آگاہ رہو!ہرباد شاہ کی ایک چراگاہ ہوتی ہے اور بلاشبہ زمین میں اللہ تعالٰی کی چراگاہ اس کے حرام کردہ امور ہیں۔ یاد رکھو!یقیناًجسم میں ایک ایساٹُکڑا ہے کہ جب تک وہ درست رہے سارا جسم ہی درست رہتا ہے اورجب وہ خراب ہوجائے تو سارا جسم ہی خراب ہو جاتا ہے، سنو!وہ دِل ہے۔‘‘","صحیح",{"k":"صحیح بخاری (52)، صحیح مسلم (1599)۔"}],[409,"ابنِ عباس رضی اللہ عنہما بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے قضائے حاجت کی، پھر آپ صلی اللہ علیہ وسلم کی خامت میں کھانا پیش کیا گیا تو آپ صلی اللہ علیہ وسلم نے کھا لیا، اور پانی کوچُھوا تک نہیں۔‘‘","صحیح",{"k":"صحیح مسلم (374)۔","f":"یعنی نبی صلی اللہ علیہ وسلم نے اسی طہارت پر اکتفا کیا جو قضائے حاجت کے بعد کی تھی اور کھا نے کے لیے دوبارہ ہاتھ نہیں دھوئے۔ گویا اگر ہاتھ پہلے سے پاک صاف ہوں تو دھو نے کی ضرورت نہیں ہے اور اگر صاف نہ ہوں تو دھو لینے چاہییں۔"}],[410,"ابنِ عباس رضی اللہ عنہما بیان کرتے ہیں کہ:\n’’ہم نبی صلی اللہ علیہ وسلم کے پاس تھے کہ آپ صلی اللہ علیہ وسلم قضائے حاجت کے لیے گئے، پھرجب واپس آئے تو کھانا آچکا تھا، پوچھا گیا:کیا آپ صلی اللہ علیہ وسلم وضوء نہیں فرمائیں گے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:میں نماز نہیں پڑھنے لگا کہ وضوء کروں۔‘‘","",{"f":"امام شافعیؒ فرماتے ہیں کہ زیادہ لائقِ ادب یہی ہے کہ وہ کام کیا جائے جو رسول اللہ صلی اللہ علیہ وسلم نے کیا ہے، چنانچہ آدمی کے ہاتھوں کو اگر گندگی نہ لگی ہو تو انہیں دھونے سے پہلے کھانا کھا لینا میرے نزدیک زیادہ پسندیدہ عمل ہے)چونکہ نبی صلی اللہ علیہ وسلم اپنے ہاتھوں کو پہلے پاک کر چکے تھے اس لیے دوبارہ نہیں دھویا(۔"}],[411,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جو شخص اس حالت میں سوجائے کہ اس کے ہاتھ میں چکنائی لگی ہو، پھر اگر اسے کوئی نقصان پہنچتا ہے تو وہ اپنے آپ کو ہی ملامت کرے۔‘‘","صحیح",{"k":"سنن ترمذی (1860)۔","f":"ہاتھ پہ سالن کی چکنائی لگی ہو اور اسے دھوئے بغیر ہی سوجا نے کو مکروہ سمجھا گیا ہے، کیونکہ اس سے نقصان کا اندیشہ ہے کہ ممکن ہے کیڑے مکوڑے اس کی بُوپا کر اس تک پہنچ جائیں اور اسے نقصان پہنچا دیں۔ لہٰذا ایسی صورت میں اگر اس کا کوئی نقصان ہو جاتا ہے توبہ فرمانِ نبویؐ اس کا وہ خود ہی ذمے دار ہے اور اسے اپنے آپ کو ہی ملامت کرنا چاہیے۔"}],[412,"ابنِ عباس رضی اللہ عنہ روایت کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم نے دودھ پِیا، پھرکُلّی کی اور فرمایا:اس میں چکناہٹ ہوتی ہے۔ سویدبن نعمان رسول اللہ صلی اللہ علیہ وسلم کے ستُّوکھا نے کا واقعہ بیان کرتے ہیں کہ صحابہؓ نے بھی آپ صلی اللہ علیہ وسلم کے ساتھ ستُّوکھائے، پھر آپ صلی اللہ علیہ وسلم مغرب کی نماز پڑھنے کے لیے کھڑے ہوئے، آپ صلی اللہ علیہ وسلم نے کُلّی کی تو ہم نے بھی کُلّی کرلی، پھر آپ صلی اللہ علیہ وسلم نے نماز پڑھائی اور وضوء نہیں کیا۔ اسی طرح ابنِ عباس رضی اللہ عنہما نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے بکری کی ہڈی کا گوشت کھایا، پھر نماز پڑھی، آپ صلی اللہ علیہ وسلم نے نہ توکُلّی کی اور نہ ہی پانی کوچھُوا۔ اور انس رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے دودھ پِیااور وضوء کیے بغیر ہی نماز پڑھ لی۔‘‘","صحیح",{"k":"صحیح بخاری (211)، صحیح مسلم (358)۔","f":"انسؓ کا یہ قول جواز پر محمول کیا جائے گااور جو اس سے پہلے والا ہے وہ استحباب پر۔"}],[413,"جابربن عبداللہ رضی اللہ عنہ روایت کرتے ہیں کہ انہوں نے نبی صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’جب آدمی گھر میں داخل ہوتاہے اور داخلے کے وقت اور کھا نے کے وقت اللہ کا ذکر کر لے تو شیطان(اپنے آپ سے) کہتا ہے کہ نہ تو تمہارے لیے (یہاں)رات گزارنے کا ٹھکانہ ہے اور نہ ہی شام کا کھانا۔ لیکن جب گھر میں داخلے کے وقت اللہ کا ذکر نہیں کرتا تو شیطان کہتا ہے:تمہیں رات گزارنے کا ٹھکانہ مل گیا، اورجب وہ کھانے کے وقت اللہ کا ذکر نہیں کرتا تو شیطان کہتا ہے:تم نے رات گزارنے کا ٹھکانہ اور شام کا کھانا دونوں حاصل کر لیے ہیں۔‘‘","صحیح",{"k":"صحیح مسلم (2018)، سنن أبوداؤد (3765)، سنن ابن ماجه (3887)۔","f":"اللہ کاذِکر کرنے سے مراد دعا پڑھنا ہے۔ گھر میں داخل ہوتے وقت یہ دعا پڑھی جائے: «اَللّٰهُمَّ» اِنِّیْ أَسْئَلُكَ «خَيْرَ الْمَوْلِجِ وَخَيْرَ الْمَخْرَجِ بِسْمِ اللّٰهِ وَلَجْنَا وَبِسْمِ اللّٰهِ خَرَجْنَا» وَعَلَی «اللّٰهِ رَبِّنَا» تَوَکَّلْنَا اور کھانا کھا نے سے پہلے «بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيْمِ» پڑھنی چاہیے۔"}],[414,"سیدہ عائشہ رضی اللہ عنہا روایت کرتی ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم اپنے چھے صحابہ کے ساتھ کھانا کھا رہے تھے کہ ایک بدوی آیا اور اس نے دو لقموں میں ہی کھا لیا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:یقیناًاگر یہ بسم اللہ پڑھ لیتا تو تمہیں بھی پورا آجاتا، جب تم میں سے کوئی کھائے اور وہ بسم اللہ پڑھنا بھول جائے تو اسے یوں کہنا چاہیے: «بِسْمِ اللّٰهِ أَوَّلَهُ وَآخِرَهُ» ’’اللہ تعالیٰ کے نام کے ساتھ )شروع کرتا ہوں(اس کے اوّل اور اس کے آخر میں۔‘‘","حسن",{"k":"سنن أبوداؤد (3767)، مسند أحمد (6؍246)۔"}],[415,"وہب بن قیسان روایت کرتے ہیں کہ انہوں نے عمربن ابی سلمہ رضی اللہ عنہ کو فرماتے سنا:\n’’میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ کھانا کھا رہا تھا اور میرا ہاتھ برتن میں گھُوم رہاتھا، تو آپ صلی اللہ علیہ وسلم نے فرمایا:اے بچے!بِسم ِاللہ پڑھ، اپنے دائیں ہاتھ سے اور اپنے سامنے سے کھا۔‘‘","صحیح",{"k":"صحیح بخاری (5376)، صحیح مسلم (2022)۔"}],[416,"ابنِ عمر رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب تم میں سے کوئی کھائے تو اسے اپنے دائیں ہاتھ سے کھانا چاہیے اورجب کوئی پِیے تو اسے پِینا بھی دائیں ہاتھ سے ہی چاہیے، کیونکہ بائیں ہاتھ سے شیطان کھا تاپِیتا ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2020)، سنن أبوداؤد (3776)۔"}],[417,"ابنِ عباس رضی اللہ عنہما بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم کے پاس ثرید کا ایک بڑا پیالہ لایا گیا، تو آپ صلی اللہ علیہ وسلم نے فرمایا:اس کے(اپنی اپنی طرف کے)کناروں سے کھانا اور درمیان سے مت کھانا، کیونکہ درمیان میں برکت نازل ہوتی ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (3772)، سنن ترمذی (1805)، سنن ابن ماجه (3277)۔"}],[418,"کعب بن مالک رضی اللہ عنہ فرماتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم تین انگلیوں سے کھایا کرتے تھے اورتب تک اپنا ہاتھ صاف نہیں کرتے تھے جب تک اسے چاٹ نہ لیتے۔‘‘","صحیح",{"k":"صحیح مسلم (2032)، مسند أحمد (3؍177)۔"}],[419,"انس بن مالک رضی اللہ عنہ روایت کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم جب کھانا کھاتے تو اپنی تین انگلیاں چاٹتے، اور فرماتے:جب تم میں سے کسی کا لقمہ گرجائے تو اسے اس سے گندگی(مٹی وغیرہ)جھاڑ کر کھا لینا چاہیے اور وہ اسے شیطان کے لیے نہ چھوڑ دے۔ اور آپ صلی اللہ علیہ وسلم ہمیں حکم فرماتے کہ ہم پلیٹ کو انگلی سے صاف کریں، اور فرماتے:بلاشبہ تم میں سے کوئی نہیں جانتا کہ اس کے کس کھانے میں برکت ڈالی گئی ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2033)، سنن أبوداؤد (4845)، سنن ترمذی (1803)۔","f":"انسان کو یہ علم نہیں ہوتا کہ جو وہ کھانا کھا رہا ہے اس کے کس حصے میں برکت ہے، شاید اسی میں ہی اللہ نے برکت رکھی ہو جو اس نے برتن میں لگا چھوڑ دیا۔ اس لیے نبی صلی اللہ علیہ وسلم نے برتن کو انگلی کے ساتھ صاف کر کے چاٹنے کاحکم فرمایا۔"}],[420,"سیدنا جابر رضی اللہ عنہ روایت کرتے ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’تم میں سے کوئی بھی (کھانا کھا نے کے بعد)تب تک رومال سے اپنا ہاتھ مت پُونچھے جب تک کہ وہ اسے چاٹ نہ لے، کیونکہ آدمی کو یہ معلوم نہیں ہوتا کہ اس کے کس کھانے میں برکت رکھی گئی ہے۔‘‘","صحیح",{"k":"مسند أحمد (15237)، سنن ترمذی، أبواب۔","f":"یعنی ممکن ہے کہ کھانے کا جو تھوڑا ساحصہ اس کی انگلیوں کے ساتھ لگا ہو اسی میں ہی برکت ہو، اس لیے اسے رومال یاٹِشُووغیرہ سے صاف کرنے کی بہ جائے چاٹ لینا چاہیے۔"}],[421,"انس رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم کی دعوت کی، آپ صلی اللہ علیہ وسلم تشریف لے گئے اور آپ صلی اللہ علیہ وسلم کے ساتھ میں بھی تھا، وہ آدمی شوربہ لے کر آیا، اس میں کدُّوتھے، رسول اللہ صلی اللہ علیہ وسلم کدُّوکھا نے لگے اور آپ صلی اللہ علیہ وسلم انہیں پسند کرتے تھے۔ جب میں نے یہ دیکھا تو میں (کدُّواُٹھااُٹھا کر)آپ صلی اللہ علیہ وسلم کی طرف رکھنے لگا اور خود میں نے اس سے کچھ نہ کھایا۔ انسؓ فرماتے ہیں کہ اس کے بعد میں بھی کدُّوپسند کرنے لگا۔سلیمان التیمی کہتے ہیں کہ ہم کدُّوؤں کے موسم میں جب بھی انس رضی اللہ عنہ کے پاس آئے تو ہم نے آپ کے کھانے میں کدُّوہی پائے۔‘‘","صحیح",{"k":"صحیح بخاری (5436)، صحیح مسلم (2041)۔"}],[422,"سلمان بیان کرتے ہیں کہ:\n’’انہوں نے ایک آدمی کو کھا نے کی دعوت دی، اسی دوران ایک مسکین آگیا تو اس(مہمان)نے اسے ایک ٹکڑا دے دیا، تو سلمان نے اس سے کہا:جہاں سے پکڑا ہے وہیں رکھ دو، میں نہیں چاہتا کہ گناہ تیرے سرآئے اور اجر تیرے علاوہ کوئی اور لے جائے، ہم نے تو اس لیے تمہیں دعوت دی ہے تاکہ تُو(خود)کھائے۔‘‘","صحیح",{"k":"السنن الکبری للبیهقی (7؍278)۔","f":"اس روایت کا مفہوم یہ ہے کہ مہمان چونکہ جس کھانے پر مدعو ہوتا ہے وہ اس کی ملکیت میں نہیں ہوتا بلکہ اسے وہ اعزازاًپیش کیا گیا ہوتا ہے، اس لیے اسے اس کھانے کو صدقہ وخیرات کرنے کاحق حاصل نہیں ہوتا بلکہ وہ صرف اسے تناول کر سکتا ہے، صدقہ کرنے کاحق صرف میزبان کو حاصل ہے کیونکہ وہ کھانا اسی کے مال سے تیار کردہ ہوتاہے اور اپنے مال کو کہیں بھی صرف کرنے کا وہی مجاز ہوتا ہے۔ روایت میں مذکور الفاظ ’’میں نہیں چاہتا کہ گناہ تیرے سرآئے اور اجر تیرے علاوہ کوئی اور لے جائے‘‘ کا مطلب یہی ہے کہ مہمان اگر اس کھانے کو صدقہ کرے تو وہ ایک ایسے کام کا مرتکب ہونے کی وجہ سے کہ جس کی اسے اجازت نہیں تھی، گنہگار ہوگا جبکہ اس صدقے کا اجر میزبان کومل جائے گا۔"}],[423,"ابوہریرہ رضی اللہ عنہ فرماتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے کبھی کسی کھانے میں عیب نہیں نکالا، اگر آپ صلی اللہ علیہ وسلم کو اس کاجی چاہتا تو کھا لیتے وگرنہ چھوڑ دیتے۔‘‘","صحیح",{"k":"صحیح بخاری (5409)، صحیح مسلم (2064)۔"}],[424,"ہُلب رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’ایک آدمی نے آپ صلی اللہ علیہ وسلم سے پوچھا کہ کوئی کھانا ایسا بھی ہوتاہے کہ جسے کھانے میں مَیں حرج محسوس کرتا ہوں(تو اس صورت میں میں کیا کروں؟) تو آپ صلی اللہ علیہ وسلم نے فرمایا:کوئی بھی چیز تیرے دِل میں خلل(شک وشبہ)ہرگز نہ ڈالے (کیونکہ)اس کام میں تُونصر انیوں کے مشابہ ہوجائے گا۔‘‘","حسن",{"k":"سنن أبوداؤد (3784)، سنن ترمذی (1565)، سنن ابن ماجه (2830)۔"}],[425,"عمروبن اُمیہ بیان کرتے ہیں کہ:\n’’انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو اپنے ہاتھ میں بکری کے کندھے کا گوشت کاٹتے دیکھا، پھر آپ صلی اللہ علیہ وسلم کو نماز کے لیے بلایا گیا تو آپ صلی اللہ علیہ وسلم نے وہ گوشت اور وہ چھری جس سے کاٹ رہے تھے، وہیں رکھ دی، پھراُٹھے اور نماز پڑھائی، اور وضوء نہیں کیا۔‘‘","صحیح",{"k":"صحیح بخاری (5462)، صحیح مسلم (355)۔"}],[426,"عبداللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم کو بکری کی پنڈلی کے اوپر والے حصے کی ایسی ہڈی بہت پسند تھی جس کا گوشت اتار لیا گیا ہو، آپ صلی اللہ علیہ وسلم کو زہر بھی اسی میں ہی دیا گیا تھا اور آپ صلی اللہ علیہ وسلم کے خیال کے مطابق یہودیوں نے آپ صلی اللہ علیہ وسلم کو زہر دیا تھا۔‘‘","صحیح",{"k":"سنن أبوداؤد (3781)، مسند أحمد (1؍394)۔"}],[427,"انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’ایک درزی نے رسول اللہ صلی اللہ علیہ وسلم کی دعوت کی، اس نے آپ صلی اللہ علیہ وسلم کو ثرید پیش کیاجس میں اس نے کدُّوڈا لے ہوئے تھے، تو رسول اللہ صلی اللہ علیہ وسلم کدُّوپکڑ پکڑ کر کھا نے لگے۔ راوی کہتے ہیں کہ آپ صلی اللہ علیہ وسلم کدُّوپسند فرمایا کرتے تھے۔ ثابت بیان کرتے ہیں کہ میں نے انس رضی اللہ عنہ کو فرماتے سنا:میرے لیے کبھی ایسا کھانا نہیں تیار کیا گیا کہ جس میں کدُّوڈالنے کی مجھ میں قدرت ہو اور میں نے نہ ڈالے ہوں۔‘‘","صحیح",{"k":"صحیح بخاری (5436)، صحیح مسلم (2041)۔"}],[428,"سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم میٹھی چیز اور شہد کو پسند فرمایا کرتے تھے۔‘‘","صحیح",{"k":"صحیح بخاری (5431)، سنن أبوداؤد (3715)۔"}],[429,"سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم کاسب سے پسندیدہ مشروب (وہ ہوتا تھا جو) ٹھنڈا اور میٹھا ہو۔‘‘","صحیح",{"k":"سنن ترمذی (1895)، مسندأحمد (6؍38)، صحیح الجامع للألبانی (4627)۔"}],[430,"زہری بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم سے پوچھا گیا کہ کونسا مشروب زیادہ اچھا ہے؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا: جو میٹھا اور ٹھنڈا ہو۔‘‘","صحیح",{"k":"سنن ترمذی (1895)، مسندأحمد (6؍38)، صحیح الجامع للألبانی (4627)۔"}],[431,"سیدہ عائشہ رضی اللہ عنہا سے مروی ہے کہ:\n’’جب کسی گھر میں کسی کی وفات ہوجاتی اور اس کی تعزیت کے لیے عورتیں اکٹھی ہوتیں، پھر وہ چلی جاتیں اور گھر کے افراد اور خاص خاص لوگ ہی رہ جاتے تو عائشہ رضی اللہ عنہا انہیں تلبینہ کی ہانڈی پکانے کاحکم دیتیں، جب وہ پکا لیا جاتا تو آپؓ ثرید بنا تیں اور اس ثرید پر تلبینہ ڈالتیں، پھر کہتیں کہ اسے کھاؤ، کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے کہ تلبینہ بیمار شخص کے دِل کو تقویت پہنچاتا ہے اور اس کاغم دور کرتا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (5417)، صحیح مسلم (2216)۔","f":"عرب لوگ تلبینہ آٹے اور دودھ یابھوسی اور دودھ کو ملا کر حلوہ ساتیار کرتے اور اس میں شہد ڈالتے تھے، اسے تلبینہ کہا جاتا تھا۔ یہ امراضِ دِل اور غمزدہ وپر یشان حال شخص کے لیے بہت مفید ہوتا تھا۔"}],[432,"جابربن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم نے میرا ہاتھ پکڑا اور اپنے کسی گھر لے آئے اور گھر والوں سے پوچھا:کیا کوئی سالن ہے؟ انہوں نے جواب دیا:سِرکے کے سوا کوئی سالن نہیں ہے، آپ صلی اللہ علیہ وسلم نے ان سے فرمایا:وہی لے آؤ، سِرکہ تو بہت اچھا سالن ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2052)۔"}],[433,"سیدنا عمر رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’زیتون کا تیل سالن کے طور بھی پر استعمال کرو اور اسے بہ طورِتیل (سراور بدن پر)بھی لگاؤ، کیونکہ یہ مبارک درخت سے نکالا جاتا ہے۔‘‘","صحیح",{"k":"سنن ترمذی (1851)، سنن ابن ماجه (3319)، سلسلہ الأحادیث الصحیحہ (379)۔"}],[434,"جابر رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’جس نے اس درخت سے کچھ کھایا، یعنی لہسن، پیاز اور گیندنا، تو وہ ہماری مسجد کے قریب بالکل نہ آئے، کیونکہ جس چیز سے انسان تکلیف پاتے ہیں اس سے فرشتوں کو بھی تکلیف پہنچتی ہے۔‘‘","صحیح",{"k":"صحیح بخاری (854)، صحیح مسلم (564)۔","f":"گیندنا بھی سبزی کی ہی ایک بدبودار قسم ہے جو پیاز کے مشابہ ہوتی ہے۔ تکلیف سے مراد یہ ہے کہ ان چیزوں کو کھا نے سے چونکہ منہ سے بُوآنے لگتی ہے جس سے مخاطب ناگواری محسوس کرتاہے، اس لیے فرمایاکہ فرشتے بھی اس سے تکلیف محسوس کرتے ہیں۔"}],[435,"جابربن سمرہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم جب کھانا کھا لیتے تھے تو باقی کھانا ابو ایوب انصاریؓ کو بھیج دیتے تھے، سو(ایک مرتبہ)آپ صلی اللہ علیہ وسلم نے انہیں ایک پیالہ بھیجاجس سے آپ صلی اللہ علیہ وسلم نے کھایا نہیں تھا(کیونکہ)اس میں لہسن تھا، تو ابو ایوبؓ آپ صلی اللہ علیہ وسلم کے پاس حاضر ہوئے اور عرض کیا:اے اللہ کے رسول!کیا یہ حرام ہے؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:نہیں، لیکن میں اس کی بُوکو ناپسند کرتا ہوں، تو ابو ایوبؓ نے کہا:جو چیز آپ صلی اللہ علیہ وسلم کو ناپسند ہے اسے میں بھی پسند نہیں کرتا۔‘‘","صحیح",{"k":"سنن ترمذی (1807)، مسند أحمد (5؍94)۔"}],[436,"سیدنا علی رضی اللہ عنہ فرماتے ہیں:\n’’لہسن کو پکائے بغیر کھا نے سے منع کیا گیا ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (3828)، سنن ترمذی (1808)۔"}],[437,"سیدنا عمر رضی اللہ عنہ نے لہسن اور پیاز کے بارے میں فرمایا:\n’’جس شخص نے یہ ضرور ہی کھانے ہوں تو اسے چاہیے کہ وہ انہیں پکا کر ان کی بدبو ختم کرلے۔‘‘","صحیح",{"k":"صحیح مسلم (567)، مسند أحمد (1؍15)۔"}],[438,"اسماء بنت ابی بکر رضی اللہ عنہا کے بارے میں مروی ہے کہ:\n’’جب آپؓ روٹی اور شوربے کا ثرید بنا تیں تو دیگچی کا ڈھکن اتار دیتیں، یہاں تک کہ اس کی گرمائش ختم ہوجاتی، پھر فرماتیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے کہ یقیناًیہ بڑی برکت کا باعث ہے۔‘‘","صحیح",{"k":"مسند أحمد (6؍350)، مستدرک حاکم (4؍118)، سلسلہ الأحادیث الصحیحہ (659)۔"}],[439,"ابوہریرہ رضی اللہ عنہ فرمایا کرتے تھے کہ:\n’’کھا ناتب تک نہ کھایا جائے جب تک کہ اس کی بھاپ ختم نہ ہوجائے۔‘‘","صحیح",{"k":"السنن الکبری للبیهقی (7؍280)۔"}],[440,"جبلہ بن سحیم بیان کرتے ہیں کہ:\n’’ہم پر ابنِ زبیر رضی اللہ عنہ کے (عہدِخلافت میں ان کے)ساتھ ایک سال قحط آن پڑا، ہمیں کھجوریں دی گئیں، ہم وہ کھجوریں کھا رہے تھے کہ عبداللہ بن عمر رضی اللہ عنہما ہمارے پاس سے یہ فرماتے ہوئے گزرے کہ تم دو دو کھجوریں ملا کرمت کھاؤ، کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے دو کھجوریں ملا کر کھا نے سے منع فرمایا ہے، ہاں اگر آدمی اپنے ساتھی سے اجازت لے لے تو پھر کھا سکتا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (5446)، صحیح مسلم (2045)۔","f":"یعنی اگر دوآدمی اکٹھے کھجوریں کھا رہے ہوں تو ایک آدمی کو دو دو کھجوریں اکٹھی نہیں کھانی چاہییں، کیونکہ اس سے دوسرے ساتھی کی حق تلفی ہوتی ہے کہ یوں اس کے حصے میں تھوڑی آئیں گی اور یہ اپنے حصے سے زیادہ کھا جائے گا، لیکن اگر اس کا ساتھی بہ خوشی اجازت دے دے تو پھر ایسا کرنے میں کوئی حرج نہیں ہے۔"}],[441,"عبداللہ بن جعفر رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’میں نے رسول اللہ صلی اللہ علیہ وسلم کو تازہ کھجور کے ساتھ ککڑی کھاتے دیکھا۔‘‘","صحیح",{"k":"صحیح بخاری (5440)، صحیح مسلم (2043)۔"}],[442,"سیدہ عائشہ رضی اللہ عنہا روایت کرتی ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم تربوز اور کھجور دونوں اکٹھے کھایا کرتے تھے، اور ایک روایت میں یہ اضافہ ہے کہ پھر آپ صلی اللہ علیہ وسلم فرماتے:اس کی گرمی اس کی ٹھنڈک کو توڑتی ہے اور اس کی ٹھنڈک اس کی گرمی کو توڑتی ہے۔‘‘","حسن",{"k":"سنن أبوداؤد (3836)، سنن ترمذی (1843)، سلسلہ الأحادیث الصحیحہ (57)۔","f":"چونکہ کھجور کی تاثیر گرم اور تربوز کی ٹھنڈی ہوتی ہے اور آپ صلی اللہ علیہ وسلم دونوں کو ایک ساتھ اس لیے ملا کر کھاتے تھے تاکہ کھجور کی گرم تاثیر تربوز کی ٹھنڈی تاثیر کا توڑ کر سکے اور تربوز کی ٹھنڈی تاثیر کھجور کی گرم تاثیر کا توڑ کر سکے۔ ٹھنڈی اور گرم چیز کو ملا کر کھانا بہت سے طبی فوائد کا حامل ہے، کیونکہ طبعِ انسانی دو ہی طرح سے کسی عارضے سے متاثر ہوتی ہے، ایک یہ کہ کوئی گرم شے اس پر اثر انداز ہو جائے اور دوسری یہ کہ کوئی ٹھنڈی چیز اس پر اثر کر جائے، اورجب ٹھنڈی اور گرم دونوں چیزوں کو ملا کر کھایا جائے تو کوئی بھی اثر انداز نہیں ہو پاتی کیونکہ ایک چیز دوسری کی تاثیر کو ختم کر دیتی ہے۔"}],[443,"بُسرکے دونوں بیٹے بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے تو ہم نے آپ صلی اللہ علیہ وسلم کی خدمت میں مکھن اور کھجور پیش کی، کیونکہ آپ صلی اللہ علیہ وسلم مکھن اور کھجور پسند فرمایا کرتے تھے۔‘‘","صحیح",{"k":"سنن أبوداؤد (3837)، سنن ابن ماجه (3334)۔"}],[444,"انس بن مالک رضی اللہ عنہ سے مروی ہے کہ:\n’’نبی صلی اللہ علیہ وسلم نے کھڑے ہو کر پینے سے سختی سے منع فرمایا۔ قتادہ کہتے ہیں کہ ہم نے پوچھا:کھڑے ہو کر کھانا کیسا ہے؟ تو آپ نے جواب دیا:یہ توسب سے بُرااور انتہائی قابلِ نفرت ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2025)۔","f":"امام بیہقیؒ فرماتے ہیں کہ یہ ممانعت ابو سعید خدری اور ابوہریرہ رضی اللہ عنہما سے بھی مروی ہے، اور لگتا ہے کہ کھڑے ہو کر پینے کی یہ ممانعت برسبیلِ تنزیہہ ہے(تنزیہہ کا مطلب ہے کسی چیز سے لوگوں کو دور رکھنے کے لیے اسے بُراقرار دینا)، اور بیٹھ کر پینے کو اختیار کرنے والی بات بہ طورِادب ہے، اور دوسری وجہ اس کی یہ بھی ہو سکتی ہے کہ کھڑے ہو کر پینے میں بیماری میں مبتلا ہو نے کا بھی خدشہ ہے جیسا کہ طبی ماہرین کا خیال ہے۔"}],[445,"ابنِ عباس رضی اللہ عنہما فرماتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم کا(میرے پاس سے)گزر ہوا تو آپ صلی اللہ علیہ وسلم نے پانی طلب فرمایا، میں آپ صلی اللہ علیہ وسلم کے پاس آبِ زم زم کا ایک ڈول لے کر آیا تو آپ صلی اللہ علیہ وسلم نے کھڑے کھڑے ہی پی لیا۔‘‘","صحیح",{"k":"صحیح مسلم (2027)۔"}],[446,"سیدنا علی بن ابی طالب رضی اللہ عنہ کے بارے میں مروی ہے کہ:\n’’آپؓ نے ظہر کی نماز پڑھائی، پھر لوگوں کی ضرورتیں سننے اور پوری کرنے کے سلسلے میں کوفہ(کی مسجد)کے صحن میں بیٹھ گئے، یہاں تک کہ نمازِعصر کا وقت ہوگیا، پھر آپؓ کے پاس پانی کا ایک مگ لایا گیا تو آپؓ نے اس سے ایک چُلُّوبھرا اور اسے اپنے چہرے، دونوں ہاتھوں، اپنے سراور دونوں پاؤں پر پھیر لیا، پھر آپؓ کھڑے ہوئے اور جو پانی بچ گیا تھا وہ پی لیا، حالانکہ آپؓ کھڑے تھے۔ پھر آپؓ نے فرمایاکہ یقیناًلوگ کھڑے ہو کر پینے کو ناپسند کرتے ہیں، جبکہ رسول اللہ صلی اللہ علیہ وسلم نے بھی اسی طرح کیا تھاجس طرح میں نے کیا۔‘‘","صحیح",{"k":"صحیح بخاری (5615)۔"}],[447,"ابوجحیفہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’میں ٹیک لگا کر نہیں کھاتا۔‘‘","صحیح",{"k":"صحیح بخاری (5398)، سنن أبوداؤد (3769)۔","f":"ٹیک لگا کر کھانا متکبرین کا انداز ہے کیونکہ اس سے نفس میں کِبرپیدا ہوتا ہے، اس لیے اس سے منع کیاگیا۔"}],[448,"عبداللہ بن عمرو رضی اللہ عنہما بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم کو کبھی ٹیک لگا کر کھاتے نہیں دیکھا گیا، اور نہ ہی دو آدمی آپ صلی اللہ علیہ وسلم کی ایڑھیاں روندتے تھے۔‘‘","صحیح",{"k":"سنن أبوداؤد (3770)، سنن ابن ماجه (244)، سلسلہ الأحادیث الصحیحہ (1239)۔","f":"ایڑھیاں روند نے سے مراد یہ ہے کہ آپ صلی اللہ علیہ وسلم لوگوں سے ممتاز ہو کر کبھی آگے آگے نہیں چلتے تھے کہ لوگ آپ صلی اللہ علیہ وسلم کے پیچھے پیچھے چلیں بلکہ آپ صلی اللہ علیہ وسلم ہمیشہ اپنے اصحاب کی معیت میں ہی چلتے تھے۔"}],[449,"انس رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم کو کھجوریں تحفے میں دی گئیں، میں نے رسول اللہ صلی اللہ علیہ وسلم کو بھوک کی وجہ سے اقعاء کی حالت میں بیٹھ کر کھجوریں کھاتے دیکھا۔‘‘","صحیح",{"k":"صحیح مسلم (2044)، سنن أبوداؤد (3771)۔","f":"دونوں ٹانگوں کی رانوں سے پنڈلیاں ملا کر کھڑی کرنا اورکُولہوں پر بیٹھنا’’اقعاء‘‘کہلاتا ہے۔ تو گویا کسی عذر کی بناء پر ایسا بیٹھنا جائز ہے، جیسا کہ نبی کریم صلی اللہ علیہ وسلم بھی بھوک کی وجہ سے کمزوری ہوجانے کی بناء پر اس حالت میں بیٹھے تھے۔"}],[450,"ابوقتادہ رضی اللہ عنہ روایت کرتے ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’جب تم میں سے کوئی پیشاب کرے تو وہ اپنی شرمگاہ کو اپنے دائیں ہاتھ سے ہرگز نہ چھُوئے، نہ اپنے دائیں ہاتھ سے استنجاء کرے اور نہ ہی برتن میں سانس لے۔‘‘","صحیح",{"k":"صحیح بخاری (154)، صحیح مسلم (267)۔"}],[451,"ابو مثنّٰی جہنی بیان کرتے ہیں کہ:\n’’میں مروان بن حکم کے پاس تھا کہ ابو سعید خدری رضی اللہ عنہ ان کے پاس تشریف لائے، تو مروان نے ان سے کہا:کیا آپ نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے کہ آپ صلی اللہ علیہ وسلم نے پینے کی چیز میں پھونک مارنے سے منع فرمایا ہے؟ تو ابو سعیدؓنے جواب دیا:جی ہاں، پھر ایک آدمی نے آپ صلی اللہ علیہ وسلم سے کہا:اے اللہ کے رسول!میں ایک سانس سے سیراب نہیں ہوتا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:اپنے منہ سے پیالے کو ہٹا لے، پھر سانس لے۔ اس نے کہا:میں اس میں گندگی دیکھوں تو؟ آپ صلی اللہ علیہ وسلم نے فرمایا:اسے انڈیل دے۔‘‘","صحیح",{"k":"سنن ترمذی (1887)۔"}],[452,"ثمامہ بیان کرتے ہیں کہ:\n’’سیدنا انس رضی اللہ عنہ مشروب پینے کے دوران دویا تین بار سانس لیتے تھے، اور ان کا خیال تھا کہ رسول اللہ صلی اللہ علیہ وسلم پیتے ہوئے تین بار سانس لیا کرتے تھے۔‘‘","صحیح",{"k":"صحیح بخاری (5631)، صحیح مسلم (2028)۔"}],[453,"ایک حدیث میں نبی کریم صلی اللہ علیہ وسلم نے تین سانسوں میں پانی یاکوئی بھی مشروب پینے کے فوائد بیان کیے ہیں، جیسا کہ انس بن مالک رضی اللہ عنہ روایت کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم جب کوئی مشروب پیتے تو تین بار سانس لیتے، اور فرماتے:اس طرح پینا پیاس بجھا نے، ہاضمے اور تندرستی کے لیے زیادہ بہتر ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2028)۔"}],[454,"جابربن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم ایک انصاری کے پاس اس کے باغ میں گئے، آپ صلی اللہ علیہ وسلم کے ساتھ آپ صلی اللہ علیہ وسلم کے ایک صحابی بھی تھے، آپ صلی اللہ علیہ وسلم نے فرمایا:اگر تمہارے پاس کسی مشکیزے میں رات کا پانی پڑا ہوا ہے (تو ہمیں دو)وگرنہ ہم منہ لگا کرپی لیں گے۔ وہ آدمی اپنے باغ کو پانی لگا رہا تھا، اس نے کہا:اے اللہ کے رسول!میرا خیال ہے کہ مشکیزے میں رات کا پانی پڑا ہوا ہے آپ صلی اللہ علیہ وسلم چھپّرمیں تشریف لے چلیں، راوی کہتے ہیں کہ آپ صلی اللہ علیہ وسلم وہاں چلے گئے اور اس آدمی نے ایک پیالے میں پانی لیا، پھر اس میں اپنی ایک دودھ دینے والی بکری کا دودھ نکالا، راوی کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے دودھ پیا اور پھر اس صحابی نے جو آپ صلی اللہ علیہ وسلم کے ساتھ تھے۔‘‘","صحیح",{"k":"صحیح بخاری (5613)، مسند أحمد (3؍343)۔"}],[455,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم سُقیا نامی چشمے سے اپنے لیے میٹھا پانی منگوایا کرتے تھے۔‘‘","صحیح",{"k":"سنن أبوداؤد (3735)۔"}],[456,"ابوہریرہ رضی اللہ بیان کرتے ہیں کہ:\n’’میں رسول اللہ صلی اللہ علیہ وسلم سے(سُنی ہوئی)کچھ باتیں تمہیں بتاتا ہوں، (ان میں سے ایک یہ ہے کہ)تم میں سے کوئی شخص مشکیزے کے منہ سے(اپنا منہ لگا کر)نہ پیے۔‘‘","صحیح",{"k":"صحیح بخاری (5628)، سنن ابن ماجه (3420)۔"}],[457,"ابوہریرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں:\n’’آپ صلی اللہ علیہ وسلم نے منع فرمایا ہے کہ آدمی مشکیزے کو منہ لگا کر پیے۔ ایوبؒ کہتے ہیں کہ کسی نے مجھے بتلایا کہ ایک آدمی نے مشکیزے کو منہ لکاگر پانی پیا تو اس سے سانپ نکل آیا۔‘‘","صحیح",{"k":"صحیح بخاری (5628)، سنن ابن ماجه (3420)۔"}],[458,"ابو سعید خدری رضی اللہ عنہ سے مروی ہے کہ:\n’’نبی صلی اللہ علیہ وسلم نے مشکیزوں کا منہ کھول کر ان کے مونہوں سے پینے سے منع فرمایا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (5562)، صحیح مسلم (2023)۔","f":"لہٰذا پانی کو پہلے کسی برتن میں نکال لینا چاہیے تاکہ تسلی ہو سکے کہ اس میں کوئی موذی چیز تو نہیں ہے اور پھر پینا چاہیے۔"}],[459,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب تم میں سے کسی کے مشروب میں مکھی گرجائے تو اسے پہلے ساری کو ڈبونا چاہیے اور پھر اسے باہر نکالنا چاہیے، کیونکہ اس کے ایک پَرمیں بیماری ہوتی ہے اور دوسرے پَرمیں شفا ہوتی ہے۔ اور ایک روایت میں یہ اضافہ ہے کہ وہ اپنے بیماری والے پَرسے اپنا بچاؤ کرتی ہے۔‘‘","صحیح",{"k":"صحیح بخاری (5782)، سنن أبوداؤد (3844)، سنن نسائی (4262)، سنن ابن ماجه (3505)۔"}],[460,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم جب مدینہ تشریف لائے تو میں دس برس کا تھا اورجب آپ صلی اللہ علیہ وسلم کی وفات ہوئی تو اس وقت میری عمر بیس سال تھی، اور میری مائیں مجھے آپ صلی اللہ علیہ وسلم کی خدمت کی ترغیب دلاتی رہتی تھیں، ایک بار آپ صلی اللہ علیہ وسلم ہمارے گھر تشریف لائے تو ہم نے دودھ دینے والی ایک بکری کا دودھ نکالا اور اس میں گھر کے کنویں کا پانی ملا کر آپ صلی اللہ علیہ وسلم کی خدمت میں پیش کیا، تو(پہلے)رسول اللہ صلی اللہ علیہ وسلم نے پیا، ابوبکر رضی اللہ عنہ آپ صلی اللہ علیہ وسلم کے بائیں جانب بیٹھے تھے، ایک بدوی صحابی آپ صلی اللہ علیہ وسلم کے دائیں جانب تھے اور سیدنا عمر رضی اللہ عنہ ایک سائیڈپہ بیٹھے ہوئے تھے، سوعمرؓنے کہا:ابوبکرؓکو دیجیے، لیکن آپ صلی اللہ علیہ وسلم نے بدوی صحابی کو دے دیا اور فرمایا:پہلے دائیں جانب والا، پھر اس کے دائیں والا۔‘‘","صحیح",{"k":"صحیح بخاری (2352)، صحیح مسلم (2029)۔"}],[461,"سہل بن سعد الساعدی رضی اللہ عنہ روایت کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم کے پاس کوئی مشروب لایا گیا تو آپ صلی اللہ علیہ وسلم نے اس سے کچھ پی لیا، آپ صلی اللہ علیہ وسلم کے دائیں جانب ایک غلام بیٹھا تھا جبکہ بائیں جانب بڑے بڑے بزرگ صحابہؓ تھے، آپ صلی اللہ علیہ وسلم نے غلام سے فرمایا:کیا تم مجھے اس کی اجازت دیتے ہوکہ (پہلے)میں ان لوگوں کوپِلادوں؟ تو غلام نے کہا:نہیں، اے اللہ کے رسول!اللہ کی قسم میں آپ صلی اللہ علیہ وسلم سے بچے ہوئے اپنے حصے پر کسی کو ترجیح نہیں دوں گا۔ راوی کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اس کے ہاتھ میں دودھ تھما دیا۔‘‘","صحیح",{"k":"صحیح بخاری (2351)، صحیح مسلم (2030)۔"}],[462,"عبداللہ بن ابی اوفٰی رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے، لوگوں کو پیاس لگی تو رسول اللہ صلی اللہ علیہ وسلم انہیں پانی پلانے لگے، (آپ صلی اللہ علیہ وسلم سے)کہا گیا:اے اللہ کے رسول!کیا آپ صلی اللہ علیہ وسلم نہیں پئیں گے؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:لوگوں کو پلا نے والا ان کے آخر میں پیتا ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (3725)، مسند أحمد (4؍354)، صحیح الجامع للألبانی (2088)۔"}],[463,"ابوامامہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’جب نبی صلی اللہ علیہ وسلم کے سامنے سے شام کا کھا نااُٹھا لیا جاتا تو آپ صلی اللہ علیہ وسلم یہ دعا پڑھتے: «اَلْحَمْدُ لِلَّهِ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا غَيْرَ مَكْفِيٍّ وَلَا مُوَدَّعٍ وَلَا مُسْتَغْنًى عَنْهُ رَبَّنَا» ’’تمام ترتعریفات اللہ تعالیٰ کے واسطے ہیں بہت زیادہ تعریف، اے ہمارے پروردگار!بہت پاکیزہ اور بابرکت کھانا تھا، نہ تو اس میں کفایت سے کام لیا گیا، نہ اسے چھوڑ دیا گیا اور نہ ہی اس کے بغیر رہا جا سکتا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (5458)، سنن أبوداؤد (3849)۔"}],[464,"سیدنا انس رضی اللہ عنہ روایت کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم جب اپنے بستر پر لیٹتے تو یہ دعا پڑھتے: «اَلْحَمْدُ لِلَّهِ، أَطْعَمَنَا وَسَقَانَا وَكَفَانَا وَآوَانَا، فَكَمْ مِمَّنْ لَا كَافِيَ لَهُ وَلَا مُؤْوِيَ» ’’تمام ترتعریفات اللہ تعالیٰ کے لیے ہیں، جس نے ہمیں کھلایا، ہمیں پلایا، ہمیں(ہرحاجت وتکلیف سے)کافی ہوا اور ہمیں (رہنے کے لیے)جگہ دی، سوکتنے ہی لوگ ایسے ہیں کہ جنہیں نہ تو کوئی کفایت کرنے والا ہے اور نہ ہی جگہ دینے والا۔‘‘","صحیح",{"k":"صحیح مسلم (2715)، سنن أبوداؤد (5053)، سنن ترمذی (3396)۔"}],[465,"ابنِ عمر رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’یقیناًمومن ایک آنت میں کھاتا ہے اور کافر سات آنتوں میں کھاتا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (5393)، صحیح مسلم (2060)۔"}],[466,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے ایک مہمان کی مہمان نوازی کی اور وہ مہمان کافر تھا، رسول اللہ صلی اللہ علیہ وسلم نے بکری کا دودھ نکال کر لانے کاحکم فرمایا، دودھ نکال کر لایا گیا تو وہ پی گیا، پھر دوسری کا لایا گیا تو وہ بھی پی گیا، یہاں تک کہ اس نے سات بکریوں کا دودھ پی لیا، پھر اگلی صبح اس نے اسلام قبول کرلیا، تو رسول اللہ صلی اللہ علیہ وسلم نے اس کے لیے بکری کا دودھ لانے کاحکم فرمایا(وہ لایا گیا)تو اس نے پی لیا، پھر آپ صلی اللہ علیہ وسلم نے دوسری بکری کا دودھ منگوایا لیکن وہ سارا نہیں پی سکا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:مومن ایک آنت میں کھاتا ہے اور کافر سات آنتوں میں کھاتا ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2063)، سنن ترمذی (1819)۔","f":"امام بیہقیؒ فرماتے ہیں کہ اس حدیث میں مِعَاءٌسے مراد معدہ ہے، اور اس کا معنٰی یہ ہے کہ کافر اس بندے جتنا کھاتا ہے جس کے سات معدے ہوں، جبکہ مومن ایک معدے والے بندے جتنا کھاتا ہے۔ راقم کی نظر میں اس کی وجہ یہ ہے کہ مومن چونکہ بسم اللہ پڑھ کر کھاتا ہے تو اللہ تعالٰی ایک تو اس کے کھانے میں برکت ڈال دیتا ہے اور دوسرا یہ کہ شیطان بھی اس کے ساتھ بیٹھ کر کھا نے سے بھاگ جاتا ہے، جیسا کہ ایک حدیث میں بیان ہے کہ جو بسم اللہ پڑھ کر نہیں کھاتا اس کے ساتھ شیطان بیٹھ جاتا ہے، جبکہ کافر کا بسم اللہ پڑھنا تو کجا اسلام سے ہی چنداں واسطہ نہیں ہوتا، اس لیے اس کا کھانا بھی بے برکت ہوتاہے اور شیطان بھی اس کے ساتھ شریک رہتا ہے، تبھی وہ سات سات آدمیوں کا کھانا اکیلا ہی کھا جاتا ہے۔"}],[467,"جابربن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’ایک بندے کا کھانا دو کو کفایت کر جاتا ہے، دو کا چار کو کافی ہو جاتا ہے اور چار کا آٹھ کوپُوراآ جاتا ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2059)، سنن ترمذی (1820)، سنن ابن ماجه (3254)۔","f":"یہ حدیث درحقیقت اکٹھے مل کر کھا نے کی فضیلت کے بارے میں ہے کہ اکیلے کھانے میں وہ برکت نہیں ہے جو اکٹھے مل کر کھا نے میں ہوتی ہے۔ اکٹھے مل کر کھایا جائے تو ایک شخص کا کھانا دو کو پوراآجاتا ہے، دوآدمیوں کے کھانے سے چارآدمی سیر ہو جاتے ہیں اور چارآدمیوں کا کھا ناآٹھ آدمیوں کو کفایت کر جاتا ہے۔"}],[468,"سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے وفات پاجانے تک مسلسل تین دِن سیر ہو کر نہیں کھایا۔‘‘","صحیح",{"k":"صحیح مسلم (2970)۔"}],[469,"ابوجحیفہ بیان کرتے ہیں کہ:\n’’میں نے روٹی اور گوشت کا ثرید بنا کر کھایا، پھر میں نبی صلی اللہ علیہ وسلم کے پاس آیا اور میں ڈکا مار رہا تھا، تو آپ صلی اللہ علیہ وسلم نے فرمایا:ہمارے سامنے(ڈکار مار نے سے)رُک جا، یافرمایا کہ اپنے ڈکار سے ہمیں دور ہی رکھ، کیونکہ جو تم میں سے دنیا میں بہت زیادہ سیر رہتا ہے وہ روزِقیامت تم سب سے زیادہ طویل مدت تک بھوکا رہے گا۔ اس کے بعد ابوجحیفہؓ نے دنیا سے کُوچ کر جا نے تک کبھی پیٹ بھر کر نہیں کھایا اورجب صبح کا کھانا کھا لیتے تو شام کا نہیں کھاتے تھے اورجب شام کا کھاتے تو صبح کا نہیں کھاتے تھے۔‘‘","صحیح",{"k":"سلسلہ الأحادیث الصحیحہ (343)۔"}],[470,"مقدام رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’آدمی اپنے پیٹ سے بُراکوئی برتن نہیں بھرتا، حالانکہ ابنِ آدم کو تو چند لقمے ہی کافی ہیں جو اس کی کمر کو سیدھا رکھیں، لیکن اگر زیادہ کھانا ضروری ہو تو ایک تہائی کھانا ہو، ایک تہائی پانی اور ایک تہائی سانس لینے کے لیے چھوڑ دے۔‘‘","صحیح",{"k":"سنن ترمذی (2380)، سنن ابن ماجه (3349)، إرواء الغلیل للألبانی (1983)۔","f":"درحقیقت کھانے کا مقصد صرف صحت اوزندگی بحال رکھنا ہوتا ہے، اسی لیے فرمایاکہ اس کے لیے تو چند لقمے ہی کافی ہیں، کیونکہ انسان کی زندگی کا مقصدِاصلی یہ ہے کہ وہ اپنی اس مستعار زندگی کو اس کے حقیقی مالک کی عبودیت وبندگی اور اس کے دِین کی خدمت میں کھپا دے اوراُخروی امتحان کی تیاری کے لیے ملنے والی اس قیمتی مہلت کو فقط ہو ائے نفسانیہ کی تکمیل میں ہی نہ ضائع کردے۔ لیکن اگر زیادہ کھانے کوجی چاہے تو اس کے لیے بھی یہ ضابطہ ملحوظ رکھنا چاہیے کہ اپنے سارے پیٹ کو کھا نے سے ہی نہیں بھر لینا چاہیے، بلکہ اس کے تین حصے کیے جائیں:ایک حصہ کھانے کے لیے، ایک پانی کے لیے اور ایک سانس لینے کے لیے خالی چھوڑ دیا جائے۔"}],[471,"اُبَی بن کعب رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’بلاشبہ انسان کے کھانے کی مثال دنیا کے لیے بہ ایں طور دی گئی ہے کہ وہ انسان سے خارج ہو جاتا ہے، اگرچہ اس نے اسے نمکین ومصالحے دار بنایا ہو لیکن وہ جانتا ہے کہ اس کا انجام کیا ہوگا۔‘‘","حسن",{"k":"مسند أحمد (5؍136)، سلسلہ الأحادیث الصحیحہ (382)۔"}],[472,"وحشی بن حرب اپنے باپ کے واسطے سے اپنے دادا سے روایت کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم کے صحابہؓ نے عرض کیا: اے اللہ کے رسول!ہم کھانا کھاتے ہیں تو سیر نہیں ہوتے۔ آپ صلی اللہ علیہ وسلم نے فرمایا:شاید تم الگ الگ کھاتے ہو؟ صحابہؓ نے جواب دیا:جی ہاں، تو آپ صلی اللہ علیہ وسلم نے فرمایا:سب اکٹھے مل کر کھایا کرو اور اللہ کا نام بھی لیا کرو)یعنی بسم اللہ پڑھ کر کھایا کرو(، تمہارے کھانے میں برکت ڈال دی جائے گی۔‘‘","حسن",{"k":"سنن أبوداؤد (3764)، سنن ابن ماجه (3286)، سلسلہ الأحادیث الصحیحہ (664)۔"}],[473,"ابو شعیب انصاری رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا تو میں نے آپ صلی اللہ علیہ وسلم کے چہرۂ مبارک سے ہی پہچان لیا کہ آپ صلی اللہ علیہ وسلم کو بھوک لگی ہوئی ہے۔ چنانچہ میں اپنے غلام کے پاس آیا جو قصاب تھا، میں نے اسے کہاکہ وہ پانچ آدمیوں کا کھانا تیار کر دے۔ پھر میں نے رسول اللہ صلی اللہ علیہ وسلم کو دعوت دی، (باقی چار لوگوں کے ساتھ)پانچویں آپ صلی اللہ علیہ وسلم تشریف لائے اور ان کے پیچھے ایک اور آدمی آگیا، جب رسول اللہ صلی اللہ علیہ وسلم (ہمارے گھر کے)دروازے کے پاس پہنچے تو آپ صلی اللہ علیہ وسلم نے فرمایا:یہ آدمی ہمارے پیچھے چلا آیا ہے، سواگر تم چاہو تو اسے اجازت دے دو، وگرنہ یہ واپس چلا جائے گا۔ چنانچہ )صاحبِ خانہ نے(اسے بھی اجازت دے دی۔‘‘","صحیح",{"k":"صحیح بخاری (5434)، صحیح مسلم (2036)۔","f":"اس حدیث سے یہ بات احاطۂ علم میں آتی ہے کہ جو لوگ دعوت پر مدعو ہوں صرف وہی کھانے میں شرکت کاحق رکھتے ہیں، اور اگر کوئی بغیر دعوت کے آجائے تو اس کے لیے اجازت لینا ضروری ہے، اگر صاحبِ خانہ اجازت دے گاتو وہ بھی شریک ہوجائے گااور اگر نہیں دے گاتو اسے شرکت کاحق حاصل نہیں ہے بلکہ اسے واپس جانا ہوگا۔"}],[474,"عبداللہ بن بُسربیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم میرے والد کے پاس سے گزرے اور آپ صلی اللہ علیہ وسلم اپنے سفید خچر پر سوار تھے، تو میرے والد آپ صلی اللہ علیہ وسلم کے پاس آئے اور(خچر کی)لگام پکڑ کر عرض کیا:میرے گھر تشریف لائیے، تو آپ صلی اللہ علیہ وسلم تشریف لے آئے۔ میرے والد کھجور اورستُّولائے، آپ صلی اللہ علیہ وسلم انہیں کھانے لگے اور گٹھلیاں انگشتِ شہادت اور درمیانی انگلی کی پُشت پر یاان دونوں پر رکھتے گئے، پھر انہیں پھینک دیا۔ راوی کہتے ہیں کہ پھر آپ صلی اللہ علیہ وسلم کی خدمت میں کھانا پیش کیاگیا، آپ صلی اللہ علیہ وسلم کھانے لگے، پھر دودھ یاستُّوکا پیالہ لایا گیا، آپ صلی اللہ علیہ وسلم نے نوش فرمایا اور اپنے داہنی جانب والے کو دیا، پھرجب آپ صلی اللہ علیہ وسلم جانے لگے تو(میرے والد)نے کہا:ہمارے لیے دعا فرما دیجیے، تو آپ صلی اللہ علیہ وسلم نے یہ دعا فرمائی: «اَللّٰهُمَّ بَارِكْ لَهُمْ فِيمَا رَزَقْتَهُمْ وَاغْفِرْ لَهُمْ وَارْحَمْهُمْ» ’’اے اللہ!جو تو نے انہیں عطا فرمایا ہے اس میں برکت ڈال دے، انہیں بخش دے اور ان پر رحم فرما۔‘‘","صحیح",{"k":"صحیح مسلم (2042)، سنن أبوداؤد (3729)، سنن ترمذی (3576)۔"}],[475,"انس رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم انصار سے ملنے جایا کرتے تھے، جب آپ صلی اللہ علیہ وسلم انصار کے گھروں کے پاس پہنچتے تو انصاری بچے آپ صلی اللہ علیہ وسلم کے پاس آجاتے اور آپ صلی اللہ علیہ وسلم کے اردگرد دچکر لگا نے لگتے۔ آپ صلی اللہ علیہ وسلم ان کے لیے دعا فرماتے، ان کے سرپر ہاتھ پھیرتے اور انہیں سلام کہتے۔ (ایک روز)سعدبن عبادہ کے ہاں تشریف لائے اور انہیں «اَلسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللّٰهِ» کہا، سعدؓنے سلام سنا تو رسول اللہ صلی اللہ علیہ وسلم کو سلام کا جواب دیا لیکن آپ صلی اللہ علیہ وسلم کو اس کا جواب نہ سنا، آپ صلی اللہ علیہ وسلم نے پھر «اَلسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللّٰهِ» کہا، سعدؓنے سُن کر جواب دیا لیکن نبی صلی اللہ علیہ وسلم کو پھر نہ سنا، آپ صلی اللہ علیہ وسلم نے تین مرتبہ سلام کہا، اور نبی صلی اللہ علیہ وسلم تین مرتبہ سے زیادہ سلام نہیں کہا کرتے تھے، سواگر اجازت مل جاتی(تو اندر تشریف لے جاتے)وگرنہ واپس چلے آتے۔ چنانچہ نبی صلی اللہ علیہ وسلم واپس آگئے اور سعد رضی اللہ عنہ دوڑتے ہوئے آئے اور عرض کیا:اے پیغمبرِخدا!اس ذات کی قسم جس نے آپ صلی اللہ علیہ وسلم کوحق دے کر مبعوث فرمایا ہے، آپ صلی اللہ علیہ وسلم نے جو بھی سلام کہا ہے میں نے وہ سنا بھی ہے اور اس کا جواب بھی دیا ہے، (لیکن آہستہ جواب دینے کی وجہ یہ ہے کہ)میں چاہتا تھا کہ آپ صلی اللہ علیہ وسلم مجھے زیادہ سے زیادہ سلامتی اور رحمت کی دعا دیں، اے اللہ کے رسول!تشریف لائیے۔ راوی کہتے ہیں کہ آپ صلی اللہ علیہ وسلم تشریف لے گئے، ہم باتیں کرنے لگ گئے تو سعدؓنے آپ صلی اللہ علیہ وسلم کی خدمت میں کھانا پیش کیا، آپ صلی اللہ علیہ وسلم نے اس سے کچھ کھا لیا، پھرجب آپ صلی اللہ علیہ وسلم نے واپس جانے کا ارادہ کیا تو یہ دعا فرمائی: «أَكَلَ طَعَامَكُمُ الْأَبْرَارُ وَأَفْطَرَ عِنْدَكُمُ الصَّائِمُونَ وَصَلَّتْ عَلَيْكُمُ الْمَلَائِكَةُ» ’’تمہارا کھانا نیک لوگ کھائیں، تمہارے پاس روزے دار افطاری کریں اور فرشتے تمہیں دعائیں دیں۔‘‘","صحیح",{"k":"صحیح بخاری (5177)، صحیح مسلم (1432)۔"}],[476,"ابنِ عمر رضی اللہ عنہما روایت کرتے ہیں کہ:\n’’سیدنا عمر رضی اللہ عنہ نے مسجد کے دروازے کے پاس ایک دھاری دار عمدہ پوشاک فروخت ہوتی دیکھی تو عرض کیا:اے اللہ کے رسول!کیوں نہ آپ صلی اللہ علیہ وسلم اسے خرید لیں اور جمعہ کے دِن اورجس دِن آپ صلی اللہ علیہ وسلم کے پاس وفد آئیں اس دِن پہن لیا کریں، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:اسے تو وہی پہنے گاجس کے لیے آخرت میں کوئی حصہ نہیں ہے۔ پھر رسول اللہ صلی اللہ علیہ وسلم کے پاس اسی طرح کی کچھ پوشا کیں آئیں تو آپ صلی اللہ علیہ وسلم نے ان میں سے ایک پوشاک عمرؓ کو دے دی، تو انہوں نے کہا:اے اللہ کے رسول!آپ صلی اللہ علیہ وسلم یہ مجھے پہننے کے لیے دے رہے ہیں حالانکہ آپ صلی اللہ علیہ وسلم تو اس کے متعلق یہ فرما چکے ہیں جو آپ صلی اللہ علیہ وسلم نے فرمایا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:میں یہ تمہیں اس لیے نہیں دے رہا کہ اسے تُوپہن لے، بلکہ میں تو اس لیے دے رہا ہوں تاکہ تُواسے فروخت کردے یاا سے کسی کو پہنا دے۔ تو عمر رضی اللہ عنہ نے وہ پوشاک اپنے ایک مشرک علاتی بھائی کو پہنا دی، جو مکہ میں رہتا تھا۔‘‘","صحیح",{"k":"صحیح بخاری (5841)، صحیح مسلم (2068)۔"}],[477,"سیدنا علی رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم کو ایک دھاری دار عمدہ پوشاک تحفہ دی گئے، آپ صلی اللہ علیہ وسلم نے وہ مجھے بھیج دی، میں وہ پہن کر نکلا تو آپ صلی اللہ علیہ وسلم نے مجھے یوں دیکھا کہ جیسے آپ صلی اللہ علیہ وسلم نے اسے ناپسند کیا ہے، پھر آپ صلی اللہ علیہ وسلم نے فرمایا:میں نے یہ تمہیں اس لیے نہیں دی تھی کہ اسے تُوپہن لے۔ چنانچہ آپ صلی اللہ علیہ وسلم نے مجھے حکم فرمایا تو میں نے اسے اپنی عورتوں میں تقسیم کردیا۔‘‘","صحیح",{"k":"صحیح بخاری (2614)، صحیح مسلم (2071)۔","f":"دیگر روایات میں اس کی وضاحت ملتی ہے کہ وہ پوشاک ریشم کی تھی اور ریشم چونکہ مردوں کے لیے جائز نہیں ہے، اس لیے آپ صلی اللہ علیہ وسلم نے اس پر ناپسندیدگی کا اظہار اور اتار دینے کاحکم فرمایا۔"}],[478,"شعبہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’جو شخص دنیا میں ریشم پہنے گاوہ اسے آخرت میں نہیں پہن سکے گا۔‘‘","صحیح",{"k":"صحیح بخاری (5832)، صحیح مسلم (2073)۔"}],[479,"ابنِ ابی لیلٰی بیان کرتے ہیں کہ:\n’’حذیفہ رضی اللہ عنہ نے پانی مانگا تو ایک دہقان چاندی کے برتن میں پانے لے آیا، آپؓ نے اسے پکڑ کر پھینک دیا اور فرمایا:یقیناًرسول اللہ صلی اللہ علیہ وسلم نے ہمیں سونے اور چاندی کے برتنوں میں پینے، ان میں کھانے اور موٹے وبا ریک ریشم پر بیٹھنے سے منع فرمایا ہے، اور آپ صلی اللہ علیہ وسلم نے کا فرمان ہے کہ یہ(سب کچھ)ان کے لیے دنیا میں ہے اور تمہارے لیے آخرت میں۔‘‘\n’’ان کے لیے دنیا میں ہے‘‘ سے مراد کافروں اور ان لوگوں کے لیے جوان کی حرمت کا علم ہونے کے باوجود انہیں استعمال کرتے ہیں، اور ایسے لوگوں کو آخرت میں ان تمام چیزوں سے محروم رکھا جائے گاجبکہ مومنین کو وہاں یہ سب بہ طورِانعام وتکریم پیش کی جائیں گی۔","صحیح",{"k":"صحیح بخاری (5831)، صحیح مسلم (2967)۔"}],[480,"عقبہ بن عامر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’ریشم اور سونا میری اُمت کے مردوں پر حرام ہے اور ان کی عورتوں کے لیے حلال ہے۔‘‘","صحیح",{"k":"السنن الکبری للبیهقی (3؍275)، سلسلہ الأحادیث الصحیحہ (1865)۔"}],[481,"سویدبن غفلہ بیان کرتے ہیں کہ:\n’’عمربن خطاب رضی اللہ عنہ نے جابیہ کے مقام پہ خطبہ دیا اور فرمایا:رسول اللہ صلی اللہ علیہ وسلم نے ریشم پہننے سے منع فرمایا ہے، سوائے دو، تین یاچار انگلیوں کی جگہ کے بہ قدر۔‘‘","صحیح",{"k":"صحیح مسلم (2069)۔"}],[482,"ابنِ عباس رضی اللہ عنہما فرماتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم نے خالص ریشم کا کپڑا پہننے سے منع فرمایا، البتہ ریشم کی کڑھائی اور کپڑے کا تانا ریشمی ہونے میں کوئی حرج نہیں ہے۔‘‘","صحیح دون قوله فأما العلم...",{"k":"سنن أبوداؤد (4055)۔","f":"اس حدیث میں ’’ریشم کی کڑھائی‘‘کے الفاظ ضعیف ہیں، اس کے علاوہ دونوں حکم صحیح ہیں، یعنی خالص ریشم کی ممانعت اور ریشمی تانے والے کپڑے کی رخصت۔"}],[483,"انس بن مالک رضی اللہ عنہ روایت کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے عبدالرحمان بن عوف کو ان کے جسم پر خارش ہوجانے کی وجہ سے ریشم کا قمیض پہننے کی رخصت دی تھی۔‘‘","صحیح",{"k":"صحیح بخاری (5839)، صحیح مسلم (2076)۔"}],[484,"عطاء کے داماد ابو عمر بیان کرتے ہیں کہ:\n’’میں نے اسماء بنت ابی بکر رضی اللہ عنہا کے پاس ایک جُبّہ (چوغہ) دیکھاجس پر موٹے ریشم کے بٹن لگائے گئے تھے، انہوں نے بتلایا کہ رسول اللہ صلی اللہ علیہ وسلم جنگ کے موقع پر اسے پہنا کرتے تھے۔‘‘","",{"k":"السنن الکبری للبیهقی (3؍268)۔","f":"یعنی یہ دو اضطراری صورتیں ہیں جنہیں ریشم کے عام حکم سے مستثنیٰ قرار دیا گیا ہے اور دور انِ جنگ یابہ صورتِ خارش ریشمی لباس پہننے کی رخصت دی گئی ہے۔"}],[485,"انس بن مالک رضی اللہ عنہ روایت کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم نے مرد کو زعفرانی رنگ استعمال کرنے سے منع فرمایا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (5846)، صحیح مسلم (2101)۔"}],[486,"عبداللہ بن عمرو رضی اللہ عنہما بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے مجھ پر دو زرد رنگ کے کپڑے دیکھے تو فرمایا: یہ جہنّمیوں کے کپڑے ہیں، تم یہ مت پہنو۔‘‘","صحیح",{"k":"صحیح مسلم (2077)، مسند أحمد (2؍193)۔","f":"یہ دونوں چونکہ نسوانی رنگ ہیں اور ایسے کپڑے پہننے سے عورتوں کی مشابہت لازم آتی ہے اس لیے آپ صلی اللہ علیہ وسلم نے ان سے منع فرمایا۔"}],[487,"ابنِ عمر رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جس نے دنیا میں شہرت کا لباس پہنا اللہ تعالیٰ اسے روزِقیامت ذِلّت کا لباس پہنائے گا۔ اور عثمان بن ابی زرعہ کی روایت میں یہ اضافہ ہے: پھر اس میں آگ بھڑ کے گی۔‘‘","حسن",{"k":"سنن أبوداؤد (4029)، سنن ابن ماجه (3606)، صحیح الجامع للألبانی (6526)۔"}],[488,"جابربن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم بغرضِ ملاقات ہمارے گھر تشریف لائے تو آپ صلی اللہ علیہ وسلم نے ایک پراگندہ بالوں والے شخص کو دیکھا تو فرمایا:کیا اسے ایسی کوئی چیز نہیں ملی جس سے یہ اپنے بال سنوار لے؟ اور آپ صلی اللہ علیہ وسلم نے ایک شخص کو میلے کچیلے کپڑے پہنے دیکھا تو فرمایا:کیا اسے ایسی کوئی چیز نہیں ملتی جس سے یہ اپنے کپڑے دھو لے؟‘‘","صحیح",{"k":"سنن أبوداؤد (4062)، سنن نسائی (5236)۔"}],[489,"عبداللہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’جس شخص کے دِل میں ذرہ برابر بھی تکبر ہوگا وہ جنّت میں نہیں جائے گااو رجس کے دِل میں ذرہ برابر بھی ایمان ہوگا وہ جہنم میں نہیں جائے گا۔ ایک آدمی نے عرض کیا:اے اللہ کے رسول!آدمی اس بات کو پسند کرتا ہے کہ اس کے کپڑے اور اس کا جوتا اچھے ہوں(تو کیا یہ بھی تکبر ہے)؟ تو رسول اللہ صلی اللہ علیہ وسلم فرمایا:یقیناًاللہ تعالٰی خوبصورت ہے)اور(خوبصورتی کو پسند فرماتا ہے، تکبر یہ ہے کہ آدمی حق کو ٹھکرائے اور لوگوں کو حقیر جا نے۔‘‘","صحیح",{"k":"صحیح مسلم (91)، سنن ترمذی (1999)۔","f":"یعنی صاف ستھرا لباس پہننا، عمدہ جوتا پہننا اور نفاست سے رہنا تکبر میں شمار نہیں ہوتا، کیونکہ تکبر سے مراد تو یہ ہے کہ آدمی حق بات کو قبول کرنے سے انکار کرے اور لوگوں کو اپنے سے کم مرتبہ سمجھے اور ان کے ساتھ حقارت آمیز رویہ اپنائے۔"}],[490,"ابو احوص اپنے باپ سے روایت کرتے ہیں کہ انہوں نے بیان کیا:\n’’نبی صلی اللہ علیہ وسلم نے مجھے پرانے کپڑے پہنے دیکھا تو فرمایا:کیا تمہارے پاس مال ہے؟ میں نے عرض کیا:جی ہاں، آپ صلی اللہ علیہ وسلم نے فرمایا:جس طرح اللہ تعالٰی نے تجھ پر انعام فرمایا ہے اسی طرح تو بھی اپنی جان پر انعام کر۔‘‘","صحیح",{"k":"سنن أبوداؤد (4063)، سنن نسائی (5294)۔","f":"یعنی اگر اللہ تعالیٰ نے تجھے مال و دولت کی نعمت سے نوازا ہے تو نئے کپڑے خرید کر پہن۔"}],[491,"عمروبن شعیب اپنے باپ کے واسطے سے اپنے دادا سے روایت کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’کھاؤ، پیو، صدقہ وخیرات کرو اور ایسا لباس پہنو جو بڑائی اور فضول خرچی والا نہ ہو، کیونکہ اللہ سبحانہ وتعالیٰ پسند فرماتا ہے کہ وہ اپنے بندے پر اپنی عطا کی ہوئی نعمت کے اثرات دیکھیں۔‘‘","حسن",{"k":"سنن ابن ماجه (3605)۔"}],[492,"معاذبن انس جہنی رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جو استطاعت کے باوجود فقط اللہ تعالیٰ کی رضا کی خاطر عاجزی دکھاتے ہوئے (قیمتی)لباس پہننا چھوڑ دے، اللہ تعالیٰ اسے تمام مخلوقات کے سامنے بلائے گااور اسے یہ اختیار دیا جائے گاکہ وہ ایمانی جُبّوں(چوغوں)میں سے جو چاہے پہن لے۔‘‘","حسن",{"k":"سنن ترمذی (2481)، مستدرک حاکم (4؍183)، سلسلہ الأحادیث الصحیحہ (718)۔","f":"ایمانی جبوں سے مراد وہ جبے ہیں جو اللہ تعالیٰ نے اہل ایمان کے لیے جنت میں تیار کر رکھے ہیں۔"}],[493,"سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم ایک صبح باہر تشریف لائے اور آپ صلی اللہ علیہ وسلم کے جسم مبارک پر بالوں سے بنی سیاہ رنگ کی چادر تھی جس پر کجاووں جیسے نقش ونگار تھے۔‘‘","صحیح",{"k":"صحیح مسلم (2081)، سنن أبوداؤد (4032)، سنن ترمذی (2813)۔"}],[494,"مغیرہ بن شعبہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے بیان کرتے ہیں کہ:\n’’آپ صلی اللہ علیہ وسلم نے اُون کارُومی جُبّہ (چوغہ)زیب تن کیے ہوئے تھے۔ ایک اور روایت میں ہے کہ تنگ آستینوں والا شامی جُبّہ تھا۔‘‘","صحیح",{"k":"صحیح بخاری (363)، صحیح مسلم (274)۔","f":"یعنی آپ صلی اللہ علیہ وسلم دو جہانوں کے سردار ہو نے کے باوجود لباس میں انتہائی تواضع اختیار فرماتے تھے۔"}],[495,"سیدنا عبداللہ بن قیس اشعری رضی اللہ عنہ نے (اپنے بیٹے سے)فرمایا:\n’’اے میرے بیٹے!کاش!تو ہمیں اس وقت دیکھتاجس وقت ہم نبی صلی اللہ علیہ وسلم کے ساتھ ہوتے تھے اورجب آسمان بارش برساتا تواُون کے کپڑوں کی وجہ سے تُوہم سے (آنے والی)بُوکو بھیڑوں کی بُوسمجھتا۔‘‘","صحیح",{"k":"سنن أبوداؤد (4033)، سنن ترمذی (2479)، سنن ابن ماجه (3562)۔","f":"یعنی تب کسی کے پاس عمدہ لباس موجود نہ ہوتا تھا، بلکہ اُون کے کپڑے پہنا کرتے تھے۔ ایسا اس لیے تھا کیونکہ ان کے ہاں ان چیزوں کی کوئی اہمیت نہ تھی، بلکہ ان کی نظر میں اہم کام نیکی اور تقویٰ کے امور میں کمال حاصل کرنا تھا۔"}],[496,"ابوبردہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’سیدہ عائشہ رضی اللہ عنہا نے ہمیں ایک پیوند لگی ہوئی چادر اور موٹے کپڑے کا تہہ بند دکھایا، اور فرمایا:رسول اللہ صلی اللہ علیہ وسلم کی رُوح انہی دو کپڑوں میں قبض ہوئی تھی۔‘‘","صحیح",{"k":"صحیح بخاری (5818)، صحیح مسلم (2080)۔"}],[497,"عقبہ بن عبد سلمی رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’میں نے رسول اللہ صلی اللہ علیہ وسلم سے پہننے کے لیے کپڑے مانگے تو آپ صلی اللہ علیہ وسلم نے مجھے معمولی ٹسر سے بنے ہوئے دو کپڑے دیے، پھر میں نے وہ پہن کر خود کو دیکھا تو میں اپنے ساتھیوں کی نسبت اچھے کپڑوں والا تھا۔‘‘","صحیح",{"k":"سنن أبوداؤد (4032)۔","f":"یعنی تب صحابہ کرام رضی اللہ عنہم کا یہ عالم تھا کہ حضرت عقبہؓ معمولی ٹسر سے بنے ہوئے کپڑے پہن کر بھی خود کو دیگر صحابہؓ سے اچھے کپڑوں والا سمجھ رہے تھے، تو باقی صحابہؓکے کپڑوں کی کیا حالت ہوگی؟ لیکن زہد وتو اضع تھا کہ انہوں نے کبھی دنیوی امور زینت کو اتنی اہمیت نہیں دی۔"}],[498,"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم کو جو کپڑاسب سے زیادہ پسند تھا وہ دھاری دار یمنی چادر تھی۔‘‘","صحیح",{"k":"صحیح بخاری (5812)، صحیح مسلم (2079)۔"}],[499,"اُمِ سلمہ رضی اللہ عنہا فرماتی ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم کو قمیض سے بڑھ کر کوئی کپڑا پسند نہیں تھا۔‘‘","صحیح",{"k":"سنن أبوداؤد (4026)۔"}],[500,"ابوجحیفہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’ایک مرتبہ رسول اللہ صلی اللہ علیہ وسلم سُرخ رنگ کی عمدہ پوشاک پہن کر تشریف لائے۔ چوغہ تہہ بند اور چادر پر مشتمل تھا اور اس میں ریشم کا استعمال نہیں کیا گیا تھا۔‘‘","صحیح",{"k":"صحیح بخاری (3551)، صحیح مسلم (2337)۔"}],[501,"ابورمثہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’میں نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا تو میں نے آپ صلی اللہ علیہ وسلم کو دو سبز چادریں پہنے دیکھا۔‘‘","صحیح",{"k":"سنن أبوداؤد (4065)، سنن ترمذی (2812)۔"}],[502,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’میں نبی صلی اللہ علیہ وسلم کے ساتھ چلا جا رہا تھا اور آپ صلی اللہ علیہ وسلم نے موٹے کناروں والی چادر اوڑھ رکھی تھی۔‘‘","صحیح",{"k":"صحیح بخاری (5809)۔"}],[503,"سیدنا ابنِ عباس رضی اللہ عنہما بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’سفید کپڑے پہنا کرو اور اپنے فوت شدگان کو کفن بھی انہی میں دیا کرو، اور تمہارے سب سُرموں سے بہترین سُرمہ اِثمد ہے، کیونکہ یہ نظر تیز کرتا ہے اور بال اُگاتا ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (3878)، سنن ترمذی (994)، صحیح الجامع للألبانی (1236)۔"}],[504,"سمرہ بن جندب رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’سفید کپڑے پہنا کرو، کیونکہ یہ بہت اچھے اور انتہائی پاکیزہ ہوتے ہیں، اور اپنے فوت شدگان کو کفن بھی انہی میں دیا کرو۔‘‘","صحیح",{"k":"سنن ترمذی (2810)، سنن ابن ماجه (3567)، صحیح الجامع للألبانی (1235)۔"}],[505,"قرہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’میں مزینہ قبیلے کی ایک جماعت کے ساتھ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور ہم نے آپ صلی اللہ علیہ وسلم سے بیعت کی، اور آپ صلی اللہ علیہ وسلم کا قمیض کھلا تھا(یعنی قمیض کے بٹن کھلے ہوئے تھے)۔ کہتے ہیں کہ میں نے آپ صلی اللہ علیہ وسلم سے بیعت کی، پھر اپنا ہاتھ آپ صلی اللہ علیہ وسلم کی قمیض کے گریبان میں ڈالا تو میں نے انڈے کی مثل یا(کہا)طشت میں پڑی انگوٹھی کی مثل مہرِنبوّت کو چھوا۔ عروہ کہتے ہیں کہ پھر میں نے معاویہ اور ان کے باپ سردی وگرمی میں بٹن کھلے رکھے ہی دیکھا اور وہ انہیں کبھی بند نہیں کرتے تھے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4082)، سنن ابن ماجه (3578)، صحیح الترغیب والترهیب (42)۔","f":"لیکن اگر تکبر کے اظہار یا شوخ پن کے طور پر قمیض کے بٹن کھلے رکھے جائیں تو پھر یہ جائز نہیں ہے۔"}],[506,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’ایک شخص عمدہ پوشاک پہنے اور بالوں میں کنگھی کیے خودپسندی میں منہمک جا رہا تھا کہ اللہ تعالٰی نے اس وجہ سے اسے زمین میں دھنسا دیا اور وہ قیامت کے دِن تک دھنستا ہی چلا جائے گا۔‘‘","صحیح",{"k":"صحیح بخاری (5789)، صحیح مسلم (2088)۔"}],[507,"ابوذر رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’تین لوگ ایسے ہیں جن کی طرف روزِقیامت اللہ تعالٰی نہ تو نظرِرحمت فرمائے گااور نہ ہی انہیں پاک کرے گابلکہ ان کے لیے دردناک عذاب ہوگا:ٹخنوں سے نیچے تہہ بند لٹکا نے والا، احسان کرکے جتلا نے والا اور اپنا سامان جھوٹی قسم کے ذریعے بیچنے والا۔‘‘","صحیح",{"k":"صحیح مسلم (907)۔"}],[508,"عبدالرحمان بیان کرتے ہیں کہ:\n’’میں نے ابو سعید خدری رضی اللہ عنہ سے پوچھا کہ کیا آپ نے رسول اللہ صلی اللہ علیہ وسلم کو تہہ بند کے بارے میں کچھ فرماتے سنا ہے؟ تو انہوں نے جواب دیا:جی ہاں، میں نے آپ صلی اللہ علیہ وسلم کو فرماتے سنا کہ مومن کا تہہ بند اس کی آدھی پنڈلیوں تک(اوپر ہونا چاہیے)اس جگہ اور ٹخنوں کے درمیان رکھنے میں بھی کوئی گناہ نہیں ہے، البتہ تہہ بند کا جو حصہ ٹخنوں سے نیچے ہو وہ آگ میں جلے گا، اللہ تعالیٰ اس شخص کی طرف (نظرِرحمت سے) نہیں دیکھے گاجو اپنے کپڑے کو تکبّرسے گھسیٹتے ہوئے چلتا ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4093)، سنن ابن ماجه (3573)، صحیح الجامع للألبانی (921)۔"}],[509,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’تہہ بند کا جو حصہ ٹخنوں سے نیچے ہوگا وہ (جہنّم کی)آگ میں جلے گا۔‘‘","صحیح",{"k":"صحیح بخاری (5787)، مسند أحمد (2؍55)۔"}],[510,"سیدہ اُمِ سلمہ رضی اللہ عنہا نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کیا-جبکہ آپ صلی اللہ علیہ وسلم نے تہہ بند کا ذکر فرمایا-:\n’’اے اللہ کے رسول!عورت(اپنا تہہ بند کہاں رکھے)؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:وہ ایک بالشت (ٹخنوں سے نیچے)لٹکائے۔ اُمِ سلمہؓ نے عرض کیا:تب تو اس کے (پاؤں)بے پردہ ہوجائیں گے، تو آپ صلی اللہ علیہ وسلم نے فرمایا:تو ایک ہاتھ (تک لٹکا لے اور)اس سے زیادہ نہ لٹکائے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4117)، مسند أحمد (6؍293)۔"}],[511,"ابنِ عمر رضی اللہ عنہما بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے جو(حکم) تہہ بند کے بارے میں فرمایا ہے وہی قمیض کے متعلق ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4095)۔","f":"یعنی صرف تہہ بند کو ہی ٹخنوں سے نیچے لٹکانا حرام نہیں ہے بلکہ اگر کوئی شخص اتنی لمبی قمیض پہنتا ہے کہ وہ بھی ٹخنوں سے نیچے تک پہنچتی ہے تو وہ بھی حرام ہے اور اس پر بھی اس وعید کا اطلاق ہوگا جو تہہ بند کو لٹکانے پر وارد ہوئی ہے۔"}],[512,"سیدنا عبداللہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جس نے بہ غرضِ تکبر اپنا کپڑا(ٹخنوں سے نیچے)لٹکایا روزِقیامت اللہ تعالٰی اس کی طرف (نظرِرحمت سے)نہیں دیکھے گا۔ ابوبکر صدیق رضی اللہ عنہ نے عرض کیا:اے اللہ کے رسول!میرے تہہ بند کے دونوں کناروں میں سے ایک کنارہ ڈھلک جاتا ہے، سوائے اس صورت کے کہ میں اس کا خاص طور پر خیال رکھا کروں)تو میرے بارے میں کیا حکم ہے؟(تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:تم ان لوگوں میں سے نہیں ہو جو تکبر کی وجہ سے ایسا کرتے ہیں۔‘‘","صحیح",{"k":"صحیح بخاری (5784)، صحیح مسلم (2085)۔","f":"سیدنا ابوبکرؓ کا جسم فربہ تھا، اس لیے آپ کا تہہ بند نیچے لٹک جاتا تھا۔ تو اس حدیث میں بیان نبی صلی اللہ علیہ وسلم کے حکم سے یہ بات احاطہ علم میں آتی ہے کہ اگر موٹاپے یا کسی اور عذر کی وجہ سے تہہ بند ڈھلک کر ٹخنوں سے نیچے آجاتا ہے تو یہ صورت متذکرہ بالا وعید سے مستثنیٰ ہے، بشرطیکہ ایسے شخص میں بھی تکبر کا شائبہ تک موجود نہ ہو۔"}],[513,"سویدبن قیس بیان کرتے ہیں کہ:\n’’میں اور مخرمہ عبدی ہجریا بحرین شہر سے کپڑا لائے، جب ہم منیٰ میں تھے تو ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوئے تو آپ صلی اللہ علیہ وسلم نے ہم سے ایک شلوار خریدی، راوی کہتے ہیں کہ وہاں ایک وزن کرنے والا تھا جو اجرت لے کر وزن کرتا تھا، تو رسول اللہ صلی اللہ علیہ وسلم نے اسے قیمت ادا کی اور اسے فرمایا:وزن کر اور جھکا۔‘‘","صحیح",{"k":"سنن أبوداؤد (3336)، سنن ترمذی (1305)، سنن نسائی (2220)۔","f":"اس روایت میں شلوار کے ذکر کے علاوہ اس بات کا بھی بیان ہے کہ ماپ تول والی چیز بیچتے ہوئے اس چیز والے پلڑے میں تھوڑا زیادہ ڈال دینا چاہیے۔ اگرچہ بالکل پورا پورا نہیں دینا بھی جائز ہے لیکن نبی صلی اللہ علیہ وسلم کی کامل اتباع کا تقاضا یہی ہے کہ آپ کے اس فرمان پر بھی عمل کیا جائے۔"}],[514,"عمروبن حریث رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’میں نے رسول اللہ صلی اللہ علیہ وسلم کو منبر پر جلوہ افروز دیکھا اور آپ صلی اللہ علیہ وسلم نے سیاہ عمامہ(پگڑی)پہنا ہوا تھا اور اس کے دونوں کناروں کو اپنے کندھوں پر لٹکایا ہوا تھا۔‘‘","صحیح",{"k":"صحیح مسلم (1359)، سنن أبوداؤد (4077)، سنن نسائی (5346)، سنن ابن ماجه (2821)۔"}],[515,"جابر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے نبی صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’زیادہ سے زیادہ )وقت(جوتے پہنے ہوئے رہا کرو، کیونکہ آدمی جب تک جوتا پہنے ہوئے ہوتاہے تب تک وہ سوار ہوتا ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2096)، سنن أبوداؤد (4133)۔"}],[516,"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم کے جوتے کی دو پٹیاں تھیں۔‘‘","صحیح",{"k":"صحیح بخاری (5857)، سنن أبوداؤد (4134)۔"}],[517,"ابنِ عباس رضی اللہ عنہما بیان کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم کے جوتے کی دو پٹیاں تھیں جن کے تسمے دو ہرے تھے۔‘‘","صحیح",{"k":"سنن ابن ماجه (3614)۔"}],[518,"جابر رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا ہے کہ آدمی کھڑا ہو کر جوتا پہنے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4135)، سلسلہ الأحادیث الصحیحہ (719)۔"}],[519,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’تم میں سے کوئی بھی ایک جوتا پہن کر نہ چلے، بلکہ دونوں پہننے چاہییں۔‘‘","صحیح",{"k":"صحیح بخاری (5856)، صحیح مسلم (2097)۔"}],[520,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب تم میں سے کوئی جوتا پہنے تو اسے دائیں طرف سے شروع کرنا چاہیے اورجب اتارے تو پہلے بایاں جوتا اتارنا چاہیے، تاکہ دایاں جوتا پہننے میں پہلا ہو اور اتار نے میں آخری ہو۔‘‘","صحیح",{"k":"صحیح بخاری (5855)، صحیح مسلم (2097)۔"}],[521,"انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم اپنے جوتوں میں ہی نماز پڑھ لیا کرتے تھے۔‘‘","صحیح",{"k":"صحیح بخاری (5850)، صحیح مسلم (555)۔"}],[522,"شدادبن اوس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’یہودیوں کی مخالفت کرو، کیونکہ وہ اپنے جوتوں اور موزوں میں نماز نہیں پڑھتے۔‘‘","صحیح",{"k":"سنن أبوداؤد (652)، مستدرک حاکم (1؍26)، صحیح الجامع للألبانی (3210)۔"}],[523,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب تم میں سے کوئی نماز پڑھے اور اپنے جوتے اتار دے تو ان کی وجہ سے کسی کو تکلیف نہ دے، بلکہ اسے چاہیے کہ وہ انہیں اپنے سامنے رکھ لے یاپھر انہی میں نماز پڑھ لینی چاہیے۔‘‘","صحیح",{"k":"سنن أبوداؤد (655)، صحیح الجامع للألبانی (643)۔"}],[524,"ابوہریرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب تم میں سے کوئی نماز پڑھے تو وہ اپنے دائیں جانب جوتا نہ رکھے اور نہ ہی بائیں جانب کیونکہ وہ کسی اور کی دائیں جانب ہوگی، سوائے اس کے کہ اس کی بائیں جانب میں کوئی نہ ہو، (یاپھر)انہیں اپنے دونوں پاؤں کے درمیان میں رکھ لینا چاہیے۔‘‘","صحیح",{"k":"سنن أبوداؤد (654)، صحیح الجامع للألبانی (645)۔"}],[525,"بریدہ روایت کرتے ہیں کہ:\n’’نجاشی نے رسول اللہ صلی اللہ علیہ وسلم کو دو سادہ سیاہ موزے بہ طورِتحفہ بھیجے، آپ صلی اللہ علیہ وسلم نے وضوء کیا تو ان پر مسح فرمایا۔‘‘","حسن",{"k":"سنن أبوداؤد (155)، سنن ترمذی (2820)، سنن ابن ماجه (549)۔"}],[526,"معاذ بن انس رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جو شخص کھانا کھا نے کے بعد یہ دعا پڑھے: «اَلْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هٰذَا الطَّعَامَ وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ» ’’تمام تعریفیں اس اللہ کے لیے ہیں جس نے مجھے یہ کھانا کھلایا اور بغیر میری محنت وکوشش کے مجھے یہ عطا فرمایا۔‘‘ تو اس کے گزشتہ تمام گناہ بخش دیے جاتے ہیں، اور جو(نیا)لباس پہنے اور یہ دعا پڑھے: «اَلْحَمْدُ لِلَّهِ الَّذِي كَسَانِي هٰذَا وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ» ’’تمام تعریفیں اس اللہ کے لیے ہیں جس نے مجھے یہ پہنایا اور بغیر میری محنت وکوشش کے مجھے یہ عنایت فرمایا۔‘‘ تو اس کے اگلے بھی اور پچھلے بھی سب گناہ معاف کر دیے جاتے ہیں۔‘‘","حسن",{"k":"سنن أبوداؤد (4023)، سنن ترمذی (3458)، سنن ابن ماجه (3285)، صحیح الجامع للألبانی (6086)۔","f":"ان گناہوں سے مراد صغیرہ گناہ ہیں، کبیرہ گناہ توبۂ نصوح کے بغیر معاف نہیں ہوتے۔"}],[527,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم کا بستر مبارک چمڑے کا تھا اور اس میں کھجور کی چھال بھری ہوئی تھی۔‘‘","صحیح",{"k":"صحیح بخاری (6456)، صحیح مسلم (2082)۔"}],[528,"جابربن عبداللہ انصاری رضی اللہ عنہ روایت کرتے ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’ایک بستر آدمی کے لیے، دوسرا اس کی بیوی کے لیے، تیسرا مہمان کے لیے اور چوتھا شیطان کے لیے ہوتاہے۔‘‘","صحیح",{"k":"صحیح مسلم (4208)، سنن أبوداؤد (4142)۔","f":"اس حدیث میں گھر میں ضرورت سے زائد بستر رکھنے کی مذمت بیان ہوئی ہے۔"}],[529,"سیدہ میمونہ رضی اللہ عنہا بیان کرتی ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم کھجور کے پتوں سے بنی ہوئی چٹائی پر نماز پڑھا کرتے تھے۔‘‘","صحیح",{"k":"صحیح بخاری (381)۔"}],[530,"انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم دوپہر کے وقت اُمِ سُلیم رضی اللہ عنہا کے ہاں آرام فرمایا کرتے تھے، وہ آپ صلی اللہ علیہ وسلم کے لیے چمڑے کا فرش(یعنی کوئی بچھونا وغیرہ)لگا دیتیں اور آپ صلی اللہ علیہ وسلم کا پسینۂ معطر لے کر اسے اپنی خوشبو میں ڈال لیتیں اور آپ صلی اللہ علیہ وسلم کے لیے کھجور کے پتوں سے بنی ہوئی چٹائی بچھا دیتیں تو آپ صلی اللہ علیہ وسلم اس پر نماز پڑھ لیتے۔‘‘","صحیح",{"k":"صحیح بخاری (6281)، صحیح مسلم (2332)۔"}],[531,"جابربن عبداللہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’عنقریب تمہیں جھالردار چادریں بھی میسر ہوں گی۔‘‘","صحیح",{"k":"صحیح بخاری (5161)، صحیح مسلم (2083)۔","f":"نمط جھالروں والی اس چادر کو کہتے ہیں جو بستر کے اوپر بچھائی جاتی ہے، اس فرمان سے اخذ شدہ مسئلہ یہ ہے کہ بستر وغیرہ کے اوپر بستر کی صفائی یاخوبصورتی کے لیے کوئی چادر وغیرہ ڈال دینا ممنوع نہیں ہے۔ بلکہ اس فرمان کا سباق یہ ہے کہ حضرت جابرؓ کی شادی کے موقع پر رسول اللہ صلی اللہ علیہ وسلم نے ان سے دریافت فرمایاکہ کیا تم نے جھالردار چادریں بھی لی ہیں؟ تو انہوں نے عرض کیاکہ ہمارے پاس یہ کہاں سے آسکتی ہیں، یعنی حالات کی تنگی کے باعث ہم یہ نہیں خرید سکتے، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:کہ یہ جلد ہی تمہیں میسر ہوں گی۔ آپ صلی اللہ علیہ وسلم کے اس فرمان کا مطلب یہ تھا کہ تمہاری یہ تنگدستی بہت جلد ختم ہوجائے گی اور مستقبل میں تم کشادہ حال ہوجاؤ گے تو یہ خرید سکوگے۔"}],[532,"جابربن سمرہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’ماعز کو رسول اللہ صلی اللہ علیہ وسلم کے پاس لایا گیا، اور آپ صلی اللہ علیہ وسلم اپنے بائیں طرف تکیے پر ٹیک لگائے ہوئے تھے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4143)، سنن ترمذی (2770)۔"}],[533,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف لائے تو میں نے ایک نقش ونگار والا پردہ لٹکایا ہوا تھاجس میں تصویریں تھیں، جب آپ صلی اللہ علیہ وسلم نے اسے دیکھا تو آپ صلی اللہ علیہ وسلم کے چہرۂ مبارک کا رنگ متغیر ہو گیا اور آپ صلی اللہ علیہ وسلم نے اپنے ہاتھ سے اسے کھینچ کر پھینک دیا اور فرمایا:روزِقیامت سب سے شدید عذاب ان لوگوں کو ہوگا جو اللہ کی مخلوق کے مشابہ (تصویریں)بناتے ہیں۔‘‘","صحیح",{"k":"صحیح بخاری (5954)، صحیح مسلم (2107)۔"}],[534,"طلحہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’فرشتے اس گھر میں داخل نہیں ہوتے جس گھر میں کتا اور تصویر ہو۔‘‘","صحیح",{"k":"صحیح بخاری (5949)، صحیح مسلم (2106)۔"}],[535,"ابوطلحہ انصاری رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’فرشتے اس گھر میں داخل نہیں ہوتے جس میں کتا اور تصویریں ہوں۔ راوی کہتے ہیں کہ میں سیدہ عائشہ رضی اللہ عنہا کے پاس آیا اور میں نے ان سے پوچھا کہ نبی صلی اللہ علیہ وسلم کا یہ جو فرمان ہے کہ فرشتے اس گھر میں داخل نہیں ہوتے جس میں کتا اور تصویریں ہوں، کیا آپؓ نے رسول اللہ صلی اللہ علیہ وسلم کو یہ بات بیان کرتے سنا ہے؟ تو انہوں نے جواب دیا:نہیں، لیکن میں تمہیں وہ بتاتی ہوں جو میں نے دیکھا ہے، پھر فرمایا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ صلی اللہ علیہ وسلم کسی غزوے میں(شرکت کرنے کے لیے)روانہ ہوئے اور میں نے جھالروں والا رنگین کپڑا لیا اور اسے دروازے پر(بہ طورِپردہ)لٹکا دیا، جب آپ صلی اللہ علیہ وسلم واپس تشریف لائے اور اس پردے کو دیکھا تو میں نے آپ صلی اللہ علیہ وسلم کے چہرۂ مبارک پر ناپسندیدگی کے تأثرات پہچان لیے، آپ صلی اللہ علیہ وسلم نے اسے کھینچا اور اس کے ٹکڑے ٹکڑے کر دیے اور فرمایا:یقیناًاللہ تعالٰی نے ہمیں یہ حکم نہیں دیا کہ ہم پتھروں اور مٹی کو کپڑے پہنا نے لگ جائیں۔ حضرت عائشہؓ فرماتی ہیں کہ میں نے اس سے دو تکیے بنا لیے اور انہیں کھجور کے درخت کے ریشوں سے بھر دیا، لیکن آپ صلی اللہ علیہ وسلم نے اس بات پر مجھے کچھ نہیں کہا۔‘‘","صحیح",{"k":"صحیح مسلم (2107)۔"}],[536,"ابوطلحہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’اس گھر میں فرشتے داخل نہیں ہوتے جس گھر میں تصویریں ہوں۔ بُسربیان کرتے ہیں کہ زیدؓبیمار ہو گئے تو ہم ان کی عیادت کے لیے گئے، ان کے گھر میں ایک پردہ لگا ہوا تھاجس میں تصویریں تھیں، تو میں نے عبیداللہ خولانی سے کہا:کیا انہوں نے ہمیں تصویروں کی ممانعت والی حدیث نہیں بیان کی تھی؟ انہوں نے کہا:انہوں نے یہ بھی فرمایا تھا کہ جو تصویر کپڑے میں ہو وہ جائز ہے، کیا تم نے یہ نہیں سنا تھا؟ میں نے کہا:نہیں، انہوں نے کہا:کیوں نہیں، یہ بھی بیان کیا گیا تھا۔‘‘","صحیح",{"k":"صحیح بخاری (5958)، صحیح مسلم (2106)۔"}],[537,"سعیدبن ابی الحسن روایت کرتے ہیں کہ:\n’’ایک آدمی ابنِ عباس رضی اللہ عنہما کے پاس آیا اور کہا:اے ابو عباس!میں ایسا بندہ ہوں کہ میرا معاش میرے ہاتھ کی تیار کردہ چیزوں پر ہے اور میں تصویریں بناتا ہوں، تو ابنِ عباس رضی اللہ عنہما نے فرمایا:قریب ہوجاؤ، نزدیک آجاؤ، بلاشبہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے کہ جس شخص نے دنیا میں کوئی تصویر بنائی اسے روزِقیامت اس میں رُوح پھونکنے کا مکلّف بنایا جائے گااور وہ پھونک نہیں سکے گا۔ راوی کہتے ہیں کہ (یہ سُن کر)اس کا سانس شدیدپھُول گیا۔ پھر ابنِ عباسؓ نے فرمایا:تجھ پر افسوس ہے کہ تم (جاندار چیزوں کی)تصویریں بناتے ہو، تم درخت وغیرہ اور ایسی چیزوں کی تصویریں بنا لیا کر وجن میں رُوح نہیں ہوتی۔‘‘","صحیح",{"k":"صحیح بخاری (2225)، صحیح مسلم (2110)۔"}],[538,"ابوہریرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’میرے پاس جبرائیل علیہ السلام تشریف لائے اور انہوں نے کہا:میں گزشتہ رات بھی آپ صلی اللہ علیہ وسلم کے پاس حاضر ہوا تھا لیکن (آپ صلی اللہ علیہ وسلم کے گھر کے)دروازے پر بنی تصویریں، گھر میں لگا ہوا تصویروں والا منقش پردہ اورکُتے کی موجودگی میرے لیے اندر داخل ہونے سے مانع بن گئی، لہٰذا آپ صلی اللہ علیہ وسلم (گھر والوں سے)کہیے کہ تصویروں کے سرکاٹ دیے جائیں، تو وہ درخت کی شکل اختیار کر لیں گی، اور پر دے کے بارے میں ہدایت کیجیے کہ اس کے دو تکیے بنا لیے جائیں جنہیں پھینکا جائے اور روندا جائے اورکُتّے کو باہر نکال دینے کاحکم فرمائیے، چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے ایسا ہی کیا۔‘‘","صحیح",{"k":"سنن أبوداؤد (4158)، سنن ترمذی (2806)۔","f":"اس حدیث میں جبرائیل علیہ السلام کے بیت الرسول صلی اللہ علیہ وسلم میں داخلے سے تین چیزوں کو موانع بتلایا گیا ہے جو ترجمۂ حدیث سے واضح ہیں۔ ساتھ ہی جبرائیل علیہ السلام نے آپ صلی اللہ علیہ وسلم کو ان تینوں امور کاحل بھی بتلا دیا کہ کیا کرنا چاہیے، ان میں سے پہلی یعنی دروازے پر کنداں تصویروں کے بابت فرمایاکہ ان تصویروں کا سرکاٹ دیا جائے اس طرح وہ درخت کی صورت اختیار کر لیں گی، تو گویا معلوم ہوا کہ صرف چہرے اور اعضائے چہرہ کی تصویر بنا نے کی ممانعت ہے، اس کے علاوہ ہاتھ پاؤں، ٹانگ، بازو وغیرہ کی تصویر بنا نے میں کوئی حرج نہیں ہے۔ دوسری چیز یعنی گھر میں جو تصویروں والا منقّش پردہ لٹکایا گیا تھا اس کو کاٹ کر دو تکیے بنانے کاحکم فرمایا، اور اس کی بھی وضاحت کردی کہ وہ تکیے زیرِاستعمال نہ لائے جائیں بلکہ انہیں خوش طبعی کے ایک انداز یعنی ایک دوسرے پر پھینکنے یاپاؤں سے روند نے کے لیے رکھ لیے جائیں اورکُتّے کے بارے میں صریحاًفرما دیا کہ اسے گھر سے نکال دینا چاہیے۔ ایک روایت میں یہ صراحت مذکور ہے کہ وہ کُتاحسن وحسین رضی اللہ عنہما کا تھا، جو ابھی بچے تھے اور انہوں نے پیار سے اسے رکھا ہوا تھا۔"}],[539,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم گھر میں کوئی کپڑا ایسا نہیں چھوڑتے تھے کہ جس میں صلیب بنی ہو، مگر آپ صلی اللہ علیہ وسلم اسے کاٹ دیتے تھے۔‘‘","صحیح",{"k":"صحیح بخاری (5952)، سنن أبوداؤد (4151)۔"}],[540,"محمدبن کعب بیان کرتے ہیں کہ:\n’’عبداللہ بن یزید کو کھا نے کی دعوت دی گئی، جب وہ تشریف لائے اور گھر کو فرنیچر، بستروں اور پر دوں سے مزیّن وآراستہ دیکھا تو باہر ہی بیٹھ گئے اور رونے لگے، ان سے پوچھا گیا کہ آپ کوکس بات نے رُلاد یاہے؟ تو انہوں نے جواب دیا کہ رسول اللہ صلی اللہ علیہ وسلم جب کسی لشکر کو رخصت فرماتے تو عقبۃ الوداع تک اس کے ساتھ جاتے اور فرماتے: «أَسْتَوْدِعُ اللّٰهَ دِينَكُمْ وَأَمَانَتَكُمْ وَخَوَاتِيْمَ أَعْمَالِكُمْ» ’’میں تمہارے دِین، تمہاری امانتیں اور تمہارے اعمال کے اچھے خاتموں کو اللہ کے حوالے کرتا ہوں۔‘‘ ایک دِن آپ صلی اللہ علیہ وسلم نے ایک آدمی کو دیکھا کہ اس نے اپنی چادر کو درخت کی گانٹھ کے ساتھ پیوند لگایا ہوا ہے، تو آپ صلی اللہ علیہ وسلم نے مشرق کی طرف رُخ کر لیا اور اپنے دونوں ہاتھوں کو پھیلا کر فرمایا:تم پر دنیا وسیع وفراخ ہوجائے گی، آپ صلی اللہ علیہ وسلم نے تین مرتبہ یہی فرمایا، یہاں تک کہ ہم نے گمان کیاکہ یہ بات ہم پر ہی واقع ہونے والی ہے، پھر آپ صلی اللہ علیہ وسلم نے فرمایا:تم آج کے دِن بہتر ہویا اس وقت بہتر ہوگے جب تمہیں ایک پیالہ صبح نصیب ہوگا اور ایک شام کو؟ اور صبح کے وقت تم ایک جو ڑاپہنوگے اور شام کے وقت دوسرا پہن لیا کروگے اور تم اپنے گھروں پر اس طرح پردے لٹکا ؤگے جس طرح کعبے پر لٹکائے جاتے ہیں۔ پھر عبداللہ بن یزید کہنے لگے کہ کیا میں روؤں نہ؟ میں اسی وجہ سے رویا ہوں کہ تم نے تو اپنے گھروں پہ اس طرح پردے لٹکا رکھے ہیں جس طرح کعبے پہ لٹکائے جاتے ہیں۔‘‘","حسن",{"k":"السنن الکبری للبیهقی (7؍272)۔"}],[541,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم نے سونے کی انگوٹھی(پہننے)سے منع فرمایا۔‘‘","صحیح",{"k":"صحیح بخاری (5864)، صحیح مسلم (2089)۔"}],[542,"عبداللہ بن عباس رضی اللہ عنہما روایت کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے ایک آدمی کے ہاتھ میں سونے کی انگوٹھی دیکھی تو آپ صلی اللہ علیہ وسلم نے اسے اتار کر پھینک دیا اور فرمایا:(یہ انگوٹھی پہننا ایسے ہی ہے جیسے)تم میں سے کوئی آگ کا انگارہ پکڑ کر اپنے ہاتھ میں رکھتا ہے۔ پھرجب رسول اللہ صلی اللہ علیہ وسلم چلے گئے تو اس آدمی سے کہا گیا کہ اپنی انگوٹھی پکڑ لو اور اس سے کوئی اور فائدہ اٹھا لینا، تو اس نے کہا:قسم بخدا!میں اسے کبھی نہیں اٹھاؤں گاجسے رسول اللہ صلی اللہ علیہ وسلم نے پھینک دیا ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2090)۔"}],[543,"اور ایک روایت میں ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’ریشم اور سونا میری اُمت کے مردوں پر حرام ہے اور ان کی عورتوں کے لیے حلال ہے۔‘‘","",{}],[544,"سیدہ عائشہ رضی اللہ عنہا ان زیورات کے بارے میں روایت کرتی ہیں جو نجاشی نے نبی صلی اللہ علیہ وسلم کو تحفے میں دیے تھے، کہ اس میں ایک سونے کی انگوٹھی تھی، تو آپ صلی اللہ علیہ وسلم نے اپنی نواسی امامہ بنت ابی العاص سے فرمایا:\n’’اے میری بیٹی!یہ زیور پہن لے۔‘‘","حسن",{"k":"سنن أبوداؤد (4235)، سنن ابن ماجه (3644)۔"}],[545,"زینب بنت نبیط بیان کرتی ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے ان کی (يعنى زينب كى)والدہ اور خالہ کو ڈھلے ہوئے سونے کی بالیاں پہنائیں جس میں موتی لگے ہوئے تھے۔‘‘","",{"k":"السنن الکبری للبیهقی (4؍141)۔"}],[546,"ایک اور روایت میں ہے کہ زینب بنت نبیط اپنی والدہ سے روایت کرتی ہیں کہ انہوں نے کہا:\n’’میں اور میری دو بہنیں نبی صلی اللہ علیہ وسلم کی گود میں ہی تھیں(یعنی بچیاں تھیں) اور آپ صلی اللہ علیہ وسلم ہمیں سونے اور موتیوں کے زیور پہنایا کرتے تھے۔‘‘","",{"k":"السنن الکبری للبیهقی (4؍141)۔"}],[547,"ابنِ عمر رضی اللہ عنہما نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ:\n’’آپ صلی اللہ علیہ وسلم کو سونے کی ایک انگوٹھی دی گئی، آپ صلی اللہ علیہ وسلم نے اسے اپنے دائیں ہاتھ میں پہن لیا اور اس کا نگینہ ہتھیلی کی جانب رکھا۔ تو(آپ صلی اللہ علیہ وسلم کو دیکھ کر)لوگوں نے بھی سونے کی انگوٹھیاں بنوالیں، جب آپ صلی اللہ علیہ وسلم نے یہ صورتحال دیکھی تو آپ صلی اللہ علیہ وسلم نے اسے اتار پھینکا اور فرمایا:میں اسے کبھی نہیں پہنوں گا، پھر آپ صلی اللہ علیہ وسلم نے چاندی کی انگوٹھی بنو الی۔‘‘","صحیح",{"k":"صحیح بخاری (5865)، صحیح مسلم (2091)۔"}],[548,"سیدنا انس رضی اللہ عنہ سے مرفوعاًمروی ہے کہ:\n’’آپ صلی اللہ علیہ وسلم نے جو چاندی کی انگوٹھی بنوائی تھی اسے بائیں ہاتھ میں پہنا کرتے تھے۔‘‘","صحیح",{"k":"صحیح بخاری (5866)، صحیح مسلم (2091)۔"}],[549,"نافع روایت کرتے ہیں کہ:\n’’ابنِ عمر رضی اللہ عنہما اپنے بائیں ہاتھ میں انگوٹھی پہنا کرتے تھے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4228)۔"}],[550,"سیدنا علی رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے مجھے اس بات سے منع فرمایاکہ میں درمیانی انگلی اور اس کے ساتھ والی یعنی انگشتِ شہادت میں انگوٹھی پہنوں۔‘‘","صحیح",{"k":"صحیح مسلم (2078)، سنن أبوداؤد (4225)، سنن ترمذی (1786)۔"}],[551,"سہل بن سعد روایت کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم نے اس شخص سے فرمایا تھاجس کا ارادہ تھا کہ آپ صلی اللہ علیہ وسلم اس کی شادی کرا دیں کہ (حق مہر میں دینے کے لیے)کچھ لے کرآؤ، خواہ لوہے کی انگوٹھی ہی ہو۔‘‘\n’’نبی صلی اللہ علیہ وسلم کی تلوار کے قبضے کا کنارہ چاندی کا تھا۔‘‘","صحیح",{"k":"صحیح بخاری (5030)، صحیح مسلم (1425)۔","f":"سعیدبن ابوالحسن بیان کرتے ہیں کہ:كَانَتْ قَبِيعَةُ سَيْفِ النَّبِيِّ صَلَّى اللّٰهُ عَلَيْهِ وَسَلَّمَ فِضَّةً."}],[552,"عرفجہ بن اسعد رضی اللہ عنہ کے بابت مروی ہے کہ:\n’’معر کۂ کلاب کے روز ان کی ناک کاٹ دی گئی، تو انہوں نے چاندی کی ناک بنو الی، لیکن وہ بدبو مار نے لگی، تو نبی صلی اللہ علیہ وسلم نے انہیں حکم فرمایا تو انہوں نے سونے کی ناک لگوا لی۔‘‘","حسن",{"k":"سنن أبوداؤد (4232)، سنن ترمذی (1770)۔","f":"مردوں کے لیے سونے کا استعمال صرف ایسی ہی کسی ناگزیر صورت میں جائز ہے، مگربہ طورِزیور استعمال کرنے کا جواز صرف عورتوں کے لیے ہی ہے۔ علاوہ ازیں اس حدیث سے استدلال کرتے ہوئے مردوں کے لیے سونے کا دانت وغیرہ لگوانا بھی جائز قرار دیا گیا ہے۔"}],[553,"عمروبن شعیب اپنے باپ کے حوالے سے اپنے دادا سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’سفید بالوں کومت اُکھاڑا کرو، کیونکہ جس بھی مسلمان کے سفید بال آجاتے ہیں اللہ تعالیٰ ان کی وجہ سے اس کا ایک درجہ بلند فرماتا ہے اور اس کا ایک گناہ مٹا دیتا ہے۔ اور ایک روایت میں ہے:تم سفید بال مت اکھاڑا کرو، کیونکہ یہ مسلمان کانُورہیں، جس شخص کوبہ حالتِ اسلام سفید بال آجائیں اللہ تعالیٰ ان کی وجہ سے اس کے کھاتے میں ایک نیکی لکھ دیتا ہے، اس کا ایک گناہ ختم کر دیتا ہے اور ایک درجہ بلند فرما دیتا ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4202)، صحیح الجامع للألبانی (7463)۔"}],[554,"انس بن مالک رضی اللہ عنہ فرماتے ہیں کہ:\n’’اس بات کو مکروہ سمجھا گیا ہے کہ آدمی اپنے سریا داڑھی سے سفید بال اُکھاڑے۔ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم خضاب نہیں لگایا کرتے تھے، صرف آپ صلی اللہ علیہ وسلم کی چھوٹی داڑھی میں(جو نچلے ہونٹ کے نیچے ہوتی ہے)، کنپٹیوں پر اورسر میں کچھ بال سفید تھے۔‘‘","صحیح",{"k":"صحیح مسلم (2341)۔"}],[555,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’یہود ونصارٰی(بالوں کو)رنگتے نہیں ہیں، سوتم ان کی مخالفت کیا کرو۔‘‘","صحیح",{"k":"صحیح بخاری (5899)، صحیح مسلم (2103)۔"}],[556,"ابوذر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جن چیزوں سے سفید بالوں (کی رنگت)کو بدلا جاتا ہے ان سب سے اچھی چیز مہندی اور کتم ہے۔‘‘","حسن",{"k":"سنن أبوداؤد (4205)، سنن ترمذی (1753)، سنن نسائی (5078)، سنن ابن ماجه (3622)، سلسلہ الأحادیث الصحیحہ (1509)۔","f":"کتم ایک بُوٹی تھی جس سے بال رنگے جاتے تھے۔"}],[557,"سیدنا انس رضی اللہ عنہ روایت کرتے ہیں کہ:\n’’سیدنا ابوبکر رضی اللہ عنہ اپنی داڑھی کو مہندی اور کتم نامی بوٹی کے ساتھ رنگتے تھے، اور سیدنا عمر رضی اللہ عنہ اپنی داڑھی کو اکیلی مہندی سے رنگتے۔‘‘","صحیح",{"k":"صحیح مسلم (2102)، سنن أبوداؤد (4420)، سنن نسائی (5076)۔"}],[558,"جابربن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’فتح مکہ کے روز ابوقحافہ کو لایا گیا اور ان کے سراور داڑھی کے بال ثغامہ بوٹی کی طرح سفید تھے، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:انہیں کسی چیز سے بدل دو(یعنی ان پہ مہندی وغیرہ لگا کر سفیدی ختم کردو)اور سیاہ کرنے سے بچو۔‘‘","صحیح",{"k":"صحیح مسلم (2102)، سنن أبوداؤد (4204)۔","f":"اس حدیث میں سیاہ خضاب لگانے کی ممانعت وارد ہوئی ہے۔"}],[559,"ابنِ عباس رضی اللہ عنہما نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’آخری زمانے میں ایسے لوگ ہوں گے کہ وہ سیاہ خضاب لگایا کریں گے، (اور ان کے بال)کبوتروں کے پوٹوں جیسے ہوں گے، یہ لوگ جنّت کی خوشبو نہیں پائیں گے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4212)۔","f":"امام بیہقیؒ فرماتے ہیں کہ بالوں کو زرد رنگ کرنا جائز ہے جیسا کہ ابنِ عمر رضی اللہ عنہما سے نبی صلی اللہ علیہ وسلم کا اپنی داڑھی کو زرد رنگ دینے کی روایت مروی ہے، اوریک روایت میں خلوق اور ورس کا ذکر ہے، اور ابنِ عمرؓبھی ایسا کیا کرتے تھے۔ یعنی ممانعت صرف بالوں کو سیاہ کرنے کی ہے، اس کے علاوہ مہندی وغیرہ یاایسی چیزجس سے سیاہ نہ ہوں وہ لگائی جاسکتی ہے۔"}],[560,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ:\n’’ایک عورت نے خط دینے کے لیے رسول اللہ صلی اللہ علیہ وسلم کی طرف پردے کے پیچھے سے اپنا ہاتھ بڑھایا تو نبی صلی اللہ علیہ وسلم نے اپنا ہاتھ پیچھے کر لیا اور فرمایا:مجھے کیا پتہ کہ یہ ہاتھ مرد کا ہے یاعورت کا؟ تو اس نے کہا:عورت کا ہاتھ ہے، آپ صلی اللہ علیہ وسلم نے فرمایا:اگرتُوعورت ہے تو اپنے ناخنوں پہ مہندی لگا لیتی۔‘‘","حسن",{"k":"سنن أبوداؤد (4166)، سنن نسائی (5089)، مسند أحمد (6؍262)۔"}],[561,"لاحق بن حمید بیان کرتے ہیں کہ:\n’’میں نے ابنِ عباس رضی اللہ عنہما سے خضاب کے بابت سوال کیا، تو انہوں نے فرمایا:ہماری عورتیں نمازِعشاء سے لے کر نمازِفجرتک خضاب لگاتی تھیں، پھر وہ اپنے ہاتھ دھو کر صاف کر لیتیں اور صاف ستھری ہو جاتیں، پھر دوبارہ نمازِفجر سے لے کر نمازِظہرتک بہترین خضاب لگاتی تھیں، اور یہ انہیں نماز کے لیے مانع نہیں ہوتا تھا۔‘‘","",{"k":"السنن الکبری للبیهقی (7؍312)۔"}],[562,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’اللہ تعالٰی نے مصنوعی بال لگانے اور لگوا نے والی پر، بال گودنے اور گودوانے والی پر لعنت فرمائی ہے۔ اور عبداللہ بن مسعود رضی اللہ عنہ سے مروی حدیث میں ہے کہ اللہ تعالٰی نے بال گودنے اور گودوانے والیوں پر، چہرے کے بال اُکھا ڑنے والیوں پر اور خوبصورتی کے لیے دانتوں کے درمیان فاصلہ پیدا کرنے والیوں پر لعنت فرمائی ہے، جو اللہ تعالیٰ کی تخلیق کو بدلنے والیاں ہیں۔‘‘","صحیح",{"k":"صحیح بخاری (5933)، صحیح مسلم (2124)۔","f":"اَلْوَاصِلَةسے مراد وہ عورت ہے جو اپنے سرمیں مصنوعی بال یعنی وِگ وغیرہ لگوائے، «اَلْمُسْتَوْصِلَةاس» عورت کو کہتے ہیں جو مصنوعی بال لگانے کا کام کرے، اَلْوَاشِمَةسے ایسی عورت مراد ہے جو اپنے چہرے میں سوراخ کرکے یاجِلدچھید کر اس میں سُرمہ یاسیا ہی بھر لیتی ہے تاکہ وہ حسین لگے، اَلْمُسْتَوْشِمَةسے مراد ایسا کام کرنے والی یعنی چہرے کوسُرمے یاسیا ہی سے گودنے والی عورت ہے، «اَلْمُتَنَمِّصَة» کا لفظ اس عورت پر بولا جاتا ہے جو اپنے چہرے سے بال اُکھا ڑتی ہیں جیسا کہ آج کل فیشن ایبل عورتیں تھریڈنگ(Threading) اور پلکنگ(Plucking) کرتی ہیں «اوراَلْمُتَفَلِّجَةاس» عورت کو کہا جاتا ہے جو خوبصورتی کے لیے اپنے دانتوں کے درمیان فاصلہ پیدا کرے۔ اصل میں عربوں کے ہاں اس عورت کو خوبصورت نہیں سمجھا جاتا تھاجس کے سامنے کے دانت ایک دوسرے سے ملے اورجُڑے ہوئے ہوں، اس لیے عورتیں دانتوں کو درمیان سے رگڑ کر ان میں فاصلہ پیدا کر لیتی تھیں۔ ان تمام امور کی ممانعت کی وجہ بھی رسولِ کریم صلی اللہ علیہ وسلم نے ساتھ ہی بیان فرما دی کہ چونکہ یہ اللہ تعالٰی کی تخلیق کو بدلنے کی صورتیں ہیں اور درحقیقت اس کی بنائی ہوئی شکل وصورت پر غیر رضامندی کا اظہار ہے اس لیے اس سے منع فرمایا گیا ہے۔"}],[563,"عبداللہ بن عمر رضی اللہ عنہما روایت کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے مونچھوں کو صاف کرنے اور داڑھی کو)کاٹنے سے(معاف کرنے کاحکم فرمایا۔‘‘","صحیح",{"k":"صحیح بخاری (5892)، صحیح مسلم (259)۔"}],[564,"زیدبن ارقم رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جو اپنی مونچھیں نہیں کاٹتا وہ ہم میں سے نہیں۔‘‘","صحیح",{"k":"سنن ترمذی (2761)، سنن نسائی (5040)، صحیح الجامع للألبانی (6533)۔"}],[565,"ابوہریرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’پانچ چیزیں فطرت سے ہیں:ختنہ کروانا، زیرِناف بال صاف کرنا، بغلوں کے بال اتارنا، مونچھیں چھوٹی کرنا اور ناخن کاٹنا۔ اور سیدہ عائشہ رضی اللہ عنہا کی نبی صلی اللہ علیہ وسلم سے روایت کردہ حدیث میں دس فطری امور کا ذکر ہے، چار تو انہی میں سے ہیں اور(باقی چھے یہ)بیان کیے ہیں:داڑھی بڑھانا، مسواک کرنا، پانی کے ساتھ ناک صاف کرنا، انگلیوں کے جوڑ دھونا، پانی کے ساتھ استنجاء کرنا اورکُلّی کا ذکرشک سے کیا ہے(یعنی قطعی یاد نہیں رہا کہ آخری چیزکُلّی ہی تھی یاکچھ اور)، اور انہوں نے ختنہ کروانے کا ذکر نہیں کیا۔ اور جو حدیث عماربن یاسر رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کی ہے اس میں انہوں نے کُلّی کا ذکر بغیرشک کے کیا ہے اور ختنے کی جگہ داڑھی بڑھانے کا بیان ہے۔‘‘","صحیح",{"k":"صحیح بخاری (5889)، صحیح مسلم (257)۔"}],[566,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’جس کے بال ہوں اسے ان کی عزت کرنی چاہیے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4163)، سلسلہ الأحادیث الصحیحہ (500)۔","f":"بالوں کی عزت کرنے سے مراد یہ ہے کہ انہیں دھوئے، صاف ستھرا رکھے، تیل لگائے اور کنگھی وغیرہ کرکے سنوار کر رکھے۔"}],[567,"عبداللہ بن مغفل بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے سوائے ایک دِن ناغے کے کنگھی کرنے سے منع فرمایا ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4159)، سنن ترمذی (1756)، سنن نسائی (5055)، سلسلہ الأحادیث الصحیحہ (501)۔","f":"یعنی روزانہ کنگھی کرنا ممنوع ہے، لہٰذا ایک دِن چھوڑ کر دوسرے دِن کرنے چاہیے۔ شارحین نے اس ممانعت کی توجیہہ یہ کی ہے کہ عرب لوگ چونکہ لمبے لمبے بال رکھتے تھے جنہیں کھولنے، صاف کرنے اور سنوار نے میں خاصا وقت صرف ہوتا تھا جو کہ سراسر ضیاعِ وقت تھا، اس لیے آپ صلی اللہ علیہ وسلم نے یہ حکم فرمایا، لیکن اگر ایسی علت نہ پائی جائے اور کنگھی کرنے سے وقت ضائع نہ ہوتا ہو کہ جس سے واجبات یاکسی بھی ذمہ داری کے ادا کرنے کا وقت اس میں صرف ہو جاتا ہو تو پھر روزانہ کرنے میں بھی کوئی حرج نہیں ہے۔"}],[568,"عبداللہ بن بریدہ بیان کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم کے ایک صحابی (مسلمانوں کے)امیر تھے، اور وہ ننگے پاؤں چلا کرتے تھے اورسر میں تیل بھی کبھی کبھار ہی لگاتے تھے، تو ان سے اس بابت کہا گیا کہ آپ امیر المومنین ہونے کے باوجود ننگے پاؤں چلتے ہیں اورسر میں تیل بھی نہیں لگاتے؟ تو انہوں نے جواب دیا:رسول اللہ صلی اللہ علیہ وسلم ہمیں بہت زیادہ زیب وزینت اختیار کرنے سے منع فرمایا کرتے تھے اور اس سے مراد روزانہ تیل لگانا ہے، اور آپ صلی اللہ علیہ وسلم ہمیں ننگے پاؤں چلنے کاحکم فرمایا کرتے تھے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4160)، سنن نسائی (5058)۔"}],[569,"براء بن عازب رضی اللہ عنہ فرماتے ہیں کہ:\n’’آپ صلی اللہ علیہ وسلم کے بال آپ صلی اللہ علیہ وسلم کے کانوں کی لوتک پہنچتے تھے۔‘‘","صحیح",{"k":"صحیح بخاری (3551)، صحیح مسلم (2337)۔"}],[570,"وائل بن حجر رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’میں نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور میرے لمبے لمبے بال تھے، تو نبی صلی اللہ علیہ وسلم نے فرمایا:نحوست ہے۔ اور ایک روایت میں ہے کہ (آپ صلی اللہ علیہ وسلم نے فرمایا:تمہارے بال)پراگندہ ہیں۔ چنانچہ میں نے اپنے کچھ بال کاٹ دیے تو آپ صلی اللہ علیہ وسلم نے فرمایا:میں نے تمہیں کوئی بری بات نہیں کہی تھی۔‘‘","صحیح",{"k":"سنن أبوداؤد (4190)۔"}],[571,"ابنِ عباس رضی اللہ عنہما فرماتے ہیں کہ:\n’’اہلِ کتاب اپنے بالوں کو سیدھا چھوڑ دیا کرتے تھے جبکہ مشرکین اپنے سروں میں مانگ نکالا کرتے تھے، اور رسول اللہ صلی اللہ علیہ وسلم کوجن امور میں اللہ کی طرف سے کوئی حکم نہیں ہوتا تھا ان میں آپ صلی اللہ علیہ وسلم اہلِ کتاب کی موافقت کو پسند فرماتے تھے، چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے بھی اپنے بال سیدھے چھوڑ دیے، پھر بعد میں مانگ نکالنے لگے۔‘‘","صحیح",{"k":"صحیح بخاری (5917)، صحیح مسلم (2336)۔","f":"نبی صلی اللہ علیہ وسلم نے پہلے تو اہلِ کتاب کی موافقت کی اور اپنے بالوں کو کھلا سیدھا چھوڑ نے لگے، لیکن بعد میں مانگ نکالنا شروع کردی، اور جیسا کہ اس روایت میں مذکور ہے کہ نبی صلی اللہ علیہ وسلم وہی کام اہلِ کتاب کی طرح کرتے تھے جس کے بارے میں آپ صلی اللہ علیہ وسلم کو اللہ تعالٰی نے کوئی حکم نہیں دیا ہوتا تھا، تو معلوم ہوا کہ آپ صلی اللہ علیہ وسلم نے جو اہلِ کتاب کی موافقت ترک کی وہ اللہ تعالٰی کی طرف سے مانگ نکالنے کاحکم آجا نے کی بناء پر ہی کی، ورنہ آپ صلی اللہ علیہ وسلم مشرکین کا طرزِعمل کیونکر اپنا سکتے تھے؟ لہٰذا مانگ نکالنا نہ صرف سُنّتِ رسول ہے بلکہ حکمِ الٰہی بھی ہے۔"}],[572,"ابنِ عمر رضی اللہ عنہما روایت کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم نے ایک لڑکے کو دیکھا کہ اس نے اپنے سرکا کچھ حصہ مونڈھا ہوا تھا اور کچھ حصہ ویسے ہی چھوڑا ہوا تھا، آپ صلی اللہ علیہ وسلم نے لوگوں کو ایسا کرنے سے منع کر دیا اور فرمایا: یاتو سارا سرمونڈھویا سارا چھوڑ دو۔‘‘","صحیح",{"k":"سنن أبوداؤد (4195)۔"}],[573,"ابنِ عمر رضی اللہ عنہما بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے ’قزع‘سے منع فرمایا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (5920)، صحیح مسلم (2120)۔","f":"’قزع‘سے مراد یہ ہے کہ بچے کے سرکا کچھ حصہ مونڈ دیا جائے اور کچھ حصہ ویسے ہی چھوڑ دیا جائے۔ اس سے یہ احتمال نکالا جاتا ہے کہ زُلفیں رکھنا اس ممانعت میں شامل نہیں ہے، جیسا کہ انس بن مالک رضی اللہ عنہ سے روایت کیا گیا ہے کہ انہوں نے بیان کیاکہ میں نے زُلفیں رکھی ہوئی تھیں اور میری ماں نے مجھے کہاکہ میں انہیں مت کاٹوں، رسول اللہ صلی اللہ علیہ وسلم انہیں کھینچا کرتے اور پکڑ لیا کرتے تھے۔ اور ابنِ عباسؓ سے بھی مروی ہے، انہوں نے جو نبی صلی اللہ علیہ وسلم کے ساتھ نماز پڑھی تھی، اس کے ذکر میں بیان کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے مجھے میری زُلفوں سے یا(فرمایا)میرے سرسے پکڑا۔"}],[574,"ابوملیح ہُذلی روایت کرتے ہیں کہ:\n’’اہلِ حمص یااہلِ شام کی عورتیں سیدہ عائشہ رضی اللہ عنہا کے پاس آئیں تو آپؓ نے پوچھا:کیا تم عورتیں عوامی غسل کانوں میں جاتی ہو؟ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:جو عورت بھی اپنے خاوند کے گھر کے علاوہ کسی اور جگہ اپنے کپڑے اتارتی ہے تو وہ اپنے اور اللہ تعالیٰ کے درمیان حائل پردے کو چاک کر دیتی ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4010)، سنن ترمذی (2803)، سنن ابن ماجه (50)، صحیح الترغیب والترهیب (164)۔"}],[575,"جابربن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم (اپنے بچپن میں)کعبے کی تعمیر کے لیے ان کے ساتھ پتھراُٹھا رہے تھے اور آپ صلی اللہ علیہ وسلم نے تہہ بند باندھا ہوا تھا، کہ آپ صلی اللہ علیہ وسلم کے چچا عباسؓ نے کہا:اے بھتیجے!اگر تم اپنا تہہ بند اتار کر اپنے کندھوں پر رکھ لو تو آسانی سے پتھراُٹھا سکوگے۔ چنانچہ آپ صلی اللہ علیہ وسلم نے اپنا تہہ بند اتارا اور اسے اپنے کندھے پر رکھ لیا، (ایسا کرتے ہی)آپ صلی اللہ علیہ وسلم غشی کھا کر گرپڑے، سواس دِن کے بعد کبھی آپ صلی اللہ علیہ وسلم کو برہنہ نہیں دیکھا گیا۔‘‘","صحیح",{"k":"صحیح بخاری (364)، صحیح مسلم (340)۔"}],[576,"مسوربن مخرمہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’میں ایک پتھر اٹھائے ہوئے آرہا تھا اور میں نے ہلکا ساتہہ بند پہنا ہوا تھا، تو میرا تہہ بند کھل گیا اور میرے پاس پتھر تھا جسے نیچے نہیں رکھ سکتا تھا، یہاں تک کہ میں نے اسے اس کی جگہ پر پہنچا دیا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:واپس جا کر اپنا کپڑااُٹھاؤ، اور ننگے نہ چلا کرو۔‘‘","صحیح",{"k":"صحیح مسلم (341)، سنن أبوداؤد (4016)۔"}],[577,"یعلیٰ بن امیہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’یقیناًاللہ تعالیٰ بہت ہی حیاء دار اور پردہ پوش ہے، سوتم میں سے جب کوئی نہانا چاہے تو اسے کسی چیز کے ساتھ پردہ کر لینا چاہیے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4012)، سنن نسائی (407)، مسند أحمد (4؍224)۔"}],[578,"ابو کثیر کے آزاد کردہ غلام محمد رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’میں نبی صلی اللہ علیہ وسلم کے ساتھ (جارہا)تھا کہ آپ صلی اللہ علیہ وسلم کا گزر معمرؓکے پاس سے ہوا جو بازار میں اپنے گھر کے پاس بیٹھے ہوئے تھے اور ان کی دونوں رانوں پر سے کپڑا ہٹا ہوا تھا، تو نبی صلی اللہ علیہ وسلم نے فرمایا:اے معمر!اپنی رانیں ڈھانپو، کیونکہ رانیں بھی پردے کے اعضاء ہیں۔‘‘","صحیح",{"k":"مسند أحمد (5؍290)، مستدرک حاکم (4؍180)۔"}],[579,"عمروبن شعیب اپنے باپ کے واسطے سے اپنے دادا سے روایت کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’جب تم میں سے کوئی اپنے غلام یانو کر کی اپنی لونڈی سے شادی کرا دے تو پھر لونڈی اس کے(یعنی اپنے مالک کے)پردے کے اعضاء کونہ دیکھے اور ناف سے نیچے گھٹنوں تک پردے کے اعضاء ہیں۔‘‘","حسن",{"k":"سنن أبوداؤد (4113)۔","f":"ایک روایت میں اس حکم کا مخاطب مالک کو بنایا گیا ہے، یعنی اپنے غلام یانو کر کے ساتھ شادی کروانے سے پہلے جو لونڈی اس کے لیے حلال تھی، شادی کے بعد وہ حرام ہوجائے گی اور وہ دونوں ایک دوسرے کے پردے کے اعضاء کو نہیں دیکھ سکتے۔"}],[580,"بہزبن حکیم اپنے باپ کے حوالے سے روایت کرتے ہیں کہ:\n’’انہوں نے عرض کیا:اے پیغمبرِخدا!ہم اپنے پردے کے اعضاء کی کونسی بات اختیار کریں اور کونسی چھوڑیں؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:اپنی بیوی اور اپنی لونڈی کے سوا(ہرعورت)سے اپنے پردے کے اعضاء کو(نظر آنے سے)محفوظ رکھو، میں نے پوچھا:آپ صلی اللہ علیہ وسلم کا کیا خیال ہے اگر کوئی اکیلا ہو تو؟ آپ صلی اللہ علیہ وسلم نے فرمایا:لوگوں کی بہ نسبت اللہ تعالیٰ اس بات کا زیادہ حق رکھتا ہے کہ اس سے حیاء کی جائے۔‘‘","حسن",{"k":"سنن أبوداؤد (4017)، سنن ترمذی (2794)، سنن ابن ماجه (2794)، صحیح الجامع للألبانی (203)۔"}],[581,"ابو سعید رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’کوئی آدمی کسی آدمی کی شرمگاہ کونہ دیکھے اور نہ ہی کوئی عورت کسی عورت کی شرمگاہ کو دیکھے، اور کوئی آدمی کسی آدمی کے ساتھ ایک کپڑے میں نہ لیٹے اور نہ ہی کوئی عورت کسی عورت کے ساتھ ایک کپڑے میں لیٹے۔‘‘","صحیح",{"k":"صحیح مسلم (338)، سنن أبوداؤد (4018)۔"}],[582,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے دو طرح کے لباس پہننے سے منع فرمایا ہے:(ایک)کپڑے کو اس طرح جسم پر لپیٹنا کہ جسم کے ایک طرف کپڑے کا کوئی حصہ نہ ہو، اور(دوسرا)یہ کہ ایک ہی کپڑے سے اپنی کمر اور پنڈلی کو ملا کر باندھ لینا اور اور شرمگاہ کو آسمان کی طرف کھلا چھوڑ دے۔‘‘","صحیح",{"k":"صحیح بخاری (5821)، سنن أبوداؤد (4080)۔","f":"حدیث میں بیان ہے کہ اَلصَّمَّاءُسے مراد یہ ہے کہ آدمی اپنے دونوں کندھوں میں سے ایک پر کپڑا ڈال لے اور دوسرے کندھے پر کوئی کپڑا نہ ہو وہ ننگا ہی رہے، اور اِحْتِبَاءٌ کا مطلب یہ ہے کہ آدمی کپڑے کے ساتھ اس طرح کمر اور پنڈلی باندھ کر بیٹھے کہ اس کی شرمگاہ پر کپڑا نہ رہے۔"}],[583,"جابربن عبداللہ رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’تم میں سے کوئی بھی چِت نہ لیٹے کہ پھر وہ اپنی ایک ٹانگ دوسری ٹانگ کے اوپر رکھ لے۔‘‘","صحیح",{"k":"صحیح مسلم (2099)۔","f":"چِت لیٹنے سے مراد ہے بالکل سیدھا آسمان کی طرف منہ کرکے لیٹنا۔ امام بیہقیؒ فرماتے ہیں کہ یہ ممانعت اس وجہ سے ہے کہ ایک ٹانگ پر دوسری ٹانگ رکھنے سے ستر ظاہر ہو نے کا احتمال ہوتاہے، اور اگر تہہ بند تنگ ہو تو پھر آدمی کی ران تو عریاں ہونے سے بچ ہی نہیں سکتی اوربہ فرمانِ نبوی صلی اللہ علیہ وسلم ران بھی شرمگاہ کا حصہ ہے۔"}],[584,"عبداللہ بن زید رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’میں نے رسول اللہ صلی اللہ علیہ وسلم کو مسجد میں اور اپنی ایک ٹانگ کو دوسری ٹانگ پہ رکھے چِت لیٹے دیکھا۔‘‘","صحیح",{"k":"صحیح بخاری (475)، صحیح مسلم (2100)۔","f":"پچھلی حدیث میں ممانعت وارد ہوئی ہے جبکہ اس حدیث میں خود نبی کریم صلی اللہ علیہ وسلم کا ایسا عمل مذکور ہے۔ تو ان دونوں حدیث میں تطبیق یہ ہے کہ اگر تو آدمی لاپروائی اوربے خیالی سے لیٹتا ہوتو پھر ایسے لیٹنا ممنوع ہے لیکن اگر کوئی شخص کو پردے میں رکھنے اور اسے ظاہر نہ ہونے دینے کا پورا اہتمام کرے تو پھر ٹانگ پر ٹانگ رکھ کر چت لیٹنا جائز ہے۔"}],[585,"ابنِ عمر رضی اللہ عنہما نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب تم میں سے کوئی نماز پڑھے تو اسے چھوٹا کمبل یاچادر اوڑھ لینی چاہیے۔‘‘","صحیح",{"k":"السنن الکبری للبیهقی (2؍235)، صحیح ابن حبان (348)، صحیح الجامع للألبانی (647)۔"}],[586,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’ایک آدمی نبی صلی اللہ علیہ وسلم کے پاس آیا اور اس نے آپ صلی اللہ علیہ وسلم سے ایک کپڑے میں نماز پڑھنے کے بابت مسئلہ پوچھا،آپ صلی اللہ علیہ وسلم نے فرمایا:کیا تم میں سے ہرایک کے پاس دو کپڑے ہیں؟ پھر ایک آدمی نے عمرؓکے پاس آکر پوچھا کہ کیا ایک کپڑے میں نماز ہو جاتی ہے؟ انہوں نے جواب دیا کہ جب اللہ تعالٰی نے تمہیں سہولت دی ہے تو تم بھی سہولت اپناؤ، آدمی پر لازم ہے کہ وہ اپنے کپڑے اکٹھے کرلے، کوئی آدمی تہہ بند اور چادر میں نماز پڑھ لے، کوئی تہہ بند قمیض میں، کوئی تہہ بند اور چوغے میں، کوئی شلوار اور چادر میں، کوئی شلوار اور قمیض میں، کوئی شلوار اور چوغے میں، کوئی لنگوٹ اور چوغے میں اور کوئی لنگوٹ اور قمیض میں، اور میرا خیال ہے کہ انہوں نے یہ بھی فرمایاکہ کوئی لنگوٹ اور چادر میں۔‘‘","صحیح",{"k":"صحیح بخاری (358)، صحیح مسلم (515)۔","f":"یعنی جس کے پاس جو میسر ہے وہ اس میں نماز پڑھ لے۔"}],[587,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’تم میں سے کوئی بھی ایک کپڑے میں ہرگز نماز نہ پڑھے کہ اس کے کندھے پہ کوئی چیز ہی نہ ہو۔‘‘","صحیح",{"k":"صحیح مسلم (516)۔","f":"یعنی نماز کے لیے ستر کے علاوہ کم ازکم کندھے ضرور ڈھکے ہونے چاہییں۔"}],[588,"جابر رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب تُونماز پڑھے اور تیرے پاس ایک ہی کپڑا ہو، اگر وہ کشادہ ہو تو اسے اپنے جسم پر اچھی طرح لپیٹ لے اور اگر وہ تنگ ہو تو اس کا تہہ بند باندھ لے۔ ایک اور روایت میں ہے:جب وہ کشادہ ہو تو اس کے دونوں کناروں کو کندھوں کی مخالف سمت پر ڈال لے، اور اگر وہ تنگ ہو تو اسے (تہہ بند کے طور پر)اپنی کمر پر باندھ لے۔‘‘","صحیح",{"k":"صحیح بخاری (361)۔"}],[589,"سلمہ بن اکوع رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’میں نے عرض کیا:اے اللہ کے رسول!میں ایک قمیض میں نماز پڑھ سکتا ہوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا:ہاں، خواہ اس کا وزن ایک کانٹے کے برابر ہی ہو۔‘‘","",{"k":"السنن الکبری للبیهقی (2؍240)۔"}],[590,"سیدہ عائشہ رضی اللہ عنہا نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’بالغہ عورت کی نماز چادر کے بغیر قبول ہی نہیں کی جاتی۔‘‘","صحیح",{"k":"سنن أبوداؤد (641)، سنن ترمذی (377)، إرواء الغلیل للألبانی (196)۔"}],[591,"سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں کہ:\n’’جب یہ آیت: «وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلٰى جُيُوبِهِنَّ» ’’اور عورتوں کو چاہیے کہ وہ اپنی چادریں اپنے سِینوں پر ڈالے رکھا کریں‘‘ نازل ہوئی تو عورتوں نے اپنے تہہ بندوں کو دونوں کناروں سے پھاڑ کر اپنی اوڑھنیاں بنالِیں۔‘‘","صحیح",{"k":"صحیح بخاری (4759)۔"}],[592,"اسامہ بن زید رضی اللہ عنہ روایت کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم نے انہیں ایک موٹا قبطی کپڑا پہننے کے لیے دیا تو انہوں نے وہ اپنی بیوی کو دے دیا، تو نبی صلی اللہ علیہ وسلم نے فرمایا:اسے کہو کہ وہ اس کے نیچے بنیان وغیرہ پہن لے، کیونکہ میں ڈرتا ہوں کہ وہ اس کے اعضاء کو نمایاں نہ کرے۔‘‘\n’’عورت تین کپڑوں میں نماز پڑھے:قمیض، چادر اور تہہ بند۔‘‘","",{"k":"السنن الکبری للبیهقی (2؍234)، المعجم الکبیر للطبرانی (1/123) السنن الکبری للبیهقی (2؍235)۔","f":"عمربن خطاب رضی اللہ عنہ فرماتے ہیں کہ:تُصَلِّي «الْمَرْأَةُ فِي ثَلَاثَةِ أَثْوَابٍ: دِرْعٍ، وَخِمَارٍ، وَإِزَارٍ»."}],[593,"ابوقلابہ بیان کرتے ہیں کہ:\n’’انس بن مالک رضی اللہ عنہ نے فرمایا:اس آیت یعنی آیتِ حجاب کے(شانِ نزول)کو میں اچھی طرح جانتا ہوں، جب سیدہ زینب رضی اللہ عنہا سے رسول اللہ صلی اللہ علیہ وسلم کی شادی ہوئی اور وہ آپ صلی اللہ علیہ وسلم کے ساتھ ہی گھر میں موجود تھیں، آپ صلی اللہ علیہ وسلم نے کھانا تیار کروایا، لوگ آئے اور(کھانا کھا کر)گھر ہی میں تھے کہ رسول اللہ صلی اللہ علیہ وسلم باہر تشریف لے گئے اور لوگ اپنی جگہ پر ہی بیٹھے رہے، پھر آپ صلی اللہ علیہ وسلم واپس آئے تو(تب بھی)وہ بیٹھے ہی تھے۔ چنانچہ اللہ تعالٰی نے یہ آیت نازل فرما دی: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَدْخُلُوا بُيُوتَ النَّبِيِّ إِلَّا أَنْ يُؤْذَنَ لَكُمْ إِلٰى طَعَامٍ غَيْرَ نَاظِرِينَ إِنَاهُ وَلٰكِنْ إِذَا دُعِيتُمْ فَادْخُلُوا فَإِذَا طَعِمْتُمْ فَانْتَشِرُوا وَلَا مُسْتَأْنِسِينَ لِحَدِيثٍ إِنَّ ذَالِكُمْ كَانَ يُؤْذِي النَّبِيَّ فَيَسْتَحْيِي مِنْكُمْ وَاللّٰهُ لَا يَسْتَحْيِي مِنَ الْحَقِّ وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ وَمَا كَانَ لَكُمْ أَنْ تُؤْذُوا رَسُولَ اللّٰهِ وَلَا أَنْ تَنْكِحُوا أَزْوَاجَهُ مِنْ بَعْدِهِ أَبَدًا إِنَّ ذَلِكُمْ كَانَ عِنْدَ اللّٰهِ عَظِيمًا﴾ ’’اے ایمان والو!جب تک تمہیں اجازت نہ دی جائے تم کھانے کے لیے نبی( صلی اللہ علیہ وسلم )کے گھروں میں نہ جایا کرو، ایسے وقت میں کہ اس کے پکنے کا انتظار کرتے رہو، بلکہ جب بلایا جائے تب جاؤ اورجب کھا چکو نکل پڑو، وہِیں (بیٹھ کر)باتوں میں مشغول نہ ہو جایا کرو، نبی( صلی اللہ علیہ وسلم )کو تمہاری اس بات سے تکلیف ہوتی ہے تو وہ لحاظ کر جاتے ہیں اور اللہ تعالٰی حق بیان کرنے میں کسی کا لحاظ نہیں کرتا۔ جب تم(نبی صلی اللہ علیہ وسلم )کی بیویوں سے کوئی چیز طلب کرو تو پر دے کے پیچھے سے طلب کرو، تمہارے اور ان کے دِلوں کے لیے کامل پاکیزگی یہی ہے، نہ تمہارے لیے یہ جائز ہے کہ تم رسول اللہ ( صلی اللہ علیہ وسلم ) کو تکلیف دو اور نہ ہی یہ جائز ہے کہ تم آپ صلی اللہ علیہ وسلم کے بعد کسی بھی وقت آپ صلی اللہ علیہ وسلم کی بیویوں سے نکاح کرو، یقیناًیہ اللہ تعالٰی کے نزدیک بہت بڑا گناہ ہے۔‘‘","صحیح",{"k":"صحیح بخاری (4792)۔"}],[594,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جہنمیوں کی دو قسمیں ایسی ہیں جنہیں میں نے نہیں دیکھا:(ایک) وہ لوگ جن کے پاس گائے کی دُموں جیسے کوڑے ہیں اور ان کے ساتھ وہ لوگوں کو مارتے ہیں، اور(دوسری)وہ عورتیں جو لباس پہننے کے باوجود بھی ننگی ہوں، (خود غیروں کی طرف)مائل ہونے والی اور(دوسروں کو)مائل کرنے والی، ان کے سربختی اونٹ کی کوہانوں کی طرح ایک طرف جھکے ہوئے ہیں، یہ نہ توجنّت میں داخل ہوں گی اور نہ ہی اس کی خوشبو پاسکیں گی، حالانکہ جنّت کی خوشبو اتنی اتنی دُورسے آرہی ہوگی۔‘‘","صحیح",{"k":"صحیح مسلم (2128)، مسند أحمد (2؍356)۔","f":"اللہ تعالیٰ فرماتا ہے: ﴿وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهْرَ مِنْهَا﴾ [النور: ۳۱] ’’اور عورتیں اپنی زینت کو ظاہر نہ کریں، سوائے اس کے جو خود ہی ظاہر ہو جائے۔‘‘\nلباس پہننے کے باوجود ننگی ہونے سے مراد یہ ہے کہ وہ لباس تو پہنیں گی، لیکن اس قدر باریک کہ ان کا جسم صاف نظر آرہا ہوگا، یا اتنا تنگ لباس پہنیں گی کہ ان کے جسم کے تمام اعضاء نمایاں ہو رہے ہوں گے۔ مائل ہونے اور کرنے والی عورتوں سے مراد وہ عورتیں ہیں جوبے حیا ہوں اور اس غرض سے زیب وآرائش کریں کہ لوگ انہیں دیکھیں اور جب لوگوں کا اپنی طرف جھکاؤ دیکھتی ہیں تو خود بھی ان کی طرف راغب ہونے لگتی ہیں۔ سر بختی اونٹوں کی کوہانوں کے مثل ہونے کا مطلب یہ ہے کہ جس طرح اونٹ کی کوہان اونچی اور نمایاں ہوتی ہے اسی کے مثل یہ عورتیں اپنے سرپر بالوں کاجُوڑا بنائيں گى۔ متذكره بالا اموركے ساتھ یہ خصلت بھی آج كل كى فيشن زده عورت ميں ديكھى جاتى ہے۔ حالانکہ ایک مسلمان عورت کو یہ تمام صورتیں اپنانے سے گریز کرنا چاہیے، تاکہ رسول اللہ صلی اللہ علیہ وسلم كى لعنت كامستوجب بننے سے بچا جا سكے۔"}],[595,"سیدنا ابنِ عباس رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے عورتوں کی مشابہت اختیار کرنے والے مردوں اور مردوں کی مشابہت اختیار کرنے والی عورتوں پر لعنت فرمائی ہے۔ اور ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے عورت کے لباس جیسا لباس پہننے والے مرد اور مرد کے لباس جیسا لباس پہننے والی عورت والی عورت پر لعنت فرمائی۔ اور سیدہ عائشہ رضی اللہ عنہا سے مرفوعاًمروی ہے کہ آپ صلی اللہ علیہ وسلم نے مردوں کی سی عادات اپنانے والی عورت پر لعنت فرمائی۔‘‘","صحیح",{"k":"صحیح بخاری (5885)، سنن أبوداؤد (4097)، سنن ترمذی (2784)، سنن ابن ماجه (1904)۔","f":"آج کل تو یہ فیشن بن چکا ہے کہ وضع قطع، لباس وعادات، چال ڈھال اور دیگر امور میں مرد عورتوں کی مشابہت اختیار کرتے ہیں اور عورتیں مردوں کی، وضع قطع میں مرد عورتوں جیسا ہیئرسٹائل بنانے لگے ہیں، بڑے بڑے بال رکھ کر ان پر پونی وغیرہ چڑھا کر عورتوں کی نقالی کرتے ہیں، اسی طرح داڑھی اور مونچھ کا صفایا(Clean Shave)کرکے عورتوں جیسی صورت بنا لیتے ہیں، لباس میں دیگر کئی طرح سے مشابہت کے علاوہ یہ صورت بھی اختیار کر لی گئی ہے کہ مردوں کی شلواریں عورتوں کی طرح ہوگئی ہیں یعنی ٹخنوں سے نیچے اور عورتوں کی شلواریں مردوں جیسی ہوگئی ہیں یعنی ٹخنوں سے اوپر اور عادات میں مردو عورت کا ایک دوسرے کی نقالی کرنا تو شمار سے باہر ہو نے لگا ہے، الغرض اسی قسم کے مردوں اور عورتوں پر رسولِ مکرم صلی اللہ علیہ وسلم نے لعنت فرمائی ہے۔"}],[596,"ابنِ عباس رضی اللہ عنہما روایت کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم نے مَردوں میں سے عورتوں کی عادات اپنانے والے اور عورتوں میں سے مردوں کی عادات اپنانے والِیوں پر لعنت فرمائی، اور فرمایا:انہیں اپنے گھروں سے نکال دیا کرو۔ اور(خُود)آپ صلی اللہ علیہ وسلم نے فلاں فلاں کو نکالا۔‘‘","صحیح",{"k":"صحیح بخاری (5886)۔"}],[597,"اُمِ سلمہ رضی اللہ عنہا بیان کرتی ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم ان کے پاس تشریف لائے تو گھر والوں کے پاس ایک ہیجڑا بیٹھا ہوا تھا اور وہ اُمِ سلمہؓ کے بھائی عبداللہؓ سے کہہ رہا تھا کہ اگر اللہ تعالٰی کل طائف کو فتح کر دیتا ہے تو میں تمہیں ایک عورت کا بتلاؤں گا، جب وہ سامنے آتی ہے تو چاربَل پڑتے ہیں اور واپس مُڑتی ہے تو آٹھ بَل پڑتے ہیں، تو نبی صلی اللہ علیہ وسلم نے فرمایا:انہیں اپنے گھروں سے نکال دیا کرو۔‘‘","صحیح",{"k":"صحیح بخاری (5886)، صحیح مسلم (2180)۔","f":"عرب لوگوں کے ہاں اس عورت کو بہت خوبصورت سمجھا اور پسند کیا جاتا تھا جو فربہ جسم والی ہو، ایسی عورت کو اس بات سے تعبیر کیا جاتا تھا کہ وہ جب آتی ہے تو اس کے جسم کے سامنے حصے پر چاربَل پڑتے ہیں اورجب واپس جاتی ہے تو آٹھ بَل پڑتے ہیں۔ مذکورہ بالا ہیجڑا بھی عبداللہؓکو ایسی ہی عورت کا طمع دے رہا تھا تو نبی صلی اللہ علیہ وسلم نے اس اخلاق باختہ بات کو ناگوار سمجھا اور اسے گھر سے نکال دینے کاحکم فرمایا۔"}],[598,"اسامہ بن زید رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’میں نے اپنے بعدمَردوں کے لیے عورتوں سے بڑھ کر نقصان دہ کوئی فتنہ نہیں چھوڑا۔‘‘","صحیح",{"k":"صحیح بخاری (5096)، صحیح مسلم (2740)۔"}],[599,"ابو سعید رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’یقیناًدنیا سرسبز اور میٹھی ہے، اور اللہ تعالیٰ تمہیں اس دنیا میں دوسروں کا جانشین بنا کر دیکھے گاکہ تم کیسے عمل کرتے ہو؟ سوتم دنیا اور عورتوں کے فتنے سے بچے رہنا، کیونکہ بنی اسرائیل کاسب سے پہلا فتنہ عورتوں کا ہی فتنہ تھا۔‘‘","صحیح",{"k":"صحیح مسلم (2742)، سنن ترمذی (2191)، سنن ابن ماجه (4000)۔"}],[600,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’لوگوں کوسب سے زیادہ جہنّم میں لے جانے والے دو پیٹ ہیں۔ پوچھا گیا:اے اللہ کے رسول!وہ دو پیٹ کونسے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا:شرمگاہ اور منہ۔ کیا تم جانتے ہوکہ لوگوں کوسب سے زیادہ جنّت میں لے جانے والے کونسے عمل ہیں؟ اللہ تعالیٰ کاڈر اور اچھا اخلاق۔‘‘","حسن",{"k":"سنن ترمذی (2004)، سنن ابن ماجه (4246)، سلسلہ الأحادیث الصحیحہ (977)۔","f":"یعنی اگر آدمی نے اپنی شرمگاہ کا حرام جگہ میں استعمال کیا تو جہنم میں جائے گا اور اگر اللہ سے ڈرتا رہا اور اسے جائز جگہ یعنی اپنی بیوی پر ہی استعمال کیاتو جنت میں جائے گا۔"}],[601,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’ہرابنِ آدم کے لیے زنا کا کچھ حصہ ہے، آنکھیں بھی زنا کرتی ہیں اور ان کا زنا(نامحرم اور ناجائز امور کو)دیکھنا ہے، ہاتھ بھی زنا کرتے ہیں اور ان کا زناچھُونا ہے، پاؤں بھی زنا کرتے ہیں اور ان کا زناچل کر جانا ہے، منہ بھی زنا کرتا ہے اور اس کاز ناچُومنا ہے اوردِل (کسی کام کا)ارادہ یاخواہش کرتاہے اور شرمگاہ اس کی تصدیق یاتکذیب کرتی ہے۔‘‘","صحیح",{"k":"صحیح بخاری (6243)، صحیح مسلم (2657)۔","f":"اللہ تعالیٰ فرماتا ہے: ﴿قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ﴾ [النور: ۳۰] ’’(اے پیغمبر!)مومن مردوں سے کہہ دیجیے کہ وہ اپنی نگاہیں جھکائے رکھیں۔‘‘ اور فرمایا: ﴿وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ﴾ [النور: ۳۱] ’’(اے پیغمبر!)مومنہ عورتوں سے (بھی)کہہ دیجیے کہ وہ اپنی نگاہیں نیچی رکھیں۔‘‘\nیعنی شہوت کی نیت سے اعضائے جسمانی کے ساتھ جو بھی کام کیا جائے گا وہ زنا ہوگا، مثلاً اگر کسی عورت کو گندی نظر سے دیکھتا ہے تو یہ آنکھوں کا زنا ہوگا اور اس کے نامۂ اعمال میں اس کا گناہ لکھا جائے گا، یا کسی کو ہاتھ سے چھوتا ہے تو ہاتھ کا، یا کسی فاحشہ کے پاس پاؤں سے چل کر جاتا ہے تو پاؤںکا، یا کسی سے بوس و کنا ر کرتا ہے تو منہ کا زنا اور گناہ لکھا جائے گا۔ یعنی اگر اس نے ملاپ کر کے شرمگاہ کے ذریعے زنا نہیں بھی کیا تو پھر بھی مذکورہ تمام کاموں کے ارتکاب سے بھی اس کے اعضائے جسمانی کے حصے کا گناہ لکھ دیا جائے گا۔ اس لیے بے حیائی کے چھوٹے سے چھوٹے کام سے بھی احتراز کرنا چاہیے۔ آخر میں فرمایا کہ ان تمام امور کے سارا معاملہ دل کے فیصلے پر موقوف ہو جاتا ہے۔ اگر دل نے بے حیائی کے ارتکاب کا ارادہ کر لیا تو شرمگاہ تو شرمگاہ اس کی تصدیق یعنی وہ کام سر انجام دیتی ہے اور اگر دل میں اللہ تعالیٰ کا خوف پیدا ہوگیا اور وہ عذاب الٰہی سے ڈر گیا تو شرمگاہ اس کے قریب بھی نہیں پھٹکے گی۔ اس لیے دل کی اصلاح اور نیکی و تقویٰ کے کاموں پر ثابت رہنے کی اللہ تعالیٰ سے دعا کرتے رہنا چاہیے، تا کہ صغیرہ و کبیرہ تمام گناہوں سے محفوظ رہا جا سکے۔"}],[602,"جابر رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’میں نے نبی صلی اللہ علیہ وسلم سے اچانک(غیرار دی طور پر)پڑنے والی نظر کے بابت پوچھا تو آپ صلی اللہ علیہ وسلم نے مجھے حکم فرمایاکہ میں اپنی نظر پھیر لوں۔‘‘","صحیح",{"k":"صحیح مسلم (2159)، سنن أبوداؤد (2148)، سنن ترمذی (2776)۔","f":"امام بیہقیؒ فرماتے ہیں:غیر ارادی طور پر پڑنے والی نظر کو فوراًپھیر لینا واجب ہے، جیسا کہ بریدہ رضی اللہ عنہ کی حدیث میں ہے کہ نبی صلی اللہ علیہ وسلم نے سیدنا علی رضی اللہ عنہ سے فرمایاکہ ایک نظر پڑنے پر دوسری نظرمت مار، کیونکہ تیرے لیے پہلی نظر(کی معافی)ہے اور دوسری نظر کی نہیں۔ اس فرمان سے آپ صلی اللہ علیہ وسلم کی «فَإِنَّ لَكَ» الْأُولٰىسے مراد یہ ہے کہ تو پہلی نظر ہی مار سکتا ہے جو غیر ارادی طور پر اچانک پڑگئی ہو، اور «وَلَيْسَتْ لَكَ» الْآخِرَةُسے مراد یہ ہے کہ ایک نظر پڑجا نے کے بعد پھر اس کی طرف دیکھتامت رہ بلکہ اپنی نظر کو موڑ لے۔"}],[603,"جابر رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’یقیناًعورت شیطان کی صورت میں آتی ہے اور شیطان کی صورت میں واپس جاتی ہے، سوتم میں سے جو کوئی اسے دیکھے تو اسے اپنی بیوی کے پاس آنا چاہیے، کیونکہ یہ اس کے دِل کے جذبات کو رازداری سے پورا کرنے والی چیز ہے۔‘‘","صحیح",{"k":"صحیح مسلم (1403)، سنن أبوداؤد (2151)۔","f":"شیطان ہردم انسان کو بہکا نے کی تاک میں رہتا ہے اور عورت اس کا بڑا ہتھیار ہے، پھر انسان میں نفسانی جذبات کااُبھر آنا بعید ازا مکان نہیں ہے لیکن ان پر قابو پانا اور ان کی جائز طور پر تکمیل کرنا حقیقی مسلمان کی علامت ہے۔ اسی لیے نبی صلی اللہ علیہ وسلم نے انسان کی اس کمزوری کاحل بتلا دیا کہ جب کسی غیر عورت کو دیکھ کر کچھ خیالات پیدا ہو نے لگیں تو فوراًاپنی بیوی کے پاس آکر اپنی حاجت کی جائز تکمیل کر لینی چاہیے، تاکہ کسی برائی کا ارتکاب کرنے سے بچ جائے۔"}],[604,"ابنِ عباس رضی اللہ عنہما بیان کرتے ہیں کہ میں نے نبی صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’کوئی آدمی کسی عورت کے ساتھ ہرگز خلوت اختیار نہ کرے، اور نہ ہی کوئی عورت محرم کے بغیر سفر کرے۔‘‘","صحیح",{"k":"صحیح بخاری (3006)، صحیح مسلم (1341)۔","f":"ایک روایت میں یہ الفاظ ہیں کہ جب بھی کوئی مرد کسی عورت کے ساتھ خلوت اختیار کرتا ہے تو ان دونوں کے ساتھ تیسرا شیطان وہاں موجود ہوتا ہے۔ (مسند احمد:۱۱۴) یعنی اس روایت میں آپ صلی اللہ علیہ وسلم نے نامحرم مرد و عورت کو تنہائی اور علیحدگی میں اکٹھے ہونے سے ممانعت کی وجہ بتلا دی ہے کہ ان دونوں کے پاس تیسرا شیطان بھی موجود ہوتا ہے، جو مرد و زن میں سے ہر ایک کے دل میں برے وساوس اور غلط خیالات ڈالتا ہے، چونکہ بہ فرمان نبوی صلی اللہ علیہ وسلم شیطان انسان میں خون کی طرح گردش کرتا ہے، تو اس لیے یہ اس وقت ان دونوں کے جذبات کو ابھار نے اور برائی پر اکسا نے کی کوئی کسر نہیں چھوڑتا۔ چنانچہ اس کبیرہ گناہ کے سدِباب کے لیے اس کام سے ہی منع کر دیا گیا جو اس کا سبب بن سکتا ہے۔"}],[605,"سیدنا انس رضی اللہ عنہ روایت کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم سیدہ فاطمہ رضی اللہ عنہا کے پاس ایک غلام لے کر آئے، جسے آپ صلی اللہ علیہ وسلم نے ان کو ہِبہ کیا تھا، راوی کہتے ہیں کہ سیدہ فاطمہؓ کے پاس ایک ہی کپڑا تھا جسے وہ سرپہ اوڑھتیں تو ان کے پیروں تک نہیں پہنچتا تھا اور پیروں کو ڈھانپتیں تو سرتک نہیں پہنچتا تھا، جب نبی صلی اللہ علیہ وسلم نے ان کی اس الجھن کو دیکھا تو فرمایا:اس سے تجھے کوئی خدشہ نہیں ہے، یہ تو تمہارا باپ بھی ہے اور غلام بھی۔‘‘","صحیح",{"k":"سنن أبوداؤد (4106)۔","f":"اللہ تعالٰی فرماتا ہے: ﴿وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ أَوْ إِخْوَانِهِنَّ أَوْ بَنِي إِخْوَانِهِنَّ أَوْ بَنِي أَخَوَاتِهِنَّ أَوْ نِسَائِهِنَّ أَوْ مَا مَلَكَتْ أَيْمَانُهُنَّ أَوِ التَّابِعِينَ غَيْرِ أُولِي الْإِرْبَةِ مِنَ الرِّجَالِ أَوِ الطِّفْلِ الَّذِينَ لَمْ يَظْهَرُوا عَلَى عَوْرَاتِ النِّسَاءِ﴾ [النور: ۳۱] ’’اور عورتیں اپنی زینت کو ظاہر نہ کریں، سوائے اس کے جواز خود ظاہر ہو جائے، اور اپنے گریبانوں پر اوڑھنیاں ڈالے رہیں، اور اپنی آرائش کو کسی کے سامنے ظاہر نہ کریں، سوائے اپنے خاوندوں کے، یاا پنے باپوں کے، یاا پنے سسروں کے، یاا پنے بیٹوں کے، یاا پنے خاوند کے(کسی اور بیوی سے)بیٹوں کے، یاا پنے بھائیوں کے، یاا پنے بھتیجوں کے، یاا پنے بھانجوں کے، یاا پنے میل جول کی عورتوں کے، یاغلاموں کے، یاایسے نو کر چاکر مردوں کے جو شہوت والے نہ ہوں، یاایسے بچوں کے جو عورتوں کی پردے کی باتوں سے مطلع نہ ہوں۔‘‘ یعنی ہروہ شخص جس کے ساتھ عورت نسب یار ضاعت کی بناء پر شادی نہ کر سکتی ہو وہ اس کے لیے محرم ہے، اس میں عورت کے چچا اور ماموں شامل ہیں کیونکہ بھتیجوں اور بھانجوں کے ذکر سے چچاؤں ماموؤں پر بھی تنبیہ ہے۔ اور میل جول کی عورتوں میں صرف مسلمان عورتیں داخل ہیں جیسا کہ سیدنا عمربن خطاب رضی اللہ عنہ نے ابوعبیدہ بن جراح رضی اللہ عنہ کو یہ لکھ کر بھیجا کہ بعض مسلمان عورتیں جب غسل خانوں میں جاتی ہیں تو ان کے ساتھ اہلِ کتاب عورتیں بھی چلی جاتی ہیں تو انہوں نے عورتوں کو اس سے منع فرمادیا۔ )السنن الكبرى للبيهقى:۷/۱۵۳-مصنف عبدالرزاق:۱۲۹۵/) ایک اور روایت میں یوں وضاحت ہے کہ اللہ تعالٰی اور روزِآخرت پر ایمان رکھنے والی عورت کے لیے جائز نہیں ہے کہ اس کی ہم مذہب عورت کے سوا کوئی عورت اس کے ستر کو دیکھے۔ )السنن الكبرى للبيهقى:۷/۱۵۳) اور غلاموں کے استثناء سے متعلقہ ایک روایت یوں ہے کہ امہات المومنین جب اپنے کسی مکاتب غلام سے بات چیت کرتیں یاا نہیں کوئی کام وغیرہ کہنے لگتیں تو اپنا پردہ ہٹا دیا کرتی تھیں، جب فارغ ہو جاتیں تو پھر پردہ کر لیا کرتیں۔\nاللہ تعالیٰ کے فرمان: ﴿ أَوِ التَّابِعِينَ غَيْرِ أُولِي الْإِرْبَةِ مِنَ الرِّجَالِ﴾ ’’یاایسے نو کر چاکر مرد کہ جو شہوت والے نہ ہوں‘‘ کی تفسیر میں ابنِ عباس رضی اللہ عنہما فرماتے ہیں:ان سے مراد وہ مرد ہیں جو لوگوں کے گھروں میں کام کاج کرتے ہوں اور سمجھدار نہ ہوں، انہیں عورتوں کی پرواہ ہوتی ہے اور نہ ہی وہ ان میں نفسانی رغبت رکھتے ہیں۔ امام شعبیؒ فرماتے ہیں:ان سے مراد وہ لوگ ہیں جنہیں عورتوں کی کوئی خواہش اور ضرورت نہیں ہوتی، طاؤسؒ اور حصنؒ کا بھی یہی قول ہے۔ امام مجاہدؒاللہ تعالیٰ کے فرمان: ﴿أَوِالطِّفْلِ الَّذِينَ لَمْ يَظْهَرُوا عَلَى عَوْرَاتِ النِّسَاءِ﴾ ’’یاایسے بچے جو عورتوں کی پردے کی باتوں سے مطلع نہ ہوں۔‘‘ کی تفسیر یوں کرتے ہیں کہ اس سے مراد وہ بچے ہیں جو چھوٹی عمر کی وجہ سے یہ تک نہیں جانتے ہوتے کہ عورتیں کیا ہیں؟ اور ابو زبیر جابر رضی اللہ عنہ سے روایت کرتے ہیں کہ اُمِ سلمہؓ نے نبی صلی اللہ علیہ وسلم سے سینگی لگوانے کے بارے میں نبی صلی اللہ علیہ وسلم سے اجازت طلب کی تو آپ صلی اللہ علیہ وسلم نے ابو طیبہ کو حکم فرمایاکہ وہ انہیں سینگی لگا دیں، راوی کہتے ہیں کہ چونکہ وہ امِ سلمہؓ کے رضاعی بھائی تھے یانا بالغ لڑکے تھے اور اللہ تعالیٰ نے غلاموں اور نابالغ بچوں کو پر دے کے ان تین اوقات میں خصوصی طور پر اجازت لے کر اندر آنے کاحکم فرمایا ہے:(۱)قبل ازفجر؛ جب میاں بیوی خلوت اختیار کرتے ہیں، (۲)دوپہر کے وقت (۳)نمازِعشاء کے بعد۔ ان تینوں اوقات کا بیان آیتِ استئذان یعنی اجازت طلب کرنے کے حکم کے بابت جو آیت نازل ہوئی تھی اس میں مذکور ہے، ملاحظہ ہو: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لِيَسْتَأْذِنْكُمُ الَّذِينَ مَلَكَتْ أَيْمَانُكُمْ وَالَّذِينَ لَمْ يَبْلُغُوا الْحُلُمَ مِنْكُمْ ثَلَاثَ مَرَّاتٍ مِنْ قَبْلِ صَلَاةِ الْفَجْرِ وَحِينَ تَضَعُونَ ثِيَابَكُمْ مِنَ الظَّهِيرَةِ وَمِنْ بَعْدِ صَلَاةِ الْعِشَاءِ ثَلَاثُ عَوْرَاتٍ لَكُمْ لَيْسَ عَلَيْكُمْ وَلَا عَلَيْهِمْ جُنَاحٌ بَعْدَهُنَّ طَوَّافُونَ عَلَيْكُمْ بَعْضُكُمْ عَلَى بَعْضٍ كَذَلِكَ يُبَيِّنُ اللَّهُ لَكُمُ الْآيَاتِ وَاللَّهُ عَلِيمٌ حَكِيمٌ﴾ [النور: ۵۹]. ’’اے ایمان والو!لازم ہے کہ تمہارے لونڈی غلام اور تمہارے وہ بچے جو ابھی عقل کی حدکو نہیں پہنچے ہیں، تین اوقات میں اجازت لے کر تمہارے پاس آیا کریں:صبح کی نماز سے پہلے، اور دوپہر کو جبکہ تم کپڑے اتار کر رکھ دیتے ہو اور عشاء کی نماز کے بعد۔ یہ تین وقت تمہارے لیے پردے کے وقت ہیں۔ ان کے بعد وہ بلا اجازت آئیں تو نہ تم پر کوئی گناہ ہے نہ ان پر، تمہیں ایک دوسرے کے پاس بار بار آنا ہی ہوتاہے۔ اس طرح اللہ تمہارے لیے اپنے ارشادات کی توضیح کرتا ہے اور وہ علیم وحکیم ہے۔‘‘"}],[606,"ثمامہ بن عبداللہ بن انس بیان کرتے ہیں کہ:\n’’سیدنا انس رضی اللہ عنہ خوشبو کا تحفہ ٹھکرایا نہیں کرتے تھے، اور ان کا مؤقف تھا کہ نبی صلی اللہ علیہ وسلم بھی خوشبو کو نہیں ٹھکراتے تھے۔‘‘","صحیح",{"k":"صحیح بخاری (5929)، سنن ترمذی (2789)۔"}],[607,"ابوہریرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’جسے خوشبو پیش کی جائے وہ اسے واپس نہ کرے، کیونکہ یہ انتہائی ہلکے سے وزن کی اور بہت ہی اچھی مہک والی ہوتی ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2253)، سنن أبوداؤد (4172)، سنن نسائی (5259)۔"}],[608,"نافع روایت کرتے ہیں کہ:\n’’ابنِ عمر رضی اللہ عنہما جب بھی خوشبو کی دھُونی لیتے توعُودکی لیتے جس میں کوئی اور چیز نہ ملی ہوتی، یاکافو رکوعُودکے ساتھ ملا کر لیتے اور فرماتے کہ رسول اللہ صلی اللہ علیہ وسلم بھی اسی طرح خوشبو لگایا کرتے تھے۔‘‘","صحیح",{"k":"صحیح مسلم (2254)۔"}],[609,"انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم کے پاس خوشبو کی ایک شیشی تھی جس سے آپ صلی اللہ علیہ وسلم خوشبو لگایا کرتے تھے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4162)، صحیح الجامع للألبانی (4831)۔"}],[610,"عمران بن حصین رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’میں ارغو ان پر سواری نہیں کرتا، نہ میں زرد لباس پہنتا ہوں اور نہ ہی ایسی قمیض کہ جس کی آستینوں پر ریشم کی کڑھائی کی گئی ہو۔ راوی کہتے ہیں کہ حسنؓ نے اپنی قمیض کے گریبان کی طرف اشارہ کیا، اور(آپ صلی اللہ علیہ وسلم نے)فرمایا:آگاہ رہو!مردوں کی خوشبو ایسی ہوکہ جس کی مہک تو ہو لیکن اس کا رنگ نہ ہو اور عورتوں کی خوشبو ایسی ہوکہ جس کا رنگ ہو لیکن مہک نہ ہو۔‘‘","صحیح",{"k":"سنن الکبری للبیهقی (3؍269)۔","f":"سعیدؒکہتے ہیں کہ ہم نے آپ صلی اللہ علیہ وسلم کے اس فرمان کو اس پر محمول کیا ہے کہ عورت کی ایسی خوشبو کا حکم اس وقت سے متعلق ہے جب وہ گھر سے باہر نکلے، لیکن اگر وہ گھر میں ہی ہو تو وہ خاوند کے سامنے جیسی چاہے خوشبو لگا سکتی ہے۔"}],[611,"ابوموسیٰ اشعری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جو بھی عورت معطر ہو کر لوگوں کے پاس سے گزرتی ہے تاکہ لوگوں کو اس کی خوشبو آئے تو وہ عورت زانیہ ہے، اور(اسے دیکھنے والی)ہرآنکھ زانیہ ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4173)، سنن ترمذی (2786)، صحیح الجامع للألبانی (323)۔"}],[612,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’ان کے پاس سے ایک عورت گزری جس سے بہت تیز خوشبو آرہی تھی، تو انہوں نے کہا:اے اللہ کی بندی!کیا تو مسجد میں جانا چاہ رہی ہے؟ اس نے جواب دیا:جی ہاں، تو آپؓ نے فرمایا:اس کے لیے تُونے خوشبو لگائی ہے؟ اس نے کہا:جی ہاں، تو ابوہریرہ رضی اللہ عنہ نے کہاکہ واپس جا اور غسل کر، کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:جو بھی عورت تیز خوشبو لگا کر مسجد کی طرف نکلتی ہے تو اللہ تعالیٰ تب تک اس کی نماز کو قبول نہیں فرما تاجب تک وہ واپس اپنے گھر آکر غسل نہیں کر لیتی۔‘‘","صحیح",{"k":"سنن أبوداؤد (4174)، سنن ابن ماجه (4002)، سلسلہ الأحادیث الصحیحہ (1031)۔"}],[613,"زینب ثقفیہ رضی اللہ عنہا رسول اللہ صلی اللہ علیہ وسلم سے روایت کرتی ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب تم میں سے کوئی عشاء کی نماز پڑھنے جائے تو وہ خوشبو کوچھُوئے بھی نہیں۔‘‘","صحیح",{"k":"صحیح مسلم (443)۔"}],[614,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جس عورت نے خوشبو کی دھُونی لی ہو وہ ہمارے ساتھ نمازِعشاء کے لیے (مسجد میں)نہ آئے۔‘‘","صحیح",{"k":"صحیح مسلم (444)، سنن أبوداؤد (4175)۔","f":"عرب لوگ خوشبو لگا نے کا ایک انداز یہ اپناتے تھے کہ وہ خوشبو کی دھونی لیا کرتے تھے، اس سے ان کے کپڑوں اور جسم میں خوشبورَچ بَس جاتی تھی اور بہت دیرتک ختم نہیں ہوتی تھی۔"}],[615,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’تم اللہ کی بند یوں کو مساجد میں جانے سے مت روکو، اور انہیں بھی چاہیے کہ جب وہ باہر نکلیں تو بغیر خوشو لگائے نکلیں۔‘‘","صحیح",{"k":"سنن أبوداؤد (565)، مسند أحمد (2؍438)، إرواء الغلیل للألبانی (515)۔"}],[616,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’عورت اپنے گھر میں نماز پڑھے یہ اس کے لیے اپنے حجرے میں نماز پڑھنے سے بہتر ہے، اور عورت اپنے حجرے میں نماز پڑھے یہ اس کے لیے اپنے گھر کے احاطے میں نماز پڑھنے سے بہتر ہے، اور وہ گھر کے احاطے میں نماز پڑھے تو یہ اس کے لیے مسجد میں نماز پڑھنے سے بہتر ہے۔‘‘","حسن",{"k":"السنن الکبری للبیهقی (3؍132)، سلسلہ الأحادیث الصحیحہ (2142)۔"}],[617,"ابنِ عمر رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’تم اپنی لونڈیوں کو مسجدوں(میں جانے)سے نہ روکو، البتہ ان کے گھر ان کے لیے بہتر ہیں۔‘‘","صحیح",{"k":"سنن أبوداؤد (567)، مسند أحمد (2؍43)، إرواء الغلیل للألبانی (515)۔"}],[618,"عمرہ، سیدہ عائشہ رضی اللہ عنہا سے روایت کرتی ہیں کہ آپؓ نے فرمایا:\n’’رسول اللہ صلی اللہ علیہ وسلم کی (وفات) کے بعد جو نئے نئے کام عورتوں نے اختیار کر لیے ہیں اگر رسول اللہ صلی اللہ علیہ وسلم انہیں دیکھ لیتے تو عورتوں کو مسجد میں آنے سے منع کردیتے جس طرح کہ بنی اسرائیل کی عورتوں کو منع کر دیا گیا تھا۔ ہم نے پوچھا:کیا بنی اسرائیل کی عورتوں کو منع کر دیا گیا تھا؟ انہوں نے جواب دیا:جی ہاں۔‘‘","صحیح",{"k":"صحیح بخاری (869)، صحیح مسلم (445)۔"}],[619,"ابنِ عباس رضی اللہ عنہما سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’اِثمد(کا استعمال)اپنے اوپر لازم کرلو، کیونکہ یہ نظر تیز کرتا ہے اور بال اُگاتا ہے۔ رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک سُرمے دانی ہوا کرتی تھی جس سے آپ صلی اللہ علیہ وسلم روزانہ رات کوسُرمے کی تین سلائیاں اس آنکھ میں ڈالتے تھے اور تین اس آنکھ میں۔‘‘","صحیح",{"k":"سنن ترمذی (1757)۔"}],[620,"سیدہ عائشہ رضی اللہ عنہا روایت کرتی ہیں کہ:\n’’ابوبکر رضی اللہ عنہ ان کے پاس تشریف لائے تو ان کے پاس دو بچیاں بیٹھی گار ہی تھیں اوردَف بجا رہی تھیں، رسول اللہ صلی اللہ علیہ وسلم کپڑے سے منہ ڈھانپے پڑے ہوئے تھے، ابوبکر رضی اللہ عنہ نے انہیں جھِڑکا تو رسول اللہ صلی اللہ علیہ وسلم نے اپنے چہرے سے کپڑا ہٹایا اور فرمایا:اے ابوبکر!انہیں چھوڑ دو، کیونکہ یہ عید کے دِن ہیں۔ یہ منٰی کے دِن تھے اور رسول اللہ صلی اللہ علیہ وسلم مدینہ میں تھے۔ سیدہ عائشہؓ فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم مجھے اپنے کپڑے کے ساتھ پردے میں کررہے تھے اور میں ان حبشی لوگوں کی طرف دیکھ رہی تھی جو مسجد میں کھیل رہے تھے، اور اس وقت میں ابھی بچی تھی۔‘‘","صحیح",{"k":"صحیح بخاری (949)، صحیح مسلم (892)۔"}],[621,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ:\n’’اللہ کی قسم!میں نے اپنے حجرے کے دروازے پر رسول اللہ صلی اللہ علیہ وسلم کو کھڑے دیکھا اور حبشی لوگ نیزوں کے ساتھ مسجد میں کھیل رہے تھے، اور رسول اللہ صلی اللہ علیہ وسلم مجھے اپنے کپڑے سے چھپا رہے تھے تاکہ میں آپ صلی اللہ علیہ وسلم کے کان اور کندھے کے درمیان سے ان کے کھیل کو دیکھ سکوں، پھر آپ صلی اللہ علیہ وسلم میری وجہ سے کھڑے رہے یہاں تک کہ میں واپس آگئی، سوتم ایک نو عمر بچی کا کھیل کود دیکھنے کے شوق کا اندازہ لگا سکتے ہو، اور عائشہؓ نے اسی حدیث میں بیان فرمایا:یہ عید کادِن تھا اور سیاہ فام لوگ ڈھال اور نیزوں سے کھیل رہے تھے۔‘‘","صحیح",{"k":"صحیح بخاری (454)، صحیح مسلم (892)۔","f":"امام بیہقیؒ فرماتے ہیں کہ اس حدیث میں نیزوں کے ساتھ کھیلنے کے جواز پر دلالت ہے (اور یہ جواز)اس وجہ سے ہے کہ اس کھیل میں دشمن سے جنگ کی تیاری بھی ہوتی ہے، اور سیدہ عائشہ رضی اللہ عنہا کا ان کی طرف دیکھنا اس وجہ سے تھا کہ وہ ابھی چھوٹی بچی تھیں اور بالغ عورتوں کی عمرتک نہیں پہنچی تھیں اور یہ واقعہ پردے کاحکم نازل ہونے سے پہلے کا ہے۔ واللہ اعلم"}],[622,"بریدہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جس نے چوسر کھیلا اس نے گویا خنزیر کے گوشت اور اس کے خون میں اپنے ہاتھ ڈبوئے۔‘‘","صحیح",{"k":"صحیح مسلم (2260)، سنن أبوداؤد (4939)، سنن ابن ماجه (3763)۔"}],[623,"ابوموسیٰ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جس نے چوسر کے ساتھ کھیلا اس نے اللہ تعالٰی اور اس کے رسول صلی اللہ علیہ وسلم کی نافرمانی کی۔‘‘","حسن",{"k":"سنن أبوداؤد (4937)، سنن ابن ماجه (3762)، إرواء الغلیل للألبانی (2670)۔"}],[624,"امام شافعی رحمہ اللہ فرماتے ہیں کہ اس کی ممانعت تو چوسر سے بھی بالا ولٰی ہے، اور آپؒ نے یہ چوسر سے کھیلنے کی ممانعت کے بارے میں ثبوتِ خبر کی بناء پر فرمایا ہے۔ علاوہ ازیں شطرنج کی کراہیت پرنص بھی وارد ہے کہ سیدنا علی رضی اللہ عنہ فرمایا کرتے تھے:\n’’شطرنج عجمیوں کاجُواہے۔‘‘","",{"k":"السنن الکبری للبیهقی (10؍358)، شعب الإیمان للبیهقی (8؍468)، مصنف ابن أبی شیبہ (5؍286)۔"}],[625,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے ایک آدمی کو دیکھا کہ وہ کبوتری کا پیچھا کر رہا تھا، تو آپ صلی اللہ علیہ وسلم نے فرمایا:شیطان، شیطانی کاموں کے پیچھے ہی چلتا ہے۔‘‘","حسن",{"k":"سنن أبوداؤد (4940)، سنن ابن ماجه (3765)، صحیح الجامع للألبانی (3724)۔"}],[626,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ:\n’’میں رسول اللہ صلی اللہ علیہ وسلم کے ہاں لڑکیوں کے ساتھ کھیلا کرتی تھی، میری سہیلیاں میرے پاس آجایا کرتی تھیں اور رسول اللہ صلی اللہ علیہ وسلم کو دیکھ کر بھاگ جاتی تھیں، فرماتی ہیں کہ نبی صلی اللہ علیہ وسلم انہیں میرے پاس بھیج دیا کرتے تھے اور وہ میرے ساتھ کھیلتی تھیں۔‘‘","صحیح",{"k":"صحیح بخاری (6130)، صحیح مسلم (2440)۔","f":"سیدہ عائشہ رضی اللہ عنہا سے رسول اللہ صلی اللہ علیہ وسلم کے سامنے جھولا تیار کرنے کے بارے میں ایک روایت مروی ہے، اور آپؓ فرماتی ہیں کہ «أَتَتْنِي أُمُّ رُومَانَ وَأَنَا عَلَى أُرْجُوحَةٍ» ’’میرے پاس اُمِ رومان آئیں اور میں جھُولے میں بیٹھی ہوئی تھی۔‘‘(صحيح مسلم، کتاب الحج، باب تزويج الأب البكر الصغيرة، ح:۱۴۲۲)یہ مدینہ آمد کے ابتدائی دنوں کا واقعہ ہے۔\n«اَلْمَرَاجِيح» جمع ہے الأرجوحةكى، اور اس کا معنٰی پھسلنے اور جھولنے کا تختہ ہے، یعنی گھروں میں مستعمل بچوں کے جھولوں کے علاوہ پار کوں اور تفریحی مقامات پر لگے جھولے بھی اسی میں شامل ہیں۔ اور ان کے بابت درست بات یہی ہے کہ جھولے وغیرہ میں بیٹھنا ممنوع نہیں ہے، اس بارے میں سیدہ عائشہ رضی اللہ عنہا کا عمل موجود ہے جو صحیح مسلم کی روایت میں بیان ہوا ہے، چنانچہ اس سے جواز کی طرف اشارہ ملتا ہے۔ البتہ یہ صرف بچوں کے لیے ہی ہونے چاہییں کیونکہ کسی عقلمند اور سنجیدہ شخص کے لیے یہ زیبا نہیں ہے کہ وہ ایسی چیزوں سے جی للچائے، اور سیدہ عائشہؓ کا یہ عمل بھی ان کے بچپن کے زمانے کا ہے، جیسا کہ اسی روایت میں مذکور ہے کہ یہ واقعہ مدینہ آمد کے ابتدائی دنوں کا ہے، اور مدینہ آمد کے وقت حضرت عائشہؓ کی عمر آٹھ اور نو برس کے درمیان تھی۔\nیعنی بچیوں کا آپس میں کھیلنا کُودنا جائز ہے۔"}],[627,"شرید رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’میں نے نبی صلی اللہ علیہ وسلم کواُمیہ بن ابی صلت کے اشعار کے سوقافیے سنائے، آپ صلی اللہ علیہ وسلم ہرشعرپہ فرماتے کہ اور سناؤ، اور سناؤ۔ پھر آپ صلی اللہ علیہ وسلم نے فرمایا:اس کے شعروں سے لگتا ہے کہ قریب تھا کہ وہ مسلمان ہوجاتا۔‘‘","صحیح",{"k":"صحیح مسلم (2255)، مسند أحمد (4؍389)۔","f":"بغیر ساز کے گانے کے متعلق امام شافعیؒ فرماتے ہیں کہ اگر کوئی شخص اسے پیشہ بنا لے تو اس کی گواہی قبول نہیں کی جائے گی کیونکہ یہ ناپسندیدہ شُغل ہے جو باطل کے مشابہ ہے اور ایسے شخص کو بیوقوف اور غیر مہذب قرار دیا جائے گاا گرچہ یہ فعل حرام نہیں ہے، لیکن اگر کوئی شخص اپنے آپ کو ایسے گانے کی طرف منسوب نہیں کرتا اور نہ اسے اس کے لیے کچھ انعام دیا جاتا ہے اور نہ اس پر کوئی سزا عائد ہوتی ہے بلکہ وہ بس اسی قدر معروف ہوتاہے کہ وہ بعض حالتوں میں گنگناتا ہے تو ایسے شخص کاحقِ شہادت ختم نہیں ہوگا۔ اس کی دلیل میں سیدہ عائشہ رضی اللہ عنہا سے مروی وہ روایت ہے جس میں یہ بیان ہے کہ سیدنا ابوبکر رضی اللہ عنہ یومِ بعاث کو ان کے پاس تشریف لائے تو دو بچیاں وہاں بیٹھی گار ہی تھیں حالانکہ وہ کوئی گانے والیاں نہیں تھیں، تو ابوبکر رضی اللہ عنہ نے کہا:رسول اللہ صلی اللہ علیہ وسلم کے گھر میں یہ شیطانی باجے؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:اے ابوبکر!ہرقوم کا ایک خوشی کادِن ہوتاہے اور یہ ہمارا خوشی کادِن ہے۔(صحيح بخارى، كتاب الجمعة، باب سنة العيدين لأهل الإسلام، ح:۹۵۲- صحيح مسلم، كتاب صلاة العيدين، باب الرخصة في اللعب الذي لا معصية فيه في أيام العيد، ح:۸۹۲) اسی طرح بہت سے صحابہ کرام رضی اللہ عنہم سے گنگنا کر اشعار پڑھنا مروی ہے اور رسول اللہ صلی اللہ علیہ وسلم سے بھی بدویوں کے گیت اور حدی سننا ثابت ہے۔ البتہ اس بات کا خیال رہے کہ وہ اشعار فحش الفاظ، غیر شرعی وغیر اخلاقی فقرات اور عشق و محبت کے اظہار والے کلمات پر مبنی نہ ہوں کیونکہ یہ ممنوع و حرام ہے۔ مذکورہ بالا روایت میں مذکور جو دو بچیاں گار ہی تھیں وہ اس وقت کی تہذیب کے مطابق پڑھے جانے والے وہ اشعار تھے جن میں ان کے آباء و اجداد کی بہادری یا اسلامی فتوحات کا ذکر تھا، یا پھر اللہ تعالیٰ کی حمد و ثناء اور نبی کریم صلی اللہ علیہ وسلم کی نعت بیان ہوتی تھی۔ تو ایسی چیزوں کو خوبصورت آواز اور اچھی طرز میں گا کر پڑھنا جائز ہے بلکہ صحابہ کرام رضی اللہ عنہم کا اس پر عمل موجود ہے۔ اگر کوئی شخص اس سے گانے گانا ثابت کرے تو اس کی بات قطعی طور پر نامعقول ہوگی، کیونکہ نقلاً بھی اس کی کوئی دلیل موجود نہ ہونے کے علاوہ عقلاً بھی یہ بات ناقابل تسلیم ہے کہ بنی صلی اللہ علیہ وسلم کی موجودگی میں ان بچیوں نے کوئی ایسے اشعار پڑھے ہوں کہ جو آج کل کے فحش گانوں کے مشابہ ہوں۔(معاذ اللہ(\nامام نوویؒ اس حدیث کی شرح میں فرماتے ہیں:اس حدیث سے معلوم ہوتاہے کہ رسول اللہ صلی اللہ علیہ وسلم نے امیہ بن صلت کے اشعار کو پسند فرمایا اور شریدؓسے مزید سنا نے کی خواہش ظاہر کی، کیونکہ ان میں توحیدِباری تعالیٰ اور قیامت کا ذکر تھا۔ اس سے ثابت ہوا کہ جن اشعار میں فحش مضمون نہ ہو ان کا پڑھنا اور سننا جائز ہے، خواہ زمانۂ جاہلیت کے ہی اشعار ہوں۔"}],[628,"اُبَی بن کعب رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’یقیناًبعض شعر بھی پُرحکمت ہوتے ہیں۔‘‘","صحیح",{"k":"صحیح بخاری (6145)، سنن أبوداؤد (5010)۔"}],[629,"انس بن مالک رضی اللہ عنہ سے مروی ہے کہ:\n’’سفر میں نبی صلی اللہ علیہ وسلم کا ایک حدی خواں ہوا کرتا تھا، اور انجشہ عورتوں کو لے کر چلا کرتے تھے اور براء بن عازبؓ مردوں کو لے کر چلا کرتے تھے۔‘‘","صحیح",{"k":"السنن الکبری للبیهقی (10؍227)۔","f":"حدی خواں سے مراد وہ شخص ہوتا تھا جو دور انِ سفر ایک مخصوص قسم کا گیت گاکر اونٹوں کو ہانکتا تھا اور اونٹ اس کی یہ خاص آوازسُن کر تیز چلا کرتے تھے، عرب اپنے اسفار میں ایسے حدی خوانوں کو عموماًساتھ رکھا کرتے تھے۔ تو یہاں جس گیت کا ذکر ہوا ہے وہ عشقیہ الفاظ وکلمات پر مشتمل ہو ائے نفس کی تکمیل کرنے والا گانا نہیں ہے بلکہ یہ محض اونٹوں کو چلا نے کے لیے گایا جاتا تھا۔"}],[630,"انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم کا ایک حدی خواں تھا جسے انجشہ کے نام سے پکارا جاتا تھا، اور میری والدہ نبی صلی اللہ علیہ وسلم کی ازواجِ مطہرات کے ساتھ تھیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا:اے انجشہ!اس طرح آرام سے لے کرچل جس طرح شیشوں کو لیجایا جاتا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (6202)، صحیح مسلم (2323)۔"}],[631,"البتہ نبی صلی اللہ علیہ وسلم کا جو یہ فرمان ہے کہ:\n’’آدمی کے لیے اپنا پیٹ شعروں سے بھرنے سے بہتر یہ ہے کہ وہ اسے پِیپ سے بھر لے۔ تو اس کا معنٰی یہ ہے کہ آدمی کا شعروں میں اس قدردِل لگنے لگ جائے کہ اشعار ہی اس پر غالب رہیں اور وہ اسے قرآنِ کرم کی تلاوت اورذِکرِالٰہی سے بھی غافل کردیں۔‘‘","صحیح",{"k":"صحیح بخاری (6155)، صحیح مسلم (2257)۔","f":"پیٹ بھرنے سے مراد یہ ہے کہ اسے بس اشعار سے ہی دلچسپی رہے اور اس کے علاوہ اسے کچھ آتا ہی نہ ہو۔ ویسے تو حمد ونعت، جہادی، فکری اور بامقصد اشعار پڑھنے میں چنداں کوئی قباحت نہیں لیکن اگر متذکرہ بالا صورت ان میں بھی پیدا ہو جائے یعنی جیسا کہ اچا مام بیہقیؒ نے اس حدیث کی شرح میں فرمایا ہے کہ اس پر اشعار کا اس قدر غلبہ ہوجائے کہ یہ عادت اسے تلاوتِ قرآن اورذِکرِالٰہی سے بھی غافل کردے، تو اس صورت میں نیکی اور اچھائی کے حامل اشعار پڑھنے اور سننے والا بھی اسی حدیث کا مصداق بن جائے گا، چہ جائیکہ وہ لغو وبے مقصد اشعار پڑھے اور سنے۔"}],[632,"ابو مالک اشعری رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’میری اُمت میں سے کچھ لوگ شرب پئیں گے اور وہ اس کا(نام بدل کر)کوئی اور نام رکھ لیں گے اور گانے والیاں انہیں ساز بجا کر گانے سنائیں گی، اللہ تعالیٰ انہیں زمین میں دھنسا دیں گے اور انہیں بندر اور خنزیر بنا دیں گے۔‘‘","صحیح",{"k":"سنن ابن ماجه (4020)، سلسلہ الأحادیث الصحیحہ (90)۔","f":"امام بیہقیؒ فرماتے ہیں: اَلْحَجَلسے مراد یہ ہے کہ خوشی میں ایک پاؤں کواُٹھا کراُچھلناکُودنا۔ جب انسان ایسا اللہ رب العزت کی عطا کردہ کسی ایک نعمت یاتمام نعمتوں پر خوشی کے جذبات سے لبریز ہو کر کرے تو اس میں کچھ حرج نہیں ہے، لیکن جب کوئی اس طرح جھُومے اور ناچے کہ جو مردوں کے اخلاق وعادات کے منافی ہو تو ایسا کرنا مکروہ ہے کیونکہ اس سے عورتوں کی مشابہت لازم آتی ہے۔"}],[633,"ابنِ عباس رضی اللہ عنہما نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’یقیناًاللہ تعالیٰ نے تم پر شراب، جُوااورطبلہ حرام کیا ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (3696)، مسند أحمد (2؍165)، صحیح الجامع للألبانی (1748)۔"}],[634,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’گھنٹی شیطان کی بانسری ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2114)، سنن أبوداؤد (2556)۔"}],[635,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’فرشتے اس جماعت (قافلے)کی صحبت اختیار نہیں کرتے جس جماعت میں گھنٹی اور کتا ہو۔‘‘","صحیح",{"k":"صحیح مسلم (2113)، سنن أبوداؤد (2555)، سنن ترمذی (1703)۔"}],[636,"ابو بشیر انصاری رضی اللہ عنہ روایت کرتے ہیں کہ:\n’’کسی سفر میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے کہ آپ صلی اللہ علیہ وسلم نے اپنے غلام زیدؓکو(یہ اعلان کرنے کے لیے)بھیجا، جبکہ لوگ اپنی خواب گاہوں میں تھے، کہ جس بھی اونٹ کے گلے میں تانت کا ہار ہو، یا(فرمایا:)جو بھی ہار ہو وہ کاٹ دیا جائے۔امام مالکؒ فرماتے ہیں کہ یہ نظر کی وجہ سے ہوتے تھے۔‘‘","صحیح",{"k":"صحیح بخاری (3005)، صحیح مسلم (2115)۔","f":"عرب اپنے اونٹوں کو نظرلگ جانے کے خدشے کی وجہ سے ان کے گلے میں پیتل یاتانبے کی تار کا بنا ہوا ہار پہنا دیا کرتے تھے، تاکہ وہ نظرِبدسے محفوظ رہے، جیسا کہ ہمارے ہاں بھی گاڑی، دکان یامکان وغیرہ پر ایسی ہی کوئی چیز بلکہ جُوتاتک لٹکا دیا جاتا ہے اور اسے نظر لگنے سے مانع سمجھا جاتا ہے، یہ انتہائی لغو اوربے فائدہ امور ہیں کیونکہ بہ فرمانِ نبوی صلی اللہ علیہ وسلم ایسی چیزیں اللہ کی لکھی ہوئی تقدیر کو نہیں مٹا سکتیں اور جو کچھ اللہ تعالٰی نے تقدیر میں لکھ دیا ہے وہ ان کے باوجود بھی ہو کر ہی رہتا ہے۔ چونکہ یہ تقدیر کا اور اعتقادی مسئلہ تھا اس لیے نبی صلی اللہ علیہ وسلم نے منع فرمایا اور ہرمسلمان کو اس فاسد سوچ کو ختم کرکے تقدیر پر کامل ایمان رکھنا چاہیے۔"}],[637,"ابنِ عباس رضی اللہ عنہما بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے مشکیزے کے منہ سے اپنا منہ لگا کر پینے سے اورسُست وکاہل جا نورا ورلِیدکھا نے والے جانور پر سواری کرنے سے منع فرمایا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (5629)۔"}],[638,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے اس بات سے منع فرمایا ہے کہ مشکیزے کے منہ سے اپنا منہ لگا کر پانے پیا جائے اورسُست وکاہل جانور پر سواری کی جائے۔‘‘","",{}],[639,"ابنِ عمر رضی اللہ عنہ فرماتے ہیں کہ:\n’’لِیدکھا نے والے جانور پر سواری کرنے سے منع کیا گیا ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (2557)۔"}],[640,"ابنِ عمر رضی اللہ عنہما سے روایت ہے کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے لِیدکھا نے والے اونٹوں پر سواری کرنے اور ان کا دودھ پینے سے منع فرمایا۔‘‘","صحیح",{"k":"سنن أبوداؤد (2558)۔"}],[641,"جابربن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے چہرے کو گود نے اور چہرے پہ مارنے سے منع فرمایا۔‘‘","صحیح",{"k":"صحیح مسلم (2116)، سنن ترمذی (1710)۔"}],[642,"ابوہریرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’اپنے جانوروں کی پِیٹھوں کو منبر بنا نے سے بچو، کیونکہ اللہ تعالیٰ نے انہیں تمہارے تابع اس لیے کیا ہے تاکہ یہ تمہیں ایسے شہر پہنچا سکیں جہاں تمہارا اپنی جان کو مشقت میں ڈالے بغیر پہنچنا ممکن نہ ہو، اور اللہ تعالیٰ نے تمہارے لیے زمین کو بنایا ہے سوتم اپنی ضروریات اس پر پوری کر لیا کرو۔‘‘","صحیح",{"k":"سنن أبوداؤد (2567)، سلسلہ الأحادیث الصحیحہ (22)۔"}],[643,"معاذبن انس رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’تم ان جانوروں پر مکمل طور پر سواری کرو، ان پر قرار پکڑو اور انہیں کر سیاں مت بناؤ۔‘‘","صحیح",{"k":"مسند أحمد (3؍440)، صحیح ابن حبان (2002)، مستدرک حاکم (1؍444)، سلسلہ الأحادیث الصحیحہ (21)۔","f":"منبر اور کر سیاں بنانے کا مطلب یہ ہے کہ انہیں کھڑا کرکے اوپر مت بیٹھ رہو اور انہیں بے جان مت سمجھو۔ بلکہ اگر کہیں کچھ دیر ٹھہرنا یا کسی سے باتیں کرنا یا کسی کے انتظار میں رکنا مقصود ہو تو اس صورت میں جانور کے اوپر سے اُتر جائے اور جانور کو بٹھا دے، تا کہ وہ اس شخص کا بوجھ اٹھائے تکلیف میں مبتلا نہ کھڑا رہے۔"}],[644,"ابنِ عباس رضی اللہ عنہما بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم اپنے صحابہؓ کو کہیں بھیجتے تو بقیع الغرقد(جنت البقیع)تک ان کے ساتھ آتے، پھر فرماتے: «اِنْطَلِقُوا عَلَى اسْمِ اللّٰهِ، اَللّٰهُمَّ أَعِنْهُمْ» ’’اللہ کے نام پرچل پڑو، اے اللہ!ان کی مدد فرما۔‘‘ اور ایک روایت میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب کسی لشکر کو رخصت فرماتے تو عقبۃ الوداع کے پاس پہنچ کر(یہ دعا)فرماتے: «أَسْتَوْدِعُ اللّٰهَ دِينَكُمْ وَأَمَانَتَكُمْ وَخَوَاتِمَ أَعْمَالِكُمْ» ’’میں تمہارے دِین، تمہاری امانتیں اور تمہارے اعمال کے اچھے خاتموں کو اللہ کے حوالے کرتا ہوں۔‘‘","صحیح",{"k":"السنن الکبری للبیهقی (7؍272)، عمل الیوم واللیلہ لابن السنی (498)۔"}],[645,"ابو لاس خزاعی بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے ہمیں(یعنی)کمزور لوگوں کوحج(کے سفر)کے لیے صدقے کے اونٹوں پر سوار کر دیا، تو انہوں نے کہا:اے اللہ کے رسول!آپ صلی اللہ علیہ وسلم ہمیں ان پر کیوں سوار کر رہے ہیں؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:کوئی اونٹ ایسا نہیں جس کی کوہان پہ شیطان نہ ہو، سوجب تم ان پر سواری کرو تو اللہ کا نام لو جیسا کہ اس نے تمہیں حکم دیا ہے، پھر ان کو اپنے نفس کی خدمت میں لگا دو، کیونکہ انہوں نے (تمہیں)صرف اللہ کے لیے سوار کیا ہے۔‘‘","حسن",{"k":"مسند أحمد (4؍221)، مستدرک حاکم (1؍444)، سلسلہ الأحادیث الصحیحہ (227)۔","f":"اللہ کا ذکر اس طرح کرو جیسے اس نے حکم دیا ہے سے مراد یہ ہے کہ سوار ہوتے وقت وہی دعا پڑھو جو اس نے تمہیں بتلائی ہے، اور وہ دعا آئندہ حدیث میں مذکور ہے۔"}],[646,"علی بن ربیعہ بیان کرتے ہیں کہ:\n’’وہ سیدنا علی رضی اللہ عنہ کے پاس موجود تھے، جب وہ سوار ہوئے تو انہوں نے اپنا پاؤں رکاب میں سوار رکھا اوربِسْمِ اللّٰهِپڑھی، پھرجب درست ہو کر بیٹھ گئے «تواَلْحَمْدُ» لِلَّهِپڑھا اور پھر یہ دعا پڑھی: «سُبْحَانَ الَّذِي سَخَّرَ لَنَا هٰذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ، وَإِنَّا إِلٰى رَبِّنَا لَمُنْقَلِبُونَ» ’’بہت پاک ہے وہ ذات جس نے اس سواری کو ہمارے تابع کیا، حالانکہ ہم اس پر قابو پانے والے نہ تھے، اور یقیناًہم اپنے پروردگار کی طرف لوٹ کر جا نے والے ہيں۔‘‘ پھر آپ نے تین مرتبہ «اَلْحَمْدُ لِلّٰهِ» اور تین مرتبہ «اَللّٰهُ أَكْبَرُ» کہا، پھر یہ دعا پڑھی: «لَا إِلٰهَ إِلَّا أَنْتَ، ظَلَمْتُ نَفْسِي فَاغْفِرْ لِي إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ» ’’تیرے سوا کوئی معبود نہیں ہے، میں اپنی جان پر ظلم کر بیٹھا ہوں؛ سوتو مجھے بخش دے، یقیناًتیرے سوا کوئی بھی گناہوں کو نہیں بخش سکتا۔‘‘ پھر آپ ہنس پڑے۔ پوچھا گیا:اے امیر المومنین!کس بات نے آپ کو ہنسایا ہے؟ تو انہوں نے جواب دیا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو اسی طرح کرتے دیکھا جیسے میں نے کیا اور اسی طرح کہتے دیکھا جیسے میں نے کہا، پھر آپ صلی اللہ علیہ وسلم ہنس پڑے، ہم نے عرض کیا:اے اللہ کے نبی!کس بات نے آپ کو ہنسایا ہے؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:بندے پر تعجب ہے کہ جب وہ کہتا ہے کہ تیرے سوا کوئی معبود نہیں ہے، میں اپنی جان پر ظلم کر بیٹھا ہوں؛ سوتو مجھے بخش دے، یقیناًتیرے سوا کوئی بھی گناہوں کو نہیں بخش سکتا۔تو وہ یہ بات جانتا ہوتا ہے کہ اس کے سوا گناہوں کو کوئی بخش نہیں سکتا۔‘‘","حسن",{"k":"مسند أحمد (1؍97)، عمل الیوم واللیلہ لابن السنی (490)۔"}],[647,"عبداللہ بن سرجس بیان کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم جب سفر کرتے تو پانچ چیزوں سے پناہ مانگا کرتے تھے:سفر کی مشقتوں سے، رنجیدہ ومحروم لوٹنے سے، خیر کے بعدشر قبول کرنے سے، مظلوم کی بددعا سے اور اپنے اہلِ خانہ اور مال میں برائی دیکھنے سے۔‘‘","صحیح",{"k":"صحیح مسلم (1343)، سنن ترمذی (3439)، سنن نسائی (5498)۔","f":"خیر کے بعدشر قبول کرنے سے مراد یہ ہے کہ اسلام قبول کر لینے کے بعد دوبارہ کفر اختیار کرنے سے پناہ یادو سرا مطلب یہ ہے کہ اطاعت بجا لانے کے بعد معصیت کا ارتکاب کرنے سے پناہ۔"}],[648,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب تم سرسبز وشاداب زمین میں سفر کرو تو اونٹوں کو زمین سے ان کاحق دو، جب تم قحط زدہ زمین پر سفر کرو تو اس پر سے جلدی گزر جاؤ اورجب تم رات کو آرام کے لیے کہیں پڑاؤ ڈالو تو راستے سے ہٹ کر پڑاؤ کرو، کیونکہ رات کے وقت یہ رینگنے والے جانوروں اور کیڑے مکوڑوں کا ٹھکانہ ہوتاہے۔ اور انس بن مالک رضی اللہ عنہ سے مروی ایک حدیث میں ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا:رات کو سفر کیا کرو، کیونکہ رات کو زمین لپیٹ دی جاتی ہے۔‘‘","صحیح",{"k":"صحیح مسلم (1926)، سنن أبوداؤد (2569)، سنن ترمذی (2858)۔"}],[649,"ابوقتادہ رضی اللہ عنہ روایت کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم جب رات کو سفر سے واپس آتے تو اپنے دائیں پہلو پر لیٹ جاتے اورجب صبح سے کچھ دیر پہلے آتے تو اپنے بازو کو کھڑا کے اپنے سرکو اپنی ہتھیلی پر رکھ لیتے تھے۔‘‘","صحیح",{"k":"مسند أحمد (5؍298)، صحیح ابن خزیمہ (2558)، صحیح الجامع للألبانی (4752)۔","f":"صبح سے کچھ دیر پہلے سونے کی اس خاص کیفیت کی وجہ یہ ہوتی تھی کہ صبح کا وقت قریب ہوتا تھا اور اس کیفیت میں سونے سے چونکہ نیند زیادہ گہری نہیں آتی اس لیے نماز فجر کے لیے بیدار ہو جانا زیادہ ممکن ہوتا تھا تا۔"}],[650,"ابنِ عمر رضی اللہ عنہما نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’اگر تم اکیلے سفر کرنے کے نقصانات کا پتہ چل جائے تو کوئی سوار رات کو اکیلا سفر نہ کرے۔‘‘","صحیح",{"k":"صحیح بخاری (2998)، مسند أحمد (2؍120)۔"}],[651,"عمروبن شعیب اپنے باپ کے حوالے سے اپنے دادا سے روایت کرتے ہیں کہ:\n’’ایک آدمی سفر سے واپس آیا تو رسول اللہ صلی اللہ علیہ وسلم نے (اس سے)دریافت فرمایا:تمہارے ساتھ کون تھا؟ اس نے کہا:میں نے اپنے ساتھ کسی کو نہیں لیا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:ایک سوار ایک شیطان ہے، دو سوار دو شیطان ہیں اور تین سوار قافلہ ہیں۔‘‘","صحیح",{"k":"سنن أبوداؤد (2607)، سنن ترمذی (1674)، سلسلہ الأحادیث الصحیحہ (62)۔"}],[652,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب تین آدمی سفر کر رہے ہوں تو انہیں اپنے میں سے ایک کو امیر بنا لینا چاہیے۔‘‘","صحیح",{"k":"سنن أبوداؤد (2609)، إرواء الغلیل للألبانی (2454)۔","f":"امیر بنا نے سے ہرکام منظم انداز سے ہو جاتا ہے اور سفری امور میں ہرشخص کو فرداًفرداًپریشان ہونے کی بہ جائے امیر کے ہی انتظام وانصرام سے بہ آسانی ہرضرورت پوری ہوجاتی ہے۔"}],[653,"سیدہ عائشہ رضی اللہ عنہا نے نبی صلی اللہ علیہ وسلم کی ہجرتِ مدینہ اور ابوبکر صدیق رضی اللہ عنہ کا آپ صلی اللہ علیہ وسلم کے ساتھ ہجرت کرنے کا قصہ بیان کرتے ہوئے فرمایا:\n’’جب آپ دونوں مکہ سے روانہ ہوئے تو آپ کے ساتھ عامربن فہیرہ بھی تھے، آپ اسی کے پیچھے پیچھے چلتے ہوئے مدینہ آن پہنچے۔‘‘","صحیح",{"k":"صحیح بخاری (3906)، السنن الکبری للبیهقی (5؍258)۔","f":"عامربن فہیرہ رضی اللہ عنہ کو آپ صلی اللہ علیہ وسلم نے سفر میں بہ طورِمعاون ساتھ لیا تھا اور انہوں نے مدینے کا راستہ بتانے میں آپ صلی اللہ علیہ وسلم کی مدد کی۔"}],[654,"ابوموسیٰ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’ہم ایک غزوے میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ روانہ ہوئے، ہم چھے لوگ تھے اور ہمارے پاس ایک اونٹ تھاجس پر ہم باری باری سوار ہوتے تھے۔‘‘","",{"k":"السنن الکبری للبیهقی (5؍258)۔"}],[655,"عبداللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’بدر کے دِن ہم دونوں ایک اونٹ پر سوار تھے اور تین آدمی ایک اونٹ پر، میرے ساتھی رسول اللہ صلی اللہ علیہ وسلم ، علیؓ اور ابولبابہ انصاریؓ تھے، اورجب ان کی باری آئی تو انہوں نے کہا:اے اللہ کے رسول!آپ صلی اللہ علیہ وسلم سوار رہیے، آپ صلی اللہ علیہ وسلم کے حصے کا ہم چل لیتے ہیں، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:یقیناًتم دونوں پیدل چلنے میں مجھ سے زیادہ طاقتور نہیں ہو اور نہ ہی میں تم دونوں کے مقابلے میں ثواب سے بے رغبتی اختیار کر سکتا ہوں۔‘‘","صحیح",{"k":"مسند أحمد (1؍422)، مسند الطیالسی (355)۔","f":"یعنی نبی صلی اللہ علیہ وسلم نے فرمایا کہ اگر تم ایثار کا جذبہ دکھا کر اجر و ثواب حاصل کرنا چاہتے ہو تو میں ایسا جذبہ کیوں نہ رکھوں؟"}],[656,"ابو بریدہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم چلے جارہے تھے کہ ایک آدمی آیا، اس کے پاس گدھا تھا، اس نے عرض کیا:اے اللہ کے رسول!آپ صلی اللہ علیہ وسلم سوار ہو جائیے میں پیچھے ہو جاتا ہوں، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:نہیں، تُواپنی سواری پر آگے بیٹھنے کا مجھ سے زیادہ حق رکھتا ہے، سوائے اس کے کہ تُواپناحق مجھے دے دے۔ اس نے کہاکہ میں نے اپناحق آپ صلی اللہ علیہ وسلم کو دیا، تو آپ صلی اللہ علیہ وسلم سوار ہو گئے۔‘‘","حسن",{"k":"سنن أبوداؤد (2572)، مسند أحمد (5؍53)۔"}],[657,"ابو سعید رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’ہم ایک سفر میں نبی صلی اللہ علیہ وسلم کے ساتھ تھے کہ ایک شخص اپنی سواری(کے جانور)پر آیا اور اسے دائیں بائیں پھیرنے لگا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:جس کے پاس زائد سواری ہو وہ اس شخص کو دے دے جس کے پاس سواری نہیں ہے اورجس کے پاس زائد سامانِ سفر ہے وہ اس کو دے دے جس کے پاس زادِراہ نہیں ہے۔ آپ صلی اللہ علیہ وسلم نے (اسی طرح)مال کی کئی قسموں کا ذکر فرمایا، یہاں تک کہ ہم نے یہ خیال کیاکہ ہم میں سے کسی کا بھی اس کے زائد مال میں کوئی حق نہیں ہے۔‘‘","صحیح",{"k":"صحیح مسلم (1728)، سنن أبوداؤد (1663)۔","f":"گویا جس کے پاس ضرورت سے زائد مال ہو اسے اس کو سنبھال نہیں رکھنا چاہیے بلکہ کسی ضرورت مند کی ضرورت پوری کر دینی چاہیے اور کسی محتاج و فقیر کو دے دینا چاہیے۔"}],[658,"جابربن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم سفر میں پیچھے رہا کرتے تھے اور کمزور لوگوں کو چلاتے، ان کے پیچھے پیچھے آتے اور ان کے لیے دعا فرماتے۔‘‘","صحیح",{"k":"سنن أبوداؤد (2639)، مستدرک حاکم (2؍115)، سلسلہ الأحادیث الصحیحہ (2120)۔"}],[659,"انس بن مالک رضی اللہ عنہ فرماتے ہیں کہ:\n’’میں جریربن عبداللہ رضی اللہ عنہ کے ساتھ تھا تو وہ میری خدمت کیا کرتے تھے حالانکہ وہ مجھ سے بڑے تھے، اور جریرؓفرماتے:میں نے انصار کو رسول اللہ صلی اللہ علیہ وسلم کا کچھ نہ کچھ کام کرتے ہی دیکھا ہے، چنانچہ میں جب بھی کسی انصاری کو دیکھتا ہوں تو اس کی عزت کرتا ہوں۔‘‘","صحیح",{"k":"صحیح بخاری (2888)، صحیح مسلم (2513)۔"}],[660,"عبداللہ بن عمرو رضی اللہ عنہما نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’اللہ تعالیٰ کی نظر میں بہترین ساتھی وہ ہے جو اپنے ساتھی کے لیے بہتر ہو اور اللہ تعالیٰ کے ہاں بہترین پڑوسی وہ ہے جو اپنے پڑوسی کے حق میں بہتر ہو۔‘‘","صحیح",{"k":"سنن ترمذی (1944)، مسند أحمد (2؍168)، سلسلہ الأحادیث الصحیحہ (103)۔"}],[661,"حارث بن شریح روایت کرتے ہیں کہ:\n’’وہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ(سفرپہ)روانہ ہوئے، یہاں تک کہ انہوں نے مکہ ومدینہ کے درمیان ایک مسجد میں آپ صلی اللہ علیہ وسلم کے ساتھ نماز ادا کی، پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:بلاشبہ مسلمان مسلمان کا بھائی ہے، جب وہ اسے ملے تو اس کے سلام کا ویسے ہی جواب دے جیسے اس نے سلام کیا ہویا پھر اس سے بہتر جواب دے، جب وہ اس سے کوئی مشورہ لے تو اس کی خیرخواہی کرے، جب وہ دشمنوں کے خلاف اس کی مدد کا طلبگار ہو تو وہ اس کی مدد کرے، جب راستہ سمجھنے میں اس سے تعاون کرنے کو کہے تو وہ اس کے لیے آسانی پیدا کرے اور اسے راستہ بتا دے، جب دشمن کے خلاف ادھار ہتھیار مانگے تو اسے دے دے لیکن جب وہ کسی مسلمان کے خلاف ادھار ہتھیار مانگے تومت دے اورجب وہ ڈھال ادھار مانگے تو دے دے اور عام استعمال کی چیزوں(کو استعمال کرنے)سے منع مت کرے۔ لوگوں نے پوچھا:اے اللہ کے رسول!عام استعمال کی چیزیں کیا ہیں؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:پانی، پتھر اور لوہا۔ پوچھا گیا:کونسا لوہا؟ آپ صلی اللہ علیہ وسلم نے فرمایا:تانبے کی ہنڈیا اور لو ہے کا کلہاڑاجس سے تم کام کرتے ہو۔ لوگوں نے عرض کیا:اور پتھر سے کیا مراد ہےَ آپ صلی اللہ علیہ وسلم نے فرمایا:پتھر کی ہنڈیا۔‘‘","",{}],[662,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’سفر عذاب کا ایک ٹُکڑا ہے، جو بندے کو سونے اور کھا نے پینے سے روک لیتا ہے، سوتم میں سے جب کوئی شخص اپنے ضروری کام سے فارغ ہوجائے تو اسے جلد ازجلد اپنے گھر واپس آجانا چاہیے۔‘‘","صحیح",{"k":"صحیح بخاری (1804)، صحیح مسلم (1927)۔","f":"سفر میں خواہ کتنی بھی سہو لیات میسر ہوں ان سب کے باوجود حضر جیسا آرام وسکون میسر نہیں آتا، کیونکہ سفر انسان کے کھانے پینے اور سونے سے مانع بن جاتا ہے اس لیے آپ صلی اللہ علیہ وسلم نے اسے عذاب کا ٹکڑا قرار دیا ہے۔"}],[663,"سیدنا عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم جب (دشمن کے) لشکروں (سے قتال) یاکسی چھوٹی جماعت سے یاحج وعمرے سے واپس لوٹتے اورجب وداع کی گھاٹی یاکنکریلی زمین پر پہنچ جاتے تو تین مرتبہ اللہ اکبر کہتے، پھر(یہ دعا)پڑھتے: «لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيكَ لَه، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، آيبُونَ تَائِبُونَ عَابِدُونَ سَاجِدُونَ، لِرَبِّنَا حَامِدُونَ، صَدَقَ اللّٰهُ وَعْدَهُ وَنَصَرَ عَبْدَهُ وَهَزَمَ الْأَحْزَابَ وَحْدَهُ» ’’اللہ تعالیٰ کے سوا کوئی معبود نہیں ہے، وہ یکتا ولا شریک ہے، اسی کی بادشاہت ہے اور اسی کو تمام ترتعریفات سزاوار ہیں اور وہ ہرچیز پر کامل قدرت رکھنے والا ہے، (ہم)لوٹ کر آنے والے، توبہ کرنے والے، عبادت کرنے والے، سجدہ ریز ہو نے والے اور اپنے پروردگار کی حمد وستائش بیان کرنے والے ہیں، اللہ تعالیٰ نے اپنا وعدہ سچ کر دکھایا، اپنے بندے کی نصرت فرمائی اور اس اکیلے نے ہی لشکروں کو شکست سے دو چار کر دیا۔‘‘","صحیح",{"k":"صحیح مسلم (1344)۔"}],[664,"انس بن مالک رضی اللہ عنہ روایت کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم (سفر سے واپسی پر)رات کو اپنے گھر والوں کے پاس نہیں آیا کرتے تھے، بلکہ صبح یاشام کو تشریف لاتے تھے۔‘‘","صحیح",{"k":"صحیح بخاری (1800)، صحیح مسلم (1928)۔","f":"اس حدیث میں نبی صلی اللہ علیہ وسلم کا عمل مذکور ہوا ہے، جبکہ ایک روایت میں یہ الفاظ مذکور ہیں کہ نبی صلی اللہ علیہ وسلم نے سفر سے واپسی پر رات کو گھر آنے سے منع فرمایا ہے۔ (صحیح بخاری:۱۸۰۱) اور یہ ممانعت اس لیے ہے کہ کیا پتہ گھر میں بیوی کس حالت میں ہو، ایسا نہ ہو کہ آدمی بغیر بتائے اچانک گھر آجائے اور بیوی کسی ناپسندیدہ حالت میں ہو تو مرد کو برا لگے اور اس کے دل میں نفرت پیدا ہوجائے۔ اس لیے ادب کا تقاضا یہی ہے کہ سفر سے واپسی پر رات کو گھر نہ آیاجائے بلکہ دِن کے وقت آناچاہیے، تاکہ بیوی کو اچھی حالت بنانے اور صفائی ستھرائی کا موقع مل سکے، کیونکہ رات کے وقت بننا سنو رنا ذرا دشوار ہوتا ہے۔ اسی لیے آپ صلی اللہ علیہ وسلم بھی اگر رات کے وقت سفر سے واپس آتے تو رات گھر جانے کی بہ جائے مسجد میں آرام فرماتے تھے اور صبح کو گھر تشریف لاتے یا پھر کوشش کرتے کہ رات ڈھلنے سے پہلے یعنی شام کے وقت ہی واپس لوٹ آتے۔"}],[665,"ابنِ عباس رضی اللہ عنہما روایت کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم (جب مکہ)تشریف لائے تو بنو عبدالمطلب کے چھوٹے بچوں نے آپ صلی اللہ علیہ وسلم کا استقبال کیا تو آپ صلی اللہ علیہ وسلم نے ان میں سے ایک کو اپنے آگے بٹھا لیا اور دوسرے کو اپنے پیچھے۔‘‘","",{"k":"السنن الکبری للبیهقی (10372)۔"}],[666,"کعب بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم جہاد وغیرہ کے سفرپہ جمعرات کے علاوہ(کسی اوردِن)بہت کم ہی روانہ ہوا کرتے تھے۔‘‘","صحیح",{"k":"صحیح بخاری (2949)، سنن أبوداؤد (2605)۔","f":"آپ صلی اللہ علیہ وسلم کے جمعرات کے دِن کے سفر کرنے کی احتما لی وجہ یہ ہو سکتی ہے کہ جمعرات کے روز اللہ کے حضور لوگوں کے اعمال پیش کیے جاتے ہیں تو آپ صلی اللہ علیہ وسلم جہاد جیسے عظیم عمل کے لیے اس دِن کا انتخاب اسی وجہ سے فرماتے ہوں گے کہ آپ صلی اللہ علیہ وسلم کے پیش کیے جانے والے اعمال میں جہاد کا عمل بھی شامل ہو۔"}],[667,"کعب بن مالک رضی اللہ عنہ روایت کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم دِن کے وقت ہی سفر سے واپس آتے تھے، پھر پہلے مسجد میں تشریف لے جاتے، وہاں دو رکعت نماز ادا فرماتے پھر بیٹھ جاتے۔‘‘","صحیح",{"k":"صحیح بخاری (4418)، صحیح مسلم (2769)۔"}],[668,"جابربن عبداللہ رضی اللہ عنہ روایت کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم جب مدینہ تشریف لائے تو آپ صلی اللہ علیہ وسلم نے اونٹنی یاگائے کی قربانی کی۔‘‘","صحیح",{"k":"صحیح بخاری (3089)، سنن أبوداؤد (3747)۔"}],[669,"انس رضی اللہ عنہ روایت کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم جب چلتے تو آگے کو جھکے ہوتے تھے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4863)، مستدرک حاکم (4؍280)، سلسلہ الأحادیث الصحیحہ (2283)۔"}],[670,"انس رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم انتہائی وقار کے ساتھ چلا کرتے تھے۔‘‘","صحیح",{"k":"مسند أحمد (3؍27)، مستدرک حاکم (2؍606)۔"}],[671,"نافع بن جبیر بیان کرتے ہیں کہ:\n’’سیدنا علی رضی اللہ عنہ نے ہم سے نبی صلی اللہ علیہ وسلم کے اوصاف بیان کیے تو اس میں یہ بھی تھا کہ آپ صلی اللہ علیہ وسلم اپنی چال میں جھکاؤ رکھا کرتے تھے جیسے آپ صلی اللہ علیہ وسلم ڈھلوان میں چل رہے ہوں۔‘‘","صحیح",{"k":"سنن ترمذی (3637)۔"}],[672,"جابر رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’کچھ لوگوں نے نبی صلی اللہ علیہ وسلم کوچل نہ سکنے کی شکایت کی تو آپ صلی اللہ علیہ وسلم نے انہیں بلایا اور فرمایا:تیز چال سے چلو، ہم تیز چال سے چلے تو ہم نے محسوس کیاکہ (چلنے کا)یہ انداز ہم پر زیادہ ہلکا ہے۔‘‘","صحیح",{"k":"مستدرک حاکم (2؍101)، صحیح ابن خزیمہ (2537)، سلسلہ الأحادیث الصحیحہ (465)۔"}],[673,"ابنِ عمر رضی اللہ عنہما سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب تم میں سے کوئی چلتے چلتے تھک جائے تو اسے دوڑ اور عام چال کا درمیانی انداز اختیار کر لینا چاہیے کیونکہ یہ انداز اس کی تھکاوٹ کو ختم کر دیتا ہے۔‘‘","",{}],[674,"ابواُسید انصاری رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو مسجد سے نکلتے ہوئے یہ فرماتے سنا-اس وقت عورتیں مردوں کے ساتھ گھلی ملی ہوئی تھیں-آپ صلی اللہ علیہ وسلم نے (عورتوں سے)فرمایا:تمہارے لیے درست نہیں ہے کہ تم راستے کے عین درمیان میں چلو، بلکہ تم پر لازم ہے کہ راستے کے کنارے کنارے چلو۔ پھر (اس حکم کے بعد) عورت اس طرح دیوار کے ساتھ چپک کر چلتی کہ بالکل دیوار کے ساتھ لگ کر چلنے کی وجہ سے اس کا کپڑا کسی چیز کے ساتھ اٹک جاتا تھا۔‘‘","حسن",{"k":"سنن أبوداؤد (5272)، سلسلہ الأحادیث الصحیحہ (537)۔"}],[675,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’اگر تم انہیں ملو تو تم ان کو سلام کرنے میں پہل مت کرو اور انہیں تنگ ترین راستے سے گزرنے پہ مجبور کر دو۔‘‘","صحیح",{"k":"صحیح مسلم (2167)۔","f":"اس حدیث کی وضاحت پیچھے بھی گزر چکی ہے کہ راستے میں یہود و نصارٰی سے آمنا سامنا ہوجانے پر انہیں گزرنے کے لیے بالکل تھوڑا سا راستہ دیا جائے اور انہیں تنگ ہو کر گزرنے پر مجبور کر دیا جائے تا کہ انہیں اپنی کمتری اور اسلام کے غلبے کا احساس ہو سکے۔"}],[676,"اسود بیان کرتے ہیں کہ:\n’’میں نے عائشہ رضی اللہ عنہا سے پوچھا:رسول اللہ صلی اللہ علیہ وسلم گھر میں کیا کرتے تھے؟ تو انہوں نے جواب دیا:آپ صلی اللہ علیہ وسلم گھر کے کام کاج کیا کرتے تھے، ان کی مراد تھی کہ اپنے اہلِ خانہ کی خدمت میں مصروف رہتے تھے اورجب نماز کا وقت ہو جاتا تو نماز کے لیے تشریف لے جاتے۔ اور سیدہ عائشہ رضی اللہ عنہا ہی بیان کرتی ہیں کہ آپ صلی اللہ علیہ وسلم اپناجُوتا گانٹھ لیا کرتے، اپنے کپڑے کو پیوند لگا لیا کرتے اور اپنے گھر میں اسی طرح کام کاج کیا کرتے تھے جس طرح تم اپنے گھر میں کرتے ہو۔‘‘","صحیح",{"k":"صحیح بخاری (676)، سنن ترمذی (2489)۔"}],[677,"براء بن عازب رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا:\n’’جب تو(سونے کے لیے)بستر پر لیٹنے لگے تو اسی طرح وضوء کرجس طرح تُونماز کے لیے وضوء کرتاہے، پھر اپنی دائیں کروٹ پر سوجا اور یہ دعا پڑھ: «اَللّٰهُمَّ إِنِّي أَسْلَمْتُ وَجْهِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَهْبَةً وَرَغْبَةً إِلَيْكَ، لَا مَلْجَأَ وَلَا مَنْجَا مِنْكَ إِلَّا إِلَيْكَ، آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ» ’’اے اللہ!یقیناًمیں نے اپنا چہرہ تیرے تابع کردیا، اپنا معاملہ تیرے سپرد کر دیا اور اپنی پُشت تیری طرف جھُکا دی، ثواب کی رغبت کرتے ہوئے اور تیرے عذاب سے ڈرتے ہوئے، تیری بارگاہ کے علاوہ کوئی ٹھکانہ نہیں اور تیرے علاوہ کوئی جائے پناہ نہیں، میں تیری نازل کردہ کتاب اور تیرے بھیجے ہوئے رسول پر ایمان لایا۔‘‘ سواگر تجھے (اس رات)موت آگئی تو فطرت(یعنی دِینِ اسلام)پر ہی موت ہوگی اور اور سوتے وقت آخری بات جوتُوکہے وہ یہی کلمات ہوں۔‘‘","صحیح",{"k":"صحیح بخاری (6311)، صحیح مسلم (2710)۔"}],[678,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم منہ کے بل لیٹے ہوئے ایک آدمی کے پاس سے گزرے تو آپ صلی اللہ علیہ وسلم نے فرمایا:لیٹنے کی اس کیفیت کو اللہ تعالیٰ پسند نہیں فرماتا۔‘‘","صحیح",{"k":"مصنف ابن أبی شیبہ (5؍119)۔"}],[679,"علی بن شیبان رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جو شخص کسی بے پردہ چھت پر رات گزارے(یعنی سوئے)اس سے ذِمہ اُٹھ ہوگیا۔‘‘","صحیح",{"k":"سنن أبوداؤد (5041)، سلسلہ الأحادیث الصحیحہ (828)۔","f":"ذِمہ اُٹھ جانے سے مراد یہ ہے کہ اگر وہ چھت سے گرجا تاہے یاکسی اور نقصان سے دو چار ہوتا ہے تو اس کاذِمہ دار کوئی اور نہیں بلکہ وہ خود ہی ہوگا۔"}],[680,"جابر رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم سے سوال کیا:کیاجنّتی سوئیں گے بھی؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:نیند موت کی بہن ہے، اورجنّتیوں کو موت نہیں آئے گی۔‘‘","صحیح",{"k":"شعب الإیمان للبیهقی (4745)، سلسلہ الأحادیث الصحیحہ (1086)۔","f":"اعمال و خصائل دو ہی طرح کے ہوتے ہیں، ایک وہ جن کے اہتمام سے جنت کا حصول ممکن ہو جاتا ہے اور دوسرے وہ کہ جن کا ارتکاب جنت سے محرومی کا باعث بن جاتا ہے۔ کثرتِ نیند سے چونکہ بندہ بہت سے اعمال صالحہ نہیں کر پاتا بلکہ بسا اوقات فرائض بھی چھوٹ جاتے ہیں، اس لیے یہ جنت سے محرومی کے اسباب میں سے ایک ہے۔ اور امام بیہقیؒ نے اس حدیث سے یوں استدلال کیا ہے کہ جنتی لوگ جس طرح دنیا میں خوابِ غفلت میں ڈوبنے کی بہ جائے رب تعالیٰ کے حضور قیام اور رکوع و سجود میں رات بسر کر دیتے ہیں اور فرمانِ خداوندی: ﴿تَتَجَافٰى جُنُوبُهُمْ عَنِ الْمَضَاجِعِ﴾ (السجدة:۱۶) ’’یعنی اُن کے پہلو بستروں سے الگ رہتے ہیںــ‘‘ کے مصداق ہوتے ہیں، اسی طرح جنت میں ان کا یہ وصف رکھ دیا جائے گا کہ وہ سویا نہیں کریں گے۔ گویا یہ بھی عیش و آرام کی ایک دلکش صورت ہے کہ جنتی رہیں گے تو موج و مستی اور راحت و سکون میں، لیکن سونے کی فکر سے آزاد کر دیے جائیں گے۔"}],[681,"عبادہ بن صامت رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’میں نے رسول اللہ صلی اللہ علیہ وسلم سے اللہ تعالیٰ کے فرمان: ﴿لَهُمُ الْبُشْرَى فِي الْحَيَاةِ الدُّنْيَا وَفِي الْآخِرَةِ﴾ (کی تفسیر)کے بارے میں سوال کیا، تو آپ صلی اللہ علیہ وسلم نے فرمایا:اس سے مراد اچھا خواب ہے جو مسلمان دیکھتا ہے، یااس کے لیے دیکھا جاتا ہے۔‘‘","صحیح",{"k":"سنن ترمذی (2275)، سنن ابن ماجه (3898)، سلسلہ الأحادیث الصحیحہ (1786)۔","f":"اللہ تعالیٰ فرماتا ہے: ﴿لَهُمُ الْبُشْرٰى فِي الْحَيَاةِ الدُّنْيَا وَفِي الْآخِرَةِ﴾ [يونس: ۶۴] ’’ان کے لیے دنیوی اوراُخروی(دونوں)زندگیوں میں بشارت ہی بشارت ہے۔‘‘\n’اس کے لیے دیکھا جاتا ہے‘ سے مراد یہ ہے کہ کسی کو اس کے بارے میں اچھا خواب آئے، تو گویا اگر وہ خود یاکوئی اور اس کے متعلق اچھا خواب دیکھتا ہے تو یہ اس کے لیے فلاح ونجات کی بشارت ہے۔"}],[682,"ابوہریرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’آخری زمانے میں مومن کا خواب جھوٹ نہیں ہوگا، اور ان میں سب سے سچا خواب اس کا ہوگا جو ان کی نسبت زیادہ سچی بات کرتا ہوگا۔ خواب کی تین قسمیں ہیں:اچھا خواب، جو اللہ تعالیٰ کی طرف سے بشارت ہوتاہے، دوسرا وہ خواب جو آدمی اپنے دِل میں خیال سوچتا ہے اور تیسرا خواب شیطان کی طرف سے غم اور پریشانی کا ہوتا ہے، سوجب تم میں سے کوئی ناپسندیدہ خواب دیکھے تو اسے وہ خواب کسی کو بھی نہیں بتانا چاہیے، بلکہ اسے چاہیے کہ اُٹھ کر نماز پڑھے۔ ابوہریرہؓ فرماتے ہیں کہ مجھے (خواب میں)بیڑیاں پہنی ہوئی(نظر آنا)اچھا لگتا ہے اور گلے میں طوق پہنا(نظر آنا)بُرالگتا ہے کیونکہ بیڑیوں کی تعبیردِین میں ثابت قدمی ہے۔ کہتے ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا:مومن کا خواب نبوّت کے چھیالیس(۴۶)حصوں میں سے ایک ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2263)، سنن ترمذی (2291)۔"}],[683,"عبدربّہٖ بن سعید انصاری بیان کرتے ہیں کہ:\n’’میں نے ابوسلمہ بن عبدالرحمان رضی اللہ عنہ کو کہتے سنا کہ جب میں خواب دیکھتا ہوں تو بیمار پڑجاتا ہوں، میں نے یہ بات ابوقتادہؓ سے بیان کی تو انہوں نے کہاکہ میں بھی جب خواب دیکھتا تھا تو بیمار پڑجاتا تھا، یہاں تک کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:اچھے خواب اللہ کی طرف سے ہوتے ہیں، سوجب تم میں سے کوئی اچھا خواب دیکھے تو وہ اسی سے بیان کرے جس سے وہ محبت رکھتا ہو، اورجب کوئی بُراخواب دیکھے اور وہ (گھبرا کر)بیدار ہو جائے تو وہ اپنے دائیں جانب تین بار ہلکا ساتھُوکے اور اس خواب کے شرسے اور شیطان سے اللہ تعالٰی کی پناہ مانگے، پھر اپنا وہ خواب کسی کو بھی نہ بتلائے کیونکہ وہ اسے ہرگز کچھ نقصان نہیں پہنچا سکتا۔ اور ابو سلمہؓ سے مروی ایک روایت میں یہ اضافہ ہے کہ وہ کروٹ بدل کر لیٹ جائے۔‘‘","صحیح",{"k":"صحیح بخاری (6986)، صحیح مسلم (2261)۔"}],[684,"ابنِ عباس رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جس نے تصویر بنائی اسے عذاب میں مبتلا کیا جائے گااور اسے اس بات کا مکلّف بنایا جائے گاکہ وہ اس میں رُوح پھونکے اور وہ پھُونک نہیں پائے گا، اورجس نے جھُوٹا خواب بیان کیا اسے اس بات کا مکلّف بنایا جائے گاکہ وہ جو کے دو دانوں میں گِرہ باندھے اورجس نے کسی قوم کی ایسی بات کان لگا کر سنی کہ جس کا(کسی اور کو پتہ چلنا) وہ ناپسند کرتے ہوں تو روزِقیامت اس کے کانوں میں سِیسہ پگھلا کر ڈالا جائے گا۔‘‘","صحیح",{"k":"صحیح بخاری (7042)، سنن أبوداؤد (5024)۔"}],[685,"حذیفہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم جب رات کو اپنے بستر پر لیٹ جاتے تو اپنا ہاتھ اپنے رُخسار پر رکھتے، پھر یہ دعا پڑھتے: «اَللّٰهُمَّ بِاسْمِكَ أَمُوتُ» وَأَحْيٰی ’’اے اللہ!تیرے ہی نام سے میں مرتا ہوں اور زندہ ہوں گا۔‘‘ اورجب آپ صلی اللہ علیہ وسلم بیدار ہوتے تو یہ دعا پڑھتے: «اَلْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَمَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ» ’’تمام ترتعریفات اس ذات کے لیے ہیں جس نے مجھے موت دینے کے بعد زندہ کیا اور اسی کی طرف (قبروں سے)اُٹھ کر جانا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (6312)، سنن أبوداؤد (5049)۔"}],[686,"براء بن عازب رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم حکم فرماتے تھے کہ جب آدمی اپنے بستر پر لیٹے تو یہ دعا پڑھے: «اَللّٰهُمَّ أَسْلَمْتُ نَفْسِي إِلَيْكَ، وَوَجَّهْتُ وَجْهِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، لَا مَلْجَأَ وَلَا مَنْجَى مِنْكَ إِلَّا إِلَيْكَ، آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَنَبِيِّكَ الَّذِي» أَرْسَلْتَ’’اے اللہ!یقیناًمیں نے اپنا نفس تیرے تابع کردیا، اپنا چہرہ تیرے مطیع کردیا، اپنا معاملہ تیرے سپرد کر دیا اور اپنی پُشت کو تیری طرف جھُکا دیا، تیرے عذاب سے ڈرتے ہوئے، تیری بارگاہ کے علاوہ کوئی ٹھکانہ نہیں اور تیرے علاوہ کوئی جائے پناہ نہیں، میں تیری نازل کردہ کتاب اور تیرے بھیجے ہوئے نبی پر ایمان لایا۔‘‘","صحیح",{"k":"مصنف ابن أبی شیبہ (5؍119)۔"}],[687,"ابنِ عباس رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم رات کوجب تہجد کے لیے اُٹھتے تو یہ دعا پڑھتے:\n’’اے اللہ!تمام تعریفیں تیرے ہی لیے ہیں، تُوآسمانوں اور زمین کا نور ہے، سارے کلماتِ ستائش تجھ ہی کو سزاوار ہیں، توُہی آسمان وزمین اور ان میں موجود تمام اشیاء کو قائم رکھنے والا ہے، تُوحق ہے، تیرا وعدہ حق ہے، تیری بات حق ہے، تیری ملاقات حق ہے، جنّت وجہنّم حق ہیں اور انبیاء بھی حق ہیں، اے اللہ!تیرے لیے ہی میں مطیع وفرمانبر دار ہوا، تجھ ہی پر میں ایمان لایا، تیرے اوپر ہی میں نے بھروسہ کیا، میں نے تائب ہو کر تیری طرف ہی رجوع کیا، سبھی جھگڑوں کو تیرے سپرد کیا اورسب فیصلے بھی تجھ ہی پر چھوڑ دیے، تُومیرے اگلے پچھلے سبھی گناہوں کو بخش دے، جو بھی میں نے چھُپ کر کیے یاا علانیہ، تُوہی میرا معبود ہے اور تیرے سوا کوئی معبود نہیں ہے۔‘‘","صحیح",{"k":"صحیح بخاری (6317)، صحیح مسلم (769)۔","f":"عبادہ بن صامت رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:"}],[688,"عمروبن شعیب اپنے باپ کے حوالے سے اپنے دادا سے روایت کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم انہیں گھبراہٹ کی صورت میں پڑھے جانے والے یہ کلمات سکھایا کرتے تھے: «أَعُوذُ بِكَلِمَاتِ اللّٰهِ التَّامَّةِ مِنْ غَضَبِهِ، وَمَنْ شَرِّ عِبَادِهِ، وَمِنْ هَمَزَاتِ الشَّيَاطِينِ وَأَنْ يَحْضُرُونَ» ’’میں اللہ تعالیٰ کے کامل کلمات کے ساتھ اس کے غصے سے، اس کے بندوں کے شرسے، شیطانی وسوسوں سے اور میرے پاس شیاطین کے حاضر ہو نے سے پناہ مانگتا ہوں۔‘‘","حسن",{"k":"سنن أبوداؤد (3893)، سنن ترمذی (3528)۔"}],[689,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم مرض الموت میں معوذات(سورۃ الاخلاص، سورۃ الفلق اور سورۃ الناس)پڑھ کر اپنے اوپر پھونک مارا کرتے تھے۔ معمر کہتے ہیں کہ میں نے زہریؒ سے پوچھا کہ آپ صلی اللہ علیہ وسلم کیسے پھونک مارا کرتے تھے؟ تو انہوں نے جواب دیا کہ آپ صلی اللہ علیہ وسلم اپنے ہاتھوں پر پھونک مارا کرتے تھے پھر انہیں اپنے چہرے پر پھیر لیتے۔ سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں کہ جب آپ صلی اللہ علیہ وسلم کی حالت گراں ہوگئی تو پھر میں آپ صلی اللہ علیہ وسلم پر پھونک مارتی تھی اور آپ صلی اللہ علیہ وسلم کے ہاتھ کو آپ صلی اللہ علیہ وسلم کے جسم پر پھیرتی۔‘‘","",{}],[690,"عبدالعزیزبن صہیب بیان کرتے ہیں کہ:\n’’میں اور ثابت، انس بن مالک رضی اللہ عنہ کے پاس حاضر ہوئے تو ثابت نے کہا:میں بیمار ہو گیا ہوں، تو انسؓ نے فرمایا:کیا میں تمہیں رسول اللہ صلی اللہ علیہ وسلم کادَم نہ کردوں؟ ثابت نے جواب دیا:کیوں نہیں(ضرور کیجیے)، تو انس رضی اللہ عنہ نے یہ دعا پڑھی: «اَللّٰهُمَّ رَبَّ النَّاسِ مُذْهِبَ الْبَأْسِ، اشْفِ أَنْتَ الشَّافِي، لَا شَافِيَ إِلَّا أَنْتَ، اشْفِ شِفَاءً لَا يُغَادِرُ سَقَمًا» ’’اے اللہ!لوگوں کے پالنہار!تکلیف کودُورکرنے والے!(اس کو) شفا عطا فرما (کیونکہ) تو ہی شفا دینے والا ہے، تیرے سوا کوئی شفا نہیں دے سکتا، ایسی شفا عطا فرما کہ جو کوئی بیماری باقی نہ رہنے دے۔‘‘","صحیح",{"k":"صحیح بخاری (5742)، سنن أبوداؤد (4737)۔"}],[691,"ابنِ عباس رضی اللہ عنہما روایت کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم حسن وحسین رضی اللہ عنہما کو(ان الفاظ کے ساتھ)پناہ کی دعا دیا کرتے تھے: «أُعِيذُكُمَا بِكَلِمَاتِ اللّٰهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ» ’’میں اللہ تعالٰی کے پورے کلمات کے ساتھ تم دونوں کو ہرشیطان سے، ہرزہریلے جانور سے اور نقصان پہنچانے والی ہرنظرِبدسے(اللہ کی)پناہ میں دیتا ہوں۔‘‘ اور آپ صلی اللہ علیہ وسلم فرماتے تھے کہ ان الفاظ کے ساتھ اپنی اولاد کے لیے پناہ کی دعا کیا کرو، کیونکہ ابراہیم علیہ السلام بھی انہی الفاظ سے اسماعیل اور اسحاق علیہما السلام کے لیے پناہ کی دعا کیا کرتے تھے۔‘‘","صحیح",{"k":"صحیح بخاری (3371)۔"}],[692,"عوف بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’ہم عہدِجاہلیت میں دَم کیا کرتے تھے، تو ہم نے عرض کیا:اے اللہ کے رسول!اس کے بارے میں آپ صلی اللہ علیہ وسلم کیا فرماتے ہیں؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:اپنے اپنے دَم مجھے سناؤ، دَم کرنے میں کوئی حرج نہیں ہے، جب تک کہ اس میں شرکیہ الفاظ نہ ہوں۔‘‘","صحیح",{"k":"صحیح مسلم (2200)، سنن أبوداؤد (3886)۔"}],[693,"اسامہ بن شریک بیان کرتے ہیں کہ:\n’’میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور آپ صلی اللہ علیہ وسلم کے صحابہؓ اس طرح(منہمک ہو کر آپ صلی اللہ علیہ وسلم کی باتیں سن رہے)تھے کہ جیسے ان کے سروں پر پرندے بیٹھے ہوں، اور اطراف واکناف سے دیہاتی لوگ آآکر آپ صلی اللہ علیہ وسلم سے ایسی چیزوں کے بابت سوال کررہے تھے جن میں (گناہ کا)کوئی اندیشہ نہیں تھا، انہوں نے کہا:کیا ہم پر اس طرح کرنے میں کوئی گناہ ہے؟ کیا ہمیں ایسا کرنے پر کوئی گناہ ملے گا؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:اے اللہ کے بندو!اللہ تعالیٰ نے گناہ کواُٹھا لیا ہے، سوائے اس آدمی کے جس نے کسی بندے پر ظلم کرتے ہوئے اس کاحق کاٹ لیا تو اس طرح وہ گنہگار ہوگا اور ہلاکت میں پڑے گا۔ لوگوں نے دواء کے بارے میں پوچھا تو آپ صلی اللہ علیہ وسلم نے فرمایا:اے اللہ کے بندو!دواء لیا کرو، کیونکہ اللہ تعالیٰ نے کوئی بھی بیماری ایسی نہیں اتاری کہ جس کی دواء نہ اتاری ہو، سوائے ایک بیماری کے اور وہ شدید بڑھاپا ہے۔ راوی کہتے ہیں کہ نبی صلی اللہ علیہ وسلم سے پوچھا گیا کہ بندے کو عطا کی جانے والی بہترین چیز کیا ہے؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:اچھا خلاق۔‘‘","صحیح",{"k":"سنن ابن ماجه (3436)، مسند أحمد (4؍278)، سلسلہ الأحادیث الصحیحہ (433)۔"}],[694,"انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’تم جو بھی دواو علاج کرتے ہو ان سب سے افضل یافرمایا کہ ان سب سے بہتر دوا اور علاج سِینگی اورقُسطِ بحری ہے، اور تم اپنے بچوں کو’غمز‘کے ساتھ عذاب میں مبتلامت کیا کرو۔‘‘","صحیح",{"k":"صحیح بخاری (5696)، صحیح مسلم (1577)۔","f":"سِینگی لگانا(Cupping)قدیم طرزِعلاج ہے لیکن اس کے فوائد اور اس میں اللہ تعالٰی کی طرف سے رکھی گئی شفا کی حقیقت کوآج کے معالجین بھی تسلیم کیے بغیر نہیں رہ سکے۔ اس کا طریقِ کار یہ ہوتاہے کہ کسی تیز دھار چیز سے مریض کے جسم پرکَٹ لگائے جاتے ہیں اور پھر کسی چیز سے اس کا خون چُوس کر نکال دیا جاتا ہے، یوں جسم میں موجود فاسد خون نکل جاتا ہے اور صحیح خون اس کی جگہ لے لیتا ہے۔ قُسطِ بحری کوعُودِہندی بھی کہا جاتا ہے، یہ ہندوستان میں پیدا ہو نے والی ایک خوشبودار لکڑی ہے جوبہ طورِدوا استعمال ہوتی ہے۔ بچے کو حلق کی بیماری کی صورت میں اس کا تالُودبا کر علاج کیا جاتا ہے؛ اسے ’غمز‘ کہا جاتا ہے، یہ طریقِ علاج ہمارے ہاں بھی مروّج ہے، جسے ہم ’’گلااُٹھانا‘‘کہتے ہیں، نبی صلی اللہ علیہ وسلم نے اس سے منع فرمایا ہے اور اس ممانعت کی دو وجوہات بیان فرمائی ہیں:ُایک تو یہ کہ اس سے بچے کو بہت تکلیف ہوتی ہے اسی لیے آپ صلی اللہ علیہ وسلم نے اسے عذاب سے تشبیہ دی ہے اور دوسری وجہ یہ ہے کہ نبی صلی اللہ علیہ وسلم نے ہرعلاج کے متبادل کے طور پر جو مذکورہ دو علاج بتلا دیے ہیں انہی میں سے ایک کو اختیار کر لینا چاہیے اور یہی افضل وبہتر علاج ہے۔"}],[695,"انس بن مالک رضی اللہ عنہ سے مروی ہے:\n’’ان سے حجام(سینگی لگانے والے)کی کمائی کے بارے میں پوچھا گیا(کہ آیا وہ حلال ہے؟) تو انہوں نے جواب دیا کہ رسول اللہ صلی اللہ علیہ وسلم نے سینگی لگوائی اور آپ صلی اللہ علیہ وسلم کو سینگی لگانے والے ابو طیبہ تھے، تو آپ صلی اللہ علیہ وسلم نے اسے (بہ طورِاجرت)اناج کے دو صاع دینے کاحکم فرمایا، اور اس کے مالکوں سے بات کی تو انہوں نے اس کے لگان سے تخفیف کردی۔‘‘","صحیح",{"k":"صحیح بخاری (5696)، صحیح مسلم (1577)۔"}],[696,"انس رضی اللہ عنہ روایت کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم تین مرتبہ سینگی لگوایا کرتے تھے، دو مرتبہ گردن کی دونوں رگوں میں اور ایک مرتبہ کندھے اور گردن کے درمیان میں۔‘‘","صحیح",{"k":"سنن ترمذی (2051)، سنن ابن ماجه (3483)، سلسلہ الأحادیث الصحیحہ (908)۔"}],[697,"ابنِ عباس رضی اللہ عنہما بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے سردرد یاسر کی کسی اور مرض کی وجہ سے سرمیں سینگی لگوائی تھی۔‘‘","",{}],[698,"جابر رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے اُبَی بن کعب کی طرف ایک طبیب بھیجا، اس نے ان کی ایک رَگ کاٹی، پھر گرم لوہے سے اسے داغ دیا۔‘‘","صحیح",{"k":"صحیح مسلم (2207)، سنن أبوداؤد (3864)۔"}],[699,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جس نے (قمری مہینے کی)سترہ(۱۷)، اُنیس(۱۹)اوراِکیس(۲۱)تاریخ کو سینگی لگوائی تو وہ اس کے لیے ہربیماری سے شفابن جائے گی۔ ایک اور اسناد کے ساتھ ہے کہ:جس نے سوموار کے دِن (قمری)مہینے کے سترہ دِن گزر جا نے پر سینگی لگوائی تو اللہ تعالیٰ اس سے ایک سال پرانی بیماری بھی ختم كردے گا۔‘‘","حسن",{"k":"سنن أبوداؤد (3861)، مستدرک حاکم (4؍210)، سلسلہ الأحادیث الصحیحہ (622)۔"}],[700,"جابربن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’اگر تمہاری دوائیوں میں کوئی بھلائی ہے تو وہ سینگی لگوانے، شہد کے شربت یاآگ سے داغنے میں ہے، لیکن میں آگ سے داٖغنے کا علاج پسند نہیں کرتا۔‘‘","صحیح",{"k":"صحیح بخاری (5702)، صحیح مسلم (2205)۔"}],[701,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کلونجی کے بارے میں فرمایا:\n’’تم اس سیاہ دانے کو اپنے اوپر لازم کرلو، کیونکہ اس میں سوائے موت کے ہربیماری کی شفا ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2215)، سنن ترمذی (2041)، سنن ابن ماجه (3447)۔","f":"سیاہ دانے سے مراد کلونجی ہے، اس کے مختلف طرح کے استعمالات سے تمام بیماریوں کا علاج ممکن ہے۔"}],[702,"سعیدبن زیدبن عمروبن نفیل رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’کھنبی ’مَن‘ میں سے ہے جو بنی اسرائیل پر اتارا جاتا تھا، اور اس کا پانی آنکھ کے لیے شفا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (5708)، صحیح مسلم (2049)۔","f":"کھنبی ایک جنگلی بوٹی کا نام ہے اور یہ بنی اسرائیل پر اتارے جانے والے من وسلوٰی میں سے ’مَن‘کا ہی ایک حصہ ہے۔ نبی صلی اللہ علیہ وسلم نے اس کی خاصیت یہ بیان فرمائی ہے کہ یہ آنکھ کی بیماریوں کے لیے شفا کا باعث ہوتی ہے۔"}],[703,"سعد رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جو شخص صبح کے وقت سات عجوہ کھجوریں کھالے اسے اس دِن کوئی زہریا جا دو نقصان نہیں پہنچا سکے گا۔‘‘","صحیح",{"k":"صحیح بخاری (5768)، صحیح مسلم (2047)۔","f":"عجوہ مدینہ شریف کی کھجوروں کی بہترین قسم ہے اوربا سہولت مل جاتی ہے، زہریلے جانوروں اور شریر جادوگروں کے نقصانات سے بچنے کے لیے روزانہ سات کھجوریں کھانا چاہییں، جس سے مذکورہ فائدے کے علاوہ فرمانِ نبویؐ پر عمل کے صلے میں ثواب کا حصول بھی یقینی ہے۔"}],[704,"عبداللہ بن مسعود رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’یقیناًاللہ تعالیٰ نے کوئی بھی ایسی بیماری نہیں اتاری جس کے لیے اس نے شفا نہ رکھی ہو، سوائے موت کے، لہٰذا تم گائے کا دودھ لازماًپیا کرو کیونکہ یہ ہردرخت سے قصد کرتی ہے۔‘‘","صحیح",{"k":"مستدرک حاکم (4؍197)، سلسلہ الأحادیث الصحیحہ (518)۔","f":"ہردرخت سے قصد کرنے کا مطلب یہ ہے کہ گائے طرح طرح کے درختوں اور جڑی بوٹیوں سے چرتی ہے تو اس طرح اس کے دودھ میں تمام نباتات کی خاصیات شامل ہوجاتی ہیں اور اس کا دودھ ہرطرح کی بیماری کے لیے مفید وکارگربن جاتا ہے۔"}],[705,"سیدہ عائشہ رضی اللہ عنہا کے بارے میں مروی ہے کہ:\n’’آپ(یعنی عائشہؓ)مریض کے لیے اور میت کے غمزدہ اہلِ خانہ کے لیے اور تلبینہ پکانے کاحکم دیتیں، اور کہتیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے کہ تلبینہ بیمار شخص کے دِل کو تقویت پہنچاتا ہے اور اس کاغم دور کرتا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (5417)، صحیح مسلم (2216)۔"}],[706,"عقبہ بن عامر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’تم اپنے مریضوں کو کھا نے پینے پر مجبور نہ کیا کرو، کیونکہ اللہ تعالیٰ انہیں کھلاتا اور پلاتا ہے۔‘‘","صحیح",{"k":"سنن ترمذی (2040)، سنن ابن ماجه (3444)، سلسلہ الأحادیث الصحیحہ (727)۔"}],[707,"علقمہ بن وائل اپنے باپ سے روایت کرتے ہیں کہ:\n’’وہ لوگ نبی صلی اللہ علیہ وسلم کے پاس آئے اور ان میں جعفی قبیلے کا ایک آدمی تھا، اس نے نبی صلی اللہ علیہ وسلم سے شراب کے بارے میں سوال کیا تو آپ صلی اللہ علیہ وسلم نے منع فرمادیا، اس نے کہا:یہ تو ہمیں بہت فائدہ دیتی ہے، یہ دوا ہے۔ تو آپ صلی اللہ علیہ وسلم نے فرمایا:یقیناًیہ دو انہیں بلکہ بیماری ہے۔‘‘","صحیح",{"k":"صحیح مسلم (1984)، سنن ترمذی (2046)۔"}],[708,"ابودرداء رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’بلاشبہ اللہ تعالیٰ نے بیماری اور دوا(دونوں)نازل کی ہیں اور ہربیماری کے لیے دو ابھی بنائی ہے، لہٰذا تم دوا لیا کرو اور حرام چیز کوبہ طورِدوا استعمال کرنے سے اجتناب کرو۔‘‘","صحیح",{"k":"سنن أبوداؤد (3874)۔"}],[709,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے ناپاک دو اسے منع فرمایا ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (3870)، سنن ترمذی (2045)، سنن ابن ماجه (3459)، صحیح الجامع للألبانی (6878)۔","f":"مذکورہ بالا دونوں چیزوں یعنی حرام اور ناپاک سے مراد یہ ہے کہ وہ دو اجس سے علاج کیا جا رہا ہے نشہ آور ہویا اس میں کسی ناپاک چیز کا استعمال کیا گیا ہو، یہ دونوں صورتیں ممنوع ہیں خواہ کتنی ہی مجبوری ہو۔"}],[710,"اُمِ مبشر انصار یہ رضی اللہ عنہا، جو رسول اللہ صلی اللہ علیہ وسلم کی خالہ لگتی تھیں، بیان کرتی ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف لائے اور آپ صلی اللہ علیہ وسلم کے ساتھ علیؓ بھی تھے جو ابھی ابھی بیماری سے صحت یاب ہوئے تھے، گھر میں کھجوروں کا خوشہ لٹک رہاتھا، نبی صلی اللہ علیہ وسلم کھڑے ہوئے اور اس سے کھجوریں لینے لگے تو علیؓ بھی لینا شروع ہوگئے تو آپ صلی اللہ علیہ وسلم نے فرمایا:تم رہنے دو، کیونکہ تم ابھی ابھی بیماری سے صحت یاب ہوئے ہو اور یہ تمہارے لیے موافق نہیں ہیں۔ راویہ کہتی ہیں کہ پھر میں اُٹھی اور میں نے جَواور چقندر پکا کر نبی صلی اللہ علیہ وسلم کی خدمت میں پیش کیے، تو آپ صلی اللہ علیہ وسلم نے (علیؓ سے)فرمایا:یہ کھاؤ، کیونکہ یہ تمہارے لیے بہت فائدہ مند ہیں۔‘‘","صحیح",{"k":"سنن أبوداؤد (3856)۔"}],[711,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ:\n’’میں بیمار ہو گئی تو میرے گھر والوں نے مجھ سے(کھانے پینے کی) ہرچیز روک لی یہاں تک کہ پانی بھی، رات کو مجھے پیاس لگی تو میرے پاس کوئی چیز موجود نہیں تھی، میں (وہاں)لٹکے ہوئے چمڑے کے مشکیزے کے قریب ہوئی اور اس سے پانی پی لیا، اور سیدہ عائشہ رضی اللہ عنہا فرمایا کرتی تھیں کہ بیمار کو کسی چیز سے مت روکو۔‘‘","صحیح",{"k":"مستدرک حاکم (4؍408)۔"}],[712,"ابنِ عباس رضی اللہ عنہما نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’نظرلگ جانا برحق بات ہے، اگر تقدیر پر کوئی چیز سبقت لے جاتی تو نظر نے سبقت لے جانا تھا، اورجب تمہیں غسل کرنے کو کہا جائے تو تم غسل کیا کرو۔‘‘","صحیح",{"k":"صحیح مسلم (2188)، سنن ترمذی (2062)۔","f":"نظر کے برحق ہونے سے مراد یہ ہے کہ یہ بات محض وہم یاوسوسۂ انسانی نہیں ہے بلکہ بری نظر تاثیر رکھتی ہے اور متاثرہ شخص کو نقصان بھی پہنچاتی ہے، یہ دراصل کسی شخص میں کوئی خوبی، یاا سے حاصل اللہ تعالٰی کی کوئی نعمت یاکسی معاملے میں اس کی کامیابی دیکھ کردِل میں پیدا ہو نے والے حسد (Jealousy) کا نتیجہ ہوتی ہے، کیونکہ انسان جب کسی کی اچھائی کو دیکھ کر اس کے حق میں اللہ تعالٰی کے مزید فضل ورحمت کی دعا کرنے کی بہ جائے اس سے حسد کرتا ہے اور اس خوبی کے زائل ہوجانے یااس سے چھِن کر خود کومل جانے کی بری خواہش کرتاہے تو اس صورت میں نظر کا لگنا عمل میں آتا ہے۔ اور تقدیر پر سبقت لے جانے سے مراد یہ ہے کہ اصولاًواعتقاداًتقدیر میں لکھا ہوا کوئی نہیں بدل سکتا اور نہ ہی کوئی چیز اسے ٹال سکتی ہے، لیکن اگر ایسا ممکن ہوتا توبہ فرمانِ نبویؐ وہ چیز نظر ہوتی، گویا نظر کالگ جانا اس قدر برحق ہے کہ اسے اس کے بارے میں یہاں تک فرما دیا کہ اس میں تقدیر کو بھی بدل ڈالنے کی صلاحیت ہو سکتی تھی۔ اور غسل کے بیان سے نظرِبدکا علاج بتلایا ہے جوکہ آئندہ روایت میں بیان ہے۔"}],[713,"ابوامامہ بن سہل بیان کرتے ہیں کہ:\n’’سہل بن حنیف نہار ہے تھے کہ عامربن ربیعہؓ ان کے پاس سے گزرے، تو انہوں نے کہا:میں نے آج کی طرح (کبھی کوئی خوبصورت شخص)نہیں دیکھا اور (آپ جیسا تو)کسی پردہ نشیں لڑکی کا جسم بھی نہیں دیکھا، ابھی انہوں نے یہ کہا ہی تھا تو وہ (اچانک تیز بخار ہو جا نے کی وجہ سے)زمین پر گرپڑے۔ انہیں نبی صلی اللہ علیہ وسلم کے پاس لایا گیا اور آپ صلی اللہ علیہ وسلم سے کہا گیا کہ سہل کو دیکھیے وہ نیم مردہ حالت میں ہیں، آپ صلی اللہ علیہ وسلم نے دریافت فرمایا:تم اس(کی اس حالت)کا کسے ذِمے دار ٹھہراتے ہو؟ انہوں نے جواب دیا کہ عامربن ربیعہ کو، تو آپ صلی اللہ علیہ وسلم نے فرمایا:ایک آدمی اپنے بھائی کو مار ڈالنے کی بات کیوں کرتاہے؟ جب وہ اس کی کوئی ایسی خوبی دیکھے جو اسے اچھی لگی ہو تو اسے (اس کے لیے)برکت کی دعا کرنی چاہیے۔ اور آپ صلی اللہ علیہ وسلم نے عامربن ربیعہؓ کو حکم فرمایاکہ وہ وضوء کریں اور اپنا چہرہ، کہنیوں تک دونوں ہاتھ، دونوں گھٹنے اور تہہ بند کے اندر کا حصہ دھوئیں اور وہ پانی اس پر(یعنی سہلؓ پر)بہا دیں۔‘‘","صحیح",{"k":"سنن ابن ماجه (3509)، مسند أحمد (3؍486)، سلسلہ الأحادیث الصحیحہ (2572)۔","f":"اس حدیث میں نظرِبدکا علاج بتایا گیا ہے، اور وہ یہ ہے کہ جس شخص کی نظر لگی ہو وہ کسی برتن وغیرہ میں کہ جس میں پانی محفوظ رہ سکے، اس میں وضوء کرے اور اپنے چہرے کو، کہنیوں تک دونوں ہاتھوں کو، دونوں گھٹنوں کو اور اپنے ازار بند کے اندر والے حصے کو دھو کر وہ پانی متاثرہ شخص پر ڈالا جائے، اور ایک روایت میں یہ ذکر ہے کہ اس کے پیچھے کی طرف سے ڈالا جائے، اس طرح اس پر سے نظر کا اثر ختم ہوجائے گااور وہ تندرست ہوجائے گا۔ تہہ بند کے اندر کے حصے سے کیا مراد ہے؟ حافظ ابنِ حجرؒنے اس سے تہہ بند کا وہ حصہ مراد لیا ہے جو کمر کے ساتھ لگا ہوتا ہے۔(فتح الباری بشرح صحيح البخارى لابن حجر: ۱۰/۲۰۴) جبکہ امام نوویؒ کے نزدیک اس سے مراد تہہ بند کا دایاں سِراہے۔ (شرح صحيح مسلم للنوویؒ:۱۴/۱۷۲) نبی صلی اللہ علیہ وسلم نے نظرِبدکے علاج کے لیے ایک دعا بھی تعلیم فرمائی ہے، وہ یہ ہے: «أَعُوذُ بِكَلِمَاتِ اللّٰهِ التَّامَّةِ، مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لاَمَّةٍ» ’’میں اللہ تعالٰی کے پورے کلمات کے ساتھ ہرشیطان سے، ہرزہریلے جانور سے اور نقصان پہنچانے والی ہرنظرِبدسے(اللہ کی)پناہ مانگتا ہوں۔‘‘"}],[714,"عبداللہ بن عمرو رضی اللہ عنہما بیان کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم ہمارے پاس سے گزرے جبکہ میں اور میرے والد اپنی جھونپڑی کو ٹھیک کر ہے تھے، تو آپ صلی اللہ علیہ وسلم نے دریافت فرمایا:اے عبداللہ!یہ کیا ہے؟ میں نے جواب دیا:اے اللہ کے رسول!ہماری جھونپڑی میں دراڑیں پڑگئی ہیں تو ہم اسے ٹھیک رہے ہیں، تو آپ صلی اللہ علیہ وسلم نے فرمایا:جو تم سمجھ رہے ہو معاملہ تو اس سے بھی بہت جلدی کا ہے۔ ایک روایت میں ہے کہ میں تو معاملے کو اس سے بھی بہت جلدی سمجھتا ہوں۔‘‘","صحیح",{"k":"سنن أبوداؤد (5236)، سنن ترمذی (2335)، سنن ابن ماجه (4160)۔","f":"آپ صلی اللہ علیہ وسلم کے فرمان میں ’معاملے‘سے مراد موت ہے، یعنی کیا پتہ کہ موت اس سے بھی بہت جلد آجائے اورجس مکان کی تم تعمیر ومرمت کررہے ہو اس میں رہنا بھی نصیب ہوکہ نہ ہو۔ آپ صلی اللہ علیہ وسلم کا یہ فرمان موقع کی مناسبت سے نصیحت کرنے سے متعلق ہے، البتہ اس روایت سے اپنے گھر اور مکان کی مناسب تعمیر ومرمت کا جواز ملتا ہے۔"}],[715,"انس بن مالک رضی اللہ عنہ نبی صلی اللہ علیہ وسلم کا اس شخص سے منہ پھیر لینے کے واقعہ کے بارے میں روایت کرتے ہیں جس نے اونچا مکان بنایا تھا تو آپ صلی اللہ علیہ وسلم نے اسے گرا دیا اور فرمایا:\n’’سنو!یقیناًہرعمارت قیامت کے دِن اپنے مالک پر وبال ہوگی، سوائے اس کے جس کے بغیر گزارہ نہ ہو۔ ایک اور روایت میں ہے:جس نے اپنی ضرورت سے زیادہ عمارت تعمیر کی، روزِقیامت وہ اس کے لیے وبال بن جائے گی۔‘‘","صحیح",{"k":"سنن أبوداؤد (5237)، سنن ابن ماجه (4161)، سلسلہ الأحادیث الصحیحہ (2830)۔","f":"یعنی مکانات و عمارات اسی صورت میں وبال نہیں بنیں گے کہ جب تک وہ ضرورت پوری کرنے کی حد تک رہیں، لیکن جب نمود و نمائش کے لیے اونچے اونچے محلات اور بڑی بڑی عمارتیں بننے لگیں تو یہی مکانات و عمارات ان کے لیے روزِقیامت وبال بن جائیں گے۔"}],[716,"خباب بن ارت رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’یقیناًمسلمان کو ہرچیز کے خرچ کرنے میں اجروثواب ملتا ہے سوائے اس کے جو وہ مٹی میں ڈالتا ہے۔‘‘","صحیح",{"k":"سنن ابن ماجه (4163)، سلسلہ الأحادیث الصحیحہ (2831)۔","f":"مٹی میں ڈالنے کا مطلب یہ ہے کہ جو مال ضرورت سے زائد گھر کی تعمیر میں خرچ کرتاہے۔"}],[717,"جابربن عبداللہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’بندہ جو کچھ بھی خرچ کرتاہے اس کا نعم البدل اللہ تعالیٰ کے ذِمے ہوتاہے، سوائے اس خرچ کے جو کسی عمارت پر کیا جائے یاکسی نافرمانی کے کام میں۔‘‘","صحیح",{"k":"سلسلہ الأحادیث الصحیحہ (918)۔"}],[718,"نافع بن عبد الحارث رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’بلاشبہ (یہ چیزیں)مسلمان کی خوش بختی کی علامت ہیں:کشادہ گھر، نیک ہمسایہ اور آرام دہ سواری۔‘‘","صحیح",{"k":"مستدرک حاکم (4؍166)، سلسلہ الأحادیث الصحیحہ (282)۔"}],[719,"ابنِ عباس رضی اللہ عنہما بیان کرتے ہیں کہ:\n’’جب نبی صلی اللہ علیہ وسلم کو معراج پر لے جایا گیا تو(آپ صلی اللہ علیہ وسلم کے سامنے سے)ایک ایک اور دو دو نبی ایسے گزرے کہ جن کے ساتھ ان پر ایمان لانے والی پوری پوری قوم تھی، کچھ کے ساتھ ایک جماعت تھی اور بعض تو ایسے تھے کہ ان کے ساتھ ایک بھی شخص نہیں تھا، یہاں تک کہ ایک بہت بڑی جماعت گزری، میں نے پوچھا:یہ کون لوگ ہیں؟ بتایا گیا کہ موسٰی علیہ السلام اور ان کی قوم ہے، لیکن آپ صلی اللہ علیہ وسلم اپنا سراُٹھا کر دیکھیے۔ میں نے دیکھا تو اتنی بڑی قوم نظر آئی کہ جو یہاں سے وہاں تک اُفق پر چھائی ہوئی تھی، تو جبرائیل علیہ السلام نے مجھے بتلایا کہ یہ آپ صلی اللہ علیہ وسلم کی اُمت ہے اور ان لوگوں کے علاوہ ستّرہزار لوگ ایسے ہیں جو بغیر حساب کے جنّت میں داخل ہوں گے۔ راوی کہتے ہیں کہ (یہ فرمانے کے بعد)پھر آپؐ(اپنے حجرہ مبارک میں)تشریف لے گئے اور اس بات کی کچھ وضاحت نہیں فرمائی اور نہ ہی لوگوں نے آپ صلی اللہ علیہ وسلم سے پوچھا(کہ وہ ستّرہزار لوگ کون ہوں گے؟) کچھ کہنے لگے کہ وہ ہم ہی ہوں گے اور کچھ کہنے لگے کہ(وہ تم نہیں) بلکہ تمہاری وہ اولاد ہوگی جو اسلام میں پیدا ہوگی۔ (یہ سن کر)نبی صلی اللہ علیہ وسلم باہر تشریف لائے اور فرمایا:یہ وہ لوگ ہوں گے جو داغنے کا علاج نہیں کرواتے، جھاڑ پھونک نہیں کرواتے اور بدشگونی نہیں لیتے، بلکہ اپنے رب پر توکل کرتے ہیں۔‘‘","صحیح",{"k":"صحیح بخاری (5705)، صحیح مسلم (220)۔"}],[720,"صہیب رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’مومن کے ہرمعا ملے میں خیروبھلائی ہی ہوتی ہے اور یہ اعزاز سوائے مومن کے کسی کو حاصل نہیں، اگر اسے کوئی خوشی پہنچتی ہے تو وہ اللہ کا شکر ادا کرتا ہے تو اسے (اس پر)اجر ملتا ہے اور اگر اس پر کوئی تنگی آتی ہے تو وہ صبر کرتا ہے تو(اس پر بھی)اسے اجر ملتا ہے، اور اللہ تعالٰی کاہر فیصلہ مومن کے حق میں بہتر ہی ہوتاہے۔‘‘","صحیح",{"k":"صحیح مسلم (2999)، مسند أحمد (6؍16)۔"}],[721,"سعدبن ابی وقاص رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’مجھے مومن کی یہ بات بہت بھلی لگتی ہے کہ اگر اسے کوئی خیروبھلائی ملتی ہے تو وہ الحمدللہ کہتا ہے اور شکر ادا کرتا ہے اور اگر اس پر کوئی مصیبت آجائے تو الحمدللہ کہتا ہے اور صبر کرتا ہے، چنانچہ مومن کو اس کے ہرکام میں اجر ملتا ہے یہاں تک کہ وہ اپنی بیوی کے منہ میں جو نوالہ ڈالتا ہے اس میں بھی وہ اجر سے نوازا جاتا ہے۔‘‘","صحیح",{"k":"السنن الکبری للبیهقی (3؍375)، مسند أحمد (1؍177)، سلسلہ الأحادیث الصحیحہ (141)۔"}],[722,"ابوہریرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’اللہ تعالیٰ فرماتا ہے:یقیناًمیرا بندہ ہربھلائی کے بہ منزلہ ہے، وہ میری تعریف کر رہا ہوتا ہے حالانکہ میں اس کے دو پہلوؤں کے درمیان سے اس کی رُوح کو کھینچ لیتا ہوں۔‘‘","صحیح",{"k":"مسند أحمد (2؍341)، سلسلہ الأحادیث الصحیحہ (1632)۔"}],[723,"ابنِ عباس رضی اللہ عنہما سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’بلاشبہ مومن کے پہلوؤں کے درمیان سے اس کی جان نکل جاتی ہے اور وہ (اس حال میں بھی)اللہ عزوجل کی تعریف کر رہا ہوتا ہے۔‘‘","صحیح",{"k":"مسند أحمد (1؍268)، سلسلہ الأحادیث الصحیحہ (1632)۔","f":"یعنی جب اللہ تعالیٰ اپنے بندے کی رُوح قبض کر رہا ہوتا ہے تب بھی بندے کی زبان پر کوئی شکوہ نہیں ہوتا بلکہ اللہ تعالیٰ کی تعریف کے کلمات ہی زبان سے ادا کر رہا ہوتا ہے۔"}],[724,"اُم المومنین سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم کوجب کوئی خوش کُن معاملہ پیش آتا تھا تو آپ صلی اللہ علیہ وسلم فرماتے: «اَلْحَمْدُ لِلَّهِ الَّذِي بِنِعْمَتِهِ تَتِمُّ الصَّالِحَاتُ» ’’تمام ترتعریفات اس ذات کے لیے ہیں جس کی نعمت کے ساتھ نیک عمل تکمیل پاتے ہیں۔‘‘ اورجب آپ صلی اللہ علیہ وسلم کو کوئی ناپسندیدہ معاملہ پیش آتا تھا تو آپ صلی اللہ علیہ وسلم فرماتے: «اَلْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ» ’’ہرحال میں تمام ترتعریفات اللہ تعالیٰ ہی کے لیے ہیں۔‘‘","صحیح",{"k":"مستدرک حاکم (1؍499)، سلسلہ الأحادیث الصحیحہ (265)۔"}],[725,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’مومن کی مثال پودے جیسی ہے کہ جب بھی ہوا چلتی ہے اسے جھکا دیتی ہے اور مومن ہمیشہ کسی نہ کسی آزمائش میں ہی پڑا رہتا ہے، جبکہ منافق کی مثال درخت کی طرح ہے کہ وہ تب تک اپنی جگہ سے نہیں ہِلتاجب تک اسے اُکھاڑ نہ دیا جائے۔‘‘","صحیح",{"k":"صحیح بخاری، کتاب المرضی، باب ما جاء فی کفارہ المرض، ح (-5644)، صحیح مسلم (2809)۔"}],[726,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’اللہ تعالٰی جس سے بھلائی کرنا چاہتا ہے اسے کسی مصیبت میں مبتلا کر دیتا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (5645)، مسند أحمد (2؍237)۔"}],[727,"انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’بلاشبہ بہت عظیم جزاء بڑی آزمائش کے ساتھ ہی ملتی ہے اور یقیناًاللہ تعالیٰ جب کسی قوم سے محبت کرتاہے تو انہیں آزماتا ہے، سوجو(اللہ کی آزمائش پر)خوش رہا اسے (اللہ کی)رضا حاصل ہوتی ہے اور جو خوش نہ رہا اس کے لیے (اللہ کی)ناراضگی ہوتی ہے۔ اور فرمایا:صبر تو ہوتا ہی پہلے صدمے پر ہے۔‘‘","حسن",{"k":"سنن ترمذی (2396)، سنن ابن ماجه (4031)، سلسلہ الأحادیث الصحیحہ (146)۔","f":"پہلے صدمے پر صبر سے مراد یہ ہے کہ تکلیف، مصیبت اور آزمائش کے آن پڑتے ہی فوراًصبر سے کام لینا اور اسے اللہ کی رضا مانتے ہوئے سرِتسلیم خم کرنا ہی درحقیقت صبر ہے، یہ صبر نہیں ہے کہ پہلے رودھو لیا جائے اور تقدیر ورضا سے شکوے شکایتیں کرکے بعد میں جب اسے اللہ کا فیصلہ سمجھنے اور اسے برداشت کرنے کے علاوہ کوئی چارہ ہی نہ ہو توتب خاموشی اختیار کر لی جائے، بلکہ صبر صدمہ پہنچنے کے پہلے وقت میں ہی ہوتاہے، کیونکہ اس وقت غم کا پہاڑ ٹوٹتا ہے تو اللہ تعالیٰ تبھی دیکھتا ہے کہ مصیبت کی اس عظیم گھڑی میں میری آزمائش پر کون پورا اترتا ہے؟ جو پورا اترتا ہے اسے اللہ کی رضا حاصل ہوتی ہے اور جو پورا نہیں اترتا وہ رب تعالیٰ کی ناراضگی مول لیتا ہے۔"}],[728,"انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب اللہ تعالیٰ کسی قوم کے ساتھ بھلائی کا ارادہ فرماتا ہے تو انہیں آزمائش میں ڈال دیتا ہے۔ اور ایک روایت میں ہے:جب اللہ تعالیٰ کسی قوم سے محبت کرتاہے تو انہیں آزماتا ہے، سوجس نے صبر کیا اس کے لیے صبر(کا اجروثواب)ہے اور جو گھبرا گیا اس کے لیے گھبراہٹ ہے۔‘‘","صحیح",{"k":"مسند أحمد (5؍428)، سلسلہ الأحادیث الصحیحہ (146)۔"}],[729,"ابوموسیٰ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’بلاشبہ میری امت اُمتِ مرحومہ ہے، اس کے لیے آخرت میں عذاب نہیں ہوگا، بلکہ اس کا عذاب دنیا میں ہی زلزلوں، قتل وغارت اور آزمائشوں کی صورت میں مل جائے گا۔‘‘","صحیح",{"k":"سنن أبوداؤد (4278)، سلسلہ الأحادیث الصحیحہ (959)۔"}],[730,"ابوبردہ بیان کرتے ہیں کہ:\n’’میں ابنِ زیاد کے پاس بیٹھا ہوا تھا اور ان کے پاس عبداللہ بن یزید بھی تھے، ان کے پاس خوارج کے سرلائے جارہے تھے اورجب بھی سپاہی سرلے کر گزرتے تو میں کہتا:(یہ جہنم کی)آگ کی طرف(جا رہا ہے)، تو انہوں نے مجھ سے کہا:اے بھتیجے!ایسے نہ کہو، کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے کہ اس اُمت کا عذاب دنیا میں ہی ہوگا۔‘‘","صحیح",{"k":"مستدرک حاکم (4؍254)۔"}],[731,"عبداللہ بن مغفل روایت کرتے ہیں کہ:\n’’ایک آدمی ایسی عورت سے ملا جو عہدِجاہلیت میں زانیہ تھی، وہ اس عورت سے کھیلنے مچلنے لگا، یہاں تک کہ اس نے اپنا ہاتھ اس عورت کی طرف پھیلا دیا(یعنی اسے پکڑنے لگا)تو اس نے کہا:رہنے دو، یقیناًاللہ تعالٰی نے (مجھ سے)شرک کو ختم کر دیا ہے اور اسلام کو لے آیا ہے۔ وہ آدمی واپس چلا گیا اور اس کا چہرہ دیوار سے ٹکرا گیا(اور وہ زخمی ہوگیا)، پھر وہ نبی صلی اللہ علیہ وسلم کے پاس آیا اور آپ صلی اللہ علیہ وسلم کو یہ بات بتلائی، تو آپ صلی اللہ علیہ وسلم نے فرمایا:تو وہ بندہ ہے جس کے ساتھ اللہ تعالٰی نے بھلائی کرنا چاہی ہے، بلاشبہ اللہ تعالٰی جب کسی بندے کے ساتھ بھلائی کرنا چاہتا ہے تو اس کے گناہ کی سزا اسے جلد(یعنی دنیا میں)ہی دے دیتا ہے اورجب کسی بندے کے ساتھ برائی کا ارادہ رکھے تو اس سے اس کے گناہ کی سزا کو روک لیتا ہے یہاں تک کہ قیامت کو اس کا بدلہ دے گا، گویا(وہ گناہ اتنا بڑا ہوگا)جیسے اونٹ۔‘‘","صحیح",{"k":"مسند أحمد (4؍87)، مستدرک حاکم (4؍608)، سلسلہ الأحادیث الصحیحہ (1220)۔"}],[732,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’دنیا مومن کا قید خانہ اور کافر کی جنّت ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2956)، سنن ترمذی (2324)، سنن ابن ماجه (4113)۔","f":"مومن کے لیے دنیا اس لیے قید خانہ ہے کہ وہ اسلامی احکام کا پابند ہوتا ہے، اس کے لیے یہ پابندی ہوتی ہے کہ وہ صرف انہی امور کو اختیار کر سکتا ہے جو شریعتِ اسلامیہ نے اس کے لیے حلال کیے ہیں اور ان امور کے قریب بھی نہیں پھٹک سکتا جو اس پر حرام کر دیے گئے ہیں، اس اعتبار سے مومن کو ہرمعا ملے میں حدود وقیود کا پابند رہنا پڑتا ہے، وہ فرائض وواجبات میں کوتاہی کا مرتکب نہیں ہوسکتا، اسے اخلاقی اقدارو اصولوں کا پاس ولحاظ رکھنا ہوتا ہے، اس کے لیے معاملاتِ زندگی میں شرعی تعلیمات کی پیروی ضروری ہوتی ہے، غرضیکہ وہ اپنی مرضی سے من چاہی زندگی نہیں گزار سکتا بہ خلاف کافر کے کہ وہ بے مہار اونٹ کی طرح ہرجگہ چرتا پھرتا ہے، اسے حلال وحرام کی تمیز کی پرواہ نہیں ہوتی، اخلاقی اقدار کا اسے چنداں پاس نہیں ہوتا اور دیگر بہت سے امور سے اسے کچھ سروکار نہیں ہوتا، چنانچہ کافر کو صرف دنیا سے ہی غرض ومطلب ہوتاہے اور اسی کو اپنی جنّت سمجھتا ہے جبکہ مومن اس دنیا کو عارضی وفانی قیام گاہ سمجھتے ہوئے اسیری کے چند ایام یہاں گزارتا ہے اور پھر اپنے حقیقی مقام یعنی جنّت کی طرف رختِ سفر باندھ لیتا ہے۔"}],[733,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے ایک بدوی سے دریافت فرمایا:کیا تمہیں اُمِ ملدم نے کبھی اپنی گرفت میں لیا ہے؟ اس نے پوچھا:اُمِ ملدم سے کیا مراد ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:یہ جلد اور گوشت کے درمیان گرمی کا نام ہے (یہ بخار ہی کی سی کیفیت والی بیماری ہوتی ہے)، اس نے کہا:میں نے اسے کبھی نہیں پایا۔ آپ صلی اللہ علیہ وسلم نے دریافت فرمایا:تمہیں کبھی صداع نے پکڑا ہے؟ اس نے پوچھا:صداع کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:ایک رگ ہوتی ہے جو انسانی سرمیں پھڑکتی ہے (تو سر درد ہونے لگتا ہے)، تو اس نے کہا:میں نے یہ بھی کبھی نہیں محسوس کیا، تو آپ صلی اللہ علیہ وسلم نے فرمایا:جسے جہنّمی شخص دیکھنے کی خواہش ہو وہ اسے دیکھ لے۔‘‘","صحیح",{"k":"مسند أحمد (2؍332)، الأدب المفرد للبخاری (495)۔","f":"آپ صلی اللہ علیہ وسلم نے ایسا اس لیے فرمایا کیونکہ اللہ تعالیٰ جس بندے کی بھلائی چاہتا ہے یعنی اس کی آخرت بہتر بنانا چاہتا ہے اسے دنیا میں ہی کسی نہ کسی بیماری، تکلیف اور مصیبت میں مبتلا کر کے اس کے گناہوں کا کفارہ فرما دیتا ہے۔اور جس شخص کا اس روایت میں ذِکر ہے اسے بخار تو کجا کبھی سر درد بھی نہیں ہوا تھا جو اس بات کی غماضی کرتا تھا کہ اس سے رب تعالیٰ ناراض ہے، تبھی تو اس کی بھلائی نہیں چاہتا یعنی کسی مرض یا تکلیف میں مبتلا نہیں کرتا۔ اس لیے اگر کسی شخص کو یہی صورت حال پیش آئے تو اسے اللہ تعالیٰ سے اپنے گناہوں کی معافی مانگنی چاہیے اور اعمال صالحہ کے اہتمام سے اپنے پروردگار کو راضی کرنا چاہیے۔"}],[734,"عطاء بن یسار روایت کرتے ہیں کہ:\n’’ابو سعید خدری رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور آپ صلی اللہ علیہ وسلم کو بخار تھا، آپ صلی اللہ علیہ وسلم لحاف اوڑھے ہوئے تھے، انہوں نے لحاف کے اوپر اپنا ہاتھ رکھا تو بخار کی حرارت محسوس کی، ابوسعیدؓنے عرض کیا:اے اللہ کے رسول!آپ صلی اللہ علیہ وسلم کو کسقدر سخت حرارت کا بخار ہوا پڑا ہے، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:یقیناًاسی طرح ہم(انبیاء)پر آزمائش بھی اتنی ہی سخت آتی ہے اور اجر بھی دو گنا ملتا ہے۔ پھر انہوں نے پوچھا:اے اللہ کے رسول!سب سے زیادہ سخت آزمائش کن لوگوں پر آتی ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:انبیاء پر، انہوں نے عرض کیا:پھرکن پر؟ آپ صلی اللہ علیہ وسلم نے فرمایا:علماء پر، انہوں نے کہا:پھرکن پر؟ آپ صلی اللہ علیہ وسلم نے فرمایا:پھر ان نیک لوگوں پر کہ جن میں سے کوئی اسقدر غربت سے آزمایا جاتا ہے کہ اس کے پاس صرف ایک چادر ہوتی ہے جسے وہ اوڑھتا ہے، اور وہ آزمائش میں مبتلا ہو کر بھی تم میں سے کسی ایسے شخص سے کہیں زیادہ خوش ہوتاہے جسے سب چیزیں میسر ہوں۔‘‘","صحیح",{"k":"سنن ابن ماجه (4024)، مستدرک حاکم (3؍343)، سلسلہ الأحادیث الصحیحہ (144)۔"}],[735,"سیدنا سعد رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’میں نے عرض کیا:اے اللہ کے رسول!سب سے زیادہ سخت آزمائش کن لوگوں پر آتی ہے؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:انبیاء پر، پھر جو(ان کے بعد)زیادہ فضیلت کے حامل ہیں، پھر جو(ان کے بعد)افضل لوگ ہیں، یہاں تک کہ آدمی کو اس کے دِین کے بہ قدر آزمایا جاتا ہے۔ اگر تو وہ دِین میں مضبوط ہوگا تو اس کی آزمائش بھی سخت ہوگی اور اگر وہ دِین میں نرم ہوا تو اس کی آزمائش اسی حساب سے کی جاتی ہے۔ بندے پر آزمائش آتی رہتی ہے، یہاں تک کہ وہ اسے ایسا کر چھوڑتی ہے کہ وہ زمین پر چلتا ہے اور اس کا کوئی گناہ باقی نہیں رہتا۔‘‘","صحیح",{"k":"سنن ترمذی (2398)، سنن ابن ماجه (4023)، مسند أحمد (1؍172)، سلسلہ الأحادیث الصحیحہ (143)۔"}],[736,"سیدنا ابوبکر صدیق رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’میں نے عرض کیا:اے اللہ کے رسول!اس آیت ﴿مَنْ يَعْمَلْ سُوءًا يُجْزَ بِهِ﴾ ’’جو بھی بُراعمل کرے گاا سے اس کا بدلہ دیا جائے گا۔‘‘ کے بعد نجات کیسے ممکن ہے؟کیونکہ ہم جو بھی بُراعمل کریں گے اس کا بدلہ ہمیں دیا جائے گا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:اے ابوبکر!اللہ تمہاری مغفرت فرمائے، آپ صلی اللہ علیہ وسلم نے تین مرتبہ یہ دعا دی، پھر فرمایا:کیا تم بیمار نہیں ہوتے؟ کیا تمہیں کوئی پریشانی نہیں آتی؟ کیا تمہیں تھکاوٹ نہیں ہوتی؟ کیا تمہیں کوئی تکلیف نہیں پہنچتی؟، میں نے جواب دیا:جی کیوں نہیں، تو آپ صلی اللہ علیہ وسلم نے فرمایا:یہی وہ بدلہ ہے جو تمہیں دنیا میں دیا جاتا ہے۔‘‘","صحیح",{"k":"مسند أحمد (1؍11)، مستدرک حاکم (3؍74)، صحیح ابن حبان (1734)۔"}],[737,"ابو سعید خدری اور ابوہریرہ رضی اللہ عنہما روایت کرتے ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’مسلمان جب بھی کسی تکان، دکھ، دردوتکلیف، بیماری اورغم میں مبتلا ہوتا ہے حتٰی کہ جب اسے کوئی پریشانی آن پڑتی ہے جو اسے پریشان کر دیتی ہے تو اس کے بدلے میں بھی اس کی برائیاں دُورکر دی جاتی ہیں۔‘‘","صحیح",{"k":"صحیح بخاری (5641)، صحیح مسلم (2573)۔"}],[738,"سیدہ عائشہ رضی اللہ عنہا سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’مسلمان پہ جو بھی مصیبت آتی ہے اس کی وجہ سے اس کے گناہ ختم کر دیے جاتے ہیں، یہاں تک کہ اسے جو کانٹا بھی چبھتا ہے (تو یہ بھی اس کے گناہوں کا کفارہ بن جاتا ہے)۔‘‘","صحیح",{"k":"صحیح مسلم (2572)۔"}],[739,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’کسی بھی مومن کو اگر کانٹا بھی چبھتا ہے یااس سے بھی چھوٹی کوئی چیز اسے تکلیف پہنچاتی ہے تو اس کے بدلے میں اللہ تعالٰی اس کا ایک گناہ ختم کر دیتا ہے اور ایک درجہ بلند فرما دیتا ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2572)۔"}],[740,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’بلاشبہ آدمی کے لیے اللہ تعالیٰ کے ہاں ایک ایسا مقام ہے جہاں وہ عمل کے ذریعے نہیں پہنچ پاتا، لیکن اللہ تعالیٰ اسے مسلسل آزماتا رہتا ہے یہاں تک کہ وہ اس مقام تک جا پہنچتا ہے۔‘‘","صحیح",{"k":"مستدرک حاکم (3؍112)، صحیح ابن حبان (692)، سلسلہ الأحادیث الصحیحہ (2599)۔"}],[741,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’مومن مرد یامومن عورت اپنے مال، جان اور اولاد کے معاملے میں آزمائش میں مبتلا رہتا ہے، یہاں تک کہ وہ اللہ سے جا ملتا ہے اور اس پر کوئی گناہ باقی نہیں رہتا۔‘‘","صحیح",{"k":"مسند أحمد (2؍287)، مستدرک حاکم (1؍346)، الأدب المفرد للبخاری (494)۔"}],[742,"ابوامامہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’بخار جہنم کا زنگ ہے، سوجس مومن کو بخار ہو جائے اسے آگ سے اس کا حصہ مل جاتا ہے۔‘‘","حسن",{"k":"مسند أحمد (5؍264)، سلسلہ الأحادیث الصحیحہ (1822)۔","f":"بخار چونکہ جہنم ہی کا زنگ ہوتاہے تو مومن کو اس کے گناہوں کے بدلے میں جو جہنم کی سزا ہونا ہوتی ہے وہ بخار ہو جا نے سے ٹَل جاتی ہے کیونکہ اس صورت میں گویا وہ اپنی سزا بھگت لیتا ہے۔"}],[743,"سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے ایک عورت سے فرمایا:\n’’تم بخار کو برا بھلامت کہو، کیونکہ یہ انسان کے گناہوں کو اس طرح ختم کر دیتا ہے جس طرح (آگ کی)بھٹّی لوہے کی میل کچیل کو ختم کر دیتی ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2575)۔"}],[744,"عبدالرحمٰن بن ازہر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’مسلمان بندے کوجب کوئی سخت تکلیف یابخار ہوتا ہے تو اس کی مثال ایسے ہی ہے جیسے لوہا، کہ جب وہ آگ کے اندر جاتا ہے تو اس کی میل، زنگ اور کھوٹ ختم ہو جاتا ہے اور عمدہ چیز باقی رہ جاتی ہے۔‘‘","صحیح",{"k":"مستدرک حاکم (1؍348)، سلسلہ الأحادیث الصحیحہ (1714)۔","f":"اسی طرح مسلمان کا معاملہ ہے کہ جب اسے بخار ہوتا ہے یاکسی تکلیف میں مبتلا ہو جاتا ہے تو اس کے سارے گناہ ختم ہوجاتے ہیں اور خطاؤں سے پاک جسم باقی رہ جاتا ہے۔"}],[745,"انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’اللہ تعالٰی فرماتا ہے کہ جب میرا بندہ اپنی دو پیاری چیزوں کے عارضے میں مبتلا کر دیا جاتا ہے پھر وہ اس پر صبر کرتا ہے تو میں ان دونوں کے بدلے میں اسے جنّت عطا کروں گا۔ دو پیاری چیزوں سے مراد آنکھیں ہیں۔‘‘","صحیح",{"k":"صحیح بخاری (5653)، مسند أحمد (3؍156)۔","f":"یعنی اگر اللہ تعالیٰ کسی کی بینائی چھین لے تو اس کی دو آنکھوں کے بدلے میں اسے جنت عطا فرما دیتا ہے۔"}],[746,"عطاء بن یسار رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب بندہ بیمار ہوتا ہے تو اللہ تعالیٰ دو فرشتوں کو اس کے پاس بھیجتا ہے اور فرماتا ہے کہ جاؤ دیکھو کہ وہ عیادت کے لیے آنے والے لوگوں سے کیا کہتا ہے؟ پھر(فرشتے اس کے پاس آتے ہیں اور)اگر تو وہ آنے والوں کے پاس الحمدللہ کہتا ہے اور اللہ کی تعریف بیان کرتاہے تو وہ اس کا یہ عمل اُٹھا کر اللہ کی طرف لے جاتے ہیں، جبکہ اللہ تعالیٰ سب سے زیادہ جانتا ہے، اور اللہ فرماتا ہے:میرے بندے کا معاملہ مجھ سے ہے، اگر میں اسے فوت کردوں تو اسے جنّت میں داخل کردوں گااور اگر میں اسے شفا دے دوں تو اسے ایسا گوشت(جسم)دوں گاجو اس کے(پہلے)گوشت سے بہتر ہوگا اور ایسا خون دوں گاجو اس کے(پہلے)خون سے بہتر ہوگا اور میں اس کی تمام برائیاں ختم کردوں گا۔‘‘","صحیح",{"k":"موطأ لإمام مالک (940)، التمهید لابن عبد البر (5؍47)، سلسلہ الأحادیث الصحیحہ (146)۔"}],[747,"ابوموسیٰ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب بندہ بیمار پڑجاتا ہے یاسفر میں ہوتاہے تو اس کے لیے اتنا ہی اجر لکھ دیا جاتا ہے جتنا وہ تندرستی یاقیام کی حالت میں عمل کرتا ہوتا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (2996)، مسند أحمد (4؍410)۔","f":"اگر بندہ روزانہ کوئی نیک عمل کرتا ہے اور پھر کسی دن بیمار ہو جانے یا سفر کرنے کی وجہ سے وہ عمل نہیں کر پاتا تو اس دن وہ عمل نہ کرنے کے باوجود بھی اس کے نامۂ اعمال میں اس کے معمول کا اجر ثواب لکھ دیا جاتا ہے۔ یہ پروردگار عالم کی اپنے بندے پر خاص رحمت ہے۔"}],[748,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’اس دوران کہ ایک آدمی چلا جا رہا تھا، اس نے ایک کانٹے دار ٹہنی راستے میں پڑی دیکھی، اس نے وہ اُٹھا دی، تو اللہ تعالٰی نے اس (کے اس عمل)کی قدر کی اور اسے بخش دیا۔‘‘","صحیح",{"k":"صحیح بخاری (652)، صحیح مسلم (1914)۔","f":"یعنی چھوٹے سے چھوٹے عمل کی بھی اللہ تعالی قدر فرماتا ہے اور اپنے بندے کو اس کے بھی ثواب سے محروم نہیں کرتا۔"}],[749,"اور آپ صلی اللہ علیہ وسلم کا فرمان ہے:\n’’شہداء کی پانچ قسمیں ہیں:طاعون کی مرض سے فوت ہونے والا، پیٹ کی بیماری میں فوت ہونے والا، پانی میں ڈوب کر مرنے والا، جو دیوار کے نیچے دَم کر مرجائے اور راہِ خدا میں جان دے کر شہادت پانے والا۔‘‘","صحیح",{"k":"صحیح بخاری (653)، صحیح مسلم (1914)۔"}],[750,"ابوہریرہ رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’راہِ خدا میں جان دینے والا شہید ہے، پیٹ کی بیماری میں فوت ہوجانے والا شہید ہے، پانی میں ڈُوب کر مرجانے والا شہید ہے اور ایامِ نفاس میں فوت ہوجانے والی عورت بھی شہیدہ ہے۔ ایک روایت میں یہ اضافہ ہے کہ اللہ کی راہ میں اپنی سواری سے گرکرمر جا نے والا شہید ہے اور راہِ خدا میں پہلُوکے درد سے فوت ہوجانے والا بھی شہید ہے۔‘‘","صحیح",{"k":"صحیح مسلم (1915)، مسند أحمد (2؍441)۔","f":"موت کی مذکورہ تمام صورتیں چونکہ انتہائی تکلیف دہ مراحل سے گزر کر آتی ہیں، اس لیے اللہ تعالیٰ نے اس طرح فوت ہونے والے اپنے بندوں کو شہادت کے مرتبے سے نوازا ہے۔"}],[751,"انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’تم میں سے کوئی بھی مصیبت یاتکلیف آن پڑنے پر موت کی خواہش ہرگز نہ کرے، لیکن اگر اس کے بغیر کوئی چارہ نہ ہو تو اسے یُوں کہنا چاہیے: «اللّٰهُمَّ أَحْيِنِي مَا كَانَتِ الْحَيَاةُ خَيْرًا لِي وَتَوَفَّنِي إِذَا كَانَتِ الْوَفَاةُ خَيْرًا» لِي ’’اے اللہ!مجھے تب تک ہی زندہ رکھناجب تک زندگی میرے لیے بہتر ہو اور اس وقت مجھے موت دے دیناجب مرجانا میرے لیے بہتر ہو۔‘‘","صحیح",{"k":"صحیح بخاری (6351)، صحیح مسلم (2680)۔"}],[752,"جابر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو وفات سے قبل تین مرتبہ یہ فرماتے سنا:\n’’تم میں سے ہرشخص کو لازماًاسی حالت میں موت آئے کہ وہ اللہ تعالیٰ سے اچھا گمان رکھتا ہو۔‘‘","صحیح",{"k":"صحیح مسلم (2877)، سنن أبوداؤد (2877)، سنن ابن ماجه (4167)۔","f":"یعنی انسان کو اللہ تعالیٰ کے بارے میں یہی گمان رکھنا چاہیے کہ وہ بہت ارحم الراحمین ہے، اس کی رحمت کے سامنے میرے گناہوں کی کوئی حیثیت نہیں ہے، وہ مجھے اپنی رحمت سے ضرور نوازے گا اور میرے گناہوں کو ضرور بخش دے گا۔ اس حکم کی وجہ ایک دوسری روایت میں مذکور ہے کہ اللہ تعالیٰ فرماتا ہے: «اَنَا عِنْدَ ظَنِّ» عَبْدِیْ بِیْ (صحيح بخاری:۷۵۰۵) ’’ میں اپنے بندے کے بارے میں وہی معاملہ کرتا ہوں جو اس کا میرے بارے میں گمان ہوتاہے۔‘‘ اس لیے اگر اللہ تعالیٰ کی رحمت کی امید ہو اور یہ حسنِ ظن ہو کہ وہ مجھے عذاب نہیں دے گا تو اللہ تعالیٰ بھی بندے کے ساتھ ایسا ہی معاملہ فرمائے گا۔ لہٰذا خواہ جتنے بھی گناہ ہوں اس کی رحمت سے ناامید نہیں ہونا چاہیے، ہاں البتہ رحمت اور مغفرت کی امید پر گناہ کرنا مذموم عمل ہے اور ایسے شخص کے بارے میں سخت وعید وارد ہوئی ہے۔"}],[753,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جس شخص کے تین ایسے بچے فوت ہوجائیں کہ جو ابھی گناہ کی عمر کو نہیں پہنچے ہوں، اسے آگ صرف قسم پوری کرنے کے لیے ہی چھُوئے گی۔‘‘","صحیح",{"k":"صحیح بخاری (1251)، صحیح مسلم (2632)۔","f":"قسم پوری کرنے سے مراد اللہ تعالیٰ کا یہ فرمان ہے: ﴿وَإِنْ مِنْكُمْ إِلَّا وَارِدُهَا﴾ ’’اور تم میں سے کوئی ایسا نہیں ہے جو جہنم پر وارد نہ ہو۔‘‘ اس آیت کی تفسیر میں اہلِ علم فرماتے ہیں کہ اس سے مرادپُل صراط ہے جو جہنم کے اوپر بنا ہوا ہے، چنانچہ جو نیک عمل کرنے والے اللہ کے پیارے لوگ ہوں گے وہ اس پر سے بہ آسانی گزر جائیں گے لیکن جو بدعمل اور کافر ہوں گے وہ اس سے گزر نہیں پائیں گے اور جہنم میں جا گریں گے۔ تو مذکورہ حدیث کا یہ مفہوم ہے کہ جس کے تین ایسے بچے فوت ہوگئے جو ابھی گناہ کی عمر کو نہیں پہنچے تھے یعنی بالغ نہیں ہوئے تھے تو اسے اللہ تعالیٰ صرف اپنی قسم پوری کرنے کے لیے اس پر سے گزاریں گے اور وہ بھی بہ آسانی گزر جائے گااور کسی قسم کی کوئی تکلیف نہیں پائے گا۔"}],[754,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’ایک عورت نبی صلی اللہ علیہ وسلم کے پاس حاضر ہوئی اور کہا:اے اللہ کے رسول!میں اپنے تین بچے دفنا چکی ہوں، تو آپ صلی اللہ علیہ وسلم نے فرمایا:تُونے توآگ سے بہت سخت رکاوٹ بنا لی ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2636)، سنن نسائی (1873)۔"}],[755,"جابربن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’جس کے تین بچے فوت ہوجائیں اور وہ ان پر اجر کی امید رکھے، تو وہ جنّت میں جائے گا۔ راوی کہتے ہیں کہ میں نے پوچھا:اور اگر دو ہوں تو؟ آپ صلی اللہ علیہ وسلم نے فرمایا:دو ہوں تب بھی۔ محمود کہتے ہیں کہ میں نے جابرؓسے کہا:اللہ کی قسم!اگر آپ ایک کا بھی پوچھتے تو آپ صلی اللہ علیہ وسلم نے ایک کا بھی یہی حکم فرما دینا تھا، تو انہوں نے کہا:قسم بخدا!میرا بھی یہی خیال ہے۔‘‘","",{}],[756,"معاویہ بن قرہ اپنے باپ کے حوالے سے بیان کرتے ہیں کہ:\n’’ایک آدمی نبی صلی اللہ علیہ وسلم کے پاس آیا کرتا تھا اور اس کے ساتھ اس کا چھوٹا بیٹا بھی ہوتا تھا، تو رسول اللہ صلی اللہ علیہ وسلم نے اس سے دریافت فرمایا:کیا تم اس سے محبت کرتے ہو؟ اس نے جواب میں کہا:اللہ تعالٰی آپ صلی اللہ علیہ وسلم سے اسی طرح محبت فرمائے جس طرح میں اس سے محبت کرتا ہوں(یعنی میں اس سے بہت زیادہ محبت کرتا ہوں)، راوی کہتے ہیں کہ پھر رسول اللہ صلی اللہ علیہ وسلم نے اسے غیر حاضر پایا تو پوچھا کہ فلاں شخص کے بیٹے کو کیا ہوا؟ صحابہؓ نے بتایا کہ اے اللہ کے رسول!وہ فوت ہو گیا ہے، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:کیا تم اس بات پر راضی نہیں ہوکہ تم جنّت کے کسی بھی دروازے پہ آؤاورا سے کھولنا چاہو تو وہ (بچہ) دوڑتا ہوا آئے، اور دروازہ کھول دیا جائے۔ ایک آدمی نے کہا:یہ اسی کے ساتھ خاص ہے یاہم سب کے لیے ہے؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:تم سب کے لیے ہے۔‘‘","صحیح",{"k":"سنن نسائی (1870)، مسند أحمد (3/436-)۔"}],[757,"اسامہ بن زید رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم کی صاحبزادی(زینبؓ)نے آپ صلی اللہ علیہ وسلم کو پیغام بھیجا کہ میرا بیٹا قریب المرگ ہے(اس لیے آپ صلی اللہ علیہ وسلم تشریف لائیں)، تو آپ صلی اللہ علیہ وسلم نے (قاصد کے ذریعے )انہیں یہ جواب بھیجا کہ وہ سلام کہتے ہیں اور فرماتے ہیں کہ «إِنَّ لِلّٰهَ مَا أَخَذَ وَلَهُ مَا أَعْطٰى وَكُلٌّ عِنْدَهُ بِأَجَلٍ مُسَمًّى فَلْتَصْبِرْ وَلْتَحْتَسِبْ» ’’یقیناًاللہ تعالٰی ہی کا تھا جو اس نے لے لیا اور جو اس نے دیا ہے وہ اسی کا ہے، اور ہرایک کا اس کے ہاں ایک وقت مقرر ہے، لہٰذا تم صبر کرو اور ثواب کی امید رکھو۔‘‘ زینبؓ نے دوبارہ آپ صلی اللہ علیہ وسلم کی طرف پیغام بھیجا کہ وہ آپ صلی اللہ علیہ وسلم کو قسم دیتی ہے کہ آپ صلی اللہ علیہ وسلم ضرور تشریف لائیں، چنانچہ آپ صلی اللہ علیہ وسلم کھڑے ہوئے اور(تشریف لائے)آپ صلی اللہ علیہ وسلم کے ساتھ سعدبن عبادہ اور ایک اور صحابی تھے، بچے کو آپ صلی اللہ علیہ وسلم کے سامنے پیش کیاگیا، اس کی جان نکل رہی تھی، آپ صلی اللہ علیہ وسلم کی آنکھیں بہہ پڑیں، تو سعدؓنے عرض کیا:اے اللہ کے رسول!یہ کیا؟ آپ صلی اللہ علیہ وسلم نے فرمایا:یہ وہ رحمت وشفقت ہے جو اللہ تعالٰی نے اپنے بندوں کے دِلوں میں ڈالی ہے، اور اللہ اپنے انہی بندوں پر رحم فرماتا ہے جو دوسروں پر رحم کرتے ہیں۔‘‘","صحیح",{"k":"صحیح بخاری (1284)، صحیح مسلم (923)۔"}],[758,"اُم المومنین سیدہ اُمِ سلمہ رضی اللہ عنہا نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’جس بھی مسلمان کو کوئی مصیبت پہنچے اور وہ اللہ تعالٰی کے حکم کے مطابق «إِنَّالِلَّهِ وَإِنَّاإِلَيْهِ رَاجِعُونَ» پڑھے (اور ساتھ یہ دعا پڑھے:) «اَللّٰهُمَّ أْجُرْنِيْ فِيْ مُصِيبَتِيْ وَأَخْلِفْ لِيْ خَيْرًا» مِنْهَا(اے اللہ!میری اس مصیبت میں مجھے اجروثواب سے نواز اور مجھے اس سے پہتر عطا فرما) تو اللہ تعالٰی اسے اس چیز سے بہتر بدل عطا فرما دیتے ہیں۔ اُمِ سلمہؓ فرماتی ہیں کہ جب(میرے خاوند)ابو سلمہ فوت ہوگئے تو میں نے کہاکہ مسلمانوں میں سے بھلا ابو سلمہ سے بہتر کون ہو سکتا ہے؟ یہ وہ پہلا گھر ہے جس نے رسول اللہ صلی اللہ علیہ وسلم کی جانب ہجرت کی۔ پھر میں یہی دعا پڑھتی رہی تو اللہ تعالٰی نے مجھے رسول اللہ صلی اللہ علیہ وسلم اس سے بہتر بدل کے طور پر عطا فرما دیے۔‘‘","صحیح",{"k":"صحیح مسلم (918)، سنن أبوداؤد (3119)۔"}],[759,"انس بن مالک رضی اللہ عنہ نبی صلی اللہ علیہ وسلم کے صاحبزادے ابراہیم (کی وفات)کا واقعہ بیان کرتے ہوئے فرماتے ہیں کہ:\n’’میں نے انہیں رسول اللہ صلی اللہ علیہ وسلم کے ہاتھوں میں دیکھا اور ان کی جانکنی کا عالم تھا، تو رسول اللہ صلی اللہ علیہ وسلم کی آنکھوں سے آنسو ٹپک پڑے، اور آپ صلی اللہ علیہ وسلم نے فرمایا:آنکھ آنسوبہارہی ہے اوردِل غمگین ہے، لیکن ہم صرف وہی بات کہیں گے جو ہمارے رب کو راضی کرے گی، اے ابراہیم!اللہ کی قسم!ہم تیری وجہ سے بہت غمگین ہیں۔‘‘","صحیح",{"k":"صحیح بخاری (1303)، صحیح مسلم (2315)۔","f":"اولاد یا کسی بھی محبوب شخصیت کی وفات پر فطری محبت کی وجہ سے آنسوؤں کا بہہ پڑنا ممنوعات میں سے نہیں ہے، بلکہ اللہ تعالیٰ کے اس فیصلے پر عدمِ رضا کا اظہار کرتے ہوئے واویلا کرنا اور رونا دھونا ممنوع ہے۔ اس لیے ایسے موقع پر صرف وہی بول بولنے چاہییں جس سے خدا ئے تعالیٰ کی رضا مندی ہی حاصل ہوتی ہو۔"}],[760,"جابربن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم کھجور کے درخت کے پاس جا کھڑے ہوئے اور آپ صلی اللہ علیہ وسلم کے ساتھ عبدالرحمان بن عوفؓ بھی تھے، آپ صلی اللہ علیہ وسلم کے صاحبزادے (ابراہیم)قریب المرگ تھے، آپ صلی اللہ علیہ وسلم نے انہیں اپنی گود میں لیا تو آپ صلی اللہ علیہ وسلم کی آنکھیں نم ہوگئیں، عبدالرحمان بن عوف نے کہا:اے اللہ کے رسول!کیا آپ صلی اللہ علیہ وسلم رورہے ہیں؟ حالانکہ آپ صلی اللہ علیہ وسلم تو ہمیں رونے سے منع فرماتے ہیں، تو آپ صلی اللہ علیہ وسلم نے فرمایا:یقیناًمیں رونے سے منع نہیں کرتا بلکہ میں نوحہ کرنے سے منع کرتا ہوں، میں دو انتہائی بے وقوفی اور گناہ والی آوازوں سے منع کرتا ہوں:ایک آواز تو لہو ولعب اور شیطانی باجوں اوربا نسر یوں کی ہے اور دوسری آواز مصیبت کے وقت چہرہ نوچنے، گریبان پھاڑ نے اور شیطانی چیخوں(کی آواز)ہے، اور(میرا)یہ (رونا)رحمت وشفقت کا اظہار ہے اور جو رحم نہیں کرتا اس پر بھی رحم نہیں کیا جاتا، اے ابراہیم!اگر یہ معاملہ برحق نہ ہوتا، وعدہ سچا نہ ہوتا، بلاشبہ یہ راستہ(دوسروں کے بھی)آنے کا نہ ہوتا اور یقیناًپیچھے رہ جانے والا ہم سے پہلے جانے والے سے عنقریب جا ملنے والا نہ ہوتا تو میں تمہارا ایساغم کرتا جو اس سے بھی زیادہ سخت ہوتا، اے ابراہیم!ہم تیری وجہ سے غم میں مبتلا ہو چکے ہیں، آنکھ رورہی ہے، دِل کوغم کھائے جا رہا ہے، لیکن ہم کوئی ایسی بات نہیں کہیں گے جورب تعالیٰ کی ناراضگی کا باعث بنے۔‘‘","صحیح",{"k":"السنن الکبری للبیهقی (4؍69)، مستدرک حاکم (4؍40)، سلسلہ الأحادیث الصحیحہ (2157)۔"}],[761,"عبداللہ بن عمر رضی اللہ عنہما نبی صلی اللہ علیہ وسلم کا سعدبن عبادہؓ کی عیادت کرنا اور ان کے پاس آنسو بہا نے کے واقعہ میں بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n’’یقیناًاللہ تعالٰی آنکھ کے آنسو بہا نے پرا وردِل کے غمگین ہونے پر عذاب نہیں دیتے، بلکہ وہ اس زبان کی وجہ سے عذاب دیتے ہیں یااسی کے باعث رحم کرتے ہیں۔‘‘","صحیح",{"k":"صحیح بخاری (1304)، صحیح مسلم (924)۔","f":"یعنی اگر تو اس زبان سے نوحہ اور واویلا کیا تو یہی زبان عذاب کی موجب بن جائے گی اور اگر اللہ کے فیصلے پر رضامندی کا اظہار کرتے ہوئے اسی زبان سے اس کا شکر ادا کیا اور صبر کیا تو اللہ تعالٰی اسی زبان کو باعثِ رحمت بنا دیتے ہیں۔"}],[762,"ابوموسیٰ اشعری رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب کسی شخص کا بچہ فوت ہوتاہے تو اللہ تعالٰی فرشتوں سے پوچھتا ہے:تم نے میرے بندے کے بیٹے کی رُوح قبض کی ہے؟ وہ جواب دیتے ہیں:جی ہاں، اللہ فرماتا ہے:تم نے میرے بندے کے دِل کا پھل چھینا ہے؟ وہ کہتے ہیں: جی ہاں، اللہ (فرشتوں سے)پوچھتا ہے: تو اس نے کیا کہا:فرشتے جواب میں کہتے ہیں:اس نے «اِنَّالِلّٰه وَاِنَّااِلَيهِ رَاجِعُوْن» پڑھا اور اور تیری تعریف بیان کی، تو اللہ تعالٰی یہ حکم فرماتا ہے کہ اس کے لیے جنّت میں گھر بنا دو اور اس کا نام ’’بیت الحمد‘‘(یعنی تعریف کا گھر)رکھ دو۔‘‘","صحیح",{"k":"سنن ترمذی (1021)، سلسلہ الأحادیث الصحیحہ (1408)۔"}],[763,"ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’کچھ انصاری لوگوں نے رسول اللہ صلی اللہ علیہ وسلم سے کچھ مانگا تو آپ صلی اللہ علیہ وسلم نے انہیں دے دیا، اورجس جس نے بھی مانگا آپ صلی اللہ علیہ وسلم اسے دیتے رہے یہاں تک کہ آپ صلی اللہ علیہ وسلم کے پاس جتنا بھی مال تھاسب ختم ہوگیا، تو آپ صلی اللہ علیہ وسلم نے جس وقت ہرچیز اپنے ہاتھ سے خرچ کردی تو فرمایا:میرے پاس جتنا بھی مال ہو میں اسے تم سے بچا کر نہیں رکھتا، لیکن جو شخص مانگنے سے بچتا ہے تو اللہ تعالٰی بھی اسے بچائے ہی رکھتا ہے، جوبے نیاز ہو جاتا ہے تو اللہ تعالٰی بھی اسے بے نیاز کر دیتا ہے اور جو صبر کرتا ہے تو اللہ تعالٰی اسے صبر کی توفیق دیتا ہے، اور کسی کو بھی صبر سے بہتر اور اس سے زیادہ وسیع چیز کوئی نہیں ملتی۔‘‘","صحیح",{"k":"صحیح بخاری (1469)، صحیح مسلم (1053)۔"}],[764,"ابنِ عباس رضی اللہ عنہما بیان کرتے ہیں کہ:\n’’میں نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور میں ابھی بچہ تھا، تو آپ صلی اللہ علیہ وسلم نے فرمایا:اے غلام!اللہ کو یاد رکھ وہ تجھے یاد رکھے گا، اللہ کی یاد میں مگن رہ تُواسے اپنے سامنے پائے گا، خوشحالی میں اللہ سے تعلق رکھ وہ سختی میں تجھ سے تعلق رکھے گا۔ یاد رکھ!جو تیرے حصے کا نہیں ہے وہ تجھے مل نہیں سکتا اور جو تیرے حصے کا ہے وہ تجھ سے کوئی چھین نہیں سکتا، اور یاد رکھ!اگر ساری مخلوق اکٹھی ہو کر تجھے کوئی چیز دینا چاہے جبکہ اللہ تعالیٰ وہ چیز تجھے نہ دینا چاہتا ہو تو وہ سب اس کی طاقت نہیں پائیں گے، یاوہ کوئی ایسی چیز تجھ سے روک لینا چاہیں جس چیز کو اللہ تجھے دینے کا ارادہ رکھتا ہو تو ان میں ایسا کرنے کی بھی طاقت نہیں ہے، اور یاد رکھ!روزِقیامت تک ہونے والے تمام معاملات لکھ کر(تقدیر کا)قلم خشک ہو گیا ہے، سوجب تُوما نگے تو اللہ سے مانگ اورجب تُوحفاظت اور پناہ چاہے تو وہ بھی اللہ سے مانگ، اور(یہ بھی)یاد رکھ!کہ یقیناًصبر کے ساتھ مدد ہے، تکلیف کے ساتھ کشادگی ہے اور بلاشبہ تنگی کے ساتھ آسانی ہے۔‘‘","صحیح",{"k":"سنن ترمذی (2516)، مستدرک حاکم (3؍541)، صحیح الجامع للألبانی (7957)۔","f":"مندرجہ بالا حدیثِ مبارکہ میں دنیوی واخروی زندگی کو کامیاب بنانے کے جوزرّیں اصول زبانِ نبوّت سے بیان ہوئے ہیں، وہ مختصراًیہ ہیں: (۱)اللہ کو یاد رکھنے سے اللہ تعالیٰ اپنے بندے کو یاد رکھتا ہے یعنی بندہ جب اللہ کو یاد رکھتا ہے تو اللہ تعالیٰ بھی ہرحال میں اس کا خیال رکھتا ہے۔(۲)اللہ کی یاد میں مگن رہنے سے انسان اس درجے کو پالیتا ہے کہ وہ اللہ تعالیٰ کو اپنے سامنے محسوس کرنے لگتا ہے، یعنی جب بھی اسے کوئی تنگی، تکلیف یامصیبت پہنچتی ہے تو اللہ تعالیٰ یوں اس کی فوراًمدد فرماتا ہے کہ جیسے وہ اس کے سامنے ہی تھا۔ (۳)بندہ اگر اللہ تعالیٰ کے ساتھ خوشی، تندرستی اور اچھے مالی حالات میں تعلق جوڑے رکھتا ہے تو پھر اللہ تعالیٰ بھی اس پر پریشانی، بیماری یاتنگدستی کے حالات میں اسے تنہا نہیں چھوڑتا۔ (۴)جو انسان کا نصیب ہوتاہے وہ اسے مل کر رہتا ہے اور جو اس کا نصیب نہیں ہوتا وہ کسی صورت اسے مل نہیں سکتا۔ (۵)اگر اللہ تعالیٰ انسان کو کوئی چیز دینا چاہے اور ساری مخلوق اس کے لیے اس چیز کے حصول میں رکاوٹ بن جائے تو پھر بھی وہ اسے مل کر ہی رہتی ہے اور اگر اللہ تعالیٰ اسے کوئی چیز نہ دینا چاہے تو ساری مخلوق اس کے لیے اپنی اپنی طاقت وکوشش بروئے کا رلا کر بھی وہ چیز اسے دِلانہیں سکتی۔ (۶)کائنات کے وجود میں آنے سے لے کر روزِقیامت تک کے تمام پیش آنے والے حالات ومعاملات تقدیر میں لکھے جا چکے ہیں جو تبدیل نہیں ہو سکتے۔ (۷)جس بھی چیز کی ضرورت ہوا سے فقط اللہ تعالیٰ سے مانگنا چاہیے کیونکہ اس کے علاوہ کوئی بھی دینے پر قادر نہیں ہے۔ (۸)کسی بھی ضرر رساں چیز، آفات وبلیات، موذی جانوروں، شیاطین اور گناہوں سے پناہ، بچاؤ اور حفاظت کے لیے بھی اللہ تعالیٰ ہی کو پکارنا چاہیے۔ (۹)صبر کرنے سے ہی اللہ کی مدد حاصل ہوتی ہے، ہرتکلیف کے بعد کشادگی یقینی ہے اور تنگی کے ساتھ ہی آسانی ملتی ہے۔"}],[765,"ابنِ عباس رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جو تم میں سے اپنے امیر میں کوئی ناپسندیدہ بات دیکھے تو اسے صبر کرنا چاہیے، کیونکہ جو بھی شخص جماعت سے الگ ہو جاتا ہے وہ جاہلیت کی موت مرتا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (7143)، صحیح مسلم (1849)۔"}],[766,"اسماء بنت عمیس رضی اللہ عنہا بیان کرتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’جسے کوئی رنج، غم، بیماری یاتکلیف پہنچتی ہے اور وہ «اَللّٰهُ اَللّٰهُ رَبِّي لَا شَرِيكَ لَهُ» کہتا ہے تو اس سے وہ دُورکر دی جاتی ہے۔‘‘","حسن",{"k":"المعجم الأوسط للطبرانی (6119)، صحیح الجامع للألبانی (6040)۔","f":"اس حدیث میں تمام تر پریشانیوں اور تکالیف کا انتہائی مختصر علاج بتلا دیا گیا ہے۔"}],[767,"سیدنا سعد رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’حضرت یونس علیہ السلام کی دعا، جو انہوں نے (سمندر کے)اندھیروں میں کی تھی، وہ یہ ہے: «لَا إِلٰهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ» ’’تیرے سوا کوئی معبود نہیں ہے، تُوبہت ہی پاک ہے، بلاشبہ میں ہی ظلم کرنے والوں میں سے تھا۔‘‘ لہٰذا جو بھی بندہ یہ کلمات پڑھ کر کسی چیز کے بارے میں دعا کرتا ہے تو اس کی دعا قبول کی جاتی ہے۔‘‘","صحیح",{"k":"سنن ترمذی (3505)، مسند أحمد (1؍170)، صحیح الجامع للألبانی (3383)۔"}],[768,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ:\n’’کسی عرب کی ایک سیاہ فام لونڈی نے اسلام قبول کیا تو اس کا خیمہ مسجد میں لگا دیا گیا، وہ ہمارے پاس آیا کرتی اور باتیں کیا کرتی تھی، جب باتوں سے فارغ ہوجاتی تو(یہ شعر)پڑھتی:","صحیح",{"k":"صحیح بخاری (439)۔","f":"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\nماں کی گود میں سوائے تین بچوں کے کسی نے بات نہیں کی۔ (ایک)عیسیٰ بن مریم علیہ السلام، (دوسرے کا واقعہ یہ ہے کہ)بنی اسرائیل کا جریج نامی ایک عبادت گزار شخص تھا، اس نے )رب تعالیٰ کی خشوع وخضوع کے ساتھ بندگی کرنے کے لیے(اپنا عبادت خانہ بنایا ہوا تھا(ایک روز)اس میں نماز پڑھ رہا تھا کہ اس کی ماں آئی اور اسے آواز دی:اے جریج!، اس نے (دِل میں) کہا:اے میرے رب!میں نماز پڑھ رہا ہوں اور ماں بھی بلا رہی ہے(ماں کی بات سنوں یانماز پڑھوں؟)، سواس نے نماز جاری رکھی، اس کی ماں واپس چلی گئی۔ اس کی ماں ایک دِن پھر آئی اور اس نے آواز دی لیکن جریج نے پہلے کی طرح ہی کیا، (تیسری مرتبہ)ایک دِن پھر آئی، اس نے پھر ویسا ہی کیا اور نماز نہ چھوڑی۔ اس کی ماں نے بددعا کر دی کہ اے اللہ!اسے تب تک موت نہ دیناجب تک یہ زانیہ عورت کا منہ نہ دیکھ لے۔ ایک روز بنی اسرائیل کے لوگ جریج کی فضیلت بیان کررہے تھے کہ )بہت عابدو زاہد شخص ہے، اتنے میں(ایک زانیہ عورت )یہ بات سُنی تو وہ(بولی:اگر تم چاہو تو میں اسے تمہارے سامنے فتنے میں ڈال کر دکھاؤں؟ انہوں نے کہا:ہم تو چاہتے ہیں۔ چنانچہ وہ عورت چل پڑی اور جریج کے سامنے جا پیش ہوئی)اور اسے ورغلا نے لگی(، لیکن جریج نے اس کی طرف آنکھ اُٹھا کر بھی نہیں دیکھا۔ اس عورت نے یہ کیاکہ ایک چرواہا جو جریج کے عبادت خانے کی طرف بکریاں چرانے آیا کرتا تھا، اسے برائی کی دعوت دی اور اس سے منہ کالا کر کے حاملہ ہوگئی، پھرجب اس نے بچے کو جنم دیا تو اس نے یہ الزام لگا دیا کہ یہ بچہ جریج کا ہے۔ بنی اسرائیل کے لوگ جریج پرٹُوٹ پڑے، اسے ماراپِیٹا، گالیاں دِیں اور اس کا عبادت خانہ بھی گرا دیا۔ جریج نے پوچھا:تمہیں ہوا کیا ہے؟ لوگوں نے جواب دیا:تم نے اس سے زنا کیا ہے اور اس نے تمہارے بچے کو جنم دیا ہے۔ جریج نے کہا:بچہ کہاں ہے؟ جب بچے کو لایا گیا تو جریج نے اُٹھ کر نماز پڑھی اور اللہ تعالٰی سے دعا کی، پھر بچے کی طرف متوجہ ہو کر اس سے پوچھا:اے بچے!تیرا باپ کون ہے؟ وہ بچہ بول پڑا کہ میرا باپ فلاں چرواہا ہے۔ لوگ(یہ سن کر)جریج کی طرف دوڑ پڑے اور اسے چومنے لگے اور کہا کہ ہم آپ کے عبادت خانے کو سونے کا بنا دیتے ہیں۔ جریج نے جواب دیا کہ مجھے اس کی ضرورت نہیں ہے، بس یہ جیسا تھا ویسا ہی بنا دو۔ (اور تیسرے بچے کا واقعہ یہ ہے کہ)ایک عورت گود میں اپنا بچہ لیے بیٹھی اسے دودھ پلا رہی تھی کہ اس کے پاس سے عمدہ لباس پہنے خوبصورت شکل وصورت والا ایک سوار گزرا تو اس عورت نے کہا:اے اللہ!میرے بیٹے کو اس جیسا بنا دے۔ اس بچے نے دودھ چھوڑا اور اس سوار کی طرف دیکھ کر بولا:اے اللہ!مجھے اس جیسامت بنانا، اور(یہ کہہ کر)دوبارہ دودھ پینے لگا۔ پھر ایک لونڈی کا اس کے پاس سے گزر ہوا جسے لوگ مار رہے تھے، تو اس عورت نے کہا:اے اللہ!میرے بیٹے کو اس جیسا نہ بنانا، بچے نے دودھ چھوڑا اور اس لونڈی کی طرف دیکھ کر بولا:اے اللہ!مجھے اسی جیسا بنانا۔ ان دونوں واقعوں کے بعد اس عورت نے اپنے بچے سے پوچھا:اے بیٹے!کیا بات ہے؟ جب وہ حسین وجمیل اور خوش لباس شخص گزرا تو میں نے کہاکہ اے اللہ!میرے بیٹے کو اس جیسا بنا دے تو تم نے کہاکہ اے اللہ!مجھے اس جیسامت بنانا اورجب یہ لونڈی گزری تو میں نے کہا:اے اللہ!میرے بیٹے کو اس جیسا نہ بنانا تو تم نے کہا:اے اللہ!مجھے اسی جیسا بنانا۔ تو اس بچے نے جواب دیا:اے میری ماں!وہ جو سوار تھا وہ بہت سرکش شخص تھا اور تم نے اللہ تعالٰی سے مجھے اس جیسا بنا نے کی دعا کر دی تو میں نے کہاکہ اے اللہ مجھے اس جیسامت بنانا، اور یہ جو لونڈی تھی لوگوں نے اس پر چوری اور زنا کا الزام لگایا حالانکہ اس نے ایسا کچھ نہیں کیا، بلکہ یہ )اپنی صفائی میں(صرف یہی کہتی ہے کہ مجھے میرا اللہ ہی کافی ہے۔\nعبداللہ بن عمر رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\nبنی اسرائیل کے تین لوگ محوِسفر تھے کہ بارش آگئی، انہوں نے پہاڑ میں موجود ایک غار میں پناہ لی۔ ابھی وہ غار میں ہی تھے کہ پہاڑ سے ایک چٹان لڑھکتی آئی اور غار کا دہا نہ بند کر دیا۔ ان میں سے ایک بندہ دوسرے سے کہنے لگا:ذرا دیکھو تو تم نے اللہ تعالٰی کی رضا کے لیے کوئی بہت فضیلت کا حامل عمل کیا ہو تو اس کے ذریعے اللہ تعالٰی سے (کوئی راستہ بن جانے کی دعا)مانگو، شاید اسی طرح تم سے یہ مصیبت ٹل جائے۔ ان میں سے ایک کہنے لگا:اے اللہ!میرے بوڑھے والدین، بیوی اور چھوٹے بچے ہیں، میں ان کی کفالت کے لیے بکریاں چراتا ہوں، جب شام کو واپس آکر دودھ دو ہتا ہوں تو پہلے اپنے والدین کو پلاتا ہوں۔ ایک دِن چارے کی تلاش میں کافی دُورجا نکلا اور میرے آنے تک والدین سوچکے تھے، میں نے برتن دھویا، اس میں دودھ نکالا، پھر وہ دودھ لے کر اپنے والدین کے سرہانے کھڑا ہو گیا۔ میرے بچے میری ٹانگوں سے لِپٹے ہوئے تھے، لیکن میں نے اپنے والدین سے پہلے انہیں پلا ناپسند نہ کیا اور میں نے انہیں نیند سے بیدار کرنا بھی مناسب نہ سمجھا، چنانچہ میں فجر ہو نے تک مسلسل یونہی کھڑا رہا۔ اے اللہ!اگر تو تیرے علم میں میرا یہ عمل فقط تیری رضا کے لیے تھا تو اس(غار کے دہا نے)کو اتناسا تو کھول دے کہ ہم آسمان کو دیکھ سکیں۔ سوا للہ تعالٰی نے ان کے لیے اتنا سادہا نہ کھول دیا کہ انہیں آسمان نظر آنے لگ گیا۔ پھر دوسرا بولا:اے اللہ!میں اپنی ایک چچازاد سے محبت کرتا تھا، اور اس قدر محبت کرتا تھا کہ وہ مجھے ہرایک سے بڑھ کر محبوب تھی، میں نے اسے دعوتِ گناہ دی تو اس نے جواب دیا کہ میں تب تک تمہیں کچھ نہیں کرنے دوں گی جب تک کہ تُومجھے سود ینار نہ لادے۔ میں نے کافی بھاگ دوڑ کر کے سود ینار اکٹھے کر لیے، جب میں اس کے پاس لایا اور اپنی خواہش پوری کرنے لگا تو اس نے کہا:اللہ سے ڈراور اس رقم کوحق مہر کے علاوہ )کسی غلط کام میں(استعمال نہ کر، چنانچہ میں اس کے پاس سے اُٹھ کھڑا ہوا۔ اے اللہ!اگر تو یہ عمل میں نے خالصتاًتیری رضا کی خاطر کیا تھا تو ہمارے لیے اس(دہا نے)کو کھول دے، چنانچہ اللہ تعالٰی نے ان کے لیے مزید کھول دیا۔ تیسرے نے یوں دعا کی:اے اللہ!میں نے ایک مزدور کو مزدوری پہ رکھا، جب اس نے اپنا کام پورا کر لیا تو میں نے اسے مزدوری دی لیکن اس نے لینے سے انکار کر دیا۔ میں نے اس کی مزدوری کی رقم سے سرمایہ کاری کرلی، یہاں تک کہ میں نے اس رقم کے ذریعے بہت سی گائیاں اور بکریاں جمع کرلِیں، پھر(ایک روز)وہ میرے پاس آیا اور اس نے کہا:اللہ سے ڈرو، مجھے میر احق دو اور میری حق تلفی مت کرو۔ میں نے کہا:جا اور یہ گائیاں اور بکریاں لے جا۔ وہ کہنے لگا:اللہ سے ڈرو اور مجھ سے مذاق مت کرو۔ میں نے کہا:میں تم سے مذاق نہیں کررہا، جا اور یہ گائیاں اور بکریاں لے جا۔ بالآخر وہ لے گیا، اے اللہ!اگر تو میرا یہ عمل فقط تیری رضا کے لیے تھا تو یہ جو باقی رہ گیا ہے اسے بھی کھول دے۔ چنانچہ اللہ تعالٰی نے مکمل دہا نہ کھول دِیااور وہ نکل کر(اپنی منزل کی طرف)روانہ ہوگئے۔"}],[769,"’’اور جو ہری ہار کادِن بھی ہمارے رب کے عجائب میں سے ہے، ہاں!اسی نے ہی مجھے کفر کے شہر سے نجات دی۔‘‘","",{"f":"جب اس نے کئی بار یہ شعر پڑھا تو حضرت عائشہؓ نے اس سے پوچھا:یہ جو ہری ہار والادِن کیا ہے؟ اس نے کہا:میرے مالکوں کی ایک لڑکی قیمتی جو ہری ہار پہنے ہوئے تھی کہ اس سے وہ ہارگِرگیا، ایک چِیل اس ہار پر جھپٹی اور اسے گوشت سمجھ کرلے اُڑی۔ وہ سب مجھ پر الزام لگانے لگے اور)طرح طرح کی(سزائیں دینے لگے، معاملہ یہاں تک پہنچ گیا کہ انہوں نے میری شرمگاہ تک کی تلاشی لی۔ میں بہت پریشانی میں مبتلا تھی اور وہ سبھی میرے گرد کھڑے تھے کہ اسی دوران چِیل آئی اور ہمارے سروں پر منڈلا نے لگی، پھر اس نے وہ ہار پھینک دیا۔ مالکوں نے ہار پکڑ لیا، تو میں نے انہیں کہا:اسی ہار کی تم مجھ پر تہمت لگا رہے تھے حالانکہ میرا اس کے ساتھ کوئی تعلق بھی نہ تھا۔‘‘"}],[770,"انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’جب حرام بن ملحان کو، جوان کے ماموں تھے، بئرِمعونہ کے موقع پر زخمی کیا گیا تو انہوں نے خون کو اس طرح اپنے چہرے اور اپنے سرپرمَلااور پھر کہا:ربِ کعبہ کی قسم!میں کامیاب ہوگیا۔‘‘","صحیح",{"k":"صحیح بخاری (4092)۔","f":"رسول اللہ صلی اللہ علیہ وسلم کے پاس عرب کے چار قبیلے (رعل، ذکوان، لحیان اور عصیہ)کے لوگوں نے آکر یہ درخواست کی کہ ہم مسلمان ہوگئے ہیں، اس لیے ہماری مدد کے لیے کچھ لوگ بھیجے جائیں جو ہمیں دِین بھی سکھائیں اور دشمن سے ہماری حفاظت بھی کریں، تو آپ صلی اللہ علیہ وسلم نے ان کے ساتھ ستّرصحابہ کرامؓ کو بھیجا جوسب کے سب قراء تھے۔ ان بدبخت لوگوں نے ان صحابہؓ کو دھو کہ دیا اور بئرِمعونہ کے پاس سب کو شہید کر دیا، ان میں سے صرف ایک صحابی کعب بن زید رضی اللہ عنہ زخمی ہو کربچ نکلے تھے اور انہوں نے ہی مدینہ آکر اس واقعے کی اطلاع دی۔ انہی شہداء میں سے حرام بن ملحان رضی اللہ عنہ تھے جن کا مذکورہ حدیث میں بیان ہوا ہے، تو انہوں نے اس آزمائش کی گھڑی میں بھی خوشی کا اظہار فرمایا اور اسے اپنی کامیابی قرار دیا، کیونکہ وہ راہِ خدا میں جان دے رہے تھے۔ اس لیے ہرمسلمان کو چاہیے کہ وہ کسی آزمائش کے آن پڑنے پر واویلا اورآہ وبکا کرنے اوررب تعالٰی کی ناراضگی مول لینے والے الفاظ منہ سے نکالنے کے بجائے اللہ تعالٰی کا شکر ادا کرے اور اس کی لکھی ہوئی تقدیر پر رضامندی وخوشی کا اظہار کرے۔"}],[771,"عباس بن عبدالمطلب رضی اللہ عنہ روایت کرتے ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’جو شخص اللہ کورب ماننے پر، اسلام کوبہ طورِدِین قبول کرنے پر اور محمد( صلی اللہ علیہ وسلم )کو پیغمبر تسلیم کر لینے پر راضی ہو گیا اس نے ایمان کا ذائقہ چکھ لیا۔‘‘","صحیح",{"k":"صحیح مسلم (34)، سنن ترمذی (2623)۔"}],[772,"عبداللہ بن عمرو رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جس شخص نے اسلام قبول کرلیا، اسے بقدرِکفایت رِزق مل گیا اور اللہ کے دِیے پر اس نے قناعت اختیار کی تو وہ کامیاب ہوگیا۔‘‘","صحیح",{"k":"صحیح مسلم (1054)، سنن ترمذی (2348)، سنن ابن ماجه (4138)۔"}],[773,"بنو سلیم کے ایک صحابی بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’یقیناًاللہ تعالیٰ بندے کو دی ہوئی نعمتوں کے ذریعے آزماتا ہے، سوجو شخص اللہ کے دِیے ہوئے پر راضی ہوتاہے تو اللہ تعالیٰ اس کے لیے برکت ڈال دیتا ہے اور اسے فراخی عطا فرماتا ہے اور جو راضی نہیں ہوتا تو اس کے لیے نہ تو برکت ڈالی جاتی ہے اور نہ ہی اسے فراخی سے نوازا جاتا ہے۔‘‘","صحیح",{"k":"مسند أحمد (5؍24)، سلسلہ الأحادیث الصحیحہ (1658)۔"}],[774,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’زیادہ مال ودولت اکٹھا کر لینا غناء نہیں ہے، بلکہ اصل غناء تودِل کا غنی ہونا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (6446)، صحیح مسلم (1051)۔","f":"اس لیے کہ بہت سے لوگ ایسے بھی ہوتے ہیں کہ جن کے پاس مال ودولت تو بہت ہوتاہے لیکن اسے خرچ کرنے کو ان کادِل نہیں کرتا، اس لیے کہ وہ دِل کے غنی نہیں ہوتے، بہت سے لوگ ایسے بھی ہوتے ہیں کہ جن کے پاس بہت زیادہ مال ودولت تو نہیں ہوتا لیکن پھر بھی وہ اپنی حیثیت واستطاعت کے مطابق خرچ کرنے میں ذراسا بھی تامل نہیں کرتے، اس لیے کہ اللہ تعالٰی نے انہیں دِل کا غنی بنایا ہوتا ہے۔ اسی لیے نبی صلی اللہ علیہ وسلم نے فرمایاکہ اصل غناء تودِل کا غنی ہونا ہے، اگردِل غنی نہیں تو خواہ کتنے ہی مال ودولت والا ہو وہ ایک فقیر ومفلس شخص کے برابر ہی ہوگا۔"}],[775,"ابوہریرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’بہت زیادہ مال ودولت والے (نیکیوں کے لحاظ)سب سے کم ہوں گے، آپ صلی اللہ علیہ وسلم نے یہ تین مرتبہ فرمایا، (پھر فرمایا:)سوائے اس شخص نے جس نے اس طرح اس طرح خرچ کیا۔ اور آپ صلی اللہ علیہ وسلم نے اپنے ہاتھ سے دائیں اور بائیں ہاتھ کی طرف اشارہ کیا۔‘‘","حسن",{"k":"سنن ابن ماجه (4131)، صحیح ابن حبان (10)، سلسلہ الأحادیث الصحیحہ (1766)۔","f":"یعنی بہت زیادہ مال ودولت والوں میں سے صرف دونوں ہاتھوں سے خرچ کرنے والے کے پاس صدقہ وخیرات کی بہت نیکیاں ہوں گی جن کی وجہ سے وہ جنت کا حقداربن جائے گا، جبکہ خرچ نہ کرنے والے اس دِن نیکیوں سے مھروم ہوں گے۔"}],[776,"عمربن خطاب رضی اللہ عنہ روایت کرتے ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’اگر تم اللہ تعالیٰ پر اس طرح توکل کرنے لگوجس طرح توکل کرنے کاحق ہے تو اللہ تمہیں اس طرح رزق سے نوازے گاجس طرح وہ اس پرندے کو رزق عطا فرماتا ہے جو صبح سویرے بھوکے پیٹ نکلتا ہے اور شام کو پیٹ بھر کر لوٹتا ہے۔‘‘","صحیح",{"k":"سنن ترمذی (2344)، سنن ابن ماجه (4164)، مسند أحمد (1؍52)، سلسلہ الأحادیث الصحیحہ (310)۔"}],[777,"جابر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’تم میں سے کسی کو بھی تب تک ہرگز موت نہیں آئے گی جب تک وہ اپنارِزق پورا نہیں کرلے گا، سوتم رزق کے بارے میں سستی نہ کرو، اے لوگو!اللہ تعالیٰ سے ڈرتے رہو اور اچھے طریقے سے روزی طلب کرو، جو حلال ہے اسے اپناؤ اور جو حرام ہے اسے چھوڑ دو۔‘‘","صحیح",{"k":"سنن ابن ماجه (2144)، سلسلہ الأحادیث الصحیحہ (2607)۔","f":"امام بیہقیؒ فرماتے ہیں مذکورہ حدیث اور اس جیسی دیگر احادیث میں حصولِ معاش کی ممانعت نہیں ہے، البتہ یہ تاکید ضرور کی گئی ہے کہ کسبِ معاش اور حصولِ رزق کے لیے اچھا انداز اپناؤ۔ اچھا انداز اپنا نے سے مراد یہ ہے کہ اللہ تعالیٰ ہی کے حقیقی رازق وداتا ہو نے پر اعتماد کرتے ہوئے اور اپنی جمیع کوششوں میں اسی پر بھروسہ کرتے ہوئے حلال روزی کمانا اور حرام سے اجتناب کرنا اور ساتھ یہ بات بھی یاد رہے کہ اسے صرف اتنا ہی مل سکتا ہے جتنا اللہ کی طرف سے اسے میسر ہونا ہے اور جتنا اس کے نصیب میں لکھا ہے۔"}],[778,"انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’ایک آدمی اپنی اونٹنی پر آیا اور بولا:اے اللہ کے رسول!کیا میں اسے چھوڑ دوں اور توکل کر لوں؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:اس کاگھُٹنا باندھ اور توکل کر۔‘‘","صحیح",{"k":"سنن ترمذی (2517)، التوکل لابن أبی الدنیا (7)۔","f":"اس حدیث میں توکل کا مفہوم بتلایا گیا ہے، توکل یہ نہیں کہ اسباب کو بروئے کار لائے بغیر ہی توکل کرکے بیٹھ جانا چاہیے بلکہ نبی صلی اللہ علیہ وسلم نے سائل کو توکل کا مفہوم یوں سمجھایا کہ پہلے اونٹنی کا گھٹنا باندھو اور پھر توکل کرو۔ تو گویا اسباب اختیار کرنا اور ذرائع استعمال کرنا توکل کے منافی نہیں بلکہ توکل کا ہی جزو ہے۔"}],[779,"ہشام بن عروہ اپنے باپ کے حوالے سے اپنے دادا سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’تم میں سے کوئی بھی شخص ایک رسّی لے اور لکڑیوں کا گٹھّابا ندھ کر اپنی پیٹھ پر اٹھا کر لائے اور اسے بیچے، اس ذریعے سے اس کی عزت بھی محفوظ رہے گی اور یہ اس بات سے بھی بہتر ہے کہ وہ لوگوں سے مانگتا پھرے، وہ اسے دیں یانہ دیں۔‘‘","صحیح",{"k":"صحیح بخاری (1471)، سنن ابن ماجه (1836)۔","f":"انسان کے جان، مال اور عزت کی حفاظت شریعت کے بنیادی مقاصد ہیں۔ انہی کے گرد تمام احکام گھومتے ہیں۔ یہاں بھی عزت کی ہی حفاظت کے لیے نبی کریم صلی اللہ علیہ وسلم نے کیا عمدہ نصیحت فرمائی ہے کہ لوگوں سے مانگ کر کھا نے سے کہیں زیادہ بہتر یہ ہے کہ آدمی ایک رسی لے، جنگل میں جا کر لکڑیاں کاٹے اور ان کا گٹھا بنا کر اسی رسی سے باندھے اور اسے اپنی پیٹھ پر لاد کر لائے، اسے بیچے، پیسے کمائے اور ان سے اپنا اور اپنے گھر والوں کا پیٹ پالے۔اس کام سے اسے مشقت تو لازماً ہو گی لیکن پھر بھی یہ مانگنے سے بدرجہا بہتر ہے، کیونکہ جب وہ لوگوں سے مانگے گا تو کوئی دے گا اور کوئی نہیں دے گا، پھر بہت سوں سے طرح طرح کی باتیں سننا پڑیں گی جس سے اس کی عزتِ نفس مجروح ہو گی، اس لیے اس قبیح عمل کی مذمت کی گئی ہے۔"}],[780,"مقدام بن معدیکرب رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’کوئی بھی شخص اپنے ہاتھ سے کما کر جو کھانا کھاتا ہے اس سے بہتر اس نے کبھی کوئی کھانا نہیں کھایا ہوگا۔ اور فرمایا کہ داؤد علیہ السلام صرف اپنے ہاتھ کی کمائی سے ہی کھاتے تھے۔ اور ایک روایت میں ہے کہ آپ صلی اللہ علیہ وسلم سے پوچھا گیا:کونسی کمائی زیادہ پاکیزہ ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:آدمی کی اپنے ہاتھ کی کمائی اورہر جائز تجارت۔‘‘","صحیح",{"k":"صحیح بخاری (2072)، مسند أحمد (4؍131)۔"}],[781,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’بہترین کمائی مزدور کے ہاتھوں کی کمائی ہے، جب وہ خلوصِ نیّت سے کام کرے۔‘‘","صحیح",{"k":"مسند أحمد (2؍334)، تاریخ أصبهان لأبی نعیم (1؍356)، صحیح الجامع للألبانی (3283)۔","f":"یعنی اگر کوئی مزدور اپنے ہاتھ سے تو کمائے لیکن وہ اپنے کام میں مخلص نہ ہو، بلکہ کام سے جان چھڑاتے ہوئے وقت گزارنے میں لگا رہے، یا پھر جان بوجھ کر آہستگی سے کرے تا کہ اس کا کام زیادہ دن تک جاری رہ سکے، تو ایسے شخص کی روزی بھی کامل حلال نہیں ہو گی۔"}],[782,"عبدالرحمٰن بن شِبل رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’تجارت کرنے والے بہت گنہگار ہوتے ہیں، صحابہؓ نے عرض کیا:اے اللہ کے رسول!کیا اللہ تعالیٰ نے تجارت کو حلال نہیں قرار دیا؟ آپ صلی اللہ علیہ وسلم نے فرمایا:کیوں نہیں، لیکن وہ قسمیں اٹھاتے ہیں تو گنہگار ہوتے ہیں اور بات کرتے ہیں تو جھوٹ بولتے ہیں۔‘‘","صحیح",{"k":"مسند أحمد (3؍444)، مستدرک حاکم (2؍6)، سلسلہ الأحادیث الصحیحہ (366)۔"}],[783,"ابوقتادہ رضی اللہ عنہ روایت کرتے ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’خریدوفروخت کرتے ہوئے زیادہ قسمیں اٹھانے سے بچو، کیونکہ ایسا کرنا فروختگیٔ سامان کو فروغ تو دیتا ہے لیکن اس کی برکت کو ختم کر دیتا ہے۔‘‘","صحیح",{"k":"صحیح مسلم (1607)، سنن ابن ماجه (2209)۔","f":"عموماً ایسا ہوتا ہے کہ دو کا ندار اپنا سامان بیچنے کے لیے اس کے عمدہ ہونے کی گاہک کو طرح طرح سے تسلی دِلاتا ہے اور اس کو مہنگے داموں میں فروخت کر کے زیادہ منافع حاصل کرنے کے لیے تو جھوٹی قسمیں تک اٹھا لیتا ہے کہ مجھے یہ چیز اتنے میں پڑی ہے اور آپ سے صرف اتنا سا منافع لے رہا ہوں۔ نبی صلی اللہ علیہ وسلم نے فرمایا یہ طریقہ اس کا سامان فروخت ہونے کے لیے تو مفید ہو سکتا ہے مگر اس سے برکت ختم ہو جاتی ہے۔"}],[784,"سیدنا عمر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’یقیناًاللہ تعالیٰ متقی پرہیزگار اور مخفی وپوشیدہ رہنے والے مالدار شخص کو پسند فرماتا ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2965)، مسند أحمد (1؍168)۔"}],[785,"معاذبن عبداللہ جہنی اپنے باپ کے واسطے سے اپنے چچا سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’اللہ تعالیٰ سے ڈرنے والے شخص کے مال دار ہو نے میں کوئی حرج نہیں ہے، اور متقی شخص کے لیے مالدار ہو نے سے صحت مند ہونا اور نعمتوں کے حصول سے نفس کی خوشحالی بہتر ہے۔‘‘","صحیح",{"k":"سنن ابن ماجه (2141)، مستدرک حاکم (2؍3)، سلسلہ الأحادیث الصحیحہ (174)۔","f":"گو کہ اللہ تعالیٰ کا خوف اپنے دل میں رکھنے اور اس کی راہ میں خرچ کرنے والے کے لیے زیادہ مال کمانے میں کوئی قباحت نہیں ہے لیکن پھر بھی یہ فرما دیا کہ بہتر یہی ہے کہ وہ مال اور نعمتیں حاصل کرنے کی بہ جائے صحت مند اور مفلسی میں رہ کر خوشحال رہے۔ اس لیے کہ اگر زیادہ مال و دولت ہو گا اور طرح طرح کی نعمتیں اور آسائشیں میسر ہوں گی تو کہیں نہ کہیں فرائض کی ادائیگی میں کوتاہی ہو ہی جائے گی، اگر فرائض کی بھی ادائیگی رہے تو نوافل میں فرق آن پڑے گا، جبکہ مفلس اور صحت مند رہ کر وہ خوب تند ہی سے اور تونگری کی ریاضت کا اہتمام کر سکے گا۔"}],[786,"ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’یقیناًتمہارے بارے میں سب سے زیادہ میں جس چیز سے ڈرتا ہوں وہ یہ ہے کہ اللہ تعالٰی تمہارے لیے زمین سے برکات نکال دیں گے۔ پوچھا گیا:زمین کی برکات کیا ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا:دنیا کا مال ومتاع۔ ایک صحابیؓ نے عرض کیا:کیا بھلائی بھی برائی لے آتی ہے؟ )یعنی کیا مال ومتاع کا حصول بھی باعثِ گناہ ہے؟(راوی کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم خاموش رہے، یہاں تک کہ ہم سمجھے آپ صلی اللہ علیہ وسلم پر وحی نازل ہو رہی ہے، پھر آپ صلی اللہ علیہ وسلم اپنی پیشانی سے پسینہ پونچھنے لگے، اور فرمایا:یہ پوچھنے والا کہاں ہے کہ کیا بھلائی بھی برائی لے آتی ہے؟تو اس نے کہا:میں یہاں ہوں، ابو سعید کہتے ہیں کہ جب اس نے یہ )سوال(کیا(تھا)تو ہم نے اس کی تعریف کی)تھی(۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:بھلائی تو صرف بھلائی ہی لے کر آتی ہے، آپ صلی اللہ علیہ وسلم نے یہ تین مرتبہ فرمایا، (پھر فرمایا:)لیکن یہ مال سرسبز اور میٹھا ہے، یقیناًموسمِ بہار جو بھی چیزاُگاتا ہے وہ چیز ناموافق غذا کھا نے والے کو ہلاک کر دیتی ہے یاا سے ہلاکت کے قریب کر دیتی ہے، سوائے سبزہ کھانے والے اس جانور کے جو اس قدر پیٹ بھر کر کھائے کہ اس کی دونوں کوکھ بھر جائیں، پھر وہ سورج کی طرف منہ کر کے جگالی کردے اور پاخانہ وپیشاب کرکے پھر دوبارہ کھانے لگ جائے۔ بلاشبہ (اسی طرح)یہ مال بھی سرسبز اور میٹھا ہے، سوجس نے تو اسے اپنے حق کے مطابق لیا اور اسے اپنے حق میں ہی صرف کیا تو اس کے لیے یہ اچھا مددگار ہے، لیکن جس نے بغیرحق کے لیا تو وہ اس کی طرح ہی ہے جو کھاتا جائے مگر پیٹ نہ بھرے۔‘‘","صحیح",{"k":"صحیح بخاری (6427)۔"}],[787,"عمروبن عوف رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے ابوعبیدہ رضی اللہ عنہ کے بحرین سے مال لے کر آنے والے واقعے کے ضمن میں روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’خوش ہو جاؤ اور اس کی امید رکھو جو تمہیں خوش کردے گی، اللہ کی قسم!میں تم پر فقر(کے غلبے)سے نہیں ڈرتا بلکہ میں تو اس بات سے ڈرتا ہوں کہ تم پر بھی دنیا اسی طرح کشادہ کردی جائے گی جس طرح تم سے پہلے لوگوں پر کشادہ کردی گئی تھی، پھر وہ ایک دوسرے سے آگے بڑھنے کے مقابلے میں لگ گئے جیسا کہ وہ کیا کرتے تھے اور تمہیں بھی اسی طرح غافل کردے گی جس طرح اس نے انہیں غافل کر دیا تھا۔ ایک اور روایت میں یہ الفاظ ہیں:یہ تمہیں بھی اسی طرح ہلاک کردے گی جس طرح انہیں ہلاک کیا تھا۔ اور ابو موسٰی رضی اللہ عنہ کی مرفوع وموقوف حدیث میں (آپ صلی اللہ علیہ وسلم کا فرمان یوں مذکور)ہے کہ یقیناًان درہم ودینار نے تم سے پہلے لوگوں کو ہلاک کر ڈالا، اور میرا خیال ہے کہ یہ تمہیں بھی ہلاک کردینے والے ہیں۔‘‘","صحیح",{"k":"صحیح بخاری (6425)، صحیح مسلم (2961)۔","f":"آپؐ کے اس فرمان کی عملی تشریح ہم بارہا اپنی زندگی میں دیکھ چکے ہیں اور آئے روز کسی نہ کسی پر اسی مال و دولت کی وجہ سے کوئی نیا ستم ٹوٹتا دیکھتے ہیں۔ اسے ہتھیا نے کے لیے انسان اپنے حقیقی رشتوں تک کو بھول جاتا ہے۔ اس کے حصول کے لیے دوسروں کی جان کے درپے ہو جانے میں بھی تأمل نہیں كرتا۔ بلکہ ایسا بھی دیکھنے میں آیا ہے کہ بہت سے شقی لوگ اس کے پیچھے اپنی جان سے بھی ہاتھ دھو بیٹھتے ہیں۔ پہلے لوگوں کی ہلاکت کا باعث بھی مال و دولت کی حرص ہی بنی تھی۔ اسی لیے نبی صلی اللہ علیہ وسلم اپنے امیتوں کے جس آفت میں مبتلا ہو جانے کا سب سے زیادہ خدشہ تھا یہی مال و متاع کی محبت ہی تھی۔ اللہ ہمیں محفوظ رکھے۔"}],[788,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’بندہ میرا مال میرا مال کہے رکھتا ہے، حالانکہ اس کا مال تیں طرح کا ہوتا ہے:وہ جو اس نے کھا لیا تو وہ ختم ہوگیا، یاوہ جو اس نے پہن لیا تو وہ بوسیدہ ہو گیا یاپھر وہ جو اس نے (صدقہ وخیرات میں)دے دیا تو وہ اس نے جاری کردیا، اور ان کے علاوہ جو بھی ہے وہ لوگوں کے لیے چھوڑ کر جا نے والا ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2959)، مسند أحمد (2؍368)، صحیح الجامع للألبانی (5620)۔"}],[789,"عبداللہ بن شخیر بیان کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم ایک آدمی کے پاس آرُکے اور وہ یہ آیات پڑھ رہاتھا: «أَلْهَاكُمُ التَّكَاثُرُ، حَتَّى زُرْتُمُ الْمَقَابِرَ» ’’زیادہ سے زیادہ مال جمع کرنے نے تمہیں غفلت میں ڈال دیا، یہاں تک کہ تم نے قبریں جا دیکھیں‘‘ تو آپ صلی اللہ علیہ وسلم نے فرمایا:ابنِ آدم ’’میرا مال، میرا مال‘‘ لگائے رکھتا ہے، حالانکہ تیرا مال اس کے سوا ہے بھی کیاکہ جوتُونے صدقہ کر دیا اس (کی نیکی)کو توتُونے جاری کردیا، جوتُونے پہن لیا وہ بوسیدہ کر دیا اور جوتُونے کھا لیا وہ ختم کردیا۔‘‘","صحیح",{"k":"صحیح مسلم (2958)۔","f":"گویا انسان جس مال کو سمیٹنے کے لیے ہر دم کسی نہ کسی مار پہ رہتا ہے اور لیل و نہار کے تمام مشاغل اور آرام و سکون سب قربان کر دیتا ہے، اس مال کی حیثیت کیا ہے اس کی وضاحت اس حدیث میں مذکورہ آپ صلی اللہ علیہ وسلم کے فرمان سے ہوتی ہے کہ اس کے مال کے تین ہی مصرف ہوتے ہیں: کھا لیا، پہن لیا یا پچھلوں کے لیے چھوڑ دیا۔ ان میں سے پہلے دو تو سراسر ضیاع ہیں، کیونکہ ضرورت سے زیادہ کھانا اور اور کفایت سے زیادہ یا بہت قیمتی پہننا اسراف ہے اور اسراف کرنے والوں سے اللہ محبت نہیں رکھتا۔ البتہ تیسرا مصرف ایسا ہے کہ جنہیں اس کے مال کے ورثاء قرار دیا جاتا ہے اور اس کے مال کے مالک بن جانا ان کا شرعی حق ہوتا ہے۔ لیکن اس سے بھی کما کر چھوڑ جانے والے کو چنداں فائدہ نہیں ہوتا۔ گویا انسان کی محبوب ترین چیز یعنی مال و دولت کے تمام مصارف ہی عبث اور فضول ہیں لیکن پھر بھی یہ اپنا سارا مال انہی مصارف میں لُٹا دیتا ہے۔ جبکہ ایک ایسی جگہ بھی ہے کہ جہاں جتنا بھی مال لگا دیا جائے ضائع نہیں ہوتا۔ بلکہ دنیا میں مال میں اضافے کا اور آخرت میں ڈھیروں اجروثواب کا ذریعہ بن جاتا ہے، اور وہ ہے انفاق فی سبیل اللہ۔ لیکن صد حیف کہ انسان کا دِل اس مصرف میں خرچ کرنے میں بہت تنگ پڑ جاتا ہے، جبکہ باقی رہ جانے والا، آخرت تک اس کا ساتھ دینے والا اور روزِحساب اس کے کام آنے والا یہی مصرف ہے۔"}],[790,"انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’ابنِ آدم بوڑھا ہو جاتا ہے لیکن دو چیزیں باقی رہتی ہیں:حِرص اوراُمید۔ ایک اور روایت میں ہے کہ(آدمی خود بوڑھا ہو جاتا ہے لیکن)دو چیزیں جوان رہتی ہیں:مال کی حرص اور عمر کی حرص۔‘‘","صحیح",{"k":"صحیح بخاری (6421)، صحیح مسلم (1047)۔","f":"لمبی عمر اور مال، یہ دونوں انسان کی ایسی کمزوریاں ہیں کہ +خردم تک بھی ان کی محبت دِل سے نہیں جاتی۔ نبی صلی اللہ علیہ وسلم نے کیا خوب فرمایا ہے کہ انسان خود بوڑھا ہو جاتا ہے لیکن اس کی حصولِ زراورطولِ عمر کی خواہش جوان ہی رہتی ہے۔ وہ تونگری اور عمر کی بزرگی کی آخری حدتک پہنچ کر بھی ان میں اضافے کا ہی خواہشمند رہتا ہے۔ جبکہ ازروئے آخرت کامیاب شخص وہ ہے جو فقرو افلاس اور اللہ سے ملاقات کو پسند فرماتا ہے۔"}],[791,"ابنِ عباس رضی اللہ عنہما نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’اگر ابنِ آدم کو مال کی بھری دو وادیاں بھی مل جائیں تو وہ تیسری کی خواہش کرے گا، اور ابنِ آدم کا پیٹ سوائے (قبر کی)مٹی کے اور کوئی چیز نہیں بھر سکتی، اور اللہ تعالٰی بھی اسی پر رجوع فرماتا ہے جو اس کی طرف رجوع کرتاہے۔‘‘","صحیح",{"k":"صحیح بخاری (6436)، صحیح مسلم (1048)۔","f":"نبی کریم صلی اللہ علیہ وسلم کا ہر فرمان ہی بے پناہ جا معیت کا حامل ہے۔ اس فرمان میں بھی آپؐ نے فطرتِ بنى آدم کی خوب عکاسی کی ہے کہ انسان ساری زندگی مال حاصل کرنے کی دوڑ دھوپ میں گزار دیتا ہے اور قبر میں جا پڑتا ہے لیکن مال کی حرص کم نہیں ہوتی۔"}],[792,"کعب بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’دو بھوکے بھیڑیے جو بکریوں میں چھوڑ دیے جائیں وہ اسقدر خرابی نہیں کریں گے جسقدر آدمی کی مال ودولت اور جاہ ومنصب کی حرص اس کے دِین کی خرابی کر ڈالتی ہے۔‘‘","صحیح",{"k":"سنن ترمذی (2376)، مسند أحمد (3/456-)۔","f":"انسان کے دین کی سب سے زیادہ خرابی کا باعث یہ اس لیے کہ ان کی حرص وہوس پیدا ہو جانے سے انسان حلال و حرام اور جائز وناجائز کی تمیز کھو بیٹھتا ہے اور ان کے حصول کے لیے کچھ بھی کر گزرنے کے لیے تیار ہوتا ہے۔ اس موقع پر اسے دِین بھی یاد نہیں رہتا اور وہ بہت سے ایسے کاموں کا مرتکب ہو جاتا ہے جنہیں شریعت نے نا جائز وحرام قرار دیا ہوتا ہے۔"}],[793,"انس بن مالک رضی اللہ عنہ روایت کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم نے چند لکیریں کھینچیں اور ایک لکیر ایک سائیڈ پر کھینچی، پھر فرمایا:تم جانتے ہو یہ کیا ہے؟ یہ آرزوؤں کی مثال ہے اور یہ لکیر امید کی لکیر ہے، آدمی ابھی امید لگائے ہی بیٹھا ہوتا ہے کہ اسے موت آجاتی ہے۔‘‘","صحیح",{"k":"صحیح بخاری (6418)۔","f":"یعنی انسان ابھی اپنی خواہشات اور امیدوں کی تکمیل کا ہی سفر طے کر رہا ہوتا ہے کہ کہ اس کی زندگی کا سفر اپنے اختتام کو پہنچ جاتا ہے۔ لہٰذا اسے چاہیے کہ دنیوی امور میں میدیں لگانے کی بہ جائے مقامِ اصلی یعنی آخرت کو بہتر بنانے کے لیے اپنی جمیع قوتیں صرف کر دے اور اپنی دنیوی زندگی کو ہی خوب سے خوب تر بنانے کی سعیِ لاحاصل میں لگے رہنے کی بہ جائے اپنی تمام تر صلاحیتیں دِین کے کاموں میں کھپا دے تا کہ وہ اس دنیا نامی سرائے کو چھوڑ کر جس دائمی و باقی مقام کی طرف جانے کا رختِ سفر باندھنے والا ہے، اسے بہتر بنا سکے۔"}],[794,"ابوہریرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’جسے اللہ تعالٰی نے ساٹھ برس کی عمر عطا فرما دی اس کا عمر کے سلسلے میں عذر پورا کر دیا۔‘‘","صحیح",{"k":"صحیح بخاری (6419)۔","f":"یعنی وہ اللہ تعالیٰ کے ہاں یہ عذر نہیں کر سکے گا کہ اسے نیک عمل کرنے کے لیے عمر نے مہلت نہیں دی، اس لیے اللہ تعالیٰ نے اس امت کی اوسط عمر ساٹھ برس رکھ کر یہ عذر ختم کر دیا۔"}],[795,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’اوسط عمر ساٹھ سے ستّربرس کے درمیان ہے اور میری امت میں سے بہت کم لوگوں کی عمرستّربرس ہوگی۔‘‘","حسن",{"k":"سلسلہ الأحادیث الصحیحہ (1517)، تاریخ بغداد للخطیب (5؍476)۔"}],[796,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’میری اُمت کی عمریں ساٹھ سے ستّرسال کے درمیان ہوں گی اور ان میں سے بہت کم لوگ اس عمر سے تجاوز کریں گے۔‘‘","صحیح",{"k":"سنن ترمذی (3550)، سنن ابن ماجه (4236)، سلسلہ الأحادیث الصحیحہ (757)۔"}],[797,"زیدبن ثابت رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’جس شخص کا مقصد دنیا(حاصل کرنا)ہو اللہ تعالیٰ اس کے کام منتشر کر دیتے ہیں، اس کے فقر کو اس کی آنکھوں کے سامنے کردیتے ہیں اور اسے دنیا بھی صرف اتنی ہی ملتی ہے جتنی اس کے مقدر میں لکھی ہوتی ہے، اورجس شخص کا مقصد آخرت(کا حصول)ہو اللہ تعالیٰ اس کے دِل میں کفایت پیدا کر دیتے ہیں، اس کے کاموں کو اکٹھا کر دیتے ہیں اور دنیا ذلیل ہو کر اس کے پاس آتی ہے۔‘‘","صحیح",{"k":"سنن ابن ماجه (4105)، سلسلہ الأحادیث الصحیحہ (950)۔","f":"لہٰذا ضروری ہے کہ اپنا مقصدِحیات صرف اور صرف آخرت کو بنایا جائے اور مال کو صرف ضرورت کی حد تک اہمیت دی جائے۔ اس سے ہر دو جہاں میں کامیابی ملتی ہے۔ دنیوی زندگی میں اس کے زہد و قناعت کے صلے میں دنیا کو اس کے تابع کر دیا جاتا ہے اور آخرت میں اسے سرخرو کر دیا جاتا ہے۔"}],[798,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے یہ آیت پڑھی: ﴿مَنْ كَانَ يُرِيدُ حَرْثَ الْآخِرَةِ نَزِدْ لَهُ فِي حَرْثِهِ وَمَنْ كَانَ يُرِيدُ حَرْثَ الدُّنْيَا نُؤْتِهِ مِنْهَا وَمَالَهُ فِي الْآخِرَةِ مِنْ نَصِيْبٍ﴾ (جو کوئی آخرت کی کھیتی چاہتا ہے اس کی کھیتی کو ہم بڑھاتے ہیں اور جو دنیا کی کھیتی چاہتا ہے اسے دنیا میں سے ہی دے دیتے ہیں اور آخرت میں اس کے لیے کوئی حصہ نہیں ہے) پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:اللہ عزوجل فرماتا ہے:اے ابنِ آدم!میری عبادت کے لیے منہمک ہو جا میں تیر اسِینہ غناء سے بھر دوں گااور تیرا فقر ختم کردوں گا، اور اگرتُونے نہ کیا تو میں تیر اسِینہ مصروفیت سے بھر دوں گااور تیرا فقر بھی ختم نہیں کروں گا۔‘‘","صحیح",{"k":"سنن ترمذی (2466)، سنن ابن ماجه (4107)، سلسلہ الأحادیث الصحیحہ (1359)۔"}],[799,"ابنِ عمر رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جو ساری فکروں کو ایک ہی فکر(یعنی آخرت کی فکر)بنا لے تو اللہ تعالیٰ اس کی دنیوی فکروں سے اسے کافی ہوجاتے ہیں اورجس کی فکریں شاخ درشاخ پھیلی ہوں تو وہ دنیا کی جس وادی میں بھی ہلاک ہوجائے اللہ تعالیٰ کو اس کی کوئی پرواہ نہیں ہوتی۔‘‘","حسن",{"k":"سنن ابن ماجه (4106)، مستدرک حاکم (2؍443)، صحیح الجامع للألبانی (6189)۔"}],[800,"عبداللہ بن مسعود رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’جس شخص پر کوئی ضرورت آن پڑے اور وہ اسے لوگوں کے سامنے پیش کردے تو اس کی وہ ضرورت پوری نہیں کی جائے گی اور اگر وہ اسے اللہ کے سامنے پیش کردے تو قریب ہے کہ اللہ تعالیٰ اسے غناو کفایت سے نواز دے، یاتو جلد ہی موت دے دے گایا جلد ہی اسے غنی کردے گا۔‘‘","صحیح",{"k":"سنن أبوداؤد (1645)، سنن ترمذی (2326)، صحیح الجامع للألبانی (6566)۔","f":"موت سے اس شخص کو دنیوی مصائب وآلام، فقروفاقہ اور حاجات وضروریات سے ہمیشہ کے لیے نجات مل جاتی ہے اور وہ رب تعالیٰ کے ہاں اس کی نعمتوں میں عیشِ دوام کے مزے لُوٹنے کے لیے اُخروی منزل کی طرف رختِ سفر باندھ لیتا ہے، تو گویا یہ بھی اللہ تعالیٰ کی طرف سے غنا کی ہی ایک صورت ہے۔"}],[801,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’دنیوی معاملات میں اپنے سے کم مرتبے والے شخص کو دیکھو، اپنے سے بلند مرتبہ شخص کونہ دیکھو، کیونکہ یہ اس بات کے زیادہ لائق ہے کہ تم اللہ تعالٰی کی نعمتوں کو حقیر نہیں جا نوگے۔‘‘","صحیح",{"k":"صحیح مسلم (2963)، سنن ترمذی (4142)۔"}],[802,"ابوہریرہ رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب تم میں سے کوئی بندہ ایسے شخص کو دیکھے جسے مال اور جسم میں اس پر فضیلت دی گئی ہو تو اسے چاہیے کہ وہ ایسے شخص کو دیکھ لے جو مال اور جسم میں اس سے کم ہو۔‘‘","صحیح",{"k":"صحیح بخاری (6490)، صحیح مسلم (2963)۔","f":"انسان جب مال و دولت، جسم وصحت اور عہدہ ومنصب کے اعتبار سے اپنے سے بالا شخص کو آئیڈیل بناتا ہے تو احساسِ کمتری کا شکار رہتا ہے اور اللہ تعالیٰ کی ان نعمتوں کی بھی نا قدری کرنے لگتا ہے جو اللہ تعالیٰ نے اس پر کی ہوتی ہیں اور جب وہ ان تمام امور میں اپنے سے نچلے شخص کو نظر میں رکھتا ہے تو اسے اپنی عزت، وقعت اور مرتبت کا احساس ہونے لگتا ہے، اللہ تعالیٰ کی عنایت کردہ نعمتوں کا بھی شکر گزار رہتا ہے اور حرص وطمع سے بھی محفوظ رہتا ہے۔"}],[803,"ابنِ عمر رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے میرا کندھا پکڑا اور فرمایا:\n’’دنیا میں اجنبی شخص یامسافر کی طرح رہ۔ اور ابنِ عمرؓفرمایا کرتے تھے:جب تُوصبح کرے تو شام کا انتظارمت کر اورجب شام کرلے تو صبح کا انتظارمت کر، اپنی صحت میں اپنی بیماری کے لیے اور اپنی زندگی میں اپنی موت کے لیے کچھ کرلے۔‘‘","صحیح",{"k":"صحیح بخاری (6416)، سنن ترمذی (2333)، سنن ابن ماجه (4114)۔","f":"یعنی جیسے ایک اجنبی شخص کسی سے واقف نہیں ہو تایا ایک مسافرجس طرح اپنے گھر سے دُوربے سروسامان تنہا ہوتا ہے اسی طرح دنیوی زندگی گزارنی چاہیے کہ عیش ومستی سے لاتعلق ہو کر ذہن میں ہردم یہی سوچ راسخ رہنی چاہیے کہ میرا حقیقی گھرجنّت ہے اور میں اس تک پہنچنے کے لیے محوِسفر ہوں اور دنیا نامی اس سرائے میں ذرا ساسستا نے اور اگلے سفر کی تیاری کے لیے ٹھہرا ہوں، یہ میرا عارضی مقام ہے دائمی نہیں، اس لیے یہاں کے لیے کچھ کرنے کی بہ جائے اخروی زندگی کو سنوار نے کا سامان کرنا مطلوب ومقصود ہے۔\nسیدنا ابنِ عمر رضی اللہ عنہما فرمایا کرتے تھے کہ اگر تجھے صبح دیکھنا نصیب ہوجائے تو شام کا انتظارمت کر، یعنی کچھ پتہ نہیں کی شام ہونے تک زندگی تیرا ساتھ دیتی ہے کہ نہیں، اورجب صحت مند وتند رست ہو تو بیماری آنے سے پہلے پہلے اور زندگی نصیب میں رہے تو موت آنے سے پہلے پہلے ایسے اعمال کرلے کہ جو تیری فلاح ونجات کا ذریعہ بن سکیں، مبادا کہ تجھے دوبارہ کچھ کرنے کا موقع نہ مل سکے، بیماری تجھے بسترِمرض سے اُٹھنے نہ دے اور موت تجھے اپنی آغوش میں لے لے اورکل تجھے تندرستی کے ان لمحات پر حسرت ہو اور اپنی اس ناکارہ زندگی پر افسوس ہوجس میں تُواپنی دائمی اُخروی زندگی کی فوزو فلاح کے لیے تیاری نہ کر سکا۔"}],[804,"ابنِ عمر رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے میرے جسم کا ایک حصہ پکڑ کر فرمایا:\n’’اے عبداللہ!دنیا میں اس طرح رہ کہ جیسے تُواجنبی ہے یامسافر ہے، اور اپنے نفس کومُردوں کے ساتھ شمار کر۔‘‘","صحیح",{"k":"سنن ترمذی (2333)، سنن ابن ماجه (4114)، سلسلہ الأحادیث الصحیحہ (1157)۔","f":"یعنی یہ کامل یقین پیدا کر لے کہ میری یہ زندگی میری نہیں بلکہ رب تعالیٰ کی دی ہوئی مستعار چیز ہے جس کی واپسی کا کسی بھی وقت مطالبہ ہو سکتا ہے اور میں ایک پل میں زندہ لوگوں کی صف سے نکل کر مردہ لوگوں میں شمار ہو نے لگوں گا۔"}],[805,"عمروبن میمون اودی رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک آدمی کو نصیحت کرتے ہوئے فرمایا:\n’’پانچ چیزوں کو پانچ چیزوں سے پہلے غنیمت جان:بڑھاپے سے پہلے جوانی کو، بیماری سے پہلے صحت کو، فقر سے پہلے مالداری کو، مصروفیت سے پہلے فراغت کو اور موت سے پہلے زندگی کو۔‘‘","صحیح",{"k":"حلیہ الأولیاء لأبی نعیم (4؍148)، صحیح الجامع للألبانی (1077)۔","f":"جوانی، تندرستی، مالداری، فراغت اور زندگی، ان پانچوں چیزوں کی قدر وقیمت کا احساس اسی وقت ہوتاہے جب انسان انہیں کھو دیتا ہے، اسی لیے نبی مکرم صلی اللہ علیہ وسلم نے انسان کو اپنی دنیوی اور اخروی دونوں زندگیوں میں کامیابی حاصل کرنے کے لیے یہ نصیحت فرمائی کہ بڑھاپا، بیماری، فقیری، مصروفیت اور موت سے پہلے پہلے ان چیزوں کو غنیمت جا نو اور ان سے بھرپور اور کماحقہ فائدہ اٹھاؤ۔"}],[806,"ابنِ عباس رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’دو نعمتیں ایسی ہیں کہ جن(سے فائدہ اٹھانے)میں بہت سے لوگ دھوکے میں ہیں:صحت اور فراغت۔‘‘","صحیح",{"k":"صحیح بخاری (6412)، سنن ترمذی (2304)، سنن ابن ماجه (4170)۔","f":"دھوکے میں ہونے سے مراد یہ ہے کہ لوگ ان دونوں چیزوں کی قدر نہیں کرتے اور ان سے فائدہ نہیں اٹھا پاتے، اورجب نہ صحت رہتی ہے اور نہ فراغت میسر ہوتی ہے تو پھر عبث گزارے ہوئے صحت وفراغت کے ایام یاد آتے ہیں لیکن اس وقت سوائے ان پر حسرت وندامت کے کچھ حاصل نہیں ہوتا۔"}],[807,"براء بن عازب رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک جنازے میں شریک تھے، جب ہم قبر کے پاس جارُکے تو آپ صلی اللہ علیہ وسلم قبر پر دو زانو ہو کر بیٹھ گئے، میں گھوم کر آپ صلی اللہ علیہ وسلم کی طرف رُخ کرکے کھڑا ہو گیا، آپ صلی اللہ علیہ وسلم اتنا روئے کہ مٹی تَرہو گئی، پھر آپ صلی اللہ علیہ وسلم نے فرمایا:میرے بھائیو!اس دِن کے مِثل(اپنے دِن)کے لیے تیاری کرو۔‘‘","",{"f":"یعنی جس طرح یہ لوگ اپنی قبروں میں لیٹے ہوئے ہیں کل تم نے بھی انہی کی طرح اپنی قبروں میں آپڑنا ہے، اس لیے یہ وقت دیکھنے سے قبل اس گھاٹی کوبہ آسانی پار کرنے کے لیے تیاری کرلو۔"}],[808,"انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’مومن کی موت کے بعد تین چیزیں اس کے پیچھے جاتی ہیں:اس کے اہلِ خانہ، اس کا مال اور اس کا عمل، دو چیزیں واپس آجاتی ہیں اور ایک (وہیں اس کے ساتھ)رہ جاتی ہے، اس کے اہلِ خانہ اور اس کا مال واپس آجاتے ہیں جبکہ اس کا عمل وہیں رہ جاتا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (6514)، صحیح مسلم (2960)۔","f":"گھر والے اس پر منوں مٹی ڈال کر قبر کے سپرد کر آتے ہیں اور ساری زندگی کی کمائی ہوئی دولت گھر میں پڑی رہ جاتی ہے، نہ وہ چیز کام آتی ہے جس کے لیے ساری زندگی دوڑ دھوپ کرتا رہا یعنی مال اور نہ ہی وہ لوگ ساتھ دیتے ہیں جن کی آسائش وآرام کی خاطر اس مال کو جمع کرتا اور دونوں ہاتھوں سے سمیٹتا رہا، دونوں سے ہی تعلق ختم ہو جاتا ہے اور صرف ایک چیز باقی رہتی اور ساتھ دیتی ہے، وہ ہے اس کا عمل، اگر عمل نیک ہوئے تو ان کا ساتھ اس کے لیے فلاح ونجات کا ذریعہ بن جائیں گے، قبر روشن اور کشادہ ہوجائے گی، اس کی قبر میں جنّت کی طرف سے ایک کھڑ کی کھول دی جائے گی اور وہ راحت واطمینان اور سکون وآرام کی ایسی نیند سوئے گاجیسے نئی نویلی دُلہن مزے سے سوتی ہے، لیکن اگر اس کے بخت برے ہوئے اور عمل نیک نہ ہوئے تو اس پہلی منزل سے ہی اسے عذاب سے دو چار کر دیا جائے گا، قبر انتہائی تاریک اور اسقدر تنگ ہوجائے گی کہ اس کی پسلیاں توڑ کر رکھ دے گی، جہنم کی ایک کھڑ کی اس کی طرف کھول دی جائے گی جس کی آگ اسے جھلسا کر رکھ دے گی اور وہ ذرہ بھر کے لیے بھی آرام کوتر سے گا۔ لہٰذا ہرمسلمان کوبہ جائے دنیوی فکروں میں غرق ہوجانے کے اپنی اُخروی زندگی سنوار نے کے لیے اس چیز کا زیادہ سے زیادہ اہتمام کرنا چاہیے جس نے اس کا ساتھ دینا ہے، کیونکہ نیک اعمال کے علاوہ کوئی چیز کام نہیں آئے گی، نہ وہ کہ جسے زندگی بھر کماتا رہتا ہے اور نہ ہی وہ کہ جن کی خاطر کماتا ہے۔"}],[809,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’یقیناًاللہ تعالیٰ تمہاری شکلوں اور مالوں کو نہیں دیکھتا، وہ تو صرف تمہارے دِلوں اور عملوں کو دیکھتا ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2564)، سنن ابن ماجه (4143)۔","f":"اللہ کے ہاں مال ودولت اور خوبصورت شکلوں صورتوں کی کوئی قدر وقیمت نہیں ہے، اس کے عذاب سے تو صرف اعمال ہی بچا سکیں گے، اگر اعمال نیک ہوئے تو انتہائی مفلس اور بدصورت لوگ بھی اعزاز واکرام کے حقدار ٹھہریں گے لیکن اگر اعمال بُرے ہوئے تو مال ودولت کا بحرِبیکراں اور حسن وجمال میں اپنی مثال نہ رکھنے والے بھی اس کی پکڑ سے بچ نہیں پائیں گے۔"}],[810,"ابوبکرہ رضی اللہ عنہ سے مروی ہے کہ:\n’’ایک آدمی نے کہا:اے اللہ کے رسول صلی اللہ علیہ وسلم !لوگوں میں سے کون شخص بہتر ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:جس کی عمر لمبی ہو اور عمل نیک ہوں۔ اس نے عرض کیا:لوگوں میں سے بُراشخص کون ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:جس کی عمر لمبی ہو اور عمل بُرے ہوں۔‘‘","صحیح",{"k":"سنن ترمذی (2330)، مستدرک حاکم (1؍339)، صحیح الجامع للألبانی (3297)۔","f":"نیک شخص کی عمر لمبی ہو تو اس کے نیک اعمال بھی اسی قدر زیادہ ہوجاتے ہیں جو اس کے لیے درجات کی بلندی کا باعث بن جاتے ہیں، اسی لیے آپ صلی اللہ علیہ وسلم نے ایسے شخص کو تمام لوگوں سے بہتر قرار دیا ہے۔"}],[811,"عقبہ بن عامر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جب تُودیکھے کہ اللہ تعالیٰ کسی بندے کے نافرمانی پر قائم ہونے کے باوجود بھی اسے (اپنی نعمتوں سے)نواز رہا ہے تو یہ اللہ کی طرف سے اس کے لیے ڈِھیل ہے، پھر اللہ تعالیٰ اس آیت کے مطابق اسے کھینچ لے گا: ﴿فَلَمَّا نَسُوا مَا ذُكِّرُوا بِهِ فَتَحْنَا عَلَيْهِمْ أَبْوَابَ كُلِّ شَيْءٍ حَتَّى إِذَا فَرِحُوا بِمَا أُوتُوا أَخَذْنَاهُمْ بَغْتَةً فَإِذَا هُمْ مُبْلِسُونَ فَقُطِعَ دَابِرُ الْقَوْمِ الَّذِينَ ظَلَمُوا وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾ ’’پھرجب انہوں نے اس نصیحت کو جو انہیں کی گئی تھی بھُلاد یاتو ہم نے ہرطرح کی خوشحالیوں کے دروازے ان کے لیے کھول دِیے، یہاں تک کہ جب وہ ان نعمتوں میں جو انہیں عطا کی گئی تھیں خوب مگن ہوگئے تو اچانک ہم نے انہیں پکڑ لیا اوراب حال یہ تھا کہ وہ ہرخیر سے مایوس تھے۔‘‘","صحیح",{"k":"مسند أحمد (4؍145)، الزهد لأحمد ابن حنبل (12)، الشکر لابن أبی الدنیا (32)، سلسلہ الأحادیث الصحیحہ (413)۔"}],[812,"سیدنا عمربن خطاب رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’تمام اعمال کا دارومدار نیت پر ہے اور آدمی کو وہی کچھ ملتا ہے جس کی اس نے نیت کی ہو، سوجس کی ہجرت اللہ اور اس کے رسول کی طرف ہو تو اس کی ہجرت اللہ اور اس کے رسول کی طرف ہی(شمار)ہوگی اورجس کی ہجرت دنیا کو حاصل کرنے یاکسی عورت سے شادی کرنے کے لیے ہو تو اس کی ہجرت اسی کی طرف(شمار)ہوگی جس کی طرف اس نے ہجرت کی۔‘‘","صحیح",{"k":"صحیح بخاری (1)، صحیح مسلم (1907)۔","f":"مسلمان کے دینی ودنیوی تمام ترمعاملات میں اس کی نیّت کو مرکزی اہمیت حاصل ہے، اگرنیّت خالص ہو تو چھوٹاسا عمل بھی بہت سے اجروثواب کا باعث بن جاتا ہے لیکن اگرنیّت رضائے الہٰی کے حصول کی بہ جائے لوگوں کو دکھلاوا اور ان سے تعریف وستائش سننا ہو تو پھر بڑے بڑے عمل بھی ناکارہ ہوجاتے ہیں جیسا کہ اس باب کی آخری حدیث میں مذکور ہے کہ روزِقیامت عالم، شہید اور غنی کو باوجود ان کے عظیم اعمال کے صرف اس بنا پر جہنم میں ڈال دیا جائے گاکہ انہوں نے وہ اعمال اللہ کو راضی کرنے کے لیے نہیں بلکہ دنیا میں اپنی شہرت پانے کے لیے کیے ہوں گے۔"}],[813,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’اللہ تعالیٰ فرماتا ہے کہ میں دیگر شریکوں کی نسبت شرک سے سب سے زیادہ بے نیاز ہوں، سوجس نے کوئی عمل کیا اور اس میں میرے علاوہ کسی اور کو بھی شریک ٹھہرایا تو میں اس سے بری ہوں، اور وہ(عمل)اسی کے لیے ہو گاجس کے لیے اس نے کیا ہوگا۔‘‘","صحیح",{"k":"صحیح مسلم (2985)، سنن ابن ماجه (4202)۔"}],[814,"جندب رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جو شخص شہرت حاصل کرنے کے لیے کوئی عمل کرتاہے اللہ تعالٰی اسے شہرت دے دیتا ہے اور جو لوگوں کے دکھلاوے کے لیے عمل کرتاہے اللہ تعالٰی اس(کی حقیقت لوگوں)کو دکھلا دیتا ہے۔‘‘","صحیح",{"k":"صحیح مسلم (2987)، سنن ابن ماجه (4207)۔","f":"یعنی اللہ تعالیٰ اس کی خواہش دنیا میں ہی پوری کر دیتا ہے اور پھر اس کے لیے آخرت میں کوئی حصہ نہیں رکھتا۔"}],[815,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’روزِقیامت سب سے پہلے تین لوگوں کا فیصلہ کیا جائے گا:ایک شہادت پانے والا آدمی، جب اللہ تعالیٰ اسے لائے گااور اسے اپنی نعمتوں کی پہچان کرائے گاتو وہ پہچان جائے گا، پھر اللہ تعالیٰ فرمائے گا:تُونے ان میں کیا عمل کیا؟ وہ کہے گا:میں تیری راہ میں تب تک قتال کرتا رہاجب تک کہ مجھے شہید نہیں کر دیا گیا، اللہ تعالیٰ فرمائے گا:تُونے جھوٹ بولا ہے، تو صرف یہ چاہتا تھا کہ تجھے بہادر کہا جائے، سووہ کہہ دیا گیا، پھر اللہ تعالیٰ اس کے بارے میں حکم فرمائے گاتُواسے منہ کے بَل گھسیٹ کرلے جایا جائے گااور جہنم میں ڈال دیا جائے گا۔ (دوسرا)آدمی وہ ہے جو علم سکھاتا ہے اور قرآن پڑھتا ہے، اللہ تعالیٰ اسے لائے گااور اسے اپنی نعمتیں یاد کرائے گاتو اسے یاد آجائیں گی، پھر اللہ تعالیٰ فرمائے گا:تُونے ان میں کیا عمل کیا؟ وہ کہے گا:میں نے علم سیکھا اور قرآن پڑھا اور اسے تیری رضا کے حصول کے لیے (دوسروں کو)سکھلایا، اللہ تعالیٰ فرمائے گا:تُونے جھوٹ کہا ہے، کیونکہ تیرا ارادہ صرف یہ تھا کہ یوں کہا جائے کہ فلاں عالم ہے فلاں قاری ہے، سوا للہ تعالیٰ اس کے بارے میں حکم فرمائے گاتو اسے منہ کے بَل گھسیٹ کرلے جایا جائے گااور جہنم میں ڈال دیا جائے گا۔ اور(تیسرا)آدمی وہ ہے جسے اللہ تعالیٰ نے مختلف طرح کے مال سے نوازا تھا، اللہ تعالیٰ اسے لائے گااور اسے اپنی نعمتوں کا اقرا کرائے گاتو وہ تسلیم کرے گا، پھر اللہ تعالیٰ فرمائے گا:تُونے ان میں کیا عمل کیا؟ وہ کہے گا:میں نے کوئی چیز ایسی نہیں چھوڑی کہ جسے تیری راہ میں خرچ کرنا تجھے پسند ہو اور میں نے اسے تیری رضا کی خاطر خرچ نہ کیا ہو، تو اللہ تعالیٰ فرمائے گا:تُوجھوٹا ہے کیونکہ تُوصرف یہی چاہتا تھا کہ یہ کہا جائے فلاں بہت سخی ہے، تو وہ کہہ دیا گیا، چنانچہ اللہ تعالیٰ اس کے بارے میں حکم فرمائے گاتو اسے منہ کے بَل گھسیٹ کرلے جایا جائے گااور جہنم میں ڈال دیا جائے گا۔‘‘","صحیح",{"k":"صحیح مسلم (1905)، مسند أحمد (2؍322)۔","f":"اتنے اتنے عظیم عمل کے حاملین بھی صرف اس بنا پر جہنم میں جھونک دیے جائیں گے کہ ان کی نیت میں خلوص نہیں تھا بلکہ ان کی غرض فقط لوگوں کی زبانوں سے اپنی تعریف وستائش سننا تھا۔"}],[816,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’سات قسم کے لوگ ایسے ہیں جنہیں اللہ تعالٰی روزِقیامت اپنا سایہ نصیب کرے گاجس دِن اس کے سائے کے سوا کوئی سایہ نہیں ہوگا:عدل کرنے والا حکمران، ایسا نو جو ان جس نے اپنی جوانی اللہ کی عبادت میں گزار دی، وہ آدمی جسے تنہائی میں اللہ کی یاد آئی تو اس کے آنسو نکل پڑے، وہ آدمی جس کادِل مسجد میں ہی لگا رہتا ہو، وہ دو بندے جو فقط اللہ تعالٰی کی رضا کے لیے آپس میں محبت کرتے ہوں، وہ آدمی جسے حسن وجمال اور حیثیت کی مالک عورت نے برائی کی دعوت دی لیکن اس نے کہاکہ مجھے اللہ سے ڈرلگتا ہے اور وہ شخص جو اس قدر چھپا کر صدقہ کرے کہ اس کے بائیں ہاتھ کو بھی پتہ نہ چلے کہ اس کے دائیں ہاتھ نے کیاکِیاہے۔‘‘","صحیح",{"k":"صحیح بخاری (1423)، صحیح مسلم (1031)۔"}],[817,"اور نبی صلی اللہ علیہ وسلم کا فرمان ہے کہ:\n’’احسان یہ ہے کہ تُواللہ تعالیٰ کی اس طرح عبادت کرے کہ گویاتُواسے دیکھ رہا ہے اور اگرتُواسے نہیں دیکھ رہا تو وہ تجھے دیکھ رہا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (50)، صحیح مسلم (9)۔","f":"یعنی عبادت کرتے ہوئے دِل میں یہ احساس پختہ طور پر جاگزیں ہونا چاہیے کہ میں اللہ کے سامنے یوں کھڑا ہوں کہ گویا اسے اپنی آنکھوں سے دیکھ رہا ہوں اور اگر یہ احساس پیدا نہ ہونے پائے تو یہ کامل یقین رہے کہ اللہ تعالیٰ مجھے دیکھ رہا ہے، لہٰذا اللہ تعالیٰ کی طرف خوب متوجہ ہو کر انتہائی خشوع وخضوع کے ساتھ اس کی عبادت کرنی چاہیے تاکہ حقِ بندگی کماحقہ ادا ہو سکے۔"}],[818,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے اپنے رب سے اس کا یہ فرمان روایت کیاکہ:\n’’اللہ تعالیٰ فرماتا ہے:میری عزت اور میری عظمت کی قسم!میں اپنے بندے پر دو خوف اور دو امن اکٹھے نہیں کروں گا، جب وہ دنیا کے معاملات میں میرا خوف رکھے تو میں قیامت کے دِن اسے امن میں رکھوں گااو رجب وہ دنیا کے معاملات میں مجھ سے امن میں رہے تو میں قیامت کے دِن اسے خوف میں مبتلا کروں گا۔‘‘","حسن",{"k":"شعب الإیمان للبیهقی (777)، مسند البزار (3233)، سلسلہ الأحادیث الصحیحہ (742)۔"}],[819,"سیدنا انس رضی اللہ عنہ روایت کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم ایک نوجوان کے پاس تشریف لائے اور وہ موت کی کیفیت میں تھا، آپ صلی اللہ علیہ وسلم نے فرمایا:اپنے آپ کو کیسا محسوس کر رہا ہے؟ اس نے کہا:اللہ (کی رحمت)کا امیدوار ہوں اور اپنے گناہوں سے ڈررہا ہوں، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:اس مقام کے مثل اللہ تعالیٰ جس بھی بندے کے دِل میں ان دو باتوں(یعنی امید اور خوف) کو اکٹھا کر دیتا ہے تو اسے وہ چیز عطا کر دیتا ہے جس کی وہ امید کیے ہوتاہے اور اس سے اسے امن میں رکھتا ہے جس سے وہ خوف میں مبتلا ہوتا ہے۔‘‘","حسن",{"k":"سنن ترمذی (983)، سنن ابن ماجه (4261)، سلسلہ الأحادیث الصحیحہ (1051)۔"}],[820,"نعمان بن بشیر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’حلال بھی واضح ہے اور حرام بھی واضح ہے، اور ان دونوں کے درمیان مشتبہات ہیں جن(کے حلال یاحرام ہونے)کا بہت سے لوگوں کو علم ہی نہیں ہے، سوجو ان مشتبہات سے بچ گیا اس نے اپنے دِین اور اپنی عزت (دونوں) کو محفوظ کرلیا، اور جو ان مشتبہات میں پڑگیا وہ اس چرواہے کے مانند ہے، جو(اپنے جانوروں کو ممنوعہ)چراگاہ کے اِردگِردچراتا ہے، بعید نہیں ہے کہ وہ اس چراگاہ میں ہی گھُس جائیں، آگاہ رہو!ہرباد شاہ کی ایک چراگاہ ہوتی ہے اور بلاشبہ زمین میں اللہ تعالٰی کی چراگاہ اس حرام کردہ امور ہیں۔ یاد رکھو!یقیناًجسم میں ایک ایساٹُکڑا ہے کہ جب تک وہ درست رہے سارا جسم ہی درست رہتا ہے اورجب وہ خراب ہوجائے تو سارا جسم ہی خراب ہو جاتا ہے، سنو!وہ دِل ہے۔‘‘","صحیح",{"k":"صحیح بخاری (52)، صحیح مسلم (1599)۔","f":"رسول اللہ صلی اللہ علیہ وسلم نے اس حدیث میں یہ بیان فرمایا ہے کہ مشتبہات(یعنی وہ چیزیں جن کے حلال یاحرام ہونے میں متفقہ رائے نہ ہو)سے بچنا گويا حرام سے بچنا ہے۔ اس ليے تقوٰى كاتقاضايہی ہے کہ ان امور واشياء سے بھى اجتناب كيا جائے جن كے حلال ياحرام ہونے كے بارے میں كوئى صريح حكم نہ ہو۔"}],[821,"سعد رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’علم کا مقام میری نظر میں عبادت کے مقام سے زیادہ پیارا ہے، اور تمہارے دِین کا بہترین عمل پرہیزگاری ہے۔‘‘","صحیح",{"k":"مستدرک حاکم (1؍92)، صحیح الجامع للألبانی (4212)۔"}],[822,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’اے ابوہریرہ!پرہیز گاربن جاتُولو گوں میں سب سے زیادہ عبادت گزار ہو جائے گا، قناعت پسند ہو جاتُولو گوں میں سب سے زیادہ شکر گزاربن جائے گا، لوگوں کے لیے وہی کچھ پسند کر جو اپنے لیے پسند کرتا ہے تُو(حقیقی) مومن بن جائے گا، اپنے ہمسائے کاحقِ ہمسائیگی اچھے طریقے سے ادا کرتُو(پکّاسچّا)مسلمان بن جائے گااور اپنی ہنسی کوکم کر کیونکہ زیادہ ہنسنا بلاشبہ دِل کومُردہ کر دیتا ہے۔‘‘","صحیح",{"k":"سنن أبوداؤد (4800)، سلسلہ الأحادیث الصحیحہ (273)۔"}],[823,"ابوقتادہ اور ابو دہماء بیان کرتے ہیں کہ:\n’’ہم ایک دیہاتی شخص کے پاس آئے تو اس نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے میرا ہاتھ پکڑا اور مجھے وہ بات تعلیم فرمانے لگے جو اللہ تعالیٰ نے انہیں سکھلائی تھی، آپ صلی اللہ علیہ وسلم فرمایا کرتے تھے:بلاشبہ تُوجس چیز کو اللہ تعالیٰ سے ڈرتے ہوئے چھوڑ دے گاا للہ تعالیٰ تجھے اس سے بہتر عطا فرمائے گا۔‘‘","صحیح",{"k":"مسند أحمد (5؍78)، صحیح ابن حبان (413)، سلسلہ الأحادیث الصحیحہ (5)۔"}],[824,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’آدمی کے اسلام کے حسن کا یہ جزو ہے کہ وہ بے معنیٰ وبے مقصد باتوں اور کاموں کو چھوڑ دے۔‘‘","صحیح",{"k":"سنن ترمذی (2317)، سنن ابن ماجه (3976)، صحیح الجامع للألبانی (5911)۔","f":"یعنی اسلام کا کامل حسن اسی شخص میں پایا جاتا ہے جو فضول، بے مقصد، لغو اور لایعنی باتوں اور کاموں کو بالکل ترک کر دیتا ہے۔"}],[825,"حذیفہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’مومن کے شایانِ شان نہیں ہے کہ وہ اپنے نفس کو ذلیل کرے، صحابہؓ نے عرض کیا:وہ اپنے نفس کو کیسے ذلیل کرتاہے؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:وہ (خود ہی)کسی ایسی آزمائش میں پڑجائے جس کی وہ طاقت نہ رکھتا ہو۔‘‘","حسن",{"k":"سنن ترمذی (2254)، سنن ابن ماجه (4016)، سلسلہ الأحادیث الصحیحہ (613)۔","f":"اس لیے آدمی کو کوئی ایسی ذمہ داری خود ہی اپنے سَر نہیں لینی چاہیے جس کی وہ طاقت نہ رکھتا ہو تا کہ وہ اسے اچھی طرح سے نبھا نہ سکنے کی وجہ سے اپنی رسوائی کا خود ہی باعث نہ بن جائے۔"}],[826,"عبداللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’اللہ تعالیٰ سے اس طرح حیاء کروجس طرح حیاء کرنے کاحق ہے، صحابہؓ نے عرض کیا:اے اللہ کے رسول! الحمدللہ ہم تو اللہ تعالیٰ سے حیاء کرتے ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا:یہ بات نہیں ہے، جو اللہ تعالیٰ سے اس طرح حیاء کرتاہے کہ جس طرح حیاء کرنے کاحق ہے اسے چاہیے کہ اپنے سراور ذہنی خیالات کی حفاظت کرے، پیٹ اور جسے وہ سمیٹے اس کی حفاظت کرے اور موت وآزمائش کو یاد رکھنا چاہیے، اور جو آخرت کو چاہتا ہو وہ دنیوی زندگی کی زیب وزینت کو ترک کردے، سوجس نے یہ کر لیا اس نے اللہ تعالیٰ سے اس طرح حیاء کیاکہ جس طرح حیاء کرنے کاحق ہے۔‘‘","حسن",{"k":"سنن ترمذی (2458)، مسند أحمد (1؍387)، صحیح الجامع للألبانی (935)۔"}],[827,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’یقیناًمومن جب کوئی گناہ کرتاہے تو اس کے دِل میں ایک سیاہ دھبّہ لگ جاتا ہے، پھر اگر وہ توبہ کرلے، گناہ چھوڑ دے اور اللہ تعالیٰ سے بخشش مانگے تو اس کے دِل سے وہ دھبّہ صاف کر دیا جاتا ہے، لیکن اگر وہ مزید گناہ کرتا جائے تو وہ دھبّہ بھی بڑھتا جاتا ہے یہاں تک کہ اس کی وجہ سے اس کادِل بند کر دیا جاتا ہے۔ یہی وہ زنگ ہے جس کاذِکر اللہ تعالیٰ نے قرآن میں فرمایا ہے: ﴿كَلَّا بَلْ رَانَ عَلَى قُلُوبِهِمْ مَا كَانُوا يَكْسِبُونَ﴾’’ہرگز نہیں، بلکہ دراصل ان لوگوں کے دِلوں پر ان کے بُرے اعمال کا زنگ چڑھ گیا ہے۔‘‘","حسن",{"k":"سنن ترمذی (3334)، سنن ابن ماجه (4244)، صحیح الجامع للألبانی (1670)۔"}],[828,"سیدنا انس رضی اللہ عنہ فرماتے ہیں:\n’’یقیناًتم ایسے اعمال کرتے ہو جو تمہاری نظر میں بال سے بھی زیادہ باریک ہوتے ہیں جبکہ ہم رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ان گناہوں کو ہلاکت خیز گناہوں میں شمار کیا کرتے تھے۔‘‘","صحیح",{"k":"صحیح بخاری (6492)۔"}],[829,"ابنِ مسعود رضی اللہ عنہ فرماتے ہیں کہ:\n’’چھوٹے گناہوں کی مثال اس قوم کی طرح ہے جو محوِسفر ہو، پھر وہ ایک چٹیل زمین پر پڑاؤ کرے اور ان کے پاس کھانا بھی ہو جسے آگ ہی(پکا کر)کھانے کے قابل بنا سکتی ہو، سووہ سب الگ الگ ہوجاتے ہیں اور ایک لید لاتا ہے، ایک ہڈی اٹھا لاتا ہے اور ایک لکڑی لے آتا ہے، یہاں تک کہ ہروہ چیز اکٹھی کرلیتے ہیں جس سے انہوں نے کھانا تیار کرنا ہوتا ہے۔ فرمایاکہ اسی طرح چھوٹے چھوٹے گناہ کرنے والا شخص ہوتاہے کہ وہ ایک ایک کرکے جھوٹ بولتا رہتا ہے اور ایک ایک کرکے گناہ کرتا رہتا ہے، یہاں تک کہ اس کے اتنے گناہ اکٹھے ہوجاتے ہیں کہ ان کی وجہ سے اللہ تعالٰی اسے منہ کے بل آتشِ جہنّم میں ڈال دیتا ہے۔یہ حدیث موقوف(یعنی صحابی کا قول)ہے، لیکن اسی معنٰی کی حدیث ابو عیاض ابنِ عباس رضی اللہ عنہما کے حوالے سے نبی صلی اللہ علیہ وسلم سے مرفوعاًروایت کرتے ہیں۔‘‘","صحیح",{"k":"شعب الإیمان للبیهقی (7262)، مصنف عبد الرزاق (20278)، المعجم الکبیر للطبرانی (9؍159)۔"}],[830,"ابنِ مسعود رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’یقیناًشیطان اس بات سے مایوس ہو گیا ہے کہ سرزمینِ عرب میں اس کی پرستش کی جائے، لیکن وہ اس کے علاوہ تمہارے چھوٹے چھوٹے گناہوں پر ہی خوش ہوجائے گا، اور یہ(چھوٹے چھوٹے گناہ)اصل میں روزِقیامت ہلاک کردینے والے گناہ بن جائیں گے۔ سوجس قدر ہو سکے ہرطرح کے ظلم سے بچو، کیونکہ بندہ روزِقیامت(بہت سی)نیکیاں لے کر آئے گااور وہ سمجھ رہا ہوگا کہ یہ نیکیاں اسے نجات دِلادیں گی، لیکن ایک بندہ کھڑا ہوگا اور کہے گا:اے میرے رب!تیرے فلاں بندے نے میرے ساتھ فلاں ظلم کیا ہے؟ تو اللہ تعالٰی فرمائے گاکہ اس کی کچھ نیکیاں مٹا دو۔ آپ صلی اللہ علیہ وسلم نے فرمایاکہ مسلسل یونہی ہوتا رہے گا(یعنی یکے بعد دیگرے اس کے ظلم کا نشانہ بننے والا ہربندہ اس کی نیکیوں سے حصہ لیتا جائے گا)یہاں تک کہ اس کی کوئی نیکی باقی نہیں رہے گی اور گناہ ہی بچ جائیں گے، اور بلاشبہ یہ ایسے ہی ہے جیسے کوئی قوم چٹیل زمین میں پڑاؤ کرے اور ان کے پاس لکڑیاں بھی موجود نہ ہوں، تو وہ سب ایندھن اکٹھا کرنے کے لیے بکھر جائیں اور کچھ ہی دیر میں وہ ایندھن جمع کرلیں اور جو وہ پکانا چاہتے ہیں پکا لیں۔ فرمایاکہ گناہ بھی اسی طرح ہیں۔‘‘","صحیح",{"k":"مستدرک حاکم (2؍32)، صحیح الترغیب والترهیب (2221)۔","f":"امام بیہقیؒ فرماتے ہیں کہ یہ اور اس جیسی دیگر مثالیں(جس شخص کے لیے بیان کی گئی ہیں)اس پرتب تک اللہ تعالٰی کی رحمت نہیں ہوگی جب تک کہ وہ اپنے گناہوں کا اتنا عذاب نہیں بھگت لے گاجتنا اللہ تعالٰی چاہے گا۔ اس لیے اسی جہان میں ہی اپنے گناہوں سے توبہ کر لینی چاہیے۔"}],[831,"عبادہ بن صامت رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم نے ہم سے بھی اسی طرح بیعت لی جس طرح آپ صلی اللہ علیہ وسلم نے عورتوں سے اس بات پر بیعت لی کہ ہم اللہ تعالیٰ کے ساتھ کسی کو شریک نہ ٹھہرائیں، چوری نہ کریں، زنا نہ کریں، اپنے بچوں کو قتل نہ کریں اور کوئی کسی پر تہمت نہ لگائے۔ سوتم میں سے جو شخص ان اعمال کا پورا اہتمام کرے گاتو اس کا اجر اللہ تعالیٰ کے ذِمے ہے، جو تم میں سے کسی قابلِ حدجُرم کا ارتکاب کرے اور اس پرحد لگا دی جائے تو وہ اس کا کفارہ بن جائے گی اورجس کے گناہ پر اللہ تعالیٰ پردہ ڈال دے تو اس کا معاملہ اسی کی طرف ہے، وہ چاہے تو اسے عذاب دے اور چاہے تو اسے معاف فرما دے۔‘‘","صحیح",{"k":"صحیح مسلم (1709)۔"}],[832,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’بلاشبہ ہرنبی کی ایک مقبول دعا ہوتی ہے، ہرنبی نے اپنی دعا مانگنے میں جلدی کی، لیکن میں نے اپنی دعا کو اپنی اُمت کی شفاعت کے لیے محفوظ کیا ہوا ہے، جو تم میں سے ہراس شخص کو ان شاء اللہ نصیب ہوگی جسے اس حالت میں موت آئے کہ وہ اللہ کے ساتھ کسی کو شریک نہ ٹھہراتا ہو۔‘‘","صحیح",{"k":"صحیح مسلم (199)، سنن ترمذی (3602)، سنن ابن ماجه (4307)۔","f":"گویا اللہ تعالیٰ کے ساتھ اس کی ذات و صفات میں کسی کو شریک ٹھہرا نے والا آپ صلی اللہ علیہ وسلم کی شفاعت سے محروم رہے گا۔"}],[833,"سیدنا عمربن خطاب رضی اللہ عنہ فرماتے ہیں:\n’’خالص توبہ سے مراد یہ ہے کہ آدمی گناہ کرے، پھر توبہ کرلے اور دوبارہ وہ گناہ کرنے کا ارادہ نہ کرے۔‘‘","مصنف ابن أبی شیبہ:7/99",{"f":"اللہ تعالیٰ فرماتا ہے: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللّٰهِ تَوْبَةً نَصُوحًا﴾ [التحريم: ۸] ’’اے ایمان والو!اللہ سے توبہ کرو، خالص توبہ۔‘‘"}],[834,"ابنِ مسعود رضی اللہ عنہ فرماتے ہیں:\n’’خالص توبہ یہ ہے کہ آدمی کسی گناہ سے توبہ کرے تو پھر کبھی دوبارہ وہ گناہ نہ کرے۔‘‘","شعب الإیمان للبیهقی:9/264",{}],[835,"عبداللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ میں نے نبی صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’ندامت بھی توبہ ہی ہے۔‘‘","صحیح",{"k":"سنن ابن ماجه (4252)، مسند أحمد (1؍376)، صحیح الجامع للألبانی (6802)۔","f":"انسان کو اپنے گناہوں پر حقیقی طور پر ایسی ندامت وشرمندگی ہوکہ جس سے وہ آئندہ گناہ کرنے سے باز رہے تو یہ بھی اس کی توبہ ہی ہے۔"}],[836,"ابنِ عمر رضی اللہ عنہما روایت کرتے ہیں کہ انہوں نے نبی صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’اے اہلِ ایمان!اپنے پروردگار سے توبہ کیا کرو، کیونکہ میں دِن میں سوبار اس سے توبہ کرتا ہوں۔‘‘","صحیح",{"k":"صحیح مسلم (2702)۔"}],[837,"اغرمُزنی رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’بلاشبہ میرے دِل پر بھی پردہ ساآ جاتا ہے، اور یقیناًمیں دِن میں سومرتبہ اللہ تعالٰی سے استغفار کرتا ہوں۔‘‘","صحیح",{"k":"صحیح بخاری (6307)، صحیح مسلم (2702)، سنن أبوداؤد (1515)۔"}],[838,"ابوموسیٰ اشعری رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’یقیناًاللہ تعالیٰ رات کو اپنا ہاتھ پھیلاتے ہیں تاکہ دِن کو گناہ کرنے والا توبہ کرلے، اوردِن کو اپنا ہاتھ پھیلاتے ہیں تاکہ رات کو گناہ کرنے والا توبہ کرلے، اور اللہ تعالیٰ تب تک ایسا کرتے رہیں گے جب تک کہ سورج مغرب سے طلوع نہیں ہوجاتا۔‘‘","صحیح",{"k":"صحیح مسلم (2759)، مسند أحمد (4؍395)۔"}],[839,"ابوذرغفاری رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم سے اللہ کا یہ فرمان روایت کرتے ہیں کہ:\n’’اللہ تعالیٰ فرماتا ہے:اے میرے بندو!یقیناًمیں نے اپنے آپ پر ظلم کو حرام کیا ہے اور تمہارے درمیان بھی اسے حرام قرار دیا ہے، چنانچہ تم ایک دوسرے پر ظلم نہ کرو۔ اے میرے بندو!تم دِن رات گناہ کرتے ہو اور میں گناہوں کو معاف کر دیتا ہوں، مجھے کوئی پرواہ نہیں ہے، سوتم مجھ سے بخشش مانگا کرو میں تمہیں بخش دیا کروں گا، اے میرے بندو!تم سب کے سب بھوکے ہو سوائے اس کے جسے میں کھلاؤں، سوتم مجھ سے کھانا طلب کیا کرو میں تمہیں کھانے کو دوں گا، اے میرے بندو!تم سارے کے سارے برہنہ ہو سوائے اس کے جسے میں پہنا دوں، سوتم مجھ سے پہننے کو(لباس)مانگا کرو میں تمہیں پہنا دوں گا۔ اے میرے بندو!اگر تمہارے اوّل وآخر اوراِنس وجِن سب کسی انتہائی پرہیزگار شخص کی طرح ہوجائیں تو ان کا ایسا ہو جانا میری بادشاہت میں چنداں اضافہ نہیں کر سکے گا، اے میرے بندو!اگر تمہارے اگلے پچھلے، جنات وانسان سارے کسی انتہائی گنہگار شخص جیسے بن جائیں تو ان کا یوں ہونا میری بادشاہت سے کچھ بھی کم نہیں کر سکے گا، اے میرے بندو!اگر تمہارے اول وآخر اورجن وانس تمام ایک میدان میں جمع ہوجائیں اور وہ مجھ سے مانگیں تو میں ہرایک کو اس کے سوال کے مطابق دیتا جاؤں تو میری بادشاہت سے کچھ بھی کم نہیں ہوگا، ہاں بس اتناسا کہ جیسے سُوئی کو سمندر میں ایک مرتبہ ڈبو کر نکال لیا جائے تو جتنا وہ سُوئی سمندر سے پانی کم کرے گی، اے میرے بندو!یہ تمہارے ہی اعمال ہیں جنہیں میں تمہارے لیے شمار کرتا ہوں، سوجو تم میں سے اپنے اعمال اچھے پائے تو اسے اللہ تعالیٰ کی تعریف وستائش کرنی چاہیے اور جو ان کے علاوہ (یعنی برے اعمال)پائے تو اسے اپنے آپ کو ہی ملامت کرنا چاہیے۔‘‘","صحیح",{"k":"صحیح مسلم (2577)۔"}],[840,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’اس ذات کی قسم جس کے ہاتھ میں میری جان ہے!اگر تم گناہ(کرکے توبہ)نہ کرو تو اللہ تعالیٰ تمہیں ختم کرکے ایسے لوگوں کو لے آئے گاجو گناہ کرکے اللہ تعالیٰ سے بخشش مانگے گااور اللہ انہیں بخش دے گا۔‘‘","صحیح",{"k":"صحیح مسلم (2749)، مسند أحمد (2؍309)۔"}],[841,"سعیدبن مسیّب اللہ تعالیٰ کے اس فرمان: ﴿إِنَّهُ كَانَ لِلْأَوَّابِينَ غَفُورًا﴾ [التحريم: ۲۵] (یقیناًوہ رجوع کرنے والوں کو بخشنے والا ہے) کی تفسیر میں فرماتے ہیں کہ:\n’’اس سے مراد وہ شخص ہے جو گناہ کرتاہے اور توبہ کر لیتا ہے، پھر گناہ کرتاہے تو توبہ کر لیتا ہے، پھر گناہ کا مرتکب ہوتاہے تو پھر توبہ کر لیتا ہے۔‘‘","",{}],[842,"اللہ تعالٰی کی رحمت کی وسعت سے متعلق اور اس کے عذاب کی شدت کے بابت بہت سے آثار وارد ہوئے ہیں، حتیٰ کہ نبی صلی اللہ علیہ وسلم کا فرمان ہے:\n’’اللہ تعالٰی کے ہاں جو عذاب ہے اس کا اگر مومن کو پتہ چل جائے تو وہ اس کی جنّت کی خواہش ہی نہیں کر سکے گااور اللہ تعالٰی کے ہاں جو رحمت ہے اس کا اگر کسی کافر کو پتہ چل جائے تو اس کی جنّت سے کوئی ناامید نہیں ہو سکے گا۔‘‘","صحیح",{"k":"صحیح مسلم (2755)، سنن ترمذی (3542)۔","f":"امام بیہقیؒ فرماتے ہیں کہ گنہگار شخص کو چاہیے کہ وہ توبہ کرنے میں جلدی کرے اور قرآن وحدیث میں بیان شدہ اللہ تعالٰی کی رحمت اور شافعین کی شفاعت پہ بھروسہ نہ کیے بیٹھا رہے، کیونکہ اگر وہ توبہ سے محروم ہو گیا تو اسے کوئی چیز فائدہ نہیں دے سکے گی۔ اور اسے اللہ تعالٰی کی رحمت اور سفارش کرنے والوں کی شفاعت سے بھی ناامید نہیں ہو جانا چاہیے کیونکہ ایسا کرنا بھی کبیرہ گناہ ہے۔ لہٰذا اسے اللہ تعالٰی کی رحمت کی امید اور اس کے عذاب کا خوف دونوں رکھنے چاہییں۔"}],[843,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’ایک آدمی نے اپنی جان پر بہت زیادتیاں کیں(یعنی بہت گناہ کیے)، پھرجب اس کی موت کا وقت آیا تو اس نے اپنے بیٹوں کو وصیت کی کہ جب میں مرجاؤں تو تم مجھے جلا دینا، پھر پھر میری راکھ بنا کر ہوا میں اُڑادینا اور سمندر میں بہا دینا، قسم بخدا!اگر میرے رب نے مجھ سے حساب لے لیا تو وہ مجھے ضرور ایسا عذاب دے گاجو اس نے کسی کونہ دیا ہوگا۔ چنانچہ اس کے بیٹوں نے ایسے ہی کیا، تو اللہ تعالٰی نے زمین کو حکم فرمایاکہ جو بھی تُونے اس (کے جسم)سے پکڑا ہے اسے میرے پاس لے آ، سو(زمین نے سب جمع کر دیا اور)وہ (اپنی اصل صورت میں اللہ کے سامنے)کھڑ ہو گیا، تو اللہ تعالٰی نے اس سے پوچھا:تجھے ایسا کرنے پرکس بات نے برانگیختہ کیا؟ اس نے جواب دیا:اے میرے رب!تیرے ڈرنے، چنانچہ اللہ تعالٰی نے اسے بخش دیا۔‘‘","صحیح",{"k":"صحیح بخاری (3481)، صحیح مسلم (2756)۔"}],[844,"انس بن مالک رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’تین چیزیں ایسی ہیں کہ وہ جس شخص میں بھی پائی جائیں گی وہ ایمان کی مٹھاس پالے گا:(پہلی)یہ کہ اسے اللہ ورسول کے ساتھ ان کے علاوہ تمام لوگوں اور تمام چیزوں سے بڑھ کر محبت ہو، (دوسری)یہ کہ وہ کسی آدمی سے صرف اللہ کی خاطر محبت کرتا ہو اور(تیسری)یہ ہے کہ اسے کافر ہو جانا اسی طرح ناپسند ہوجس طرح کہ اسے یہ ناپسند ہو کہ اس کے لیے آگ جلائی جائے اور اسے اس میں ڈال دیا جائے۔‘‘","صحیح",{"k":"صحیح بخاری (21)، صحیح مسلم (43)۔","f":"اللہ تعالیٰ فرماتا ہے: ﴿وَمِنَ النَّاسِ مَنْ يَتَّخِذُ مِنْ دُونِ اللّٰهِ أَنْدَادًا يُحِبُّونَهُمْ كَحُبِّ اللّٰهِ وَالَّذِينَ آمَنُوا أَشَدُّ حُبًّا لِلَّهِ﴾ [البقرة: ۱۶۵] ’’بعض لوگ ایسے بھی ہیں کہ جو اوروں کو اللہ کے شریک ٹھہرا کر ان سے ایسی محبت رکھتے ہیں جیسی محبت اللہ سے ہونی چاہیے، جبکہ ایمان والے اللہ کی محبت میں بہت سخت ہوتے ہیں۔‘‘\nاور اسی طرح فرمایا: ﴿قُلْ إِنْ كُنْتُمْ تُحِبُّونَ اللّٰهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللّٰهُ﴾ [آل عمران: ۳۱] ’’کہہ دیجیے!اگر تم اللہ تعالیٰ سے محبت رکھتے ہو تو میری پیروی کرو، (اس کے بدلے میں)وہ بھی تم سے محبت کرنے لگے گا۔‘‘"}],[845,"انس رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’ایک شخص نے پوچھا:اے اللہ کے رسول!قیامت کب آئے گی؟ آپ صلی اللہ علیہ وسلم نے فرمایا: تُونے اس کے لیے کیا تیاری کر رکھی ہے؟ تو اس شخص نے کوئی بہت زیادہ اعمال بیان نہیں کیے، سوائے اس کے کہ وہ اللہ اور اس کے رسول سے محبت رکھتا ہے۔ تو آپ صلی اللہ علیہ وسلم نے فرمایا:تُواسی کے ساتھ ہو گاجس سے تُومحبت رکھتا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (3688)، صحیح مسلم (2639)۔"}],[846,"عثمان بن عفان رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n’’تم میں سے بہتر وہ شخص ہے جو(خود بھی)قرآن کا علم حاصل کرے اور(دوسروں کو بھی)اس کی تعلیم دے۔‘‘","صحیح",{"k":"صحیح بخاری (5027)۔"}],[847,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جس نے کسی مومن سے دنیا کی پریشانیوں میں سے کوئی پریشانی دُورکی اللہ تعالیٰ اس سے قیامت کے دِن کی پریشانیوں میں سے ایک پریشانی زائل کردے گا، جس نے کسی تنگدست کے لیے آسانی پیدا کی اللہ تعالیٰ اس کے لیے دنیا وآخرت میں آسانیاں پیدا کر دے گا، جس نے کسی مسلمان(کے عیوب)کی پردہ پوشی کی اللہ تعالیٰ دنیا وآخرت میں اس (کے عیوب)پر پردہ ڈالے گا، اللہ تعالیٰ تب تک بندے کی مدد میں رہتا ہے جب تک بندہ اپنے(مسلمان)بھائی کی مدد میں رہتا ہے، جو شخص حصولِ علم کی نیّت سے گھر سے نکلا اللہ تعالیٰ اس کی وجہ سے جنّت کا راستہ اس کے لیے آسان کردے گا، جو لوگ اللہ تعالیٰ کی مساجد میں سے کسی بھی مسجد میں فقط کتاب اللہ کی تلاوت اور اسے مل کر پڑھنے اور سمجھنے کے لیے بیٹھتے ہیں تو ان پر سکینت نازل ہوتی ہے، فرشتے انہیں گھیر لیتے ہیں، رحمت ان پہ سایہ فگن ہوجاتی ہے اور اللہ تعالیٰ ان لوگوں کا ذکر اپنے پاس موجود افراد کے پاس کرتاہے اور جسے اس کے عمل نے اسے پیچھے چھوڑ دیا اسے اس کا نسب آگے نہیں بڑھا سکتا۔‘‘","صحیح",{"k":"صحیح بخاری (2442)، صحیح مسلم (2580)۔"}],[848,"عبدالرحمان بن یزید بیان کرتے ہیں کہ عبداللہ بن مسعود رضی اللہ عنہ نے فرمایا:\n’’جو شخص یہ پسند کرتا ہو کہ اسے یہ پتہ چل جائے کہ وہ اللہ اور اس کے رسول سے محبت کرتاہے(یانہیں؟)تو اسے یہ دیکھ لینا چاہیے کہ اگر تو وہ قرآن سے محبت کرتاہے تو اللہ اور اس کے رسول سے بھی محبت کرتاہے۔‘‘","صحیح موقوف",{"k":"شعب الإیمان للبیهقی (2017)۔","f":"قرآن سے محبت فقط زبانی کلامی نہ ہو بلکہ عملی طور پر محبت کا مظاہرہ کرے، یعنی قرآن کی تلاوت کیا کرے اور اس کی تعلیمات وفرامین کو حرزِجان بنا لے۔"}],[849,"عبداللہ بن بُسر رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’رسول اللہ صلی اللہ علیہ وسلم کے پاس دو بدوی شخص آکر سوال کرنے لگے، ان میں سے ایک نے کہا:لوگوں میں سے کون شخص بہتر ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:جس کی عمر لمبی ہو اور عمل نیک ہوں، دوسرے نے کہا:اے اللہ کے رسول!مجھ پر اسلام کے احکام بہت زیادہ ہوگئے ہیں(میں ان سب پر عمل نہیں کرسکتا)لہٰذا مجھے ایک ہی ایسا حکم بتلا دیجیے جس پر میں اچھی طرح عمل پیرا رہوں، آپ صلی اللہ علیہ وسلم نے فرمایا:تیری زبان ہمیشہ اللہ تعالیٰ کے ذِکر سے تَررہے۔‘‘","صحیح",{"k":"سنن ترمذی (3375)، سنن ابن ماجه (3793)، صحیح الجامع للألبانی (7700)۔"}],[850,"جابربن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’نبی صلی اللہ علیہ وسلم کے پاس فرشتے حاضر ہوئے اور آپ صلی اللہ علیہ وسلم سور ہے تھے، ان میں سے بعض نے دوسروں سے کہا:یہ تو سور ہے ہیں، تو دوسروں نے کہا:یقیناً(ان کی)آنکھ سور ہی ہے لیکن دِل جاگ رہا ہے۔ پھر انہوں نے کہا:ان کی مثال اس شخص کی طرح ہے جس نے ایک گھر بنایا اور اس میں دعوت کا اہتمام کیا اور اس نے ایک دعوت دینے والے کو بھیجا، سوجس نے تو دعوت دینے والے کی دعوت قبول کرلی، وہ اس گھر میں آگیا اور اس نے دعوت کا کھانا کھایا اورجس نے دعوت قبول نہیں کی وہ نہ تو اس گھر میں آیا اور نہ ہی دعوت کا کھانا کھا سکا۔ پھر انہوں نے کہاکہ اس بات کی تفسیر بیان کر دو تاکہ یہ سمجھ جائیں، بعض نے کہا تھا کہ یہ سوئے ہوئے ہیں جبکہ کچھ نے کہا تھا کہ آنکھ سوئی ہوئی ہے مگردِل جاگ رہا ہے، (پھر اس بات کی وضاحت کرتے ہوئے)انہوں نے کہاکہ وہ گھرجنّت ہے اور دعوت دینے والے محمد( صلی اللہ علیہ وسلم )ہیں، چنانچہ جس نے محمد( صلی اللہ علیہ وسلم )کی اطاعت کی اس نے (درحقیقت)اللہ تعالٰی کی اطاعت کی اورجس نے ان محمد( صلی اللہ علیہ وسلم )کی نافرمانی کی اس نے اللہ تعالٰی کی نافرمانی کی، اور محمد( صلی اللہ علیہ وسلم )لوگوں میں فرق (کرنے والے)ہیں۔‘‘","صحیح",{"k":"صحیح بخاری (7281)۔","f":"اس حدیث میں واضح طور پر بیان ہے کہ نبی صلی اللہ علیہ وسلم کی اطاعت کرنے والا ہی جنّت میں جائے گا، کیونکہ آپ صلی اللہ علیہ وسلم کی اطاعت درحقیقت اللہ تعالٰی کی اطاعت ہے۔ سوجو شخص آپ صلی اللہ علیہ وسلم کی اطاعت کے بجائے کسی اور کو مطاع سمجھے گاوہ جنّت کا قطعی حقدار نہیں ہوگا، اس لیے جمیع امور میں رسول مکرم صلی اللہ علیہ وسلم کی ہی ذات کو اسوہ بناتے ہوئے آپ صلی اللہ علیہ وسلم ہی کی پیروی کرنی چاہیے۔"}],[851,"عقبہ بن عامر رضی اللہ عنہ بیان کرتے ہیں کہ:\n’’(ایک روز)ہم صفہ میں (بیٹھے ہوئے)تھے کہ رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے اور فرمایا:تم میں سے کون شخص یہ پسند کرتا ہے کہ وہ ہرروز صبح کو بطحان یاعقیق(وادی)میں جائے اور وہاں سے کسی ظلم وزیادتی اور ناتہ توڑے بغیر موٹی تازی اونچی کوہانوں والی دو اونٹنیاں لے آئے؟ تو ہم نے عرض کیا:اے اللہ کے رسول!یہ تو ہم میں سے ہرکوئی پسند کرے گا، تو آپ صلی اللہ علیہ وسلم نے فرمایا:تم میں سے کوئی شخص روزانہ صبح مسجد میں جائے اور قرآن کریم کی دو آیات سیکھ لے تو اس کے لیے یہ دو اونٹنیوں سے بہتر ہے، تیں آیات سیکھنا تین اونٹنیوں سے بہتر ہے اور چار سیکھنا چار اونٹنیوں سے بہتر، اور آیات کی تعداد کے مطابق (اس کا یہ عمل)اتنی ہی اونٹنیوں سے بہتر ہوگا۔‘‘","صحیح",{"k":"صحیح مسلم (803)، سنن أبوداؤد (1456)۔","f":"یعنی وہ جتنی زیادہ آیات سیکھے گا اتنی ہی اونٹنیوں سے بہتر عمل کا اجروثواب پائے گا۔"}],[852,"ابوامامہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’جو صبح کو مسجد میں صرف اس ارادے سے جائے کہ وہ خیروبھلائی سیکھے یاسکھائے تو اس کے لیے ایک کامل عمرے کا ثواب ہے اور جو شام کو کو مسجد میں صرف اس ارادے سے جائے کہ وہ خیروبھلائی سیکھے یاسکھائے تو اس کے لیے ایک کامل حج کا ثواب ہے۔‘‘","صحیح",{"k":"مستدرک حاکم (1؍91)، المعجم الکبیر للطبرانی (8؍112)، حلیہ الأولیاء لأبی نعیم (6؍97)۔"}],[853,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’جو میری اس مسجد میں فقط خیروبھلائی سیکھنے سکھانے کے لیے آتا ہے تو وہ راہِ خدا میں جہاد کرنے والے کا مقام رکھتا ہے اور جو اس کے علاوہ کسی اور مقصد کے لیے آتا ہے تو وہ اس شخص کے بہ منزلہ ہوتاہے جو کسی اور کے سامان کی طرف دیکھتا ہے۔‘‘","صحیح",{"k":"سنن ابن ماجه (227)، صحیح الجامع للألبانی (6184)۔"}],[854,"کثیربن قیس بیان کرتے ہیں کہ:\n’’میں سیدنا ابودرداء رضی اللہ عنہ کی خدمت میں حاضر ہوا اور آپ مسجدِدمشق میں جلوہ افروز تھے، میں نے عرض کیا:اے ابودرداء!میں آپ کے پاس مدینۃ الرسول سے ایک حدیث لینے کے لیے حاضر ہوا ہوں مجھے پتہ چلا ہے کہ آپ وہ حدیث رسول اللہ صلی اللہ علیہ وسلم سے بیان کرتے ہیں۔ تو انہوں نے دریافت فرمایا:تم کسی ضرورت یاتجارت کی غرض سے نہیں بلکہ صرف حدیث کی خاطر آئے ہو؟ میں نے جواب دیا:جی ہاں، انہوں نے کہاکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:جو شخص حصولِ علم کے لیے رختِ سفر باندھے اللہ تعالیٰ اسے جنّت کی راہ پر گامزن فرما دیتا ہے، یقیناًطالبِ علم کے اس عمل کی وجہ سے اس کے لیے فرشتے اپنے پَربچھاتے ہیں، صاحبِ علم کی فضیلت عبادت گزار پر ایسے ہی ہے جیسے چودھویں رات میں چاند کی فضیلت ستاروں پر ہے، زمین وآسمان میں موجود تمام مخلوقات یہاں تک کہ پانی کی تہہ میں موجود مچھلی بھی عالم کی بخشش کے لیے دعا کرتی ہے، بلاشبہ اہلِ علم انبیاء کے وارث ہیں اور یقیناًانبیاء اپنی وراثت میں درہم ودینار چھوڑ کر نہیں جاتے بلکہ علم کوبہ طورِوراثت چھوڑتے ہیں، سوجس نے اسے حاصل کر لیا اس نے (خیروبھلائی کا)بہت بڑا حصہ حاصل کرلیا۔‘‘","صحیح",{"k":"سنن أبوداؤد (3641)، سنن ترمذی (2682)، سنن ابن ماجه (223)، صحیح الجامع للألبانی (6297)۔"}],[855,"زیدبن ثابت رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\n’’اللہ تعالیٰ اس آدمی کو شاداب وفرحاں رکھے جس نے ہم سے کوئی حدیث سنی، پھر اسے یاد رکھا یہاں تک کہ اسے آگے پہنچا دیا(یعنی کسی اور کو پڑھا دی)اور بہت سے فقہ (یعنی علمِ قرآن وسنّت)کے حامل لوگ کسی ایسے شخص تک(وہ بات پہنچا دیتے)جوان سے زیادہ فقیہ ہوتاہے، اور بہت سے دِین کی سُوجھ بُوجھ رکھنے والے ایسے بھی ہوتے ہیں جو(درحقیقت)فقیہ نہیں ہوتے، تین امور ایسے ہیں کہ جن کے بارے میں مومن کے دِل سے خیانت نہیں کی جاتی:(ایک)اللہ (کی رضا)کے لیے عمل، )دوسرا( امور ومعاملات کے نگرانوں کی خیرخواہی اور )تیسرا( مسلمانوں کی جماعت کو مضبوطی سے تھامے رکھنا۔ جس شخص کا مقصد آخرت(کا حصول)ہو اللہ تعالیٰ اس کے کاموں کو جمع فرما دیتا ہے، کفایت اس کے دِل میں ڈال دیتا ہے اور دنیا اس کے پاس رُسوا ہو کر آتی ہے اورجس کا مقصد دنیا(کا حصول)ہو اللہ تعالیٰ اس کے کاموں کو منتشر کر دیتا ہے، اس کے فقر کو اس کی آنکھوں کے سامنے کر دیتا ہے اور دنیا بھی اسے صرف اسی قدر ملتی ہے جتنی اس کے نصیب میں لکھی ہوتی ہے۔‘‘","صحیح",{"k":"سنن ابن ماجه (230)، سلسلہ الأحادیث الصحیحہ (403)۔"}],[856,"عبداللہ بن عمرو رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’مجھ سے(سُنی ہربات)آگے پہنچا دو، اگرچہ وہ ایک ہی آیت ہو۔ بنی اسرائیل سے بیان کر لیا کرو کوئی حرج نہیں ہے، اورجس نے مجھ پر جان بُوجھ کرجھُوٹ باندھا اسے اپنا ٹھکانہ جہنّم میں بنا لینا چاہیے۔‘‘","صحیح",{"k":"صحیح بخاری (3461)، سنن ترمذی (2669)۔","f":"لہٰذا نبی صلی اللہ علیہ وسلم کی طرف منسوب بات کو آگے بیان کرنے یا اس پر عمل کرنے سے پہلے یہ تحقیق کر لینی چاہیے کہ آیا واقعی یہ رسول اللہ صلی اللہ علیہ وسلم کا فرمان ہے؟ اس لیے کئی احادیث بے سند اور من گھڑت ہوتی ہیں، خاص طور پر جو عوام الناس کے ہاں معروف ہوتی ہیں۔ آج کل موبائل پیغامات کے ذریعے کسی خاص مکتب فکر کے حامل لوگ اپنے خاص عقائد ونظریات حدیث کے نام سے پھیلا رہے ہیں، حالانکہ ان باتوں کا حدیث کی کسی بھی کتاب میں ذکرتک نہیں ہے۔ ایسے پیغامات کی ترسیل میں نہایت احتیاط برتنی چاہیے اور جب تک اس کے حدیثِ رسول کا پختہ علم اور یقین نہ ہو جائے تب تک اسے پھیلانے میں شریک نہیں ہونا چاہیے۔ تا کہ کہیں لا شعوری میں اس حدیث کے مصداق نہ بن جائیں۔"}],[857,"ابنِ عباس رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اللہ تعالٰی سے روایت کرتے ہوئے فرمایا:\n’’یقیناًتمہارارب بہت رحم والا ہے، جس شخص نے نیکی کا ارادہ کیا لیکن نیکی نہیں کی تو اس کی)ارادے کی(ایک نیکی لکھ دی جاتی ہے، اور اگر وہ نیکی کرلے تو اسے دس گُناسے سات سوگُناتک بڑھا چڑھا کر لکھا جاتا ہے، اورجس نے برائی کا ارادہ کیا لیکن برائی نہیں کی تو)گناہ نہ کرنے کی(ایک نیکی لکھ دی جاتی ہے، اور اگر وہ برائی کرلے تو اس کا صرف ایک ہی گناہ لکھا جاتا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (6491)، صحیح مسلم (131)۔","f":"اللہ تعالیٰ فرماتا ہے: ﴿إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ إِنَّا لَا نُضِيعُ أَجْرَ مَنْ أَحْسَنَ عَمَلًا﴾ [الكهف: ۳۰] ’’یقیناًجو لوگ ایمان لائے اور نیک عمل کیے، بِلاشک جس نے بھی اچھے عمل کیے ہم اس کا اجر ضائع نہیں کریں گے۔‘‘ اسی طرح فرمایا: ﴿وَمَنْ أَرَادَ الْآخِرَةَ وَسَعٰى لَهَا سَعْيَهَا وَهُوَ مُؤْمِنٌ فَأُولٰئِكَ كَانَ سَعْيُهُمْ مَشْكُورًا﴾ [الإسراء: ۱۹] ’’جو شخص اُخروی زندگی چاہتا ہے اور وہ ایمان ویقین کی حالت میں اس کے لیے کوشش بھی کرتاہے، تو یہی وہ لوگ ہیں جن کی کوشش کی قدر کی جاتی ہے۔‘‘"}],[858,"اور رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’میانہ روی اختیار کرو اور راہِ راست پر رہو، کیونکہ تم میں سے کوئی بھی اپنے عمل کے باعث بالکل نجات نہیں پاسکے گا، صحابہؓ نے عرض کیا:اے اللہ کے رسول!آپ صلی اللہ علیہ وسلم بھی نہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا:میں بھی نہیں، ہاں یہ ہے کہ اللہ تعالیٰ کا فضل ورحمت مجھے ڈھانپ لے۔‘‘","صحیح",{"k":"صحیح بخاری (5673)، صحیح مسلم (2817)۔","f":"امام بیہقیؒ فرماتے ہیں کہ اللہ تعالیٰ کی اطاعت وفرمانبرداری کا عمل بھی فقط اللہ رب العزت کی توفیق سے ہی ممکن ہے اور ایسے ہی معصیت سے بچاؤ بھی اللہ تعالیٰ کے محفوظ رکھ لینے پر ہی منحصر ہے، نیکی کی توفیق اور گناہوں سے بچاؤ اللہ کے ارادے، اس کی توفیق اور اسی کی حفاظت کی بنیاد پر ہے اور یہ خاص اسی کی رحمت ہوتی ہے، چنانچہ نجات درحقیقت تب ہی وقوع پذیر ہوگی جب خدا تعالیٰ کی رحمت اور اس کا فضل شاملِ حال ہوگا۔ لہٰذا انسان کو اللہ تعالیٰ کے احکام کا لحاظ رکھتے ہوئے عمل کا اہتمام ضرور کرنا چاہیے اور ایسا کرنا ان لوگوں کی علامت بن جائے جو اخروی زندگی کو کامیاب بنانے کے لیے عمل کرتے ہیں۔ پھر ہرشخص وہی عمل کرتاہے جو اللہ تعالیٰ اس کے لیے میسر فرما دیتا ہے، اسی تقدیر کے موافق جو ازل سے نوشتۂ تقدیر میں لکھی جا چکی ہے اور اس کا ہرعمل اللہ کے علم میں ہوتاہے۔"}],[859,"اسی طرح آپ صلی اللہ علیہ وسلم کا ارشادِگرامی ہے:\n’’نیک عمل کیا کرو، کیونکہ ہرشخص کو ان اعمال کی توفیق دی جاتی ہے جن کے لیے وہ پیدا کیا گیا ہے۔‘‘","صحیح",{"k":"صحیح بخاری (4949)، صحیح مسلم (2647)۔","f":"امام بیہقیؒ فرماتے ہیں کہ جس شخص کو اللہ تعالٰی نیک اعمال کی توفیق سے نوازے اور اپنی بندگی بجا لانے میں اس کا معاون بن جائے تو یہ ان لوگوں میں سے ہیں جو ایمان لائے اور نیک اعمال کیے، اور اللہ تعالٰی کی بات بھی حق ہے اور اس کا وعدہ بھی سچا ہے، اللہ تعالٰی کا فرمان ہے: ﴿إِنَّا لَا نُضِيعُ أَجْرَ مَنْ أَحْسَنَ عَمَلًا﴾ [الكهف: ۳۰] ’’یقیناًہم نیک عمل کرنے والے کے اجروثواب کو ضائع نہیں کریں گے۔‘‘ ہم اللہ تعالٰی سے اس کی بندگی بجا لانے پر مدد مانگتے ہیں اور اس کی حسنِ توفیق میں اسی کی طرف رغبت رکھتے ہیں، کیونکہ اس کے فضل اور اس کی رحمت کے بغیر اس کی معرفت واطاعت ممکن نہیں ہے، جیسا کہ اللہ تعالٰی فرماتے ہیں: ﴿وَلَوْلَا فَضْلُ اللّٰهِ عَلَيْكُمْ وَرَحْمَتُهُ مَا زَكَا مِنْكُمْ مِنْ أَحَدٍ أَبَدًا وَلَكِنَّ اللّٰهَ يُزَكِّي مَنْ يَشَاءُ﴾ [النور: ۲۱] ’’اور اگر تم پر اللہ تعالٰی کا فضل وکرم اور اس کی رحمت نہ ہوتی تو تم میں سے کوئی بھی کبھی پاک صاف نہ ہوتا، لیکن اللہ تعالٰی جسے پاک کرنا چاہے کر دیتا ہے۔‘‘ ہم اللہ تعالٰی سے جنّت کا سوال کرتے ہیں اور جہنّم سے پناہ مانگتے ہیں، کیونکہ اس کے فضل وکرم اور اس کی بے پایاں رحمت کے بغیر نہ تو کامیابی کے کسی راستے کا حصول ممکن ہے اور نہ ہی اس کے عذاب سے ہی نجات پائی جاسکتی ہے۔ «وَاللّٰهُ الْمُوَفِّقُ وَالْمُعِيْنُ»"}]]);
